{
  "name": "Bangla Food Club (BFC) - Ultimate Platform",
  "description": "A high-performance, PWA-ready Bangladeshi food delivery and restaurant management platform featuring real-time tracking, multi-role admin panels, loyalty systems, and an AI-powered BFC Assist bot.",
  "requestFramePermissions": [
    "microphone",
    "geolocation",
    "camera"
  ]
}

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  rating: number;
  ingredients: string[];
  dietary: string[]; // ['Spicy', 'Mild', 'Veg', 'Non-Veg']
  stock: number;
  prepTime: string;
  isPopular?: boolean;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  items: Array<{
    menuId: string;
    quantity: number;
    price: number;
    name: string;
  }>;
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentStatus: 'PAID' | 'UNPAID';
  paymentMethod: 'BKASH' | 'STRIPE' | 'COD';
  address: string;
  pointsEarned: number;
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  phone: string;
  loyaltyPoints: number;
  tier: 'SILVER' | 'GOLD' | 'PLATINUM';
  wishlist: string[];
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist", the friendly AI bot for "Bangla Food Club" (BFC). 
        You help customers with menu queries, order status (mocked), and general food recommendations in both English and Bengali.
        Keep your responses warm, professional, and culinary-focused. If a user asks about local spicy foods, recommend BFC's Beef Rezala or Kacchi Biryani.
        Always refer to yourself as BFC Assist.`,
        temperature: 0.7,
        topP: 0.95,
      },
    });

    return response.text || "I'm sorry, I couldn't process that. Please try again.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "BFC Assist is currently taking a break. Please contact support at 16123.";
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'outline';
  size?: 'sm' | 'md' | 'lg';
  fullWidth?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  fullWidth, 
  className, 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center font-semibold rounded-lg transition-all active:scale-95 disabled:opacity-50";

  const variants = {
    primary: "bg-red-600 text-white hover:bg-red-700 shadow-md",
    secondary: "bg-orange-500 text-white hover:bg-orange-600 shadow-md",
    danger: "bg-red-100 text-red-700 hover:bg-red-200",
    outline: "border-2 border-red-600 text-red-600 hover:bg-red-50"
  };

  const sizes = {
    sm: "px-3 py-1.5 text-sm",
    md: "px-5 py-2.5",
    lg: "px-8 py-3.5 text-lg"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${fullWidth ? 'w-full' : ''} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

export const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Hello! I am BFC Assist. How can I help you enjoy the best of Bangla today?', timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: ChatMessage = { role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({
      role: m.role,
      parts: [{ text: m.text }]
    }));

    const botResponse = await bfcAssistChat(input, history);

    setMessages(prev => [...prev, { 
      role: 'model', 
      text: botResponse, 
      timestamp: new Date() 
    }]);
    setIsTyping(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-50">
      {isOpen ? (
        <div className="bg-white w-80 md:w-96 h-[500px] rounded-2xl shadow-2xl flex flex-col border border-gray-100 overflow-hidden animate-slide-up">
          <div className="bg-red-600 p-4 text-white flex justify-between items-center">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-white rounded-full flex items-center justify-center text-red-600 font-bold">
                B
              </div>
              <div>
                <h3 className="font-bold">BFC Assist</h3>
                <p className="text-xs opacity-80">Online | Powered by Gemini 3</p>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="hover:bg-red-700 p-1 rounded">
              <i className="fas fa-times"></i>
            </button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-3 rounded-2xl text-sm ${
                  m.role === 'user' 
                  ? 'bg-red-600 text-white rounded-tr-none' 
                  : 'bg-white text-gray-800 shadow-sm rounded-tl-none'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white p-3 rounded-2xl text-sm shadow-sm flex gap-1">
                  <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce"></div>
                  <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                  <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>

          <div className="p-4 bg-white border-t border-gray-100 flex gap-2">
            <input 
              type="text" 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Ask anything..."
              className="flex-1 bg-gray-100 rounded-full px-4 py-2 outline-none focus:ring-2 focus:ring-red-600 text-sm"
            />
            <button 
              onClick={handleSend}
              className="bg-red-600 text-white w-10 h-10 rounded-full flex items-center justify-center hover:bg-red-700 transition-colors"
            >
              <i className="fas fa-paper-plane"></i>
            </button>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-red-600 text-white w-14 h-14 rounded-full shadow-2xl flex items-center justify-center hover:scale-110 transition-transform"
        >
          <i className="fas fa-robot text-2xl"></i>
          <span className="absolute -top-1 -right-1 bg-green-500 w-4 h-4 rounded-full border-2 border-white"></span>
        </button>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<Array<{ item: MenuItem, qty: number }>>([]);
  const [language, setLanguage] = useState<'EN' | 'BN'>('EN');
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN'>('HOME');

  const categories = useMemo(() => ['All', ...new Set(MOCK_MENU.map(m => m.category))], []);

  const filteredMenu = useMemo(() => {
    return MOCK_MENU.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [searchQuery, activeCategory]);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(c => c.item.id === item.id);
      if (existing) {
        return prev.map(c => c.item.id === item.id ? { ...c, qty: c.qty + 1 } : c);
      }
      return [...prev, { item, qty: 1 }];
    });
  };

  const removeFromCart = (itemId: string) => {
    setCart(prev => prev.filter(c => c.item.id !== itemId));
  };

  const totalCartPrice = cart.reduce((acc, curr) => acc + (curr.item.price * curr.qty), 0);

  const loginAs = (role: UserRole) => {
    const mockUser: User = {
      id: 'U-001',
      name: 'Admin User',
      email: 'admin@bfc.com',
      role: role,
      phone: '01712345678',
      loyaltyPoints: 1250,
      tier: 'GOLD',
      wishlist: []
    };
    setCurrentUser(mockUser);
    setView(role === UserRole.CUSTOMER ? 'HOME' : 'ADMIN');
  };

  if (view === 'ADMIN' && currentUser) {
    return (
      <>
        <AdminPanel userRole={currentUser.role} />
        <ChatBot />
      </>
    );
  }

  return (
    <div className="min-h-screen pb-20 md:pb-0">
      {/* Navigation */}
      <nav className="sticky top-0 bg-white/80 backdrop-blur-md z-40 border-b border-gray-100">
        <div className="max-w-7xl mx-auto px-4 py-4 flex justify-between items-center">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setView('HOME')}>
            <div className="bg-red-600 text-white w-10 h-10 rounded-xl flex items-center justify-center text-xl font-black">B</div>
            <div>
              <h1 className="text-xl font-black tracking-tight leading-none text-red-600">BFC</h1>
              <p className="text-[10px] text-gray-500 font-bold tracking-[3px] uppercase">Bangla Food Club</p>
            </div>
          </div>

          <div className="hidden md:flex items-center gap-8 font-semibold text-gray-600">
            <button onClick={() => setView('HOME')} className={view === 'HOME' ? 'text-red-600' : ''}>Home</button>
            <button onClick={() => setView('MENU')} className={view === 'MENU' ? 'text-red-600' : ''}>Menu</button>
            <button onClick={() => setView('CART')} className="relative">
              Cart {cart.length > 0 && <span className="absolute -top-3 -right-3 bg-red-600 text-white text-[10px] w-5 h-5 rounded-full flex items-center justify-center">{cart.length}</span>}
            </button>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setLanguage(l => l === 'EN' ? 'BN' : 'EN')}
              className="bg-gray-100 px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-gray-200"
            >
              {language}
            </button>
            {currentUser ? (
              <div className="flex items-center gap-2 bg-red-50 px-3 py-1.5 rounded-full">
                <div className="w-6 h-6 bg-red-600 rounded-full flex items-center justify-center text-[10px] text-white">
                  {currentUser.name.charAt(0)}
                </div>
                <span className="text-sm font-bold text-red-700">{currentUser.loyaltyPoints} pts</span>
              </div>
            ) : (
              <Button size="sm" onClick={() => setView('LOGIN')}>Login</Button>
            )}
          </div>
        </div>
      </nav>

      {/* Main Sections */}
      {view === 'HOME' && (
        <main className="animate-fade-in">
          {/* Hero */}
          <section className="relative h-[500px] overflow-hidden bg-gray-900">
            <img src="https://images.unsplash.com/photo-1512152272829-e3139592d56f?auto=format&fit=crop&q=80&w=2070" className="w-full h-full object-cover opacity-50" />
            <div className="absolute inset-0 flex flex-col justify-center items-center text-center px-4">
              <h2 className="text-5xl md:text-7xl font-black text-white mb-6">Authentic <span className="text-red-500">Bangla</span> Bliss</h2>
              <p className="text-gray-200 text-lg md:text-xl max-w-2xl mb-8">Experience the heritage of Bangladeshi cuisine delivered hot to your doorstep. From Kacchi to Rezala, we have it all.</p>
              <div className="flex gap-4">
                <Button size="lg" onClick={() => setView('MENU')}>Order Now</Button>
                <Button size="lg" variant="outline" className="bg-white/10 text-white border-white/20">Explore Menu</Button>
              </div>
            </div>
          </section>

          {/* Featured Categories */}
          <section className="max-w-7xl mx-auto px-4 py-16">
            <h3 className="text-3xl font-bold mb-8">Shop by Category</h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
              {['Biryani', 'Curry', 'Kebab', 'Desserts'].map(cat => (
                <div 
                  key={cat}
                  onClick={() => { setActiveCategory(cat); setView('MENU'); }}
                  className="group relative h-48 rounded-3xl overflow-hidden cursor-pointer shadow-lg"
                >
                  <img src={`https://picsum.photos/seed/${cat}/400/300`} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                  <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
                    <span className="text-white text-2xl font-black">{cat}</span>
                  </div>
                </div>
              ))}
            </div>
          </section>
        </main>
      )}

      {view === 'MENU' && (
        <div className="max-w-7xl mx-auto px-4 py-12 animate-fade-in">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
            <div>
              <h2 className="text-4xl font-black mb-2">Our Culinary Gallery</h2>
              <p className="text-gray-500">Curated dishes from the heart of Dhaka</p>
            </div>
            <div className="flex bg-gray-100 p-1 rounded-2xl">
              <input 
                type="text" 
                placeholder="Search flavors..." 
                className="bg-transparent border-none outline-none px-4 py-2 w-full md:w-64"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
              <div className="bg-red-600 text-white p-3 rounded-xl">
                <i className="fas fa-search"></i>
              </div>
            </div>
          </div>

          <div className="flex gap-4 overflow-x-auto pb-6 scrollbar-hide mb-8">
            {categories.map(cat => (
              <button 
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-6 py-2.5 rounded-full font-bold whitespace-nowrap transition-all ${
                  activeCategory === cat 
                  ? 'bg-red-600 text-white shadow-lg' 
                  : 'bg-white text-gray-600 border border-gray-100 hover:border-red-600'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
            {filteredMenu.map(item => (
              <div key={item.id} className="group bg-white rounded-[32px] overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 border border-gray-100 flex flex-col">
                <div className="relative h-56 overflow-hidden">
                  <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                  <div className="absolute top-4 right-4 flex flex-col gap-2">
                    <button className="bg-white/90 backdrop-blur-md w-10 h-10 rounded-full flex items-center justify-center text-gray-400 hover:text-red-600 shadow-sm"><i className="far fa-heart"></i></button>
                    {item.isPopular && <span className="bg-orange-500 text-white text-[10px] font-bold px-2 py-1 rounded-lg uppercase tracking-wider">Popular</span>}
                  </div>
                </div>
                <div className="p-6 flex-1 flex flex-col">
                  <div className="flex justify-between items-start mb-2">
                    <h4 className="text-xl font-bold leading-tight">{language === 'EN' ? item.name : item.nameBn}</h4>
                    <span className="text-xs font-bold text-gray-400 bg-gray-50 px-2 py-1 rounded-md">{item.prepTime}</span>
                  </div>
                  <p className="text-gray-500 text-sm mb-6 flex-1 line-clamp-2">{item.description}</p>
                  <div className="flex justify-between items-center mt-auto pt-4 border-t border-gray-50">
                    <span className="text-2xl font-black text-red-600">৳{item.price}</span>
                    <Button size="sm" onClick={() => addToCart(item)}>
                      <i className="fas fa-plus mr-2"></i> Add
                    </Button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {view === 'CART' && (
        <div className="max-w-4xl mx-auto px-4 py-12 animate-fade-in">
          <h2 className="text-4xl font-black mb-8">Your Feast</h2>
          {cart.length === 0 ? (
            <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-gray-300">
              <i className="fas fa-shopping-basket text-6xl text-gray-200 mb-6"></i>
              <h3 className="text-xl font-bold text-gray-400">Cart is empty</h3>
              <Button className="mt-6" onClick={() => setView('MENU')}>Browse Menu</Button>
            </div>
          ) : (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
              <div className="lg:col-span-2 space-y-4">
                {cart.map(item => (
                  <div key={item.item.id} className="bg-white p-4 rounded-3xl flex items-center gap-4 shadow-sm border border-gray-50">
                    <img src={item.item.image} className="w-24 h-24 rounded-2xl object-cover" />
                    <div className="flex-1">
                      <h4 className="font-bold">{item.item.name}</h4>
                      <p className="text-sm text-gray-500">৳{item.item.price} each</p>
                      <div className="flex items-center gap-4 mt-2">
                        <button className="text-red-600 font-bold px-2 hover:bg-red-50 rounded" onClick={() => removeFromCart(item.item.id)}>-</button>
                        <span className="font-black text-lg">{item.qty}</span>
                        <button className="text-red-600 font-bold px-2 hover:bg-red-50 rounded" onClick={() => addToCart(item.item.id as any)}>+</button>
                      </div>
                    </div>
                    <span className="font-black text-lg">৳{item.item.price * item.qty}</span>
                  </div>
                ))}
              </div>
              <div className="bg-white p-8 rounded-[40px] shadow-2xl h-fit sticky top-28 border border-gray-100">
                <h3 className="text-xl font-bold mb-6">Order Summary</h3>
                <div className="space-y-4 mb-8">
                  <div className="flex justify-between text-gray-500">
                    <span>Subtotal</span>
                    <span>৳{totalCartPrice}</span>
                  </div>
                  <div className="flex justify-between text-gray-500">
                    <span>Delivery Fee</span>
                    <span>৳60</span>
                  </div>
                  <div className="flex justify-between text-gray-500">
                    <span>Tax (VAT)</span>
                    <span>৳{Math.round(totalCartPrice * 0.15)}</span>
                  </div>
                  <div className="pt-4 border-t border-gray-100 flex justify-between font-black text-2xl">
                    <span>Total</span>
                    <span className="text-red-600">৳{totalCartPrice + 60 + Math.round(totalCartPrice * 0.15)}</span>
                  </div>
                </div>
                <Button fullWidth size="lg">Place Order</Button>
                <div className="mt-4 flex gap-2 justify-center">
                  <img src="https://upload.wikimedia.org/wikipedia/commons/8/8b/Bkash_logo.png" className="h-6 opacity-40 grayscale" />
                  <img src="https://upload.wikimedia.org/wikipedia/commons/b/ba/Stripe_Logo%2C_revised_2016.svg" className="h-4 opacity-40 grayscale" />
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {view === 'LOGIN' && (
        <div className="min-h-[80vh] flex items-center justify-center px-4">
          <div className="bg-white p-10 rounded-[40px] shadow-2xl w-full max-w-md border border-gray-100">
            <h2 className="text-3xl font-black mb-2 text-center">Login</h2>
            <p className="text-center text-gray-500 mb-10">Select your role to explore the platform</p>
            <div className="space-y-3">
              <Button fullWidth onClick={() => loginAs(UserRole.CUSTOMER)}>Login as Customer</Button>
              <Button fullWidth variant="secondary" onClick={() => loginAs(UserRole.ADMIN)}>Login as Admin</Button>
              <Button fullWidth variant="outline" onClick={() => loginAs(UserRole.MANAGER)}>Login as Manager</Button>
              <Button fullWidth variant="danger" onClick={() => loginAs(UserRole.STAFF)}>Login as Staff</Button>
            </div>
          </div>
        </div>
      )}

      {/* Mobile Bar */}
      <div className="md:hidden fixed bottom-0 w-full bg-white border-t border-gray-100 px-6 py-4 flex justify-between items-center z-50">
        <button onClick={() => setView('HOME')} className={`flex flex-col items-center gap-1 ${view === 'HOME' ? 'text-red-600' : 'text-gray-400'}`}>
          <i className="fas fa-home"></i>
          <span className="text-[10px] font-bold">Home</span>
        </button>
        <button onClick={() => setView('MENU')} className={`flex flex-col items-center gap-1 ${view === 'MENU' ? 'text-red-600' : 'text-gray-400'}`}>
          <i className="fas fa-utensils"></i>
          <span className="text-[10px] font-bold">Menu</span>
        </button>
        <button onClick={() => setView('CART')} className={`relative flex flex-col items-center gap-1 ${view === 'CART' ? 'text-red-600' : 'text-gray-400'}`}>
          <i className="fas fa-shopping-bag"></i>
          {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[8px] w-3 h-3 rounded-full flex items-center justify-center">{cart.length}</span>}
          <span className="text-[10px] font-bold">Cart</span>
        </button>
        <button onClick={() => setView('LOGIN')} className={`flex flex-col items-center gap-1 ${view === 'LOGIN' ? 'text-red-600' : 'text-gray-400'}`}>
          <i className="fas fa-user"></i>
          <span className="text-[10px] font-bold">Account</span>
        </button>
      </div>

      <ChatBot />
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  rating: number;
  ingredients: string[];
  dietary: string[]; // ['Spicy', 'Mild', 'Veg', 'Non-Veg']
  stock: number;
  prepTime: string;
  isPopular?: boolean;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  items: Array<{
    menuId: string;
    quantity: number;
    price: number;
    name: string;
  }>;
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentStatus: 'PAID' | 'UNPAID';
  paymentMethod: 'BKASH' | 'STRIPE' | 'COD';
  address: string;
  pointsEarned: number;
  trackingUpdates: Array<{ status: OrderStatus; time: string }>;
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  phone: string;
  loyaltyPoints: number;
  tier: 'SILVER' | 'GOLD' | 'PLATINUM';
  wishlist: string[];
  referralCode: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState } from 'react';
import { UserRole, OrderStatus } from '../types';
import { MOCK_ORDERS, MOCK_MENU } from '../constants';
import { Button } from './Button';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar, Cell } from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
}

const COLORS = ['#dc2626', '#f97316', '#22c55e', '#3b82f6', '#8b5cf6'];

const MOCK_SALES_DATA = [
  { name: 'Mon', sales: 4000 },
  { name: 'Tue', sales: 3000 },
  { name: 'Wed', sales: 2000 },
  { name: 'Thu', sales: 2780 },
  { name: 'Fri', sales: 1890 },
  { name: 'Sat', sales: 2390 },
  { name: 'Sun', sales: 3490 },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ userRole, onLogout }) => {
  const [activeTab, setActiveTab] = useState(userRole === UserRole.STAFF ? 'orders' : 'dashboard');
  const [orders, setOrders] = useState(MOCK_ORDERS);

  const isAdmin = userRole === UserRole.ADMIN;
  const isManager = userRole === UserRole.MANAGER;
  const isStaff = userRole === UserRole.STAFF;

  // RBAC permissions
  const canSeeFinance = isAdmin;
  const canManageUsers = isAdmin;
  const canDeleteItems = isAdmin;
  const canEditPrices = isAdmin || isManager;
  const canUpdateStock = isAdmin || isManager;
  const canViewReports = isAdmin || isManager;

  const updateStatus = (orderId: string, newStatus: OrderStatus) => {
    // Staff restrictions: only specific stage moves
    if (isStaff) {
      const order = orders.find(o => o.id === orderId);
      if (!order) return;
      // Mock logic: staff can only progress, not cancel or jump stages drastically
    }
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
  };

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden">
      {/* Sidebar */}
      <div className="w-64 bg-white border-r border-gray-200 flex flex-col">
        <div className="p-6 border-b border-gray-100">
          <h1 className="text-xl font-black text-red-600">BFC CONTROL</h1>
          <p className="text-[10px] text-gray-400 mt-1 uppercase tracking-widest font-bold">Role: {userRole}</p>
        </div>
        <nav className="flex-1 p-4 space-y-1">
          {canViewReports && (
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'dashboard' ? 'bg-red-600 text-white' : 'text-gray-600 hover:bg-red-50 hover:text-red-600'}`}
            >
              <i className="fas fa-chart-line"></i> Dashboard
            </button>
          )}
          <button 
            onClick={() => setActiveTab('orders')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'orders' ? 'bg-red-600 text-white' : 'text-gray-600 hover:bg-red-50 hover:text-red-600'}`}
          >
            <i className="fas fa-shopping-bag"></i> {isStaff ? "Today's Orders" : "Orders"}
          </button>
          {!isStaff && (
            <button 
              onClick={() => setActiveTab('inventory')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'inventory' ? 'bg-red-600 text-white' : 'text-gray-600 hover:bg-red-50 hover:text-red-600'}`}
            >
              <i className="fas fa-box"></i> Inventory
            </button>
          )}
          {canManageUsers && (
            <button 
              onClick={() => setActiveTab('users')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'users' ? 'bg-red-600 text-white' : 'text-gray-600 hover:bg-red-50 hover:text-red-600'}`}
            >
              <i className="fas fa-users-cog"></i> Staff Management
            </button>
          )}
        </nav>
        <div className="p-4 border-t border-gray-100">
          <Button variant="outline" fullWidth onClick={onLogout}>
            <i className="fas fa-sign-out-alt mr-2"></i> Log Out
          </Button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-8">
        {activeTab === 'dashboard' && canViewReports && (
          <div className="space-y-8 animate-fade-in">
            <header>
              <h2 className="text-2xl font-bold">Business Overview</h2>
              <p className="text-gray-500">Real-time performance metrics</p>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {canSeeFinance && <StatCard title="Total Revenue" value="৳ 1,24,500" icon="fa-wallet" color="text-green-600" />}
              <StatCard title="Total Orders" value="842" icon="fa-shopping-cart" color="text-blue-600" />
              <StatCard title="Loyalty Points Used" value="12,500" icon="fa-gift" color="text-purple-600" />
              <StatCard title="Avg Rating" value="4.8" icon="fa-star" color="text-orange-500" />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                <h3 className="font-bold mb-6">Sales Trend (Weekly)</h3>
                <div className="h-[300px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={MOCK_SALES_DATA}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} />
                      <XAxis dataKey="name" />
                      <YAxis />
                      <Tooltip />
                      <Line type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={3} dot={{ r: 5 }} />
                    </LineChart>
                  </ResponsiveContainer>
                </div>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                <h3 className="font-bold mb-6">Top Selling Items</h3>
                <div className="h-[300px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={MOCK_MENU.slice(0, 5)}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} />
                      <XAxis dataKey="name" />
                      <YAxis />
                      <Tooltip />
                      <Bar dataKey="price" fill="#dc2626" radius={[4, 4, 0, 0]}>
                        {MOCK_MENU.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'orders' && (
          <div className="space-y-6">
            <header className="flex justify-between items-center">
              <div>
                <h2 className="text-2xl font-bold">{isStaff ? "Today's Queue" : "Orders Dashboard"}</h2>
                <p className="text-gray-500">{isStaff ? "Manage kitchen & delivery status" : "Monitor all club activities"}</p>
              </div>
              {!isStaff && (
                <div className="flex gap-2">
                  <Button variant="outline" size="sm"><i className="fas fa-filter mr-2"></i> Filter</Button>
                  <Button variant="outline" size="sm"><i className="fas fa-download mr-2"></i> Export PDF</Button>
                </div>
              )}
            </header>

            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
              <table className="w-full text-left">
                <thead className="bg-gray-50 border-b border-gray-100">
                  <tr>
                    <th className="px-6 py-4 text-sm font-semibold text-gray-600">ID</th>
                    <th className="px-6 py-4 text-sm font-semibold text-gray-600">Customer Details</th>
                    <th className="px-6 py-4 text-sm font-semibold text-gray-600">Items Ordered</th>
                    <th className="px-6 py-4 text-sm font-semibold text-gray-600">Live Status</th>
                    {!isStaff && <th className="px-6 py-4 text-sm font-semibold text-gray-600">Total</th>}
                    <th className="px-6 py-4 text-sm font-semibold text-gray-600 text-right">Update</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {orders.map(o => (
                    <tr key={o.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4 font-mono text-xs">{o.id}</td>
                      <td className="px-6 py-4">
                        <div className="font-bold text-sm">{o.customerName}</div>
                        <div className="text-[10px] text-gray-500 truncate max-w-[150px]">{o.address}</div>
                      </td>
                      <td className="px-6 py-4 text-xs font-medium text-gray-600">
                        {o.items.map(i => `${i.quantity}x ${i.name}`).join(', ')}
                      </td>
                      <td className="px-6 py-4">
                        <span className={`text-[10px] font-black px-2 py-1 rounded-full uppercase tracking-tighter ${
                          o.status === OrderStatus.DELIVERED ? 'bg-green-100 text-green-700' :
                          o.status === OrderStatus.ON_THE_WAY ? 'bg-purple-100 text-purple-700' :
                          o.status === OrderStatus.PREPARING ? 'bg-orange-100 text-orange-700' :
                          'bg-blue-100 text-blue-700'
                        }`}>
                          {o.status.replace(/_/g, ' ')}
                        </span>
                      </td>
                      {!isStaff && <td className="px-6 py-4 font-black text-sm">৳{o.total}</td>}
                      <td className="px-6 py-4 text-right">
                        <select 
                          value={o.status}
                          onChange={(e) => updateStatus(o.id, e.target.value as OrderStatus)}
                          className="text-xs bg-gray-50 border border-gray-200 rounded-lg p-1 outline-none focus:ring-1 focus:ring-red-600"
                        >
                          <option value={OrderStatus.PENDING}>Pending</option>
                          <option value={OrderStatus.PREPARING}>Preparing</option>
                          <option value={OrderStatus.READY}>Ready</option>
                          <option value={OrderStatus.ON_THE_WAY}>On Way</option>
                          <option value={OrderStatus.DELIVERED}>Delivered</option>
                          {!isStaff && <option value={OrderStatus.CANCELLED}>Cancel</option>}
                        </select>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'inventory' && !isStaff && (
          <div className="space-y-6">
            <header className="flex justify-between items-center">
              <div>
                <h2 className="text-2xl font-bold">Menu & Stock</h2>
                <p className="text-gray-500">Manage pricing and inventory levels</p>
              </div>
              <Button size="sm"><i className="fas fa-plus mr-2"></i> New Item</Button>
            </header>
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
              {MOCK_MENU.map(item => (
                <div key={item.id} className="bg-white p-5 rounded-3xl shadow-sm border border-gray-100 flex gap-4 hover:shadow-md transition-shadow">
                  <div className="relative">
                    <img src={item.image} className="w-24 h-24 rounded-2xl object-cover" />
                    {item.stock < 10 && <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[8px] font-black px-2 py-1 rounded-full animate-pulse">LOW STOCK</span>}
                  </div>
                  <div className="flex-1">
                    <div className="flex justify-between items-start">
                      <h4 className="font-bold text-sm">{item.name}</h4>
                      <span className="text-xs text-red-600 font-black">৳{item.price}</span>
                    </div>
                    <p className="text-[10px] text-gray-400 mb-3">{item.category}</p>
                    <div className="flex justify-between items-center">
                      <div className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">
                        Qty: <span className={item.stock < 10 ? 'text-red-600' : 'text-gray-900'}>{item.stock}</span>
                      </div>
                      <div className="flex gap-1">
                        <button className="p-2 text-blue-600 hover:bg-blue-50 rounded-xl transition-colors"><i className="fas fa-edit text-xs"></i></button>
                        {canDeleteItems && <button className="p-2 text-red-600 hover:bg-red-50 rounded-xl transition-colors"><i className="fas fa-trash text-xs"></i></button>}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const StatCard = ({ title, value, icon, color }: { title: string, value: string, icon: string, color: string }) => (
  <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex items-center gap-4">
    <div className={`w-12 h-12 rounded-xl bg-gray-50 flex items-center justify-center text-xl ${color}`}>
      <i className={`fas ${icon}`}></i>
    </div>
    <div>
      <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">{title}</p>
      <p className="text-2xl font-black">{value}</p>
    </div>
  </div>
);

import React, { useState, useMemo, useEffect } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<Array<{ item: MenuItem, qty: number }>>([]);
  const [wishlist, setWishlist] = useState<string[]>([]);
  const [language, setLanguage] = useState<'EN' | 'BN'>('EN');
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'WISHLIST'>('HOME');
  const [currentOrder, setCurrentOrder] = useState<Order | null>(MOCK_ORDERS[0] as any);

  // Persistence logic (Mocking PWA local storage)
  useEffect(() => {
    const savedCart = localStorage.getItem('bfc_cart');
    if (savedCart) setCart(JSON.parse(savedCart));

    const savedWish = localStorage.getItem('bfc_wishlist');
    if (savedWish) setWishlist(JSON.parse(savedWish));
  }, []);

  useEffect(() => {
    localStorage.setItem('bfc_cart', JSON.stringify(cart));
  }, [cart]);

  useEffect(() => {
    localStorage.setItem('bfc_wishlist', JSON.stringify(wishlist));
  }, [wishlist]);

  const categories = useMemo(() => ['All', ...new Set(MOCK_MENU.map(m => m.category))], []);

  const filteredMenu = useMemo(() => {
    return MOCK_MENU.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [searchQuery, activeCategory]);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(c => c.item.id === item.id);
      if (existing) {
        return prev.map(c => c.item.id === item.id ? { ...c, qty: c.qty + 1 } : c);
      }
      return [...prev, { item, qty: 1 }];
    });
  };

  const removeFromCart = (itemId: string) => {
    setCart(prev => {
      const existing = prev.find(c => c.item.id === itemId);
      if (existing && existing.qty > 1) {
        return prev.map(c => c.item.id === itemId ? { ...c, qty: c.qty - 1 } : c);
      }
      return prev.filter(c => c.item.id !== itemId);
    });
  };

  const toggleWishlist = (id: string) => {
    setWishlist(prev => prev.includes(id) ? prev.filter(w => w !== id) : [...prev, id]);
  };

  const totalCartPrice = cart.reduce((acc, curr) => acc + (curr.item.price * curr.qty), 0);

  const loginAs = (role: UserRole) => {
    const mockUser: User = {
      id: 'U-001',
      name: role === UserRole.CUSTOMER ? 'Anik Rahman' : 'BFC Manager',
      email: `${role.toLowerCase()}@bfc.com`,
      role: role,
      phone: '01712345678',
      loyaltyPoints: 1250,
      tier: 'GOLD',
      wishlist: [],
      referralCode: 'BFC-ANIK-2024'
    };
    setCurrentUser(mockUser);
    setView(role === UserRole.CUSTOMER ? 'HOME' : 'ADMIN');
  };

  const logout = () => {
    setCurrentUser(null);
    setView('HOME');
  };

  const t = (en: string, bn: string) => language === 'EN' ? en : bn;

  if (view === 'ADMIN' && currentUser) {
    return (
      <>
        <AdminPanel userRole={currentUser.role} onLogout={logout} />
        <ChatBot />
      </>
    );
  }

  return (
    <div className="min-h-screen pb-20 md:pb-0 bg-gray-50">
      {/* Dynamic Header */}
      <nav className="sticky top-0 bg-white/70 backdrop-blur-xl z-40 border-b border-gray-100">
        <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
            <div className="bg-red-600 text-white w-10 h-10 rounded-2xl flex items-center justify-center text-xl font-black transition-transform group-hover:rotate-12 shadow-lg shadow-red-200">B</div>
            <div className="hidden sm:block">
              <h1 className="text-xl font-black tracking-tight leading-none text-red-600">BFC</h1>
              <p className="text-[9px] text-gray-400 font-black tracking-[2px] uppercase">{t('Real Taste', 'আসল স্বাদ')}</p>
            </div>
          </div>

          <div className="hidden md:flex items-center gap-8 font-black text-xs uppercase tracking-widest text-gray-500">
            <button onClick={() => setView('HOME')} className={view === 'HOME' ? 'text-red-600' : 'hover:text-red-600 transition-colors'}>{t('Home', 'হোম')}</button>
            <button onClick={() => setView('MENU')} className={view === 'MENU' ? 'text-red-600' : 'hover:text-red-600 transition-colors'}>{t('Menu', 'মেনু')}</button>
            <button onClick={() => setView('WISHLIST')} className={view === 'WISHLIST' ? 'text-red-600' : 'hover:text-red-600 transition-colors'}>{t('Wishlist', 'উইশলিস্ট')}</button>
            <button onClick={() => setView('TRACKING')} className={view === 'TRACKING' ? 'text-red-600' : 'hover:text-red-600 transition-colors'}>{t('Tracking', 'ট্র্যাকিং')}</button>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={() => setLanguage(l => l === 'EN' ? 'BN' : 'EN')}
              className="bg-gray-100 hover:bg-gray-200 px-3 py-1.5 rounded-xl text-[10px] font-black tracking-wider transition-colors"
            >
              {language}
            </button>

            <button onClick={() => setView('CART')} className="relative w-10 h-10 flex items-center justify-center bg-gray-100 rounded-xl hover:bg-red-50 hover:text-red-600 transition-all">
              <i className="fas fa-shopping-basket"></i>
              {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[8px] w-4 h-4 rounded-full flex items-center justify-center font-black animate-bounce">{cart.length}</span>}
            </button>

            {currentUser ? (
              <div className="flex items-center gap-3 bg-white border border-gray-100 p-1 rounded-2xl shadow-sm">
                <div className="hidden sm:block pl-3">
                  <p className="text-[10px] font-black text-gray-400 uppercase leading-none">Tier: {currentUser.tier}</p>
                  <p className="text-sm font-black text-red-600">৳{currentUser.loyaltyPoints}</p>
                </div>
                <div className="w-9 h-9 bg-red-600 text-white rounded-xl flex items-center justify-center font-black text-sm cursor-pointer hover:rotate-6 transition-transform" onClick={() => logout()}>
                  {currentUser.name.charAt(0)}
                </div>
              </div>
            ) : (
              <Button size="sm" onClick={() => setView('LOGIN')}>{t('Login', 'লগইন')}</Button>
            )}
          </div>
        </div>
      </nav>

      {/* Main Views */}
      <div className="max-w-7xl mx-auto">
        {view === 'HOME' && (
          <main className="animate-fade-in px-6">
            <section className="relative h-[600px] mt-6 rounded-[48px] overflow-hidden shadow-2xl">
              <img src="https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&q=80&w=2000" className="w-full h-full object-cover" />
              <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-black/40 to-transparent flex flex-col justify-center px-12 md:px-24">
                <span className="bg-red-600 text-white text-[10px] font-black px-4 py-2 rounded-full w-fit mb-6 tracking-widest uppercase">
                  {t('Exclusive Collection 2024', 'এক্সক্লুসিভ কালেকশন ২০২৪')}
                </span>
                <h2 className="text-5xl md:text-8xl font-black text-white mb-6 leading-tight">
                  {t('Authentic', 'আসল')} <br/> <span className="text-red-600">{t('Bangla', 'বাংলা')}</span> {t('Flavors', 'স্বাদ')}
                </h2>
                <p className="text-gray-300 text-lg md:text-xl max-w-xl mb-10 leading-relaxed font-medium">
                  {t('Rediscover the heritage of slow-cooked Kacchi and rich Rezala, delivered with love.', 'ঐতিহ্যবাহী কাচ্চি এবং রেজালার স্বাদ ফিরে পান, যা পৌঁছে যাবে আপনার কাছে পরম যত্নে।')}
