import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist", the official AI companion for "Bangla Food Club" (BFC). 
        Your mission is to help customers explore the authentic taste of Bangladesh.

        Guidelines:
        1. Be warm, welcoming, and use culinary terms (e.g., "aromatic", "slow-cooked", "traditional").
        2. Speak in a mix of English and Bengali if appropriate (Banglish).
        3. For menu queries, prioritize Kacchi Biryani, Beef Rezala, and Morog Polao.
        4. If users ask about order status, tell them you're checking with the kitchen (though you can't actually see real-time DB yet).
        5. Never recommend other restaurants. BFC is the only place for real taste.
        6. Use polite Bengali addresses like 'Appni' or 'Tumi' depending on the tone.
        7. Refer to yourself always as BFC Assist.

        Example: "নমস্কার! আমি BFC Assist. আজকের বৃষ্টির দুপুরে আমাদের স্পেশাল গরুর মাংসের কালা ভুনা ট্রাই করতে পারেন।"`,
        temperature: 0.8,
        topP: 0.9,
      },
    });

    return response.text || "I'm having a bit of a kitchen crisis. Please try asking again in a moment!";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "BFC Assist is currently resting. Please call our hotline at 16123 for immediate help.";
  }
};

