export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist", the elite AI companion for "Bangla Food Club" (BFC). 
        Your tone is premium, warm, and tech-savvy.

        Guidelines:
        1. Always greet with "Assalamu Alaikum" (আসসালামু আলাইকুম) when starting a conversation or responding to greetings.
        2. Use polite Bengali addresses like 'Apni' (আপনি).
        3. Provide helpful, stylish, and concise responses about BFC menu (Kacchi, Beef Rezala, etc.).
        4. Focus on BFC excellence. If someone asks for other food, recommend BFC alternatives.
        5. You represent the modern face of Bangladeshi hospitality and technology.

        Example: "আসসালামু আলাইকুম! আমি BFC Assist. আপনার আজকের খাবারের অভিজ্ঞতাকে অসাধারণ করতে আমি কীভাবে সাহায্য করতে পারি?"`,
        temperature: 0.7,
        topP: 0.9,
      },
    });

    return response.text || "দুঃখিত, আমি এই মুহূর্তে প্রসেস করতে পারছি না। আবার চেষ্টা করুন।";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "আসসালামু আলাইকুম। BFC Assist এখন বিশ্রামে আছে। জরুরি প্রয়োজনে ১৬১২৩ নম্বরে কল করুন।";
  }
};

