import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

export const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'আসসালামু আলাইকুম! আমি BFC Assist। আপনার আজকের খাবারের অভিজ্ঞতাকে অসাধারণ করতে আমি কীভাবে সাহায্য করতে পারি?', timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ role: m.role, parts: [{ text: m.text }] }));
    const botResponse = await bfcAssistChat(input, history);

    setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    setIsTyping(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[100]">
      {isOpen ? (
        <div className="bg-white/80 backdrop-blur-2xl w-[320px] sm:w-[380px] h-[550px] rounded-[40px] shadow-[0_20px_60px_-15px_rgba(0,0,0,0.15)] flex flex-col border border-white/40 overflow-hidden animate-slide-up">
          <div className="bg-red-600 p-6 text-white flex justify-between items-center shadow-lg">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center font-black text-lg">B</div>
              <div>
                <h3 className="font-black text-sm leading-none">BFC Assist</h3>
                <p className="text-[10px] opacity-80 font-bold uppercase mt-1 tracking-widest">Always Online</p>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="hover:bg-black/10 w-8 h-8 rounded-lg flex items-center justify-center transition-colors">
              <i className="fas fa-times"></i>
            </button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 scrollbar-hide">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-4 rounded-[24px] text-xs font-medium leading-relaxed ${
                  m.role === 'user' 
                  ? 'bg-red-600 text-white rounded-tr-none shadow-lg shadow-red-100' 
                  : 'bg-white text-gray-800 shadow-sm border border-gray-50 rounded-tl-none'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white p-4 rounded-full text-xs shadow-sm flex gap-1">
                  <div className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce"></div>
                  <div className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>

          <div className="p-6 bg-white/50 border-t border-white/40 flex gap-2">
            <input 
              type="text" value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Ask me anything..."
              className="flex-1 bg-white border border-gray-100 rounded-2xl px-5 py-3 outline-none focus:ring-2 focus:ring-red-600 text-xs font-bold shadow-inner"
            />
            <button onClick={handleSend} className="bg-red-600 text-white w-12 h-12 rounded-2xl flex items-center justify-center hover:bg-red-700 transition-all shadow-xl shadow-red-200">
              <i className="fas fa-paper-plane"></i>
            </button>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-red-600 text-white w-14 h-14 lg:w-16 lg:h-16 rounded-[24px] shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all duration-300"
        >
          <i className="fas fa-robot text-2xl lg:text-3xl"></i>
          <span className="absolute -top-1 -right-1 bg-green-500 w-4 h-4 rounded-full border-2 border-white animate-pulse"></span>
        </button>
      )}
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist". 
        Rules:
        1. Always start with "Assalamu Alaikum".
        2. Keep responses EXTREMELY SHORT and CONCISE (max 1-2 sentences).
        3. Only provide essential information about BFC food or orders.
        4. Use polite Bengali (Apni).
        5. Do not apologize unless necessary. Be direct and fast.

        Example: "Assalamu Alaikum! Our Kacchi is 450 BDT. Would you like to order?"`,
        temperature: 0.5,
        topP: 0.8,
      },
    });

    return response.text || "দুঃখিত, আবার চেষ্টা করুন।";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "আসসালামু আলাইকুম। বিএফসি অ্যাসিস্ট এখন অফলাইনে। ১৬১২৩ কল করুন।";
  }
};

