import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

export const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'আসসালামু আলাইকুম! আমি BFC Assist। আমি কীভাবে আপনাকে সাহায্য করতে পারি?', timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ role: m.role, parts: [{ text: m.text }] }));
    const botResponse = await bfcAssistChat(input, history);

    setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    setIsTyping(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[100] font-sans">
      {isOpen ? (
        <div className="bg-white/90 backdrop-blur-3xl w-[90vw] sm:w-[400px] h-[75vh] sm:h-[600px] rounded-[48px] shadow-[0_30px_100px_-20px_rgba(0,0,0,0.2)] flex flex-col border border-white/50 overflow-hidden animate-slide-up gpu">
          {/* Header */}
          <div className="bg-red-600 p-8 text-white flex justify-between items-center shadow-lg shrink-0">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center font-black text-xl">B</div>
              <div>
                <h3 className="font-black text-sm">BFC Assist</h3>
                <p className="text-[10px] opacity-70 font-bold uppercase tracking-widest mt-0.5">Live Agent AI</p>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-10 h-10 hover:bg-black/10 rounded-xl transition-colors">
              <i className="fas fa-times"></i>
            </button>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-6 scrollbar-hide bg-gradient-to-b from-transparent to-gray-50/50">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-5 py-4 rounded-[28px] text-xs font-bold leading-relaxed shadow-sm ${
                  m.role === 'user' 
                  ? 'bg-red-600 text-white rounded-tr-none' 
                  : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white px-5 py-3 rounded-full flex gap-1.5 shadow-sm border border-gray-50">
                  <span className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce"></span>
                  <span className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="p-8 bg-white border-t border-gray-50 flex gap-3 shrink-0">
            <input 
              type="text" value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Ask anything..."
              className="flex-1 bg-gray-50 border-none rounded-2xl px-6 py-4 outline-none focus:ring-2 focus:ring-red-600 text-xs font-bold shadow-inner"
            />
            <button onClick={handleSend} className="bg-red-600 text-white w-14 h-14 rounded-2xl flex items-center justify-center hover:bg-red-700 transition-all shadow-xl shadow-red-200 active:scale-90">
              <i className="fas fa-paper-plane"></i>
            </button>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-red-600 text-white w-16 h-16 lg:w-20 lg:h-20 rounded-[30px] shadow-2xl flex items-center justify-center hover:scale-110 active:scale-90 transition-all duration-300 group relative"
        >
