import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

export const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'আসসালামু আলাইকুম! আমি BFC Assist। আমি কীভাবে আপনাকে সাহায্য করতে পারি?', timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ role: m.role, parts: [{ text: m.text }] }));
    const botResponse = await bfcAssistChat(input, history);

    setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    setIsTyping(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[100] font-sans">
      {isOpen ? (
        <div className="bg-white/95 backdrop-blur-3xl w-[90vw] sm:w-[380px] h-[70vh] sm:h-[550px] rounded-[40px] shadow-[0_40px_100px_-20px_rgba(0,0,0,0.3)] flex flex-col border border-white/50 overflow-hidden animate-slide-up gpu">
          {/* Header */}
          <div className="bg-red-600 p-6 text-white flex justify-between items-center shadow-lg shrink-0">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-white/20 backdrop-blur-md rounded-xl flex items-center justify-center font-black text-lg">B</div>
              <div>
                <h3 className="font-black text-xs">BFC Assist</h3>
                <p className="text-[8px] opacity-70 font-bold uppercase tracking-widest">AI Expert</p>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-8 h-8 hover:bg-black/10 rounded-lg transition-colors flex items-center justify-center">
              <i className="fas fa-times"></i>
            </button>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 scrollbar-hide">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] px-5 py-3.5 rounded-[24px] text-xs font-bold leading-relaxed shadow-sm ${
                  m.role === 'user' 
                  ? 'bg-red-600 text-white rounded-tr-none' 
                  : 'bg-gray-100 text-gray-800 rounded-tl-none'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-gray-100 px-4 py-2 rounded-full flex gap-1.5 shadow-sm">
                  <span className="w-1 h-1 bg-red-400 rounded-full animate-bounce"></span>
                  <span className="w-1 h-1 bg-red-400 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-1 h-1 bg-red-400 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-6 bg-white border-t border-gray-50 flex gap-2 shrink-0">
            <input 
              type="text" value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Type your question..."
              className="flex-1 bg-gray-50 border-none rounded-2xl px-5 py-3 outline-none focus:ring-2 focus:ring-red-600 text-xs font-bold shadow-inner"
            />
            <button onClick={handleSend} className="bg-red-600 text-white w-12 h-12 rounded-2xl flex items-center justify-center hover:bg-red-700 transition-all active:scale-90 shadow-xl shadow-red-200">
              <i className="fas fa-paper-plane text-sm"></i>
            </button>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-red-600 text-white w-14 h-14 sm:w-16 sm:h-16 rounded-[24px] shadow-2xl flex items-center justify-center hover:scale-110 active:scale-90 transition-all group relative"
        >
          <i className="fas fa-robot text-2xl group-hover:rotate-12 transition-transform"></i>
          <span className="absolute -top-1 -right-1 w-4 h-4 bg-green-500 border-4 border-gray-50 rounded-full"></span>
        </button>
      )}
    </div>
  );
};

