import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

export const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'আসসালামু আলাইকুম! আমি BFC Assist। আমি কীভাবে আপনাকে সাহায্য করতে পারি?', timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ role: m.role, parts: [{ text: m.text }] }));
    const botResponse = await bfcAssistChat(input, history);

    setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    setIsTyping(false);
  };

  return (
    <div className="fixed bottom-10 right-10 z-[100] font-sans">
      {isOpen ? (
        <div className="bg-white/95 backdrop-blur-3xl w-[90vw] sm:w-[420px] h-[75vh] sm:h-[620px] rounded-[50px] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.4)] flex flex-col border border-white/50 overflow-hidden animate-slide-up gpu">
          {/* Header */}
          <div className="bg-red-600 p-8 text-white flex justify-between items-center shadow-xl shrink-0">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center font-black text-2xl">B</div>
              <div>
                <h3 className="font-black text-sm tracking-tight">BFC Concierge</h3>
                <p className="text-[9px] opacity-70 font-bold uppercase tracking-widest flex items-center gap-1">
                  <span className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse"></span> Active AI Instance
                </p>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-10 h-10 hover:bg-black/10 rounded-xl transition-colors flex items-center justify-center">
              <i className="fas fa-times text-xl"></i>
            </button>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-10 space-y-8 scrollbar-hide">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-6 py-4.5 rounded-[32px] text-xs font-bold leading-relaxed shadow-sm ${
                  m.role === 'user' 
                  ? 'bg-red-600 text-white rounded-tr-none' 
                  : 'bg-gray-100 text-gray-800 rounded-tl-none border border-gray-50'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-gray-100 px-6 py-3 rounded-full flex gap-2 shadow-sm border border-gray-50">
                  <span className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce"></span>
                  <span className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-8 bg-white border-t border-gray-50 flex gap-3 shrink-0">
            <input 
              type="text" value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Ask me anything..."
              className="flex-1 bg-gray-50 border-none rounded-3xl px-7 py-5 outline-none focus:ring-4 focus:ring-red-50 text-xs font-black shadow-inner"
            />
            <button onClick={handleSend} className="bg-red-600 text-white w-16 h-16 rounded-[24px] flex items-center justify-center hover:bg-red-700 transition-all active:scale-90 shadow-2xl shadow-red-200">
              <i className="fas fa-paper-plane text-lg"></i>
            </button>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-red-600 text-white w-16 h-16 sm:w-20 sm:h-20 rounded-[30px] shadow-[0_25px_60px_-15px_rgba(220,38,38,0.5)] flex items-center justify-center hover:scale-110 active:scale-95 transition-all duration-500 group relative gpu"
        >
          <i className="fas fa-robot text-3xl group-hover:rotate-12 transition-transform"></i>
          <span className="absolute -top-1 -right-1 w-6 h-6 bg-green-500 border-4 border-white rounded-full"></span>
        </button>
      )}
    </div>
  );
};

