  paymentMethod: 'BKASH' | 'NAGAD' | 'ROCKET' | 'UPAY' | 'CARD' | 'COD';
  address: string;
  pointsEarned: number;
  trackingUpdates: Array<{ status: OrderStatus; time: string }>;
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  phone: string;
  password?: string;
  loyaltyPoints: number;
  tier: 'SILVER' | 'GOLD' | 'PLATINUM';
  wishlist: string[];
  referralCode: string;
  profileImage?: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useEffect, useRef } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<Array<{ item: MenuItem, qty: number }>>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE' | 'PAYMENT' | 'REGISTER'>('HOME');

  // Profile & Auth States
  const [formName, setFormName] = useState('');
  const [formEmail, setFormEmail] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [formPass, setFormPass] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Payment & Order States
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'ROCKET' | 'UPAY' | 'CARD' | 'COD'>('BKASH');
  const [isProcessing, setIsProcessing] = useState(false);
  const [orderCode, setOrderCode] = useState('');
  const [cardDetails, setCardDetails] = useState({ number: '', exp: '', cvv: '' });

  // Persistence Logic
  useEffect(() => {
    const saved = localStorage.getItem('bfc_session_user');
    if (saved) {
      const parsed = JSON.parse(saved);
      setCurrentUser(parsed);
      setFormName(parsed.name);
      setFormPhone(parsed.phone);
    }
  }, []);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('bfc_session_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('bfc_session_user');
    }
  }, [currentUser]);

  const handleAuth = (type: 'LOGIN' | 'REGISTER') => {
    if (formEmail === 'admin@bfc.com' && formPass === 'admin123') {
      const admin: User = {
        id: 'ADM-001', name: 'Super Admin', email: 'admin@bfc.com',
        phone: '01711000000', role: UserRole.ADMIN, loyaltyPoints: 9999,
        tier: 'PLATINUM', wishlist: [], referralCode: 'BFC-MASTER'
      };
      setCurrentUser(admin);
      setView('ADMIN');
      return;
    }

    const user: User = {
      id: 'U-' + Date.now(),
      name: formName || 'BFC Member',
      email: formEmail,
      phone: formPhone || '01XXXXXXXXX',
      role: UserRole.CUSTOMER,
      loyaltyPoints: 0,
      tier: 'SILVER',
      wishlist: [],
      referralCode: 'BFC-' + Math.random().toString(36).substring(7).toUpperCase()
    };
    setCurrentUser(user);
    setView('HOME');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && currentUser) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setCurrentUser({ ...currentUser, profileImage: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const executeCheckout = () => {
    if (paymentMethod === 'CARD' && (!cardDetails.number || !cardDetails.exp || !cardDetails.cvv)) {
      alert('কার্ডের তথ্য সম্পূর্ণ করুন'); return;
    }
    setIsProcessing(true);
    setTimeout(() => {
      setIsProcessing(false);
      setOrderCode('BFC-' + Math.floor(100000 + Math.random() * 900000));
      setCart([]);
      setView('TRACKING');
    }, 2000);
  };

  const totalPrice = cart.reduce((acc, curr) => acc + (curr.item.price * curr.qty), 0);

  if (view === 'ADMIN' && currentUser) {
    return <AdminPanel userRole={currentUser.role} onLogout={() => { setCurrentUser(null); setView('HOME'); }} />;
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans selection:bg-red-100 overflow-x-hidden">
      {/* Premium Navbar */}
      <nav className="sticky top-0 z-50 bg-white/80 backdrop-blur-2xl border-b border-gray-100 px-6 lg:px-12 py-5 flex justify-between items-center gpu">
        <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white font-black shadow-xl group-hover:scale-105 transition-transform duration-500">B</div>
          <h1 className="text-2xl font-black text-red-600 tracking-tighter hidden sm:block">BFC</h1>
        </div>

        <div className="hidden lg:flex items-center gap-10 text-[11px] font-black uppercase tracking-widest text-gray-400">
          <button onClick={()=>setView('HOME')} className={view === 'HOME' ? 'text-red-600' : 'hover:text-red-600 transition-all'}>Home</button>
          <button onClick={()=>setView('MENU')} className={view === 'MENU' ? 'text-red-600' : 'hover:text-red-600 transition-all'}>Collection</button>
          <button onClick={()=>setView('TRACKING')} className={view === 'TRACKING' ? 'text-red-600' : 'hover:text-red-600 transition-all'}>Orders</button>
        </div>

        <div className="flex items-center gap-5">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 bg-gray-50 text-gray-800 rounded-2xl flex items-center justify-center hover:bg-red-600 hover:text-white transition-all shadow-sm group">
            <i className="fas fa-shopping-basket group-hover:-translate-y-1 transition-transform"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[9px] w-6 h-6 rounded-full flex items-center justify-center ring-4 ring-white animate-bounce">{cart.length}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-12 h-12 rounded-2xl border-2 border-white overflow-hidden shadow-lg active:scale-90 transition-all">
              {currentUser.profileImage ? (
                <img src={currentUser.profileImage} className="w-full h-full object-cover" />
              ) : (
                <div className="w-full h-full bg-red-600 flex items-center justify-center text-white font-black">{currentUser.name.charAt(0)}</div>
              )}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl px-8" onClick={() => setView('LOGIN')}>Login</Button>
          )}
        </div>
      </nav>

      {/* Main Content Area */}
      <div className="max-w-7xl mx-auto px-6 py-8">
        {view === 'HOME' && (
          <div className="animate-slide-up gpu">
            <header className="relative h-[450px] lg:h-[650px] rounded-[60px] overflow-hidden shadow-2xl mb-20">
               <img src="https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&q=80&w=2000" className="w-full h-full object-cover" />
               <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-black/40 to-transparent flex flex-col justify-center px-10 lg:px-24">
                  <h2 className="text-5xl lg:text-9xl font-black text-white leading-tight mb-8 tracking-tighter">Savor <br/><span className="text-red-600">Bengal</span></h2>
                  <div className="flex gap-4">
                    <Button size="lg" className="rounded-3xl px-12" onClick={() => setView('MENU')}>Order Now</Button>
                    <Button variant="outline" size="lg" className="rounded-3xl px-12 border-white text-white hover:bg-white hover:text-black">Explore Perks</Button>
                  </div>
               </div>
            </header>
            <div className="flex justify-between items-center mb-10">
               <h3 className="text-3xl font-black text-gray-800">Chef's Recommendations</h3>
               <button onClick={()=>setView('MENU')} className="text-red-600 font-bold text-sm">View All <i className="fas fa-arrow-right ml-2"></i></button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-10">
               {MOCK_MENU.slice(0, 4).map(item => (
                 <ProductCard key={item.id} item={item} onAdd={(item: any) => setCart([...cart, {item, qty:1}])} />
               ))}
            </div>
          </div>
        )}

        {view === 'PROFILE' && currentUser && (
          <div className="max-w-4xl mx-auto animate-slide-up gpu">
             <div className="bg-white rounded-[60px] p-12 lg:p-20 shadow-2xl border border-gray-50 flex flex-col lg:flex-row gap-20">
                <div className="flex flex-col items-center shrink-0">
                   <div className="relative group">
                      <div className="w-48 h-48 rounded-[50px] overflow-hidden border-8 border-gray-50 shadow-2xl">
                         {currentUser.profileImage ? (
                           <img src={currentUser.profileImage} className="w-full h-full object-cover" />
                         ) : (
                           <div className="w-full h-full bg-red-600 flex items-center justify-center text-7xl text-white font-black">{currentUser.name.charAt(0)}</div>
                         )}
                      </div>
                      <button onClick={() => fileInputRef.current?.click()} className="absolute -bottom-4 -right-4 w-14 h-14 bg-white text-red-600 rounded-2xl shadow-2xl flex items-center justify-center hover:bg-red-600 hover:text-white transition-all">
                         <i className="fas fa-camera"></i>
                      </button>
                      <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
                   </div>
                   <div className="mt-10 text-center">
                      <p className="text-2xl font-black text-gray-800">{currentUser.name}</p>
                      <p className="text-[10px] font-bold text-red-600 uppercase tracking-widest mt-1">{currentUser.tier} Membership</p>
                      <div className="mt-6 flex gap-4 justify-center">
                         <div className="bg-orange-50 px-4 py-2 rounded-xl text-center">
                            <p className="text-sm font-black text-orange-600">{currentUser.loyaltyPoints}</p>
                            <p className="text-[8px] font-bold text-gray-400 uppercase">Points</p>
                         </div>
                      </div>
                   </div>
                </div>

                <div className="flex-1 space-y-10">
                   <h2 className="text-4xl font-black text-gray-800">Account Identity</h2>
                   <form onSubmit={(e) => { e.preventDefault(); alert('প্রোফাইল আপডেট হয়েছে!'); }} className="space-y-6">
                      <Input label="Full Name" value={formName} onChange={(e:any)=>setFormName(e.target.value)} />
                      <Input label="Active Phone" value={formPhone} onChange={(e:any)=>setFormPhone(e.target.value)} />
                      <Input label="Email Address" value={currentUser.email} disabled />
                      <Button fullWidth className="rounded-3xl py-6 mt-4 shadow-2xl shadow-red-100">Save Configuration</Button>
                   </form>
                   <button onClick={()=>{setCurrentUser(null); setView('HOME')}} className="w-full py-5 text-gray-400 font-bold hover:text-red-600 transition-colors uppercase text-[10px] tracking-widest">Terminate Session</button>
                </div>
             </div>
          </div>
        )}

        {view === 'PAYMENT' && (
          <div className="max-w-2xl mx-auto animate-slide-up gpu">
             <div className="bg-white rounded-[60px] p-12 lg:p-16 shadow-2xl border border-gray-100">
                <h2 className="text-4xl font-black mb-12 text-center text-gray-800">Secure Payment</h2>
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-5 mb-12">
                   <PaymentOption id="BKASH" active={paymentMethod === 'BKASH'} onClick={()=>setPaymentMethod('BKASH')} img="https://upload.wikimedia.org/wikipedia/commons/8/8b/Bkash_logo.png" label="bKash" />
                   <PaymentOption id="NAGAD" active={paymentMethod === 'NAGAD'} onClick={()=>setPaymentMethod('NAGAD')} img="https://seeklogo.com/images/N/nagad-logo-7A70AE6460-seeklogo.com.png" label="Nagad" />
                   <PaymentOption id="ROCKET" active={paymentMethod === 'ROCKET'} onClick={()=>setPaymentMethod('ROCKET')} img="https://seeklogo.com/images/D/dutch-bangla-rocket-logo-B4D1CC458D-seeklogo.com.png" label="Rocket" />
                   <PaymentOption id="UPAY" active={paymentMethod === 'UPAY'} onClick={()=>setPaymentMethod('UPAY')} img="https://seeklogo.com/images/U/upay-logo-0D2B6005E1-seeklogo.com.png" label="Upay" />
                   <PaymentOption id="CARD" active={paymentMethod === 'CARD'} onClick={()=>setPaymentMethod('CARD')} icon="fa-credit-card" label="Card" />
                   <PaymentOption id="COD" active={paymentMethod === 'COD'} onClick={()=>setPaymentMethod('COD')} icon="fa-truck-fast" label="COD" />
                </div>

                {paymentMethod === 'CARD' && (
                   <div className="bg-gray-50 p-8 rounded-[40px] mb-10 space-y-6 animate-slide-up border border-gray-100 shadow-inner">
                      <Input label="Card Number" value={cardDetails.number} onChange={(e:any)=>setCardDetails({...cardDetails, number: e.target.value})} placeholder="0000 0000 0000 0000" />
                      <div className="grid grid-cols-2 gap-6">
                         <Input label="Expiry" value={cardDetails.exp} onChange={(e:any)=>setCardDetails({...cardDetails, exp: e.target.value})} placeholder="MM/YY" />
                         <Input label="CVV" value={cardDetails.cvv} onChange={(e:any)=>setCardDetails({...cardDetails, cvv: e.target.value})} type="password" placeholder="***" />
                      </div>
                   </div>
                )}

                <div className="bg-red-50 p-10 rounded-[40px] mb-12 flex justify-between items-center">
                   <div>
                      <p className="text-[10px] font-black text-red-400 uppercase tracking-widest">Grand Total</p>
                      <h4 className="text-4xl font-black text-red-600">৳{totalPrice + 60}</h4>
                   </div>
                   <div className="text-right">
                      <p className="text-[10px] font-bold text-gray-400">Incl. Taxes & Delivery</p>
                   </div>
                </div>

                <Button fullWidth size="lg" className="rounded-3xl py-8 text-xl shadow-2xl shadow-red-200" disabled={isProcessing} onClick={executeCheckout}>
                   {isProcessing ? 'Connecting...' : 'Authorize Transaction'}
                </Button>
             </div>
          </div>
        )}

        {view === 'TRACKING' && (
          <div className="max-w-2xl mx-auto animate-slide-up gpu text-center py-10">
             <div className="bg-white rounded-[70px] p-16 lg:p-24 shadow-2xl border border-gray-100 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-3 bg-gradient-to-r from-red-600 to-orange-500"></div>
                <div className="w-24 h-24 bg-green-50 text-green-600 rounded-full flex items-center justify-center mx-auto mb-10 shadow-lg">
                   <i className="fas fa-radar text-4xl animate-pulse"></i>
                </div>
                <h2 className="text-4xl font-black text-gray-800 mb-2">Live Logistics</h2>
                <p className="text-gray-400 font-bold mb-16 tracking-widest uppercase text-xs">Unit ID: {orderCode || 'BFC-882901'}</p>

                <div className="space-y-16 text-left relative max-w-[320px] mx-auto mb-16">
                   <div className="absolute left-[23px] top-8 bottom-8 w-1 bg-gray-100"></div>
                   <TrackerNode active icon="fa-receipt" title="Command Received" desc="Kitchen has confirmed the order" />
                   <TrackerNode active icon="fa-utensils" title="Production Phase" desc="Meal is currently being crafted" />
                   <TrackerNode icon="fa-motorcycle" title="In Transit" desc="Delivery unit is moving to target" />
                   <TrackerNode icon="fa-check-double" title="Fulfilled" desc="Order dropped at destination" />
                </div>
                <Button variant="outline" className="rounded-3xl px-14 py-5" onClick={()=>setView('HOME')}>Return to HQ</Button>
             </div>
          </div>
        )}
      </div>

      <ChatBot />

      {/* Modern OS Bottom Bar */}
      <div className="lg:hidden fixed bottom-0 w-full bg-white/95 backdrop-blur-3xl px-12 py-10 flex justify-between items-center z-50 rounded-t-[60px] shadow-[0_-20px_50px_rgba(0,0,0,0.1)] border-t border-gray-100">
         <button onClick={()=>setView('HOME')} className={view === 'HOME' ? 'text-red-600 scale-150 transition-all' : 'text-gray-300'}><i className="fas fa-home text-2xl"></i></button>
         <button onClick={()=>setView('MENU')} className={view === 'MENU' ? 'text-red-600 scale-150 transition-all' : 'text-gray-300'}><i className="fas fa-search text-2xl"></i></button>
         <button onClick={()=>setView('CART')} className={view === 'CART' ? 'text-red-600 scale-150 transition-all' : 'text-gray-300'}><i className="fas fa-shopping-basket text-2xl"></i></button>
         <button onClick={()=>currentUser ? setView('PROFILE') : setView('LOGIN')} className={view === 'PROFILE' ? 'text-red-600 scale-150 transition-all' : 'text-gray-300'}><i className="fas fa-user-circle text-2xl"></i></button>
      </div>
    </div>
  );
};

const ProductCard = ({ item, onAdd }: any) => (
  <div className="group bg-white rounded-[50px] overflow-hidden shadow-sm border border-gray-100 hover:shadow-2xl hover:-translate-y-4 transition-all duration-700 gpu">
    <div className="h-64 p-4">
      <img src={item.image} className="w-full h-full rounded-[40px] object-cover group-hover:scale-110 transition-transform duration-1000" />
    </div>
    <div className="p-10 pt-2 flex flex-col flex-1">
       <h4 className="text-2xl font-black text-gray-800 mb-1 leading-tight">{item.name}</h4>
       <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mb-8">{item.category}</p>
       <div className="flex justify-between items-center mt-auto">
          <span className="text-3xl font-black text-red-600">৳{item.price}</span>
          <button onClick={() => onAdd(item)} className="w-14 h-14 bg-gray-50 hover:bg-red-600 hover:text-white rounded-[24px] flex items-center justify-center transition-all shadow-sm active:scale-90 border border-gray-100">
