import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

export const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'আসসালামু আলাইকুম! আমি BFC Assist। আপনার খাবারের অর্ডার বা অন্য যেকোনো প্রয়োজনে আমি পাশে আছি।', timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));
    const botResponse = await bfcAssistChat(input, history);

    setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    setIsTyping(false);
  };

  return (
    <div className="fixed bottom-10 right-10 z-[100] font-sans">
      {isOpen ? (
        <div className="bg-white/95 backdrop-blur-3xl w-[92vw] sm:w-[450px] h-[80vh] sm:h-[680px] rounded-[60px] shadow-[0_60px_120px_-30px_rgba(0,0,0,0.5)] flex flex-col border border-white/50 overflow-hidden animate-slide-up gpu">
          {/* Elite Bot Header */}
          <div className="bg-red-600 p-10 text-white flex justify-between items-center shadow-2xl shrink-0">
            <div className="flex items-center gap-5">
               <div className="relative">
                  <div className="w-14 h-14 bg-white/20 backdrop-blur-xl rounded-[22px] flex items-center justify-center font-black text-3xl">B</div>
                  <span className="absolute -bottom-1 -right-1 w-5 h-5 bg-green-400 border-4 border-red-600 rounded-full animate-pulse"></span>
               </div>
              <div>
                <h3 className="font-black text-lg tracking-tight">BFC Concierge</h3>
                <p className="text-[10px] opacity-70 font-bold uppercase tracking-[4px]">Neural Link Active</p>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="w-12 h-12 hover:bg-black/10 rounded-2xl transition-all flex items-center justify-center">
              <i className="fas fa-times text-2xl"></i>
            </button>
          </div>

          {/* Message Stream */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-12 space-y-10 scrollbar-hide bg-gradient-to-b from-gray-50/50 to-white">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-8 py-6 rounded-[35px] text-sm font-bold leading-relaxed shadow-sm transition-all animate-slide-up ${
                  m.role === 'user' 
                  ? 'bg-red-600 text-white rounded-tr-none shadow-red-100' 
                  : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white px-8 py-5 rounded-[30px] flex gap-3 shadow-sm border border-gray-50">
                  <span className="w-2 h-2 bg-red-400 rounded-full animate-bounce"></span>
                  <span className="w-2 h-2 bg-red-400 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-2 h-2 bg-red-400 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            )}
          </div>

          {/* Secure Input Node */}
          <div className="p-10 bg-white border-t border-gray-50 flex gap-4 shrink-0">
            <input 
              type="text" value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Ask for recommendations..."
              className="flex-1 bg-gray-50 border-none rounded-[35px] px-10 py-6 outline-none focus:ring-4 focus:ring-red-50 text-sm font-black shadow-inner"
            />
            <button onClick={handleSend} className="bg-red-600 text-white w-20 h-20 rounded-[30px] flex items-center justify-center hover:bg-red-700 transition-all active:scale-90 shadow-[0_20px_40px_rgba(220,38,38,0.3)]">
              <i className="fas fa-paper-plane text-2xl"></i>
            </button>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-red-600 text-white w-20 h-20 sm:w-24 sm:h-24 rounded-[35px] shadow-[0_30px_70px_-15px_rgba(220,38,38,0.6)] flex items-center justify-center hover:scale-110 active:scale-95 transition-all duration-700 group relative gpu border-4 border-white"
        >
          <i className="fas fa-comment-nodes text-4xl group-hover:rotate-12 transition-transform"></i>
          <span className="absolute -top-1 -right-1 w-7 h-7 bg-green-500 border-4 border-white rounded-full"></span>
        </button>
      )}
    </div>
  );
};

