);

const TrackerNode = ({ active, icon, title, desc }: any) => (
  <div className="flex items-center gap-8 relative z-10">
    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${active ? 'bg-red-600 text-white shadow-lg scale-110' : 'bg-gray-100 text-gray-300'}`}>
