    <div>
      <h4 className={`text-lg font-bold ${active ? 'text-gray-800' : 'text-gray-200'}`}>{title}</h4>
      <p className="text-[10px] font-bold text-gray-400">{desc}</p>
    </div>
  </div>
);

export default App;

