export const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { 
      role: 'model', 
      text: 'হ্যালো! আমি BFC কনসিয়ার্জ। আপনার পছন্দের খাবারের খোঁজে সাহায্য করতে পারি? আজ আমাদের স্পেশাল কাচ্চি ট্রাই করেছেন?', 
      timestamp: new Date() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));
    const botResponse = await bfcAssistChat(input, history);

    setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    setIsTyping(false);
  };

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-10 lg:right-10 z-[100] font-sans">
      {isOpen ? (
        <div className="bg-white/90 backdrop-blur-2xl w-[92vw] sm:w-[420px] h-[75vh] sm:h-[600px] rounded-[40px] shadow-[0_40px_100px_-20px_rgba(0,0,0,0.3)] flex flex-col border border-white/40 overflow-hidden animate-slide-up gpu">
          {/* Stylized Glass Header */}
          <div className="bg-gradient-to-br from-red-600 to-red-700 p-8 text-white flex justify-between items-center shadow-lg shrink-0">
            <div className="flex items-center gap-4">
               <div className="relative">
                  <div className="w-12 h-12 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center font-black text-2xl border border-white/30">B</div>
                  <span className="absolute -bottom-1 -right-1 w-4 h-4 bg-emerald-400 border-[3px] border-red-600 rounded-full shadow-lg"></span>
               </div>
              <div>
                <h3 className="font-extrabold text-lg tracking-tight">BFC Concierge</h3>
                <div className="flex items-center gap-2 mt-0.5">
                   <div className="w-1.5 h-1.5 bg-white/60 rounded-full animate-pulse"></div>
                   <p className="text-[9px] opacity-70 font-black uppercase tracking-widest">Always Ready</p>
                </div>
              </div>
            </div>
            <button 
              onClick={() => setIsOpen(false)} 
              className="w-10 h-10 hover:bg-white/10 rounded-xl transition-all flex items-center justify-center group"
            >
              <i className="fas fa-chevron-down text-lg group-hover:translate-y-0.5 transition-transform"></i>
            </button>
          </div>

          {/* Chat Flow */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 scrollbar-hide bg-gradient-to-b from-gray-50/50 to-white">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-6 py-4 rounded-[28px] text-sm font-bold leading-relaxed shadow-sm transition-all animate-slide-up ${
                  m.role === 'user' 
                  ? 'bg-gray-900 text-white rounded-br-none' 
                  : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white px-6 py-4 rounded-[24px] flex gap-2 shadow-sm border border-gray-50">
                  <span className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                  <span className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                  <span className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce"></span>
                </div>
              </div>
            )}
          </div>

          {/* Elegant Input Area */}
          <div className="p-6 bg-white border-t border-gray-50 shrink-0 flex items-center gap-3">
            <div className="flex-1 relative">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="একটি প্রশ্ন লিখুন..."
                className="w-full bg-gray-50 border-none rounded-[24px] pl-6 pr-12 py-4 outline-none focus:ring-4 focus:ring-red-50 text-sm font-bold shadow-inner"
              />
              <button 
                onClick={handleSend}
                className="absolute right-2 top-2 w-10 h-10 bg-red-600 text-white rounded-full flex items-center justify-center hover:bg-red-700 transition-all active:scale-90 shadow-lg"
              >
                <i className="fas fa-arrow-up text-sm"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
