        </button>
      )}
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Concierge", a stylish and helpful food assistant for BFC (Bangla Food Club).
        Rules:
        1. Keep greetings friendly and modern (use "Hello", "Hi", "স্বাগতম"). Avoid overly formal or specific religious greetings.
        2. Responses must be EXTREMELY CONCISE and practical (max 1-2 short sentences).
        3. Focus on menu details, recommendations, or order status.
        4. Use warm, polite, and slightly informal Bengali (use "আপনি" but keep the tone fresh).
        5. If someone asks for a recommendation, suggest popular items like Kacchi Biryani or Morog Polao.

        Example: "হ্যালো! আমাদের কাচ্চি বিরিয়ানি আজ দারুণ হয়েছে। ট্রাই করতে চান?"`,
        temperature: 0.7,
        topP: 0.9,
      },
    });

    return response.text || "দুঃখিত, আমি বুঝতে পারিনি। আবার বলবেন কি?";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "দুঃখিত, আমি এই মুহূর্তে কানেক্ট হতে পারছি না। অনুগ্রহ করে আমাদের হটলাইনে কল করুন।";
  }
};

