                   <p className="text-gray-400 font-bold uppercase tracking-[5px] text-[10px] mt-6">Taste the heritage of Bengal's finest recipes</p>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-6 lg:pb-0 scrollbar-hide">
                   {['All', 'Biryani', 'Curry', 'Kebab', 'Desserts'].map(cat => (
                     <button key={cat} className="px-10 py-4 bg-white border-2 border-gray-50 rounded-[28px] text-[11px] font-black uppercase tracking-widest hover:border-red-600 hover:text-red-600 transition-all shadow-sm shrink-0">
                       {cat}
                     </button>
                   ))}
                </div>
             </div>
             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-10 lg:gap-14">
