                ))}
             </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-4xl mx-auto animate-slide-up gpu">
             <h2 className="text-4xl lg:text-7xl font-black text-gray-800 mb-16 tracking-tighter leading-none">{language === 'BN' ? 'ব্যাগ' : 'Your Order'}</h2>
             {cart.length === 0 ? (
               <div className="text-center py-28 bg-white rounded-[60px] border-4 border-dashed border-gray-50">
                  <i className="fas fa-shopping-basket text-8xl text-gray-100 mb-10"></i>
                  <p className="text-3xl font-black text-gray-300 tracking-tight">{language === 'BN' ? 'ব্যাগটি খালি' : 'Bag is empty'}</p>
                  <Button className="mt-12 rounded-3xl px-16 py-6" onClick={()=>setView('MENU')}>{language === 'BN' ? 'খাবার দেখুন' : 'Explore Menu'}</Button>
               </div>
             ) : (
               <div className="space-y-8">
                  {cart.map((c, idx) => (
                    <div key={idx} className="bg-white p-8 lg:p-12 rounded-[50px] shadow-sm border border-gray-50 flex flex-col sm:flex-row items-center justify-between gap-10 group hover:border-red-100 transition-all">
