        )}

        {view === 'PAYMENT' && (
          <div className="max-w-4xl mx-auto animate-slide-up gpu">
             <div className="bg-white rounded-[50px] lg:rounded-[80px] p-10 lg:p-20 shadow-2xl border border-gray-100">
                <h2 className="text-4xl lg:text-6xl font-black mb-16 text-center text-gray-800 tracking-tighter leading-none">{language === 'BN' ? 'পেমেন্ট গেটওয়ে' : 'Payment Portal'}</h2>

                <div className="grid grid-cols-2 sm:grid-cols-3 gap-6 lg:gap-10 mb-16">
                   <PaymentOption id="BKASH" active={paymentMethod === 'BKASH'} onClick={()=>setPaymentMethod('BKASH')} img="https://upload.wikimedia.org/wikipedia/commons/8/8b/Bkash_logo.png" label="bKash" />
                   <PaymentOption id="NAGAD" active={paymentMethod === 'NAGAD'} onClick={()=>setPaymentMethod('NAGAD')} img="https://seeklogo.com/images/N/nagad-logo-7A70AE6460-seeklogo.com.png" label="Nagad" />
                   <PaymentOption id="ROCKET" active={paymentMethod === 'ROCKET'} onClick={()=>setPaymentMethod('ROCKET')} img="https://seeklogo.com/images/D/dutch-bangla-rocket-logo-B4D1CC458D-seeklogo.com.png" label="Rocket" />
                   <PaymentOption id="UPAY" active={paymentMethod === 'UPAY'} onClick={()=>setPaymentMethod('UPAY')} img="https://seeklogo.com/images/U/upay-logo-0D2B6005E1-seeklogo.com.png" label="Upay" />
                   <PaymentOption id="CARD" active={paymentMethod === 'CARD'} onClick={()=>setPaymentMethod('CARD')} icon="fa-credit-card" label="Card/Visa" />
                   <PaymentOption id="COD" active={paymentMethod === 'COD'} onClick={()=>setPaymentMethod('COD')} icon="fa-hand-holding-dollar" label="Cash On Delivery" />
                </div>

                {['BKASH', 'NAGAD', 'ROCKET', 'UPAY'].includes(paymentMethod) && (
                   <div className="bg-red-50/50 p-10 rounded-[40px] mb-12 animate-slide-up border border-red-100 shadow-inner space-y-6">
                      <p className="text-sm font-bold text-red-600 text-center mb-4">
                        {language === 'BN' ? 'আপনার পেমেন্ট সম্পন্ন করে নিচের বক্সে ট্রানজেকশন আইডি দিন।' : 'Send money and enter the Transaction ID below.'}
                      </p>
                      <Input label="Transaction ID" value={transactionId} onChange={(e:any)=>setTransactionId(e.target.value)} placeholder="TRX-12345678" />
                   </div>
                )}

                {paymentMethod === 'CARD' && (
                   <div className="bg-gray-50 p-10 rounded-[40px] mb-12 space-y-8 animate-slide-up border border-gray-100 shadow-inner">
                      <Input label="Card Identity Number" value={cardDetails.number} onChange={(e:any)=>setCardDetails({...cardDetails, number: e.target.value})} placeholder="0000 0000 0000 0000" />
                      <div className="grid grid-cols-2 gap-10">
                         <Input label="Expiry Date" value={cardDetails.exp} onChange={(e:any)=>setCardDetails({...cardDetails, exp: e.target.value})} placeholder="MM/YY" />
                         <Input label="CVV" value={cardDetails.cvv} onChange={(e:any)=>setCardDetails({...cardDetails, cvv: e.target.value})} type="password" placeholder="***" />
                      </div>
                   </div>
                )}

                <div className="bg-gray-900 text-white p-12 lg:p-16 rounded-[50px] mb-16 flex flex-col sm:flex-row justify-between items-center gap-10 shadow-2xl">
                   <div>
                      <p className="text-[10px] font-black text-gray-500 uppercase tracking-[5px] mb-2">{language === 'BN' ? 'সর্বমোট প্রদেয়' : 'Total Net Payable'}</p>
                      <h4 className="text-5xl lg:text-7xl font-black text-red-600 tracking-tighter">৳{subTotal + 65}</h4>
                   </div>
                   <div className="text-center sm:text-right">
                      <p className="text-[10px] font-bold text-gray-500 uppercase tracking-widest leading-loose">Including VAT &<br/>Logistic Service Fee</p>
                   </div>
                </div>

                <Button fullWidth size="lg" className="rounded-[35px] py-10 text-3xl shadow-2xl" disabled={isProcessing} onClick={finalizeOrder}>
                   {isProcessing ? (
                     <span className="flex items-center gap-6">
                       <i className="fas fa-spinner fa-spin"></i> {language === 'BN' ? 'ভেরিফাই হচ্ছে...' : 'Authorizing...'}
                     </span>
                   ) : (language === 'BN' ? 'অর্ডার সম্পন্ন করুন' : 'Confirm Order')}
                </Button>
             </div>
          </div>
        )}

        {view === 'TRACKING' && (
          <div className="max-w-3xl mx-auto animate-slide-up gpu py-10">
             <div className="bg-white rounded-[60px] lg:rounded-[100px] p-12 lg:p-28 shadow-2xl border border-gray-100 text-center relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-4 bg-red-600"></div>
                <div className="w-28 h-28 lg:w-40 lg:h-40 bg-green-50 text-green-600 rounded-[50px] flex items-center justify-center mx-auto mb-16 shadow-2xl border-[6px] border-white">
                   <i className="fas fa-rocket text-5xl lg:text-7xl animate-pulse"></i>
                </div>
                <h2 className="text-5xl lg:text-7xl font-black text-gray-800 mb-6 tracking-tighter leading-none">{language === 'BN' ? 'অর্ডার ট্র্যাকিং' : 'Mission Status'}</h2>
                <p className="text-gray-400 font-black mb-20 tracking-[8px] uppercase text-[12px]">Vector ID: {orderCode || 'BFC-882901'}</p>
                <div className="space-y-20 text-left relative max-w-[380px] mx-auto mb-20">
                   <div className="absolute left-[31px] top-10 bottom-10 w-2 bg-gray-50 rounded-full"></div>
                   <TrackerNode active icon="fa-clipboard-check" title={language === 'BN' ? 'অর্ডার গৃহীত' : 'Confirmed'} desc="Confirmed at BFC HQ" />
                   <TrackerNode active icon="fa-fire-burner" title={language === 'BN' ? 'প্রস্তুত হচ্ছে' : 'Production'} desc="Crafting the flavor palette" />
                   <TrackerNode icon="fa-rocket" title={language === 'BN' ? 'ডেলিভারি চলছে' : 'Dispatched'} desc="Logistic partner on path" />
                   <TrackerNode icon="fa-flag-checkered" title={language === 'BN' ? 'পৌঁছে গেছে' : 'Fulfillment'} desc="Arrival at target coordinates" />
                </div>
                <Button variant="outline" className="rounded-[30px] w-full lg:w-auto px-20 py-6 text-xl" onClick={()=>setView('HOME')}>{language === 'BN' ? 'হোমে ফিরে যান' : 'Back to Control'}</Button>
             </div>
          </div>
        )}
      </main>

      <ChatBot />

      <div className="lg:hidden fixed bottom-0 w-full bg-white/90 backdrop-blur-3xl px-12 py-10 flex justify-between items-center z-50 border-t border-gray-50 shadow-[0_-20px_50px_rgba(0,0,0,0.08)] rounded-t-[60px]">
         <button onClick={()=>setView('HOME')} className={view === 'HOME' ? 'text-red-600 scale-150' : 'text-gray-300'}><i className="fas fa-home text-2xl"></i></button>
         <button onClick={()=>setView('MENU')} className={view === 'MENU' ? 'text-red-600 scale-150' : 'text-gray-300'}><i className="fas fa-book-open text-2xl"></i></button>
         <button onClick={()=>setView('CART')} className={view === 'CART' ? 'text-red-600 scale-150' : 'text-gray-300'}><i className="fas fa-shopping-basket text-2xl"></i></button>
         <button onClick={()=>currentUser ? setView('PROFILE') : setView('LOGIN')} className={(view === 'PROFILE' || view === 'REGISTER' || view === 'LOGIN') ? 'text-red-600 scale-150' : 'text-gray-300'}><i className="fas fa-user-astronaut text-2xl"></i></button>
      </div>
    </div>
  );
};

