    <div>
      <h4 className={`text-3xl font-black transition-colors leading-none ${active ? 'text-gray-800' : 'text-gray-100'}`}>{title}</h4>
      <p className="text-[12px] font-bold text-gray-400 mt-2">{desc}</p>
