export default App;

import React, { useState, useEffect, useRef } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<Array<{ item: MenuItem, qty: number }>>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE' | 'PAYMENT' | 'REGISTER'>('HOME');
  const [language, setLanguage] = useState<'EN' | 'BN'>('BN');

  const [formName, setFormName] = useState('');
  const [formEmail, setFormEmail] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [formPass, setFormPass] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'ROCKET' | 'UPAY' | 'CARD' | 'COD'>('BKASH');
  const [isProcessing, setIsProcessing] = useState(false);
  const [orderCode, setOrderCode] = useState('');
  const [cardDetails, setCardDetails] = useState({ number: '', exp: '', cvv: '' });
  const [transactionId, setTransactionId] = useState('');

  // Load user from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('bfc_user_profile');
    if (saved) {
      const parsed = JSON.parse(saved);
      setCurrentUser(parsed);
      setFormName(parsed.name || '');
      setFormPhone(parsed.phone || '');
      setFormEmail(parsed.email || '');
    }
  }, []);

  // Persist user whenever it changes
  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('bfc_user_profile', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('bfc_user_profile');
    }
  }, [currentUser]);

  const handleAuth = (isRegistering: boolean = false) => {
    // Admin check
    if (formEmail === 'admin@bfc.com' && formPass === 'admin123') {
      const admin: User = {
        id: 'ADM-BFC-01', name: 'BFC Super Admin', email: 'admin@bfc.com',
        phone: '01700000000', role: UserRole.ADMIN, loyaltyPoints: 50000,
        tier: 'PLATINUM', wishlist: [], referralCode: 'BFC-MASTER'
      };
      setCurrentUser(admin);
      setFormName(admin.name);
      setFormPhone(admin.phone);
      setView('HOME');
      return;
    }

    if (!formEmail || !formPass || (isRegistering && (!formName || !formPhone))) {
      alert(language === 'BN' ? 'সব তথ্য সঠিক ভাবে পূরণ করুন' : 'Please fill all information correctly');
      return;
    }

    // Default Customer Logic
    const newUser: User = {
      id: 'U-' + Date.now(),
      name: formName || (language === 'BN' ? 'নতুন মেম্বার' : 'New Member'),
      email: formEmail,
      phone: formPhone || '01XXXXXXXXX',
      role: UserRole.CUSTOMER,
      loyaltyPoints: 0,
      tier: 'SILVER',
      wishlist: [],
      referralCode: 'BFC-' + Math.random().toString(36).substring(7).toUpperCase(),
      profileImage: currentUser?.profileImage // Carry over if exists
    };
    setCurrentUser(newUser);
    setView('HOME');
  };

  const handleUpdateProfile = () => {
    if (currentUser) {
      const updatedUser = { ...currentUser, name: formName, phone: formPhone };
      setCurrentUser(updatedUser);
      alert(language === 'BN' ? 'প্রোফাইল তথ্য সফলভাবে আপডেট হয়েছে' : 'Profile successfully updated');
    }
  };

  const handleProfileImage = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && currentUser) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        setCurrentUser({ ...currentUser, profileImage: base64String });
      };
      reader.readAsDataURL(file);
    }
  };

  const finalizeOrder = () => {
    if (paymentMethod === 'CARD' && (!cardDetails.number || !cardDetails.exp || !cardDetails.cvv)) {
      alert(language === 'BN' ? 'কার্ডের তথ্য সম্পূর্ণ দিন' : 'Please provide full card details');
      return;
    }
    if (['BKASH', 'NAGAD', 'ROCKET', 'UPAY'].includes(paymentMethod) && !transactionId) {
      alert(language === 'BN' ? 'ট্রানজেকশন আইডি প্রদান করুন' : 'Please provide Transaction ID');
      return;
    }

    setIsProcessing(true);
    setTimeout(() => {
      setIsProcessing(false);
      setOrderCode('BFC-' + Math.floor(100000 + Math.random() * 900000));
      setCart([]);
      setView('TRACKING');
    }, 2500);
  };

  const subTotal = cart.reduce((acc, curr) => acc + (curr.item.price * curr.qty), 0);

  if (view === 'ADMIN' && currentUser && (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.MANAGER)) {
