import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

export const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { 
      role: 'model', 
      text: 'Hi! 👋 BFC Concierge here. Feeling hungry? I can recommend our legendary Kacchi or find the perfect dessert for you. What are we craving today?', 
      timestamp: new Date() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim()) return;
    const userMsg: ChatMessage = { role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));
    const botResponse = await bfcAssistChat(input, history);

    setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    setIsTyping(false);
  };

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-10 lg:right-10 z-[100] font-sans">
      {isOpen ? (
        <div className="bg-white/95 backdrop-blur-3xl w-[92vw] sm:w-[420px] h-[70vh] sm:h-[650px] rounded-[48px] shadow-[0_50px_100px_-20px_rgba(220,38,38,0.25)] flex flex-col border border-white/60 overflow-hidden animate-slide-up gpu">
          {/* Premium Glass Header */}
          <div className="bg-gradient-to-br from-gray-900 via-gray-800 to-black p-8 text-white flex justify-between items-center relative overflow-hidden shrink-0">
            <div className="absolute top-0 right-0 w-32 h-32 bg-red-600/20 rounded-full -mr-16 -mt-16 blur-3xl"></div>
            <div className="flex items-center gap-5 relative z-10">
               <div className="relative">
                  <div className="w-14 h-14 bg-white/10 backdrop-blur-xl rounded-[22px] flex items-center justify-center font-black text-2xl border border-white/20 shadow-inner">
                    <span className="text-red-600">B</span>
                  </div>
                  <span className="absolute -bottom-1 -right-1 w-4 h-4 bg-emerald-400 border-[3px] border-gray-900 rounded-full shadow-lg"></span>
               </div>
              <div>
                <h3 className="font-black text-xl tracking-tighter leading-none">BFC Concierge</h3>
                <div className="flex items-center gap-2 mt-1.5">
                   <div className="w-1.5 h-1.5 bg-emerald-400 rounded-full animate-pulse"></div>
                   <p className="text-[10px] opacity-60 font-black uppercase tracking-[2px]">AI Protocol Active</p>
                </div>
              </div>
            </div>
            <button 
              onClick={() => setIsOpen(false)} 
              className="w-12 h-12 bg-white/5 hover:bg-white/10 rounded-2xl transition-all flex items-center justify-center group border border-white/10"
            >
              <i className="fas fa-xmark text-lg group-hover:rotate-90 transition-transform"></i>
            </button>
          </div>

          {/* Chat Flow with Modern Bubbles */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-6 scrollbar-hide bg-gradient-to-b from-gray-50/50 to-white/30">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                <div className={`max-w-[88%] px-6 py-4 rounded-[30px] text-[14px] font-bold leading-relaxed shadow-sm transition-all border ${
                  m.role === 'user' 
                  ? 'bg-red-600 text-white border-red-500 rounded-br-none' 
                  : 'bg-white text-gray-800 border-gray-100 rounded-tl-none'
                }`}>
                  {m.text}
                  <div className={`text-[9px] mt-2 opacity-40 font-black tracking-widest ${m.role === 'user' ? 'text-white' : 'text-gray-400'}`}>
                    {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </div>
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white px-6 py-5 rounded-[24px] rounded-tl-none flex gap-2 shadow-sm border border-gray-50">
                  <span className="w-2 h-2 bg-red-600 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                  <span className="w-2 h-2 bg-red-600 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                  <span className="w-2 h-2 bg-red-600 rounded-full animate-bounce"></span>
                </div>
              </div>
            )}
          </div>

          {/* Floating Input Capsule */}
          <div className="p-8 bg-white/50 backdrop-blur-md shrink-0">
            <div className="flex items-center gap-3 bg-white p-2 pl-6 rounded-[32px] shadow-[0_15px_40px_-10px_rgba(0,0,0,0.08)] border border-gray-100 ring-4 ring-gray-50/50 group focus-within:ring-red-50 transition-all">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask BFC Assist..."
                className="flex-1 bg-transparent border-none py-3 outline-none text-sm font-bold text-gray-800 placeholder:text-gray-300"
              />
              <button 
                onClick={handleSend}
                className="w-12 h-12 bg-red-600 text-white rounded-[24px] flex items-center justify-center hover:bg-red-700 transition-all active:scale-90 shadow-xl shadow-red-200"
