          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-gray-900 text-white w-18 h-18 lg:w-22 lg:h-22 rounded-[35px] shadow-[0_25px_60px_-15px_rgba(0,0,0,0.4)] flex items-center justify-center hover:scale-110 active:scale-95 transition-all duration-500 group relative gpu border-2 border-white/10"
