          </div>
          <span className="absolute -top-1 -right-1 w-6 h-6 bg-red-600 border-[4px] border-white rounded-full shadow-lg flex items-center justify-center">
            <span className="w-1.5 h-1.5 bg-white rounded-full animate-pulse"></span>
          </span>
        </button>
      )}
