  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  };

  // Load user from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('bfc_user_profile');
    if (saved) {
      const parsed = JSON.parse(saved);
      setCurrentUser(parsed);
      setFormName(parsed.name || '');
      setFormPhone(parsed.phone || '');
      setFormEmail(parsed.email || '');
    }
  }, []);

  useEffect(() => {
    if (currentUser) {
      setFormName(prev => prev || currentUser.name);
      setFormPhone(prev => prev || currentUser.phone);
      setFormEmail(prev => prev || currentUser.email);
    }
  }, [currentUser?.id]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('bfc_user_profile', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('bfc_user_profile');
    }
  }, [currentUser]);

  const validateAuth = (isRegistering: boolean) => {
    const newErrors: Record<string, string> = {};
    if (!formEmail.includes('@')) newErrors.email = language === 'BN' ? 'সঠিক ইমেইল দিন' : 'Enter valid email';
    if (formPass.length < 6) newErrors.pass = language === 'BN' ? 'কমপক্ষে ৬ অক্ষরের পাসওয়ার্ড দিন' : 'Min 6 characters';

    if (isRegistering) {
      if (!formName.trim()) newErrors.name = language === 'BN' ? 'নাম প্রয়োজন' : 'Name required';
      if (!/^\d{11}$/.test(formPhone)) newErrors.phone = language === 'BN' ? '১১ ডিজিটের মোবাইল নম্বর দিন' : 'Enter 11 digit phone';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleAuth = (isRegistering: boolean = false) => {
    if (formEmail === 'admin@bfc.com' && formPass === 'admin123') {
      const admin: User = {
        id: 'ADM-BFC-01', name: 'BFC Super Admin', email: 'admin@bfc.com',
        phone: '01700000000', role: UserRole.ADMIN, loyaltyPoints: 50000,
        tier: 'PLATINUM', wishlist: [], referralCode: 'BFC-MASTER'
      };
      setCurrentUser(admin);
      setFormName(admin.name);
      setFormPhone(admin.phone);
      showToast(language === 'BN' ? 'অ্যাডমিন হিসেবে লগইন সফল' : 'Admin Login Successful', 'success');
      setView('HOME');
      return;
    }

    if (!validateAuth(isRegistering)) {
      showToast(language === 'BN' ? 'অনুগ্রহ করে সঠিক তথ্য প্রদান করুন' : 'Please provide valid information', 'error');
      return;
    }

    const newUser: User = {
      id: 'U-' + Date.now(),
      name: formName || (language === 'BN' ? 'নতুন মেম্বার' : 'New Member'),
      email: formEmail,
      phone: formPhone || '01XXXXXXXXX',
      role: UserRole.CUSTOMER,
      loyaltyPoints: 0,
      tier: 'SILVER',
      wishlist: [],
      referralCode: 'BFC-' + Math.random().toString(36).substring(7).toUpperCase(),
      profileImage: currentUser?.profileImage
    };
    setCurrentUser(newUser);
    showToast(language === 'BN' ? 'স্বাগতম!' : 'Welcome back!', 'success');
    setView('HOME');
    setErrors({});
  };

  const handleUpdateProfile = () => {
    if (currentUser) {
      if (!formName.trim() || !/^\d{11}$/.test(formPhone)) {
        showToast(language === 'BN' ? 'সঠিক নাম ও ফোন নম্বর দিন' : 'Provide valid name and phone', 'error');
        return;
      }
      const updatedUser = { ...currentUser, name: formName, phone: formPhone };
      setCurrentUser(updatedUser);
      showToast(language === 'BN' ? 'প্রোফাইল আপডেট হয়েছে' : 'Profile Updated', 'success');
    }
  };

  const handleProfileImage = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && currentUser) {
      if (file.size > 2 * 1024 * 1024) {
        showToast(language === 'BN' ? 'ছবি ২ মেগাবাইটের কম হতে হবে' : 'Image must be less than 2MB', 'error');
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        setCurrentUser({ ...currentUser, profileImage: base64String });
        showToast(language === 'BN' ? 'প্রোফাইল ছবি সেভ হয়েছে' : 'Profile image saved', 'success');
      };
      reader.readAsDataURL(file);
    }
  };

  const finalizeOrder = () => {
    setErrors({});
    if (paymentMethod === 'CARD') {
      const cardErrors: Record<string, string> = {};
      if (cardDetails.number.replace(/\s/g, '').length < 16) cardErrors.cardNumber = language === 'BN' ? 'সঠিক কার্ড নম্বর দিন' : 'Invalid card number';
      if (!/^\d{2}\/\d{2}$/.test(cardDetails.exp)) cardErrors.cardExp = language === 'BN' ? 'সঠিক এক্সপায়ারি ডেট দিন' : 'Invalid expiry';
      if (cardDetails.cvv.length < 3) cardErrors.cardCvv = language === 'BN' ? 'সঠিক CVV দিন' : 'Invalid CVV';
      if (!cardDetails.name.trim()) cardErrors.cardName = language === 'BN' ? 'নাম দিন' : 'Name required';

      if (Object.keys(cardErrors).length > 0) {
        setErrors(cardErrors);
        showToast(language === 'BN' ? 'কার্ডের তথ্য চেক করুন' : 'Check card details', 'error');
        return;
      }
    }

    if (['BKASH', 'NAGAD', 'ROCKET', 'UPAY'].includes(paymentMethod) && !transactionId) {
      setErrors({ trx: language === 'BN' ? 'ট্রানজেকশন আইডি দিন' : 'Trx ID required' });
      showToast(language === 'BN' ? 'পেমেন্ট আইডি প্রদান করুন' : 'Provide Payment ID', 'error');
      return;
    }

    setIsProcessing(true);
    setTimeout(() => {
      setIsProcessing(false);
      setOrderCode('BFC-' + Math.floor(100000 + Math.random() * 900000));
      setCart([]);
      setView('TRACKING');
      showToast(language === 'BN' ? 'অর্ডার সফলভাবে সম্পন্ন হয়েছে!' : 'Order Placed Successfully!', 'success');
    }, 2500);
  };

  const subTotal = cart.reduce((acc, curr) => acc + (curr.item.price * curr.qty), 0);
  const deliveryCharge = 65;
  const tax = Math.round(subTotal * 0.05);
  const grandTotal = subTotal + deliveryCharge + tax;

  const getCardIcon = (number: string) => {
    if (number.startsWith('4')) return 'fa-cc-visa text-blue-600';
    if (number.startsWith('5')) return 'fa-cc-mastercard text-orange-600';
    if (number.startsWith('3')) return 'fa-cc-amex text-cyan-600';
    return 'fa-credit-card text-gray-300';
  };

  if (view === 'ADMIN' && currentUser && (currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.MANAGER)) {
    return <AdminPanel userRole={currentUser.role} onLogout={() => { setCurrentUser(null); setView('HOME'); }} />;
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 overflow-x-hidden selection:bg-red-100">
      {/* Toast Notification Container */}
      <div className="fixed top-8 right-8 z-[200] space-y-4 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className={`pointer-events-auto flex items-center gap-4 px-8 py-5 rounded-3xl shadow-2xl border bg-white animate-slide-up ${
            t.type === 'success' ? 'border-green-100 text-green-700' : 
            t.type === 'error' ? 'border-red-100 text-red-600' : 'border-gray-100 text-gray-800'
          }`}>
            <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm ${
              t.type === 'success' ? 'bg-green-50' : 
              t.type === 'error' ? 'bg-red-50' : 'bg-gray-50'
            }`}>
              <i className={`fas ${t.type === 'success' ? 'fa-check' : t.type === 'error' ? 'fa-xmark' : 'fa-info'}`}></i>
            </div>
            <p className="font-black text-[12px] uppercase tracking-wider">{t.message}</p>
          </div>
        ))}
      </div>

      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-4 lg:px-14 py-4 flex justify-between items-center gpu">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 lg:w-14 lg:h-14 bg-red-600 rounded-[18px] flex items-center justify-center text-white text-xl lg:text-3xl font-black shadow-xl group-hover:rotate-3 transition-all duration-300">B</div>
          <h1 className="text-xl lg:text-3xl font-black text-red-600 tracking-tighter hidden xs:block">BFC</h1>
        </div>

        <div className="hidden lg:flex items-center gap-12 text-[11px] font-black uppercase tracking-[3px] text-gray-400">
          <button onClick={()=>setView('HOME')} className={view === 'HOME' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'হোম' : 'Home'}</button>
          <button onClick={()=>setView('MENU')} className={view === 'MENU' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'মেনু' : 'Menu'}</button>
          <button onClick={()=>setView('TRACKING')} className={view === 'TRACKING' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'ট্র্যাকিং' : 'Tracking'}</button>
          <button onClick={()=>setLanguage(language === 'BN' ? 'EN' : 'BN')} className="text-gray-900 border-x px-4 border-gray-100">{language}</button>
        </div>

        <div className="flex items-center gap-3 lg:gap-6">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 lg:w-14 lg:h-14 bg-gray-50 text-gray-800 rounded-2xl flex items-center justify-center shadow-inner hover:bg-red-50 transition-all group">
            <i className="fas fa-shopping-basket text-lg group-hover:-translate-y-0.5 transition-transform"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[9px] w-6 h-6 rounded-full flex items-center justify-center ring-4 ring-white font-black animate-pulse">{cart.length}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 lg:w-14 lg:h-14 rounded-2xl border-2 border-white overflow-hidden shadow-xl hover:scale-105 transition-all bg-red-600 ring-2 ring-red-100 ring-offset-2">
              {currentUser.profileImage ? (
                <img src={currentUser.profileImage} className="w-full h-full object-cover" alt="Profile" />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-white font-black">{currentUser.name.charAt(0)}</div>
              )}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl px-6 lg:px-10 py-3 lg:py-4" onClick={() => setView('LOGIN')}>{language === 'BN' ? 'লগইন' : 'Login'}</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 lg:px-10 py-6 lg:py-12">
        {view === 'HOME' && (
          <div className="animate-slide-up gpu">
            <header className="relative h-[400px] lg:h-[650px] rounded-[40px] lg:rounded-[80px] overflow-hidden shadow-2xl mb-16 lg:mb-24 group">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover transition-transform duration-[5s] group-hover:scale-105" />
               <div className="absolute inset-0 bg-gradient-to-r from-black/90 via-black/40 to-transparent flex flex-col justify-center px-8 lg:px-24">
                  <span className="text-red-600 font-black uppercase tracking-[6px] text-[10px] mb-4">The Premium Taste of Dhaka</span>
                  <h2 className="text-4xl lg:text-[110px] font-black text-white leading-[0.9] mb-10 tracking-tighter">
                    {language === 'BN' ? 'আসল স্বাদ' : 'Real Taste'}<br/>
                    <span className="text-red-600">{language === 'BN' ? 'সেরা খাবার' : 'Best Food'}</span>
                  </h2>
                  <div className="flex gap-4 lg:gap-8">
                    <Button size="lg" className="rounded-[24px] px-10 lg:px-16 py-5 lg:py-8 text-lg" onClick={() => setView('MENU')}>{language === 'BN' ? 'অর্ডার করুন' : 'Order Now'}</Button>
                  </div>
               </div>
            </header>

            <div className="flex justify-between items-end mb-12">
               <h3 className="text-3xl lg:text-5xl font-black text-gray-800 tracking-tighter">{language === 'BN' ? 'সেরা মেনু' : 'Premium Flavors'}</h3>
               <button onClick={()=>setView('MENU')} className="text-red-600 font-black text-sm hover:underline">{language === 'BN' ? 'সব দেখুন' : 'Explore All'}</button>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8 lg:gap-12">
               {MOCK_MENU.slice(0, 4).map(item => (
                 <ProductCard key={item.id} item={item} language={language} onAdd={(item: any) => {
                   setCart([...cart, {item, qty:1}]);
                   showToast(language === 'BN' ? 'ব্যাগ এ যোগ করা হয়েছে' : 'Added to Bag', 'success');
                 }} />
               ))}
            </div>
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto animate-slide-up bg-white p-10 lg:p-16 rounded-[40px] lg:rounded-[60px] shadow-2xl border border-gray-100 mt-10">
             <h2 className="text-3xl lg:text-4xl font-black text-center mb-12 text-gray-800 tracking-tighter leading-none">{language === 'BN' ? 'লগইন করুন' : 'Identity Portal'}</h2>
             <div className="space-y-6">
                <Input label={language === 'BN' ? 'ইমেইল' : 'Email Node'} error={errors.email} value={formEmail} onChange={(e:any)=>setFormEmail(e.target.value)} placeholder="user@bfc.com" />
                <Input label={language === 'BN' ? 'পাসওয়ার্ড' : 'Secure Key'} error={errors.pass} type="password" value={formPass} onChange={(e:any)=>setFormPass(e.target.value)} placeholder="******" />
                <Button fullWidth size="lg" className="rounded-3xl py-6 mt-6 shadow-xl shadow-red-100" onClick={() => handleAuth(false)}>{language === 'BN' ? 'প্রবেশ করুন' : 'Sync Identity'}</Button>
                <div className="flex justify-center mt-10">
                  <span className="cursor-pointer text-gray-400 font-black uppercase text-[10px] tracking-widest hover:text-red-600" onClick={()=>{setView('REGISTER'); setErrors({});}}>{language === 'BN' ? 'নতুন একাউন্ট খুলুন' : 'No Access? Register Now'}</span>
                </div>
             </div>
          </div>
        )}

        {view === 'REGISTER' && (
          <div className="max-w-md mx-auto animate-slide-up bg-white p-10 lg:p-16 rounded-[40px] lg:rounded-[60px] shadow-2xl border border-gray-100 mt-10">
             <h2 className="text-3xl lg:text-4xl font-black text-center mb-12 text-gray-800 tracking-tighter leading-none">{language === 'BN' ? 'নিবন্ধন করুন' : 'Join BFC'}</h2>
             <div className="space-y-6">
                <Input label={language === 'BN' ? 'পুরো নাম' : 'Identity Name'} error={errors.name} value={formName} onChange={(e:any)=>setFormName(e.target.value)} placeholder="Rahim Ahmed" />
                <Input label={language === 'BN' ? 'ফোন নাম্বার' : 'Contact Number'} error={errors.phone} value={formPhone} onChange={(e:any)=>setFormPhone(e.target.value)} placeholder="0171XXXXXXX" />
                <Input label={language === 'BN' ? 'ইমেইল' : 'Email Node'} error={errors.email} value={formEmail} onChange={(e:any)=>setFormEmail(e.target.value)} placeholder="rahim@example.com" />
                <Input label={language === 'BN' ? 'পাসওয়ার্ড' : 'Secure Key'} error={errors.pass} type="password" value={formPass} onChange={(e:any)=>setFormPass(e.target.value)} placeholder="******" />
                <Button fullWidth size="lg" className="rounded-3xl py-6 mt-6 shadow-xl shadow-red-100" onClick={() => handleAuth(true)}>{language === 'BN' ? 'রেজিস্ট্রেশন করুন' : 'Create Identity'}</Button>
                <div className="flex justify-center mt-10">
                  <span className="cursor-pointer text-gray-400 font-black uppercase text-[10px] tracking-widest hover:text-red-600" onClick={()=>{setView('LOGIN'); setErrors({});}}>{language === 'BN' ? 'ইতিমধ্যেই মেম্বার?' : 'Already Registered? Login'}</span>
                </div>
             </div>
          </div>
        )}

        {view === 'PAYMENT' && (
          <div className="max-w-6xl mx-auto animate-slide-up gpu">
             <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

                <div className="lg:col-span-7 bg-white rounded-[50px] lg:rounded-[70px] p-8 lg:p-14 shadow-2xl border border-gray-50 relative overflow-hidden">
                   <div className="absolute top-0 left-0 w-2 h-full bg-red-600"></div>

                   <h2 className="text-3xl lg:text-4xl font-black mb-12 text-gray-800 tracking-tighter leading-none flex items-center gap-5">
                      <div className="w-12 h-12 bg-gray-900 text-red-600 rounded-2xl flex items-center justify-center text-xl shadow-xl"><i className="fas fa-shield-check"></i></div>
                      {language === 'BN' ? 'সুরক্ষিত পেমেন্ট' : 'Secure Checkout'}
                   </h2>

                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-[4px] mb-8 ml-2">Choose Method</p>
                   <div className="grid grid-cols-2 sm:grid-cols-3 gap-5 lg:gap-8 mb-12">
                      <PaymentOption id="BKASH" active={paymentMethod === 'BKASH'} onClick={()=>setPaymentMethod('BKASH')} img="https://www.logo.wine/a/logo/Bkash/Bkash-Logo.wine.svg" label="bKash" />
                      <PaymentOption id="NAGAD" active={paymentMethod === 'NAGAD'} onClick={()=>setPaymentMethod('NAGAD')} img="https://seeklogo.com/images/N/nagad-logo-7A70AE6460-seeklogo.com.png" label="Nagad" />
                      <PaymentOption id="ROCKET" active={paymentMethod === 'ROCKET'} onClick={()=>setPaymentMethod('ROCKET')} img="https://seeklogo.com/images/D/dutch-bangla-rocket-logo-B4D1CC458D-seeklogo.com.png" label="Rocket" />
                      <PaymentOption id="UPAY" active={paymentMethod === 'UPAY'} onClick={()=>setPaymentMethod('UPAY')} img="https://seeklogo.com/images/U/upay-logo-0D2B6005E1-seeklogo.com.png" label="Upay" />
                      <PaymentOption id="CARD" active={paymentMethod === 'CARD'} onClick={()=>setPaymentMethod('CARD')} icon="fa-credit-card" label="Card/Visa" />
                      <PaymentOption id="COD" active={paymentMethod === 'COD'} onClick={()=>setPaymentMethod('COD')} icon="fa-wallet" label="Cash On Delivery" />
                   </div>

                   <div className="min-h-[280px]">
                      {['BKASH', 'NAGAD', 'ROCKET', 'UPAY'].includes(paymentMethod) && (
                         <div className="bg-[#F8FAFC] p-10 lg:p-12 rounded-[45px] animate-slide-up border border-gray-100 shadow-inner group">
                            <div className="flex items-center gap-8 mb-10 bg-white p-8 rounded-3xl border border-gray-50 shadow-sm">
                               <div className="w-16 h-16 bg-red-50 text-red-600 rounded-[24px] flex items-center justify-center text-2xl ring-8 ring-red-50/50"><i className="fas fa-mobile-retro"></i></div>
                               <div>
                                  <h4 className="font-black text-gray-800 text-lg tracking-tight mb-1">{paymentMethod} Integration</h4>
                                  <p className="text-[11px] font-bold text-gray-400 leading-relaxed uppercase tracking-wider">
                                     {language === 'BN' ? 'পেমেন্ট সম্পন্ন করে নিচের বক্সে ট্রানজেকশন আইডি প্রদান করুন' : 'Provide Transaction ID after sending payment to our merchant.'}
                                  </p>
                               </div>
                            </div>
                            <div className="relative">
                               <Input 
                                  label="Transaction Reference ID" 
                                  error={errors.trx}
                                  value={transactionId} 
                                  onChange={(e:any)=>setTransactionId(e.target.value)} 
                                  placeholder="TRX-XXXX-XXXX" 
                                  className="bg-white"
                                />
                            </div>
                         </div>
                      )}

                      {paymentMethod === 'CARD' && (
                         <div className="bg-[#F8FAFC] p-10 lg:p-12 rounded-[45px] space-y-10 animate-slide-up border border-gray-100 shadow-inner">
                            <div className="grid grid-cols-1 md:grid-cols-12 gap-10">
                               <div className="md:col-span-12">
                                  <Input 
                                     label="Cardholder Identity" 
                                     error={errors.cardName}
                                     value={cardDetails.name} 
                                     onChange={(e:any)=>setCardDetails({...cardDetails, name: e.target.value})} 
                                     placeholder="RAHIM AHMED" 
                                     className="bg-white"
                                  />
                               </div>
                               <div className="md:col-span-12 relative group">
                                  <Input 
                                     label="Primary Card Vector" 
                                     error={errors.cardNumber}
                                     value={cardDetails.number} 
                                     onChange={(e:any)=>setCardDetails({...cardDetails, number: e.target.value.replace(/\s?/g, '').replace(/(\d{4})/g, '$1 ').trim()})} 
                                     placeholder="0000 0000 0000 0000" 
                                     className="bg-white pr-20"
                                     maxLength={19}
                                  />
                                  <div className="absolute right-8 bottom-6 flex items-center gap-3">
                                     <i className={`fab ${getCardIcon(cardDetails.number)} text-4xl transition-all duration-500`}></i>
                                  </div>
                               </div>
                               <div className="md:col-span-7">
                                  <Input label="Expiry (MM/YY)" error={errors.cardExp} value={cardDetails.exp} onChange={(e:any)=>setCardDetails({...cardDetails, exp: e.target.value})} placeholder="12/26" className="bg-white" />
                               </div>
                               <div className="md:col-span-5">
                                  <Input label="Secure CVV" error={errors.cardCvv} value={cardDetails.cvv} onChange={(e:any)=>setCardDetails({...cardDetails, cvv: e.target.value})} type="password" placeholder="***" maxLength={3} className="bg-white" />
                               </div>
                            </div>
                         </div>
                      )}

                      {paymentMethod === 'COD' && (
