                    </Button>
                  )}
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 2xl:grid-cols-3 gap-10">
                  {menuItems.map(item => (
                    <div key={item.id} className="bg-white p-10 rounded-[50px] shadow-sm border border-gray-100 flex flex-col hover:shadow-2xl transition-all duration-500 group relative">
                       <div className="flex items-center gap-8 mb-10">
                          <img src={item.image} className="w-28 h-28 rounded-[35px] object-cover shadow-2xl group-hover:scale-105 transition-transform border-4 border-white" alt={item.name} />
                          <div className="flex-1 min-w-0">
                             <div className="flex justify-between items-start gap-2">
                                <h4 className="font-black text-xl text-gray-800 truncate tracking-tighter">{item.name}</h4>
                                {userRole === UserRole.ADMIN && (
                                  <button onClick={()=>deleteMenuItem(item.id)} className="w-8 h-8 rounded-full flex items-center justify-center text-gray-200 hover:text-red-600 transition-all">
                                    <i className="fas fa-trash-can text-xs"></i>
                                  </button>
                                )}
                             </div>
                             <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1.5 block">{item.category}</span>
                             <p className="text-lg font-black text-red-600 mt-3 tracking-tighter">৳{item.price}</p>
                          </div>
                       </div>

                       <div className="mt-auto space-y-8">
                          <div className="flex justify-between items-end px-2">
                             <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Realtime Stock</p>
                             <p className={`text-3xl font-black tracking-tighter ${item.stock < 10 ? 'text-red-600' : 'text-gray-900'}`}>{item.stock}</p>
                          </div>
                          <div className="flex gap-4">
                             <button onClick={() => updateStock(item.id, -1)} className="flex-1 bg-gray-50 text-gray-400 py-5 rounded-2xl font-black hover:bg-red-50 hover:text-red-600 transition-all shadow-inner border border-gray-50"><i className="fas fa-minus"></i></button>
                             <button onClick={() => updateStock(item.id, 1)} className="flex-1 bg-gray-900 text-white py-5 rounded-2xl font-black hover:bg-red-600 transition-all shadow-xl"><i className="fas fa-plus"></i></button>
                          </div>
                       </div>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {activeTab === 'reports' && canAccess('reports') && (
            <div className="space-y-12">
               <h2 className="text-4xl font-black text-gray-800 tracking-tighter">Financial Ledger</h2>
               <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                  <div className="bg-white p-12 rounded-[60px] shadow-sm border border-gray-100 flex flex-col justify-between group min-h-[500px]">
                     <div className="grid grid-cols-2 gap-6 lg:gap-10">
                        <MetricBox label="Mean Order Value" value="৳1,280" />
                        <MetricBox label="Efficiency Ratio" value={`${metrics.margin}%`} color="text-red-600" />
                        <MetricBox label="Asset Intake" value="৳88,500" />
                        <MetricBox label="Growth Vector" value="+4.2%" color="text-green-600" />
                     </div>
                  </div>
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

