import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist", an advanced AI concierge for BFC (Bangla Food Club).

        Tone: Stylish, modern, helpful, and culturally aware of Bangladesh.
        Language: Use a mix of warm Bengali (Shuddho) and professional English where appropriate.

        Guidelines:
        1. Keep greetings fresh and neutral (Hello/স্বাগতম).
        2. Responses must be EXTREMELY CONCISE (max 2 sentences).
        3. Prioritize food recommendations (Kacchi Biryani, Morog Polao, Beef Rezala) and menu queries.
        4. If asked about order status, remind them to check the "Tracking" tab.

        Example: "স্বাগতম! বিএফসিতে আজ আমাদের কাচ্চি বিরিয়ানি এবং শিক কাবাব স্পেশাল। ট্রাই করবেন?"`,
        temperature: 0.7,
        topP: 0.9,
      },
    });

    return response.text || "দুঃখিত, আমি এই মুহূর্তে ঠিক বুঝতে পারিনি। দয়া করে আবার বলবেন কি?";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "দুঃখিত, কানেকশনে সমস্যা হচ্ছে। দয়া করে আমাদের কল সেন্টারে যোগাযোগ করুন।";
  }
};

import React, { useState, useMemo } from 'react';
import { UserRole, OrderStatus, Order, MenuItem } from '../types';
import { MOCK_ORDERS, MOCK_MENU } from '../constants';
import { Button } from './Button';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar, Cell } from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
}

interface AdminToast {
  message: string;
  type: 'success' | 'error' | 'info';
  id: number;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, orders: 240, profit: 1470 },
  { name: 'Sun', sales: 3800, orders: 198, profit: 1330 },
  { name: 'Mon', sales: 5200, orders: 310, profit: 1820 },
  { name: 'Tue', sales: 4800, orders: 280, profit: 1680 },
  { name: 'Wed', sales: 6200, orders: 390, profit: 2170 },
  { name: 'Thu', sales: 5800, orders: 340, profit: 2030 },
  { name: 'Fri', sales: 8500, orders: 480, profit: 2975 },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ userRole, onLogout }) => {
  const [activeTab, setActiveTab] = useState(userRole === UserRole.STAFF ? 'orders' : 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [orders, setOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [toasts, setToasts] = useState<AdminToast[]>([]);

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  };

  const metrics = useMemo(() => {
    const totalRev = orders.reduce((acc, o) => acc + o.total, 0);
    const estimatedCost = totalRev * 0.62; // Operational cost simulation
    const margin = totalRev > 0 ? ((totalRev - estimatedCost) / totalRev) * 100 : 0;
    return { 
      totalRev, 
      pendingCount: orders.filter(o => o.status !== OrderStatus.DELIVERED).length, 
      margin: margin.toFixed(1) 
    };
  }, [orders]);

  const updateOrderStatus = (orderId: string, newStatus: OrderStatus) => {
    if (userRole === UserRole.STAFF) {
      const order = orders.find(o => o.id === orderId);
      if (order?.status === OrderStatus.DELIVERED) {
        showToast("Access Denied: Cannot modify completed deliveries.", "error");
        return;
      }
    }
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order status updated to ${newStatus}`, "success");
  };

  const updateStock = (itemId: string, delta: number) => {
    setMenuItems(prev => prev.map(item => 
      item.id === itemId ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
    showToast("Stock level synchronized", "info");
  };

  const deleteMenuItem = (itemId: string) => {
    if (userRole !== UserRole.ADMIN) {
      showToast("Security Violation: Super Admin required for deletion.", "error");
      return;
    }
    if (window.confirm("This action is irreversible. Remove from catalog?")) {
      setMenuItems(prev => prev.filter(item => item.id !== itemId));
      showToast("Asset purged from system", "success");
    }
  };

  const canAccess = (tab: string) => {
    if (userRole === UserRole.STAFF) return tab === 'orders';
    if (userRole === UserRole.MANAGER) return tab !== 'reports'; 
    return true; 
  };

  const navigate = (tab: string) => {
    setActiveTab(tab);
    setSidebarOpen(false);
  };

  return (
    <div className="flex h-screen bg-[#F1F3F6] overflow-hidden font-sans select-none">
      {/* Admin Toasts */}
