        </div>

        <nav className="p-6 space-y-2">
          {canAccess('dashboard') && <SidebarBtn active={activeTab === 'dashboard'} onClick={()=>navigate('dashboard')} icon="fa-chart-pie" label="Dashboard" />}
          {canAccess('orders') && <SidebarBtn active={activeTab === 'orders'} onClick={()=>navigate('orders')} icon="fa-list-check" label="Orders" />}
          {canAccess('inventory') && <SidebarBtn active={activeTab === 'inventory'} onClick={()=>navigate('inventory')} icon="fa-box-open" label="Inventory" />}
