             <div className="w-10 h-10 lg:w-12 lg:h-12 bg-gray-900 text-white rounded-xl flex items-center justify-center shadow-lg"><i className="fas fa-user-gear"></i></div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 lg:p-10 scrollbar-hide animate-slide-up">
          {activeTab === 'dashboard' && canAccess('dashboard') && (
            <div className="space-y-10">
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6">
                 <DashboardStat title="Revenue" value={`৳${metrics.totalRev.toLocaleString()}`} icon="fa-bangladeshi-taka-sign" color="text-green-600" />
                 <DashboardStat title="Queue" value={metrics.pendingCount} icon="fa-clock" color="text-orange-500" />
                 <DashboardStat title="Low Stock" value={menuItems.filter(i => i.stock < 10).length} icon="fa-box-open" color="text-red-500" />
                 <DashboardStat title="Staff" value="12" icon="fa-users" color="text-blue-500" />
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                <div className="xl:col-span-2 bg-white p-6 lg:p-10 rounded-[40px] shadow-sm border border-gray-100 flex flex-col min-h-[450px]">
                   <h3 className="text-xl font-black text-gray-800 mb-8">Revenue Analytics</h3>
                   <div className="flex-1 w-full min-h-[300px]">
                      <ResponsiveContainer width="100%" height="100%">
                         <AreaChart data={ANALYTICS_DATA} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                            <defs>
                               <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                                  <stop offset="5%" stopColor="#dc2626" stopOpacity={0.15}/>
                                  <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
