                            </defs>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                            <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 800, fill: '#94a3b8'}} dy={10} />
                            <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 800, fill: '#94a3b8'}} />
                            <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 40px -10px rgba(0,0,0,0.1)' }} />
                            <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={4} fillOpacity={1} fill="url(#colorSales)" />
                         </AreaChart>
                      </ResponsiveContainer>
                   </div>
                </div>

                <div className="bg-white p-6 lg:p-10 rounded-[40px] shadow-sm border border-gray-100 flex flex-col min-h-[450px]">
                   <h3 className="text-xl font-black text-gray-800 mb-8">Top Item Stock</h3>
                   <div className="flex-1 w-full min-h-[300px]">
                      <ResponsiveContainer width="100%" height="100%">
                         <BarChart data={menuItems.slice(0, 5)} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                            <XAxis dataKey="nameBn" axisLine={false} tickLine={false} tick={{fontSize: 9, fontWeight: 800}} dy={10} />
                            <Tooltip cursor={{fill: 'transparent'}} />
                            <Bar dataKey="stock" radius={[8, 8, 0, 0]} barSize={30}>
                               {menuItems.slice(0, 5).map((entry, index) => (
                                  <Cell key={`cell-${index}`} fill={entry.stock < 15 ? '#dc2626' : '#1e293b'} />
                               ))}
                            </Bar>
                         </BarChart>
                      </ResponsiveContainer>
                   </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'orders' && (
             <div className="space-y-8">
                <div className="flex justify-between items-center">
                   <h2 className="text-3xl font-black text-gray-800 tracking-tighter">Order Hub</h2>
                   <Button size="sm" className="rounded-xl px-6" onClick={() => showToast("Feed Synced", "info")}>Refresh</Button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 2xl:grid-cols-3 gap-6">
                   {orders.map(o => (
                      <div key={o.id} className="bg-white p-6 lg:p-8 rounded-[40px] shadow-sm border border-gray-100 flex flex-col gap-6 group hover:shadow-xl transition-all">
                         <div className="flex justify-between items-start">
                            <div className="flex items-center gap-4">
                               <div className="w-12 h-12 bg-gray-900 text-white rounded-2xl flex items-center justify-center font-black text-xs">{o.id.split('-')[1]}</div>
                               <div>
                                  <p className="font-black text-lg text-gray-800 leading-tight">{o.customerName}</p>
                                  <p className="text-[9px] text-gray-400 font-black uppercase tracking-widest mt-1">{o.paymentMethod} • {o.createdAt.split('T')[1].slice(0,5)}</p>
                               </div>
                            </div>
                            <span className={`px-3 py-1.5 rounded-xl text-[8px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-green-100 text-green-700' : 'bg-red-50 text-red-600'}`}>{o.status}</span>
                         </div>
                         <div className="bg-gray-50 rounded-[25px] p-6 space-y-3">
                            {o.items.map((item, idx) => (
                              <div key={idx} className="flex justify-between text-xs font-bold text-gray-800">
                                <span>{item.quantity}x {item.name}</span>
                                {userRole !== UserRole.STAFF && <span className="text-gray-400">৳{item.price * item.quantity}</span>}
                              </div>
                            ))}
                         </div>
                         <select 
                           className="w-full bg-gray-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest p-4 cursor-pointer outline-none"
                           value={o.status}
                           onChange={(e) => updateOrderStatus(o.id, e.target.value as OrderStatus)}
                         >
                            {Object.values(OrderStatus).map(status => <option key={status} value={status}>{status}</option>)}
                         </select>
                      </div>
                   ))}
                </div>
             </div>
          )}

          {activeTab === 'inventory' && canAccess('inventory') && (
            <div className="space-y-10">
               <div className="flex justify-between items-center">
                  <h2 className="text-3xl font-black text-gray-800 tracking-tighter">Stock Management</h2>
                  {userRole === UserRole.ADMIN && <Button className="rounded-xl px-8 h-12 text-xs">Add Unit</Button>}
               </div>
               <div className="grid grid-cols-1 sm:grid-cols-2 2xl:grid-cols-4 gap-6">
                  {menuItems.map(item => (
                    <div key={item.id} className="bg-white p-6 rounded-[35px] shadow-sm border border-gray-100 flex flex-col group hover:shadow-xl transition-all">
                       <div className="flex items-center gap-4 mb-6">
                          <img src={item.image} className="w-20 h-20 rounded-2xl object-cover shadow-lg shrink-0" alt={item.name} />
                          <div className="min-w-0 flex-1">
                             <div className="flex justify-between">
                                <h4 className="font-black text-sm text-gray-800 truncate">{item.name}</h4>
                                {userRole === UserRole.ADMIN && <button onClick={()=>deleteMenuItem(item.id)} className="text-gray-200 hover:text-red-600 transition-colors"><i className="fas fa-trash-can text-[10px]"></i></button>}
                             </div>
                             <p className="text-[10px] text-gray-400 font-bold uppercase">{item.category}</p>
                             <p className="text-sm font-black text-red-600 mt-1">৳{item.price}</p>
                          </div>
                       </div>
                       <div className="mt-auto flex justify-between items-center mb-6 px-2">
                          <span className="text-[9px] font-black text-gray-300 uppercase tracking-widest">Stock</span>
                          <span className={`text-xl font-black ${item.stock < 10 ? 'text-red-600' : 'text-gray-900'}`}>{item.stock}</span>
                       </div>
                       <div className="flex gap-2">
                          <button onClick={() => updateStock(item.id, -1)} className="flex-1 bg-gray-50 text-gray-400 py-3 rounded-xl hover:bg-red-50 hover:text-red-600 transition-all"><i className="fas fa-minus text-[10px]"></i></button>
                          <button onClick={() => updateStock(item.id, 1)} className="flex-1 bg-gray-900 text-white py-3 rounded-xl hover:bg-red-600 transition-all"><i className="fas fa-plus text-[10px]"></i></button>
                       </div>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {activeTab === 'reports' && canAccess('reports') && (
            <div className="max-w-4xl mx-auto space-y-10">
               <h2 className="text-3xl font-black text-gray-800 tracking-tighter">Fiscal Audit</h2>
               <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                  <MetricBox label="Order Average" value="৳1,280" />
                  <MetricBox label="Net Margin" value={`${metrics.margin}%`} color="text-red-600" />
                  <MetricBox label="Asset Intake" value="৳88,500" />
                  <MetricBox label="Growth" value="+4.2%" color="text-green-600" />
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

const SidebarBtn = ({ active, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-xl transition-all duration-300 transform ${active ? 'bg-red-600 text-white shadow-xl scale-[1.02]' : 'text-gray-400 hover:text-red-600 hover:bg-red-50'}`}>
    <i className={`fas ${icon} text-lg w-6`}></i>
    <span className="font-black text-[10px] uppercase tracking-widest leading-none">{label}</span>
  </button>
);

const DashboardStat = ({ title, value, icon, color }: any) => (
  <div className="bg-white p-6 lg:p-8 rounded-[35px] shadow-sm border border-gray-100 flex items-center gap-6 group hover:shadow-xl transition-all relative overflow-hidden">
    <div className={`w-14 h-14 lg:w-16 lg:h-16 bg-gray-50 rounded-2xl flex items-center justify-center text-xl lg:text-2xl ${color} shadow-inner shrink-0`}><i className={`fas ${icon}`}></i></div>
    <div className="min-w-0">
      <p className="text-[8px] lg:text-[9px] font-black text-gray-300 uppercase tracking-widest mb-1 truncate">{title}</p>
      <h4 className="text-xl lg:text-2xl font-black text-gray-900 tracking-tighter truncate">{value}</h4>
