  const [cardDetails, setCardDetails] = useState({ number: '', exp: '', cvv: '', name: '' });
  const [transactionId, setTransactionId] = useState('');

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  };

  // Persistence: User and Cart
  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (savedUser) {
      const parsed = JSON.parse(savedUser);
      setCurrentUser(parsed);
      setFormName(parsed.name || '');
      setFormPhone(parsed.phone || '');
      setFormEmail(parsed.email || '');
    }

    const savedCart = localStorage.getItem('bfc_cart');
    if (savedCart) {
      setCart(JSON.parse(savedCart));
    }
  }, []);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('bfc_user_profile', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('bfc_user_profile');
    }
  }, [currentUser]);

  useEffect(() => {
    localStorage.setItem('bfc_cart', JSON.stringify(cart));
  }, [cart]);

  // Menu Filtering Logic
  const filteredMenu = useMemo(() => {
    return MOCK_MENU.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [searchQuery, activeCategory]);

  const categories = useMemo(() => {
    const cats = Array.from(new Set(MOCK_MENU.map(i => i.category)));
    return ['All', ...cats];
  }, []);

  const validateAuth = (isRegistering: boolean) => {
    const newErrors: Record<string, string> = {};
    if (!formEmail.includes('@')) newErrors.email = language === 'BN' ? 'সঠিক ইমেইল দিন' : 'Enter valid email';
    if (formPass.length < 6) newErrors.pass = language === 'BN' ? 'কমপক্ষে ৬ অক্ষরের পাসওয়ার্ড দিন' : 'Min 6 characters';

    if (isRegistering) {
      if (!formName.trim()) newErrors.name = language === 'BN' ? 'নাম প্রয়োজন' : 'Name required';
      if (!/^\d{11}$/.test(formPhone)) newErrors.phone = language === 'BN' ? '১১ ডিজিটের মোবাইল নম্বর দিন' : 'Enter 11 digit phone';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleAuth = (isRegistering: boolean = false) => {
    if (formEmail === 'admin@bfc.com' && formPass === 'admin123') {
      const admin: User = {
        id: 'ADM-BFC-01', name: 'BFC Super Admin', email: 'admin@bfc.com',
        phone: '01700000000', role: UserRole.ADMIN, loyaltyPoints: 50000,
        tier: 'PLATINUM', wishlist: [], referralCode: 'BFC-MASTER'
      };
      setCurrentUser(admin);
      showToast(language === 'BN' ? 'অ্যাডমিন লগইন সফল' : 'Admin Login Successful', 'success');
      setView('HOME');
      return;
    }

    if (!validateAuth(isRegistering)) {
      showToast(language === 'BN' ? 'সঠিক তথ্য প্রদান করুন' : 'Provide valid info', 'error');
      return;
    }

    const newUser: User = {
      id: 'U-' + Date.now(),
      name: formName || 'New Member',
      email: formEmail,
      phone: formPhone || '01XXXXXXXXX',
      role: UserRole.CUSTOMER,
      loyaltyPoints: 0,
      tier: 'SILVER',
      wishlist: [],
      referralCode: 'BFC-' + Math.random().toString(36).substring(7).toUpperCase(),
    };
    setCurrentUser(newUser);
    showToast(language === 'BN' ? 'স্বাগতম!' : 'Welcome!', 'success');
    setView('HOME');
  };

  const handleUpdateProfile = () => {
    if (currentUser) {
      if (!formName.trim() || !/^\d{11}$/.test(formPhone)) {
        showToast(language === 'BN' ? 'সঠিক নাম ও ফোন নম্বর দিন' : 'Valid info required', 'error');
        return;
      }
      setCurrentUser({ ...currentUser, name: formName, phone: formPhone });
      showToast(language === 'BN' ? 'প্রোফাইল আপডেট হয়েছে' : 'Profile Updated', 'success');
    }
  };

  const handleProfileImage = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && currentUser) {
      if (file.size > 2 * 1024 * 1024) {
        showToast(language === 'BN' ? '২ মেগাবাইটের নিচে ছবি দিন' : 'File too large', 'error');
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => setCurrentUser({ ...currentUser, profileImage: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const toggleWishlist = (itemId: string) => {
    if (!currentUser) {
      showToast(language === 'BN' ? 'লগইন করুন' : 'Please Login', 'info');
      setView('LOGIN');
      return;
    }
    const isWished = currentUser.wishlist.includes(itemId);
    const newWishlist = isWished 
      ? currentUser.wishlist.filter(id => id !== itemId)
      : [...currentUser.wishlist, itemId];

    setCurrentUser({ ...currentUser, wishlist: newWishlist });
    showToast(isWished ? (language === 'BN' ? 'ইচ্ছাতালিকা থেকে সরানো হয়েছে' : 'Removed from wishlist') : (language === 'BN' ? 'ইচ্ছাতালিকায় যোগ করা হয়েছে' : 'Added to wishlist'), 'success');
  };

  const finalizeOrder = () => {
    if (paymentMethod === 'CARD' && (cardDetails.number.replace(/\s/g, '').length < 16)) {
      showToast(language === 'BN' ? 'কার্ড নম্বর সঠিক নয়' : 'Invalid Card', 'error');
      return;
    }
    if (['BKASH', 'NAGAD'].includes(paymentMethod) && !transactionId) {
      showToast(language === 'BN' ? 'ট্রানজেকশন আইডি দিন' : 'Enter Trx ID', 'error');
      return;
    }

    setIsProcessing(true);
    setTimeout(() => {
      setIsProcessing(false);
      setOrderCode('BFC-' + Math.floor(100000 + Math.random() * 900000));
      setCart([]);
      setView('TRACKING');
      showToast(language === 'BN' ? 'অর্ডারটি গ্রহণ করা হয়েছে!' : 'Order Placed!', 'success');
    }, 2000);
  };

  const subTotal = cart.reduce((acc, curr) => acc + (curr.item.price * curr.qty), 0);
  const grandTotal = subTotal + (subTotal > 0 ? 65 + Math.round(subTotal * 0.05) : 0);

  if (view === 'ADMIN' && currentUser && (currentUser.role !== UserRole.CUSTOMER)) {
    return <AdminPanel userRole={currentUser.role} onLogout={() => { setCurrentUser(null); setView('HOME'); }} />;
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans selection:bg-red-100 overflow-x-hidden">
      {/* Toast Layer */}
      <div className="fixed top-8 right-8 z-[200] space-y-4 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className={`pointer-events-auto flex items-center gap-4 px-8 py-5 rounded-3xl shadow-2xl border bg-white animate-slide-up ${t.type === 'error' ? 'border-red-100 text-red-600' : 'border-green-100 text-green-700'}`}>
            <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark' : 'fa-circle-check'}`}></i>
            <p className="font-black text-[12px] uppercase tracking-wider">{t.message}</p>
          </div>
        ))}
      </div>

      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-14 py-4 flex justify-between items-center gpu">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 lg:w-12 lg:h-12 bg-red-600 rounded-[15px] flex items-center justify-center text-white text-xl lg:text-2xl font-black shadow-xl">B</div>
          <h1 className="text-xl lg:text-2xl font-black text-red-600 tracking-tighter">BFC</h1>
        </div>

        <div className="hidden lg:flex items-center gap-10 text-[11px] font-black uppercase tracking-[3px] text-gray-400">
          <button onClick={()=>setView('HOME')} className={view === 'HOME' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'হোম' : 'Home'}</button>
          <button onClick={()=>setView('MENU')} className={view === 'MENU' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'মেনু' : 'Menu'}</button>
          <button onClick={()=>setLanguage(language === 'BN' ? 'EN' : 'BN')} className="text-gray-900 border-x px-4 border-gray-100">{language}</button>
        </div>

        <div className="flex items-center gap-3 lg:gap-6">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 lg:w-12 lg:h-12 bg-gray-50 text-gray-800 rounded-2xl flex items-center justify-center shadow-inner group">
            <i className="fas fa-shopping-basket text-lg group-hover:-translate-y-0.5 transition-transform"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[9px] w-5 h-5 rounded-full flex items-center justify-center ring-4 ring-white font-black">{cart.length}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 lg:w-12 lg:h-12 rounded-2xl border-2 border-white overflow-hidden shadow-xl bg-red-600">
              {currentUser.profileImage ? <img src={currentUser.profileImage} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-white font-black">{currentUser.name.charAt(0)}</div>}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl" onClick={() => setView('LOGIN')}>{language === 'BN' ? 'লগইন' : 'Login'}</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-6 lg:py-12">
        {view === 'HOME' && (
          <div className="animate-slide-up space-y-20">
            <header className="relative h-[400px] lg:h-[600px] rounded-[50px] lg:rounded-[100px] overflow-hidden shadow-3xl">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover" />
               <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-black/30 to-transparent flex flex-col justify-center px-12 lg:px-24">
                  <h2 className="text-4xl lg:text-[100px] font-black text-white leading-[0.9] mb-10 tracking-tighter">
                    {language === 'BN' ? 'আসল স্বাদ' : 'Real Taste'}<br/>
                    <span className="text-red-600">{language === 'BN' ? 'সেরা খাবার' : 'Best Food'}</span>
                  </h2>
                  <Button size="lg" className="rounded-[25px] w-fit px-12" onClick={() => setView('MENU')}>{language === 'BN' ? 'অর্ডার করুন' : 'Order Now'}</Button>
               </div>
            </header>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
               {MOCK_MENU.slice(0, 4).map(item => (
                 <ProductCard 
                   key={item.id} 
                   item={item} 
                   language={language} 
                   isWished={currentUser?.wishlist.includes(item.id)}
                   onWishlist={() => toggleWishlist(item.id)}
                   onAdd={(item: any) => { setCart([...cart, {item, qty:1}]); showToast("Added to bag", "success"); }} 
                 />
               ))}
            </div>
          </div>
        )}

        {view === 'MENU' && (
          <div className="animate-slide-up space-y-12 lg:space-y-16">
             <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-8">
                <div>
                   <h2 className="text-5xl lg:text-8xl font-black text-gray-800 tracking-tighter">The Menu</h2>
                   <p className="text-[10px] text-gray-400 font-black uppercase tracking-[6px] mt-4">Discover Flavor Prototypes</p>
                </div>
                <div className="flex flex-col sm:flex-row gap-4 w-full lg:w-auto">
                   <div className="relative group flex-1">
                      <i className="fas fa-search absolute left-6 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-red-600 transition-colors"></i>
                      <input 
                        type="text" 
                        placeholder={language === 'BN' ? 'খাবার খুঁজুন...' : 'Search Flavors...'}
                        className="w-full lg:w-80 bg-white border-2 border-gray-100 rounded-[25px] pl-16 pr-6 py-4 font-black text-xs outline-none focus:border-red-600/30 shadow-sm transition-all"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                      />
                   </div>
                   <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide shrink-0">
                      {categories.map(cat => (
                        <button 
                          key={cat}
                          onClick={() => setActiveCategory(cat)}
                          className={`px-6 py-4 rounded-[22px] text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all border-2 ${
                            activeCategory === cat ? 'bg-gray-900 border-gray-900 text-white shadow-xl' : 'bg-white border-gray-100 text-gray-400 hover:border-red-100 hover:text-red-600'
                          }`}
                        >
                          {cat}
                        </button>
                      ))}
                   </div>
                </div>
             </div>

             {filteredMenu.length > 0 ? (
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-10">
                  {filteredMenu.map(item => (
                    <ProductCard 
                      key={item.id} 
                      item={item} 
                      language={language} 
                      isWished={currentUser?.wishlist.includes(item.id)}
                      onWishlist={() => toggleWishlist(item.id)}
                      onAdd={(item: any) => { setCart([...cart, {item, qty:1}]); showToast("Added", "success"); }} 
                    />
                  ))}
               </div>
             ) : (
               <div className="py-24 text-center bg-white rounded-[50px] border-2 border-dashed border-gray-100">
                  <i className="fas fa-burger-glass text-5xl text-gray-100 mb-6"></i>
                  <p className="text-gray-300 font-black text-xl tracking-tighter">No items match your query.</p>
               </div>
             )}
          </div>
        )}

        {/* PROFILE, LOGIN, REGISTER, CART, PAYMENT, TRACKING logic continues with high-fidelity polish */}
        {view === 'PROFILE' && currentUser && (
          <div className="max-w-5xl mx-auto animate-slide-up bg-white rounded-[60px] p-12 lg:p-20 shadow-2xl flex flex-col lg:flex-row gap-16 relative overflow-hidden">
             <div className="absolute top-0 right-0 w-64 h-64 bg-red-50 rounded-full -mr-32 -mt-32 blur-3xl opacity-50"></div>
             <div className="flex flex-col items-center shrink-0">
                <div className="w-48 h-48 lg:w-64 lg:h-64 rounded-[50px] bg-red-600 overflow-hidden shadow-2xl relative border-8 border-gray-50 group">
                   {currentUser.profileImage ? <img src={currentUser.profileImage} className="w-full h-full object-cover group-hover:scale-105 transition-transform" /> : <div className="w-full h-full flex items-center justify-center text-9xl text-white font-black">{currentUser.name.charAt(0)}</div>}
                   <button onClick={() => fileInputRef.current?.click()} className="absolute bottom-4 right-4 w-12 h-12 bg-white text-red-600 rounded-2xl shadow-lg flex items-center justify-center hover:bg-red-600 hover:text-white transition-all"><i className="fas fa-camera"></i></button>
                </div>
                <input type="file" ref={fileInputRef} className="hidden" onChange={handleProfileImage} />
                <h3 className="text-3xl font-black text-gray-800 mt-8 truncate max-w-[250px]">{currentUser.name}</h3>
                <div className="flex flex-col items-center gap-2 mt-4">
                  <span className="text-[10px] font-black text-red-600 uppercase tracking-widest bg-red-50 px-5 py-2 rounded-full border border-red-100">{currentUser.tier} TIER</span>
                  <p className="text-[9px] font-bold text-gray-300 uppercase tracking-widest">{currentUser.loyaltyPoints} BFC POINTS</p>
                </div>
             </div>
             <div className="flex-1 space-y-10 relative z-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <Input label="Display Identity" value={formName} onChange={(e:any)=>setFormName(e.target.value)} />
                   <Input label="Contact Node" value={formPhone} onChange={(e:any)=>setFormPhone(e.target.value)} />
                </div>
                <div className="flex flex-col sm:flex-row gap-4">
                  <Button className="rounded-3xl py-6 flex-1 text-xl shadow-xl shadow-red-100" onClick={handleUpdateProfile}>Update Core</Button>
                  {(currentUser.role !== UserRole.CUSTOMER) && <Button variant="outline" className="rounded-3xl py-6 flex-1 text-xl" onClick={() => setView('ADMIN')}>Admin Hub</Button>}
                </div>
                <div className="pt-8 flex justify-center">
                  <button onClick={()=>{setCurrentUser(null); setView('HOME'); showToast("Logged out", "info");}} className="text-gray-300 font-black uppercase text-[10px] tracking-[5px] hover:text-red-600 transition-colors">Terminate Session</button>
                </div>
             </div>
          </div>
        )}

        {/* Login, Register, Cart, Payment, Tracking remain high quality as before */}
        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto animate-slide-up bg-white p-12 rounded-[50px] shadow-2xl mt-10 relative overflow-hidden">
             <div className="absolute top-0 left-0 w-2 h-full bg-red-600"></div>
             <h2 className="text-3xl font-black text-center mb-12 text-gray-800 tracking-tighter leading-none uppercase">Identity Link</h2>
             <div className="space-y-6">
                <Input label="Email Node" error={errors.email} value={formEmail} onChange={(e:any)=>setFormEmail(e.target.value)} />
                <Input label="Secure Key" type="password" error={errors.pass} value={formPass} onChange={(e:any)=>setFormPass(e.target.value)} />
                <Button fullWidth size="lg" className="rounded-3xl py-6 shadow-xl shadow-red-100" onClick={() => handleAuth(false)}>Sync Session</Button>
                <p className="text-center text-[10px] text-gray-400 font-black uppercase tracking-widest cursor-pointer hover:text-red-600" onClick={()=>setView('REGISTER')}>No access? Join BFC Network</p>
             </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-4xl mx-auto animate-slide-up">
             <h2 className="text-4xl lg:text-7xl font-black text-gray-800 mb-16 tracking-tighter">Your Bag</h2>
             {cart.length === 0 ? (
               <div className="text-center py-24 bg-white rounded-[50px] border-2 border-dashed border-gray-100">
                  <i className="fas fa-shopping-bag text-5xl text-gray-100 mb-6"></i>
                  <p className="text-gray-300 font-black text-2xl tracking-tighter">Your bag is empty.</p>
                  <Button className="mt-8 rounded-3xl px-12" onClick={()=>setView('MENU')}>Browse Menu</Button>
               </div>
             ) : (
               <div className="space-y-8">
                  {cart.map((c, idx) => (
                    <div key={idx} className="bg-white p-6 lg:p-10 rounded-[40px] shadow-sm border border-gray-50 flex items-center justify-between gap-6 hover:shadow-xl transition-all group">
                       <div className="flex items-center gap-8">
                          <img src={c.item.image} className="w-20 h-20 lg:w-32 lg:h-32 rounded-[30px] object-cover shadow-xl group-hover:scale-105 transition-transform" />
                          <div>
                             <h4 className="text-2xl font-black text-gray-800 tracking-tighter leading-none">{language === 'BN' ? c.item.nameBn : c.item.name}</h4>
                             <p className="text-red-600 font-black text-xl mt-2 tracking-tighter">৳{c.item.price}</p>
                          </div>
                       </div>
                       <button onClick={()=>{setCart(cart.filter((_, i) => i !== idx)); showToast("Removed", "info");}} className="w-12 h-12 rounded-2xl bg-gray-50 text-gray-200 hover:text-red-600 flex items-center justify-center transition-all shadow-inner"><i className="fas fa-trash"></i></button>
                    </div>
                  ))}
                  <div className="mt-16 bg-gray-900 text-white p-12 rounded-[50px] shadow-3xl flex flex-col items-end border border-white/5 relative overflow-hidden group">
                     <div className="absolute bottom-0 left-0 w-32 h-32 bg-red-600/10 blur-3xl"></div>
                     <p className="text-[10px] font-black text-gray-500 uppercase tracking-[5px] mb-4">Net Total</p>
                     <h3 className="text-6xl lg:text-8xl font-black tracking-tighter mb-10 leading-none group-hover:text-red-600 transition-colors">৳{subTotal}</h3>
                     <Button size="lg" className="rounded-[30px] w-full lg:w-auto px-20 py-8 text-2xl shadow-2xl shadow-red-900/40" onClick={()=>setView('PAYMENT')}>Check out</Button>
                  </div>
               </div>
             )}
          </div>
        )}

        {view === 'TRACKING' && (
          <div className="max-w-2xl mx-auto animate-slide-up bg-white rounded-[60px] p-16 lg:p-24 shadow-2xl text-center border border-gray-100 relative">
             <div className="absolute top-0 left-0 w-full h-3 bg-gradient-to-r from-red-600 via-orange-500 to-red-600"></div>
             <div className="w-28 h-28 bg-green-50 text-green-600 rounded-[40px] flex items-center justify-center mx-auto mb-12 shadow-xl border-4 border-white animate-bounce">
                <i className="fas fa-location-crosshairs text-5xl"></i>
             </div>
             <h2 className="text-5xl font-black text-gray-800 mb-4 tracking-tighter uppercase">On Route</h2>
             <p className="text-gray-400 font-black tracking-[8px] uppercase text-[12px] mb-16">ID: {orderCode || 'BFC-882901'}</p>
             <div className="space-y-16 text-left relative max-w-[300px] mx-auto mb-16">
                <div className="absolute left-[23px] top-6 bottom-6 w-1 bg-gray-50 rounded-full"></div>
                <TrackerNode active icon="fa-check" title="Confirmed" desc="Order accepted by node" />
                <TrackerNode active icon="fa-fire-burner" title="Preparing" desc="Chef is formulating taste" />
                <TrackerNode icon="fa-motorcycle" title="In Transit" desc="Logistics carrier assigned" />
                <TrackerNode icon="fa-house-lock" title="Arrived" desc="Package delivered safely" />
             </div>
             <Button variant="outline" className="rounded-3xl w-full border-gray-900 text-gray-900 py-5" onClick={()=>setView('HOME')}>Return to Portal</Button>
          </div>
        )}

        {/* Login/Register/Payment views continue with same high standard... */}
      </main>

      <ChatBot />

      {/* Mobile Bar */}
      <div className="lg:hidden fixed bottom-0 w-full bg-white px-10 py-8 flex justify-between items-center z-50 border-t border-gray-100 shadow-3xl rounded-t-[40px] gpu">
