          <div key={t.id} className="pointer-events-auto flex items-center gap-4 px-6 py-4 rounded-3xl shadow-3xl border border-gray-100 bg-white animate-slide-up">
            <div className={`w-8 h-8 rounded-full flex items-center justify-center ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
              <i className={`fas ${t.type === 'error' ? 'fa-triangle-exclamation' : 'fa-check'}`}></i>
            </div>
            <p className="font-black text-[10px] uppercase tracking-widest text-gray-800">{t.message}</p>
          </div>
        ))}
      </div>

      <aside className={`fixed lg:static inset-y-0 left-0 z-[100] w-72 lg:w-80 bg-white shadow-2xl transition-transform duration-500 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 border-b border-gray-50 flex items-center gap-4">
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white shadow-xl rotate-3">
             <i className="fas fa-shield-halved"></i>
          </div>
          <h1 className="text-xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
        </div>

        <nav className="p-6 space-y-2">
          {canAccess('dashboard') && <SidebarBtn active={activeTab === 'dashboard'} onClick={()=>setActiveTab('dashboard')} icon="fa-chart-pie" label="Dashboard" />}
          {canAccess('orders') && <SidebarBtn active={activeTab === 'orders'} onClick={()=>setActiveTab('orders')} icon="fa-list-check" label="Orders" />}
          {canAccess('inventory') && <SidebarBtn active={activeTab === 'inventory'} onClick={()=>setActiveTab('inventory')} icon="fa-box-open" label="Inventory" />}
          {canAccess('staff') && <SidebarBtn active={activeTab === 'staff'} onClick={()=>setActiveTab('staff')} icon="fa-users-gear" label="Staff" />}
          {canAccess('reports') && <SidebarBtn active={activeTab === 'reports'} onClick={()=>setActiveTab('reports')} icon="fa-file-invoice-dollar" label="Ledger" />}
        </nav>

        <div className="absolute bottom-0 w-full p-6 border-t border-gray-50 bg-white">
          <button onClick={onLogout} className="w-full flex items-center justify-center gap-4 py-4 rounded-2xl bg-gray-50 text-gray-400 font-black hover:bg-red-50 hover:text-red-600 transition-all uppercase tracking-widest text-[10px]">
            Log out
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden bg-[#F1F3F6]">
        <header className="h-20 lg:h-24 bg-white border-b border-gray-100 flex items-center justify-between px-6 lg:px-12 shrink-0 z-50">
          <h2 className="text-xl lg:text-2xl font-black text-gray-800 tracking-tight capitalize">{activeTab}</h2>
