        </header>

        <div className="flex-1 overflow-y-auto p-6 lg:p-10 scrollbar-hide animate-slide-up">
          {activeTab === 'dashboard' && (
            <div className="space-y-10">
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6">
                 <DashboardStat title="Revenue" value={`৳${metrics.totalRev.toLocaleString()}`} icon="fa-bangladeshi-taka-sign" color="text-green-600" />
                 <DashboardStat title="Queue" value={metrics.pendingCount} icon="fa-clock" color="text-orange-500" />
                 <DashboardStat title="Low Stock" value={menuItems.filter(i => i.stock < 10).length} icon="fa-triangle-exclamation" color="text-red-500" />
                 <DashboardStat title="Daily Growth" value="+12%" icon="fa-chart-line" color="text-blue-500" />
              </div>
              <div className="bg-white p-10 rounded-[40px] shadow-sm border border-gray-100 min-h-[450px]">
                 <h3 className="text-xl font-black text-gray-800 mb-8">Sales Performance</h3>
                 <div className="h-[300px]">
                    <ResponsiveContainer width="100%" height="100%">
                       <AreaChart data={ANALYTICS_DATA}>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 800, fill: '#94a3b8'}} dy={10} />
                          <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 800, fill: '#94a3b8'}} />
                          <Tooltip />
                          <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={4} fill="#dc2626" fillOpacity={0.1} />
                       </AreaChart>
                    </ResponsiveContainer>
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'staff' && (
            <div className="space-y-8">
               <div className="flex justify-between items-center">
                  <h2 className="text-3xl font-black text-gray-800 tracking-tighter">Staff Directory</h2>
                  <Button size="sm">Add New Member</Button>
               </div>
               <div className="bg-white rounded-[40px] shadow-sm border border-gray-100 overflow-hidden">
                  <table className="w-full text-left border-collapse">
                     <thead>
                        <tr className="bg-gray-50/50">
                           <th className="p-8 text-[10px] font-black uppercase text-gray-400 tracking-widest">Name</th>
                           <th className="p-8 text-[10px] font-black uppercase text-gray-400 tracking-widest">Role</th>
                           <th className="p-8 text-[10px] font-black uppercase text-gray-400 tracking-widest">Status</th>
                           <th className="p-8 text-[10px] font-black uppercase text-gray-400 tracking-widest">Action</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-gray-50">
                        <StaffRow name="Abul Hasan" role="Manager" status="Active" />
                        <StaffRow name="Sujon Ali" role="Kitchen Staff" status="Active" />
                        <StaffRow name="Mofizur" role="Delivery" status="On Duty" />
                        <StaffRow name="Kabir Khan" role="Delivery" status="Offline" />
                     </tbody>
                  </table>
               </div>
            </div>
          )}

          {activeTab === 'orders' && (
             <div className="grid grid-cols-1 md:grid-cols-2 2xl:grid-cols-3 gap-6">
                {orders.map(o => (
                   <div key={o.id} className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 flex flex-col gap-6">
                      <div className="flex justify-between items-start">
                         <div className="flex items-center gap-4">
                            <div className="w-12 h-12 bg-gray-900 text-white rounded-2xl flex items-center justify-center font-black text-xs">{o.id.split('-')[1]}</div>
                            <div>
                               <p className="font-black text-lg text-gray-800">{o.customerName}</p>
                               <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest">{o.paymentMethod} • {o.createdAt.split('T')[1].slice(0,5)}</p>
                            </div>
                         </div>
                         <span className={`px-3 py-1.5 rounded-xl text-[8px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-green-100 text-green-700' : 'bg-red-50 text-red-600'}`}>{o.status}</span>
                      </div>
                      <select 
                        className="w-full bg-gray-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest p-4 cursor-pointer outline-none"
                        value={o.status}
                        onChange={(e) => updateOrderStatus(o.id, e.target.value as OrderStatus)}
                      >
                         {Object.values(OrderStatus).map(status => <option key={status} value={status}>{status}</option>)}
                      </select>
                   </div>
                ))}
             </div>
          )}

          {activeTab === 'inventory' && (
             <div className="grid grid-cols-1 sm:grid-cols-2 2xl:grid-cols-4 gap-6">
                {menuItems.map(item => (
                  <div key={item.id} className="bg-white p-6 rounded-[35px] shadow-sm border border-gray-100 flex flex-col group">
                     <div className="flex items-center gap-4 mb-6">
                        <img src={item.image} className="w-16 h-16 rounded-2xl object-cover shadow-lg" alt={item.name} />
                        <div className="min-w-0 flex-1">
                           <h4 className="font-black text-sm text-gray-800 truncate">{item.name}</h4>
                           <p className="text-[10px] text-gray-400 font-bold uppercase">{item.category}</p>
                        </div>
                     </div>
                     <div className="mt-auto flex justify-between items-center mb-6">
                        <span className="text-[10px] font-black text-gray-300 uppercase tracking-widest">Stock Level</span>
                        <span className={`text-xl font-black ${item.stock < 10 ? 'text-red-600' : 'text-gray-900'}`}>{item.stock}</span>
                     </div>
                     <div className="flex gap-2">
                        <button onClick={() => updateStock(item.id, -1)} className="flex-1 bg-gray-50 text-gray-400 py-3 rounded-xl hover:bg-red-50 hover:text-red-600 transition-all"><i className="fas fa-minus text-[10px]"></i></button>
                        <button onClick={() => updateStock(item.id, 1)} className="flex-1 bg-gray-900 text-white py-3 rounded-xl hover:bg-red-600 transition-all"><i className="fas fa-plus text-[10px]"></i></button>
                     </div>
                  </div>
                ))}
