          <div className="flex items-center gap-4 lg:hidden">
             <button onClick={()=>setSidebarOpen(true)} className="p-2 text-gray-400"><i className="fas fa-bars text-xl"></i></button>
             <h2 className="text-xl font-black text-gray-800 tracking-tight capitalize">{activeTab}</h2>
          </div>
          <h2 className="hidden lg:block text-xl lg:text-2xl font-black text-gray-800 tracking-tight capitalize">{activeTab}</h2>
          <div className="flex items-center gap-6">
