             <div className="w-10 h-10 lg:w-12 lg:h-12 bg-gray-900 text-white rounded-xl flex items-center justify-center shadow-lg"><i className="fas fa-user-gear"></i></div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 lg:p-10 scrollbar-hide animate-slide-up">
