                 <DashboardStat title="Queue" value={metrics.pendingCount} icon="fa-clock" color="text-orange-500" />
                 <DashboardStat title="Low Stock" value={menuItems.filter(i => i.stock < 10).length} icon="fa-triangle-exclamation" color="text-red-500" />
                 <DashboardStat title="Growth" value="+12.4%" icon="fa-chart-line" color="text-blue-500" />
              </div>
              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                 <div className="xl:col-span-2 bg-white p-10 rounded-[40px] shadow-sm border border-gray-100 min-h-[450px]">
                    <h3 className="text-xl font-black text-gray-800 mb-8">Performance History</h3>
                    <div className="h-[300px]">
                       <ResponsiveContainer width="100%" height="100%">
                          <AreaChart data={ANALYTICS_DATA}>
                             <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                             <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 800, fill: '#94a3b8'}} dy={10} />
                             <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 800, fill: '#94a3b8'}} />
                             <Tooltip />
                             <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={4} fill="#dc2626" fillOpacity={0.1} />
                          </AreaChart>
                       </ResponsiveContainer>
                    </div>
                 </div>
                 <div className="bg-white p-10 rounded-[40px] shadow-sm border border-gray-100">
                    <h3 className="text-xl font-black text-gray-800 mb-8">Live Stock Stats</h3>
                    <div className="space-y-6">
                       {menuItems.slice(0, 4).map(i => (
                          <div key={i.id} className="flex justify-between items-center">
                             <span className="text-xs font-bold text-gray-500">{i.name}</span>
                             <div className="flex items-center gap-3">
                                <div className="h-2 w-24 bg-gray-50 rounded-full overflow-hidden"><div className="h-full bg-red-600" style={{width: `${(i.stock/100)*100}%`}}></div></div>
                                <span className="text-xs font-black text-gray-800">{i.stock}</span>
                             </div>
                          </div>
                       ))}
                    </div>
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'staff' && (
            <div className="space-y-8">
               <div className="flex justify-between items-center">
                  <h2 className="text-3xl font-black text-gray-800 tracking-tighter">Personnel Directory</h2>
