                        <tr className="bg-gray-50/50">
                           <th className="p-8 text-[10px] font-black uppercase text-gray-400 tracking-widest">Employee</th>
                           <th className="p-8 text-[10px] font-black uppercase text-gray-400 tracking-widest">Node Role</th>
                           <th className="p-8 text-[10px] font-black uppercase text-gray-400 tracking-widest">Presence</th>
