                        </tr>
                     </thead>
                     <tbody className="divide-y divide-gray-50">
                        <StaffRow name="Rahman K." role="Manager" status="Active" color="emerald" />
                        <StaffRow name="Hussain A." role="Kitchen" status="Break" color="orange" />
                        <StaffRow name="Malik S." role="Logistics" status="Dispatching" color="blue" />
                        <StaffRow name="Zaman F." role="Staff" status="Offline" color="gray" />
                     </tbody>
                  </table>
               </div>
            </div>
          )}

          {activeTab === 'orders' && (
             <div className="grid grid-cols-1 md:grid-cols-2 2xl:grid-cols-3 gap-6">
