                  <div className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce"></div>
                </div>
              </div>
            )}
          </div>

          {/* Footer Area with Quick Actions */}
          <div className="p-6 bg-white border-t border-gray-50">
            {messages.length < 4 && (
              <div className="flex gap-2 overflow-x-auto pb-4 scrollbar-hide">
                {QUICK_ACTIONS.map(action => (
                  <button 
                    key={action}
                    onClick={() => handleSend(action)}
                    className="whitespace-nowrap px-4 py-2 bg-gray-50 hover:bg-red-50 hover:text-red-600 rounded-full text-[11px] font-black uppercase tracking-wider text-gray-500 border border-gray-100 transition-all"
                  >
                    {action}
                  </button>
                ))}
              </div>
            )}
            <div className="flex items-center gap-3 bg-gray-50 p-2 pl-6 rounded-[32px] border border-gray-100 focus-within:ring-4 ring-red-50/50 transition-all">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Talk to BFC Assist..."
                className="flex-1 bg-transparent border-none py-3 outline-none text-sm font-bold text-gray-800 placeholder:text-gray-300"
              />
              <button 
                onClick={() => handleSend()}
                disabled={!input.trim()}
                className="w-12 h-12 bg-red-600 text-white rounded-full flex items-center justify-center hover:bg-red-700 transition-all disabled:opacity-30 disabled:grayscale shadow-lg shadow-red-200"
              >
                <i className="fas fa-paper-plane text-xs"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-gray-900 text-white w-20 h-20 rounded-[30px] shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all duration-500 group relative border-4 border-white"
        >
          <div className="absolute inset-0 bg-red-600 rounded-[30px] animate-ping opacity-10 group-hover:opacity-30"></div>
