import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'info';
  id: number;
}

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<Array<{ item: MenuItem, qty: number, isSubscription?: boolean }>>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE' | 'PAYMENT' | 'REGISTER' | 'WISHLIST'>('HOME');
  const [language, setLanguage] = useState<'EN' | 'BN'>('BN');
  const [selectedProduct, setSelectedProduct] = useState<MenuItem | null>(null);
  const [isSubscriptionMode, setIsSubscriptionMode] = useState(false);

  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  const [formName, setFormName] = useState('');
  const [formEmail, setFormEmail] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [formPass, setFormPass] = useState('');
  const [deliveryZone, setDeliveryZone] = useState('Gulshan');
  const [deliverySlot, setDeliverySlot] = useState('Immediate');

  const [toasts, setToasts] = useState<Toast[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'ROCKET' | 'UPAY' | 'CARD' | 'COD'>('BKASH');
  const [isProcessing, setIsProcessing] = useState(false);
  const [orderCode, setOrderCode] = useState('');
  const [cardDetails, setCardDetails] = useState({ number: '', exp: '', cvv: '', name: '' });
  const [transactionId, setTransactionId] = useState('');

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (savedUser) {
      const parsed = JSON.parse(savedUser);
      setCurrentUser(parsed);
