          </div>
          <h1 className="text-xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
        </div>

        <nav className="p-6 space-y-2">
          {canAccess('dashboard') && <SidebarBtn active={activeTab === 'dashboard'} onClick={()=>setActiveTab('dashboard')} icon="fa-chart-pie" label="Analytics" />}
          {canAccess('orders') && <SidebarBtn active={activeTab === 'orders'} onClick={()=>setActiveTab('orders')} icon="fa-list-check" label="Orders" />}
          {canAccess('inventory') && <SidebarBtn active={activeTab === 'inventory'} onClick={()=>setActiveTab('inventory')} icon="fa-box-open" label="Inventory" />}
          {canAccess('staff') && <SidebarBtn active={activeTab === 'staff'} onClick={()=>setActiveTab('staff')} icon="fa-users-gear" label="Staff" />}
          {canAccess('reports') && <SidebarBtn active={activeTab === 'reports'} onClick={()=>setActiveTab('reports')} icon="fa-file-invoice-dollar" label="Ledger" />}
        </nav>

        <div className="absolute bottom-0 w-full p-6 border-t border-gray-50 bg-white">
          <button onClick={onLogout} className="w-full flex items-center justify-center gap-4 py-4 rounded-2xl bg-gray-50 text-gray-400 font-black hover:bg-red-50 hover:text-red-600 transition-all uppercase tracking-widest text-[10px]">
            Log out
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden bg-[#F1F3F6]">
