                 <DashboardStat title="Queue" value={metrics.pendingCount} icon="fa-clock" color="text-orange-500" />
                 <DashboardStat title="Low Stock" value={menuItems.filter(i => i.stock < 10).length} icon="fa-triangle-exclamation" color="text-red-500" />
              </div>
              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                 <div className="xl:col-span-2 bg-white p-10 rounded-[40px] shadow-sm border border-gray-100 min-h-[450px]">
                    <h3 className="text-xl font-black text-gray-800 mb-8">Performance Node</h3>
                    <div className="h-[300px]">
                       <ResponsiveContainer width="100%" height="100%">
                          <AreaChart data={ANALYTICS_DATA}>
