export default AdminPanel;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, Review } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'info';
  id: number;
}

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<Array<{ item: MenuItem, qty: number, isSubscription?: boolean }>>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE' | 'PAYMENT' | 'REGISTER' | 'WISHLIST'>('HOME');
  const [language, setLanguage] = useState<'EN' | 'BN'>('BN');
  const [selectedProduct, setSelectedProduct] = useState<MenuItem | null>(null);
  const [isSubscriptionMode, setIsSubscriptionMode] = useState(false);

  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  const [formName, setFormName] = useState('');
  const [formEmail, setFormEmail] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [formPass, setFormPass] = useState('');
  const [deliveryZone, setDeliveryZone] = useState('Gulshan');
  const [deliverySlot, setDeliverySlot] = useState('Immediate');

  const [toasts, setToasts] = useState<Toast[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'CARD' | 'COD'>('BKASH');
  const [isProcessing, setIsProcessing] = useState(false);
  const [orderCode, setOrderCode] = useState('');
  const [cardDetails, setCardDetails] = useState({ number: '', exp: '', cvv: '', name: '' });
  const [transactionId, setTransactionId] = useState('');

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (savedUser) {
      const parsed = JSON.parse(savedUser);
      setCurrentUser(parsed);
      setFormName(parsed.name || '');
      setFormPhone(parsed.phone || '');
      setFormEmail(parsed.email || '');
    }
    const savedCart = localStorage.getItem('bfc_cart');
    if (savedCart) setCart(JSON.parse(savedCart));
  }, []);

  useEffect(() => {
    if (currentUser) localStorage.setItem('bfc_user_profile', JSON.stringify(currentUser));
    else localStorage.removeItem('bfc_user_profile');
  }, [currentUser]);

  useEffect(() => {
    localStorage.setItem('bfc_cart', JSON.stringify(cart));
  }, [cart]);

  const filteredMenu = useMemo(() => {
    return MOCK_MENU.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [searchQuery, activeCategory]);

  const wishlistItems = useMemo(() => {
    if (!currentUser) return [];
    return MOCK_MENU.filter(item => currentUser.wishlist.includes(item.id));
  }, [currentUser?.wishlist]);

  const handleAuth = (isRegistering: boolean = false) => {
    // Admin Shortcut
    if (formEmail === 'admin@bfc.com' && formPass === 'admin123') {
      const admin: User = {
        id: 'ADM-01', name: 'BFC Admin', email: 'admin@bfc.com',
        phone: '01700000000', role: UserRole.ADMIN, loyaltyPoints: 1000,
        tier: 'PLATINUM', wishlist: [], referralCode: 'BFC-ADMIN'
      };
      setCurrentUser(admin);
      showToast('Admin Session Initialized', 'success');
      setView('HOME');
      return;
    }

    // Simple Auth Mock
    const newUser: User = {
      id: 'U-' + Date.now(),
      name: formName || 'New User',
      email: formEmail,
      phone: formPhone || '01XXXXXXXXX',
      role: UserRole.CUSTOMER,
      loyaltyPoints: 0,
      tier: 'SILVER',
      wishlist: [],
      referralCode: 'BFC-' + Math.random().toString(36).substring(7).toUpperCase(),
    };
    setCurrentUser(newUser);
    showToast(isRegistering ? 'Registration Success!' : 'Logged In', 'success');
    setView('HOME');
  };

  const toggleWishlist = (itemId: string) => {
    if (!currentUser) {
      showToast('Login to save favorites', 'info');
      setView('LOGIN');
      return;
    }
    const isWished = currentUser.wishlist.includes(itemId);
    const newWishlist = isWished 
      ? currentUser.wishlist.filter(id => id !== itemId)
      : [...currentUser.wishlist, itemId];
    setCurrentUser({ ...currentUser, wishlist: newWishlist });
    showToast(isWished ? 'Removed' : 'Added to Wishlist', 'success');
  };

  const handleProfileImage = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (currentUser) {
          setCurrentUser({ ...currentUser, profileImage: reader.result as string });
          showToast('Identity Image Updated', 'success');
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const subTotal = cart.reduce((acc, curr) => acc + (curr.item.price * curr.qty), 0);
  const deliveryCharge = deliveryZone === 'Gulshan' ? 50 : 70;
  const tax = Math.round(subTotal * 0.05);
  const grandTotal = subTotal + (subTotal > 0 ? deliveryCharge + tax : 0);

  const finalizeOrder = () => {
    if (paymentMethod === 'CARD' && !cardDetails.number) return showToast("Enter card details", "error");
    if (['BKASH', 'NAGAD'].includes(paymentMethod) && !transactionId) return showToast("Enter Trx ID", "error");

    setIsProcessing(true);
    setTimeout(() => {
      setIsProcessing(false);
      setOrderCode('BFC-' + Math.floor(100000 + Math.random() * 900000));
      if (currentUser) {
        const pointsEarned = Math.floor(subTotal / 10);
        setCurrentUser({ ...currentUser, loyaltyPoints: currentUser.loyaltyPoints + pointsEarned });
      }
      setCart([]);
      setView('TRACKING');
      showToast('Order Transmitted Successfully', 'success');
    }, 2500);
  };

  if (view === 'ADMIN' && currentUser && (currentUser.role !== UserRole.CUSTOMER)) {
    return <AdminPanel userRole={currentUser.role} onLogout={() => { setCurrentUser(null); setView('HOME'); }} />;
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans selection:bg-red-100 overflow-x-hidden">
