                    <Button size="lg" className="rounded-[35px] px-14 py-8 text-2xl shadow-3xl shadow-red-600/20" onClick={()=>{setCart([...cart, {item: selectedProduct, qty:1, isSubscription: isSubscriptionMode}]); setSelectedProduct(null); showToast("Added to Primary Bag", "success");}}>Add to Bag</Button>
                 </div>
