         <button onClick={()=>setView('MENU')} className={view === 'MENU' ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-utensils text-2xl transition-all"></i></button>
         <button onClick={()=>setView('WISHLIST')} className={view === 'WISHLIST' ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-heart text-2xl transition-all"></i></button>
         <button onClick={()=>setView('CART')} className={view === 'CART' ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-shopping-bag text-2xl transition-all"></i></button>
         <button onClick={()=>currentUser ? setView('PROFILE') : setView('LOGIN')} className={(view === 'PROFILE' || view === 'REGISTER' || view === 'LOGIN') ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-user-circle text-2xl transition-all"></i></button>
