import React, { useState, useMemo, useEffect } from 'react';
import { UserRole, OrderStatus, Order, MenuItem } from '../types';
import { MOCK_ORDERS, MOCK_MENU } from '../constants';
import { Button } from './Button';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
}

interface AdminToast {
  message: string;
  type: 'success' | 'error' | 'info';
  id: number;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, orders: 240, volume: 85 },
  { name: 'Sun', sales: 3800, orders: 198, volume: 70 },
  { name: 'Mon', sales: 5200, orders: 310, volume: 110 },
  { name: 'Tue', sales: 4800, orders: 280, volume: 95 },
  { name: 'Wed', sales: 6200, orders: 390, volume: 140 },
  { name: 'Thu', sales: 5800, orders: 340, volume: 125 },
  { name: 'Fri', sales: 8500, orders: 480, volume: 180 },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ userRole, onLogout }) => {
  // Defensive initialization of active tab based on role
  const getDefaultTab = () => {
    if (userRole === UserRole.STAFF) return 'orders';
    return 'dashboard';
  };

  const [activeTab, setActiveTab] = useState(getDefaultTab());
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [orders, setOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [toasts, setToasts] = useState<AdminToast[]>([]);

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  };

  const metrics = useMemo(() => {
    const totalRev = orders.reduce((acc, o) => acc + o.total, 0);
    const estimatedCost = totalRev * 0.62;
    const margin = totalRev > 0 ? ((totalRev - estimatedCost) / totalRev) * 100 : 0;
    return { 
      totalRev, 
      pendingCount: orders.filter(o => o.status !== OrderStatus.DELIVERED).length, 
      margin: margin.toFixed(1),
      orderCount: orders.length
    };
  }, [orders]);

  const updateOrderStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order status transitioned to ${newStatus}`, "success");
  };

  const updateStock = (itemId: string, delta: number) => {
    if (userRole === UserRole.STAFF) {
      showToast("Inventory access restricted for staff members.", "error");
      return;
    }
    setMenuItems(prev => prev.map(item => 
      item.id === itemId ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
    showToast("Stock parity synchronized", "info");
  };

  const deleteMenuItem = (itemId: string) => {
    if (userRole !== UserRole.ADMIN) {
      showToast("Operation Restricted: Admin clearance required.", "error");
      return;
    }
    if (window.confirm("Purge asset from database?")) {
      setMenuItems(prev => prev.filter(i => i.id !== itemId));
      showToast("Asset Purged", "success");
    }
  };

  // Centralized logic for RBAC checks
