      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (savedUser) {
      const parsed = JSON.parse(savedUser);
      setCurrentUser(parsed);
      setFormName(parsed.name || '');
      setFormPhone(parsed.phone || '');
      setFormEmail(parsed.email || '');
    }
    const savedCart = localStorage.getItem('bfc_cart');
    if (savedCart) setCart(JSON.parse(savedCart));
  }, []);

  useEffect(() => {
    if (currentUser) localStorage.setItem('bfc_user_profile', JSON.stringify(currentUser));
    else localStorage.removeItem('bfc_user_profile');
  }, [currentUser]);

  useEffect(() => {
    localStorage.setItem('bfc_cart', JSON.stringify(cart));
  }, [cart]);

  const filteredMenu = useMemo(() => {
    return MOCK_MENU.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [searchQuery, activeCategory]);

  const wishlistItems = useMemo(() => {
    if (!currentUser) return [];
    return MOCK_MENU.filter(item => currentUser.wishlist.includes(item.id));
  }, [currentUser?.wishlist]);

  const handleAuth = (isRegistering: boolean = false) => {
    if (formEmail === 'admin@bfc.com' && formPass === 'admin123') {
      const admin: User = {
        id: 'ADM-01', name: 'BFC Admin', email: 'admin@bfc.com',
        phone: '01700000000', role: UserRole.ADMIN, loyaltyPoints: 1000,
        tier: 'PLATINUM', wishlist: [], referralCode: 'BFC-ADMIN'
      };
      setCurrentUser(admin);
      showToast('Admin Session Initialized', 'success');
      setView('HOME');
      return;
    }

