import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist", the ultimate food concierge for BFC (Bangla Food Club).

        Tone: Engaging, casual, energetic, and culturally connected. You are a "foodie friend" (bondhu), not a corporate bot. 

        CORE RULES:
        1. STRICT CONCISENESS: Never exceed 2 short sentences.
        2. NO FORMAL GREETINGS: Avoid "Assalamu Alaikum", "Adab", or formal "Hello". Use casual intros like "Yo!", "Hey!", or "Hi there!".
        3. PRACTICALITY FIRST: Focus on menu favorites (Kacchi, Morog Polao), spice levels, or order status (point them to the Tracking tab).
        4. HYPED VIBE: Use words like "Legendary", "Absolute fire 🔥", "Elite", and "Chef's kiss".
        5. LANGUAGE: Natural Banglish (blend of English and casual Bengali).

        Example: "Yo! That Kacchi is absolute fire today. 🔥 Check the Tracking tab to see when your order hits the node!"`,
        temperature: 0.8,
        topP: 0.9,
      },
    });

    return response.text || "Connection glitch. Say that again? 😅";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "The system is a bit full right now. Try again in a sec! 🌯";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

const QUICK_ACTIONS = [
  "Recommend Kacchi 🍛",
  "Today's Specials ✨",
  "Track My Order 📍",
  "Is it Spicy? 🔥"
];

export const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { 
      role: 'model', 
      text: "Yo! BFC Assist here. 👋 Ready for some legendary Kacchi or need help with a delivery? I got you!", 
      timestamp: new Date() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async (text: string = input) => {
    const messageToSend = text.trim();
    if (!messageToSend) return;

    const userMsg: ChatMessage = { role: 'user', text: messageToSend, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));

    try {
      const botResponse = await bfcAssistChat(messageToSend, history);
      setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Connection's a bit glitchy. Try again? 😅", timestamp: new Date() }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-10 lg:right-10 z-[100] font-sans">
      {isOpen ? (
        <div className="bg-white/95 backdrop-blur-3xl w-[92vw] sm:w-[420px] h-[75vh] sm:h-[680px] rounded-[48px] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.3)] flex flex-col border border-white/60 overflow-hidden animate-slide-up gpu">
          {/* Modern Premium Header */}
          <div className="bg-gray-950 p-8 text-white relative overflow-hidden shrink-0">
            <div className="absolute -top-10 -right-10 w-48 h-48 bg-red-600/20 rounded-full blur-[60px] animate-pulse"></div>
            <div className="absolute -bottom-10 -left-10 w-32 h-32 bg-emerald-500/10 rounded-full blur-[40px]"></div>

            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-5">
                <div className="w-14 h-14 bg-gradient-to-br from-red-600 to-orange-500 rounded-[22px] flex items-center justify-center shadow-2xl shadow-red-500/30 rotate-3 group-hover:rotate-0 transition-transform">
                  <i className="fas fa-robot text-2xl"></i>
                </div>
                <div>
                  <h3 className="font-black text-xl tracking-tighter leading-none">BFC Assist</h3>
                  <div className="flex items-center gap-2 mt-2">
                    <span className="w-2 h-2 bg-emerald-400 rounded-full animate-pulse shadow-[0_0_10px_rgba(52,211,153,0.8)]"></span>
                    <p className="text-[9px] font-black uppercase tracking-[3px] opacity-60">Node Active</p>
                  </div>
                </div>
              </div>
              <button 
                onClick={() => setIsOpen(false)} 
                className="w-12 h-12 bg-white/10 hover:bg-white/20 rounded-2xl flex items-center justify-center transition-all border border-white/5 active:scale-90"
              >
                <i className="fas fa-chevron-down opacity-60"></i>
              </button>
            </div>
          </div>

          {/* Chat History Flow */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-6 scrollbar-hide bg-[#FDFDFD]">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                <div className={`max-w-[85%] px-7 py-5 rounded-[32px] text-[14px] font-bold leading-relaxed shadow-sm ${
                  m.role === 'user' 
                  ? 'bg-red-600 text-white rounded-br-none shadow-red-100' 
                  : 'bg-white text-gray-800 border border-gray-100 rounded-tl-none'
                }`}>
                  {m.text}
                  <div className={`text-[8px] mt-2 font-black tracking-widest opacity-40 uppercase ${m.role === 'user' ? 'text-white' : 'text-gray-400'}`}>
                    {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </div>
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start animate-slide-up">
                <div className="bg-gray-50 px-6 py-4 rounded-[25px] rounded-tl-none flex gap-2 border border-gray-100 shadow-inner">
                  <div className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-400 rounded-full animate-bounce"></div>
                </div>
              </div>
            )}
          </div>

          {/* Premium Interactive Footer */}
          <div className="p-8 bg-white border-t border-gray-50/50">
            {messages.length < 5 && (
              <div className="flex gap-2 overflow-x-auto pb-6 scrollbar-hide">
                {QUICK_ACTIONS.map(action => (
                  <button 
                    key={action}
                    onClick={() => handleSend(action)}
                    className="whitespace-nowrap px-6 py-3 bg-gray-50 hover:bg-red-600 hover:text-white rounded-full text-[10px] font-black uppercase tracking-widest text-gray-400 border border-gray-100 transition-all active:scale-95 shadow-sm"
                  >
                    {action}
                  </button>
                ))}
              </div>
            )}
            <div className="flex items-center gap-3 bg-[#F8FAFC] p-2 pl-8 rounded-full border border-gray-100 focus-within:ring-12 ring-red-50/50 transition-all focus-within:bg-white focus-within:border-red-600/10 shadow-inner">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Talk to BFC Assist..."
                className="flex-1 bg-transparent border-none py-4 outline-none text-sm font-bold text-gray-800 placeholder:text-gray-300"
              />
              <button 
                onClick={() => handleSend()}
                disabled={!input.trim()}
                className="w-14 h-14 bg-red-600 text-white rounded-full flex items-center justify-center hover:bg-red-700 transition-all disabled:opacity-20 disabled:grayscale shadow-xl shadow-red-200"
              >
                <i className="fas fa-paper-plane text-sm"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-gray-950 text-white w-20 h-20 rounded-[30px] shadow-3xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all duration-500 group relative border-4 border-white overflow-hidden ring-8 ring-gray-900/5"
        >
          <div className="absolute inset-0 bg-gradient-to-tr from-red-600 to-orange-500 opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>
          <i className="fas fa-comment-dots text-3xl group-hover:scale-125 transition-transform relative z-10"></i>
          <span className="absolute -top-1 -right-1 w-7 h-7 bg-red-600 border-4 border-white rounded-full flex items-center justify-center shadow-lg z-20">
             <span className="w-1.5 h-1.5 bg-white rounded-full animate-ping"></span>
          </span>
        </button>
      )}
    </div>
  );
};

