  const generateMockToken = (role: UserRole, email: string) => {
    const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
    const payload = btoa(JSON.stringify({ role, email, exp: Date.now() + 86400000 }));
    const signature = btoa('bfc-secure-signature-v1');
    return `${header}.${payload}.${signature}`;
  };

  // Session Validation
  const validateSession = (user: User) => {
    if (!user.sessionToken) return false;
    try {
      const payloadPart = user.sessionToken.split('.')[1];
      const payload = JSON.parse(atob(payloadPart));
      return payload.exp > Date.now();
    } catch {
      return false;
    }
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (savedUser) {
      const parsed = JSON.parse(savedUser) as User;
      if (validateSession(parsed)) {
        setCurrentUser(parsed);
        setFormName(parsed.name || '');
        setFormPhone(parsed.phone || '');
        setFormEmail(parsed.email || '');
      } else {
        localStorage.removeItem('bfc_user_profile');
        showToast('Session Expired: Please Re-authenticate', 'info');
      }
    }
    const savedCart = localStorage.getItem('bfc_cart');
    if (savedCart) setCart(JSON.parse(savedCart));
  }, []);

  useEffect(() => {
    if (currentUser) localStorage.setItem('bfc_user_profile', JSON.stringify(currentUser));
    else localStorage.removeItem('bfc_user_profile');
  }, [currentUser]);

  useEffect(() => {
    localStorage.setItem('bfc_cart', JSON.stringify(cart));
  }, [cart]);

  const filteredMenu = useMemo(() => {
    return MOCK_MENU.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [searchQuery, activeCategory]);

  const wishlistItems = useMemo(() => {
    if (!currentUser) return [];
    return MOCK_MENU.filter(item => currentUser.wishlist.includes(item.id));
  }, [currentUser?.wishlist]);

  const handleAuth = async (isRegistering: boolean = false) => {
    if (!formEmail || !formPass) {
      return showToast('Credentials Required', 'error');
    }

    setIsAuthenticating(true);

    // Simulate Network Latency & Digital Signature Verification
    await new Promise(resolve => setTimeout(resolve, 1800));

    const privilegedUser = MOCK_AUTH_DB[formEmail as keyof typeof MOCK_AUTH_DB];

    if (privilegedUser) {
      if (privilegedUser.pass === formPass) {
        const token = generateMockToken(privilegedUser.role, formEmail);
        const user: User = {
          id: `SEC-${Math.random().toString(36).substring(7).toUpperCase()}`,
          name: privilegedUser.name,
          email: formEmail,
          phone: '01700-XXXXXX',
          role: privilegedUser.role,
          loyaltyPoints: 1000,
          tier: 'PLATINUM',
          wishlist: [],
          referralCode: 'SEC-BFC-MASTER',
          sessionToken: token
        };
        setCurrentUser(user);
        setIsAuthenticating(false);
        showToast(`${privilegedUser.role} Access Granted`, 'success');
        setView('HOME');
      } else {
        setIsAuthenticating(false);
        showToast('Invalid Secret: Hash Mismatch', 'error');
      }
      return;
    }

    // Customer Login Flow
    if (isRegistering) {
      const newUser: User = {
        id: 'U-' + Date.now(),
        name: formName || 'New Node',
        email: formEmail,
        phone: formPhone || '01XXXXXXXXX',
        role: UserRole.CUSTOMER,
        loyaltyPoints: 0,
        tier: 'SILVER',
        wishlist: [],
        referralCode: 'BFC-' + Math.random().toString(36).substring(7).toUpperCase(),
        sessionToken: generateMockToken(UserRole.CUSTOMER, formEmail)
      };
      setCurrentUser(newUser);
      showToast('Node Initialized Successfully', 'success');
    } else {
      // Mock simple customer login
      const user: User = {
        id: 'U-EXISTING',
        name: formName || 'Returning Node',
        email: formEmail,
        phone: formPhone || '01XXXXXXXXX',
        role: UserRole.CUSTOMER,
        loyaltyPoints: 150,
        tier: 'GOLD',
        wishlist: [],
        referralCode: 'BFC-RETURN-88',
        sessionToken: generateMockToken(UserRole.CUSTOMER, formEmail)
      };
      setCurrentUser(user);
      showToast('Identity Synchronized', 'success');
    }

    setIsAuthenticating(false);
    setView('HOME');
  };

  const toggleWishlist = (itemId: string) => {
    if (!currentUser) {
      showToast('Sync Identity to Save Favorites', 'info');
      setView('LOGIN');
      return;
    }
    const isWished = currentUser.wishlist.includes(itemId);
    const newWishlist = isWished 
      ? currentUser.wishlist.filter(id => id !== itemId)
      : [...currentUser.wishlist, itemId];
    setCurrentUser({ ...currentUser, wishlist: newWishlist });
    showToast(isWished ? 'Asset Removed' : 'Asset Pinned', 'success');
  };

  const handleProfileImage = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (currentUser) {
          setCurrentUser({ ...currentUser, profileImage: reader.result as string });
          showToast('Biometric Image Updated', 'success');
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const subTotal = cart.reduce((acc, curr) => acc + (curr.item.price * curr.qty), 0);
  const deliveryCharge = deliveryZone.includes('Gulshan') ? 50 : 70;
  const tax = Math.round(subTotal * 0.05);
  const grandTotal = subTotal + (subTotal > 0 ? deliveryCharge + tax : 0);

  const finalizeOrder = () => {
    if (paymentMethod === 'CARD' && !cardDetails.number) return showToast("Invalid Card Sequence", "error");
    if (['BKASH', 'NAGAD'].includes(paymentMethod) && !transactionId) return showToast("Sync TRX ID", "error");

    setIsProcessing(true);
    setTimeout(() => {
      setIsProcessing(false);
      setOrderCode('BFC-' + Math.floor(100000 + Math.random() * 900000));
      if (currentUser) {
        const pointsEarned = Math.floor(subTotal / 10);
        setCurrentUser({ ...currentUser, loyaltyPoints: currentUser.loyaltyPoints + pointsEarned });
      }
      setCart([]);
      setView('TRACKING');
      showToast('Logistics Trace Initialized', 'success');
    }, 2500);
  };

  if (view === 'ADMIN' && currentUser && (currentUser.role !== UserRole.CUSTOMER)) {
    // Only render if token is present and valid
    if (validateSession(currentUser)) {
      return <AdminPanel userRole={currentUser.role} onLogout={() => { setCurrentUser(null); setView('HOME'); }} />;
    } else {
      setView('LOGIN');
    }
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans selection:bg-red-100 overflow-x-hidden">
      {/* Auth Verification Loader Overlay */}
      {isAuthenticating && (
        <div className="fixed inset-0 z-[1000] bg-gray-950/95 backdrop-blur-3xl flex flex-col items-center justify-center text-white animate-fade-in">
           <div className="w-24 h-24 mb-10 relative">
              <div className="absolute inset-0 border-4 border-red-600/20 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-red-600 rounded-full border-t-transparent animate-spin"></div>
              <div className="absolute inset-4 bg-red-600 rounded-full animate-pulse flex items-center justify-center">
                 <i className="fas fa-shield-halved text-xl"></i>
              </div>
           </div>
           <h2 className="text-2xl font-black uppercase tracking-[8px] mb-4">Verifying Identity</h2>
           <p className="text-gray-500 font-black text-[9px] uppercase tracking-[4px]">Syncing with Digital Security Matrix...</p>
        </div>
      )}

      {/* Toast notifications */}
      <div className="fixed top-8 right-8 z-[200] space-y-4 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-center gap-4 px-8 py-5 rounded-3xl shadow-2xl border bg-white animate-slide-up border-green-100 text-green-700">
            <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark text-red-600' : 'fa-circle-check text-green-600'}`}></i>
            <p className="font-black text-[12px] uppercase tracking-wider">{t.message}</p>
          </div>
        ))}
      </div>

      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-14 py-4 flex justify-between items-center gpu">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 lg:w-12 lg:h-12 bg-red-600 rounded-[15px] flex items-center justify-center text-white text-xl lg:text-2xl font-black shadow-xl ring-4 ring-red-50">B</div>
          <h1 className="text-xl lg:text-2xl font-black text-red-600 tracking-tighter">BFC</h1>
        </div>

        <div className="hidden lg:flex items-center gap-10 text-[11px] font-black uppercase tracking-[3px] text-gray-400">
          <button onClick={()=>setView('HOME')} className={view === 'HOME' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'হোম' : 'Home'}</button>
          <button onClick={()=>setView('MENU')} className={view === 'MENU' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'মেনু' : 'Menu'}</button>
          <button onClick={()=>setView('WISHLIST')} className={view === 'WISHLIST' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'পছন্দ' : 'Wishlist'}</button>
          <button onClick={()=>setLanguage(language === 'BN' ? 'EN' : 'BN')} className="text-gray-900 border-x px-4 border-gray-100 hover:text-red-600 transition-colors">{language}</button>
        </div>

        <div className="flex items-center gap-3 lg:gap-6">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 lg:w-12 lg:h-12 bg-gray-50 text-gray-800 rounded-2xl flex items-center justify-center shadow-inner group">
            <i className="fas fa-shopping-basket text-lg group-hover:-translate-y-0.5 transition-transform"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[9px] w-5 h-5 rounded-full flex items-center justify-center ring-4 ring-white font-black">{cart.length}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 lg:w-12 lg:h-12 rounded-2xl border-2 border-white overflow-hidden shadow-xl bg-red-600 group">
              {currentUser.profileImage ? <img src={currentUser.profileImage} className="w-full h-full object-cover group-hover:scale-110 transition-transform" /> : <div className="w-full h-full flex items-center justify-center text-white font-black">{currentUser.name.charAt(0)}</div>}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl" onClick={() => setView('LOGIN')}>{language === 'BN' ? 'লগইন' : 'Login'}</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-6 lg:py-12">
        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto animate-slide-up bg-white p-14 rounded-[60px] shadow-3xl mt-12 border border-gray-100 relative overflow-hidden group">
             <div className="absolute top-0 right-0 w-32 h-32 bg-red-600/5 rounded-full blur-3xl -mr-16 -mt-16"></div>
             <div className="w-16 h-16 bg-red-600 text-white rounded-[20px] flex items-center justify-center text-3xl mx-auto mb-10 shadow-2xl ring-8 ring-red-50 group-hover:rotate-6 transition-transform"><i className="fas fa-fingerprint"></i></div>
             <h2 className="text-3xl font-black text-center mb-4 text-gray-800 tracking-tighter uppercase">Identity Access</h2>
             <p className="text-center text-[9px] font-black text-gray-300 uppercase tracking-[4px] mb-12">Privileged Node Verification Required</p>
             <div className="space-y-8">
                <Input label="Cloud Email" value={formEmail} onChange={(e:any)=>setFormEmail(e.target.value)} />
                <div className="relative">
                  <Input label="Secure Secret" type="password" value={formPass} onChange={(e:any)=>setFormPass(e.target.value)} />
                  <i className="fas fa-lock absolute right-8 bottom-7 text-gray-200 pointer-events-none group-focus-within:text-red-500 transition-colors"></i>
                </div>
                <Button fullWidth size="lg" className="rounded-[30px] py-7 text-2xl shadow-xl shadow-red-100 relative overflow-hidden group/btn" onClick={() => handleAuth(false)}>
                   <span className="relative z-10">Sync Identity</span>
                   <div className="absolute inset-0 bg-gradient-to-r from-red-600 to-orange-500 opacity-0 group-hover/btn:opacity-100 transition-opacity"></div>
                </Button>
                <div className="flex justify-center">
                  <button className="text-[10px] text-gray-400 font-black uppercase tracking-[5px] cursor-pointer hover:text-red-600 transition-colors" onClick={()=>setView('REGISTER')}>Initialize New Node</button>
                </div>
             </div>
          </div>
        )}

        {view === 'REGISTER' && (
          <div className="max-w-md mx-auto animate-slide-up bg-white p-14 rounded-[60px] shadow-3xl mt-12 border border-gray-100">
             <div className="w-16 h-16 bg-red-600 text-white rounded-[20px] flex items-center justify-center text-3xl mx-auto mb-10 shadow-2xl ring-8 ring-red-50"><i className="fas fa-user-plus"></i></div>
             <h2 className="text-3xl font-black text-center mb-4 text-gray-800 tracking-tighter uppercase">Join Network</h2>
             <p className="text-center text-[9px] font-black text-gray-300 uppercase tracking-[4px] mb-12">New Physical Entity Registration</p>
             <div className="space-y-6">
                <Input label="Display Identity" value={formName} onChange={(e:any)=>setFormName(e.target.value)} />
                <Input label="Cloud Email" value={formEmail} onChange={(e:any)=>setFormEmail(e.target.value)} />
                <Input label="Secure Phone" value={formPhone} onChange={(e:any)=>setFormPhone(e.target.value)} />
                <Input label="Secure Secret" type="password" value={formPass} onChange={(e:any)=>setFormPass(e.target.value)} />
                <Button fullWidth size="lg" className="rounded-[30px] py-7 text-2xl shadow-xl shadow-red-100" onClick={() => handleAuth(true)}>Initialize Node</Button>
                <div className="flex justify-center">
                  <button className="text-[10px] text-gray-400 font-black uppercase tracking-[5px] cursor-pointer hover:text-red-600 transition-colors" onClick={()=>setView('LOGIN')}>Synchronize Existing Node</button>
                </div>
             </div>
          </div>
        )}

        {/* Existing views logic (HOME, MENU, etc.) follows... */}
        {view === 'HOME' && (
          <div className="animate-slide-up space-y-24">
            <header className="relative h-[450px] lg:h-[700px] rounded-[60px] lg:rounded-[100px] overflow-hidden shadow-3xl group">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover transition-transform duration-[10s] group-hover:scale-110" />
               <div className="absolute inset-0 bg-gradient-to-r from-black/90 via-black/40 to-transparent flex flex-col justify-center px-12 lg:px-24">
                  <span className="text-red-600 font-black uppercase tracking-[8px] text-[10px] mb-6 block animate-slide-up">Authentic Taste of Dhaka</span>
                  <h2 className="text-5xl lg:text-[120px] font-black text-white leading-[0.85] mb-12 tracking-tighter animate-slide-up [animation-delay:0.1s]">
                    {language === 'BN' ? 'আসল স্বাদ' : 'Real Taste'}<br/>
                    <span className="text-red-600">{language === 'BN' ? 'সেরা খাবার' : 'Fine Food'}</span>
                  </h2>
                  <Button size="lg" className="rounded-[35px] w-fit px-16 py-8 text-2xl shadow-2xl shadow-red-600/20 animate-slide-up [animation-delay:0.2s]" onClick={() => setView('MENU')}>{language === 'BN' ? 'মেনু দেখুন' : 'Explore Menu'}</Button>
               </div>
            </header>
            <section>
              <div className="flex items-end justify-between mb-12">
                <div>
                  <h3 className="text-4xl lg:text-7xl font-black text-gray-800 tracking-tighter leading-none">{language === 'BN' ? 'আপনার জন্য সেরা' : 'Editor\'s Picks'}</h3>
                  <p className="text-[10px] text-gray-400 font-black uppercase tracking-[5px] mt-4">Curated for your palate</p>
                </div>
                <button onClick={()=>setView('MENU')} className="text-red-600 font-black text-[10px] uppercase tracking-widest hover:underline pb-2 transition-all">View All Menu</button>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-12">
                 {MOCK_MENU.slice(0, 4).map(item => (
                   <ProductCard 
                     key={item.id} 
                     item={item} 
                     language={language} 
                     isWished={currentUser?.wishlist.includes(item.id)}
                     onWishlist={() => toggleWishlist(item.id)}
                     onDetails={() => { setSelectedProduct(item); setIsSubscriptionMode(false); }}
                     onAdd={(item: any) => { setCart([...cart, {item, qty:1}]); showToast("Added to Bag", "success"); }} 
                   />
                 ))}
              </div>
            </section>
          </div>
        )}

        {view === 'MENU' && (
          <div className="animate-slide-up space-y-16">
             <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-12">
                <div>
                   <h2 className="text-6xl lg:text-9xl font-black text-gray-800 tracking-tighter leading-none">{language === 'BN' ? 'মেনু গ্যালারি' : 'The Menu'}</h2>
                   <p className="text-[11px] text-gray-400 font-black uppercase tracking-[8px] mt-6">Taste the perfection in every bite</p>
                </div>
                <div className="flex flex-col sm:flex-row gap-4 w-full lg:w-auto">
                   <div className="relative group flex-1">
                      <i className="fas fa-search absolute left-7 top-1/2 -translate-y-1/2 text-gray-300"></i>
                      <input 
                        type="text" 
                        placeholder={language === 'BN' ? 'খুঁজুন...' : 'Search delicacies...'}
                        className="w-full lg:w-96 bg-white border-2 border-gray-100 rounded-[30px] pl-16 pr-8 py-5 font-black text-sm outline-none focus:border-red-600/30 shadow-sm transition-all focus:ring-8 ring-red-50/50"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                      />
                   </div>
                   <div className="flex gap-2 overflow-x-auto pb-4 scrollbar-hide">
                      {['All', 'Biryani', 'Curry', 'Kebab', 'Desserts'].map(cat => (
                        <button 
                          key={cat}
                          onClick={() => setActiveCategory(cat)}
                          className={`px-8 py-5 rounded-[25px] text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all border-2 ${
                            activeCategory === cat ? 'bg-gray-900 border-gray-900 text-white shadow-2xl scale-105' : 'bg-white border-gray-100 text-gray-400 hover:border-red-100 hover:text-red-600'
                          }`}
                        >
                          {cat}
                        </button>
                      ))}
                   </div>
                </div>
             </div>
             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-12">
                {filteredMenu.map(item => (
                  <ProductCard 
                    key={item.id} 
                    item={item} 
                    language={language} 
                    isWished={currentUser?.wishlist.includes(item.id)}
                    onWishlist={() => toggleWishlist(item.id)}
                    onDetails={() => { setSelectedProduct(item); setIsSubscriptionMode(false); }}
                    onAdd={(item: any) => { setCart([...cart, {item, qty:1}]); showToast("Added to Bag", "success"); }} 
                  />
                ))}
             </div>
          </div>
        )}

        {view === 'WISHLIST' && (
          <div className="animate-slide-up space-y-16">
             <h2 className="text-6xl lg:text-9xl font-black text-gray-800 tracking-tighter leading-none">{language === 'BN' ? 'আমার পছন্দ' : 'Favorites'}</h2>
             {wishlistItems.length > 0 ? (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-12">
                   {wishlistItems.map(item => (
                     <ProductCard 
                       key={item.id} 
                       item={item} 
                       language={language} 
                       isWished={true}
                       onWishlist={() => toggleWishlist(item.id)}
                       onDetails={() => { setSelectedProduct(item); setIsSubscriptionMode(false); }}
                       onAdd={(item: any) => { setCart([...cart, {item, qty:1}]); showToast("Added to Bag", "success"); }} 
                     />
                   ))}
                </div>
             ) : (
                <div className="flex flex-col items-center justify-center py-40 px-6 bg-white rounded-[70px] border-4 border-dashed border-gray-100 relative overflow-hidden group">
                   <div className="absolute inset-0 pattern-grid opacity-5"></div>
                   <div className="relative w-40 h-40 mb-12 animate-bounce-gentle">
                      <div className="absolute inset-0 bg-red-100 rounded-full blur-3xl opacity-60"></div>
                      <div className="absolute inset-0 flex items-center justify-center text-red-600 drop-shadow-2xl"><i className="fas fa-heart text-8xl"></i></div>
                   </div>
                   <div className="text-center relative z-10 max-w-lg">
                      <h3 className="text-3xl lg:text-5xl font-black text-gray-800 tracking-tighter mb-4">Collection Void</h3>
                      <p className="text-gray-400 font-bold text-lg leading-relaxed mb-10">Your personal selection of favorites is empty. Start curating your BFC dream list today!</p>
                      <Button size="lg" className="rounded-[30px] px-12 py-6 text-xl shadow-2xl shadow-red-100" onClick={()=>setView('MENU')}>Discover Delicacies</Button>
                   </div>
                </div>
             )}
          </div>
        )}
      </main>

      <ChatBot />

      {/* Persistent Mobile Navigation */}
      <div className="lg:hidden fixed bottom-0 w-full bg-white px-12 py-10 flex justify-between items-center z-50 border-t border-gray-100 shadow-[0_-20px_60px_-15px_rgba(0,0,0,0.1)] rounded-t-[50px] backdrop-blur-xl bg-white/90">
         <button onClick={()=>setView('HOME')} className={view === 'HOME' ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-home text-2xl transition-all"></i></button>
         <button onClick={()=>setView('MENU')} className={view === 'MENU' ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-utensils text-2xl transition-all"></i></button>
         <button onClick={()=>setView('WISHLIST')} className={view === 'WISHLIST' ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-heart text-2xl transition-all"></i></button>
         <button onClick={()=>setView('CART')} className={view === 'CART' ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-shopping-bag text-2xl transition-all"></i></button>
         <button onClick={()=>currentUser ? setView('PROFILE') : setView('LOGIN')} className={(view === 'PROFILE' || view === 'REGISTER' || view === 'LOGIN') ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-user-circle text-2xl transition-all"></i></button>
      </div>
    </div>
  );
};

const ProductCard = ({ item, language, onAdd, onWishlist, isWished, onDetails }: any) => (
  <div onClick={onDetails} className="bg-white rounded-[60px] overflow-hidden shadow-sm border border-gray-50 hover:shadow-3xl hover:-translate-y-6 transition-all duration-700 flex flex-col group relative cursor-pointer">
    <div className="h-72 p-6 overflow-hidden relative">
      <img src={item.image} className="w-full h-full rounded-[50px] object-cover group-hover:scale-125 transition-transform duration-[2s]" />
      <button onClick={(e) => { e.stopPropagation(); onWishlist(); }} className={`absolute top-10 right-10 w-14 h-14 rounded-3xl flex items-center justify-center backdrop-blur-2xl shadow-2xl transition-all border ${isWished ? 'bg-red-600 text-white border-red-500 scale-110' : 'bg-white/90 text-gray-300 border-white hover:text-red-600 hover:scale-110'}`}><i className="fas fa-heart text-lg"></i></button>
