export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { MOCK_ORDERS, MOCK_MENU } from '../constants';
import { Button } from './Button';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
}

interface AdminToast {
  message: string;
  type: 'success' | 'error' | 'info';
  id: number;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, orders: 240, volume: 85 },
  { name: 'Sun', sales: 3800, orders: 198, volume: 70 },
  { name: 'Mon', sales: 5200, orders: 310, volume: 110 },
  { name: 'Tue', sales: 4800, orders: 280, volume: 95 },
  { name: 'Wed', sales: 6200, orders: 390, volume: 140 },
  { name: 'Thu', sales: 5800, orders: 340, volume: 125 },
  { name: 'Fri', sales: 8500, orders: 480, volume: 180 },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ userRole, onLogout }) => {
  const [activeTab, setActiveTab] = useState(userRole === UserRole.STAFF ? 'orders' : 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [orders, setOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [toasts, setToasts] = useState<AdminToast[]>([]);

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  };

  // Mock JWT Security Verification Layer
  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (!savedUser) {
      onLogout();
      return;
    }

    try {
      const user = JSON.parse(savedUser) as User;
      const payloadPart = user.sessionToken?.split('.')[1];
      if (!payloadPart) throw new Error('Malformed Token');

      const payload = JSON.parse(atob(payloadPart));
      if (payload.role !== userRole || payload.exp < Date.now()) {
        throw new Error('Identity Verification Failed');
      }

      setIsAuthorized(true);
      showToast(`Identity Trace Verified: Role ${userRole}`, 'success');
    } catch (err) {
      console.error('Security Breach or Expired Token:', err);
      showToast('Security Violation: Terminal Locked', 'error');
      setTimeout(onLogout, 2000);
    }
  }, [userRole, onLogout]);

  const metrics = useMemo(() => {
    const totalRev = orders.reduce((acc, o) => acc + o.total, 0);
    const estimatedCost = totalRev * 0.62;
    const margin = totalRev > 0 ? ((totalRev - estimatedCost) / totalRev) * 100 : 0;
    return { 
      totalRev, 
      pendingCount: orders.filter(o => o.status !== OrderStatus.DELIVERED).length, 
      margin: margin.toFixed(1),
      orderCount: orders.length
    };
  }, [orders]);

  const updateOrderStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order status transitioned to ${newStatus}`, "success");
  };

  const updateStock = (itemId: string, delta: number) => {
    if (userRole === UserRole.STAFF) {
      showToast("Inventory access restricted for staff members.", "error");
      return;
    }
    setMenuItems(prev => prev.map(item => 
      item.id === itemId ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
    showToast("Stock parity synchronized", "info");
  };

  const deleteMenuItem = (itemId: string) => {
    if (userRole !== UserRole.ADMIN) {
      showToast("Operation Restricted: Admin clearance required.", "error");
      return;
    }
    if (window.confirm("Purge asset from database?")) {
      setMenuItems(prev => prev.filter(i => i.id !== itemId));
      showToast("Asset Purged", "success");
    }
  };

  const canAccess = (tab: string) => {
    switch (userRole) {
      case UserRole.ADMIN: return true;
      case UserRole.MANAGER: return ['dashboard', 'orders', 'inventory'].includes(tab);
      case UserRole.STAFF: return ['orders'].includes(tab);
      default: return false;
    }
  };

  if (!isAuthorized) {
    return (
      <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white">
         <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin mb-8"></div>
         <p className="text-[10px] font-black uppercase tracking-[6px] animate-pulse">Initializing Secure Shell...</p>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-[#F1F3F6] overflow-hidden font-sans select-none">
      <div className="fixed top-8 right-8 z-[200] space-y-3 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-center gap-4 px-8 py-5 rounded-[25px] shadow-3xl border border-gray-100 bg-white animate-slide-up">
            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
              <i className={`fas ${t.type === 'error' ? 'fa-triangle-exclamation' : 'fa-check'}`}></i>
            </div>
            <p className="font-black text-[11px] uppercase tracking-widest text-gray-800">{t.message}</p>
          </div>
        ))}
      </div>

      {/* Modern Sidebar with filtered items */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[100] w-80 bg-white shadow-2xl transition-transform duration-700 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-10 border-b border-gray-50 flex items-center gap-5">
          <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white shadow-2xl rotate-3 ring-4 ring-red-50">
             <i className="fas fa-shield-halved"></i>
          </div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
        </div>

        <nav className="p-8 space-y-3">
          {canAccess('dashboard') && <SidebarBtn active={activeTab === 'dashboard'} onClick={()=>setActiveTab('dashboard')} icon="fa-chart-pie" label="Analytics" />}
          {canAccess('orders') && <SidebarBtn active={activeTab === 'orders'} onClick={()=>setActiveTab('orders')} icon="fa-list-check" label="Orders" />}
          {canAccess('inventory') && <SidebarBtn active={activeTab === 'inventory'} onClick={()=>setActiveTab('inventory')} icon="fa-box-open" label="Inventory" />}
          {canAccess('staff') && <SidebarBtn active={activeTab === 'staff'} onClick={()=>setActiveTab('staff')} icon="fa-users-gear" label="Personnel" />}
          {canAccess('reports') && <SidebarBtn active={activeTab === 'reports'} onClick={()=>setActiveTab('reports')} icon="fa-file-invoice-dollar" label="Financials" />}
        </nav>

        <div className="absolute bottom-0 w-full p-8 border-t border-gray-50 bg-white">
          <button onClick={onLogout} className="w-full flex items-center justify-center gap-5 py-5 rounded-[25px] bg-gray-50 text-gray-400 font-black hover:bg-red-50 hover:text-red-600 transition-all uppercase tracking-[4px] text-[10px]">
            Log out Node
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden bg-[#F1F3F6]">
        <header className="h-24 bg-white border-b border-gray-100 flex items-center justify-between px-12 shrink-0 z-50">
          <div className="flex items-center gap-6 lg:hidden">
             <button onClick={()=>setSidebarOpen(true)} className="p-3 text-gray-400"><i className="fas fa-bars text-2xl"></i></button>
             <h2 className="text-2xl font-black text-gray-800 tracking-tight capitalize">{activeTab}</h2>
          </div>
          <h2 className="hidden lg:block text-2xl font-black text-gray-800 tracking-tight capitalize">{activeTab} Node</h2>
          <div className="flex items-center gap-8">
             <span className="hidden sm:flex items-center gap-3 text-[10px] font-black text-emerald-500 uppercase tracking-widest"><span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.5)]"></span> Terminal Live</span>
             <div className="flex items-center gap-4 bg-gray-900 px-6 py-2.5 rounded-2xl text-white">
                <i className="fas fa-user-shield text-red-500"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">{userRole}</span>
             </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-12 scrollbar-hide animate-slide-up">
          {activeTab === 'dashboard' && canAccess('dashboard') && (
            <div className="space-y-12">
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-8">
                 {userRole === UserRole.ADMIN ? (
                    <>
                      <DashboardStat title="Total Revenue" value={`৳${metrics.totalRev.toLocaleString()}`} icon="fa-bangladeshi-taka-sign" color="text-green-600" />
                      <DashboardStat title="Profit Margin" value={`${metrics.margin}%`} icon="fa-chart-line" color="text-blue-500" />
                    </>
                 ) : (
                    <>
                      <DashboardStat title="Order Volume" value={metrics.orderCount} icon="fa-chart-simple" color="text-purple-600" />
                      <DashboardStat title="Hub Status" value="Online" icon="fa-server" color="text-emerald-500" />
                    </>
                 )}
                 <DashboardStat title="Queue Count" value={metrics.pendingCount} icon="fa-clock" color="text-orange-500" />
                 <DashboardStat title="Low Stock Assets" value={menuItems.filter(i => i.stock < 10).length} icon="fa-triangle-exclamation" color="text-red-500" />
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-3 gap-10">
                 <div className="xl:col-span-2 bg-white p-12 rounded-[60px] shadow-sm border border-gray-100 min-h-[500px]">
                    <h3 className="text-2xl font-black text-gray-800 mb-10 tracking-tighter">Performance Spectrum</h3>
                    <div className="h-[350px]">
                       <ResponsiveContainer width="100%" height="100%">
                          <AreaChart data={ANALYTICS_DATA}>
                             <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                             <Tooltip contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 20px 40px -10px rgba(0,0,0,0.1)' }} />
                             <Area type="monotone" dataKey={userRole === UserRole.ADMIN ? "sales" : "volume"} stroke="#dc2626" strokeWidth={5} fill="url(#colorGrad)" />
                             <defs>
                                <linearGradient id="colorGrad" x1="0" y1="0" x2="0" y2="1">
                                   <stop offset="5%" stopColor="#dc2626" stopOpacity={0.15}/>
                                   <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                                </linearGradient>
                             </defs>
                          </AreaChart>
                       </ResponsiveContainer>
                    </div>
                 </div>
                 <div className="bg-white p-12 rounded-[60px] shadow-sm border border-gray-100">
                    <h3 className="text-2xl font-black text-gray-800 mb-10 tracking-tighter">Inventory Criticals</h3>
                    <div className="space-y-8">
                       {menuItems.filter(i => i.stock < 25).sort((a,b) => a.stock - b.stock).slice(0, 5).map(i => (
                          <div key={i.id} className="flex items-center gap-6 p-5 rounded-[30px] bg-gray-50 border border-gray-100 group hover:scale-105 transition-transform">
