                                <p className="font-black text-gray-800 text-sm truncate">{i.name}</p>
                                <div className="h-1.5 w-full bg-gray-200 rounded-full mt-3 overflow-hidden">
                                   <div className={`h-full rounded-full ${i.stock < 10 ? 'bg-red-600' : 'bg-orange-500'}`} style={{ width: `${(i.stock/100)*100}%` }}></div>
