                          </div>
                       ))}
                    </div>
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'staff' && canAccess('staff') && (
            <div className="space-y-10">
               <div className="flex justify-between items-center">
                  <h2 className="text-4xl font-black text-gray-800 tracking-tighter">Personnel Directory</h2>
                  {userRole === UserRole.ADMIN && <Button className="rounded-2xl px-8">Sync New Identity</Button>}
               </div>
               <div className="bg-white rounded-[60px] shadow-sm border border-gray-100 overflow-hidden">
                  <table className="w-full text-left border-collapse">
                     <thead>
                        <tr className="bg-gray-50/50">
                           <th className="p-10 text-[11px] font-black uppercase text-gray-400 tracking-[5px]">Identified Entity</th>
                           <th className="p-10 text-[11px] font-black uppercase text-gray-400 tracking-[5px]">Access Node</th>
                           <th className="p-10 text-[11px] font-black uppercase text-gray-400 tracking-[5px]">Pulse Status</th>
                           <th className="p-10 text-[11px] font-black uppercase text-gray-400 tracking-[5px]">Control</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-gray-50">
                        <StaffRow name="Rahman K." role="MANAGER" status="ACTIVE" color="emerald" />
                        <StaffRow name="Hussain A." role="STAFF (KITCHEN)" status="BREAK" color="orange" />
                        <StaffRow name="Malik S." role="STAFF (LOGISTICS)" status="TRANSIT" color="blue" />
                        <StaffRow name="Zaman F." role="STAFF" status="OFFLINE" color="gray" />
                     </tbody>
