                   <div key={o.id} className="bg-white p-10 rounded-[60px] shadow-sm border border-gray-100 flex flex-col gap-8 hover:shadow-2xl hover:-translate-y-2 transition-all">
                      <div className="flex justify-between items-start">
                         <div className="flex items-center gap-6">
                            <div className="w-16 h-16 bg-gray-900 text-white rounded-[25px] flex items-center justify-center font-black text-xl shadow-2xl ring-4 ring-gray-100">{o.id.split('-')[1]}</div>
                            <div className="min-w-0">
                               <p className="font-black text-2xl text-gray-800 truncate tracking-tighter">{o.customerName}</p>
                               <p className="text-[10px] text-gray-400 font-black uppercase tracking-[4px] truncate">{o.paymentMethod} • {o.createdAt.split('T')[1].slice(0,5)}</p>
                            </div>
                         </div>
                         <span className={`px-4 py-2 rounded-2xl text-[9px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-100 text-emerald-700' : 'bg-red-50 text-red-600'}`}>{o.status}</span>
                      </div>
                      <div className="bg-gray-50 rounded-[35px] p-8 space-y-3">
                         {o.items.map((i, idx) => (
                           <div key={idx} className="flex justify-between text-xs font-bold text-gray-600 border-b border-gray-200 pb-3 last:border-0 last:pb-0">
                             <span>{i.name} <span className="text-gray-300 ml-2">x{i.quantity}</span></span>
                             {userRole !== UserRole.STAFF && <span className="font-black text-gray-800">৳{i.price * i.quantity}</span>}
                           </div>
                         ))}
                      </div>
                      <div className="space-y-4">
                         <label className="text-[9px] font-black uppercase text-gray-300 tracking-[5px] ml-6">Transition Status</label>
