import React, { useState, useMemo, useEffect } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { Button } from './Button';
import { AreaChart, Area, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, orders: 240, volume: 85 },
  { name: 'Sun', sales: 3800, orders: 198, volume: 70 },
  { name: 'Mon', sales: 5200, orders: 310, volume: 110 },
  { name: 'Tue', sales: 4800, orders: 280, volume: 95 },
  { name: 'Wed', sales: 6200, orders: 390, volume: 140 },
  { name: 'Thu', sales: 5800, orders: 340, volume: 125 },
  { name: 'Fri', sales: 8500, orders: 480, volume: 180 },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ userRole, onLogout, menuItems, setMenuItems, orders, setOrders }) => {
  const [activeTab, setActiveTab] = useState(userRole === UserRole.STAFF ? 'orders' : 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [toasts, setToasts] = useState<any[]>([]);

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (!savedUser) return onLogout();
    try {
      const user = JSON.parse(savedUser) as User;
      const payload = JSON.parse(atob(user.sessionToken!.split('.')[1]));
      if (payload.role !== userRole || payload.exp < Date.now()) throw new Error('Auth Failed');
      setIsAuthorized(true);
      showToast(`Identity Verified: Role ${userRole}`, 'success');
    } catch {
      showToast('Security Breach: Terminal Locked', 'error');
      setTimeout(onLogout, 2000);
    }
  }, [userRole, onLogout]);

  const metrics = useMemo(() => {
    const totalRev = orders.reduce((acc, o) => acc + o.total, 0);
    const estimatedCost = totalRev * 0.62;
    const margin = totalRev > 0 ? ((totalRev - estimatedCost) / totalRev) * 100 : 0;
    return { totalRev, pendingCount: orders.filter(o => o.status !== OrderStatus.DELIVERED).length, margin: margin.toFixed(1), orderCount: orders.length };
  }, [orders]);

  const canAccess = (tab: string) => {
    switch (userRole) {
      case UserRole.ADMIN: return true;
      case UserRole.MANAGER: return ['dashboard', 'orders', 'inventory'].includes(tab);
      case UserRole.STAFF: return ['orders'].includes(tab);
      default: return false;
    }
  };

  if (!isAuthorized) return <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white"><div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div><p className="mt-8 text-[10px] font-black uppercase tracking-[6px]">Initializing Secure Shell...</p></div>;

  return (
    <div className="flex h-screen bg-[#F1F3F6] overflow-hidden font-sans select-none">
      <div className="fixed top-8 right-8 z-[200] space-y-3 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-center gap-4 px-8 py-5 rounded-[25px] shadow-3xl border border-gray-100 bg-white animate-slide-up">
            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}><i className={`fas ${t.type === 'error' ? 'fa-triangle-exclamation' : 'fa-check'}`}></i></div>
            <p className="font-black text-[11px] uppercase tracking-widest text-gray-800">{t.message}</p>
          </div>
        ))}
      </div>

      <aside className={`fixed lg:static inset-y-0 left-0 z-[100] w-80 bg-white shadow-2xl transition-transform transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-10 border-b border-gray-50 flex items-center gap-5">
          <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white shadow-2xl rotate-3 ring-4 ring-red-50"><i className="fas fa-shield-halved"></i></div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
        </div>
        <nav className="p-8 space-y-3">
          {canAccess('dashboard') && <SidebarBtn active={activeTab === 'dashboard'} onClick={()=>setActiveTab('dashboard')} icon="fa-chart-pie" label="Analytics" />}
          {canAccess('orders') && <SidebarBtn active={activeTab === 'orders'} onClick={()=>setActiveTab('orders')} icon="fa-list-check" label="Orders" />}
          {canAccess('inventory') && <SidebarBtn active={activeTab === 'inventory'} onClick={()=>setActiveTab('inventory')} icon="fa-box-open" label="Inventory" />}
          {canAccess('staff') && <SidebarBtn active={activeTab === 'staff'} onClick={()=>setActiveTab('staff')} icon="fa-users-gear" label="Personnel" />}
          {canAccess('reports') && <SidebarBtn active={activeTab === 'reports'} onClick={()=>setActiveTab('reports')} icon="fa-file-invoice-dollar" label="Financials" />}
        </nav>
        <div className="absolute bottom-0 w-full p-8 border-t border-gray-50 bg-white"><button onClick={onLogout} className="w-full flex items-center justify-center gap-5 py-5 rounded-[25px] bg-gray-50 text-gray-400 font-black hover:bg-red-50 hover:text-red-600 transition-all uppercase tracking-[4px] text-[10px]">Log out Node</button></div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden bg-[#F1F3F6]">
        <header className="h-24 bg-white border-b border-gray-100 flex items-center justify-between px-12 shrink-0 z-50">
          <h2 className="text-2xl font-black text-gray-800 tracking-tight capitalize">{activeTab} Node</h2>
          <div className="flex items-center gap-4 bg-gray-900 px-6 py-2.5 rounded-2xl text-white"><i className="fas fa-user-shield text-red-500"></i><span className="text-[10px] font-black uppercase tracking-widest">{userRole}</span></div>
        </header>
        <div className="flex-1 overflow-y-auto p-12 scrollbar-hide">
          {activeTab === 'dashboard' && canAccess('dashboard') && (
            <div className="space-y-12 animate-slide-up">
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-8">
                 <DashboardStat title="Revenue" value={`৳${metrics.totalRev.toLocaleString()}`} icon="fa-bangladeshi-taka-sign" color="text-green-600" />
                 <DashboardStat title="Queue" value={metrics.pendingCount} icon="fa-clock" color="text-orange-500" />
                 <DashboardStat title="Orders" value={metrics.orderCount} icon="fa-list" color="text-purple-600" />
                 <DashboardStat title="Critical Stock" value={menuItems.filter(i => i.stock < 10).length} icon="fa-triangle-exclamation" color="text-red-500" />
              </div>
              <div className="bg-white p-12 rounded-[60px] shadow-sm border border-gray-100 min-h-[500px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={ANALYTICS_DATA}><Area type="monotone" dataKey="sales" stroke="#dc2626" fill="#fee2e2" strokeWidth={5} /></AreaChart>
                  </ResponsiveContainer>
              </div>
            </div>
          )}
          {activeTab === 'orders' && (
            <div className="grid grid-cols-1 md:grid-cols-2 2xl:grid-cols-3 gap-10 animate-slide-up">
              {orders.map(o => (
                <div key={o.id} className="bg-white p-10 rounded-[60px] shadow-sm border border-gray-100 flex flex-col gap-8">
                  <div className="flex justify-between items-start">
                    <div><p className="font-black text-2xl text-gray-800 truncate tracking-tighter">{o.customerName}</p><p className="text-[10px] text-gray-400 font-black uppercase">{o.id} • {o.paymentMethod}</p></div>
                    <span className="px-4 py-2 rounded-2xl text-[9px] font-black uppercase bg-red-50 text-red-600">{o.status}</span>
                  </div>
                  <select 
                    className="w-full bg-gray-900 text-white rounded-[25px] text-[11px] font-black uppercase p-6 cursor-pointer"
                    value={o.status}
                    onChange={(e) => {
                      setOrders(prev => prev.map(order => order.id === o.id ? { ...order, status: e.target.value as OrderStatus } : order));
                      showToast(`Order updated`, 'success');
                    }}
                  >
                    {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
              ))}
            </div>
          )}
          {activeTab === 'inventory' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 2xl:grid-cols-4 gap-10 animate-slide-up">
              {menuItems.map(item => (
                <div key={item.id} className="bg-white p-8 rounded-[55px] shadow-sm border border-gray-100 flex flex-col group">
                  <div className="flex items-center gap-6 mb-10">
                    <img src={item.image} className="w-20 h-20 rounded-[30px] object-cover" />
                    <div><h4 className="font-black text-lg text-gray-800 truncate">{item.name}</h4><p className="text-[10px] text-gray-400 font-black uppercase">{item.category}</p></div>
                  </div>
                  <div className="flex justify-between items-center px-2 mb-8"><span className="text-[10px] font-black text-gray-300 uppercase tracking-[4px]">Stock</span><span className={`text-3xl font-black ${item.stock < 10 ? 'text-red-600' : 'text-gray-900'}`}>{item.stock}</span></div>
                  <div className="flex gap-4">
                    <button onClick={() => setMenuItems(prev => prev.map(i => i.id === item.id ? { ...i, stock: Math.max(0, i.stock - 1) } : i))} className="flex-1 bg-gray-50 py-4 rounded-3xl font-black">-</button>
                    <button onClick={() => setMenuItems(prev => prev.map(i => i.id === item.id ? { ...i, stock: i.stock + 1 } : i))} className="flex-1 bg-gray-900 text-white py-4 rounded-3xl font-black">+</button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

const SidebarBtn = ({ active, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-6 px-8 py-5 rounded-[25px] transition-all duration-500 transform ${active ? 'bg-red-600 text-white shadow-2xl scale-[1.05] ring-8 ring-red-50' : 'text-gray-400 hover:text-red-600 hover:bg-red-50'}`}>
    <div className="w-8 flex justify-center"><i className={`fas ${icon} text-xl`}></i></div>
    <span className="font-black text-[11px] uppercase tracking-[4px] leading-none">{label}</span>
  </button>
);

const DashboardStat = ({ title, value, icon, color }: any) => (
  <div className="bg-white p-10 rounded-[55px] shadow-sm border border-gray-100 flex items-center gap-8 group hover:shadow-2xl transition-all">
    <div className={`w-16 h-16 bg-gray-50 rounded-[25px] flex items-center justify-center text-2xl ${color} shadow-inner shrink-0`}><i className={`fas ${icon}`}></i></div>
    <div className="min-w-0"><p className="text-[10px] font-black text-gray-300 uppercase tracking-[4px] mb-2 truncate">{title}</p><h4 className="text-3xl font-black text-gray-900 tracking-tighter leading-none">{value}</h4></div>
  </div>
);

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'info';
  id: number;
}

const MOCK_AUTH_DB = {
  'admin@bfc.com': { pass: 'admin123', role: UserRole.ADMIN, name: 'Root Admin' },
  'manager@bfc.com': { pass: 'manager456', role: UserRole.MANAGER, name: 'Node Manager' },
  'staff@bfc.com': { pass: 'staff789', role: UserRole.STAFF, name: 'Logistics Staff' }
};

const App: React.FC = () => {
  // Global Application State
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);

  // Navigation & UI State
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE' | 'PAYMENT' | 'REGISTER' | 'WISHLIST'>('HOME');
  const [language, setLanguage] = useState<'EN' | 'BN'>('BN');
  const [selectedProduct, setSelectedProduct] = useState<MenuItem | null>(null);
  const [isSubscriptionMode, setIsSubscriptionMode] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  // Form State
  const [formName, setFormName] = useState('');
  const [formEmail, setFormEmail] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [formPass, setFormPass] = useState('');
  const [deliveryZone, setDeliveryZone] = useState('Gulshan Node');
  const [deliverySlot, setDeliverySlot] = useState('Immediate (ETA 35m)');
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'CARD' | 'COD'>('BKASH');
  const [isProcessing, setIsProcessing] = useState(false);
  const [orderCode, setOrderCode] = useState('');
  const [cardDetails, setCardDetails] = useState({ number: '', exp: '', cvv: '', name: '' });
  const [transactionId, setTransactionId] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  };

  const generateMockToken = (role: UserRole, email: string) => {
    const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
    const payload = btoa(JSON.stringify({ role, email, exp: Date.now() + 86400000 }));
    return `${header}.${payload}.bfc-signature`;
  };

  const validateSession = (user: User) => {
    if (!user.sessionToken) return false;
    try {
      const payload = JSON.parse(atob(user.sessionToken.split('.')[1]));
      return payload.exp > Date.now();
    } catch { return false; }
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (savedUser) {
      const parsed = JSON.parse(savedUser) as User;
      if (validateSession(parsed)) {
        setCurrentUser(parsed);
        setFormName(parsed.name);
        setFormEmail(parsed.email);
        setFormPhone(parsed.phone);
      } else {
        localStorage.removeItem('bfc_user_profile');
      }
    }
    const savedCart = localStorage.getItem('bfc_cart');
    if (savedCart) setCart(JSON.parse(savedCart));
  }, []);

  useEffect(() => {
    if (currentUser) localStorage.setItem('bfc_user_profile', JSON.stringify(currentUser));
    else localStorage.removeItem('bfc_user_profile');
  }, [currentUser]);

  useEffect(() => {
    localStorage.setItem('bfc_cart', JSON.stringify(cart));
  }, [cart]);

  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [searchQuery, activeCategory, menuItems]);

  const wishlistItems = useMemo(() => {
    if (!currentUser) return [];
    return menuItems.filter(item => currentUser.wishlist.includes(item.id));
  }, [currentUser?.wishlist, menuItems]);

  const handleAddToCart = (item: MenuItem, isSub: boolean = false) => {
    setCart(prev => {
      const existing = prev.find(c => c.item.id === item.id && c.isSubscription === isSub);
      if (existing) {
        return prev.map(c => (c.item.id === item.id && c.isSubscription === isSub) ? { ...c, qty: c.qty + 1 } : c);
      }
      return [...prev, { item, qty: 1, isSubscription: isSub }];
    });
    showToast("Added to Bag", "success");
  };

  const handleAuth = async (isRegistering: boolean = false) => {
    if (!formEmail || !formPass) return showToast('Credentials Required', 'error');
    setIsAuthenticating(true);
    await new Promise(r => setTimeout(r, 1500));

    const privileged = MOCK_AUTH_DB[formEmail as keyof typeof MOCK_AUTH_DB];
    if (privileged && privileged.pass === formPass) {
      const user: User = {
        id: 'SEC-' + Math.random().toString(36).slice(7).toUpperCase(),
        name: privileged.name, email: formEmail, phone: '01700-XXXXXX',
        role: privileged.role, loyaltyPoints: 1000, tier: 'PLATINUM',
        wishlist: [], referralCode: 'BFC-MASTER',
        sessionToken: generateMockToken(privileged.role, formEmail)
      };
      setCurrentUser(user);
      showToast(`${privileged.role} Authorized`, 'success');
      setView('HOME');
    } else if (!privileged && !isRegistering) {
      const user: User = {
        id: 'U-MOCK', name: formName || 'Customer Node', email: formEmail,
        phone: '01XXXXXXXXX', role: UserRole.CUSTOMER, loyaltyPoints: 120,
        tier: 'GOLD', wishlist: [], referralCode: 'BFC-GUEST',
        sessionToken: generateMockToken(UserRole.CUSTOMER, formEmail)
      };
      setCurrentUser(user);
      showToast('Welcome back!', 'success');
      setView('HOME');
    } else if (isRegistering) {
       const user: User = {
        id: 'U-' + Date.now(), name: formName, email: formEmail,
        phone: formPhone, role: UserRole.CUSTOMER, loyaltyPoints: 0,
        tier: 'SILVER', wishlist: [], referralCode: 'BFC-' + Math.random().toString(36).slice(7).toUpperCase(),
        sessionToken: generateMockToken(UserRole.CUSTOMER, formEmail)
      };
      setCurrentUser(user);
      showToast('Registration Success', 'success');
      setView('HOME');
    } else {
      showToast('Invalid credentials', 'error');
    }
    setIsAuthenticating(false);
  };

  const subTotal = cart.reduce((acc, curr) => acc + (curr.item.price * curr.qty), 0);
  const deliveryCharge = deliveryZone.includes('Gulshan') ? 50 : 70;
  const tax = Math.round(subTotal * 0.05);
  const grandTotal = subTotal + (subTotal > 0 ? deliveryCharge + tax : 0);

  const finalizeOrder = () => {
    if (paymentMethod === 'CARD' && (!cardDetails.number || cardDetails.number.length < 16)) return showToast("Card verification failed", "error");
    if (['BKASH', 'NAGAD'].includes(paymentMethod) && !transactionId) return showToast("Trx ID required", "error");

    setIsProcessing(true);
    setTimeout(() => {
      const newOrder: Order = {
        id: 'ORD-' + Math.floor(10000 + Math.random() * 90000),
        customerId: currentUser?.id || 'GUEST',
        customerName: currentUser?.name || 'Guest',
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total: grandTotal, status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(), paymentStatus: 'PAID',
        paymentMethod, address: formPass || 'No address provided', deliveryZone, deliverySlot,
        pointsEarned: Math.floor(subTotal / 10),
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };
      setAllOrders([newOrder, ...allOrders]);
      setIsProcessing(false);
      setOrderCode(newOrder.id);
      setCart([]);
      setView('TRACKING');
      if (currentUser) {
        setCurrentUser({ ...currentUser, loyaltyPoints: currentUser.loyaltyPoints + newOrder.pointsEarned });
      }
      showToast('Protocol Transmitted', 'success');
    }, 2000);
  };

  const handleProfileUpdate = () => {
    if (currentUser) {
      setCurrentUser({ ...currentUser, name: formName, phone: formPhone });
      showToast('Identity parameters updated', 'success');
    }
  };

  if (view === 'ADMIN' && currentUser && currentUser.role !== UserRole.CUSTOMER) {
    return (
      <AdminPanel 
        userRole={currentUser.role} 
        onLogout={() => { setCurrentUser(null); setView('HOME'); }}
        menuItems={menuItems}
        setMenuItems={setMenuItems}
        orders={allOrders}
        setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans selection:bg-red-100 overflow-x-hidden">
      {isAuthenticating && (
        <div className="fixed inset-0 z-[1000] bg-gray-950/95 backdrop-blur-3xl flex flex-col items-center justify-center text-white">
           <div className="w-24 h-24 mb-10 relative">
              <div className="absolute inset-0 border-4 border-red-600/20 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-red-600 rounded-full border-t-transparent animate-spin"></div>
              <div className="absolute inset-4 bg-red-600 rounded-full animate-pulse flex items-center justify-center"><i className="fas fa-shield-halved text-xl"></i></div>
           </div>
           <h2 className="text-2xl font-black uppercase tracking-[8px]">Verifying Identity</h2>
        </div>
      )}

      <div className="fixed top-8 right-8 z-[200] space-y-4 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-center gap-4 px-8 py-5 rounded-3xl shadow-2xl border bg-white animate-slide-up border-green-100 text-green-700">
            <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark text-red-600' : 'fa-circle-check text-green-600'}`}></i>
            <p className="font-black text-[12px] uppercase tracking-wider">{t.message}</p>
          </div>
        ))}
      </div>

      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-14 py-4 flex justify-between items-center gpu">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 lg:w-12 lg:h-12 bg-red-600 rounded-[15px] flex items-center justify-center text-white text-xl lg:text-2xl font-black shadow-xl ring-4 ring-red-50">B</div>
          <h1 className="text-xl lg:text-2xl font-black text-red-600 tracking-tighter">BFC</h1>
        </div>
        <div className="hidden lg:flex items-center gap-10 text-[11px] font-black uppercase tracking-[3px] text-gray-400">
          <button onClick={()=>setView('HOME')} className={view === 'HOME' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'হোম' : 'Home'}</button>
          <button onClick={()=>setView('MENU')} className={view === 'MENU' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'মেনু' : 'Menu'}</button>
          <button onClick={()=>setView('WISHLIST')} className={view === 'WISHLIST' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'পছন্দ' : 'Wishlist'}</button>
          <button onClick={()=>setLanguage(language === 'BN' ? 'EN' : 'BN')} className="text-gray-900 border-x px-4 border-gray-100 hover:text-red-600 transition-colors">{language}</button>
        </div>
        <div className="flex items-center gap-3 lg:gap-6">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 lg:w-12 lg:h-12 bg-gray-50 text-gray-800 rounded-2xl flex items-center justify-center shadow-inner group">
            <i className="fas fa-shopping-basket text-lg group-hover:-translate-y-0.5 transition-transform"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[9px] w-5 h-5 rounded-full flex items-center justify-center ring-4 ring-white font-black">{cart.reduce((a,b)=>a+b.qty, 0)}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 lg:w-12 lg:h-12 rounded-2xl border-2 border-white overflow-hidden shadow-xl bg-red-600 group">
              {currentUser.profileImage ? <img src={currentUser.profileImage} className="w-full h-full object-cover group-hover:scale-110 transition-transform" /> : <div className="w-full h-full flex items-center justify-center text-white font-black">{currentUser.name.charAt(0)}</div>}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl" onClick={() => setView('LOGIN')}>{language === 'BN' ? 'লগইন' : 'Login'}</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-6 lg:py-12">
        {view === 'HOME' && (
          <div className="animate-slide-up space-y-24">
            <header className="relative h-[450px] lg:h-[700px] rounded-[60px] lg:rounded-[100px] overflow-hidden shadow-3xl group">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover transition-transform duration-[10s] group-hover:scale-110" />
               <div className="absolute inset-0 bg-gradient-to-r from-black/90 via-black/40 to-transparent flex flex-col justify-center px-12 lg:px-24">
                  <span className="text-red-600 font-black uppercase tracking-[8px] text-[10px] mb-6 block animate-slide-up">Authentic Taste of Dhaka</span>
                  <h2 className="text-5xl lg:text-[120px] font-black text-white leading-[0.85] mb-12 tracking-tighter animate-slide-up [animation-delay:0.1s]">
                    {language === 'BN' ? 'আসল স্বাদ' : 'Real Taste'}<br/>
                    <span className="text-red-600">{language === 'BN' ? 'সেরা খাবার' : 'Fine Food'}</span>
                  </h2>
                  <Button size="lg" className="rounded-[35px] w-fit px-16 py-8 text-2xl shadow-2xl shadow-red-600/20 animate-slide-up [animation-delay:0.2s]" onClick={() => setView('MENU')}>{language === 'BN' ? 'মেনু দেখুন' : 'Explore Menu'}</Button>
               </div>
            </header>
            <section>
              <div className="flex items-end justify-between mb-12">
                <div>
                  <h3 className="text-4xl lg:text-7xl font-black text-gray-800 tracking-tighter leading-none">{language === 'BN' ? 'আপনার জন্য সেরা' : 'Editor\'s Picks'}</h3>
                  <p className="text-[10px] text-gray-400 font-black uppercase tracking-[5px] mt-4">Curated for your palate</p>
                </div>
                <button onClick={()=>setView('MENU')} className="text-red-600 font-black text-[10px] uppercase tracking-widest hover:underline pb-2 transition-all">View All Menu</button>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-12">
                 {menuItems.slice(0, 4).map(item => (
                   <ProductCard 
                     key={item.id} item={item} language={language} 
                     isWished={currentUser?.wishlist.includes(item.id)}
                     onWishlist={() => {
                        if(!currentUser) return setView('LOGIN');
