                        setCurrentUser({ ...currentUser!, wishlist: newWishes });
                       }}
                       onDetails={() => { setSelectedProduct(item); setIsSubscriptionMode(false); }}
                       onAdd={(item: MenuItem) => handleAddToCart(item)} 
                     />
                   ))}
                </div>
             ) : (
                <div className="py-40 text-center bg-white rounded-[70px] border-4 border-dashed border-gray-100">
                   <h3 className="text-4xl font-black text-gray-300">Wishlist Void</h3>
                   <Button className="mt-10 rounded-3xl" onClick={()=>setView('MENU')}>Browse Menu</Button>
                </div>
             )}
          </div>
        )}
      </main>

      {/* Selected Product Modal */}
      {selectedProduct && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-6 lg:p-12 bg-black/70 backdrop-blur-2xl">
           <div className="bg-white w-full max-w-6xl max-h-[95vh] rounded-[80px] overflow-hidden flex flex-col lg:flex-row shadow-2xl animate-slide-up relative">
              <button onClick={()=>setSelectedProduct(null)} className="absolute top-10 right-10 w-16 h-16 bg-white/30 backdrop-blur-2xl rounded-3xl flex items-center justify-center text-gray-800 hover:text-red-600 transition-all border border-white/20 z-50"><i className="fas fa-xmark text-xl"></i></button>
              <div className="lg:w-1/2 h-80 lg:h-auto overflow-hidden relative">
                 <img src={selectedProduct.image} className="w-full h-full object-cover" />
              </div>
              <div className="lg:w-1/2 p-12 lg:p-20 overflow-y-auto flex flex-col gap-12">
                 <div>
                    <span className="text-red-600 font-black uppercase tracking-[8px] text-[11px] block">{selectedProduct.category}</span>
                    <h3 className="text-5xl lg:text-7xl font-black text-gray-800 tracking-tighter leading-none mt-4">{language === 'BN' ? selectedProduct.nameBn : selectedProduct.name}</h3>
                    <p className="text-gray-400 font-bold text-lg leading-relaxed mt-6">{selectedProduct.description}</p>
                 </div>
                 <div className="bg-gray-50/50 p-8 rounded-[45px] border border-gray-100 flex items-center justify-between group">
                    <div className="flex items-center gap-6">
                       <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-white transition-all shadow-xl ${isSubscriptionMode ? 'bg-emerald-500 shadow-emerald-100' : 'bg-gray-200'}`}><i className="fas fa-repeat text-xl"></i></div>
                       <div><p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Temporal Subscription</p><p className="text-sm font-black text-gray-800">Order daily?</p></div>
                    </div>
                    <button onClick={()=>setIsSubscriptionMode(!isSubscriptionMode)} className={`w-16 h-9 rounded-full transition-all relative shadow-inner ${isSubscriptionMode ? 'bg-emerald-500' : 'bg-gray-200'}`}><div className={`absolute top-1 w-7 h-7 bg-white rounded-full transition-all shadow-lg ${isSubscriptionMode ? 'left-8' : 'left-1'}`}></div></button>
                 </div>
                 <div className="mt-auto pt-14 flex items-center justify-between border-t border-gray-50">
                    <span className="text-6xl font-black text-red-600 tracking-tighter">৳{selectedProduct.price}</span>
                    <Button size="lg" className="rounded-[35px] px-14 py-8 text-2xl shadow-3xl shadow-red-600/20" onClick={()=>{handleAddToCart(selectedProduct, isSubscriptionMode); setSelectedProduct(null);}}>Add to Bag</Button>
                 </div>
              </div>
           </div>
        </div>
      )}

      <ChatBot />

      <div className="lg:hidden fixed bottom-0 w-full bg-white px-12 py-10 flex justify-between items-center z-50 border-t border-gray-100 shadow-[0_-20px_60px_-15px_rgba(0,0,0,0.1)] rounded-t-[50px] backdrop-blur-xl bg-white/90">
         <button onClick={()=>setView('HOME')} className={view === 'HOME' ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-home text-2xl"></i></button>
         <button onClick={()=>setView('MENU')} className={view === 'MENU' ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-utensils text-2xl"></i></button>
         <button onClick={()=>setView('WISHLIST')} className={view === 'WISHLIST' ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-heart text-2xl"></i></button>
         <button onClick={()=>setView('CART')} className={view === 'CART' ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-shopping-bag text-2xl"></i></button>
         <button onClick={()=>currentUser ? setView('PROFILE') : setView('LOGIN')} className={(view === 'PROFILE' || view === 'REGISTER' || view === 'LOGIN') ? 'text-red-600 scale-125' : 'text-gray-300'}><i className="fas fa-user-circle text-2xl"></i></button>
      </div>
    </div>
  );
};

