import React, { useState, useMemo, useEffect } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from './types';
import { Button } from './components/Button';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, orders: 240, volume: 85 },
  { name: 'Sun', sales: 3800, orders: 198, volume: 70 },
  { name: 'Mon', sales: 5200, orders: 310, volume: 110 },
  { name: 'Tue', sales: 4800, orders: 280, volume: 95 },
  { name: 'Wed', sales: 6200, orders: 390, volume: 140 },
  { name: 'Thu', sales: 5800, orders: 340, volume: 125 },
  { name: 'Fri', sales: 8500, orders: 480, volume: 180 },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const [activeTab, setActiveTab] = useState(userRole === UserRole.STAFF ? 'orders' : 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [toasts, setToasts] = useState<any[]>([]);

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (!savedUser) return onLogout();
    try {
      const user = JSON.parse(savedUser) as User;
      const payload = JSON.parse(atob(user.sessionToken!.split('.')[1]));
      if (payload.role !== userRole || payload.exp < Date.now()) throw new Error('Auth Failed');
      setIsAuthorized(true);
      showToast(`Terminal Secure: Role ${userRole}`, 'success');
    } catch {
      showToast('Security Breach: Session Invalidated', 'error');
      setTimeout(onLogout, 2000);
    }
  }, [userRole, onLogout]);

  const metrics = useMemo(() => {
    const totalRev = orders.reduce((acc, o) => acc + o.total, 0);
    const estimatedCost = totalRev * 0.62;
    const margin = totalRev > 0 ? ((totalRev - estimatedCost) / totalRev) * 100 : 0;
    return { 
      totalRev, 
      pendingCount: orders.filter(o => o.status !== OrderStatus.DELIVERED && o.status !== OrderStatus.CANCELLED).length, 
      margin: margin.toFixed(1), 
      orderCount: orders.length 
    };
  }, [orders]);

  const canAccess = (tab: string) => {
    switch (userRole) {
      case UserRole.ADMIN: return true;
      case UserRole.MANAGER: return ['dashboard', 'orders', 'inventory'].includes(tab);
      case UserRole.STAFF: return ['orders'].includes(tab);
      default: return false;
    }
  };

  const handleStatusChange = (orderId: string, status: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status } : o));
    showToast(`Order ${orderId} transitioned to ${status}`, 'success');
  };

  const handleStockAdjust = (itemId: string, delta: number) => {
    setMenuItems(prev => prev.map(item => 
      item.id === itemId ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
    showToast('Inventory parity synced', 'info');
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white">
      <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
      <p className="mt-8 text-[10px] font-black uppercase tracking-[6px] animate-pulse">Establishing Secure Uplink...</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F1F3F6] overflow-hidden font-sans select-none">
      {/* Dynamic Toast System */}
      <div className="fixed top-8 right-8 z-[250] space-y-3 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-center gap-4 px-8 py-5 rounded-[25px] shadow-3xl border border-gray-100 bg-white animate-slide-up">
            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
              <i className={`fas ${t.type === 'error' ? 'fa-triangle-exclamation' : 'fa-check'}`}></i>
            </div>
            <p className="font-black text-[11px] uppercase tracking-widest text-gray-800">{t.message}</p>
          </div>
        ))}
      </div>

      {/* Modern Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[200] w-80 bg-white shadow-2xl transition-transform duration-500 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-10 border-b border-gray-50 flex items-center gap-5">
          <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white shadow-2xl rotate-3 ring-4 ring-red-50">
            <i className="fas fa-shield-halved"></i>
          </div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
        </div>

        <nav className="p-8 space-y-3">
          {canAccess('dashboard') && <SidebarBtn active={activeTab === 'dashboard'} onClick={()=>{setActiveTab('dashboard'); setSidebarOpen(false);}} icon="fa-chart-pie" label="Analytics" />}
          {canAccess('orders') && <SidebarBtn active={activeTab === 'orders'} onClick={()=>{setActiveTab('orders'); setSidebarOpen(false);}} icon="fa-list-check" label="Orders" />}
          {canAccess('inventory') && <SidebarBtn active={activeTab === 'inventory'} onClick={()=>{setActiveTab('inventory'); setSidebarOpen(false);}} icon="fa-box-open" label="Inventory" />}
          {canAccess('staff') && <SidebarBtn active={activeTab === 'staff'} onClick={()=>{setActiveTab('staff'); setSidebarOpen(false);}} icon="fa-users-gear" label="Personnel" />}
          {canAccess('reports') && <SidebarBtn active={activeTab === 'reports'} onClick={()=>{setActiveTab('reports'); setSidebarOpen(false);}} icon="fa-file-invoice-dollar" label="Financials" />}
        </nav>

        <div className="absolute bottom-0 w-full p-8 border-t border-gray-50 bg-white">
          <button onClick={onLogout} className="w-full flex items-center justify-center gap-5 py-5 rounded-[25px] bg-gray-50 text-gray-400 font-black hover:bg-red-50 hover:text-red-600 transition-all uppercase tracking-[4px] text-[10px]">
            Terminate Node
          </button>
        </div>
      </aside>

      {/* Overlay for mobile sidebar */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[150] lg:hidden" onClick={() => setSidebarOpen(false)}></div>
      )}

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden bg-[#F1F3F6]">
        {/* Responsive Header */}
        <header className="h-24 bg-white border-b border-gray-100 flex items-center justify-between px-8 lg:px-12 shrink-0 z-50">
          <div className="flex items-center gap-6 lg:hidden">
            <button onClick={() => setSidebarOpen(true)} className="w-12 h-12 flex items-center justify-center bg-gray-50 rounded-2xl text-gray-800">
              <i className="fas fa-bars"></i>
            </button>
            <h2 className="text-xl font-black text-gray-800 tracking-tight capitalize">{activeTab}</h2>
          </div>
          <h2 className="hidden lg:block text-2xl font-black text-gray-800 tracking-tight capitalize">{activeTab} Node</h2>

          <div className="flex items-center gap-4 lg:gap-8">
            <span className="hidden md:flex items-center gap-3 text-[10px] font-black text-emerald-500 uppercase tracking-widest">
              <span className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_12px_rgba(16,185,129,0.6)]"></span> 
              Live Network
            </span>
            <div className="flex items-center gap-4 bg-gray-900 px-6 py-2.5 rounded-2xl text-white shadow-xl shadow-gray-200">
              <i className="fas fa-user-shield text-red-500"></i>
              <span className="text-[10px] font-black uppercase tracking-widest">{userRole}</span>
            </div>
          </div>
        </header>

        {/* Scrollable Content Area */}
        <div className="flex-1 overflow-y-auto p-6 lg:p-12 scrollbar-hide space-y-12 animate-slide-up">

          {/* Dashboard Section */}
          {activeTab === 'dashboard' && canAccess('dashboard') && (
            <div className="space-y-12">
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-8">
                <DashboardStat title="Revenue Today" value={`৳${metrics.totalRev.toLocaleString()}`} icon="fa-bangladeshi-taka-sign" color="text-green-600" />
                <DashboardStat title="Queue Volume" value={metrics.pendingCount} icon="fa-clock" color="text-orange-500" />
                <DashboardStat title="Total Orders" value={metrics.orderCount} icon="fa-list" color="text-purple-600" />
                <DashboardStat title="Critical Stock" value={menuItems.filter(i => i.stock < 10).length} icon="fa-triangle-exclamation" color="text-red-500" />
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-3 gap-10">
                <div className="xl:col-span-2 bg-white p-8 lg:p-12 rounded-[50px] shadow-sm border border-gray-100 min-h-[500px] flex flex-col">
                  <h3 className="text-2xl font-black text-gray-800 mb-10 tracking-tighter">Performance Spectrum</h3>
                  <div className="flex-1 min-h-[350px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={ANALYTICS_DATA}>
                        <defs>
                          <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor="#dc2626" stopOpacity={0.1}/>
                            <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                          </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
                        <Tooltip contentStyle={{ borderRadius: '24px', border: 'none', boxShadow: '0 20px 40px -10px rgba(0,0,0,0.1)' }} />
                        <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={5} fill="url(#colorSales)" />
                      </AreaChart>
                    </ResponsiveContainer>
                  </div>
                </div>

                <div className="bg-white p-8 lg:p-10 rounded-[50px] shadow-sm border border-gray-100 flex flex-col">
                  <h3 className="text-xl font-black text-gray-800 mb-8 tracking-tighter">Inventory Pulse</h3>
                  <div className="space-y-6">
                    {menuItems.filter(i => i.stock < 25).sort((a,b) => a.stock - b.stock).slice(0, 5).map(i => (
                      <div key={i.id} className="flex items-center gap-5 p-4 bg-gray-50 rounded-3xl border border-gray-100">
                        <img src={i.image} className="w-14 h-14 rounded-2xl object-cover" />
                        <div className="flex-1 min-w-0">
                          <p className="font-black text-gray-800 text-xs truncate">{i.name}</p>
                          <div className="h-1.5 w-full bg-gray-200 rounded-full mt-2.5 overflow-hidden">
                            <div className={`h-full rounded-full transition-all duration-1000 ${i.stock < 10 ? 'bg-red-600' : 'bg-orange-500'}`} style={{ width: `${Math.min(100, (i.stock / 50) * 100)}%` }}></div>
                          </div>
                        </div>
                        <span className={`text-xs font-black ${i.stock < 10 ? 'text-red-600' : 'text-gray-400'}`}>{i.stock}</span>
                      </div>
                    ))}
                    {menuItems.filter(i => i.stock < 25).length === 0 && (
                      <div className="py-20 text-center opacity-30 font-black uppercase text-[10px] tracking-widest">Stock Balanced</div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Orders Section */}
          {activeTab === 'orders' && (
            <div className="grid grid-cols-1 md:grid-cols-2 2xl:grid-cols-3 gap-10">
              {orders.length > 0 ? orders.map(o => (
                <div key={o.id} className="bg-white p-8 lg:p-10 rounded-[50px] shadow-sm border border-gray-100 flex flex-col gap-8 hover:shadow-2xl hover:-translate-y-1 transition-all">
                  <div className="flex justify-between items-start">
                    <div className="flex items-center gap-5">
                      <div className="w-14 h-14 bg-gray-900 text-white rounded-[20px] flex items-center justify-center font-black text-lg shadow-xl ring-4 ring-gray-100">{o.id.split('-')[1]}</div>
                      <div className="min-w-0">
                        <p className="font-black text-xl text-gray-800 truncate tracking-tight">{o.customerName}</p>
                        <p className="text-[9px] text-gray-400 font-black uppercase tracking-[3px] truncate">{o.paymentMethod} • {new Date(o.createdAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                      </div>
                    </div>
                    <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest shadow-sm ${
                      o.status === OrderStatus.DELIVERED ? 'bg-emerald-100 text-emerald-700' : 
                      o.status === OrderStatus.CANCELLED ? 'bg-gray-100 text-gray-500' :
                      'bg-red-50 text-red-600'
                    }`}>{o.status}</span>
                  </div>

                  <div className="bg-gray-50 rounded-[35px] p-6 space-y-3">
                    {o.items.map((i, idx) => (
                      <div key={idx} className="flex justify-between text-xs font-bold text-gray-600">
                        <span className="truncate pr-4">{i.name} <span className="text-gray-300 ml-2">x{i.quantity}</span></span>
                        <span className="font-black text-gray-800 shrink-0">৳{i.price * i.quantity}</span>
                      </div>
                    ))}
                  </div>

                  <div className="space-y-4">
                    <label className="text-[9px] font-black uppercase text-gray-300 tracking-[5px] ml-4">Lifecycle State</label>
                    <select 
                      className="w-full bg-gray-900 text-white rounded-3xl text-[10px] font-black uppercase tracking-widest p-5 cursor-pointer outline-none shadow-xl hover:bg-black transition-colors"
                      value={o.status}
                      onChange={(e) => handleStatusChange(o.id, e.target.value as OrderStatus)}
                    >
