import React, { useState, useMemo, useEffect } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from './types';
import { Button } from './components/Button';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, orders: 240, volume: 85 },
  { name: 'Sun', sales: 3800, orders: 198, volume: 70 },
  { name: 'Mon', sales: 5200, orders: 310, volume: 110 },
  { name: 'Tue', sales: 4800, orders: 280, volume: 95 },
  { name: 'Wed', sales: 6200, orders: 390, volume: 140 },
  { name: 'Thu', sales: 5800, orders: 340, volume: 125 },
  { name: 'Fri', sales: 8500, orders: 480, volume: 180 },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const [activeTab, setActiveTab] = useState(userRole === UserRole.STAFF ? 'orders' : 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [toasts, setToasts] = useState<any[]>([]);

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (!savedUser) return onLogout();
    try {
      const user = JSON.parse(savedUser) as User;
      const payload = JSON.parse(atob(user.sessionToken!.split('.')[1]));
      if (payload.role !== userRole || payload.exp < Date.now()) throw new Error('Auth Failed');
      setIsAuthorized(true);
      showToast(`Terminal Secure: Role ${userRole}`, 'success');
    } catch {
      showToast('Security Breach: Session Invalidated', 'error');
      setTimeout(onLogout, 2000);
    }
  }, [userRole, onLogout]);

  const metrics = useMemo(() => {
    const totalRev = orders.reduce((acc, o) => acc + o.total, 0);
    const estimatedCost = totalRev * 0.62;
    const margin = totalRev > 0 ? ((totalRev - estimatedCost) / totalRev) * 100 : 0;
    return { 
      totalRev, 
      pendingCount: orders.filter(o => o.status !== OrderStatus.DELIVERED && o.status !== OrderStatus.CANCELLED).length, 
      margin: margin.toFixed(1), 
      orderCount: orders.length 
    };
  }, [orders]);

  const canAccess = (tab: string) => {
    switch (userRole) {
      case UserRole.ADMIN: return true;
      case UserRole.MANAGER: return ['dashboard', 'orders', 'inventory'].includes(tab);
      case UserRole.STAFF: return ['orders'].includes(tab);
      default: return false;
    }
  };

  const handleStatusChange = (orderId: string, status: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status } : o));
    showToast(`Order ${orderId} transitioned to ${status}`, 'success');
  };

  const handleStockAdjust = (itemId: string, delta: number) => {
    setMenuItems(prev => prev.map(item => 
      item.id === itemId ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
    showToast('Inventory parity synced', 'info');
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white p-6 text-center">
      <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
      <p className="mt-8 text-[10px] font-black uppercase tracking-[6px] animate-pulse">Establishing Secure Uplink...</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F1F3F6] overflow-hidden font-sans select-none">
      {/* Dynamic Toast System */}
      <div className="fixed top-8 right-8 z-[250] space-y-3 pointer-events-none max-w-[calc(100%-2rem)]">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-center gap-4 px-6 py-4 lg:px-8 lg:py-5 rounded-[25px] shadow-3xl border border-gray-100 bg-white animate-slide-up">
            <div className={`w-8 h-8 lg:w-10 lg:h-10 rounded-2xl flex items-center justify-center shrink-0 ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
              <i className={`fas ${t.type === 'error' ? 'fa-triangle-exclamation' : 'fa-check'}`}></i>
            </div>
            <p className="font-black text-[10px] lg:text-[11px] uppercase tracking-widest text-gray-800 line-clamp-2">{t.message}</p>
          </div>
        ))}
      </div>

      {/* Modern Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[200] w-72 lg:w-80 bg-white shadow-2xl transition-transform duration-500 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 lg:p-10 border-b border-gray-50 flex items-center gap-5">
          <div className="w-10 h-10 lg:w-12 lg:h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white shadow-2xl rotate-3 ring-4 ring-red-50">
            <i className="fas fa-shield-halved"></i>
          </div>
          <h1 className="text-xl lg:text-2xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
          <button onClick={() => setSidebarOpen(false)} className="lg:hidden ml-auto p-2 text-gray-400">
            <i className="fas fa-times"></i>
          </button>
        </div>

        <nav className="p-6 lg:p-8 space-y-2 lg:space-y-3 overflow-y-auto max-h-[calc(100vh-200px)] scrollbar-hide">
          {canAccess('dashboard') && <SidebarBtn active={activeTab === 'dashboard'} onClick={()=>{setActiveTab('dashboard'); setSidebarOpen(false);}} icon="fa-chart-pie" label="Analytics" />}
          {canAccess('orders') && <SidebarBtn active={activeTab === 'orders'} onClick={()=>{setActiveTab('orders'); setSidebarOpen(false);}} icon="fa-list-check" label="Orders" />}
          {canAccess('inventory') && <SidebarBtn active={activeTab === 'inventory'} onClick={()=>{setActiveTab('inventory'); setSidebarOpen(false);}} icon="fa-box-open" label="Inventory" />}
          {canAccess('staff') && <SidebarBtn active={activeTab === 'staff'} onClick={()=>{setActiveTab('staff'); setSidebarOpen(false);}} icon="fa-users-gear" label="Personnel" />}
          {canAccess('reports') && <SidebarBtn active={activeTab === 'reports'} onClick={()=>{setActiveTab('reports'); setSidebarOpen(false);}} icon="fa-file-invoice-dollar" label="Financials" />}
        </nav>

        <div className="absolute bottom-0 w-full p-6 lg:p-8 border-t border-gray-50 bg-white">
          <button onClick={onLogout} className="w-full flex items-center justify-center gap-4 py-4 lg:py-5 rounded-[20px] lg:rounded-[25px] bg-gray-50 text-gray-400 font-black hover:bg-red-50 hover:text-red-600 transition-all uppercase tracking-[4px] text-[9px] lg:text-[10px]">
            Terminate Node
          </button>
        </div>
      </aside>

      {/* Overlay for mobile sidebar */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[150] lg:hidden" onClick={() => setSidebarOpen(false)}></div>
      )}

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden bg-[#F1F3F6]">
        {/* Responsive Header */}
        <header className="h-20 lg:h-24 bg-white border-b border-gray-100 flex items-center justify-between px-6 lg:px-12 shrink-0 z-50">
          <div className="flex items-center gap-4 lg:hidden">
            <button onClick={() => setSidebarOpen(true)} className="w-10 h-10 flex items-center justify-center bg-gray-50 rounded-xl text-gray-800 shadow-sm border border-gray-100">
              <i className="fas fa-bars"></i>
            </button>
            <h2 className="text-lg font-black text-gray-800 tracking-tight capitalize truncate max-w-[120px]">{activeTab}</h2>
          </div>
          <h2 className="hidden lg:block text-2xl font-black text-gray-800 tracking-tight capitalize">{activeTab} Node</h2>

          <div className="flex items-center gap-3 lg:gap-8">
            <span className="hidden md:flex items-center gap-3 text-[10px] font-black text-emerald-500 uppercase tracking-widest">
              <span className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_12px_rgba(16,185,129,0.6)]"></span> 
              Live Network
            </span>
            <div className="flex items-center gap-3 lg:gap-4 bg-gray-900 px-4 py-2 lg:px-6 lg:py-2.5 rounded-xl lg:rounded-2xl text-white shadow-xl shadow-gray-200">
              <i className="fas fa-user-shield text-red-500 text-xs lg:text-sm"></i>
              <span className="text-[9px] lg:text-[10px] font-black uppercase tracking-widest truncate max-w-[80px] lg:max-w-none">{userRole}</span>
            </div>
          </div>
        </header>

        {/* Scrollable Content Area */}
        <div className="flex-1 overflow-y-auto p-4 lg:p-12 scrollbar-hide space-y-8 lg:space-y-12 animate-slide-up">

          {/* Dashboard Section */}
          {activeTab === 'dashboard' && canAccess('dashboard') && (
            <div className="space-y-8 lg:space-y-12">
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6 lg:gap-8">
                <DashboardStat title="Revenue Today" value={`৳${metrics.totalRev.toLocaleString()}`} icon="fa-bangladeshi-taka-sign" color="text-green-600" />
                <DashboardStat title="Queue Volume" value={metrics.pendingCount} icon="fa-clock" color="text-orange-500" />
                <DashboardStat title="Total Orders" value={metrics.orderCount} icon="fa-list" color="text-purple-600" />
                <DashboardStat title="Critical Stock" value={menuItems.filter(i => i.stock < 10).length} icon="fa-triangle-exclamation" color="text-red-500" />
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-3 gap-8 lg:gap-10">
                <div className="xl:col-span-2 bg-white p-6 lg:p-12 rounded-[40px] lg:rounded-[50px] shadow-sm border border-gray-100 min-h-[400px] lg:min-h-[500px] flex flex-col">
                  <h3 className="text-xl lg:text-2xl font-black text-gray-800 mb-8 lg:mb-10 tracking-tighter">Performance Spectrum</h3>
                  <div className="flex-1 min-h-[300px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={ANALYTICS_DATA}>
                        <defs>
                          <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor="#dc2626" stopOpacity={0.1}/>
                            <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                          </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
                        <Tooltip contentStyle={{ borderRadius: '24px', border: 'none', boxShadow: '0 20px 40px -10px rgba(0,0,0,0.1)' }} />
                        <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={5} fill="url(#colorSales)" />
                      </AreaChart>
                    </ResponsiveContainer>
                  </div>
                </div>

                <div className="bg-white p-6 lg:p-10 rounded-[40px] lg:rounded-[50px] shadow-sm border border-gray-100 flex flex-col h-full">
                  <h3 className="text-lg lg:text-xl font-black text-gray-800 mb-6 lg:mb-8 tracking-tighter">Inventory Pulse</h3>
