export default AdminPanel;

import React, { useState, useMemo, useEffect } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from './types';
import { Button } from './components/Button';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, orders: 240, volume: 85 },
  { name: 'Sun', sales: 3800, orders: 198, volume: 70 },
  { name: 'Mon', sales: 5200, orders: 310, volume: 110 },
  { name: 'Tue', sales: 4800, orders: 280, volume: 95 },
  { name: 'Wed', sales: 6200, orders: 390, volume: 140 },
  { name: 'Thu', sales: 5800, orders: 340, volume: 125 },
  { name: 'Fri', sales: 8500, orders: 480, volume: 180 },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const [activeTab, setActiveTab] = useState(userRole === UserRole.STAFF ? 'orders' : 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [toasts, setToasts] = useState<any[]>([]);

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (!savedUser) return onLogout();
    try {
      const user = JSON.parse(savedUser) as User;
      const payload = JSON.parse(atob(user.sessionToken!.split('.')[1]));
      if (payload.role !== userRole || payload.exp < Date.now()) throw new Error('Auth Failed');
      setIsAuthorized(true);
    } catch {
      showToast('Security Breach: Session Invalidated', 'error');
      setTimeout(onLogout, 2000);
    }
  }, [userRole, onLogout]);

  const metrics = useMemo(() => {
    const totalRev = orders.reduce((acc, o) => acc + o.total, 0);
    const estimatedCost = totalRev * 0.62;
    const margin = totalRev > 0 ? ((totalRev - estimatedCost) / totalRev) * 100 : 0;
    return { 
      totalRev, 
      pendingCount: orders.filter(o => o.status !== OrderStatus.DELIVERED && o.status !== OrderStatus.CANCELLED).length, 
      margin: margin.toFixed(1), 
      orderCount: orders.length 
    };
  }, [orders]);

  const canAccess = (tab: string) => {
    switch (userRole) {
      case UserRole.ADMIN: return true;
      case UserRole.MANAGER: return ['dashboard', 'orders', 'inventory'].includes(tab);
      case UserRole.STAFF: return ['orders'].includes(tab);
      default: return false;
    }
  };

  const handleStatusChange = (orderId: string, status: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status } : o));
    showToast(`Order ${orderId} is now ${status}`, 'success');
  };

  const handleStockAdjust = (itemId: string, delta: number) => {
    setMenuItems(prev => prev.map(item => 
      item.id === itemId ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
    showToast('Inventory updated', 'info');
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white p-6 text-center">
      <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
      <p className="mt-8 text-[10px] font-black uppercase tracking-[6px] animate-pulse">Establishing Secure Uplink...</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F1F3F6] overflow-hidden font-sans select-none">
      {/* Notifications */}
      <div className="fixed top-6 right-6 lg:top-8 lg:right-8 z-[250] space-y-3 pointer-events-none max-w-[calc(100%-3rem)]">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-center gap-4 px-6 py-4 rounded-[25px] shadow-2xl border border-gray-100 bg-white animate-slide-up">
            <div className={`w-8 h-8 rounded-xl flex items-center justify-center shrink-0 ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
              <i className={`fas ${t.type === 'error' ? 'fa-triangle-exclamation' : 'fa-check'}`}></i>
            </div>
            <p className="font-black text-[10px] uppercase tracking-widest text-gray-800">{t.message}</p>
          </div>
        ))}
      </div>

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[200] w-72 lg:w-80 bg-white shadow-2xl lg:shadow-none lg:border-r border-gray-100 transition-transform duration-500 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 lg:p-10 border-b border-gray-50 flex items-center gap-5 shrink-0">
          <div className="w-10 h-10 lg:w-12 lg:h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white shadow-xl rotate-3 ring-4 ring-red-50 shrink-0">
            <i className="fas fa-shield-halved"></i>
          </div>
          <div className="min-w-0">
            <h1 className="text-xl lg:text-2xl font-black text-gray-800 tracking-tighter truncate">BFC HUB</h1>
            <p className="text-[8px] font-black uppercase text-gray-300 tracking-[3px]">System Active</p>
          </div>
        </div>

        <nav className="p-6 lg:p-8 space-y-2 lg:space-y-3 overflow-y-auto max-h-[calc(100vh-200px)] scrollbar-hide">
          {canAccess('dashboard') && <SidebarBtn active={activeTab === 'dashboard'} onClick={()=>{setActiveTab('dashboard'); setSidebarOpen(false);}} icon="fa-chart-pie" label="Analytics" />}
          {canAccess('orders') && <SidebarBtn active={activeTab === 'orders'} onClick={()=>{setActiveTab('orders'); setSidebarOpen(false);}} icon="fa-list-check" label="Orders" />}
          {canAccess('inventory') && <SidebarBtn active={activeTab === 'inventory'} onClick={()=>{setActiveTab('inventory'); setSidebarOpen(false);}} icon="fa-box-open" label="Inventory" />}
          {canAccess('staff') && <SidebarBtn active={activeTab === 'staff'} onClick={()=>{setActiveTab('staff'); setSidebarOpen(false);}} icon="fa-users-gear" label="Personnel" />}
          {canAccess('reports') && <SidebarBtn active={activeTab === 'reports'} onClick={()=>{setActiveTab('reports'); setSidebarOpen(false);}} icon="fa-file-invoice-dollar" label="Financials" />}
        </nav>

        <div className="absolute bottom-0 w-full p-6 lg:p-8 border-t border-gray-50 bg-white">
          <button onClick={onLogout} className="w-full flex items-center justify-center gap-4 py-4 rounded-[20px] bg-gray-50 text-gray-400 font-black hover:bg-red-50 hover:text-red-600 transition-all uppercase tracking-[4px] text-[9px] lg:text-[10px]">
            Terminate Session
          </button>
        </div>
      </aside>

      {/* Sidebar Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-gray-950/40 backdrop-blur-sm z-[150] lg:hidden" onClick={() => setSidebarOpen(false)}></div>
      )}

      {/* Main UI */}
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden bg-[#F1F3F6]">
        {/* Header */}
        <header className="h-20 lg:h-24 bg-white/80 backdrop-blur-xl border-b border-gray-100 flex items-center justify-between px-6 lg:px-12 shrink-0 z-50">
          <div className="flex items-center gap-4 lg:hidden">
            <button onClick={() => setSidebarOpen(true)} className="w-10 h-10 flex items-center justify-center bg-gray-50 rounded-xl text-gray-800 shadow-sm border border-gray-100">
              <i className="fas fa-bars"></i>
            </button>
            <h2 className="text-lg font-black text-gray-800 tracking-tight capitalize truncate">{activeTab}</h2>
          </div>
          <h2 className="hidden lg:block text-2xl font-black text-gray-800 tracking-tight capitalize">{activeTab} Monitor</h2>

          <div className="flex items-center gap-3 lg:gap-8">
