  const [language, setLanguage] = useState<'EN' | 'BN'>('BN');
  const [selectedProduct, setSelectedProduct] = useState<MenuItem | null>(null);
  const [isSubscriptionMode, setIsSubscriptionMode] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [formName, setFormName] = useState('');
  const [formEmail, setFormEmail] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [formPass, setFormPass] = useState('');
  const [deliveryZone, setDeliveryZone] = useState('Gulshan Node');
  const [deliverySlot, setDeliverySlot] = useState('Immediate (ETA 35m)');
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'CARD' | 'COD'>('BKASH');
  const [isProcessing, setIsProcessing] = useState(false);
  const [orderCode, setOrderCode] = useState('');
  const [cardDetails, setCardDetails] = useState({ number: '', exp: '', cvv: '', name: '' });
  const [transactionId, setTransactionId] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  };

  const generateMockToken = (role: UserRole, email: string) => {
    const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
    const payload = btoa(JSON.stringify({ role, email, exp: Date.now() + 86400000 }));
    return `${header}.${payload}.bfc-signature`;
  };

  const validateSession = (user: User) => {
    if (!user.sessionToken) return false;
    try {
      const payload = JSON.parse(atob(user.sessionToken.split('.')[1]));
      return payload.exp > Date.now();
    } catch { return false; }
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (savedUser) {
      const parsed = JSON.parse(savedUser) as User;
      if (validateSession(parsed)) {
        setCurrentUser(parsed);
        setFormName(parsed.name);
        setFormEmail(parsed.email);
        setFormPhone(parsed.phone);
      } else {
        localStorage.removeItem('bfc_user_profile');
      }
    }
    const savedCart = localStorage.getItem('bfc_cart');
