                         <TrackerTimelineNode active icon="fa-check" title="Transmitted" desc="Order logged in node" time="10:05" isCompleted />
                         <TrackerTimelineNode active icon="fa-fire-burner" title="Synthesis" desc="Chef is preparing asset" time="10:15" isCompleted />
