                      </div>
                      <Button fullWidth className="rounded-[35px] py-6 lg:py-7 text-xl shadow-2xl shadow-red-900/40" onClick={()=>setView('HOME')}>Finish Trace</Button>
                   </div>
                </div>
             ) : (
                <div className="py-20 lg:py-40 text-center bg-white rounded-[70px] border-4 border-dashed border-gray-100 flex flex-col items-center">
                   <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mb-8 text-gray-200"><i className="fas fa-satellite-dish text-4xl"></i></div>
                   <h3 className="text-2xl lg:text-4xl font-black text-gray-300 uppercase tracking-widest px-6">No Active Tracking Signal</h3>
                   <Button className="mt-10 rounded-3xl px-12 py-5 shadow-xl" onClick={()=>setView('MENU')}>Browse Menu</Button>
                </div>
             )}
          </div>
        )}
      </main>

      {/* Selected Product Modal - Same refined logic for small screens */}
      {selectedProduct && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 lg:p-12 bg-black/80 backdrop-blur-xl animate-fade-in">
           <div className="bg-white w-full max-w-6xl max-h-[90vh] lg:max-h-[95vh] rounded-[50px] lg:rounded-[80px] overflow-hidden flex flex-col lg:flex-row shadow-2xl animate-slide-up relative">
              <button onClick={()=>setSelectedProduct(null)} className="absolute top-6 right-6 lg:top-10 lg:right-10 w-12 h-12 lg:w-16 lg:h-16 bg-white/40 backdrop-blur-xl rounded-2xl lg:rounded-3xl flex items-center justify-center text-gray-800 hover:text-red-600 transition-all z-50 shadow-xl border border-white/20 active:scale-90"><i className="fas fa-xmark text-xl lg:text-2xl"></i></button>
              <div className="lg:w-1/2 h-64 lg:h-auto overflow-hidden relative shrink-0">
                 <img src={selectedProduct.image} className="w-full h-full object-cover" />
                 <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent lg:hidden"></div>
              </div>
              <div className="lg:w-1/2 p-8 lg:p-20 overflow-y-auto flex flex-col gap-8 lg:gap-12 scrollbar-hide">
                 <div>
                    <span className="text-red-600 font-black uppercase tracking-[8px] text-[10px] lg:text-[11px] block mb-4">{selectedProduct.category}</span>
