                    <p className="text-gray-400 font-bold text-base lg:text-lg leading-relaxed mt-6">{selectedProduct.description}</p>
                 </div>
                 <div className="bg-gray-50 p-6 lg:p-8 rounded-[35px] lg:rounded-[45px] border border-gray-100 flex items-center justify-between shadow-inner">
                    <div className="flex items-center gap-4 lg:gap-6">
                       <div className={`w-12 h-12 lg:w-14 lg:h-14 rounded-2xl flex items-center justify-center text-white shadow-xl transition-all ${isSubscriptionMode ? 'bg-emerald-500' : 'bg-gray-200'}`}><i className="fas fa-calendar-check text-xl"></i></div>
                       <div><p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Recurring Protocol</p><p className="text-xs lg:text-sm font-black text-gray-800">Set as Subscription?</p></div>
                    </div>
                    <button onClick={()=>setIsSubscriptionMode(!isSubscriptionMode)} className={`w-14 h-8 lg:w-16 lg:h-9 rounded-full transition-all relative shadow-inner ${isSubscriptionMode ? 'bg-emerald-500' : 'bg-gray-300'}`}><div className={`absolute top-1 w-6 h-6 lg:w-7 lg:h-7 bg-white rounded-full transition-all shadow-lg ${isSubscriptionMode ? 'left-7 lg:left-8' : 'left-1'}`}></div></button>
                 </div>
                 <div className="mt-auto pt-8 lg:pt-14 flex flex-col sm:flex-row items-center justify-between border-t border-gray-100 gap-8">
                    <span className="text-5xl lg:text-6xl font-black text-red-600 tracking-tighter leading-none">৳{selectedProduct.price}</span>
                    <Button size="lg" className="rounded-[35px] w-full sm:w-auto px-12 lg:px-14 py-6 lg:py-8 text-xl lg:text-2xl shadow-3xl shadow-red-600/20" onClick={()=>{handleAddToCart(selectedProduct, isSubscriptionMode); setSelectedProduct(null);}}>Add to Bag</Button>
                 </div>
              </div>
           </div>
        </div>
      )}

      <ChatBot />

      {/* Mobile Bottom Bar - Refined alignment */}
      <div className="lg:hidden fixed bottom-0 w-full bg-white/95 backdrop-blur-xl px-10 py-6 flex justify-between items-center z-[200] border-t border-gray-100 shadow-[0_-15px_40px_-15px_rgba(0,0,0,0.1)] rounded-t-[40px]">
         <button onClick={()=>setView('HOME')} className={`transition-all active:scale-90 ${view === 'HOME' ? 'text-red-600' : 'text-gray-300 hover:text-red-400'}`}><i className="fas fa-home text-2xl"></i></button>
         <button onClick={()=>setView('MENU')} className={`transition-all active:scale-90 ${view === 'MENU' ? 'text-red-600' : 'text-gray-300 hover:text-red-400'}`}><i className="fas fa-utensils text-2xl"></i></button>
         <button onClick={()=>setView('CART')} className={`transition-all active:scale-90 relative ${view === 'CART' ? 'text-red-600' : 'text-gray-300 hover:text-red-400'}`}>
            <i className="fas fa-shopping-bag text-2xl"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[8px] w-5 h-5 rounded-full flex items-center justify-center ring-4 ring-white font-black">{cart.reduce((a,b)=>a+b.qty, 0)}</span>}
         </button>
         {isPrivileged && <button onClick={()=>setView('ADMIN')} className={`transition-all active:scale-90 ${view === 'ADMIN' ? 'text-red-600' : 'text-gray-300 hover:text-red-400'}`}><i className="fas fa-shield-halved text-2xl"></i></button>}
         <button onClick={()=>currentUser ? setView('PROFILE') : setView('LOGIN')} className={`transition-all active:scale-90 ${['PROFILE', 'LOGIN', 'REGISTER'].includes(view) ? 'text-red-600' : 'text-gray-300 hover:text-red-400'}`}><i className="fas fa-user-circle text-2xl"></i></button>
      </div>
    </div>
  );
};

