    setIsAuthenticating(true);
    await new Promise(r => setTimeout(r, 1500));

    const privileged = MOCK_AUTH_DB[formEmail as keyof typeof MOCK_AUTH_DB];
    if (privileged && privileged.pass === formPass) {
      const user: User = {
