        phone: '01XXXXXXXXX', role: UserRole.CUSTOMER, loyaltyPoints: 120,
        tier: 'GOLD', wishlist: [], referralCode: 'BFC-GUEST',
        sessionToken: generateMockToken(UserRole.CUSTOMER, formEmail)
      };
      setCurrentUser(user);
      showToast('Welcome back!', 'success');
      setView('HOME');
    } else if (isRegistering) {
       const user: User = {
        id: 'U-' + Date.now(), name: formName, email: formEmail,
        phone: formPhone, role: UserRole.CUSTOMER, loyaltyPoints: 0,
        tier: 'SILVER', wishlist: [], referralCode: 'BFC-' + Math.random().toString(36).slice(7).toUpperCase(),
        sessionToken: generateMockToken(UserRole.CUSTOMER, formEmail)
      };
      setCurrentUser(user);
      showToast('Registration Success', 'success');
      setView('HOME');
    } else {
      showToast('Invalid credentials', 'error');
    }
    setIsAuthenticating(false);
  };

  const handleProfileUpdate = () => {
    if (!currentUser) return;
    const updatedUser = {
      ...currentUser,
      name: formName,
      phone: formPhone,
    };
    setCurrentUser(updatedUser);
    showToast('Profile Updated Locally', 'success');
  };

  const isPrivileged = currentUser && currentUser.role !== UserRole.CUSTOMER;

  if (view === 'ADMIN' && isPrivileged) {
    return (
      <AdminPanel 
        userRole={currentUser.role} 
        onLogout={() => { setCurrentUser(null); setView('HOME'); }}
        menuItems={menuItems}
        setMenuItems={setMenuItems}
        orders={allOrders}
        setOrders={setAllOrders}
