import React, { useState, useMemo, useEffect } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { Button } from './Button';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  BarChart, Bar, Cell, PieChart, Pie
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, orders: 240, volume: 85, customers: 120 },
  { name: 'Sun', sales: 3800, orders: 198, volume: 70, customers: 105 },
  { name: 'Mon', sales: 5200, orders: 310, volume: 110, customers: 180 },
  { name: 'Tue', sales: 4800, orders: 280, volume: 95, customers: 155 },
  { name: 'Wed', sales: 6200, orders: 390, volume: 140, customers: 210 },
  { name: 'Thu', sales: 5800, orders: 340, volume: 125, customers: 190 },
  { name: 'Fri', sales: 8500, orders: 480, volume: 180, customers: 310 },
];

const CUSTOMER_BEHAVIOR = [
  { name: 'Returning', value: 65, color: '#dc2626' },
  { name: 'New', value: 35, color: '#10b981' },
];

const INVENTORY_VELOCITY = [
  { name: 'Biryani', usage: 85, stock: 50 },
  { name: 'Curry', usage: 45, stock: 30 },
  { name: 'Kebab', usage: 120, stock: 100 },
  { name: 'Desserts', usage: 30, stock: 60 },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const [activeTab, setActiveTab] = useState(userRole === UserRole.STAFF ? 'orders' : 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [toasts, setToasts] = useState<any[]>([]);
  const [exportLoading, setExportLoading] = useState<string | null>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (!savedUser) return onLogout();
    try {
      const user = JSON.parse(savedUser) as User;
      const payload = JSON.parse(atob(user.sessionToken!.split('.')[1]));
      if (payload.role !== userRole || payload.exp < Date.now()) throw new Error('Auth Failed');
      setIsAuthorized(true);
    } catch {
      showToast('Security Breach: Session Invalidated', 'error');
      setTimeout(onLogout, 2000);
    }
  }, [userRole, onLogout]);

  const metrics = useMemo(() => {
    const totalRev = orders.reduce((acc, o) => acc + o.total, 0);
    const estimatedCost = totalRev * 0.62;
    const margin = totalRev > 0 ? ((totalRev - estimatedCost) / totalRev) * 100 : 0;
    return { 
      totalRev, 
      pendingCount: orders.filter(o => o.status !== OrderStatus.DELIVERED && o.status !== OrderStatus.CANCELLED).length, 
      margin: margin.toFixed(1), 
      orderCount: orders.length 
    };
  }, [orders]);

  const canAccess = (tab: string) => {
    switch (userRole) {
      case UserRole.ADMIN: return true;
      case UserRole.MANAGER: return ['dashboard', 'orders', 'inventory', 'reports'].includes(tab);
      case UserRole.STAFF: return ['orders'].includes(tab);
      default: return false;
    }
  };

  const handleStatusChange = (orderId: string, status: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status } : o));
    showToast(`Order ${orderId} transitioned to ${status}`, 'success');
  };

  const handleStockAdjust = (itemId: string, delta: number) => {
    setMenuItems(prev => prev.map(item => 
      item.id === itemId ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
    showToast('Inventory parity synced', 'info');
  };

  const handleExport = async (format: 'PDF' | 'EXCEL', reportType: string) => {
    setExportLoading(`${reportType}-${format}`);
    await new Promise(r => setTimeout(r, 2000));
    setExportLoading(null);
    showToast(`${reportType} exported successfully as ${format}`, 'success');
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white p-6 text-center">
      <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
      <p className="mt-8 text-[10px] font-black uppercase tracking-[6px] animate-pulse">Establishing Secure Uplink...</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F1F3F6] overflow-hidden font-sans select-none">
      {/* Toast Notifications */}
      <div className="fixed top-6 right-6 z-[300] space-y-3 pointer-events-none max-w-[calc(100%-3rem)]">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-center gap-4 px-6 py-4 rounded-3xl shadow-2xl border border-gray-100 bg-white animate-slide-up">
            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shrink-0 ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
              <i className={`fas ${t.type === 'error' ? 'fa-triangle-exclamation' : 'fa-check'}`}></i>
            </div>
            <p className="font-black text-[11px] uppercase tracking-widest text-gray-800 line-clamp-2">{t.message}</p>
          </div>
        ))}
      </div>

      {/* Sidebar Navigation */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 lg:w-80 bg-white shadow-2xl transition-transform duration-500 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 lg:p-10 border-b border-gray-50 flex items-center justify-between">
          <div className="flex items-center gap-5">
            <div className="w-10 h-10 lg:w-12 lg:h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white shadow-xl rotate-3 ring-4 ring-red-50">
              <i className="fas fa-shield-halved"></i>
            </div>
            <h1 className="text-xl lg:text-2xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
          </div>
          <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2 text-gray-400">
             <i className="fas fa-times text-xl"></i>
          </button>
        </div>

        <nav className="p-6 lg:p-8 space-y-3 overflow-y-auto h-[calc(100%-200px)]">
          {canAccess('dashboard') && <SidebarBtn active={activeTab === 'dashboard'} onClick={()=>{setActiveTab('dashboard'); setSidebarOpen(false);}} icon="fa-chart-pie" label="Analytics" />}
