             <div className="w-10 h-10 lg:w-12 lg:h-12 bg-gray-100 rounded-2xl flex items-center justify-center text-gray-400 font-black shrink-0">{name.charAt(0)}</div>
             <span className="font-black text-gray-800 text-base lg:text-lg tracking-tight whitespace-nowrap">{name}</span>
          </div>
       </td>
       <td className="p-6 lg:p-10 font-black text-gray-400 text-[9px] lg:text-[10px] uppercase tracking-widest whitespace-nowrap">{role}</td>
       <td className="p-6 lg:p-10">
          <span className={`px-4 lg:px-5 py-2 rounded-full font-black text-[8px] lg:text-[9px] uppercase tracking-[2px] border whitespace-nowrap ${styles[type]}`}>
            {status}
          </span>
       </td>
       <td className="p-6 lg:p-10">
          <button className="w-10 h-10 lg:w-12 lg:h-12 rounded-2xl bg-gray-50 text-gray-300 hover:text-red-600 transition-all shadow-inner border border-gray-100 flex items-center justify-center">
            <i className="fas fa-sliders text-xs"></i>
          </button>
       </td>
    </tr>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'info';
  id: number;
}

const MOCK_AUTH_DB = {
  'admin@bfc.com': { pass: 'admin123', role: UserRole.ADMIN, name: 'Root Admin' },
  'manager@bfc.com': { pass: 'manager456', role: UserRole.MANAGER, name: 'Node Manager' },
  'staff@bfc.com': { pass: 'staff789', role: UserRole.STAFF, name: 'Logistics Staff' }
};

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE' | 'PAYMENT' | 'REGISTER' | 'WISHLIST'>('HOME');
  const [language, setLanguage] = useState<'EN' | 'BN'>('BN');
  const [selectedProduct, setSelectedProduct] = useState<MenuItem | null>(null);
  const [isSubscriptionMode, setIsSubscriptionMode] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Form State
  const [formName, setFormName] = useState('');
  const [formEmail, setFormEmail] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [formPass, setFormPass] = useState('');
  const [deliveryZone, setDeliveryZone] = useState('Gulshan Node');
  const [deliverySlot, setDeliverySlot] = useState('Immediate (ETA 35m)');
  const [paymentMethod, setPaymentMethod] = useState<'BKASH' | 'NAGAD' | 'CARD' | 'COD'>('BKASH');
  const [isProcessing, setIsProcessing] = useState(false);
  const [orderCode, setOrderCode] = useState('');
  const [cardDetails, setCardDetails] = useState({ number: '', exp: '', cvv: '', name: '' });
  const [transactionId, setTransactionId] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true);
      showToast('Node Restored: Syncing Data', 'success');
    };
    const handleOffline = () => {
      setIsOnline(false);
      showToast('Node Disconnected: Offline Mode', 'error');
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  };

  const generateMockToken = (role: UserRole, email: string) => {
    const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
    const payload = btoa(JSON.stringify({ role, email, exp: Date.now() + 86400000 }));
    return `${header}.${payload}.bfc-signature`;
  };

  const validateSession = (user: User) => {
    if (!user.sessionToken) return false;
    try {
      const payload = JSON.parse(atob(user.sessionToken.split('.')[1]));
      return payload.exp > Date.now();
    } catch { return false; }
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (savedUser) {
      const parsed = JSON.parse(savedUser) as User;
      if (validateSession(parsed)) {
        setCurrentUser(parsed);
        setFormName(parsed.name);
        setFormEmail(parsed.email);
        setFormPhone(parsed.phone);
      } else {
        localStorage.removeItem('bfc_user_profile');
      }
    }
    const savedCart = localStorage.getItem('bfc_cart');
    if (savedCart) setCart(JSON.parse(savedCart));
  }, []);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('bfc_user_profile', JSON.stringify(currentUser));
    }
  }, [currentUser]);

  useEffect(() => {
    localStorage.setItem('bfc_cart', JSON.stringify(cart));
  }, [cart]);

  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [searchQuery, activeCategory, menuItems]);

  const handleAddToCart = (item: MenuItem, isSub: boolean = false) => {
    setCart(prev => {
      const existing = prev.find(c => c.item.id === item.id && c.isSubscription === isSub);
      if (existing) {
        return prev.map(c => (c.item.id === item.id && c.isSubscription === isSub) ? { ...c, qty: c.qty + 1 } : c);
      }
      return [...prev, { item, qty: 1, isSubscription: isSub }];
    });
    showToast("Added to Bag", "success");
  };

  const handleAuth = async (isRegistering: boolean = false) => {
    // Basic offline check for auth
    if (!isOnline) {
      showToast('Sync Required for Identity Update', 'error');
      return;
    }

    if (!formEmail || !formPass) {
      showToast('Credentials Missing', 'error');
      return;
    }

    setIsAuthenticating(true);
    // Simulate server processing
    await new Promise(r => setTimeout(r, 1200));

    const emailKey = formEmail.toLowerCase().trim();
    const privileged = MOCK_AUTH_DB[emailKey as keyof typeof MOCK_AUTH_DB];

    if (privileged && privileged.pass === formPass) {
      const user: User = {
        id: 'SEC-' + Math.random().toString(36).slice(7).toUpperCase(),
        name: privileged.name, 
        email: emailKey, 
        phone: '01700-000000',
        role: privileged.role, 
        loyaltyPoints: 1000, 
        tier: 'PLATINUM',
        wishlist: [], 
        referralCode: 'BFC-MASTER',
        sessionToken: generateMockToken(privileged.role, emailKey)
      };

      // CRITICAL: Force save to localStorage before changing view to prevent race condition
      localStorage.setItem('bfc_user_profile', JSON.stringify(user));
      setCurrentUser(user);
      showToast(`${privileged.role} Authorized`, 'success');
      setView('ADMIN');
    } else if (!privileged && !isRegistering) {
      const user: User = {
        id: 'U-MOCK', 
        name: formName || 'Customer Node', 
        email: emailKey,
        phone: '01XXXXXXXXX', 
        role: UserRole.CUSTOMER, 
        loyaltyPoints: 120,
        tier: 'GOLD', 
        wishlist: [], 
        referralCode: 'BFC-GUEST',
        sessionToken: generateMockToken(UserRole.CUSTOMER, emailKey)
      };
      localStorage.setItem('bfc_user_profile', JSON.stringify(user));
      setCurrentUser(user);
      showToast('Welcome back!', 'success');
      setView('HOME');
    } else if (isRegistering) {
       const user: User = {
        id: 'U-' + Date.now(), 
        name: formName, 
        email: emailKey,
        phone: formPhone, 
        role: UserRole.CUSTOMER, 
        loyaltyPoints: 0,
        tier: 'SILVER', 
        wishlist: [], 
        referralCode: 'BFC-' + Math.random().toString(36).slice(7).toUpperCase(),
        sessionToken: generateMockToken(UserRole.CUSTOMER, emailKey)
      };
      localStorage.setItem('bfc_user_profile', JSON.stringify(user));
      setCurrentUser(user);
      showToast('Node Established', 'success');
      setView('HOME');
    } else {
      showToast('Access Denied: Invalid Credentials', 'error');
    }
    setIsAuthenticating(false);
  };

  const handleProfileUpdate = () => {
    if (!currentUser) return;
    const updatedUser = {
      ...currentUser,
      name: formName,
      phone: formPhone,
    };
    setCurrentUser(updatedUser);
    showToast('Profile Updated', 'success');
  };

  const isPrivileged = currentUser && currentUser.role !== UserRole.CUSTOMER;

  if (view === 'ADMIN' && isPrivileged) {
    return (
      <AdminPanel 
        userRole={currentUser.role} 
        onLogout={() => { 
          localStorage.removeItem('bfc_user_profile');
          setCurrentUser(null); 
          setView('HOME'); 
        }}
        menuItems={menuItems}
        setMenuItems={setMenuItems}
        orders={allOrders}
        setOrders={setAllOrders}
      />
    );
  }

  const subTotal = cart.reduce((acc, curr) => acc + (curr.item.price * curr.qty), 0);
  const deliveryCharge = deliveryZone.includes('Gulshan') ? 50 : 70;
  const tax = Math.round(subTotal * 0.05);
  const grandTotal = subTotal + (subTotal > 0 ? deliveryCharge + tax : 0);

  const finalizeOrder = () => {
    if (!isOnline) return showToast('Node Link Lost. Cannot Transmit.', 'error');
    if (paymentMethod === 'CARD' && (!cardDetails.number || cardDetails.number.length < 16)) return showToast("Verification Failed", "error");
    if (['BKASH', 'NAGAD'].includes(paymentMethod) && !transactionId) return showToast("Trx ID Missing", "error");

    setIsProcessing(true);
    setTimeout(() => {
      const newOrder: Order = {
        id: 'ORD-' + Math.floor(10000 + Math.random() * 90000),
        customerId: currentUser?.id || 'GUEST',
        customerName: currentUser?.name || 'Guest',
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total: grandTotal, status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(), paymentStatus: 'PAID',
        paymentMethod, address: formPass || 'No address provided', deliveryZone, deliverySlot,
        pointsEarned: Math.floor(subTotal / 10),
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };
      setAllOrders([newOrder, ...allOrders]);
      setIsProcessing(false);
      setOrderCode(newOrder.id);
      setCart([]);
      setView('TRACKING');
      if (currentUser) {
        setCurrentUser({ ...currentUser, loyaltyPoints: currentUser.loyaltyPoints + newOrder.pointsEarned });
      }
      showToast('Transmission Confirmed', 'success');
    }, 2000);
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans selection:bg-red-100 overflow-x-hidden">
      {!isOnline && (
        <div className="fixed top-0 left-0 w-full z-[1100] bg-orange-500 text-white text-[10px] font-black uppercase tracking-[4px] py-2 flex items-center justify-center gap-3 animate-slide-up">
           <i className="fas fa-cloud-slash animate-pulse"></i>
           Offline Mode: Node Local Sync Only
        </div>
      )}

      {isAuthenticating && (
        <div className="fixed inset-0 z-[1000] bg-gray-950/95 backdrop-blur-3xl flex flex-col items-center justify-center text-white">
           <div className="w-24 h-24 mb-10 relative">
              <div className="absolute inset-0 border-4 border-red-600/20 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-red-600 rounded-full border-t-transparent animate-spin"></div>
              <div className="absolute inset-4 bg-red-600 rounded-full animate-pulse flex items-center justify-center"><i className="fas fa-shield-halved text-xl"></i></div>
           </div>
           <h2 className="text-2xl font-black uppercase tracking-[8px]">Uplink Authorized</h2>
        </div>
      )}

      <div className="fixed top-12 right-8 z-[200] space-y-4 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-center gap-4 px-8 py-5 rounded-3xl shadow-2xl border bg-white animate-slide-up border-green-100 text-green-700">
            <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark text-red-600' : 'fa-circle-check text-green-600'}`}></i>
            <p className="font-black text-[12px] uppercase tracking-wider">{t.message}</p>
          </div>
        ))}
      </div>

      <nav className={`sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-14 py-4 flex justify-between items-center gpu transition-all ${!isOnline ? 'mt-8' : ''}`}>
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 lg:w-12 lg:h-12 bg-red-600 rounded-[15px] flex items-center justify-center text-white text-xl lg:text-2xl font-black shadow-xl ring-4 ring-red-50 transition-all group-hover:rotate-3">B</div>
          <h1 className="text-xl lg:text-2xl font-black text-red-600 tracking-tighter">BFC</h1>
        </div>
        <div className="hidden lg:flex items-center gap-10 text-[11px] font-black uppercase tracking-[3px] text-gray-400">
          <button onClick={()=>setView('HOME')} className={view === 'HOME' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'হোম' : 'Home'}</button>
          <button onClick={()=>setView('MENU')} className={view === 'MENU' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'মেনু' : 'Menu'}</button>
          {isPrivileged && (
            <button onClick={()=>setView('ADMIN')} className="text-gray-900 bg-gray-50 px-5 py-2 rounded-full border border-gray-100 hover:border-red-600 hover:text-red-600 transition-all font-black flex items-center gap-3 shadow-sm">
              <i className="fas fa-shield-halved text-red-600"></i>
              {language === 'BN' ? 'ড্যাশবোর্ড' : 'Dashboard'}
            </button>
          )}
          <button onClick={()=>setView('WISHLIST')} className={view === 'WISHLIST' ? 'text-red-600' : 'hover:text-red-600'}>{language === 'BN' ? 'পছন্দ' : 'Wishlist'}</button>
          <button onClick={()=>setLanguage(language === 'BN' ? 'EN' : 'BN')} className="text-gray-900 border-x px-4 border-gray-100 hover:text-red-600 transition-colors">{language}</button>
        </div>
        <div className="flex items-center gap-3 lg:gap-6">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 lg:w-12 lg:h-12 bg-gray-50 text-gray-800 rounded-2xl flex items-center justify-center shadow-inner group transition-all active:scale-90">
            <i className="fas fa-shopping-basket text-lg group-hover:-translate-y-0.5 transition-transform"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[9px] w-5 h-5 rounded-full flex items-center justify-center ring-4 ring-white font-black">{cart.reduce((a,b)=>a+b.qty, 0)}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 lg:w-12 lg:h-12 rounded-2xl border-2 border-white overflow-hidden shadow-xl bg-red-600 group active:scale-90">
              {currentUser.profileImage ? <img src={currentUser.profileImage} className="w-full h-full object-cover group-hover:scale-110 transition-transform" /> : <div className="w-full h-full flex items-center justify-center text-white font-black">{currentUser.name.charAt(0)}</div>}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl" onClick={() => setView('LOGIN')}>{language === 'BN' ? 'লগইন' : 'Login'}</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-6 lg:py-12">
        {view === 'HOME' && (
          <div className="animate-slide-up space-y-24">
            <header className="relative h-[450px] lg:h-[700px] rounded-[60px] lg:rounded-[100px] overflow-hidden shadow-3xl group">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover transition-transform duration-[10s] group-hover:scale-110" />
               <div className="absolute inset-0 bg-gradient-to-r from-black/90 via-black/40 to-transparent flex flex-col justify-center px-8 lg:px-24">
                  <span className="text-red-600 font-black uppercase tracking-[8px] text-[10px] mb-6 block animate-slide-up">Authentic Taste of Dhaka</span>
                  <h2 className="text-4xl lg:text-[120px] font-black text-white leading-[0.85] mb-12 tracking-tighter animate-slide-up [animation-delay:0.1s]">
                    {language === 'BN' ? 'আসল স্বাদ' : 'Real Taste'}<br/>
                    <span className="text-red-600">{language === 'BN' ? 'সেরা খাবার' : 'Fine Food'}</span>
                  </h2>
                  <div className="flex flex-wrap gap-4 lg:gap-6">
                    <Button size="lg" className="rounded-[35px] w-full sm:w-fit px-12 py-6 lg:px-16 lg:py-8 text-xl lg:text-2xl shadow-2xl shadow-red-600/20 animate-slide-up [animation-delay:0.2s]" onClick={() => setView('MENU')}>{language === 'BN' ? 'মেনু দেখুন' : 'Explore Menu'}</Button>
                  </div>
               </div>
            </header>
            <section>
              <div className="flex flex-col sm:flex-row items-start sm:items-end justify-between mb-12 gap-6">
                <div>
                  <h3 className="text-4xl lg:text-7xl font-black text-gray-800 tracking-tighter leading-none">{language === 'BN' ? 'আপনার জন্য সেরা' : 'Elite Selections'}</h3>
                  <p className="text-[10px] text-gray-400 font-black uppercase tracking-[5px] mt-4">Curated culinary excellence</p>
                </div>
                <button onClick={()=>setView('MENU')} className="text-red-600 font-black text-[10px] uppercase tracking-widest hover:underline pb-2 transition-all">View Full Menu</button>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8 lg:gap-12">
                 {menuItems.slice(0, 4).map(item => (
                   <ProductCard 
                     key={item.id} item={item} language={language} 
                     isWished={currentUser?.wishlist.includes(item.id)}
                     onWishlist={() => {
                        if(!currentUser) return setView('LOGIN');
                        const isWished = currentUser.wishlist.includes(item.id);
                        setCurrentUser({ ...currentUser, wishlist: isWished ? currentUser.wishlist.filter(id => id !== item.id) : [...currentUser.wishlist, item.id] });
                        showToast(isWished ? 'Removed' : 'Pinned', 'success');
                     }}
                     onDetails={() => { setSelectedProduct(item); setIsSubscriptionMode(false); }}
                     onAdd={(item: MenuItem) => handleAddToCart(item)} 
                   />
                 ))}
              </div>
            </section>
          </div>
        )}

