                   <h3 className="text-2xl lg:text-4xl font-black text-gray-800 tracking-tighter mb-4 text-center">Your bag is empty</h3>
                   <Button size="lg" className="rounded-[30px] px-12 py-6 text-xl shadow-2xl mt-8" onClick={()=>setView('MENU')}>Browse Menu</Button>
                </div>
             ) : (
                <div className="space-y-8">
