      if (!savedUser) return false;
      try {
        const user = JSON.parse(savedUser) as User;
        const payload = JSON.parse(atob(user.sessionToken!.split('.')[1]));
        if (payload.role !== userRole || payload.exp < Date.now()) return false;
        return true;
      } catch { return false; }
    };

    if (verify()) {
      setIsAuthorized(true);
    } else {
      // Small timeout to allow localStorage write from App.tsx to settle
      setTimeout(() => {
        if (verify()) setIsAuthorized(true);
        else onLogout();
      }, 300);
