                    {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start animate-slide-up">
                <div className="bg-white/50 px-5 py-3.5 rounded-[20px] rounded-tl-none flex gap-1.5 border border-white">
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce"></div>
                </div>
              </div>
            )}
          </div>

          {/* Quick Actions & Input */}
          <div className="p-6 bg-white/40 backdrop-blur-xl border-t border-white/20">
            {messages.length < 5 && !isTyping && (
              <div className="flex gap-2 overflow-x-auto pb-5 scrollbar-hide">
                {QUICK_ACTIONS.map(action => (
                  <button 
                    key={action}
                    onClick={() => handleSend(action)}
                    className="whitespace-nowrap px-5 py-2.5 bg-white/80 hover:bg-red-600 hover:text-white rounded-full text-[9px] font-black uppercase tracking-widest text-gray-500 border border-gray-100 transition-all active:scale-95 shadow-sm"
                  >
                    {action}
                  </button>
                ))}
              </div>
            )}

            <div className="relative flex items-center bg-white rounded-3xl p-2 shadow-inner border border-gray-50 group focus-within:ring-4 ring-red-50 transition-all">
              <button 
                onClick={toggleVoice}
                className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'text-gray-300 hover:text-red-600'}`}
              >
                <i className={`fas ${isListening ? 'fa-microphone-lines' : 'fa-microphone'}`}></i>
              </button>
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={isListening ? "Listening..." : "Ask anything..."}
                className="flex-1 bg-transparent border-none py-3 px-3 outline-none text-sm font-bold text-gray-800"
              />
              <button 
                onClick={() => handleSend()}
                disabled={!input.trim() || isTyping}
                className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center hover:bg-red-600 transition-all disabled:opacity-20 shadow-lg active:scale-90"
              >
                <i className="fas fa-paper-plane text-xs"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-gray-950 text-white w-16 h-16 lg:w-20 lg:h-20 rounded-[28px] lg:rounded-[32px] shadow-3xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all duration-500 group relative border-4 border-white"
        >
          <div className="absolute inset-0 bg-gradient-to-tr from-red-600 to-red-800 opacity-0 group-hover:opacity-100 transition-opacity rounded-3xl"></div>
          <i className="fas fa-comment-dots text-2xl lg:text-3xl relative z-10"></i>
          <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-600 border-4 border-white rounded-full z-20 animate-bounce"></span>
        </button>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'info';
  id: number;
}

const MOCK_AUTH_DB = {
  'admin@bfc.com': { pass: 'admin123', role: UserRole.ADMIN, name: 'Root Admin' },
  'manager@bfc.com': { pass: 'manager456', role: UserRole.MANAGER, name: 'Node Manager' },
  'staff@bfc.com': { pass: 'staff789', role: UserRole.STAFF, name: 'Logistics Staff' }
};

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE' | 'PAYMENT'>('HOME');
  const [language, setLanguage] = useState<'EN' | 'BN'>('BN');
  const [selectedProduct, setSelectedProduct] = useState<MenuItem | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Form States
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [formAddress, setFormAddress] = useState('');
  const [showPass, setShowPass] = useState(false);

  useEffect(() => {
    const handleOnline = () => { setIsOnline(true); showToast('System Online', 'success'); };
    const handleOffline = () => { setIsOnline(false); showToast('Offline Mode Active', 'error'); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  };

  const generateMockToken = (role: UserRole, email: string) => {
    const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
    const payload = btoa(JSON.stringify({ role, email, exp: Date.now() + 86400000 }));
    return `${header}.${payload}.bfc-signature`;
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (savedUser) {
      try {
        const parsed = JSON.parse(savedUser) as User;
        const payload = JSON.parse(atob(parsed.sessionToken!.split('.')[1]));
        if (payload.exp > Date.now()) {
          setCurrentUser(parsed);
          setFormEmail(parsed.email);
        }
      } catch { localStorage.removeItem('bfc_user_profile'); }
    }
    const savedCart = localStorage.getItem('bfc_cart');
    if (savedCart) setCart(JSON.parse(savedCart));
  }, []);

  useEffect(() => {
    localStorage.setItem('bfc_cart', JSON.stringify(cart));
  }, [cart]);

  const handleAddToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(c => c.item.id === item.id);
      if (existing) {
        return prev.map(c => c.item.id === item.id ? { ...c, qty: c.qty + 1 } : c);
      }
      return [...prev, { item, qty: 1 }];
    });
    showToast("Added to Bag", "success");
  };

  const handleAuth = async () => {
    if (!formEmail || !formPass) return showToast('Credentials required', 'error');
    setIsAuthenticating(true);

    // Aesthetic delay for "scanning" effect
    await new Promise(r => setTimeout(r, 2000));

    const emailKey = formEmail.toLowerCase().trim();
    const privileged = MOCK_AUTH_DB[emailKey as keyof typeof MOCK_AUTH_DB];

    if (privileged && privileged.pass === formPass) {
      const user: User = {
        id: 'SEC-' + Math.random().toString(36).slice(7).toUpperCase(),
        name: privileged.name, email: emailKey, phone: '01700-000000',
        role: privileged.role, loyaltyPoints: 1000, tier: 'PLATINUM',
        wishlist: [], referralCode: 'BFC-MASTER',
        sessionToken: generateMockToken(privileged.role, emailKey)
      };
      localStorage.setItem('bfc_user_profile', JSON.stringify(user));
      setCurrentUser(user);
      showToast(`Welcome back, ${user.name}`, 'success');
      setView('ADMIN');
    } else if (!privileged) {
      const user: User = {
        id: 'U-' + Date.now(), name: 'Customer', email: emailKey,
        phone: '01XXXXXXXXX', role: UserRole.CUSTOMER, loyaltyPoints: 10,
        tier: 'SILVER', wishlist: [], referralCode: 'BFC-GUEST',
        sessionToken: generateMockToken(UserRole.CUSTOMER, emailKey)
      };
      localStorage.setItem('bfc_user_profile', JSON.stringify(user));
      setCurrentUser(user);
      showToast('Login Successful', 'success');
      setView('HOME');
    } else {
      showToast('Access Denied: Invalid Password', 'error');
    }
    setIsAuthenticating(false);
  };

  const isPrivileged = currentUser && currentUser.role !== UserRole.CUSTOMER;

  if (view === 'ADMIN' && isPrivileged) {
    return (
      <AdminPanel 
        userRole={currentUser.role} 
        onLogout={() => { 
          localStorage.removeItem('bfc_user_profile');
          setCurrentUser(null); 
          setView('HOME'); 
        }}
        menuItems={menuItems}
        setMenuItems={setMenuItems}
        orders={allOrders}
        setOrders={setAllOrders}
      />
    );
  }

  const subTotal = cart.reduce((acc, curr) => acc + (curr.item.price * curr.qty), 0);
  const deliveryCharge = 50;
  const tax = Math.round(subTotal * 0.05);
  const grandTotal = subTotal + (subTotal > 0 ? deliveryCharge + tax : 0);

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans selection:bg-red-100 overflow-x-hidden">
      {/* Toast System */}
      <div className="fixed top-12 right-8 z-[1000] space-y-4 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-center gap-4 px-8 py-5 rounded-3xl shadow-2xl border bg-white animate-slide-up border-gray-100 text-gray-800 ring-1 ring-black/5">
            <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-xs ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
              <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark' : 'fa-circle-check'}`}></i>
            </div>
            <p className="font-black text-[12px] uppercase tracking-wider">{t.message}</p>
          </div>
        ))}
      </div>

      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-14 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-[15px] flex items-center justify-center text-white text-xl font-black shadow-xl group-hover:rotate-6 transition-transform">B</div>
          <h1 className="text-xl lg:text-2xl font-black text-red-600 tracking-tighter">BFC</h1>
        </div>
        <div className="hidden lg:flex items-center gap-10 text-[11px] font-black uppercase tracking-[3px] text-gray-400">
          <button onClick={()=>setView('HOME')} className={view === 'HOME' ? 'text-red-600' : 'hover:text-red-600'}>Home</button>
          <button onClick={()=>setView('MENU')} className={view === 'MENU' ? 'text-red-600' : 'hover:text-red-600'}>Menu</button>
          {isPrivileged && <button onClick={()=>setView('ADMIN')} className="text-gray-900 bg-gray-50 px-5 py-2 rounded-full border border-gray-100 font-black">Admin Hub</button>}
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 bg-gray-50 rounded-2xl flex items-center justify-center active:scale-90 transition-transform">
            <i className="fas fa-shopping-basket text-gray-600"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[9px] w-5 h-5 rounded-full flex items-center justify-center ring-2 ring-white font-black">{cart.reduce((a,b)=>a+b.qty, 0)}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 rounded-2xl bg-red-600 text-white font-black flex items-center justify-center overflow-hidden">
               {currentUser.name.charAt(0)}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl" onClick={() => setView('LOGIN')}>Secure Login</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-6 lg:py-12 min-h-[80vh]">
        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto relative mt-12 lg:mt-24">
            {/* Animated Background Elements for Login */}
            <div className="absolute -top-20 -left-20 w-64 h-64 bg-red-600/5 rounded-full blur-[100px] animate-pulse"></div>
            <div className="absolute -bottom-20 -right-20 w-64 h-64 bg-orange-600/5 rounded-full blur-[100px] animate-pulse [animation-delay:1s]"></div>

            <div className="relative z-10 bg-white/70 backdrop-blur-3xl p-10 lg:p-14 rounded-[60px] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.1)] border border-white animate-slide-up">
               <div className="relative w-24 h-24 mx-auto mb-10 group">
                  <div className="absolute inset-0 bg-red-600 rounded-[35px] rotate-6 group-hover:rotate-12 transition-transform shadow-xl"></div>
                  <div className="absolute inset-0 bg-gray-950 rounded-[35px] flex items-center justify-center text-white text-3xl shadow-2xl relative z-10 transition-transform group-hover:scale-105">
                     {isAuthenticating ? (
                       <i className="fas fa-fingerprint animate-pulse text-red-500"></i>
                     ) : (
                       <i className="fas fa-shield-halved"></i>
                     )}
                  </div>
                  {isAuthenticating && (
                    <div className="absolute -inset-2 border-2 border-red-600/30 rounded-[40px] animate-ping"></div>
