               <div className="text-center mb-10">
                  <h2 className="text-4xl font-black text-gray-900 tracking-tighter uppercase mb-2">Secure Access</h2>
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-[4px]">Verified Terminal Login</p>
               </div>

               <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-gray-400 tracking-[5px] block ml-6">Registry ID</label>
                    <div className="relative group">
                      <i className="fas fa-envelope absolute left-6 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-red-600 transition-colors"></i>
                      <input 
                        type="email" 
                        value={formEmail} 
                        onChange={(e)=>setFormEmail(e.target.value)}
                        placeholder="admin@bfc.com"
                        className="w-full bg-gray-50/50 border-2 border-transparent focus:border-red-600/10 focus:bg-white rounded-3xl px-14 py-5 font-bold outline-none transition-all"
                      />
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-gray-400 tracking-[5px] block ml-6">Secret Key</label>
                    <div className="relative group">
                      <i className="fas fa-lock absolute left-6 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-red-600 transition-colors"></i>
                      <input 
                        type={showPass ? 'text' : 'password'} 
                        value={formPass} 
                        onChange={(e)=>setFormPass(e.target.value)}
                        placeholder="••••••••"
                        className="w-full bg-gray-50/50 border-2 border-transparent focus:border-red-600/10 focus:bg-white rounded-3xl px-14 py-5 font-bold outline-none transition-all"
                      />
                      <button 
                        onClick={() => setShowPass(!showPass)}
                        className="absolute right-6 top-1/2 -translate-y-1/2 text-gray-300 hover:text-gray-600 transition-colors"
                      >
                        <i className={`fas ${showPass ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                      </button>
                    </div>
                  </div>

                  <Button 
