                  >
                    {isAuthenticating ? (
                      <span className="flex items-center gap-3">
                        <i className="fas fa-circle-notch fa-spin"></i>
                        Authenticating...
                      </span>
                    ) : 'Initialize Session'}
                  </Button>

                  <div className="pt-8 text-center border-t border-gray-100">
                    <p className="text-[10px] text-gray-300 font-black uppercase tracking-widest leading-relaxed">
                      Encrypted End-to-End Node Login.<br/>
                      Unauthorized access is logged.
                    </p>
                  </div>
               </div>
            </div>
          </div>
        )}

        {view === 'HOME' && (
          <div className="animate-slide-up space-y-24">
            <header className="relative h-[450px] lg:h-[650px] rounded-[60px] overflow-hidden shadow-3xl group">
