               <div className="absolute inset-0 bg-gradient-to-r from-black/80 to-transparent flex flex-col justify-center px-8 lg:px-24">
                  <h2 className="text-5xl lg:text-[100px] font-black text-white leading-[0.9] mb-8 tracking-tighter">
                    {language === 'BN' ? 'আসল স্বাদ' : 'Real Taste'}<br/>
                    <span className="text-red-600">{language === 'BN' ? 'সেরা খাবার' : 'Fine Food'}</span>
