             </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-4xl mx-auto animate-slide-up space-y-12">
             <h2 className="text-7xl font-black text-gray-800 tracking-tighter uppercase leading-none">Your Bag</h2>
             {cart.length === 0 ? (
                <div className="py-32 bg-white rounded-[60px] text-center border-4 border-dashed border-gray-100">
                   <p className="text-gray-300 font-black uppercase tracking-widest text-2xl">Bag is Empty</p>
                   <Button className="mt-8 rounded-full" onClick={()=>setView('MENU')}>Browse Menu</Button>
                </div>
             ) : (
                <div className="space-y-8">
                   {cart.map((c, idx) => (
