import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

const QUICK_ACTIONS = [
  "Recommend Kacchi 🍛",
  "Is it Spicy? 🔥",
  "Track Order 🚚",
  "Offers 🎁"
];

export const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { 
      role: 'model', 
      text: "Yo! BFC Assist here. 👋 Ready for some legendary Kacchi or need help with a delivery? I got you!", 
      timestamp: new Date() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isTyping]);

  const toggleVoice = () => {
    if (!('webkitSpeechRecognition' in window)) {
      alert("Voice recognition not supported in this browser.");
      return;
    }

    // @ts-ignore
    const recognition = new window.webkitSpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(transcript);
      handleSend(transcript);
    };
    recognition.start();
  };

  const handleSend = async (text: string = input) => {
    const messageToSend = text.trim();
    if (!messageToSend) return;

    const userMsg: ChatMessage = { role: 'user', text: messageToSend, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));

    try {
      const botResponse = await bfcAssistChat(messageToSend, history);
      setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Connection's a bit glitchy. Try again? 😅", timestamp: new Date() }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-10 lg:right-10 z-[100] font-sans">
      {isOpen ? (
        <div className="bg-white/80 backdrop-blur-3xl w-[94vw] sm:w-[420px] h-[80vh] sm:h-[680px] rounded-[40px] shadow-[0_40px_100px_-20px_rgba(0,0,0,0.3)] flex flex-col border border-white/40 overflow-hidden animate-slide-up gpu">

          {/* Enhanced Premium Header */}
          <div className="bg-gray-950 p-7 text-white relative overflow-hidden shrink-0">
            <div className="absolute top-0 right-0 w-64 h-64 bg-red-600/20 rounded-full blur-[80px] -mr-32 -mt-32"></div>
            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-4">
                <div className="relative">
                  <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center shadow-2xl rotate-3">
                    <i className="fas fa-robot text-xl"></i>
                  </div>
                  <span className="absolute -top-1 -right-1 w-3.5 h-3.5 bg-emerald-500 border-4 border-gray-950 rounded-full animate-pulse"></span>
                </div>
                <div>
                  <h3 className="font-black text-lg tracking-tight leading-none uppercase">BFC Assist</h3>
                  <p className="text-[8px] font-bold uppercase tracking-[4px] opacity-40 mt-1">AI Concierge active</p>
                </div>
              </div>
              <div className="flex gap-2">
                <button onClick={() => setMessages([messages[0]])} className="w-10 h-10 hover:bg-white/10 rounded-xl flex items-center justify-center transition-all opacity-40 hover:opacity-100">
                  <i className="fas fa-rotate-left text-xs"></i>
                </button>
                <button onClick={() => setIsOpen(false)} className="w-10 h-10 hover:bg-white/10 rounded-xl flex items-center justify-center transition-all">
                  <i className="fas fa-xmark opacity-60"></i>
                </button>
              </div>
            </div>
          </div>

          {/* Messages Area */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 scrollbar-hide">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                <div className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'} max-w-[85%]`}>
                  <div className={`px-5 py-3.5 rounded-[24px] text-sm font-bold leading-relaxed shadow-sm ${
                    m.role === 'user' 
                    ? 'bg-gradient-to-br from-red-600 to-red-700 text-white rounded-br-none' 
                    : 'bg-white text-gray-800 border border-gray-100 rounded-tl-none'
                  }`}>
                    {m.text}
                  </div>
                  <span className="text-[8px] mt-2 font-black tracking-widest opacity-20 uppercase px-2">
                    {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start animate-slide-up">
                <div className="bg-white/50 px-5 py-3.5 rounded-[20px] rounded-tl-none flex gap-1.5 border border-white">
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce"></div>
                </div>
              </div>
            )}
          </div>

          {/* Quick Actions & Input */}
          <div className="p-6 bg-white/40 backdrop-blur-xl border-t border-white/20">
            {messages.length < 5 && !isTyping && (
              <div className="flex gap-2 overflow-x-auto pb-5 scrollbar-hide">
                {QUICK_ACTIONS.map(action => (
                  <button 
                    key={action}
                    onClick={() => handleSend(action)}
                    className="whitespace-nowrap px-5 py-2.5 bg-white/80 hover:bg-red-600 hover:text-white rounded-full text-[9px] font-black uppercase tracking-widest text-gray-500 border border-gray-100 transition-all active:scale-95 shadow-sm"
                  >
                    {action}
                  </button>
                ))}
              </div>
            )}

            <div className="relative flex items-center bg-white rounded-3xl p-2 shadow-inner border border-gray-50 group focus-within:ring-4 ring-red-50 transition-all">
              <button 
                onClick={toggleVoice}
                className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'text-gray-300 hover:text-red-600'}`}
              >
                <i className={`fas ${isListening ? 'fa-microphone-lines' : 'fa-microphone'}`}></i>
              </button>
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={isListening ? "Listening..." : "Ask anything..."}
                className="flex-1 bg-transparent border-none py-3 px-3 outline-none text-sm font-bold text-gray-800"
              />
              <button 
                onClick={() => handleSend()}
                disabled={!input.trim() || isTyping}
                className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center hover:bg-red-600 transition-all disabled:opacity-20 shadow-lg active:scale-90"
              >
                <i className="fas fa-paper-plane text-xs"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-gray-950 text-white w-16 h-16 lg:w-20 lg:h-20 rounded-[28px] lg:rounded-[32px] shadow-3xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all duration-500 group relative border-4 border-white"
        >
          <div className="absolute inset-0 bg-gradient-to-tr from-red-600 to-red-800 opacity-0 group-hover:opacity-100 transition-opacity rounded-3xl"></div>
          <i className="fas fa-comment-dots text-2xl lg:text-3xl relative z-10"></i>
          <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-600 border-4 border-white rounded-full z-20 animate-bounce"></span>
        </button>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { Button } from './Button';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  BarChart, Bar, Cell, PieChart, Pie
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, orders: 240 },
  { name: 'Sun', sales: 3800, orders: 198 },
  { name: 'Mon', sales: 5200, orders: 310 },
  { name: 'Tue', sales: 4800, orders: 280 },
  { name: 'Wed', sales: 6200, orders: 390 },
  { name: 'Thu', sales: 5800, orders: 340 },
  { name: 'Fri', sales: 8500, orders: 480 },
];

const CUSTOMER_RETENTION = [
  { name: 'Active', value: 72, color: '#dc2626' },
  { name: 'New Nodes', value: 28, color: '#10b981' },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const [activeTab, setActiveTab] = useState(userRole === UserRole.STAFF ? 'orders' : 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [exporting, setExporting] = useState<string | null>(null);

  useEffect(() => {
    const verifyAccess = () => {
      const savedUser = localStorage.getItem('bfc_user_profile');
      if (!savedUser) return false;
      try {
        const user = JSON.parse(savedUser) as User;
        // Basic check: in a real app, we'd verify the JWT signature/exp
        return user.role === userRole;
      } catch { return false; }
    };

    if (verifyAccess()) {
      setIsAuthorized(true);
    } else {
      onLogout();
    }
  }, [userRole, onLogout]);

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length
    };
