  const handleExport = async (format: 'PDF' | 'EXCEL', report: string) => {
    setExporting(`${report}-${format}`);
    await new Promise(r => setTimeout(r, 2000));
    setExporting(null);
    showToast(`${report} exported successfully in ${format} format.`, 'success');
  };

  const handleExportAll = async (format: 'PDF' | 'EXCEL') => {
    setExporting(`ALL-${format}`);
    await new Promise(r => setTimeout(r, 4000));
    setExporting(null);
    showToast(`Consolidated ${format} report bundle generated.`, 'success');
  };

  // Internal toast helper for Admin Panel
  const [adminToast, setAdminToast] = useState<{msg: string, type: string} | null>(null);
  const showToast = (msg: string, type: string) => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 3000);
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white">
      <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
      <p className="mt-8 text-[10px] font-black uppercase tracking-[6px] animate-pulse">Synchronizing Node Security...</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F1F3F6] overflow-hidden font-sans relative">
