                    >
                      {exporting === 'ALL-EXCEL' ? <i className="fas fa-circle-notch fa-spin mr-2"></i> : <i className="fas fa-file-excel mr-2"></i>}
                      Export All Excel
                    </Button>
                  </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                  <ReportModule 
                    title="Customer Behavior" 
                    icon="fa-fingerprint" 
                    desc="Analyze order frequency, churn rates, and high-value customer clusters."
                    onPdf={() => handleExport('PDF', 'Customer Behavior')}
                    onExcel={() => handleExport('EXCEL', 'Customer Behavior')}
                    loading={exporting}
                  />
                  <ReportModule 
                    title="Inventory Velocity" 
                    icon="fa-boxes-stacked" 
                    desc="Stock depletion trends, replenishment alerts, and wastage auditing."
                    onPdf={() => handleExport('PDF', 'Inventory Velocity')}
                    onExcel={() => handleExport('EXCEL', 'Inventory Velocity')}
                    loading={exporting}
                  />
                  <ReportModule 
                    title="Regional Density" 
                    icon="fa-map-location-dot" 
                    desc="Logistics performance across Dhaka delivery nodes and heatmaps."
                    onPdf={() => handleExport('PDF', 'Regional Density')}
                    onExcel={() => handleExport('EXCEL', 'Regional Density')}
                    loading={exporting}
                  />
                  <ReportModule 
                    title="Financial Forensics" 
                    icon="fa-vault" 
                    desc="Gross inflows, platform fees, and tax liability calculations."
                    onPdf={() => handleExport('PDF', 'Fiscal Audit')}
                    onExcel={() => handleExport('EXCEL', 'Fiscal Audit')}
                    loading={exporting}
                  />
                  <ReportModule 
                    title="MenuItem Performance" 
                    icon="fa-utensils" 
                    desc="Profit margin analysis per item and popularity forecasting."
                    onPdf={() => handleExport('PDF', 'MenuItem Performance')}
                    onExcel={() => handleExport('EXCEL', 'MenuItem Performance')}
                    loading={exporting}
                  />
                  <ReportModule 
                    title="System Operations" 
                    icon="fa-server" 
                    desc="Platform uptime, API latency, and security logs for the node."
                    onPdf={() => handleExport('PDF', 'System Ops')}
                    onExcel={() => handleExport('EXCEL', 'System Ops')}
                    loading={exporting}
                  />
               </div>
            </div>
          )}

          {activeTab === 'inventory' && (
             <div className="space-y-12">
                <div className="flex justify-between items-end">
