                        <div className="flex gap-4 mt-8 w-full">
                           <button onClick={()=>setMenuItems(prev=>prev.map(i=>i.id===item.id ? {...i, stock: Math.max(0, i.stock-1)} : i))} className="flex-1 bg-gray-100 p-4 rounded-2xl hover:bg-red-50 hover:text-red-600 transition-colors font-black">-</button>
                           <button onClick={()=>setMenuItems(prev=>prev.map(i=>i.id===item.id ? {...i, stock: i.stock+1} : i))} className="flex-1 bg-gray-950 text-white p-4 rounded-2xl hover:bg-red-600 transition-colors font-black">+</button>
                        </div>
                     </div>
                   ))}
                </div>
             </div>
