          {activeTab === 'orders' && (
             <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
               {orders.map(o => (
                  <div key={o.id} className="bg-white p-8 rounded-[40px] border border-gray-50 flex flex-col gap-6 shadow-sm animate-slide-up hover:shadow-xl transition-shadow">
                    <div className="flex justify-between items-start">
                       <div className="flex items-center gap-4">
                          <div className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center font-black shadow-lg">#{o.id.slice(-4)}</div>
                          <div>
                            <p className="font-black text-gray-800 text-lg leading-none mb-1">{o.customerName}</p>
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{o.paymentMethod} • {new Date(o.createdAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                          </div>
                       </div>
                       <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-100 text-emerald-700' : 'bg-red-50 text-red-600'}`}>{o.status}</span>
                    </div>
                    <div className="bg-gray-50 p-6 rounded-3xl space-y-2 flex-1">
                       {o.items.map((i, idx) => (
                         <div key={idx} className="flex justify-between text-[11px] font-bold text-gray-600">
                           <span>{i.name} <span className="text-gray-400">x{i.quantity}</span></span>
                           <span>৳{(i.price * i.quantity).toLocaleString()}</span>
                         </div>
                       ))}
                       <div className="pt-4 mt-4 border-t border-gray-200 flex justify-between font-black text-gray-900">
                          <span>TOTAL</span>
                          <span>৳{o.total.toLocaleString()}</span>
                       </div>
                    </div>
                    <select className="w-full bg-gray-950 text-white rounded-[22px] p-5 text-[10px] font-black uppercase tracking-widest outline-none border-none shadow-xl cursor-pointer hover:bg-red-600 transition-colors" value={o.status} onChange={(e)=>setOrders(prev=>prev.map(ord=>ord.id===o.id ? {...ord, status: e.target.value as OrderStatus}:ord))}>
                      {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
               ))}
             </div>
          )}
        </main>
      </div>
    </div>
  );
};

