  </div>
);

import React, { useState, useEffect, useCallback } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'info';
  id: number;
}

const MOCK_AUTH_DB = {
  'admin@bfc.com': { pass: 'admin123', role: UserRole.ADMIN, name: 'Root Admin' },
  'manager@bfc.com': { pass: 'manager456', role: UserRole.MANAGER, name: 'Node Manager' },
  'staff@bfc.com': { pass: 'staff789', role: UserRole.STAFF, name: 'Logistics Staff' }
};

const MAX_ATTEMPTS = 3;
const LOCKOUT_TIME = 60000; // 1 minute

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE'>('HOME');
  const [language, setLanguage] = useState<'EN' | 'BN'>('BN');
  const [selectedProduct, setSelectedProduct] = useState<MenuItem | null>(null);
  const [activeCategory, setActiveCategory] = useState('All');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Security States
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [failedAttempts, setFailedAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);

  const showToast = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  }, []);

  useEffect(() => {
    const handleOnline = () => { setIsOnline(true); showToast('System Online', 'success'); };
    const handleOffline = () => { setIsOnline(false); showToast('Offline Mode Active', 'error'); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  // Session Management & Token Verification
  useEffect(() => {
    const verifyStoredSession = () => {
      const savedUser = localStorage.getItem('bfc_user_profile');
      if (savedUser) {
        try {
          const parsed = JSON.parse(savedUser) as User;
          if (parsed.sessionToken) {
            const parts = parsed.sessionToken.split('.');
            if (parts.length === 3) {
              const payload = JSON.parse(atob(parts[1]));
              if (payload.exp > Date.now()) {
                setCurrentUser(parsed);
              } else {
                localStorage.removeItem('bfc_user_profile');
                showToast('Session expired. Please re-authenticate.', 'info');
              }
            }
          }
        } catch { 
          localStorage.removeItem('bfc_user_profile'); 
        }
      }
    };
    verifyStoredSession();

    const savedCart = localStorage.getItem('bfc_cart');
    if (savedCart) setCart(JSON.parse(savedCart));
  }, [showToast]);

  useEffect(() => {
    localStorage.setItem('bfc_cart', JSON.stringify(cart));
  }, [cart]);

  const generateSecureToken = (role: UserRole, email: string) => {
    const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
    const payload = btoa(JSON.stringify({ 
      role, 
      email, 
      iat: Date.now(),
      exp: Date.now() + 3600000 // 1 hour session
    }));
    // Simulated HMAC-SHA256 signature
    const signature = btoa(`bfc_secret_key_${email}_${role}`);
    return `${header}.${payload}.${signature}`;
  };

  const handleAuth = async () => {
    if (lockoutUntil && Date.now() < lockoutUntil) {
      const remaining = Math.ceil((lockoutUntil - Date.now()) / 1000);
      return showToast(`Security Lock active. Try again in ${remaining}s`, 'error');
    }

    if (!formEmail || !formPass) return showToast('Registry ID and Secret Key required', 'error');

    setIsAuthenticating(true);
    // Aesthetic delay for "security handshake"
    await new Promise(r => setTimeout(r, 2200));

    const emailKey = formEmail.toLowerCase().trim();
    const privileged = MOCK_AUTH_DB[emailKey as keyof typeof MOCK_AUTH_DB];

    if (privileged && privileged.pass === formPass) {
      setFailedAttempts(0);
      const user: User = {
        id: 'SEC-' + Math.random().toString(36).slice(7).toUpperCase(),
        name: privileged.name, email: emailKey, phone: '01700-000000',
        role: privileged.role, loyaltyPoints: 1000, tier: 'PLATINUM',
        wishlist: [], referralCode: 'BFC-MASTER',
        sessionToken: generateSecureToken(privileged.role, emailKey)
      };
      localStorage.setItem('bfc_user_profile', JSON.stringify(user));
      setCurrentUser(user);
      showToast(`Encrypted Session Established: Welcome ${user.name}`, 'success');
      setView(privileged.role === UserRole.CUSTOMER ? 'HOME' : 'ADMIN');
    } else {
      const newAttempts = failedAttempts + 1;
      setFailedAttempts(newAttempts);

      if (newAttempts >= MAX_ATTEMPTS) {
        setLockoutUntil(Date.now() + LOCKOUT_TIME);
        showToast('Maximum attempts exceeded. Security Lockout triggered.', 'error');
      } else {
        showToast(`Invalid Secret Key. ${MAX_ATTEMPTS - newAttempts} attempts remaining.`, 'error');
      }
    }
    setIsAuthenticating(false);
  };

  const isPrivileged = currentUser && currentUser.role !== UserRole.CUSTOMER;

  if (view === 'ADMIN' && isPrivileged) {
    return (
      <AdminPanel 
        userRole={currentUser.role} 
        onLogout={() => { 
          localStorage.removeItem('bfc_user_profile');
          setCurrentUser(null); 
          setView('HOME'); 
          showToast('Secure Session Terminated', 'info');
        }}
        menuItems={menuItems}
        setMenuItems={setMenuItems}
        orders={allOrders}
        setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans selection:bg-red-100 overflow-x-hidden">
      {/* Toast Notification Container */}
      <div className="fixed top-12 right-8 z-[1000] space-y-4 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-center gap-4 px-8 py-5 rounded-3xl shadow-2xl border bg-white animate-slide-up border-gray-100 text-gray-800 ring-1 ring-black/5">
            <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-xs ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
              <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark' : 'fa-circle-check'}`}></i>
            </div>
            <p className="font-black text-[10px] uppercase tracking-wider">{t.message}</p>
          </div>
        ))}
      </div>

      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-14 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-[15px] flex items-center justify-center text-white text-xl font-black shadow-xl group-hover:rotate-6 transition-transform">B</div>
          <h1 className="text-xl lg:text-2xl font-black text-red-600 tracking-tighter">BFC</h1>
        </div>
        <div className="hidden lg:flex items-center gap-8">
          <button onClick={() => setLanguage(language === 'EN' ? 'BN' : 'EN')} className="text-[10px] font-black uppercase tracking-[3px] bg-gray-100 px-4 py-2 rounded-xl hover:bg-red-50 hover:text-red-600 transition-all">{language}</button>
          <div className="flex items-center gap-10 text-[11px] font-black uppercase tracking-[3px] text-gray-400">
            <button onClick={()=>setView('HOME')} className={view === 'HOME' ? 'text-red-600' : 'hover:text-red-600'}>Home</button>
            <button onClick={()=>setView('MENU')} className={view === 'MENU' ? 'text-red-600' : 'hover:text-red-600'}>Menu</button>
            {isPrivileged && <button onClick={()=>setView('ADMIN')} className="text-gray-900 bg-gray-50 px-5 py-2 rounded-full border border-gray-100 font-black tracking-widest text-[9px] uppercase">Admin Hub</button>}
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 bg-gray-50 rounded-2xl flex items-center justify-center">
            <i className="fas fa-shopping-basket text-gray-600"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[9px] w-5 h-5 rounded-full flex items-center justify-center ring-2 ring-white font-black">{cart.reduce((a,b)=>a+b.qty, 0)}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 rounded-2xl bg-red-600 text-white font-black flex items-center justify-center">
               {currentUser.name.charAt(0)}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl" onClick={() => setView('LOGIN')}>Secure Login</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-12 min-h-[80vh]">
        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto relative mt-12 lg:mt-24">
            <div className="absolute -top-20 -left-20 w-64 h-64 bg-red-600/5 rounded-full blur-[100px] animate-pulse"></div>
            <div className="relative z-10 bg-white/70 backdrop-blur-3xl p-10 lg:p-14 rounded-[50px] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.1)] border border-white animate-slide-up overflow-hidden">
               {/* Security Scanning Beam */}
               {isAuthenticating && <div className="absolute top-0 left-0 w-full h-1 bg-red-600 shadow-[0_0_20px_rgba(220,38,38,1)] animate-scan z-50"></div>}

               <div className="text-center mb-10">
                  <div className={`w-20 h-20 mx-auto mb-6 flex items-center justify-center text-white text-3xl shadow-2xl relative overflow-hidden group transition-all duration-700 ${isAuthenticating ? 'bg-red-600 scale-110 rounded-full rotate-[360deg]' : 'bg-gray-950 rounded-[28px]'}`}>
                     {isAuthenticating ? (
                       <i className="fas fa-circle-notch fa-spin"></i>
                     ) : (
                       <i className="fas fa-fingerprint group-hover:scale-110 transition-transform"></i>
                     )}
                  </div>
                  <h2 className="text-3xl font-black text-gray-900 tracking-tight uppercase">BFC Auth Node</h2>
                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-[4px] mt-2">End-to-End Encrypted Terminal</p>
               </div>

               <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 tracking-[5px] block ml-6">Access Registry ID</label>
                    <div className="relative group">
                      <i className="fas fa-user-shield absolute left-6 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-red-600 transition-colors"></i>
                      <input 
                        type="email" 
                        value={formEmail} 
                        onChange={(e)=>setFormEmail(e.target.value)}
                        placeholder="admin@bfc.com"
                        className="w-full bg-gray-50/50 border-2 border-transparent focus:border-red-600/10 focus:bg-white rounded-3xl px-14 py-5 font-bold outline-none transition-all"
                        disabled={isAuthenticating || !!(lockoutUntil && Date.now() < lockoutUntil)}
                      />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 tracking-[5px] block ml-6">Secret Handshake Key</label>
                    <div className="relative group">
                      <i className="fas fa-key absolute left-6 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-red-600 transition-colors"></i>
                      <input 
                        type={showPass ? 'text' : 'password'} 
                        value={formPass} 
                        onChange={(e)=>setFormPass(e.target.value)}
                        placeholder="••••••••"
                        className="w-full bg-gray-50/50 border-2 border-transparent focus:border-red-600/10 focus:bg-white rounded-3xl px-14 py-5 font-bold outline-none transition-all"
                        disabled={isAuthenticating || !!(lockoutUntil && Date.now() < lockoutUntil)}
                      />
                      <button onClick={()=>setShowPass(!showPass)} className="absolute right-6 top-1/2 -translate-y-1/2 text-gray-300 hover:text-gray-600 transition-colors">
                        <i className={`fas ${showPass ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                      </button>
                    </div>
                  </div>

                  <Button 
                    fullWidth 
                    size="lg" 
                    className={`rounded-[25px] py-6 shadow-xl mt-4 transition-all ${lockoutUntil && Date.now() < lockoutUntil ? 'bg-gray-200' : ''}`} 
                    onClick={handleAuth}
                    disabled={isAuthenticating || !!(lockoutUntil && Date.now() < lockoutUntil)}
                  >
                    {isAuthenticating ? (
                      <span className="flex items-center gap-3">
                        <i className="fas fa-shield-halved animate-pulse"></i>
                        Verifying Node...
                      </span>
                    ) : lockoutUntil && Date.now() < lockoutUntil ? (
                       'System Locked'
                    ) : 'Initiate Secure Login'}
                  </Button>

                  <div className="pt-4 flex items-center justify-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${isOnline ? 'bg-emerald-500 animate-pulse' : 'bg-red-500'}`}></div>
                    <p className="text-[8px] font-black text-gray-400 uppercase tracking-[2px]">
                      {isOnline ? 'Encrypted Connection Stable' : 'Offline Mode Restricted'}
                    </p>
                  </div>
               </div>
            </div>
          </div>
        )}

        {view === 'HOME' && (
          <div className="animate-slide-up space-y-20">
            <header className="relative h-[400px] lg:h-[600px] rounded-[50px] overflow-hidden shadow-3xl group">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover transition-transform duration-[10s] group-hover:scale-110" />
               <div className="absolute inset-0 bg-gradient-to-r from-black/80 to-transparent flex flex-col justify-center px-12 lg:px-24">
                  <h2 className="text-4xl lg:text-8xl font-black text-white leading-[0.95] mb-8 tracking-tighter">
                    {language === 'BN' ? 'আসল স্বাদের' : 'The Real'}<br/>
