  const [adminToast, setAdminToast] = useState<{msg: string, type: string} | null>(null);
  const showToast = useCallback((msg: string, type: string) => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 3000);
  }, []);

  // Strict JWT Security Check
  const verifyAccess = useCallback(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (!savedUser) return false;
    try {
      const user = JSON.parse(savedUser) as User;
      if (!user.sessionToken) return false;

      // Deep verify the simulated JWT
      const parts = user.sessionToken.split('.');
      if (parts.length !== 3) return false;

      const payload = JSON.parse(atob(parts[1]));

      // Expired?
      if (payload.exp < Date.now()) return false;

      // Role Mismatch?
      if (payload.role !== userRole) return false;

      return true;
    } catch { return false; }
  }, [userRole]);

  useEffect(() => {
    if (verifyAccess()) {
      setIsAuthorized(true);
    } else {
      onLogout();
    }
  }, [verifyAccess, onLogout]);

  // Periodic Session Re-validation (every 30s)
  useEffect(() => {
    const interval = setInterval(() => {
      if (!verifyAccess()) {
        showToast('Session Invalid or Expired. Logging out...', 'error');
        setTimeout(onLogout, 2000);
      }
    }, 30000);
    return () => clearInterval(interval);
  }, [verifyAccess, onLogout, showToast]);

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length
    };
  }, [orders, menuItems]);

  const handleExportCSV = () => {
    setExporting('SALES-CSV');
    const headers = ['Day', 'Sales (BDT)', 'Orders Count'];
    const rows = ANALYTICS_DATA.map(item => [item.name, item.sales, item.orders].join(','));
    const csvContent = [headers.join(','), ...rows].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `BFC_Sales_Velocity_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    setTimeout(() => {
      setExporting(null);
      showToast('Sales Data CSV Generated', 'success');
    }, 1000);
  };

  const handleExport = async (format: 'PDF' | 'EXCEL', report: string) => {
    setExporting(`${report}-${format}`);
    await new Promise(r => setTimeout(r, 2000));
    setExporting(null);
    showToast(`${report} exported successfully in ${format} format.`, 'success');
  };

  const handleExportAll = async (format: 'PDF' | 'EXCEL') => {
    setExporting(`ALL-${format}`);
    await new Promise(r => setTimeout(r, 4000));
    setExporting(null);
    showToast(`Consolidated ${format} report bundle generated.`, 'success');
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white p-10">
      <div className="relative w-24 h-24 mb-10">
        <div className="absolute inset-0 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center">
           <i className="fas fa-lock text-red-600 animate-pulse text-2xl"></i>
        </div>
      </div>
      <p className="text-[10px] font-black uppercase tracking-[8px] animate-pulse text-red-500">Security Handshake Protocol Active...</p>
      <p className="text-[8px] font-bold text-gray-500 uppercase tracking-[4px] mt-4">Verifying Node Credentials & Role Auth</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F1F3F6] overflow-hidden font-sans relative">
      {adminToast && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[1000] bg-gray-900 text-white px-8 py-4 rounded-2xl shadow-2xl border border-white/10 animate-slide-up flex items-center gap-3">
          <i className={`fas ${adminToast.type === 'success' ? 'fa-check-circle text-emerald-500' : 'fa-info-circle'}`}></i>
          <span className="text-[10px] font-black uppercase tracking-widest">{adminToast.msg}</span>
        </div>
      )}

      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 lg:w-80 bg-white shadow-2xl transition-transform duration-500 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-10 border-b flex items-center gap-4">
          <div className="w-10 h-10 bg-red-600 rounded-2xl flex items-center justify-center text-white shadow-xl rotate-3">
            <i className="fas fa-shield-halved"></i>
          </div>
          <h1 className="text-xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
        </div>

        <nav className="p-8 space-y-4">
          <SidebarBtn active={activeTab === 'dashboard'} onClick={()=>setActiveTab('dashboard')} icon="fa-chart-pie" label="Analytics" />
          <SidebarBtn active={activeTab === 'orders'} onClick={()=>setActiveTab('orders')} icon="fa-list-check" label="Orders" />
          <SidebarBtn active={activeTab === 'inventory'} onClick={()=>setActiveTab('inventory')} icon="fa-box-open" label="Inventory" />
          <SidebarBtn active={activeTab === 'reports'} onClick={()=>setActiveTab('reports')} icon="fa-file-invoice-dollar" label="Fiscal Reports" />
        </nav>

        <div className="absolute bottom-0 w-full p-8 border-t">
          <button onClick={onLogout} className="w-full flex items-center justify-center gap-3 py-4 rounded-2xl bg-gray-50 text-gray-400 font-black hover:bg-red-50 hover:text-red-600 transition-all uppercase tracking-[4px] text-[10px]">
            Log out
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col min-w-0">
        <header className="h-24 bg-white/80 backdrop-blur-xl border-b flex items-center justify-between px-12 shrink-0 z-50">
          <div className="flex items-center gap-4 lg:hidden">
            <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="w-10 h-10 bg-gray-100 rounded-xl flex items-center justify-center">
              <i className="fas fa-bars"></i>
            </button>
          </div>
          <h2 className="text-2xl font-black text-gray-800 tracking-tight capitalize">{activeTab} Terminal</h2>
          <div className="flex items-center gap-4 bg-gray-900 px-6 py-2.5 rounded-2xl text-white shadow-xl">
            <i className="fas fa-user-shield text-red-500"></i>
            <span className="text-[10px] font-black uppercase tracking-widest">{userRole}</span>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-12 space-y-12 animate-slide-up">
          {activeTab === 'dashboard' && (
            <div className="space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                <StatCard title="Total Revenue" value={`৳${stats.revenue.toLocaleString()}`} icon="fa-bangladeshi-taka-sign" color="text-green-600" />
                <StatCard title="Orders Volume" value={stats.orderCount} icon="fa-box" color="text-blue-600" />
                <StatCard title="Queue Pending" value={stats.pending} icon="fa-clock" color="text-orange-500" />
                <StatCard title="Stock Risks" value={stats.lowStock} icon="fa-triangle-exclamation" color="text-red-500" />
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-white p-10 rounded-[50px] shadow-sm border border-gray-100 flex flex-col h-[450px]">
                  <div className="flex justify-between items-center mb-8">
                    <h3 className="text-xl font-black">Sales Velocity</h3>
                    <button 
                      onClick={handleExportCSV} 
                      disabled={exporting === 'SALES-CSV'}
                      className="flex items-center gap-2 text-[9px] font-black uppercase tracking-widest bg-gray-50 hover:bg-red-50 hover:text-red-600 px-4 py-2 rounded-xl transition-all"
                    >
                      {exporting === 'SALES-CSV' ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-download"></i>}
                      Export CSV
                    </button>
                  </div>
                  <div className="flex-1">
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={ANALYTICS_DATA}>
                        <defs>
                          <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor="#dc2626" stopOpacity={0.1}/>
                            <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                          </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                        <Tooltip />
                        <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={5} fill="url(#colorSales)" />
                      </AreaChart>
                    </ResponsiveContainer>
                  </div>
                </div>

                <div className="bg-white p-10 rounded-[50px] shadow-sm border border-gray-100 flex flex-col h-[450px]">
                  <h3 className="text-xl font-black mb-8">Customer Node Retention</h3>
                  <div className="flex-1 flex items-center justify-center gap-10">
                    <div className="w-48 h-48">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={CUSTOMER_RETENTION} innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                            {CUSTOMER_RETENTION.map((entry, idx) => <Cell key={idx} fill={entry.color} />)}
                          </Pie>
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                    </div>
                    <div className="space-y-4">
                       {CUSTOMER_RETENTION.map((entry, idx) => (
                         <div key={idx} className="flex justify-between items-center gap-8 p-4 bg-gray-50 rounded-2xl">
                           <span className="text-[10px] font-black uppercase text-gray-400">{entry.name}</span>
                           <span className="font-black text-gray-800">{entry.value}%</span>
                         </div>
                       ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'reports' && (
            <div className="space-y-12">
               <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
                  <div>
                    <h2 className="text-5xl font-black text-gray-800 tracking-tighter uppercase leading-none mb-4">Fiscal Hub</h2>
                    <p className="text-gray-400 font-bold max-w-md">Generate detailed business intelligence reports for audit, logistics, and customer lifetime value analysis.</p>
                  </div>
                  <div className="flex gap-4">
                    <Button 
                      variant="outline" 
                      className="rounded-2xl border-gray-900 text-gray-900 hover:bg-gray-900 hover:text-white"
                      onClick={() => handleExportAll('PDF')}
                      disabled={!!exporting}
                    >
                      {exporting === 'ALL-PDF' ? <i className="fas fa-circle-notch fa-spin mr-2"></i> : <i className="fas fa-file-pdf mr-2"></i>}
                      Export All PDF
                    </Button>
                    <Button 
                      variant="primary" 
                      className="rounded-2xl bg-emerald-600 hover:bg-emerald-700"
                      onClick={() => handleExportAll('EXCEL')}
                      disabled={!!exporting}
                    >
                      {exporting === 'ALL-EXCEL' ? <i className="fas fa-circle-notch fa-spin mr-2"></i> : <i className="fas fa-file-excel mr-2"></i>}
                      Export All Excel
                    </Button>
                  </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                  <ReportModule 
                    title="Customer Behavior" 
                    icon="fa-fingerprint" 
                    desc="Analyze order frequency, churn rates, and high-value customer clusters."
                    onPdf={() => handleExport('PDF', 'Customer Behavior')}
                    onExcel={() => handleExport('EXCEL', 'Customer Behavior')}
                    loading={exporting}
                  />
                  <ReportModule 
                    title="Inventory Velocity" 
                    icon="fa-boxes-stacked" 
                    desc="Stock depletion trends, replenishment alerts, and wastage auditing."
                    onPdf={() => handleExport('PDF', 'Inventory Velocity')}
                    onExcel={() => handleExport('EXCEL', 'Inventory Velocity')}
                    loading={exporting}
                  />
                  <ReportModule 
                    title="Regional Density" 
                    icon="fa-map-location-dot" 
                    desc="Logistics performance across Dhaka delivery nodes and heatmaps."
                    onPdf={() => handleExport('PDF', 'Regional Density')}
                    onExcel={() => handleExport('EXCEL', 'Regional Density')}
                    loading={exporting}
                  />
                  <ReportModule 
                    title="Financial Forensics" 
                    icon="fa-vault" 
                    desc="Gross inflows, platform fees, and tax liability calculations."
                    onPdf={() => handleExport('PDF', 'Fiscal Audit')}
                    onExcel={() => handleExport('EXCEL', 'Fiscal Audit')}
                    loading={exporting}
                  />
                  <ReportModule 
                    title="MenuItem Performance" 
                    icon="fa-utensils" 
                    desc="Profit margin analysis per item and popularity forecasting."
                    onPdf={() => handleExport('PDF', 'MenuItem Performance')}
                    onExcel={() => handleExport('EXCEL', 'MenuItem Performance')}
                    loading={exporting}
                  />
                  <ReportModule 
                    title="System Operations" 
                    icon="fa-server" 
                    desc="Platform uptime, API latency, and security logs for the node."
                    onPdf={() => handleExport('PDF', 'System Ops')}
                    onExcel={() => handleExport('EXCEL', 'System Ops')}
                    loading={exporting}
                  />
               </div>
            </div>
          )}

          {activeTab === 'inventory' && (
             <div className="space-y-12">
                <div className="flex justify-between items-end">
                   <h2 className="text-5xl font-black text-gray-800 tracking-tighter uppercase leading-none">Stock Registry</h2>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                   {menuItems.map(item => (
                     <div key={item.id} className="bg-white p-10 rounded-[45px] border border-gray-100 flex flex-col items-center text-center shadow-sm hover:shadow-2xl transition-all relative overflow-hidden group">
                        <div className="absolute top-0 right-0 w-24 h-24 bg-red-600/5 rounded-full -mr-12 -mt-12 group-hover:scale-150 transition-transform"></div>
                        <img src={item.image} className="w-24 h-24 rounded-3xl object-cover mb-6 shadow-xl relative z-10" />
                        <h4 className="font-black text-gray-800 text-lg mb-2 truncate w-full">{item.name}</h4>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">{item.category}</p>
                        <p className={`text-5xl font-black ${item.stock < 10 ? 'text-red-600 animate-pulse' : 'text-gray-900'}`}>{item.stock}</p>
                        <div className="flex gap-4 mt-8 w-full">
                           <button onClick={()=>setMenuItems(prev=>prev.map(i=>i.id===item.id ? {...i, stock: Math.max(0, i.stock-1)} : i))} className="flex-1 bg-gray-100 p-4 rounded-2xl hover:bg-red-50 hover:text-red-600 transition-colors font-black">-</button>
                           <button onClick={()=>setMenuItems(prev=>prev.map(i=>i.id===item.id ? {...i, stock: i.stock+1} : i))} className="flex-1 bg-gray-950 text-white p-4 rounded-2xl hover:bg-red-600 transition-colors font-black">+</button>
                        </div>
                     </div>
                   ))}
                </div>
             </div>
          )}

          {activeTab === 'orders' && (
             <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
               {orders.map(o => (
                  <div key={o.id} className="bg-white p-8 rounded-[40px] border border-gray-50 flex flex-col gap-6 shadow-sm animate-slide-up hover:shadow-xl transition-shadow">
                    <div className="flex justify-between items-start">
                       <div className="flex items-center gap-4">
                          <div className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center font-black shadow-lg">#{o.id.slice(-4)}</div>
                          <div>
                            <p className="font-black text-gray-800 text-lg leading-none mb-1">{o.customerName}</p>
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{o.paymentMethod} • {new Date(o.createdAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                          </div>
                       </div>
                       <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-100 text-emerald-700' : 'bg-red-50 text-red-600'}`}>{o.status}</span>
                    </div>
                    <div className="bg-gray-50 p-6 rounded-3xl space-y-2 flex-1">
                       {o.items.map((i, idx) => (
                         <div key={idx} className="flex justify-between text-[11px] font-bold text-gray-600">
                           <span>{i.name} <span className="text-gray-400">x{i.quantity}</span></span>
                           <span>৳{(i.price * i.quantity).toLocaleString()}</span>
                         </div>
                       ))}
                       <div className="pt-4 mt-4 border-t border-gray-200 flex justify-between font-black text-gray-900">
                          <span>TOTAL</span>
                          <span>৳{o.total.toLocaleString()}</span>
                       </div>
                    </div>
                    <select className="w-full bg-gray-950 text-white rounded-[22px] p-5 text-[10px] font-black uppercase tracking-widest outline-none border-none shadow-xl cursor-pointer hover:bg-red-600 transition-colors" value={o.status} onChange={(e)=>setOrders(prev=>prev.map(ord=>ord.id===o.id ? {...ord, status: e.target.value as OrderStatus}:ord))}>
                      {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
               ))}
             </div>
          )}
        </main>
      </div>
    </div>
  );
};

const SidebarBtn = ({ active, onClick, icon, label }: any) => (
