        </button>
        <button onClick={onExcel} disabled={!!loading} className="flex-1 bg-gray-50 p-4 rounded-2xl flex items-center justify-center gap-3 text-[10px] font-black uppercase tracking-widest text-gray-500 hover:bg-emerald-50 hover:text-emerald-600 transition-all">
           {loading === `${title}-EXCEL` ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-file-excel"></i>} EXCEL
        </button>
     </div>
  </div>
);

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { Button } from './Button';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, orders: 240 },
  { name: 'Sun', sales: 3800, orders: 198 },
  { name: 'Mon', sales: 5200, orders: 310 },
  { name: 'Tue', sales: 4800, orders: 280 },
  { name: 'Wed', sales: 6200, orders: 390 },
  { name: 'Thu', sales: 5800, orders: 340 },
  { name: 'Fri', sales: 8500, orders: 480 },
];

const CUSTOMER_RETENTION = [
  { name: 'Active', value: 72, color: '#dc2626' },
  { name: 'New Nodes', value: 28, color: '#10b981' },
];

// Define accessible tabs per role
const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  [UserRole.ADMIN]: ['dashboard', 'orders', 'inventory', 'reports'],
  [UserRole.MANAGER]: ['dashboard', 'orders', 'inventory', 'reports'],
  [UserRole.STAFF]: ['orders', 'inventory'],
  [UserRole.CUSTOMER]: []
};

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const allowedTabs = ROLE_PERMISSIONS[userRole] || [];
  const [activeTab, setActiveTab] = useState(allowedTabs[0] || 'orders');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [exporting, setExporting] = useState<string | null>(null);
  const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(3600); // 1 hour in seconds

  const [adminToast, setAdminToast] = useState<{msg: string, type: string} | null>(null);
  const showToast = useCallback((msg: string, type: string) => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 3000);
  }, []);

  // Strict Token & Session Verification
  const verifyAccess = useCallback(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (!savedUser) return false;
    try {
      const user = JSON.parse(savedUser) as User;
      if (!user.sessionToken) return false;

      const parts = user.sessionToken.split('.');
      if (parts.length !== 3) return false;

      const payload = JSON.parse(atob(parts[1]));

      if (payload.exp < Date.now()) return false;
      if (payload.role !== userRole) return false;

      const timeLeft = Math.round((payload.exp - Date.now()) / 1000);
      setSessionTimeLeft(timeLeft);

      return true;
    } catch { return false; }
  }, [userRole]);

  useEffect(() => {
    if (verifyAccess()) {
      setIsAuthorized(true);
    } else {
      onLogout();
    }
  }, [verifyAccess, onLogout]);

  // Session Heartbeat & Countdown
  useEffect(() => {
    const timer = setInterval(() => {
      if (!verifyAccess()) {
        showToast('Session Expired. Secure logout initiated.', 'error');
        setTimeout(onLogout, 1500);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [verifyAccess, onLogout, showToast]);

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length
    };
  }, [orders, menuItems]);

  const handleExportCSV = () => {
    setExporting('SALES-CSV');
    const headers = ['Day', 'Sales (BDT)', 'Orders Count'];
    const rows = ANALYTICS_DATA.map(item => [item.name, item.sales, item.orders].join(','));
    const csvContent = [headers.join(','), ...rows].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `BFC_Analytics_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    setTimeout(() => {
      setExporting(null);
      showToast('Analytics Exported to CSV', 'success');
    }, 1000);
  };

  const handleExport = async (format: 'PDF' | 'EXCEL', report: string) => {
    setExporting(`${report}-${format}`);
    await new Promise(r => setTimeout(r, 2000));
    setExporting(null);
    showToast(`${report} exported in ${format} format.`, 'success');
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white p-10">
      <div className="relative w-24 h-24 mb-10">
        <div className="absolute inset-0 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center">
           <i className="fas fa-fingerprint text-red-600 animate-pulse text-2xl"></i>
        </div>
      </div>
      <p className="text-[10px] font-black uppercase tracking-[8px] animate-pulse text-red-500">Node Authentication Protocol...</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F1F3F6] overflow-hidden font-sans relative">
      {adminToast && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[1000] bg-gray-900 text-white px-8 py-4 rounded-2xl shadow-2xl border border-white/10 animate-slide-up flex items-center gap-3">
          <i className={`fas ${adminToast.type === 'success' ? 'fa-check-circle text-emerald-500' : 'fa-info-circle'}`}></i>
          <span className="text-[10px] font-black uppercase tracking-widest">{adminToast.msg}</span>
        </div>
      )}

      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 lg:w-80 bg-white shadow-2xl transition-transform duration-500 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-10 border-b flex items-center gap-4">
          <div className="w-10 h-10 bg-red-600 rounded-2xl flex items-center justify-center text-white shadow-xl rotate-3">
            <i className="fas fa-shield-halved"></i>
          </div>
          <h1 className="text-xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
        </div>

        <nav className="p-8 space-y-4">
          {allowedTabs.includes('dashboard') && <SidebarBtn active={activeTab === 'dashboard'} onClick={()=>setActiveTab('dashboard')} icon="fa-chart-pie" label="Analytics" />}
          {allowedTabs.includes('orders') && <SidebarBtn active={activeTab === 'orders'} onClick={()=>setActiveTab('orders')} icon="fa-list-check" label="Orders" />}
          {allowedTabs.includes('inventory') && <SidebarBtn active={activeTab === 'inventory'} onClick={()=>setActiveTab('inventory')} icon="fa-box-open" label="Inventory" />}
          {allowedTabs.includes('reports') && <SidebarBtn active={activeTab === 'reports'} onClick={()=>setActiveTab('reports')} icon="fa-file-invoice-dollar" label="Fiscal Reports" />}
        </nav>

        <div className="absolute bottom-0 w-full p-8 border-t bg-white">
          <div className="mb-6 p-4 bg-gray-50 rounded-2xl border border-gray-100">
             <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest mb-1">Session Expiry</p>
             <div className="flex items-center justify-between font-black text-gray-800 text-[10px]">
                <span>{Math.floor(sessionTimeLeft / 60)}m {sessionTimeLeft % 60}s</span>
                <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
             </div>
          </div>
          <button onClick={onLogout} className="w-full flex items-center justify-center gap-3 py-4 rounded-2xl bg-gray-50 text-gray-400 font-black hover:bg-red-50 hover:text-red-600 transition-all uppercase tracking-[4px] text-[10px]">
            Terminte Node
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col min-w-0">
        <header className="h-24 bg-white/80 backdrop-blur-xl border-b flex items-center justify-between px-12 shrink-0 z-50">
          <div className="flex items-center gap-4 lg:hidden">
            <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="w-10 h-10 bg-gray-100 rounded-xl flex items-center justify-center">
              <i className="fas fa-bars"></i>
            </button>
          </div>
          <h2 className="text-2xl font-black text-gray-800 tracking-tight capitalize">{activeTab} Terminal</h2>
          <div className="flex items-center gap-4 bg-gray-950 px-6 py-2.5 rounded-2xl text-white shadow-xl">
            <i className="fas fa-user-shield text-red-500"></i>
            <span className="text-[10px] font-black uppercase tracking-widest">{userRole}</span>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-12 space-y-12 animate-slide-up">
          {activeTab === 'dashboard' && allowedTabs.includes('dashboard') && (
            <div className="space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                <StatCard title="Total Revenue" value={`৳${stats.revenue.toLocaleString()}`} icon="fa-bangladeshi-taka-sign" color="text-green-600" />
                <StatCard title="Orders Volume" value={stats.orderCount} icon="fa-box" color="text-blue-600" />
                <StatCard title="Queue Pending" value={stats.pending} icon="fa-clock" color="text-orange-500" />
                <StatCard title="Stock Risks" value={stats.lowStock} icon="fa-triangle-exclamation" color="text-red-500" />
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-white p-10 rounded-[50px] shadow-sm border border-gray-100 flex flex-col h-[450px]">
                  <div className="flex justify-between items-center mb-8">
                    <h3 className="text-xl font-black">Sales Velocity</h3>
                    <button onClick={handleExportCSV} className="text-[9px] font-black uppercase tracking-widest bg-gray-50 hover:bg-red-50 px-4 py-2 rounded-xl transition-all">
                      {exporting === 'SALES-CSV' ? <i className="fas fa-sync fa-spin"></i> : <i className="fas fa-download mr-1"></i>} CSV
                    </button>
                  </div>
                  <div className="flex-1">
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={ANALYTICS_DATA}>
                        <defs>
                          <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor="#dc2626" stopOpacity={0.1}/>
                            <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                          </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                        <Tooltip />
                        <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={5} fill="url(#colorSales)" />
                      </AreaChart>
                    </ResponsiveContainer>
                  </div>
                </div>

                <div className="bg-white p-10 rounded-[50px] shadow-sm border border-gray-100 flex flex-col h-[450px]">
                  <h3 className="text-xl font-black mb-8">Retention Node</h3>
                  <div className="flex-1 flex items-center justify-center gap-10">
                    <div className="w-48 h-48">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={CUSTOMER_RETENTION} innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                            {CUSTOMER_RETENTION.map((entry, idx) => <Cell key={idx} fill={entry.color} />)}
                          </Pie>
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'reports' && allowedTabs.includes('reports') && (
            <div className="space-y-12">
               <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                  <ReportModule 
                    title="Customer Behavior" 
                    icon="fa-fingerprint" 
                    desc="Analyze order frequency and churn rates."
                    onPdf={() => handleExport('PDF', 'Customer Behavior')}
                    onExcel={() => handleExport('EXCEL', 'Customer Behavior')}
                    loading={exporting}
                  />
                  <ReportModule 
                    title="Inventory Velocity" 
                    icon="fa-boxes-stacked" 
                    desc="Audit depletion trends and replenishment."
                    onPdf={() => handleExport('PDF', 'Inventory Velocity')}
                    onExcel={() => handleExport('EXCEL', 'Inventory Velocity')}
                    loading={exporting}
                  />
                  <ReportModule 
                    title="Financial Forensics" 
                    icon="fa-vault" 
                    desc="Gross inflows and platform liability."
                    onPdf={() => handleExport('PDF', 'Fiscal Audit')}
                    onExcel={() => handleExport('EXCEL', 'Fiscal Audit')}
                    loading={exporting}
                  />
               </div>
            </div>
          )}

          {activeTab === 'inventory' && allowedTabs.includes('inventory') && (
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                {menuItems.map(item => (
                  <div key={item.id} className="bg-white p-10 rounded-[45px] border border-gray-100 flex flex-col items-center text-center shadow-sm hover:shadow-2xl transition-all">
                     <img src={item.image} className="w-20 h-20 rounded-2xl object-cover mb-4 shadow-lg" />
                     <h4 className="font-black text-gray-800 text-sm mb-1">{item.name}</h4>
                     <p className={`text-4xl font-black ${item.stock < 10 ? 'text-red-600' : 'text-gray-950'}`}>{item.stock}</p>
                     <div className="flex gap-2 mt-6 w-full">
                        <button onClick={()=>setMenuItems(prev=>prev.map(i=>i.id===item.id ? {...i, stock: Math.max(0, i.stock-1)} : i))} className="flex-1 bg-gray-100 p-3 rounded-xl hover:bg-red-50 hover:text-red-600 transition-colors font-black text-xs">-</button>
                        <button onClick={()=>setMenuItems(prev=>prev.map(i=>i.id===item.id ? {...i, stock: i.stock+1} : i))} className="flex-1 bg-gray-950 text-white p-3 rounded-xl hover:bg-red-600 transition-colors font-black text-xs">+</button>
                     </div>
                  </div>
                ))}
             </div>
          )}

          {activeTab === 'orders' && allowedTabs.includes('orders') && (
             <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
               {orders.map(o => (
                  <div key={o.id} className="bg-white p-8 rounded-[40px] border border-gray-50 flex flex-col gap-6 shadow-sm">
                    <div className="flex justify-between items-start">
                       <div className="flex items-center gap-4">
                          <div className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center font-black shadow-lg">#{o.id.slice(-4)}</div>
                          <div>
                            <p className="font-black text-gray-800 text-lg leading-none mb-1">{o.customerName}</p>
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{o.paymentMethod}</p>
                          </div>
                       </div>
                       <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-100 text-emerald-700' : 'bg-red-50 text-red-600'}`}>{o.status}</span>
                    </div>
                    <select className="w-full bg-gray-950 text-white rounded-[22px] p-5 text-[10px] font-black uppercase tracking-widest outline-none shadow-xl cursor-pointer hover:bg-red-600 transition-all" value={o.status} onChange={(e)=>setOrders(prev=>prev.map(ord=>ord.id===o.id ? {...ord, status: e.target.value as OrderStatus}:ord))}>
                      {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
               ))}
             </div>
          )}
        </main>
      </div>
    </div>
  );
};

