const StatCard = ({ title, value, icon, color }: any) => (
  <div className="bg-white p-8 rounded-[40px] border border-gray-100 flex items-center gap-6 group hover:shadow-2xl transition-all h-full">
    <div className={`w-14 h-14 bg-gray-50 rounded-[20px] flex items-center justify-center text-xl ${color} shadow-inner shrink-0 group-hover:scale-110 transition-transform`}><i className={`fas ${icon}`}></i></div>
    <div className="min-w-0">
      <p className="text-[10px] font-black text-gray-300 uppercase tracking-[4px] mb-1 truncate">{title}</p>
