     <div className="w-16 h-16 bg-red-50 rounded-3xl flex items-center justify-center text-red-600 mb-8 shadow-inner group-hover:bg-red-600 group-hover:text-white transition-all">
        <i className={`fas ${icon} text-2xl`}></i>
     </div>
     <h4 className="text-2xl font-black text-gray-800 tracking-tighter mb-2">{title}</h4>
     <p className="text-sm font-bold text-gray-400 mb-10 leading-relaxed">{desc}</p>
     <div className="mt-auto flex gap-4">
        <button onClick={onPdf} disabled={!!loading} className="flex-1 bg-gray-50 p-4 rounded-2xl flex items-center justify-center gap-3 text-[10px] font-black uppercase tracking-widest text-gray-500 hover:bg-red-50 hover:text-red-600 transition-all">
           {loading === `${title}-PDF` ? <i className="fas fa-sync fa-spin"></i> : <i className="fas fa-file-pdf"></i>} PDF
        </button>
        <button onClick={onExcel} disabled={!!loading} className="flex-1 bg-gray-50 p-4 rounded-2xl flex items-center justify-center gap-3 text-[10px] font-black uppercase tracking-widest text-gray-500 hover:bg-emerald-50 hover:text-emerald-600 transition-all">
           {loading === `${title}-EXCEL` ? <i className="fas fa-sync fa-spin"></i> : <i className="fas fa-file-excel"></i>} EXCEL
        </button>
     </div>
  </div>
);

import React, { useState, useEffect, useCallback } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
  persistent?: boolean;
}

const MOCK_AUTH_DB = {
  'admin@bfc.com': { pass: 'admin123', role: UserRole.ADMIN, name: 'Root Admin' },
  'manager@bfc.com': { pass: 'manager456', role: UserRole.MANAGER, name: 'Node Manager' },
  'staff@bfc.com': { pass: 'staff789', role: UserRole.STAFF, name: 'Logistics Staff' }
};

const MAX_ATTEMPTS = 3;
const LOCKOUT_TIME = 60000;

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE'>('HOME');
  const [language, setLanguage] = useState<'EN' | 'BN'>('BN');
  const [selectedProduct, setSelectedProduct] = useState<MenuItem | null>(null);
  const [activeCategory, setActiveCategory] = useState('All');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Security & Form States
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [emailError, setEmailError] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [failedAttempts, setFailedAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);

  // Checkout Simulation States
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [checkoutStep, setCheckoutStep] = useState<'IDLE' | 'PROCESSING' | 'ERROR' | 'SUCCESS'>('IDLE');

  const showToast = useCallback((message: string, type: Toast['type'] = 'info', persistent: boolean = false) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, persistent }]);
    if (!persistent) {
      setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
    }
  }, []);

  const dismissToast = (id: number) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  useEffect(() => {
    const handleOnline = () => { setIsOnline(true); showToast('System Online: Connection Restored', 'success'); };
    const handleOffline = () => { setIsOnline(false); showToast('Network Link Severed: Operating in Offline Mode', 'error', true); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  const validateEmail = (email: string) => {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email) return "ID is required for node access.";
    if (!re.test(email)) return "Invalid ID format. Please use a valid email.";
    return "";
  };

  const handleAuth = async () => {
    const error = validateEmail(formEmail);
    if (error) {
      setEmailError(error);
      showToast(error, 'warning');
      return;
    }
    setEmailError("");

    if (lockoutUntil && Date.now() < lockoutUntil) {
      const remaining = Math.ceil((lockoutUntil - Date.now()) / 1000);
      return showToast(`Security Lockout: Try again in ${remaining}s. Your account is temporarily frozen for safety.`, 'error');
    }

    if (!formPass) return showToast('Secret Key required. Please input your handshake passphrase.', 'warning');

    setIsAuthenticating(true);
    await new Promise(r => setTimeout(r, 1800));

    const emailKey = formEmail.toLowerCase().trim();
    const privileged = MOCK_AUTH_DB[emailKey as keyof typeof MOCK_AUTH_DB];

    if (privileged && privileged.pass === formPass) {
      setFailedAttempts(0);
      const user: User = {
        id: 'SEC-' + Math.random().toString(36).slice(7).toUpperCase(),
        name: privileged.name, email: emailKey, phone: '01700-000000',
        role: privileged.role, loyaltyPoints: 1000, tier: 'PLATINUM',
        wishlist: [], referralCode: 'BFC-MASTER',
        sessionToken: `header.${btoa(JSON.stringify({role: privileged.role, exp: Date.now() + 3600000}))}.sig`
      };
      localStorage.setItem('bfc_user_profile', JSON.stringify(user));
      setCurrentUser(user);
      showToast(`Authentication Successful: Welcome back, ${user.name}.`, 'success');
      setView(privileged.role === UserRole.CUSTOMER ? 'HOME' : 'ADMIN');
    } else {
      const newAttempts = failedAttempts + 1;
      setFailedAttempts(newAttempts);

      if (newAttempts >= MAX_ATTEMPTS) {
        setLockoutUntil(Date.now() + LOCKOUT_TIME);
        showToast('Maximum attempts exceeded. Node security triggered a temporary lockout. Please wait 60 seconds.', 'error', true);
      } else {
        showToast(`Access Denied: The secret key provided is incorrect. You have ${MAX_ATTEMPTS - newAttempts} attempts left before lockout.`, 'error');
      }
    }
    setIsAuthenticating(false);
  };

  const handleCheckout = async () => {
    if (!isOnline) {
      showToast("Connection Error: You must be online to process payments. Please check your WiFi or Data.", "error");
      return;
    }

    setIsCheckingOut(true);
    setCheckoutStep('PROCESSING');

    // Simulating gateway processing
    await new Promise(r => setTimeout(r, 2500));

    // 40% chance of a simulated "Payment Failure" to demonstrate error handling
    if (Math.random() < 0.4) {
      setCheckoutStep('ERROR');
      showToast("Payment Failed: We couldn't authorize the transaction with your provider. Ensure you have sufficient balance in bKash/Nagad.", "error", true);
    } else {
      setCheckoutStep('SUCCESS');
      setCart([]);
      showToast("Order Confirmed! Your feast is being prepared. Check the Tracking tab for updates.", "success");
      setTimeout(() => setView('HOME'), 2000);
    }
    setIsCheckingOut(false);
  };

  const isPrivileged = currentUser && currentUser.role !== UserRole.CUSTOMER;

  if (view === 'ADMIN' && isPrivileged) {
    return (
      <AdminPanel 
        userRole={currentUser.role} 
        onLogout={() => { 
          localStorage.removeItem('bfc_user_profile');
          setCurrentUser(null); 
          setView('HOME'); 
          showToast('Session terminated safely.', 'info');
        }}
        menuItems={menuItems}
        setMenuItems={setMenuItems}
        orders={allOrders}
        setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans selection:bg-red-100 overflow-x-hidden">
      {/* Toast Notification Container */}
      <div className="fixed top-12 right-8 z-[1000] space-y-4 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-start gap-4 px-6 py-5 rounded-3xl shadow-[0_20px_50px_rgba(0,0,0,0.1)] border bg-white animate-slide-up border-gray-100 text-gray-800 ring-1 ring-black/5">
            <div className={`w-8 h-8 rounded-xl shrink-0 flex items-center justify-center text-xs ${
              t.type === 'error' ? 'bg-red-50 text-red-600' : 
              t.type === 'warning' ? 'bg-amber-50 text-amber-600' : 
              t.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'
            }`}>
              <i className={`fas ${
                t.type === 'error' ? 'fa-circle-xmark' : 
                t.type === 'warning' ? 'fa-triangle-exclamation' :
                t.type === 'success' ? 'fa-circle-check' : 'fa-circle-info'
              }`}></i>
            </div>
            <div className="flex-1">
              <p className="font-bold text-[11px] leading-relaxed">{t.message}</p>
              {t.persistent && (
                <button onClick={() => dismissToast(t.id)} className="mt-3 text-[9px] font-black uppercase tracking-widest text-gray-400 hover:text-gray-950 transition-colors">Dismiss Information</button>
              )}
