import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  if (!navigator.onLine) {
    return "Whoops! Your internet node is offline. I can't reach the BFC kitchen without a connection! 📶";
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist", the ultimate food concierge for BFC (Bangla Food Club).

        Tone: Engaging, casual, energetic, and culturally connected. You are a "foodie friend" (bondhu), not a corporate bot. 

        CORE RULES:
        1. STRICT CONCISENESS: Never exceed 2 short sentences.
        2. NO FORMAL GREETINGS: Avoid "Assalamu Alaikum", "Adab", or formal "Hello". Use casual intros like "Yo!", "Hey!", or "Hi there!".
        3. PRACTICALITY FIRST: Focus on menu favorites (Kacchi, Morog Polao), spice levels, or order status (point them to the Tracking tab).
        4. HYPED VIBE: Use words like "Legendary", "Absolute fire 🔥", "Elite", and "Chef's kiss".
        5. LANGUAGE: Natural Banglish (blend of English and casual Bengali).

        Example: "Yo! That Kacchi is absolute fire today. 🔥 Check the Tracking tab to see when your order hits the node!"`,
        temperature: 0.8,
        topP: 0.9,
      },
    });

    return response.text || "Connection glitch. My brain is a bit fuzzy—say that again? 😅";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    if (error?.message?.includes('403')) {
      return "Access denied! It seems my key doesn't work right now. 🗝️ Contact support!";
    }
    return "The BFC cloud node is acting up. Give it a minute and try again! 🌯";
  }
};

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { Button } from './Button';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, orders: 240 },
  { name: 'Sun', sales: 3800, orders: 198 },
  { name: 'Mon', sales: 5200, orders: 310 },
  { name: 'Tue', sales: 4800, orders: 280 },
  { name: 'Wed', sales: 6200, orders: 390 },
  { name: 'Thu', sales: 5800, orders: 340 },
  { name: 'Fri', sales: 8500, orders: 480 },
];

const CUSTOMER_RETENTION = [
  { name: 'Active', value: 72, color: '#dc2626' },
  { name: 'New Nodes', value: 28, color: '#10b981' },
];

const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  [UserRole.ADMIN]: ['dashboard', 'orders', 'inventory', 'reports'],
  [UserRole.MANAGER]: ['dashboard', 'orders', 'inventory', 'reports'],
  [UserRole.STAFF]: ['orders', 'inventory'],
  [UserRole.CUSTOMER]: []
};

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const allowedTabs = ROLE_PERMISSIONS[userRole] || [];
  const [activeTab, setActiveTab] = useState(allowedTabs[0] || 'orders');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [exporting, setExporting] = useState<string | null>(null);
  const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(3600);

  const [adminToast, setAdminToast] = useState<{msg: string, type: 'success' | 'error' | 'warning'} | null>(null);
  const showToast = useCallback((msg: string, type: 'success' | 'error' | 'warning') => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const verifyAccess = useCallback(() => {
    const savedUser = localStorage.getItem('bfc_user_profile');
    if (!savedUser) return false;
    try {
      const user = JSON.parse(savedUser) as User;
      if (!user.sessionToken) return false;
      const parts = user.sessionToken.split('.');
      if (parts.length !== 3) return false;
      const payload = JSON.parse(atob(parts[1]));
      if (payload.exp < Date.now()) return false;
      if (payload.role !== userRole) return false;
      setSessionTimeLeft(Math.round((payload.exp - Date.now()) / 1000));
      return true;
    } catch { return false; }
  }, [userRole]);

  useEffect(() => {
    if (verifyAccess()) {
      setIsAuthorized(true);
    } else {
      onLogout();
    }
  }, [verifyAccess, onLogout]);

  useEffect(() => {
    const timer = setInterval(() => {
      if (!verifyAccess()) {
        showToast('Your session has expired for security reasons. Please login again.', 'error');
        setTimeout(onLogout, 2000);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [verifyAccess, onLogout, showToast]);

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length
    };
  }, [orders, menuItems]);

  const handleStockUpdate = (itemId: string, delta: number) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = item.stock + delta;
        if (newStock < 0) {
          showToast(`Invalid Update: Stock for ${item.name} cannot be less than zero.`, 'warning');
          return item;
        }
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  const handleExportCSV = () => {
    if (!navigator.onLine) {
      showToast('Export Failed: An internet connection is required to sync and generate analytics.', 'error');
      return;
    }
    setExporting('SALES-CSV');
    const headers = ['Day', 'Sales (BDT)', 'Orders Count'];
    const rows = ANALYTICS_DATA.map(item => [item.name, item.sales, item.orders].join(','));
    const csvContent = [headers.join(','), ...rows].join('\n');

    try {
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.setAttribute('href', url);
      link.setAttribute('download', `BFC_Analytics_${new Date().toISOString().split('T')[0]}.csv`);
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      setTimeout(() => {
        setExporting(null);
        showToast('Analytics CSV downloaded successfully.', 'success');
      }, 1000);
    } catch (e) {
      setExporting(null);
      showToast('System Error: Could not generate CSV file. Local storage might be full.', 'error');
    }
  };

  const handleExport = async (format: 'PDF' | 'EXCEL', report: string) => {
    setExporting(`${report}-${format}`);
    // Simulating potential server failure
    await new Promise(r => setTimeout(r, 2000));

    if (Math.random() < 0.15) {
      setExporting(null);
