         <button onClick={()=>setView('HOME')} className={`text-2xl ${view === 'HOME' ? 'text-red-600' : 'text-gray-300'}`}><i className="fas fa-home"></i></button>
         <button onClick={()=>setView('MENU')} className={`text-2xl ${view === 'MENU' ? 'text-red-600' : 'text-gray-300'}`}><i className="fas fa-utensils"></i></button>
         <button onClick={()=>setView('CART')} className={`text-2xl relative ${view === 'CART' ? 'text-red-600' : 'text-gray-300'}`}>
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[8px] w-5 h-5 rounded-full flex items-center justify-center ring-2 ring-white font-black">{cart.length}</span>}
         </button>
         <button onClick={()=>currentUser ? setView('PROFILE') : setView('LOGIN')} className={`text-2xl ${['PROFILE', 'LOGIN'].includes(view) ? 'text-red-600' : 'text-gray-300'}`}><i className="fas fa-user-circle"></i></button>
      </div>
    </div>
  );
};

