            <span className="text-[10px] font-black uppercase tracking-widest">{userRole}</span>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-12 space-y-12 animate-slide-up">
          {activeTab === 'dashboard' && allowedTabs.includes('dashboard') && (
            <div className="space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                <StatCard title="Total Revenue" value={`৳${stats.revenue.toLocaleString()}`} icon="fa-bangladeshi-taka-sign" color="text-green-600" />
                <StatCard title="Orders Volume" value={stats.orderCount} icon="fa-box" color="text-blue-600" />
                <StatCard title="Queue Pending" value={stats.pending} icon="fa-clock" color="text-orange-500" />
                <StatCard title="Stock Risks" value={stats.lowStock} icon="fa-triangle-exclamation" color="text-red-500" />
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-white p-10 rounded-[50px] shadow-sm border border-gray-100 flex flex-col h-[450px]">
                   <h3 className="text-xl font-black mb-8">Sales Velocity</h3>
                   <div className="flex-1">
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={ANALYTICS_DATA}>
                        <defs>
                          <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor="#dc2626" stopOpacity={0.1}/>
