import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

const QUICK_ACTIONS = [
  "Recommend Kacchi 🍛",
  "Spice Level? 🔥",
  "Track my food 🚚",
  "Secret Deals 🎁"
];

export const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { 
      role: 'model', 
      text: "Yo! BFC Assist here. 👋 Ready to find the most legendary Kacchi in town? I'm your food concierge—just ask!", 
      timestamp: new Date() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isTyping]);

  const toggleVoice = () => {
    if (!('webkitSpeechRecognition' in window)) {
      alert("Voice recognition not supported in this browser.");
      return;
    }

    // @ts-ignore
    const recognition = new window.webkitSpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(transcript);
      handleSend(transcript);
    };
    recognition.start();
  };

  const handleSend = async (text: string = input) => {
    const messageToSend = text.trim();
    if (!messageToSend) return;

    const userMsg: ChatMessage = { role: 'user', text: messageToSend, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));

    try {
      const botResponse = await bfcAssistChat(messageToSend, history);
      setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Node glitch. Try again? 😅", timestamp: new Date() }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-10 lg:right-10 z-[1000] font-sans">
      {isOpen ? (
        <div className="bg-white/90 backdrop-blur-3xl w-[94vw] sm:w-[420px] h-[75vh] sm:h-[620px] rounded-[45px] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.4)] flex flex-col border border-white/60 overflow-hidden animate-slide-up gpu ring-1 ring-black/5">

          {/* Header Section */}
          <div className="bg-gray-950 p-6 lg:p-8 text-white relative overflow-hidden shrink-0">
            <div className="absolute -top-10 -right-10 w-40 h-40 bg-red-600/30 rounded-full blur-[60px]"></div>
            <div className="absolute -bottom-10 -left-10 w-24 h-24 bg-blue-600/10 rounded-full blur-[40px]"></div>

            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-4">
                <div className="relative group">
                  <div className="w-14 h-14 bg-red-600 rounded-[22px] flex items-center justify-center shadow-2xl rotate-2 group-hover:rotate-6 transition-transform">
                    <i className="fas fa-bolt text-xl"></i>
                  </div>
                  <span className="absolute -bottom-1 -right-1 w-4 h-4 bg-emerald-500 border-4 border-gray-950 rounded-full"></span>
                </div>
                <div>
                  <h3 className="font-black text-xl tracking-tighter leading-none uppercase">BFC Assist</h3>
                  <div className="flex items-center gap-1.5 mt-2">
                    <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></span>
                    <p className="text-[9px] font-black uppercase tracking-[3px] opacity-60">System Online</p>
                  </div>
                </div>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={() => setIsOpen(false)} 
                  className="w-10 h-10 bg-white/5 hover:bg-white/10 rounded-2xl flex items-center justify-center transition-all border border-white/10"
                >
                  <i className="fas fa-chevron-down text-sm opacity-60"></i>
                </button>
              </div>
            </div>
          </div>

          {/* Chat Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-6 scrollbar-hide bg-gradient-to-b from-white/50 to-gray-50/50">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                <div className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'} max-w-[85%]`}>
                  <div className={`px-6 py-4 rounded-[28px] text-sm font-bold leading-relaxed shadow-sm transition-all hover:shadow-md ${
                    m.role === 'user' 
                    ? 'bg-gradient-to-br from-gray-800 to-gray-950 text-white rounded-br-none' 
                    : 'bg-white text-gray-800 border border-gray-100 rounded-tl-none'
                  }`}>
                    {m.text}
                  </div>
                  <span className="text-[8px] mt-2 font-black tracking-widest opacity-20 uppercase px-3">
                    {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start animate-slide-up">
                <div className="bg-white/80 backdrop-blur-sm px-6 py-4 rounded-[24px] rounded-tl-none flex gap-1.5 border border-white shadow-sm">
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce"></div>
                </div>
              </div>
            )}
          </div>

          {/* Interactive Footer */}
          <div className="p-8 bg-white/60 backdrop-blur-3xl border-t border-white/60 shrink-0">
            {messages.length < 4 && !isTyping && (
              <div className="flex gap-2 overflow-x-auto pb-6 scrollbar-hide">
                {QUICK_ACTIONS.map(action => (
                  <button 
                    key={action}
                    onClick={() => handleSend(action)}
                    className="whitespace-nowrap px-6 py-3 bg-white hover:bg-red-600 hover:text-white rounded-full text-[10px] font-black uppercase tracking-widest text-gray-900 border border-gray-100 transition-all active:scale-95 shadow-sm hover:shadow-xl hover:-translate-y-0.5"
                  >
                    {action}
                  </button>
                ))}
              </div>
            )}

            <div className="relative flex items-center bg-white rounded-[30px] p-2.5 shadow-xl border border-gray-100 group focus-within:ring-8 ring-red-50/50 transition-all">
              <button 
                onClick={toggleVoice}
                className={`w-14 h-14 rounded-[22px] flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'text-gray-300 hover:text-red-600 hover:bg-red-50'}`}
              >
                <i className={`fas ${isListening ? 'fa-microphone-lines text-xl' : 'fa-microphone text-lg'}`}></i>
              </button>

              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={isListening ? "Listening..." : "Message BFC Assist..."}
                className="flex-1 bg-transparent border-none py-4 px-4 outline-none text-sm font-bold text-gray-800 placeholder:text-gray-300"
              />

              <button 
                onClick={() => handleSend()}
                disabled={!input.trim() || isTyping}
                className="w-14 h-14 bg-gray-950 text-white rounded-[22px] flex items-center justify-center hover:bg-red-600 transition-all disabled:opacity-10 shadow-lg active:scale-90 group-hover:shadow-2xl"
              >
                <i className="fas fa-arrow-up text-lg"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-gray-950 text-white w-20 h-20 lg:w-24 lg:h-24 rounded-[32px] lg:rounded-[38px] shadow-3xl flex items-center justify-center hover:scale-105 active:scale-95 transition-all duration-700 group relative border-8 border-white ring-1 ring-black/5"
        >
          <div className="absolute inset-0 bg-gradient-to-tr from-red-600 to-red-800 opacity-0 group-hover:opacity-100 transition-all duration-700 rounded-[28px] lg:rounded-[34px]"></div>
          <div className="relative z-10 flex flex-col items-center gap-1">
            <i className="fas fa-message text-2xl lg:text-3xl"></i>
            <span className="text-[8px] font-black uppercase tracking-widest hidden lg:block opacity-0 group-hover:opacity-100 translate-y-2 group-hover:translate-y-0 transition-all">Assist</span>
          </div>
          <span className="absolute -top-1 -right-1 w-6 h-6 bg-red-600 border-4 border-white rounded-full z-20 shadow-xl group-hover:animate-bounce flex items-center justify-center">
             <span className="w-1.5 h-1.5 bg-white rounded-full animate-pulse"></span>
          </span>
        </button>
      )}
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  if (!navigator.onLine) {
    return "Network error! Your connection is currently offline. Please reconnect to chat with BFC Assist! 📶";
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist", the ultimate food concierge for BFC (Bangla Food Club).

        Tone: Engaging, high-energy, and culturally connected. You are a "foodie friend" (bondhu).

        CORE RULES:
        1. ULTRA-CONCISE: Never exceed 15-20 words. Max 2 short sentences.
        2. NO FORMALITIES: Skip "Hello", "Assalamu Alaikum", or "How can I help?". Start directly with the vibe.
        3. PRACTICALITY: Only answer about the menu (Kacchi, Roast, Rezala), spice levels, or order status.
        4. HYPED VIBE: Use "Legendary", "Fire 🔥", "Elite", "Chef's kiss", "Pure magic".
        5. LANGUAGE: Natural Banglish (blend of English and casual Bengali).

        Example: "That Kacchi is legendary fire! 🔥 Tracking is live—check your status now."`,
        temperature: 0.85,
        topP: 0.95,
      },
    });

    return response.text || "Snagged! Try that again? 😅";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    if (error?.message?.includes('403')) {
      return "Access denied! My security keys need an update. Contact the BFC hub team! 🗝️";
    }
    if (error?.message?.includes('quota')) {
      return "Whoa! Everyone's hungry. I've hit my limit for a sec—try again in a bit! 🌯";
    }
    return "Node glitch. Give it a refresh and let's try again! 🌯";
  }
};

