    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(transcript);
      handleSend(transcript);
    };
    recognition.start();
  };

  const handleSend = async (text: string = input) => {
    const messageToSend = text.trim();
    if (!messageToSend) return;

    const userMsg: ChatMessage = { role: 'user', text: messageToSend, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));

    try {
      const botResponse = await bfcAssistChat(messageToSend, history);
      setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Node glitch. Try again? 😅", timestamp: new Date() }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-10 lg:right-10 z-[1000] font-sans">
      {isOpen ? (
        <div className="bg-white/95 backdrop-blur-2xl w-[94vw] sm:w-[420px] h-[75vh] sm:h-[640px] rounded-[48px] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.3)] flex flex-col border border-white/60 overflow-hidden animate-slide-up ring-1 ring-black/5">

          {/* Advanced Header */}
          <div className="bg-gray-950 p-7 lg:p-9 text-white relative overflow-hidden shrink-0">
            <div className="absolute -top-12 -right-12 w-48 h-48 bg-red-600/30 rounded-full blur-[60px]"></div>
            <div className="absolute -bottom-12 -left-12 w-32 h-32 bg-blue-600/10 rounded-full blur-[40px]"></div>

            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-5">
                <div className="relative group">
                  <div className="w-16 h-16 bg-red-600 rounded-[24px] flex items-center justify-center shadow-2xl rotate-3 group-hover:rotate-12 transition-all duration-500">
                    <i className="fas fa-bolt-lightning text-2xl"></i>
                  </div>
                  <span className="absolute -bottom-1 -right-1 w-5 h-5 bg-emerald-500 border-4 border-gray-950 rounded-full"></span>
                </div>
                <div>
                  <h3 className="font-black text-2xl tracking-tighter uppercase leading-none">BFC Assist</h3>
                  <div className="flex items-center gap-2 mt-2.5">
                    <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_#10b981]"></span>
                    <p className="text-[10px] font-black uppercase tracking-[4px] opacity-60">Node Connected</p>
                  </div>
                </div>
              </div>
              <button 
                onClick={() => setIsOpen(false)} 
                className="w-12 h-12 bg-white/5 hover:bg-white/15 rounded-2xl flex items-center justify-center transition-all border border-white/10 group active:scale-90"
              >
                <i className="fas fa-chevron-down text-sm opacity-50 group-hover:opacity-100 transition-opacity"></i>
              </button>
            </div>
          </div>

          {/* Message Stream */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 scrollbar-hide bg-gradient-to-b from-gray-50/20 to-white">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                <div className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'} max-w-[85%]`}>
                  <div className={`px-7 py-5 rounded-[32px] text-[15px] font-bold leading-relaxed shadow-sm ring-1 ring-black/5 transition-all hover:shadow-xl ${
                    m.role === 'user' 
                    ? 'bg-gradient-to-br from-gray-800 to-gray-950 text-white rounded-br-none' 
                    : 'bg-white text-gray-800 rounded-tl-none border-b-4 border-gray-100'
                  }`}>
                    {m.text}
                  </div>
                  <span className="text-[8px] mt-3 font-black tracking-widest opacity-20 uppercase px-4">
                    {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start animate-slide-up">
                <div className="bg-white/80 backdrop-blur-sm px-7 py-5 rounded-[28px] rounded-tl-none flex gap-2 border border-white shadow-sm ring-1 ring-black/5">
                  <div className="w-2 h-2 bg-red-600 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-2 h-2 bg-red-600 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-2 h-2 bg-red-600 rounded-full animate-bounce"></div>
                </div>
              </div>
            )}
          </div>

          {/* Smart Interaction Layer */}
          <div className="p-8 bg-white/40 backdrop-blur-3xl border-t border-gray-100/60 shrink-0">
            {messages.length < 5 && !isTyping && (
              <div className="flex gap-3 overflow-x-auto pb-7 scrollbar-hide">
                {QUICK_ACTIONS.map(action => (
                  <button 
                    key={action}
                    onClick={() => handleSend(action)}
                    className="whitespace-nowrap px-7 py-4 bg-white/80 hover:bg-red-600 hover:text-white rounded-full text-[10px] font-black uppercase tracking-widest text-gray-900 border border-gray-100 transition-all active:scale-95 shadow-lg hover:shadow-red-600/20 hover:-translate-y-1"
                  >
                    {action}
                  </button>
                ))}
              </div>
            )}

            <div className="relative flex items-center bg-white/80 rounded-[35px] p-3 shadow-2xl border border-white group focus-within:ring-8 ring-red-500/5 transition-all ring-offset-0">
              <button 
                onClick={toggleVoice}
                className={`w-14 h-14 rounded-[26px] flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'text-gray-300 hover:text-red-600 hover:bg-red-50'}`}
              >
                <i className={`fas ${isListening ? 'fa-microphone-lines text-xl' : 'fa-microphone-alt text-lg'}`}></i>
              </button>

              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={isListening ? "Listening..." : "Tell me what's fire..."}
                className="flex-1 bg-transparent border-none py-4 px-5 outline-none text-[15px] font-bold text-gray-800 placeholder:text-gray-300"
              />

              <button 
                onClick={() => handleSend()}
                disabled={!input.trim() || isTyping}
                className="w-14 h-14 bg-gray-950 text-white rounded-[26px] flex items-center justify-center hover:bg-red-600 transition-all disabled:opacity-5 shadow-xl active:scale-90 group-hover:shadow-red-600/40"
              >
                <i className="fas fa-paper-plane text-lg"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-gray-950 text-white w-20 h-20 lg:w-26 lg:h-26 rounded-[35px] lg:rounded-[45px] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.5)] flex items-center justify-center hover:scale-110 active:scale-95 transition-all duration-700 group relative border-[6px] border-white ring-1 ring-black/10 overflow-hidden"
        >
          <div className="absolute inset-0 bg-gradient-to-tr from-red-600 to-red-800 opacity-0 group-hover:opacity-100 transition-all duration-700"></div>
          <div className="relative z-10 flex flex-col items-center gap-1.5 transition-transform duration-500 group-hover:-translate-y-1">
            <i className="fas fa-utensils text-2xl lg:text-3xl"></i>
            <span className="text-[9px] font-black uppercase tracking-[4px] opacity-0 group-hover:opacity-100 translate-y-2 group-hover:translate-y-0 transition-all duration-500">Assist</span>
          </div>
          <div className="absolute top-3 right-3 w-3 h-3 bg-red-600 rounded-full border-2 border-white z-20 group-hover:scale-150 transition-transform">
             <div className="absolute inset-0 bg-red-600 rounded-full animate-ping opacity-75"></div>
          </div>
        </button>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
  persistent?: boolean;
}

const MOCK_AUTH_DB = {
  'admin@bfc.com': { pass: 'admin123', role: UserRole.ADMIN, name: 'Root Admin' },
  'manager@bfc.com': { pass: 'manager456', role: UserRole.MANAGER, name: 'Node Manager' },
  'staff@bfc.com': { pass: 'staff789', role: UserRole.STAFF, name: 'Logistics Staff' }
};

const MAX_ATTEMPTS = 3;
const LOCKOUT_TIME = 60000;

const generateSecureToken = (role: UserRole, email: string) => {
  const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
  const payload = btoa(JSON.stringify({
    role,
    email,
    iat: Date.now(),
    exp: Date.now() + 3600000 
  }));
  const signature = btoa(`bfc_master_secret_${email}_${role}_v2`);
  return `${header}.${payload}.${signature}`;
};

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE'>('HOME');
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [language, setLanguage] = useState<'EN' | 'BN'>('BN');
  const [selectedProduct, setSelectedProduct] = useState<MenuItem | null>(null);
  const [activeCategory, setActiveCategory] = useState('All');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Form States
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [formName, setFormName] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [emailError, setEmailError] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [failedAttempts, setFailedAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);

  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [checkoutError, setCheckoutError] = useState<string | null>(null);

  const showToast = useCallback((message: string, type: Toast['type'] = 'info', persistent: boolean = false) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, persistent }]);
    if (!persistent) {
      setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
    }
  }, []);

  const dismissToast = (id: number) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  useEffect(() => {
    const handleOnline = () => { 
      setIsOnline(true); 
      showToast('Connection Restored: Syncing with BFC Node.', 'success'); 
    };
    const handleOffline = () => { 
      setIsOnline(false); 
      showToast('Offline Mode: Some features are restricted.', 'error', true); 
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (savedUser) {
      try {
        const user = JSON.parse(savedUser) as User;
        if (user.sessionToken) {
          const parts = user.sessionToken.split('.');
          if (parts.length === 3) {
            const payload = JSON.parse(atob(parts[1]));
            if (payload.exp > Date.now()) {
              setCurrentUser(user);
            } else {
              localStorage.removeItem('bfc_user_session');
              showToast("Session expired. Please log in again.", "warning");
            }
          }
        }
      } catch (e) {
        localStorage.removeItem('bfc_user_session');
      }
    }
  }, [showToast]);

  const validateAuthForm = () => {
    let isValid = true;
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!formEmail) {
      setEmailError("Email is required.");
      isValid = false;
    } else if (!emailRegex.test(formEmail)) {
      setEmailError("Enter a valid email address.");
      isValid = false;
    } else {
      setEmailError("");
    }

    if (!formPass || formPass.length < 4) {
      showToast("Passkey must be at least 4 characters.", "warning");
      isValid = false;
    }

    if (authMode === 'REGISTER' && (!formName || !formPhone)) {
      showToast("Name and Phone are required for registration.", "warning");
      isValid = false;
    }

    return isValid;
  };

  const handleAuth = async () => {
    if (!validateAuthForm()) return;

    if (lockoutUntil && Date.now() < lockoutUntil) {
      const remaining = Math.ceil((lockoutUntil - Date.now()) / 1000);
      return showToast(`Lockout Active: Try in ${remaining}s.`, 'error');
    }

    setIsAuthenticating(true);
    await new Promise(r => setTimeout(r, 1500));

    const emailKey = formEmail.toLowerCase().trim();

    if (authMode === 'REGISTER') {
      const existingCustomers = JSON.parse(localStorage.getItem('bfc_customers') || '{}');
      if (existingCustomers[emailKey] || MOCK_AUTH_DB[emailKey as keyof typeof MOCK_AUTH_DB]) {
        showToast("Email already registered. Try logging in.", "error");
        setIsAuthenticating(false);
        return;
      }

      const newCustomer: any = {
        name: formName,
        email: emailKey,
        pass: formPass,
        phone: formPhone,
        role: UserRole.CUSTOMER,
        loyaltyPoints: 50,
        tier: 'SILVER',
        referralCode: 'BFC-' + Math.random().toString(36).slice(7).toUpperCase()
      };

      existingCustomers[emailKey] = newCustomer;
      localStorage.setItem('bfc_customers', JSON.stringify(existingCustomers));

      showToast("Account Created! You've earned 50 welcome points.", "success");
      setAuthMode('LOGIN');
      setIsAuthenticating(false);
      return;
    }

    // Login Logic
    const privileged = MOCK_AUTH_DB[emailKey as keyof typeof MOCK_AUTH_DB];
    const customers = JSON.parse(localStorage.getItem('bfc_customers') || '{}');
    const registeredCustomer = customers[emailKey];

    const match = privileged || registeredCustomer;

    if (match && match.pass === formPass) {
      setFailedAttempts(0);
      const user: User = {
        id: 'BFC-' + Math.random().toString(36).slice(7).toUpperCase(),
        name: match.name, 
        email: emailKey, 
        phone: match.phone || '01700-000000',
        role: match.role, 
        loyaltyPoints: match.loyaltyPoints || 0, 
        tier: match.tier || 'SILVER',
        wishlist: [], 
        referralCode: match.referralCode || 'N/A',
        sessionToken: generateSecureToken(match.role, emailKey)
      };
      localStorage.setItem('bfc_user_session', JSON.stringify(user));
      setCurrentUser(user);
      showToast(`Logged in as ${user.name}`, 'success');
      setView(user.role === UserRole.CUSTOMER ? 'HOME' : 'ADMIN');
    } else {
      const newAttempts = failedAttempts + 1;
      setFailedAttempts(newAttempts);
      if (newAttempts >= MAX_ATTEMPTS) {
        setLockoutUntil(Date.now() + LOCKOUT_TIME);
        showToast('Node Lockout triggered.', 'error', true);
      } else {
        showToast(`Invalid credentials. ${MAX_ATTEMPTS - newAttempts} left.`, 'error');
      }
    }
    setIsAuthenticating(false);
  };

  const handleCheckout = async () => {
    if (!isOnline) {
      showToast("Checkout Failed: No Connection.", "error");
      return;
    }
    setIsCheckingOut(true);
    setCheckoutError(null);
    await new Promise(r => setTimeout(r, 2000));
    if (Math.random() < 0.2) {
      setCheckoutError("Payment Declined. Please try another method.");
      showToast("Transaction Failed.", "error");
      setIsCheckingOut(false);
    } else {
      setCart([]);
      showToast("Order Successful!", "success");
      setIsCheckingOut(false);
      setTimeout(() => setView('HOME'), 2000);
    }
  };

  const isPrivileged = currentUser && [UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF].includes(currentUser.role);

  if (view === 'ADMIN' && isPrivileged) {
    return (
      <AdminPanel 
        userRole={currentUser.role} 
        onLogout={() => { 
          localStorage.removeItem('bfc_user_session');
          setCurrentUser(null); 
          setView('HOME'); 
          showToast('Safely logged out.', 'info');
        }}
        menuItems={menuItems}
        setMenuItems={setMenuItems}
        orders={allOrders}
        setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans selection:bg-red-100 overflow-x-hidden">
      {/* Dynamic Toast Notifications */}
      <div className="fixed top-12 right-8 z-[1000] space-y-4 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-start gap-4 px-6 py-5 rounded-3xl shadow-2xl border bg-white animate-slide-up border-gray-100 text-gray-800 ring-1 ring-black/5">
            <div className={`w-8 h-8 rounded-xl shrink-0 flex items-center justify-center text-xs ${
              t.type === 'error' ? 'bg-red-50 text-red-600' : 
              t.type === 'warning' ? 'bg-amber-50 text-amber-600' : 
              t.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'
            }`}>
              <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark' : t.type === 'warning' ? 'fa-triangle-exclamation' : t.type === 'success' ? 'fa-circle-check' : 'fa-info-circle'}`}></i>
            </div>
            <div className="flex-1">
              <p className="font-bold text-[11px] leading-relaxed">{t.message}</p>
            </div>
          </div>
        ))}
      </div>

      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-14 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-[15px] flex items-center justify-center text-white text-xl font-black shadow-xl group-hover:rotate-6 transition-transform">B</div>
          <h1 className="text-xl lg:text-2xl font-black text-red-600 tracking-tighter">BFC</h1>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 bg-gray-50 rounded-2xl flex items-center justify-center">
            <i className="fas fa-shopping-basket text-gray-600"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[9px] w-5 h-5 rounded-full flex items-center justify-center ring-2 ring-white font-black">{cart.reduce((a,b)=>a+b.qty, 0)}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 rounded-2xl bg-gray-950 text-white font-black flex items-center justify-center shadow-lg border-2 border-white">
               {currentUser.name.charAt(0)}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl px-6" onClick={() => setView('LOGIN')}>Login</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-12 min-h-[80vh]">
        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto mt-6 lg:mt-12 perspective-1000">
            <div className="bg-white/80 backdrop-blur-3xl p-10 lg:p-14 rounded-[50px] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.1)] border border-white animate-slide-up relative overflow-hidden">
               <div className="flex gap-2 p-1.5 bg-gray-100 rounded-3xl mb-10">
                  <button onClick={()=>setAuthMode('LOGIN')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${authMode === 'LOGIN' ? 'bg-white text-gray-900 shadow-md' : 'text-gray-400'}`}>Login</button>
                  <button onClick={()=>setAuthMode('REGISTER')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${authMode === 'REGISTER' ? 'bg-white text-gray-900 shadow-md' : 'text-gray-400'}`}>Register</button>
               </div>

               <div className="text-center mb-8">
                  <h2 className="text-3xl font-black text-gray-900 uppercase tracking-tight">{authMode === 'LOGIN' ? 'Welcome Back' : 'Join the Club'}</h2>
                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-[4px] mt-2">BFC VIP Terminal</p>
               </div>

               <div className="space-y-5">
                  {authMode === 'REGISTER' && (
                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-400 tracking-[5px] block ml-6">Full Name</label>
                      <input 
                        type="text" 
                        value={formName} 
                        onChange={(e)=>setFormName(e.target.value)}
                        placeholder="John Doe"
                        className="w-full bg-gray-50 border-2 border-transparent focus:border-red-600/20 focus:bg-white rounded-3xl px-8 py-4 font-bold outline-none transition-all"
                      />
                    </div>
                  )}

                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 tracking-[5px] block ml-6">Email Node</label>
                    <input 
                      type="email" 
                      value={formEmail} 
                      onChange={(e)=>{setFormEmail(e.target.value); setEmailError("");}}
                      placeholder="name@example.com"
                      className={`w-full bg-gray-50 border-2 rounded-3xl px-8 py-4 font-bold outline-none transition-all ${emailError ? 'border-red-400' : 'border-transparent focus:border-red-600/20'}`}
                    />
                  </div>

                  {authMode === 'REGISTER' && (
                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-400 tracking-[5px] block ml-6">Phone Number</label>
                      <input 
                        type="tel" 
                        value={formPhone} 
                        onChange={(e)=>setFormPhone(e.target.value)}
                        placeholder="01700000000"
                        className="w-full bg-gray-50 border-2 border-transparent focus:border-red-600/20 focus:bg-white rounded-3xl px-8 py-4 font-bold outline-none transition-all"
                      />
                    </div>
                  )}

                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 tracking-[5px] block ml-6">Secure Passkey</label>
                    <div className="relative">
                      <input 
                        type={showPass ? 'text' : 'password'} 
                        value={formPass} 
                        onChange={(e)=>setFormPass(e.target.value)}
                        placeholder="••••••••"
                        className="w-full bg-gray-50 border-2 border-transparent focus:border-red-600/20 focus:bg-white rounded-3xl px-8 py-4 font-bold outline-none transition-all"
                      />
                      <button onClick={()=>setShowPass(!showPass)} className="absolute right-6 top-1/2 -translate-y-1/2 text-gray-300">
                        <i className={`fas ${showPass ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                      </button>
                    </div>
                  </div>

                  <Button 
                    fullWidth 
                    size="lg" 
                    className="rounded-[25px] py-5 shadow-xl mt-4" 
                    onClick={handleAuth}
                    disabled={isAuthenticating}
                  >
                    {isAuthenticating ? 'Processing...' : (authMode === 'LOGIN' ? 'Initiate Link' : 'Create Registry')}
                  </Button>
               </div>
            </div>
          </div>
        )}

        {view === 'PROFILE' && currentUser && (
          <div className="max-w-4xl mx-auto animate-slide-up">
            <div className="bg-white rounded-[50px] p-12 lg:p-20 shadow-sm border border-gray-100 relative overflow-hidden">
               <div className="absolute top-0 right-0 w-64 h-64 bg-red-600/5 rounded-full blur-3xl -mr-32 -mt-32"></div>

               <div className="flex flex-col lg:flex-row items-center gap-12 relative z-10">
                  <div className="w-40 h-40 bg-gray-900 rounded-[60px] flex items-center justify-center text-white text-6xl font-black shadow-2xl border-8 border-white ring-1 ring-black/5">
                     {currentUser.name.charAt(0)}
                  </div>
                  <div className="flex-1 text-center lg:text-left">
                     <span className="px-5 py-2 bg-red-600 text-white text-[9px] font-black uppercase tracking-[5px] rounded-full shadow-lg inline-block mb-4">{currentUser.tier} Member</span>
                     <h2 className="text-5xl font-black text-gray-900 tracking-tighter mb-2">{currentUser.name}</h2>
                     <p className="text-gray-400 font-bold">{currentUser.email}</p>
                  </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mt-20">
                  <div className="bg-gray-50 p-10 rounded-[40px] border border-gray-100">
                     <p className="text-[9px] font-black text-gray-400 uppercase tracking-[4px] mb-4">Loyalty Balance</p>
                     <div className="flex items-end gap-2">
                        <h4 className="text-4xl font-black text-red-600">৳{currentUser.loyaltyPoints}</h4>
                        <span className="text-[10px] font-black text-gray-400 mb-2 uppercase">Points</span>
                     </div>
                  </div>
                  <div className="bg-gray-50 p-10 rounded-[40px] border border-gray-100">
                     <p className="text-[9px] font-black text-gray-400 uppercase tracking-[4px] mb-4">Referral Code</p>
                     <h4 className="text-2xl font-black text-gray-900 tracking-tight">{currentUser.referralCode}</h4>
                  </div>
                  <div className="bg-gray-50 p-10 rounded-[40px] border border-gray-100">
                     <p className="text-[9px] font-black text-gray-400 uppercase tracking-[4px] mb-4">Account Status</p>
                     <div className="flex items-center gap-3">
                        <div className="w-3 h-3 bg-emerald-500 rounded-full animate-pulse"></div>
                        <h4 className="text-xl font-black text-gray-900 uppercase tracking-widest">Active</h4>
                     </div>
                  </div>
               </div>

               <div className="mt-12 flex flex-col md:flex-row gap-4">
                  <Button fullWidth className="rounded-3xl py-5" onClick={()=>{localStorage.removeItem('bfc_user_session'); setCurrentUser(null); setView('HOME');}}>Safe Logout</Button>
                  <Button fullWidth variant="outline" className="rounded-3xl py-5">Edit Registry</Button>
               </div>
            </div>
          </div>
        )}

        {view === 'HOME' && (
          <div className="animate-slide-up space-y-20">
            <header className="relative h-[400px] lg:h-[600px] rounded-[50px] overflow-hidden shadow-3xl group">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover transition-transform duration-[10s] group-hover:scale-110" />
               <div className="absolute inset-0 bg-gradient-to-r from-black/80 to-transparent flex flex-col justify-center px-12 lg:px-24">
                  <h2 className="text-4xl lg:text-8xl font-black text-white leading-[0.95] mb-8 tracking-tighter">
                    {language === 'BN' ? 'আসল স্বাদের' : 'The Real'}<br/>
                    <span className="text-red-600">{language === 'BN' ? 'জাদু' : 'Experience'}</span>
                  </h2>
                  <Button size="lg" className="rounded-[30px] w-fit px-10 py-5 text-lg" onClick={() => setView('MENU')}>Explore Menu</Button>
               </div>
            </header>
            <section>
              <h3 className="text-3xl font-black text-gray-800 tracking-tighter mb-12">Legendary Picks</h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                 {menuItems.slice(0, 4).map(item => (
                   <div key={item.id} className="bg-white rounded-[40px] overflow-hidden shadow-sm border border-gray-50 hover:shadow-2xl hover:-translate-y-2 transition-all group cursor-pointer" onClick={()=>setSelectedProduct(item)}>
                      <div className="h-56 overflow-hidden relative">
                         <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                      </div>
                      <div className="p-8">
                         <h4 className="text-xl font-black text-gray-800 tracking-tight mb-1">{language === 'BN' ? item.nameBn : item.name}</h4>
                         <p className="text-[9px] text-gray-400 font-black uppercase tracking-widest mb-6">{item.category}</p>
                         <div className="flex justify-between items-center">
                            <span className="text-2xl font-black text-red-600">৳{item.price}</span>
                            <button onClick={(e)=>{e.stopPropagation(); setCart(prev => [...prev, {item, qty:1}]); showToast('Added to Bag', 'success')}} className="w-10 h-10 bg-gray-900 text-white rounded-2xl flex items-center justify-center hover:bg-red-600 transition-colors"><i className="fas fa-plus"></i></button>
                         </div>
                      </div>
                   </div>
                 ))}
              </div>
            </section>
          </div>
        )}

        {view === 'MENU' && (
          <div className="animate-slide-up space-y-12">
             <div className="flex justify-between items-end border-b-2 border-gray-100 pb-10">
                <h2 className="text-5xl font-black text-gray-800 tracking-tighter uppercase leading-none">The Menu</h2>
                <div className="flex gap-4 overflow-x-auto pb-2 scrollbar-hide">
                   {['All', 'Biryani', 'Curry', 'Kebab', 'Desserts'].map(cat => (
                     <button key={cat} onClick={() => setActiveCategory(cat)} className={`px-6 py-3 rounded-[20px] text-[10px] font-black uppercase tracking-widest border-2 transition-all ${activeCategory === cat ? 'bg-gray-900 border-gray-900 text-white shadow-xl' : 'bg-white border-gray-100 text-gray-400'}`}>{cat}</button>
                   ))}
                </div>
             </div>
             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                {menuItems.filter(i => activeCategory === 'All' || i.category === activeCategory).map(item => (
                   <div key={item.id} className="bg-white rounded-[40px] overflow-hidden shadow-sm border border-gray-50 hover:shadow-2xl hover:-translate-y-2 transition-all group cursor-pointer" onClick={()=>setSelectedProduct(item)}>
                      <div className="h-48 overflow-hidden"><img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" /></div>
                      <div className="p-8">
                         <h4 className="text-xl font-black text-gray-800 tracking-tight mb-1">{language === 'BN' ? item.nameBn : item.name}</h4>
                         <p className="text-[9px] text-gray-400 font-black uppercase tracking-widest mb-6">{item.category}</p>
                         <div className="flex justify-between items-center">
                            <span className="text-2xl font-black text-red-600">৳{item.price}</span>
                            <button onClick={(e)=>{e.stopPropagation(); setCart(prev => [...prev, {item, qty:1}]); showToast('Added to Bag', 'success')}} className="w-10 h-10 bg-gray-900 text-white rounded-2xl flex items-center justify-center hover:bg-red-600 transition-colors"><i className="fas fa-plus"></i></button>
                         </div>
                      </div>
                   </div>
                ))}
             </div>
          </div>
        )}
      </main>

      <ChatBot />

      {/* Mobile Control Bar */}
      <div className="lg:hidden fixed bottom-0 w-full bg-white/95 backdrop-blur-xl px-10 py-6 flex justify-between items-center z-[200] border-t border-gray-100 shadow-2xl rounded-t-[35px]">
         <button onClick={()=>setView('HOME')} className={`text-2xl ${view === 'HOME' ? 'text-red-600' : 'text-gray-300'}`}><i className="fas fa-home"></i></button>
         <button onClick={()=>setView('MENU')} className={`text-2xl ${view === 'MENU' ? 'text-red-600' : 'text-gray-300'}`}><i className="fas fa-utensils"></i></button>
         <button onClick={()=>setView('CART')} className={`text-2xl relative ${view === 'CART' ? 'text-red-600' : 'text-gray-300'}`}>
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[8px] w-5 h-5 rounded-full flex items-center justify-center ring-2 ring-white font-black">{cart.length}</span>}
         </button>
         <button onClick={()=>currentUser ? setView('PROFILE') : setView('LOGIN')} className={`text-2xl ${['PROFILE', 'LOGIN'].includes(view) ? 'text-red-600' : 'text-gray-300'}`}><i className="fas fa-user-circle"></i></button>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from './types';
import { Button } from './components/Button';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, BarChart, Bar
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 },
  { name: 'Sun', sales: 3800 },
  { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 },
  { name: 'Wed', sales: 6200 },
  { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

const CATEGORY_DATA = [
  { name: 'Biryani', value: 45, color: '#dc2626' },
  { name: 'Kebab', value: 25, color: '#ea580c' },
  { name: 'Curry', value: 20, color: '#f59e0b' },
  { name: 'Desserts', value: 10, color: '#10b981' },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const [activeTab, setActiveTab] = useState(userRole === UserRole.STAFF ? 'workplace' : 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [adminToast, setAdminToast] = useState<{msg: string, type: 'success' | 'error' | 'warning'} | null>(null);
  const [customers, setCustomers] = useState<any[]>([]);

  const showToast = useCallback((msg: string, type: 'success' | 'error' | 'warning') => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 3000);
  }, []);

  // Sync Customers from LocalStorage
  useEffect(() => {
    const raw = localStorage.getItem('bfc_customers');
    if (raw) {
      const data = JSON.parse(raw);
      setCustomers(Object.values(data));
    }
  }, []);

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    const today = new Date().toISOString().split('T')[0];
    const todayOrders = orders.filter(o => o.createdAt.startsWith(today));

    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length,
      todayCount: todayOrders.length,
      todayRevenue: todayOrders.reduce((acc, o) => acc + o.total, 0)
    };
  }, [orders, menuItems]);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order ${orderId.slice(-4)} updated to ${newStatus}`, 'success');
  };

  const isStaff = userRole === UserRole.STAFF;
  const isManagerOrAdmin = userRole === UserRole.MANAGER || userRole === UserRole.ADMIN;

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden font-sans">
      {/* Admin Toast */}
      {adminToast && (
        <div className={`fixed top-8 left-1/2 -translate-x-1/2 z-[2000] px-6 py-3 rounded-2xl shadow-2xl border animate-slide-up flex items-center gap-3 ${
          adminToast.type === 'error' ? 'bg-red-600 border-red-400 text-white' : 
          adminToast.type === 'warning' ? 'bg-amber-500 border-amber-400 text-white' : 'bg-gray-900 border-white/10 text-white'
        }`}>
          <i className="fas fa-circle-check"></i>
          <span className="text-[10px] font-black uppercase tracking-widest">{adminToast.msg}</span>
        </div>
      )}

      {/* Sidebar - Dynamically rendered based on Role */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 lg:w-80 bg-white border-r border-gray-100 transition-transform duration-500 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-10 flex items-center gap-4">
          <div className="w-10 h-10 bg-red-600 rounded-2xl flex items-center justify-center text-white shadow-xl rotate-3">
            <i className="fas fa-shield-halved"></i>
          </div>
          <h1 className="text-xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
        </div>

        <nav className="p-6 space-y-2">
          {isManagerOrAdmin && (
            <>
              <SidebarBtn active={activeTab === 'dashboard'} onClick={()=>setActiveTab('dashboard')} icon="fa-chart-pie" label="Insights" />
              <SidebarBtn active={activeTab === 'orders'} onClick={()=>setActiveTab('orders')} icon="fa-list-check" label="All Orders" />
              <SidebarBtn active={activeTab === 'menu'} onClick={()=>setActiveTab('menu')} icon="fa-utensils" label="Menu Editor" />
              <SidebarBtn active={activeTab === 'customers'} onClick={()=>setActiveTab('customers')} icon="fa-users" label="Customers" />
              <SidebarBtn active={activeTab === 'reports'} onClick={()=>setActiveTab('reports')} icon="fa-file-invoice-dollar" label="Fiscal Reports" />
            </>
          )}
          {isStaff && (
            <>
              <SidebarBtn active={activeTab === 'workplace'} onClick={()=>setActiveTab('workplace')} icon="fa-briefcase" label="Today's Workplace" />
              <SidebarBtn active={activeTab === 'inventory'} onClick={()=>setActiveTab('inventory')} icon="fa-box-open" label="Inventory Check" />
            </>
          )}
        </nav>

        <div className="absolute bottom-0 w-full p-8 border-t">
          <div className="flex items-center gap-4 mb-8">
            <div className="w-12 h-12 bg-gray-100 rounded-2xl flex items-center justify-center font-black text-gray-950">
              {userRole.charAt(0)}
            </div>
            <div>
              <p className="text-[10px] font-black text-gray-950 uppercase tracking-widest">{userRole}</p>
              <p className="text-[8px] font-bold text-gray-400">Node Active</p>
            </div>
          </div>
          <button onClick={onLogout} className="w-full flex items-center justify-center gap-3 py-4 rounded-2xl bg-gray-50 text-gray-400 font-black hover:bg-red-50 hover:text-red-600 transition-all uppercase tracking-[4px] text-[9px]">
            Terminate
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0">
        <header className="h-24 bg-white/80 backdrop-blur-xl border-b flex items-center justify-between px-12 shrink-0 z-50">
          <div className="lg:hidden">
            <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="w-10 h-10 bg-gray-100 rounded-xl flex items-center justify-center">
              <i className="fas fa-bars"></i>
            </button>
          </div>
          <h2 className="text-2xl font-black text-gray-800 tracking-tight uppercase">
            {isStaff ? "Operations Terminal" : "Management Suite"}
          </h2>
          <div className="text-[9px] font-black text-gray-400 uppercase tracking-widest bg-gray-50 px-6 py-2 rounded-full border border-gray-100">
             Region: DHAKA-NORTH-01
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-12 space-y-12 animate-slide-up">

          {/* STAFF DASHBOARD VIEW */}
          {activeTab === 'workplace' && isStaff && (
            <div className="space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                <StatCard title="Today's Load" value={stats.todayCount} icon="fa-fire-flame-curved" color="text-red-600" />
                <StatCard title="Pending Pickup" value={stats.pending} icon="fa-truck-fast" color="text-amber-600" />
                <StatCard title="Revenue (Today)" value={`৳${stats.todayRevenue.toLocaleString()}`} icon="fa-money-bill-trend-up" color="text-emerald-600" />
              </div>

              <div className="bg-white rounded-[40px] border border-gray-100 shadow-sm overflow-hidden">
                <div className="p-8 border-b flex items-center justify-between bg-gray-50/50">
                  <h3 className="text-xl font-black text-gray-900">Today's Live Orders</h3>
                  <div className="flex gap-2">
                    <span className="w-3 h-3 bg-emerald-500 rounded-full animate-ping"></span>
                    <span className="text-[10px] font-black uppercase tracking-widest text-emerald-600">Live Queue</span>
                  </div>
                </div>
                <div className="divide-y divide-gray-50">
                  {orders.length === 0 ? (
                    <div className="p-20 text-center text-gray-400 font-bold uppercase tracking-widest text-[10px]">No orders in queue</div>
                  ) : (
                    orders.map(o => (
                      <div key={o.id} className="p-8 flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6 hover:bg-gray-50 transition-all">
                        <div className="flex items-center gap-6">
                           <div className="w-16 h-16 bg-gray-950 rounded-3xl flex items-center justify-center text-white font-black text-lg">#{o.id.slice(-4)}</div>
                           <div>
                              <p className="font-black text-gray-900 text-lg leading-none mb-2">{o.customerName}</p>
                              <div className="flex gap-2">
                                {o.items.map((it, idx) => (
                                  <span key={idx} className="bg-gray-100 px-3 py-1 rounded-full text-[9px] font-bold text-gray-500">
                                    {it.quantity}x {it.name}
                                  </span>
                                ))}
                              </div>
                           </div>
                        </div>
                        <div className="flex items-center gap-4 w-full lg:w-auto">
                           <select 
                            className={`flex-1 lg:w-48 p-4 rounded-2xl text-[10px] font-black uppercase tracking-widest border-2 outline-none transition-all ${
                              o.status === OrderStatus.DELIVERED ? 'border-emerald-200 bg-emerald-50 text-emerald-700' : 'border-red-100 bg-white text-gray-900 focus:border-red-600'
                            }`}
                            value={o.status}
                            onChange={(e) => handleUpdateStatus(o.id, e.target.value as OrderStatus)}
                           >
                              {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                           </select>
                           <button className="w-14 h-14 bg-gray-950 text-white rounded-2xl hover:bg-red-600 transition-all shadow-lg flex items-center justify-center">
                              <i className="fas fa-print"></i>
                           </button>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
            </div>
          )}

          {/* MANAGER DASHBOARD VIEW */}
          {activeTab === 'dashboard' && isManagerOrAdmin && (
            <div className="space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                <StatCard title="Gross Revenue" value={`৳${stats.revenue.toLocaleString()}`} icon="fa-vault" color="text-red-600" />
                <StatCard title="Total Volume" value={stats.orderCount} icon="fa-box-archive" color="text-blue-600" />
                <StatCard title="VIP Customers" value={customers.length} icon="fa-users" color="text-purple-600" />
                <StatCard title="Restock Alert" value={stats.lowStock} icon="fa-warning" color="text-amber-500" />
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-white p-10 rounded-[50px] border border-gray-100 shadow-sm">
                   <h3 className="text-xl font-black mb-10 uppercase tracking-tighter">Performance Velocity</h3>
                   <div className="h-[300px]">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={ANALYTICS_DATA}>
                          <defs>
                            <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                              <stop offset="5%" stopColor="#dc2626" stopOpacity={0.1}/>
                              <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                            </linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                          <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                          <Tooltip />
                          <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={5} fill="url(#colorSales)" />
                        </AreaChart>
                      </ResponsiveContainer>
                   </div>
                </div>
                <div className="bg-white p-10 rounded-[50px] border border-gray-100 shadow-sm">
                   <h3 className="text-xl font-black mb-10 uppercase tracking-tighter">Category Mix</h3>
                   <div className="h-[300px]">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={CATEGORY_DATA} innerRadius={70} outerRadius={100} paddingAngle={8} dataKey="value">
                            {CATEGORY_DATA.map((entry, idx) => <Cell key={idx} fill={entry.color} />)}
                          </Pie>
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                   </div>
                </div>
              </div>
            </div>
          )}

          {/* CUSTOMER LIST (Manager/Admin only) */}
          {activeTab === 'customers' && isManagerOrAdmin && (
            <div className="bg-white rounded-[50px] border border-gray-100 shadow-sm overflow-hidden animate-slide-up">
              <div className="p-10 border-b flex justify-between items-center">
                 <h3 className="text-2xl font-black text-gray-900">Member Registry</h3>
                 <span className="text-[10px] font-black uppercase tracking-[4px] bg-red-600 text-white px-5 py-2 rounded-full">{customers.length} Members</span>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="bg-gray-50 border-b border-gray-100">
                       <th className="px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Identity</th>
                       <th className="px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Communication</th>
                       <th className="px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Loyalty Status</th>
                       <th className="px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50">
                    {customers.map((c, idx) => (
                      <tr key={idx} className="hover:bg-gray-50/50 transition-all">
                        <td className="px-10 py-8 font-black text-gray-900">{c.name}</td>
                        <td className="px-10 py-8 text-sm text-gray-500 font-bold">{c.email}</td>
                        <td className="px-10 py-8">
                           <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest ${
                             c.tier === 'PLATINUM' ? 'bg-indigo-100 text-indigo-700' :
                             c.tier === 'GOLD' ? 'bg-amber-100 text-amber-700' : 'bg-gray-100 text-gray-500'
                           }`}>{c.tier} ({c.loyaltyPoints} pts)</span>
                        </td>
                        <td className="px-10 py-8">
