                  <div className="bg-gray-50 p-10 rounded-[40px] border border-gray-100 group transition-all hover:bg-white hover:shadow-xl">
                     <p className="text-[9px] font-black text-gray-400 uppercase tracking-[4px] mb-4">Referral Code</p>
                     <h4 className="text-2xl font-black text-gray-900 tracking-tight uppercase">{currentUser.referralCode}</h4>
                  </div>
                  <div className="bg-gray-50 p-10 rounded-[40px] border border-gray-100 group transition-all hover:bg-white hover:shadow-xl">
                     <p className="text-[9px] font-black text-gray-400 uppercase tracking-[4px] mb-4">Account Status</p>
                     <div className="flex items-center gap-3">
                        <div className="w-3 h-3 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_#10b981]"></div>
                        <h4 className="text-xl font-black text-gray-900 uppercase tracking-widest">Active</h4>
                     </div>
                  </div>
               </div>

               <div className="mt-12 flex flex-col md:flex-row gap-4">
                  {isEditingProfile ? (
                    <>
                      <Button fullWidth className="rounded-3xl py-5 shadow-xl" onClick={handleSaveProfile}>Confirm Changes</Button>
                      <Button fullWidth variant="outline" className="rounded-3xl py-5" onClick={() => setIsEditingProfile(false)}>Cancel</Button>
                    </>
                  ) : (
                    <>
                      <Button fullWidth className="rounded-3xl py-5" onClick={startEditing}>Edit Registry</Button>
                      <Button fullWidth variant="outline" className="rounded-3xl py-5" onClick={()=>{localStorage.removeItem('bfc_user_session'); setCurrentUser(null); setView('HOME');}}>Terminate Link</Button>
                    </>
                  )}
               </div>
            </div>
          </div>
        )}

        {view === 'HOME' && (
          <div className="animate-slide-up space-y-20">
            <header className="relative h-[400px] lg:h-[600px] rounded-[50px] overflow-hidden shadow-3xl group">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover transition-transform duration-[10s] group-hover:scale-110" />
               <div className="absolute inset-0 bg-gradient-to-r from-black/80 to-transparent flex flex-col justify-center px-12 lg:px-24">
                  <h2 className="text-4xl lg:text-8xl font-black text-white leading-[0.95] mb-8 tracking-tighter">
                    {language === 'BN' ? 'আসল স্বাদের' : 'The Real'}<br/>
                    <span className="text-red-600">{language === 'BN' ? 'জাদু' : 'Experience'}</span>
                  </h2>
                  <Button size="lg" className="rounded-[30px] w-fit px-10 py-5 text-lg shadow-2xl hover:bg-red-700" onClick={() => setView('MENU')}>Explore Menu</Button>
               </div>
            </header>
            <section>
              <div className="flex justify-between items-center mb-12">
                <h3 className="text-3xl font-black text-gray-800 tracking-tighter">Legendary Picks</h3>
                <button onClick={() => setView('MENU')} className="text-[10px] font-black uppercase tracking-[5px] text-gray-400 hover:text-red-600 transition-colors">View All</button>
