              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                 {menuItems.slice(0, 4).map(item => (
                   <div key={item.id} className="bg-white rounded-[40px] overflow-hidden shadow-sm border border-gray-50 hover:shadow-2xl hover:-translate-y-2 transition-all group cursor-pointer" onClick={()=>setSelectedProduct(item)}>
                      <div className="h-56 overflow-hidden relative">
                         <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                      </div>
                      <div className="p-8">
                         <h4 className="text-xl font-black text-gray-800 tracking-tight mb-1">{language === 'BN' ? item.nameBn : item.name}</h4>
                         <p className="text-[9px] text-gray-400 font-black uppercase tracking-widest mb-6">{item.category}</p>
                         <div className="flex justify-between items-center">
                            <span className="text-2xl font-black text-red-600">৳{item.price}</span>
                            <button onClick={(e)=>{e.stopPropagation(); setCart(prev => [...prev, {item, qty:1}]); showToast('Added to Bag', 'success')}} className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center hover:bg-red-600 transition-colors shadow-lg active:scale-90"><i className="fas fa-plus"></i></button>
                         </div>
                      </div>
                   </div>
                 ))}
              </div>
            </section>
          </div>
        )}

        {view === 'MENU' && (
          <div className="animate-slide-up space-y-12">
             <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end border-b-2 border-gray-100 pb-10 gap-8">
                <div>
                   <h2 className="text-5xl font-black text-gray-800 tracking-tighter uppercase leading-none">The Menu</h2>
                   <p className="text-[9px] font-black text-gray-400 uppercase tracking-[4px] mt-4">Handcrafted Heritage Cuisine</p>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-2 scrollbar-hide w-full lg:w-auto">
                   {['All', 'Biryani', 'Curry', 'Kebab', 'Desserts'].map(cat => (
                     <button key={cat} onClick={() => setActiveCategory(cat)} className={`px-7 py-4 rounded-[22px] text-[10px] font-black uppercase tracking-widest border-2 transition-all whitespace-nowrap ${activeCategory === cat ? 'bg-gray-900 border-gray-900 text-white shadow-xl' : 'bg-white border-gray-100 text-gray-400 hover:border-red-600/30'}`}>{cat}</button>
                   ))}
                </div>
             </div>
             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                {menuItems.filter(i => activeCategory === 'All' || i.category === activeCategory).map(item => (
                   <div key={item.id} className="bg-white rounded-[40px] overflow-hidden shadow-sm border border-gray-50 hover:shadow-2xl hover:-translate-y-2 transition-all group cursor-pointer" onClick={()=>setSelectedProduct(item)}>
                      <div className="h-48 overflow-hidden relative">
                         <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                         {item.isPopular && <span className="absolute top-6 right-6 bg-red-600 text-white text-[8px] font-black uppercase px-4 py-2 rounded-full shadow-xl">Hot</span>}
                      </div>
                      <div className="p-8">
                         <h4 className="text-xl font-black text-gray-800 tracking-tight mb-1">{language === 'BN' ? item.nameBn : item.name}</h4>
                         <p className="text-[9px] text-gray-400 font-black uppercase tracking-widest mb-6">{item.category}</p>
                         <div className="flex justify-between items-center">
                            <span className="text-2xl font-black text-red-600">৳{item.price}</span>
                            <button onClick={(e)=>{e.stopPropagation(); setCart(prev => [...prev, {item, qty:1}]); showToast('Added to Bag', 'success')}} className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center hover:bg-red-600 transition-colors shadow-lg active:scale-90"><i className="fas fa-plus"></i></button>
                         </div>
                      </div>
                   </div>
                ))}
             </div>
          </div>
        )}
      </main>

      <ChatBot />

      {/* Mobile Control Bar */}
      <div className="lg:hidden fixed bottom-0 w-full bg-white/95 backdrop-blur-xl px-10 py-6 flex justify-between items-center z-[200] border-t border-gray-100 shadow-[0_-20px_50px_rgba(0,0,0,0.1)] rounded-t-[40px]">
         <button onClick={()=>setView('HOME')} className={`text-2xl transition-all ${view === 'HOME' ? 'text-red-600 scale-125' : 'text-gray-300'}`}><i className="fas fa-house"></i></button>
         <button onClick={()=>setView('MENU')} className={`text-2xl transition-all ${view === 'MENU' ? 'text-red-600 scale-125' : 'text-gray-300'}`}><i className="fas fa-utensils"></i></button>
         <button onClick={()=>setView('CART')} className={`text-2xl relative transition-all ${view === 'CART' ? 'text-red-600 scale-125' : 'text-gray-300'}`}>
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[8px] w-5 h-5 rounded-full flex items-center justify-center ring-2 ring-white font-black">{cart.length}</span>}
         </button>
         <button onClick={()=>currentUser ? setView('PROFILE') : setView('LOGIN')} className={`text-2xl transition-all ${['PROFILE', 'LOGIN'].includes(view) ? 'text-red-600 scale-125' : 'text-gray-300'}`}>
            {currentUser?.profileImage && ['PROFILE'].includes(view) ? (
              <img src={currentUser.profileImage} className="w-8 h-8 rounded-xl object-cover ring-2 ring-red-600" />
            ) : (
              <i className="fas fa-circle-user"></i>
            )}
         </button>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
  persistent?: boolean;
}

const MOCK_AUTH_DB = {
  'admin@bfc.com': { pass: 'admin123', role: UserRole.ADMIN, name: 'Root Admin' },
  'manager@bfc.com': { pass: 'manager456', role: UserRole.MANAGER, name: 'Node Manager' },
  'staff@bfc.com': { pass: 'staff789', role: UserRole.STAFF, name: 'Logistics Staff' }
};

const MAX_ATTEMPTS = 3;
const LOCKOUT_TIME = 60000;

const generateSecureToken = (role: UserRole, email: string) => {
  const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
  const payload = btoa(JSON.stringify({
    role,
    email,
    iat: Date.now(),
    exp: Date.now() + 3600000 
  }));
  const signature = btoa(`bfc_master_secret_${email}_${role}_v2`);
  return `${header}.${payload}.${signature}`;
};

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE'>('HOME');
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [language, setLanguage] = useState<'EN' | 'BN'>('BN');
  const [selectedProduct, setSelectedProduct] = useState<MenuItem | null>(null);
  const [activeCategory, setActiveCategory] = useState('All');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Form States
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [formName, setFormName] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [emailError, setEmailError] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [failedAttempts, setFailedAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);

  // Profile Edit States
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editName, setEditName] = useState('');
  const [editPhone, setEditPhone] = useState('');
  const [editImage, setEditImage] = useState<string | undefined>(undefined);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [checkoutError, setCheckoutError] = useState<string | null>(null);

  const showToast = useCallback((message: string, type: Toast['type'] = 'info', persistent: boolean = false) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, persistent }]);
    if (!persistent) {
      setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
    }
  }, []);

  useEffect(() => {
    const handleOnline = () => { 
      setIsOnline(true); 
      showToast('Connection Restored: You are back online. All features are now active.', 'success'); 
    };
    const handleOffline = () => { 
      setIsOnline(false); 
      showToast('You are currently offline. Please check your internet connection to place orders.', 'error', true); 
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (savedUser) {
      try {
        const user = JSON.parse(savedUser) as User;
        if (user.sessionToken) {
          const parts = user.sessionToken.split('.');
          if (parts.length === 3) {
            const payload = JSON.parse(atob(parts[1]));
            if (payload.exp > Date.now()) {
              setCurrentUser(user);
            } else {
              localStorage.removeItem('bfc_user_session');
              showToast("Your session has expired for security. Please log in again to continue.", "warning");
            }
          }
        }
      } catch (e) {
        localStorage.removeItem('bfc_user_session');
      }
    }
  }, [showToast]);

  const validateAuthForm = () => {
    let isValid = true;
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!formEmail) {
      setEmailError("Email address is required.");
      isValid = false;
    } else if (!emailRegex.test(formEmail)) {
      setEmailError("Please enter a valid email address (e.g., name@example.com).");
      isValid = false;
    } else {
      setEmailError("");
    }

    if (!formPass) {
      showToast("Please enter your passkey.", "warning");
      isValid = false;
    } else if (formPass.length < 4) {
      showToast("Your passkey must be at least 4 characters long for security.", "warning");
      isValid = false;
    }

    if (authMode === 'REGISTER') {
      if (!formName) {
        showToast("Please enter your full name for your profile.", "warning");
        isValid = false;
      }
      if (!formPhone) {
        showToast("A phone number is required for delivery contact.", "warning");
        isValid = false;
      } else if (formPhone.length < 10) {
        showToast("Please enter a valid phone number.", "warning");
        isValid = false;
      }
    }

    return isValid;
  };

  const handleAuth = async () => {
    if (!validateAuthForm()) return;

    if (lockoutUntil && Date.now() < lockoutUntil) {
      const remaining = Math.ceil((lockoutUntil - Date.now()) / 1000);
      return showToast(`Security Lockout: Too many failed attempts. Please wait ${remaining} seconds before trying again.`, 'error');
    }

    setIsAuthenticating(true);
    await new Promise(r => setTimeout(r, 1500));

    const emailKey = formEmail.toLowerCase().trim();

    if (authMode === 'REGISTER') {
      const existingCustomers = JSON.parse(localStorage.getItem('bfc_customers') || '{}');
      if (existingCustomers[emailKey] || MOCK_AUTH_DB[emailKey as keyof typeof MOCK_AUTH_DB]) {
        showToast("This email is already registered. Please log in instead.", "error");
        setIsAuthenticating(false);
        return;
      }

      const newCustomer: any = {
        name: formName,
        email: emailKey,
        pass: formPass,
        phone: formPhone,
        role: UserRole.CUSTOMER,
        loyaltyPoints: 50,
        tier: 'SILVER',
        referralCode: 'BFC-' + Math.random().toString(36).slice(7).toUpperCase(),
        profileImage: undefined
      };

      existingCustomers[emailKey] = newCustomer;
      localStorage.setItem('bfc_customers', JSON.stringify(existingCustomers));

      showToast("Account successfully created! Enjoy your 50 welcome loyalty points.", "success");
      setAuthMode('LOGIN');
      setIsAuthenticating(false);
      return;
    }

    const privileged = MOCK_AUTH_DB[emailKey as keyof typeof MOCK_AUTH_DB];
    const customers = JSON.parse(localStorage.getItem('bfc_customers') || '{}');
    const registeredCustomer = customers[emailKey];

    const match = privileged || registeredCustomer;

    if (match && match.pass === formPass) {
      setFailedAttempts(0);
      const user: User = {
        id: match.id || 'BFC-' + Math.random().toString(36).slice(7).toUpperCase(),
        name: match.name, 
        email: emailKey, 
        phone: match.phone || '01700-000000',
        role: match.role, 
        loyaltyPoints: match.loyaltyPoints || 0, 
        tier: match.tier || 'SILVER',
        wishlist: [], 
        referralCode: match.referralCode || 'N/A',
        profileImage: match.profileImage,
        sessionToken: generateSecureToken(match.role, emailKey)
      };
      localStorage.setItem('bfc_user_session', JSON.stringify(user));
      setCurrentUser(user);
      showToast(`Welcome back, ${user.name}! Accessing your BFC account.`, 'success');
      setView(user.role === UserRole.CUSTOMER ? 'HOME' : 'ADMIN');
    } else {
      const newAttempts = failedAttempts + 1;
      setFailedAttempts(newAttempts);
      if (newAttempts >= MAX_ATTEMPTS) {
        setLockoutUntil(Date.now() + LOCKOUT_TIME);
        showToast('Security Alert: Your account is temporarily locked due to multiple failed logins.', 'error', true);
      } else {
        showToast(`Incorrect email or passkey. You have ${MAX_ATTEMPTS - newAttempts} attempts remaining.`, 'error');
      }
    }
    setIsAuthenticating(false);
  };

  const handleSaveProfile = () => {
    if (!currentUser) return;
    if (!editName.trim()) {
      showToast("Name cannot be empty. Please enter your name.", "warning");
      return;
    }
    if (!editPhone.trim() || editPhone.length < 10) {
      showToast("Please enter a valid phone number for account updates.", "warning");
      return;
    }

    const updatedUser: User = {
      ...currentUser,
      name: editName,
      phone: editPhone,
      profileImage: editImage
    };

    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    setCurrentUser(updatedUser);

    const customers = JSON.parse(localStorage.getItem('bfc_customers') || '{}');
    if (customers[currentUser.email]) {
      customers[currentUser.email] = {
        ...customers[currentUser.email],
        name: editName,
        phone: editPhone,
        profileImage: editImage
      };
      localStorage.setItem('bfc_customers', JSON.stringify(customers));
    }

    setIsEditingProfile(false);
    showToast("Profile details successfully updated.", "success");
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        showToast("Invalid file type. Please select an image (JPG, PNG).", "error");
        return;
      }
      if (file.size > 2 * 1024 * 1024) {
        showToast("The image file is too large. Please select an image smaller than 2MB.", "error");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditImage(reader.result as string);
      };
      reader.onerror = () => {
        showToast("There was an error reading the file. Please try another image.", "error");
      };
      reader.readAsDataURL(file);
    }
  };

  const startEditing = () => {
    if (currentUser) {
      setEditName(currentUser.name);
      setEditPhone(currentUser.phone);
      setEditImage(currentUser.profileImage);
      setIsEditingProfile(true);
    }
  };

  const handleCheckout = async () => {
    if (!isOnline) {
      showToast("Payment Failed: You appear to be offline. Please reconnect to finalize your order.", "error");
      return;
    }
    if (cart.length === 0) {
      showToast("Your bag is empty! Add some delicious items before checking out.", "warning");
      return;
    }

    setIsCheckingOut(true);
    setCheckoutError(null);
    await new Promise(r => setTimeout(r, 2000));

    // Simulate payment failures for testing UX
    if (Math.random() < 0.2) {
      const errorMsg = "The transaction was declined by the payment gateway. Please verify your details or try a different method.";
      setCheckoutError(errorMsg);
      showToast(errorMsg, "error");
      setIsCheckingOut(false);
    } else {
      setCart([]);
      showToast("Transaction successful! Your order has been placed and is being prepared.", "success");
      setIsCheckingOut(false);
      setTimeout(() => setView('HOME'), 2000);
    }
  };

  const isPrivileged = currentUser && [UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF].includes(currentUser.role);

  if (view === 'ADMIN' && isPrivileged) {
    return (
      <AdminPanel 
        userRole={currentUser.role} 
        onLogout={() => { 
          localStorage.removeItem('bfc_user_session');
          setCurrentUser(null); 
          setView('HOME'); 
          showToast('You have been safely logged out of the admin node.', 'info');
        }}
        menuItems={menuItems}
        setMenuItems={setMenuItems}
        orders={allOrders}
        setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans selection:bg-red-100 overflow-x-hidden">
      {/* Dynamic Toast Notifications */}
      <div className="fixed top-12 right-8 z-[1000] space-y-4 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-start gap-4 px-6 py-5 rounded-3xl shadow-2xl border bg-white animate-slide-up border-gray-100 text-gray-800 ring-1 ring-black/5">
            <div className={`w-8 h-8 rounded-xl shrink-0 flex items-center justify-center text-xs ${
              t.type === 'error' ? 'bg-red-50 text-red-600' : 
              t.type === 'warning' ? 'bg-amber-50 text-amber-600' : 
              t.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'
            }`}>
              <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark' : t.type === 'warning' ? 'fa-triangle-exclamation' : t.type === 'success' ? 'fa-circle-check' : 'fa-info-circle'}`}></i>
            </div>
            <div className="flex-1">
              <p className="font-bold text-[11px] leading-relaxed">{t.message}</p>
            </div>
          </div>
        ))}
      </div>

      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-14 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-[15px] flex items-center justify-center text-white text-xl font-black shadow-xl group-hover:rotate-6 transition-transform duration-500">B</div>
          <h1 className="text-xl lg:text-2xl font-black text-red-600 tracking-tighter">BFC</h1>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 bg-gray-50 rounded-2xl flex items-center justify-center group transition-all hover:bg-red-50">
            <i className="fas fa-shopping-basket text-gray-600 group-hover:text-red-600"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[9px] w-5 h-5 rounded-full flex items-center justify-center ring-2 ring-white font-black">{cart.reduce((a,b)=>a+b.qty, 0)}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 rounded-2xl bg-gray-950 text-white font-black flex items-center justify-center shadow-lg border-2 border-white overflow-hidden">
               {currentUser.profileImage ? (
                 <img src={currentUser.profileImage} className="w-full h-full object-cover" />
               ) : (
                 currentUser.name.charAt(0)
               )}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl px-6" onClick={() => setView('LOGIN')}>Login</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-12 min-h-[80vh]">
