import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from './types';
import { Button } from './components/Button';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, BarChart, Bar
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 },
  { name: 'Sun', sales: 3800 },
  { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 },
  { name: 'Wed', sales: 6200 },
  { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

const CATEGORY_DATA = [
  { name: 'Biryani', value: 45, color: '#dc2626' },
  { name: 'Kebab', value: 25, color: '#ea580c' },
  { name: 'Curry', value: 20, color: '#f59e0b' },
  { name: 'Desserts', value: 10, color: '#10b981' },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const [activeTab, setActiveTab] = useState(userRole === UserRole.STAFF ? 'workplace' : 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [adminToast, setAdminToast] = useState<{msg: string, type: 'success' | 'error' | 'warning'} | null>(null);
  const [customers, setCustomers] = useState<any[]>([]);
  const [isExporting, setIsExporting] = useState(false);

  const showToast = useCallback((msg: string, type: 'success' | 'error' | 'warning') => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  // Sync Customers from LocalStorage
  useEffect(() => {
    const raw = localStorage.getItem('bfc_customers');
    if (raw) {
      const data = JSON.parse(raw);
      setCustomers(Object.values(data));
    }
  }, []);

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    const today = new Date().toISOString().split('T')[0];
    const todayOrders = orders.filter(o => o.createdAt.startsWith(today));

    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length,
      todayCount: todayOrders.length,
      todayRevenue: todayOrders.reduce((acc, o) => acc + o.total, 0)
    };
  }, [orders, menuItems]);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
