                        <img src={item.item.image} className="w-24 h-24 rounded-3xl object-cover shadow-lg" />
                        <div className="flex-1">
                           <h4 className="text-xl font-black text-gray-800 mb-1">{item.item.name}</h4>
                           <div className="flex items-center gap-4">
                              <button onClick={() => setCart(prev => prev.map((c, i) => i === idx ? {...c, qty: Math.max(1, c.qty-1)} : c))} className="w-8 h-8 rounded-xl bg-gray-50 flex items-center justify-center text-xs hover:bg-red-50 hover:text-red-600 transition-all font-black">-</button>
                              <span className="font-black text-lg w-6 text-center">{item.qty}</span>
                              <button onClick={() => setCart(prev => prev.map((c, i) => i === idx ? {...c, qty: c.qty+1} : c))} className="w-8 h-8 rounded-xl bg-gray-950 text-white flex items-center justify-center text-xs hover:bg-red-600 transition-all font-black">+</button>
                           </div>
                        </div>
                        <div className="text-right">
                           <p className="text-2xl font-black text-red-600 mb-2">৳{item.item.price * item.qty}</p>
                           <button onClick={() => setCart(prev => prev.filter((_, i) => i !== idx))} className="text-[8px] font-black text-gray-300 uppercase tracking-widest hover:text-red-600 transition-colors">Remove</button>
                        </div>
                     </div>
                   ))}
                 </div>

                 <div className="bg-white p-12 rounded-[50px] shadow-sm border border-gray-50">
