                       <span className="text-red-600">৳{cart.reduce((a,b)=>a+(b.item.price*b.qty), 0)}</span>
                    </div>
                    {checkoutError && <p className="text-red-600 font-bold mb-4 text-sm">{checkoutError}</p>}
