              </div>
            )}
          </div>
        )}
      </main>

      <ChatBot />

      {/* Mobile Bar */}
      <div className="lg:hidden fixed bottom-0 w-full bg-white/95 backdrop-blur-xl px-10 py-6 flex justify-between items-center z-[200] border-t border-gray-100 shadow-2xl rounded-t-[35px]">
         <button onClick={()=>setView('HOME')} className={`text-2xl transition-all ${view === 'HOME' ? 'text-red-600 scale-125' : 'text-gray-300'}`}><i className="fas fa-house"></i></button>
         <button onClick={()=>setView('MENU')} className={`text-2xl transition-all ${view === 'MENU' ? 'text-red-600 scale-125' : 'text-gray-300'}`}><i className="fas fa-utensils"></i></button>
         <button onClick={()=>setView('CART')} className={`text-2xl relative transition-all ${view === 'CART' ? 'text-red-600 scale-125' : 'text-gray-300'}`}>
