            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[8px] w-5 h-5 rounded-full flex items-center justify-center ring-2 ring-white font-black">{cart.length}</span>}
         </button>
         <button onClick={()=>currentUser ? setView('PROFILE') : setView('LOGIN')} className={`text-2xl transition-all ${['PROFILE', 'LOGIN'].includes(view) ? 'text-red-600 scale-125' : 'text-gray-300'}`}>
           {currentUser?.profileImage && ['PROFILE'].includes(view) ? (
             <img src={currentUser.profileImage} className="w-8 h-8 rounded-xl object-cover ring-2 ring-red-600" />
           ) : (
             <i className="fas fa-circle-user"></i>
           )}
         </button>
      </div>
    </div>
  );
};

