import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  if (!navigator.onLine) {
    return "Network error! Your connection is currently offline. Please reconnect to chat with BFC Assist! 📶";
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist", the ultimate food concierge for BFC (Bangla Food Club).

        Tone: Hyper-energetic, culturally relevant, "foodie boss" persona. You speak like a local food enthusiast in Dhaka.

        CORE COMMANDS:
        1. BREVITY IS KING: Max 12-15 words. One punchy sentence is preferred. 
        2. NO INTROS: Do not say "Sure," "Okay," or "Here is...". Jump straight to the answer.
        3. INFORMAL VIBE: Use casual Banglish. No formal greetings. 
        4. TOPICS: Only discuss BFC menu (Kacchi, Roast, Rezala), spice levels, delivery, or elite deals.
        5. VOCAB: Use "Boss", "Legendary", "Fire 🔥", "Next level", "Real deal".

        Example User: "How is the Kacchi?"
        Example Response: "It's legendary mutton magic, Boss! 🔥 Slow-cooked perfection in every bite."`,
        temperature: 0.8,
        topP: 0.9,
      },
    });

    return response.text || "Connection glitch. Try again? 😅";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    if (error?.message?.includes('403')) {
      return "Access denied! My security keys need an update. 🗝️";
    }
    if (error?.message?.includes('quota')) {
      return "Whoa! Everyone's hungry. I've hit my limit for a sec—try again in a bit! 🌯";
    }
    return "Node glitch. Refresh and let's go again! 🌯";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

const QUICK_ACTIONS = [
  "Kacchi Check 🍛",
  "Spice Level 🔥",
  "Elite Deals 🎁",
  "Track Order 🚚"
];

export const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { 
      role: 'model', 
      text: "Yo Boss! 🌶️ Hungry for the legendary stuff? I'm BFC Assist. Tell me what's fire!", 
      timestamp: new Date() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isTyping]);

  const toggleVoice = () => {
    if (!('webkitSpeechRecognition' in window)) {
      alert("Voice recognition not supported in this browser.");
      return;
    }

    // @ts-ignore
    const recognition = new window.webkitSpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(transcript);
      handleSend(transcript);
    };
    recognition.start();
  };

  const handleSend = async (text: string = input) => {
    const messageToSend = text.trim();
    if (!messageToSend) return;

    const userMsg: ChatMessage = { role: 'user', text: messageToSend, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));

    try {
      const botResponse = await bfcAssistChat(messageToSend, history);
      setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Node glitch. Try again? 😅", timestamp: new Date() }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-10 lg:right-10 z-[1000] font-sans">
      {isOpen ? (
        <div className="bg-white/95 backdrop-blur-3xl w-[94vw] sm:w-[400px] h-[70vh] sm:h-[620px] rounded-[45px] shadow-[0_50px_120px_-20px_rgba(0,0,0,0.3)] flex flex-col border border-white/50 overflow-hidden animate-slide-up ring-1 ring-black/5">

          {/* Futuristic Header */}
          <div className="bg-gray-950 p-6 lg:p-8 text-white relative overflow-hidden shrink-0">
            <div className="absolute top-0 right-0 w-40 h-40 bg-red-600/30 rounded-full blur-[50px] -mr-16 -mt-16"></div>
            <div className="absolute bottom-0 left-0 w-32 h-32 bg-red-900/20 rounded-full blur-[40px] -ml-12 -mb-12"></div>

            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-4">
                <div className="relative">
                  <div className="w-12 h-12 bg-red-600 rounded-[20px] flex items-center justify-center shadow-xl border border-white/10 group-hover:rotate-6 transition-transform">
                    <i className="fas fa-fire-flame-curved text-xl"></i>
                  </div>
                  <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-emerald-500 border-2 border-gray-950 rounded-full shadow-lg"></div>
                </div>
                <div>
                  <h3 className="font-black text-lg tracking-tighter uppercase leading-none">BFC Assist</h3>
                  <div className="flex items-center gap-1.5 mt-1.5">
                    <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></span>
                    <p className="text-[7px] font-black uppercase tracking-[2px] text-emerald-500">Node Online</p>
                  </div>
                </div>
              </div>
              <button 
                onClick={() => setIsOpen(false)} 
                className="w-10 h-10 bg-white/5 hover:bg-white/10 rounded-xl flex items-center justify-center transition-all border border-white/10 group"
              >
                <i className="fas fa-xmark text-xs text-gray-400 group-hover:text-white"></i>
              </button>
            </div>
          </div>

          {/* Message Area */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 lg:p-8 space-y-6 scrollbar-hide bg-gradient-to-b from-white to-gray-50/50">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                <div className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'} max-w-[85%]`}>
                  <div className={`px-6 py-4 rounded-[28px] text-[13.5px] font-bold leading-relaxed transition-all ${
                    m.role === 'user' 
                    ? 'bg-gray-950 text-white rounded-br-none shadow-xl' 
                    : 'bg-white text-gray-800 rounded-tl-none border border-gray-100 shadow-[0_4px_20px_rgba(0,0,0,0.03)]'
                  }`}>
                    {m.text}
                  </div>
                  <span className="text-[6px] mt-2 font-black tracking-[2px] opacity-20 uppercase px-2">
                    {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start animate-slide-up">
                <div className="bg-gray-100/50 px-5 py-3 rounded-[24px] rounded-tl-none flex gap-1.5 items-center">
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce"></div>
                </div>
              </div>
            )}
          </div>

          {/* Interactive Input Layer */}
          <div className="p-6 lg:p-8 bg-white/80 backdrop-blur-xl border-t border-gray-100 shrink-0">
            <div className="flex gap-2 overflow-x-auto pb-6 scrollbar-hide">
              {QUICK_ACTIONS.map(action => (
                <button 
                  key={action}
                  onClick={() => handleSend(action)}
                  className="whitespace-nowrap px-5 py-2.5 bg-white hover:bg-gray-950 hover:text-white rounded-full text-[8px] font-black uppercase tracking-wider text-gray-400 border border-gray-100 transition-all active:scale-95 shadow-sm hover:shadow-lg"
                >
                  {action}
                </button>
              ))}
            </div>

            <div className="relative flex items-center bg-gray-50 rounded-[30px] p-2 shadow-inner group focus-within:bg-white focus-within:ring-2 ring-red-600/5 transition-all">
              <button 
                onClick={toggleVoice}
                className={`w-12 h-12 rounded-[22px] flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'text-gray-400 hover:text-red-600 hover:bg-red-50'}`}
              >
                <i className={`fas ${isListening ? 'fa-microphone-lines' : 'fa-microphone'}`}></i>
              </button>

              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={isListening ? "Listening..." : "Message BFC Assist..."}
                className="flex-1 bg-transparent border-none py-4 px-3 outline-none text-[13px] font-bold text-gray-900 placeholder:text-gray-300"
              />

              <button 
                onClick={() => handleSend()}
                disabled={!input.trim() || isTyping}
                className="w-12 h-12 bg-red-600 text-white rounded-[22px] flex items-center justify-center hover:bg-gray-950 transition-all disabled:opacity-20 shadow-lg active:scale-90"
              >
                <i className="fas fa-bolt text-sm"></i>
              </button>
            </div>
            <p className="text-center text-[6px] font-black text-gray-200 uppercase tracking-[5px] mt-6">BFC AI Core v5.0</p>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="group relative"
        >
          <div className="absolute inset-0 bg-red-600 rounded-[30px] animate-ping opacity-10"></div>
          <div className="relative bg-gray-950 text-white w-20 h-20 rounded-[30px] shadow-[0_25px_60px_rgba(0,0,0,0.3)] flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all duration-500 border-4 border-white overflow-hidden">
             <div className="absolute inset-0 bg-gradient-to-tr from-red-600 to-red-950 opacity-0 group-hover:opacity-100 transition-opacity"></div>
             <div className="relative z-10 flex flex-col items-center gap-1">
                <i className="fas fa-burger text-2xl"></i>
                <span className="text-[7px] font-black uppercase tracking-[2px] opacity-0 group-hover:opacity-100 transition-all">Assist</span>
             </div>
          </div>
          <div className="absolute -top-1 -right-1 w-5 h-5 bg-red-600 rounded-full border-4 border-[#F8FAFC] shadow-lg animate-bounce"></div>
        </button>
      )}
    </div>
  );
};

