              <div className="p-8 lg:p-10 border-b flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                 <h3 className="text-xl lg:text-2xl font-black text-gray-900">Member Registry</h3>
                 <span className="text-[10px] font-black uppercase tracking-widest bg-red-600 text-white px-5 py-2 rounded-full">{customers.length} Members</span>
              </div>
              <div className="overflow-x-auto w-full">
                <table className="w-full text-left min-w-[700px]">
                  <thead>
                    <tr className="bg-gray-50 border-b border-gray-100">
                       <th className="px-8 lg:px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Identity</th>
                       <th className="px-8 lg:px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Communication</th>
                       <th className="px-8 lg:px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Loyalty Status</th>
                       <th className="px-8 lg:px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50">
                    {customers.map((c, idx) => (
                      <tr key={idx} className="hover:bg-gray-50/50 transition-all">
                        <td className="px-8 lg:px-10 py-6 lg:py-8 font-black text-gray-900">{c.name}</td>
                        <td className="px-8 lg:px-10 py-6 lg:py-8 text-sm text-gray-500 font-bold">{c.email}</td>
                        <td className="px-8 lg:px-10 py-6 lg:py-8">
                           <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest ${
                             c.tier === 'PLATINUM' ? 'bg-indigo-100 text-indigo-700' :
                             c.tier === 'GOLD' ? 'bg-amber-100 text-amber-700' : 'bg-gray-100 text-gray-500'
                           }`}>{c.tier}</span>
                        </td>
                        <td className="px-8 lg:px-10 py-6 lg:py-8">
                           <button onClick={() => showToast(`Audit for ${c.name}`, 'info')} className="text-gray-300 hover:text-red-600 transition-all p-2">
                             <i className="fas fa-ellipsis"></i>
                           </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

        </main>
      </div>
    </div>
  );
};

