import React, { useState, useEffect, useCallback, useRef } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
  persistent?: boolean;
}

const MOCK_AUTH_DB = {
  'admin@bfc.com': { pass: 'admin123', role: UserRole.ADMIN, name: 'Root Admin' },
  'manager@bfc.com': { pass: 'manager456', role: UserRole.MANAGER, name: 'Node Manager' },
  'staff@bfc.com': { pass: 'staff789', role: UserRole.STAFF, name: 'Logistics Staff' }
};

const MAX_ATTEMPTS = 3;
const LOCKOUT_TIME = 60000;

const generateSecureToken = (role: UserRole, email: string) => {
  const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
  const payload = btoa(JSON.stringify({
    role,
    email,
    iat: Date.now(),
    exp: Date.now() + 3600000 
  }));
  const signature = btoa(`bfc_master_secret_${email}_${role}_v2`);
  return `${header}.${payload}.${signature}`;
};

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE'>('HOME');
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [language, setLanguage] = useState<'EN' | 'BN'>('BN');
  const [selectedProduct, setSelectedProduct] = useState<MenuItem | null>(null);
  const [activeCategory, setActiveCategory] = useState('All');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Auth Form States
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [formName, setFormName] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [formImage, setFormImage] = useState<string | undefined>(undefined);
  const [emailError, setEmailError] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [failedAttempts, setFailedAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);

  // Profile Edit States (For existing users)
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editName, setEditName] = useState('');
  const [editPhone, setEditPhone] = useState('');
  const [editImage, setEditImage] = useState<string | undefined>(undefined);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const regFileInputRef = useRef<HTMLInputElement>(null);

  // Checkout States
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [checkoutError, setCheckoutError] = useState<string | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<Order['paymentMethod']>('BKASH');

  const showToast = useCallback((message: string, type: Toast['type'] = 'info', persistent: boolean = false) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, persistent }]);
    if (!persistent) {
      setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
    }
  }, []);

  useEffect(() => {
    const handleOnline = () => { 
      setIsOnline(true); 
      showToast('Connection Restored: All systems online.', 'success'); 
    };
    const handleOffline = () => { 
      setIsOnline(false); 
      showToast('Offline Mode: Check your connection for ordering.', 'error', true); 
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (savedUser) {
      try {
        const user = JSON.parse(savedUser) as User;
        if (user.sessionToken) {
          const parts = user.sessionToken.split('.');
          if (parts.length === 3) {
            const payload = JSON.parse(atob(parts[1]));
            if (payload.exp > Date.now()) {
              setCurrentUser(user);
            } else {
              localStorage.removeItem('bfc_user_session');
              showToast("Session expired. Please log in again.", "warning");
            }
          }
        }
      } catch (e) {
        localStorage.removeItem('bfc_user_session');
      }
    }
  }, [showToast]);

  const validateAuthForm = () => {
    let isValid = true;
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!formEmail) {
      setEmailError("Email is required.");
      isValid = false;
    } else if (!emailRegex.test(formEmail)) {
      setEmailError("Invalid email format.");
      isValid = false;
    } else {
      setEmailError("");
    }

    if (!formPass || formPass.length < 4) {
      showToast("Passkey must be at least 4 characters.", "warning");
      isValid = false;
    }

    if (authMode === 'REGISTER') {
      if (!formName) { showToast("Name is required.", "warning"); isValid = false; }
      if (!formPhone) { showToast("Phone is required.", "warning"); isValid = false; }
    }

    return isValid;
  };

  const handleAuth = async () => {
    if (!validateAuthForm()) return;

    if (lockoutUntil && Date.now() < lockoutUntil) {
      const remaining = Math.ceil((lockoutUntil - Date.now()) / 1000);
      return showToast(`Retry in ${remaining}s.`, 'error');
    }

    setIsAuthenticating(true);
    await new Promise(r => setTimeout(r, 1500));

    const emailKey = formEmail.toLowerCase().trim();

    if (authMode === 'REGISTER') {
      const existingCustomers = JSON.parse(localStorage.getItem('bfc_customers') || '{}');
      if (existingCustomers[emailKey] || MOCK_AUTH_DB[emailKey as keyof typeof MOCK_AUTH_DB]) {
        showToast("Email already exists.", "error");
        setIsAuthenticating(false);
        return;
      }

      const newCustomer: any = {
        name: formName,
        email: emailKey,
        pass: formPass,
        phone: formPhone,
        role: UserRole.CUSTOMER,
        loyaltyPoints: 50,
        tier: 'SILVER',
        referralCode: 'BFC-' + Math.random().toString(36).slice(7).toUpperCase(),
        profileImage: formImage
      };

      existingCustomers[emailKey] = newCustomer;
      localStorage.setItem('bfc_customers', JSON.stringify(existingCustomers));

      showToast("Registered successfully!", "success");
      setAuthMode('LOGIN');
      setIsAuthenticating(false);
      return;
    }

    const privileged = MOCK_AUTH_DB[emailKey as keyof typeof MOCK_AUTH_DB];
    const customers = JSON.parse(localStorage.getItem('bfc_customers') || '{}');
    const registeredCustomer = customers[emailKey];

    const match = privileged || registeredCustomer;

    if (match && match.pass === formPass) {
      setFailedAttempts(0);
      const user: User = {
        id: match.id || 'BFC-' + Math.random().toString(36).slice(7).toUpperCase(),
        name: match.name, 
        email: emailKey, 
        phone: match.phone || '01700-000000',
        role: match.role, 
        loyaltyPoints: match.loyaltyPoints || 0, 
        tier: match.tier || 'SILVER',
        wishlist: [], 
        referralCode: match.referralCode || 'N/A',
        profileImage: match.profileImage,
        sessionToken: generateSecureToken(match.role, emailKey)
      };
      localStorage.setItem('bfc_user_session', JSON.stringify(user));
      setCurrentUser(user);
      showToast(`Welcome back, ${user.name}!`, 'success');
      setView(user.role === UserRole.CUSTOMER ? 'HOME' : 'ADMIN');
    } else {
      const newAttempts = failedAttempts + 1;
      setFailedAttempts(newAttempts);
      if (newAttempts >= MAX_ATTEMPTS) {
        setLockoutUntil(Date.now() + LOCKOUT_TIME);
        showToast('Account locked temporarily.', 'error', true);
      } else {
        showToast(`Invalid credentials. ${MAX_ATTEMPTS - newAttempts} left.`, 'error');
      }
    }
    setIsAuthenticating(false);
  };

  const handleSaveProfile = () => {
    if (!currentUser) return;
    if (!editName.trim() || !editPhone.trim()) {
      showToast("Name and Phone cannot be empty.", "warning");
      return;
    }

    const updatedUser: User = {
      ...currentUser,
      name: editName,
      phone: editPhone,
      profileImage: editImage
    };

    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    setCurrentUser(updatedUser);

    const customers = JSON.parse(localStorage.getItem('bfc_customers') || '{}');
    if (customers[currentUser.email]) {
      customers[currentUser.email] = {
        ...customers[currentUser.email],
        name: editName,
        phone: editPhone,
        profileImage: editImage
      };
      localStorage.setItem('bfc_customers', JSON.stringify(customers));
    }

    setIsEditingProfile(false);
    showToast("Profile updated successfully.", "success");
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, isReg: boolean = false) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        showToast("Image too large (Max 2MB).", "error");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        if (isReg) setFormImage(reader.result as string);
        else setEditImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const startEditing = () => {
    if (currentUser) {
      setEditName(currentUser.name);
      setEditPhone(currentUser.phone);
      setEditImage(currentUser.profileImage);
      setIsEditingProfile(true);
    }
  };

  const handleCheckout = async () => {
    if (!isOnline) {
      showToast("Network Error: Reconnect to place order.", "error");
      return;
    }
    if (cart.length === 0) return;
    if (!currentUser) {
      showToast("Please login to proceed with the order.", "warning");
      setView('LOGIN');
      return;
    }

    setIsCheckingOut(true);
    setCheckoutError(null);
    await new Promise(r => setTimeout(r, 2000));

    // Simulate transaction processing
    if (paymentMethod !== 'COD' && Math.random() < 0.15) {
      setCheckoutError(`${paymentMethod} gateway is currently busy. Please try again or use another method.`);
      showToast("Transaction interrupted.", "error");
      setIsCheckingOut(false);
    } else {
      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser.id,
        customerName: currentUser.name,
        customerPhone: currentUser.phone,
        items: cart.map(c => ({
          menuId: c.item.id,
          quantity: c.qty,
          price: c.item.price,
          name: c.item.name
        })),
        total: cart.reduce((a, b) => a + (b.item.price * b.qty), 0),
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: paymentMethod === 'COD' ? 'UNPAID' : 'PAID',
        paymentMethod: paymentMethod,
        address: 'BFC Standard Delivery Node',
        deliveryZone: 'Dhaka Metropolitan',
        deliverySlot: 'ASAP',
        pointsEarned: Math.floor(cart.reduce((a, b) => a + (b.item.price * b.qty), 0) / 10),
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };

      setAllOrders(prev => [newOrder, ...prev]);
      setCart([]);
      showToast(`Order #${newOrder.id.slice(-4)} confirmed via ${paymentMethod}!`, "success");
      setIsCheckingOut(false);
      setTimeout(() => setView('HOME'), 1500);
    }
  };

  const isPrivileged = currentUser && [UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF].includes(currentUser.role);

  if (view === 'ADMIN' && isPrivileged) {
    return (
      <AdminPanel 
        userRole={currentUser.role} 
        onLogout={() => { 
          localStorage.removeItem('bfc_user_session');
          setCurrentUser(null); 
          setView('HOME'); 
          showToast('Logged out of Admin Node.', 'info');
        }}
        menuItems={menuItems}
        setMenuItems={setMenuItems}
        orders={allOrders}
        setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans selection:bg-red-100 overflow-x-hidden">
      {/* Toast Notifications */}
      <div className="fixed top-12 right-8 z-[1000] space-y-4 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-start gap-4 px-6 py-5 rounded-3xl shadow-2xl border bg-white animate-slide-up border-gray-100 text-gray-800 ring-1 ring-black/5">
            <div className={`w-8 h-8 rounded-xl shrink-0 flex items-center justify-center text-xs ${
              t.type === 'error' ? 'bg-red-50 text-red-600' : 
              t.type === 'warning' ? 'bg-amber-50 text-amber-600' : 
              t.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'
            }`}>
              <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark' : t.type === 'warning' ? 'fa-triangle-exclamation' : t.type === 'success' ? 'fa-circle-check' : 'fa-info-circle'}`}></i>
            </div>
            <div className="flex-1">
              <p className="font-bold text-[11px] leading-relaxed">{t.message}</p>
            </div>
          </div>
        ))}
      </div>

      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-14 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-[15px] flex items-center justify-center text-white text-xl font-black shadow-xl group-hover:rotate-6 transition-transform">B</div>
          <h1 className="text-xl lg:text-2xl font-black text-red-600 tracking-tighter">BFC</h1>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 bg-gray-50 rounded-2xl flex items-center justify-center transition-all hover:bg-red-50">
            <i className="fas fa-shopping-basket text-gray-600"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[9px] w-5 h-5 rounded-full flex items-center justify-center ring-2 ring-white font-black">{cart.reduce((a,b)=>a+b.qty, 0)}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 rounded-2xl bg-gray-950 text-white font-black flex items-center justify-center shadow-lg border-2 border-white overflow-hidden">
               {currentUser.profileImage ? (
                 <img src={currentUser.profileImage} className="w-full h-full object-cover" />
               ) : (
                 currentUser.name.charAt(0)
               )}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl px-6" onClick={() => setView('LOGIN')}>Login</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-12 min-h-[80vh]">
        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto mt-6 lg:mt-12 perspective-1000">
            <div className="bg-white/80 backdrop-blur-3xl p-10 lg:p-14 rounded-[50px] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.1)] border border-white animate-slide-up relative overflow-hidden">
               <div className="flex gap-2 p-1.5 bg-gray-100 rounded-3xl mb-10">
                  <button onClick={()=>setAuthMode('LOGIN')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${authMode === 'LOGIN' ? 'bg-white text-gray-900 shadow-md' : 'text-gray-400'}`}>Login</button>
                  <button onClick={()=>setAuthMode('REGISTER')} className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${authMode === 'REGISTER' ? 'bg-white text-gray-900 shadow-md' : 'text-gray-400'}`}>Register</button>
               </div>

               <div className="text-center mb-8">
                  <h2 className="text-3xl font-black text-gray-900 uppercase tracking-tight">{authMode === 'LOGIN' ? 'Welcome Back' : 'Join BFC'}</h2>
                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-[4px] mt-2">VIP Terminal Access</p>
               </div>

               <div className="space-y-5">
                  {authMode === 'REGISTER' && (
                    <div className="flex flex-col items-center mb-6">
                      <div className="w-24 h-24 bg-gray-100 rounded-[30px] flex items-center justify-center overflow-hidden border-4 border-white shadow-xl relative cursor-pointer group" onClick={() => regFileInputRef.current?.click()}>
                        {formImage ? (
                          <img src={formImage} className="w-full h-full object-cover" />
                        ) : (
                          <i className="fas fa-camera text-gray-300 text-2xl group-hover:scale-110 transition-transform"></i>
                        )}
                        <input type="file" ref={regFileInputRef} onChange={(e) => handleImageUpload(e, true)} className="hidden" accept="image/*" />
                      </div>
                      <p className="text-[8px] font-black uppercase tracking-widest text-gray-300 mt-3">Upload Profile Image</p>
                    </div>
                  )}

                  {authMode === 'REGISTER' && (
                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-400 tracking-[5px] block ml-6">Full Name</label>
                      <input 
                        type="text" 
                        value={formName} 
                        onChange={(e)=>setFormName(e.target.value)}
                        placeholder="John Doe"
                        className="w-full bg-gray-50 border-2 border-transparent focus:border-red-600/20 rounded-3xl px-8 py-4 font-bold outline-none transition-all"
                      />
                    </div>
                  )}

                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 tracking-[5px] block ml-6">Email</label>
                    <input 
                      type="email" 
                      value={formEmail} 
                      onChange={(e)=>{setFormEmail(e.target.value); setEmailError("");}}
                      placeholder="name@example.com"
                      className={`w-full bg-gray-50 border-2 rounded-3xl px-8 py-4 font-bold outline-none transition-all ${emailError ? 'border-red-400' : 'border-transparent focus:border-red-600/20'}`}
                    />
                  </div>

                  {authMode === 'REGISTER' && (
                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-400 tracking-[5px] block ml-6">Phone</label>
                      <input 
                        type="tel" 
                        value={formPhone} 
                        onChange={(e)=>setFormPhone(e.target.value)}
                        placeholder="01700000000"
                        className="w-full bg-gray-50 border-2 border-transparent focus:border-red-600/20 rounded-3xl px-8 py-4 font-bold outline-none transition-all"
                      />
                    </div>
                  )}

                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-gray-400 tracking-[5px] block ml-6">Passkey</label>
                    <div className="relative">
                      <input 
                        type={showPass ? 'text' : 'password'} 
                        value={formPass} 
                        onChange={(e)=>setFormPass(e.target.value)}
                        placeholder="••••••••"
                        className="w-full bg-gray-50 border-2 border-transparent focus:border-red-600/20 rounded-3xl px-8 py-4 font-bold outline-none transition-all"
                      />
                      <button onClick={()=>setShowPass(!showPass)} className="absolute right-6 top-1/2 -translate-y-1/2 text-gray-300">
                        <i className={`fas ${showPass ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                      </button>
                    </div>
                  </div>

                  <Button 
