const TrackerStep = ({ status, currentStatus, label }: { status: OrderStatus, currentStatus: OrderStatus, label: string }) => {
  const statusOrder = [OrderStatus.PENDING, OrderStatus.PREPARING, OrderStatus.READY, OrderStatus.ON_THE_WAY, OrderStatus.DELIVERED];
  const currentIndex = statusOrder.indexOf(currentStatus);
  const stepIndex = statusOrder.indexOf(status);
  const isCompleted = stepIndex < currentIndex;
  const isActive = stepIndex === currentIndex;

  return (
    <div className={`flex items-center gap-6 transition-all ${isActive ? 'scale-105' : ''}`}>
       <div className={`w-7 h-7 rounded-full flex items-center justify-center z-10 border-4 transition-all ${
         isCompleted ? 'bg-red-600 border-red-50 text-white' : 
         isActive ? 'bg-white border-red-600 text-red-600' : 'bg-gray-50 border-gray-100 text-gray-300'
       }`}>
          {isCompleted ? <i className="fas fa-check text-[10px]"></i> : <div className="w-1.5 h-1.5 rounded-full bg-current"></div>}
       </div>
       <div>
          <p className={`text-[10px] font-black uppercase tracking-widest ${isActive ? 'text-gray-950' : isCompleted ? 'text-red-600' : 'text-gray-300'}`}>{label}</p>
          {isActive && <p className="text-[7px] font-bold text-emerald-500 uppercase tracking-widest mt-0.5">Live Now</p>}
       </div>
    </div>
  );
};

