      {logo ? (
        <img src={logo} alt={label} className="w-8 h-8 sm:w-12 sm:h-12 object-contain" />
      ) : (
        <i className={`fas ${icon || 'fa-wallet'} ${color ? 'text-white' : 'text-gray-400'} text-sm sm:text-lg`}></i>
