  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { 
      role: 'model', 
      text: "Terminal Linked, Boss! 🌶️ BFC Assist ready. Looking for legendary insights or the daily fire? Tell me the mission!", 
      timestamp: new Date() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isTyping]);

  const toggleVoice = () => {
    if (!('webkitSpeechRecognition' in window)) {
      alert("Voice recognition not supported in this browser.");
      return;
    }

    // @ts-ignore
    const recognition = new window.webkitSpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(transcript);
      handleSend(transcript);
    };
    recognition.start();
  };

  const handleSend = async (text: string = input) => {
    const messageToSend = text.trim();
    if (!messageToSend) return;

    const userMsg: ChatMessage = { role: 'user', text: messageToSend, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));

    try {
      const botResponse = await bfcAssistChat(messageToSend, history);
      setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Node glitch. Try again? 😅", timestamp: new Date() }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[2000] font-sans">
      {isOpen ? (
        <div className="bg-white/90 backdrop-blur-2xl w-[92vw] sm:w-[420px] h-[75vh] sm:h-[680px] rounded-[48px] shadow-[0_60px_150px_-30px_rgba(0,0,0,0.4)] flex flex-col border border-white/40 overflow-hidden animate-slide-up ring-1 ring-black/5">

          {/* Elite Header */}
          <div className="bg-gray-950 p-8 text-white relative overflow-hidden shrink-0 border-b border-white/5">
            <div className="absolute top-0 right-0 w-48 h-48 bg-red-600/20 rounded-full blur-[60px] -mr-20 -mt-20"></div>
            <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-10"></div>

            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-5">
                <div className="relative">
                  <div className="w-14 h-14 bg-red-600 rounded-2xl flex items-center justify-center shadow-[0_0_20px_rgba(220,38,38,0.5)] border border-white/10 group-hover:scale-105 transition-transform">
                    <i className="fas fa-microchip text-2xl"></i>
                  </div>
                  <div className="absolute -bottom-1 -right-1 w-4.5 h-4.5 bg-emerald-500 border-4 border-gray-950 rounded-full"></div>
                </div>
                <div>
                  <h3 className="font-black text-xl tracking-tight uppercase leading-none">BFC Assist</h3>
                  <div className="flex items-center gap-2 mt-2">
                    <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_#10b981]"></span>
                    <p className="text-[8px] font-black uppercase tracking-[3px] text-emerald-500/80">Command Active</p>
                  </div>
                </div>
              </div>
              <button 
                onClick={() => setIsOpen(false)} 
                className="w-12 h-12 bg-white/5 hover:bg-white/10 rounded-2xl flex items-center justify-center transition-all border border-white/10 group active:scale-90"
              >
                <i className="fas fa-chevron-down text-sm text-gray-400 group-hover:text-white"></i>
              </button>
            </div>
          </div>

          {/* Chat Engine */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 lg:p-10 space-y-8 scrollbar-hide bg-[#FDFDFD] relative">
            <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/grid.png')] opacity-[0.03] pointer-events-none"></div>
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                <div className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'} max-w-[88%]`}>
                  <div className={`px-7 py-5 rounded-[32px] text-[14px] font-bold leading-relaxed shadow-sm transition-all ${
                    m.role === 'user' 
                    ? 'bg-gray-950 text-white rounded-br-none shadow-[0_10px_30px_-5px_rgba(0,0,0,0.2)]' 
                    : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'
                  }`}>
                    {m.text}
                  </div>
                  <span className="text-[7px] mt-3 font-black tracking-[3px] opacity-20 uppercase px-2">
                    {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start animate-slide-up">
                <div className="bg-gray-100/50 px-6 py-4 rounded-[28px] rounded-tl-none flex gap-2 items-center">
                  <div className="w-2 h-2 bg-red-600 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-2 h-2 bg-red-600 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-2 h-2 bg-red-600 rounded-full animate-bounce"></div>
                </div>
              </div>
            )}
          </div>

          {/* Pro Action Bar */}
          <div className="p-8 lg:p-10 bg-white/95 backdrop-blur-xl border-t border-gray-100 shrink-0">
            <div className="flex gap-3 overflow-x-auto pb-6 scrollbar-hide">
              {QUICK_ACTIONS.map(action => (
                <button 
                  key={action}
                  onClick={() => handleSend(action)}
                  className="whitespace-nowrap px-6 py-3 bg-white hover:bg-red-600 hover:text-white rounded-2xl text-[9px] font-black uppercase tracking-widest text-gray-400 border border-gray-100 transition-all active:scale-95 shadow-sm hover:shadow-xl hover:border-red-600"
                >
                  {action}
                </button>
              ))}
            </div>

            <div className="relative flex items-center bg-gray-50 rounded-[35px] p-2.5 shadow-inner ring-1 ring-black/5 focus-within:bg-white focus-within:ring-2 focus-within:ring-red-600/10 transition-all">
              <button 
                onClick={toggleVoice}
                className={`w-14 h-14 rounded-[28px] flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'text-gray-400 hover:text-red-600 hover:bg-red-50'}`}
              >
                <i className={`fas ${isListening ? 'fa-microphone-lines' : 'fa-microphone'} text-xl`}></i>
              </button>

              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={isListening ? "Listening..." : "Execute Command..."}
                className="flex-1 bg-transparent border-none py-5 px-4 outline-none text-[15px] font-bold text-gray-900 placeholder:text-gray-300"
              />

              <button 
                onClick={() => handleSend()}
                disabled={!input.trim() || isTyping}
                className="w-14 h-14 bg-red-600 text-white rounded-[28px] flex items-center justify-center hover:bg-gray-950 transition-all disabled:opacity-20 shadow-xl active:scale-90"
              >
                <i className="fas fa-paper-plane text-sm"></i>
              </button>
            </div>
            <div className="flex justify-between items-center mt-8">
              <p className="text-[7px] font-black text-gray-200 uppercase tracking-[6px]">BFC Intelligence v6.0</p>
              <div className="flex gap-1">
                <div className="w-1 h-1 bg-gray-200 rounded-full"></div>
                <div className="w-1 h-1 bg-gray-200 rounded-full"></div>
                <div className="w-1 h-1 bg-red-600 rounded-full animate-pulse"></div>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="group relative"
        >
          <div className="absolute inset-0 bg-red-600 rounded-[35px] animate-ping opacity-10"></div>
          <div className="relative bg-gray-950 text-white w-24 h-24 rounded-[35px] shadow-[0_30px_70px_rgba(0,0,0,0.4)] flex flex-col items-center justify-center hover:scale-110 active:scale-90 transition-all duration-500 border-4 border-white overflow-hidden">
