            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[9px] w-5 h-5 rounded-full flex items-center justify-center ring-2 ring-white font-black">{cart.reduce((a,b)=>a+b.qty, 0)}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 rounded-2xl bg-gray-950 text-white font-black flex items-center justify-center shadow-lg border-2 border-white overflow-hidden">
               {currentUser.profileImage ? (
                 <img src={currentUser.profileImage} className="w-full h-full object-cover" />
