                        <TrackerStep status={OrderStatus.PREPARING} currentStatus={selectedOrderToTrack.status} label="Cooking" />
                        <TrackerStep status={OrderStatus.ON_THE_WAY} currentStatus={selectedOrderToTrack.status} label="En Route" />
                        <TrackerStep status={OrderStatus.DELIVERED} currentStatus={selectedOrderToTrack.status} label="Arrived" />
