import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  if (!navigator.onLine) {
    return "Network error! Your connection is currently offline. Please reconnect to chat with BFC Assist! 📶";
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist", the ultimate food concierge for BFC (Bangla Food Club).

        Tone: Hyper-energetic, culturally relevant, "foodie boss" persona. You speak like a local food enthusiast in Dhaka.

        CORE COMMANDS:
        1. BREVITY IS KING: Max 12-15 words. One punchy sentence is preferred. 
        2. NO INTROS: Do not say "Sure," "Okay," or "Here is...". Jump straight to the answer.
        3. INFORMAL VIBE: Use casual Banglish. No formal greetings. 
        4. TOPICS: Only discuss BFC menu (Kacchi, Roast, Rezala), spice levels, delivery, or elite deals.
        5. VOCAB: Use "Boss", "Legendary", "Fire 🔥", "Next level", "Real deal".

        Example User: "How is the Kacchi?"
        Example Response: "It's legendary mutton magic, Boss! 🔥 Slow-cooked perfection in every bite."`,
        temperature: 0.8,
        topP: 0.9,
      },
    });

    return response.text || "Node glitch. I'm drawing a blank—ask me again, Boss! 😅";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    if (error?.message?.includes('403')) {
      return "Access denied! My security keys need an update. Contact BFC Support Node. 🗝️";
    }
    if (error?.message?.includes('quota')) {
      return "Whoa! Everyone's hungry. I've hit my processing limit—try again in a minute! 🌯";
    }
    return "Connection glitch! My signal just dropped. Let's try that one more time, Boss! 🌯";
  }
};

