import { ChatBot } from './ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, BarChart, Bar, LineChart, Line
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, growth: 12 },
  { name: 'Sun', sales: 3800, growth: -5 },
  { name: 'Mon', sales: 5200, growth: 22 },
  { name: 'Tue', sales: 4800, growth: 8 },
  { name: 'Wed', sales: 6200, growth: 15 },
  { name: 'Thu', sales: 5800, growth: 10 },
  { name: 'Fri', sales: 8500, growth: 35 },
];

const CATEGORY_DATA = [
  { name: 'Biryani', value: 45, color: '#dc2626' },
  { name: 'Kebab', value: 25, color: '#ea580c' },
  { name: 'Curry', value: 20, color: '#f59e0b' },
  { name: 'Desserts', value: 10, color: '#10b981' },
];

const CUSTOMER_BEHAVIOR = [
  { name: 'Dine-In Pref', value: 35 },
  { name: 'Delivery Loyalists', value: 45 },
  { name: 'Takeaway Only', value: 20 },
];

const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  [UserRole.ADMIN]: ['dashboard', 'orders', 'menu', 'inventory', 'customers', 'reports'],
  [UserRole.MANAGER]: ['dashboard', 'orders', 'menu', 'inventory', 'reports'],
  [UserRole.STAFF]: ['workplace', 'inventory'],
  [UserRole.CUSTOMER]: []
};

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const allowedTabs = ROLE_PERMISSIONS[userRole] || [];
  const [activeTab, setActiveTab] = useState(allowedTabs[0] || 'orders');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(3600);
  const [isExporting, setIsExporting] = useState<'PDF' | 'EXCEL' | null>(null);
  const [adminToast, setAdminToast] = useState<{msg: string, type: 'success' | 'error' | 'warning'} | null>(null);
  const [customers, setCustomers] = useState<any[]>([]);

  const showToast = useCallback((msg: string, type: 'success' | 'error' | 'warning') => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const verifyAccess = useCallback(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (!savedUser) return false;
    try {
      const user = JSON.parse(savedUser) as User;
      if (!user.sessionToken) return false;
      const parts = user.sessionToken.split('.');
      if (parts.length !== 3) return false;

      const payload = JSON.parse(atob(parts[1]));
      if (payload.exp < Date.now()) return false;
      if (payload.role !== userRole) return false;

      setSessionTimeLeft(Math.round((payload.exp - Date.now()) / 1000));
      return true;
    } catch { return false; }
  }, [userRole]);

  useEffect(() => {
    if (verifyAccess()) {
      setIsAuthorized(true);
    } else {
      onLogout();
    }
  }, [verifyAccess, onLogout]);

  useEffect(() => {
    const timer = setInterval(() => {
      if (!verifyAccess()) {
        showToast('Session Expired: Re-authenticating terminal...', 'error');
        setTimeout(onLogout, 2000);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [verifyAccess, onLogout, showToast]);

  useEffect(() => {
    const raw = localStorage.getItem('bfc_customers');
    if (raw) {
      const data = JSON.parse(raw);
      setCustomers(Object.values(data));
    }
  }, []);

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    const today = new Date().toISOString().split('T')[0];
    const todayOrders = orders.filter(o => o.createdAt.startsWith(today));

    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length,
      todayCount: todayOrders.length,
      todayRevenue: todayOrders.reduce((acc, o) => acc + o.total, 0)
    };
  }, [orders, menuItems]);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order #${orderId.slice(-4)} status set to ${newStatus}.`, 'success');
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) {
          showToast(`Action Blocked: Stock cannot drop below zero.`, 'warning');
          return item;
        }
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  const handleExportData = async (type: 'PDF' | 'EXCEL') => {
    if (!navigator.onLine) {
      showToast('Network Error: Export node requires active sync.', 'error');
      return;
    }
    setIsExporting(type);
    await new Promise(r => setTimeout(r, 2000));
    showToast(`Fiscal ${type} report generated. Check local downloads.`, 'success');
    setIsExporting(null);
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white p-10">
      <div className="relative w-20 h-20 mb-10">
        <div className="absolute inset-0 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center">
           <i className="fas fa-microchip text-red-600 animate-pulse"></i>
        </div>
      </div>
      <p className="text-[10px] font-black uppercase tracking-[8px] animate-pulse text-red-500 text-center">Encrypting Control Node...</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden font-sans relative">
      {adminToast && (
        <div className={`fixed top-8 left-1/2 -translate-x-1/2 z-[3000] px-8 py-4 rounded-3xl shadow-2xl border animate-slide-up flex items-center gap-4 ${
          adminToast.type === 'error' ? 'bg-red-600 border-red-400 text-white' : 
          adminToast.type === 'warning' ? 'bg-amber-500 border-amber-400 text-white' : 'bg-gray-900 border-white/10 text-white'
        }`}>
          <i className={`fas ${adminToast.type === 'success' ? 'fa-circle-check' : adminToast.type === 'error' ? 'fa-circle-xmark' : 'fa-triangle-exclamation'}`}></i>
          <span className="text-[10px] font-black uppercase tracking-widest">{adminToast.msg}</span>
        </div>
      )}

      {isSidebarOpen && (
        <div className="lg:hidden fixed inset-0 bg-black/40 backdrop-blur-sm z-[200]" onClick={() => setSidebarOpen(false)} />
      )}

      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 sm:w-80 bg-white border-r border-gray-100 transition-transform duration-500 ease-in-out transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 lg:p-10 flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-red-600 rounded-2xl flex items-center justify-center text-white shadow-xl rotate-3">
              <i className="fas fa-shield-halved"></i>
            </div>
            <h1 className="text-xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
          </div>
          <button className="lg:hidden text-gray-300" onClick={() => setSidebarOpen(false)}>
            <i className="fas fa-times text-xl"></i>
          </button>
        </div>

        <nav className="px-6 lg:px-8 space-y-2 max-h-[calc(100vh-250px)] overflow-y-auto scrollbar-hide">
          {allowedTabs.map(tab => (
             <SidebarBtn 
                key={tab} 
                active={activeTab === tab} 
                onClick={() => {setActiveTab(tab); setSidebarOpen(false);}} 
                icon={tab === 'dashboard' ? 'fa-chart-pie' : tab === 'orders' ? 'fa-list-check' : tab === 'menu' ? 'fa-utensils' : tab === 'inventory' ? 'fa-box-open' : tab === 'customers' ? 'fa-users' : tab === 'reports' ? 'fa-file-invoice-dollar' : 'fa-briefcase'} 
                label={tab} 
             />
          ))}
        </nav>

        <div className="absolute bottom-0 w-full p-8 border-t bg-white">
          <div className="flex items-center gap-4 mb-6">
            <div className="w-12 h-12 bg-gray-100 rounded-2xl flex items-center justify-center font-black text-gray-950">
              {userRole.charAt(0)}
            </div>
            <div className="min-w-0">
              <p className="text-[10px] font-black text-gray-950 uppercase tracking-widest truncate">{userRole}</p>
              <p className={`text-[8px] font-bold ${sessionTimeLeft < 300 ? 'text-red-600 animate-pulse' : 'text-gray-400'}`}>Session: {Math.floor(sessionTimeLeft / 60)}m {sessionTimeLeft % 60}s</p>
            </div>
          </div>
          <button onClick={onLogout} className="w-full flex items-center justify-center gap-3 py-4 rounded-2xl bg-gray-50 text-gray-400 font-black hover:bg-red-50 hover:text-red-600 transition-all uppercase tracking-[4px] text-[9px]">
            Terminate
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden">
        <header className="h-20 lg:h-24 bg-white/80 backdrop-blur-xl border-b flex items-center justify-between px-6 lg:px-12 shrink-0 z-50">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center text-gray-600">
              <i className="fas fa-bars"></i>
            </button>
            <h2 className="text-lg lg:text-2xl font-black text-gray-800 tracking-tight uppercase truncate">
              {activeTab} Terminal
            </h2>
          </div>
          <div className="hidden sm:block text-[9px] font-black text-gray-400 uppercase tracking-widest bg-gray-50 px-6 py-2 rounded-full border border-gray-100">
             NODE: DHAKA-CENTER-01
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-6 lg:p-12 space-y-10 lg:space-y-12 animate-slide-up scroll-smooth">
          {activeTab === 'dashboard' && (
            <div className="space-y-10 lg:space-y-12">
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6 lg:gap-8">
                <StatCard title="Total Revenue" value={`৳${stats.revenue.toLocaleString()}`} icon="fa-taka-sign" color="text-red-600" />
                <StatCard title="Orders Flow" value={stats.orderCount} icon="fa-box-archive" color="text-blue-600" />
                <StatCard title="Queue Pending" value={stats.pending} icon="fa-clock" color="text-purple-600" />
                <StatCard title="Stock Risks" value={stats.lowStock} icon="fa-warning" color="text-amber-500" />
              </div>
              <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 lg:gap-12">
                <div className="bg-white p-6 lg:p-10 rounded-[35px] lg:rounded-[50px] border border-gray-100 shadow-sm min-h-[400px]">
                   <h3 className="text-lg lg:text-xl font-black mb-8 lg:mb-10 uppercase tracking-tighter">Velocity Metrics</h3>
                   <div className="h-[300px] w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={ANALYTICS_DATA}>
                          <defs>
                            <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                              <stop offset="5%" stopColor="#dc2626" stopOpacity={0.1}/>
                              <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                            </linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                          <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                          <Tooltip />
                          <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={4} fill="url(#colorSales)" />
                        </AreaChart>
                      </ResponsiveContainer>
                   </div>
                </div>
                <div className="bg-white p-6 lg:p-10 rounded-[35px] lg:rounded-[50px] border border-gray-100 shadow-sm min-h-[400px]">
                   <h3 className="text-lg lg:text-xl font-black mb-8 lg:mb-10 uppercase tracking-tighter">Category Mix</h3>
                   <div className="h-[300px] w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={CATEGORY_DATA} innerRadius="60%" outerRadius="80%" paddingAngle={8} dataKey="value">
                            {CATEGORY_DATA.map((entry, idx) => <Cell key={idx} fill={entry.color} />)}
                          </Pie>
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                   </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'orders' && (
             <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
               {orders.map(o => (
                  <div key={o.id} className="bg-white p-8 rounded-[40px] border border-gray-50 flex flex-col gap-6 shadow-sm hover:shadow-xl transition-all">
                    <div className="flex justify-between items-start">
                       <div className="flex items-center gap-4">
                          <div className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center font-black">#{o.id.slice(-4)}</div>
                          <div>
                            <p className="font-black text-gray-800 text-lg leading-none mb-1">{o.customerName}</p>
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{o.paymentMethod}</p>
                          </div>
                       </div>
                       <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-100 text-emerald-700' : 'bg-red-50 text-red-600'}`}>{o.status}</span>
                    </div>
                    <select 
                      className="w-full bg-gray-950 text-white rounded-[22px] p-5 text-[10px] font-black uppercase tracking-widest outline-none shadow-xl cursor-pointer hover:bg-red-600 transition-all" 
                      value={o.status} 
                      onChange={(e) => handleUpdateStatus(o.id, e.target.value as OrderStatus)}
                    >
                      {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
               ))}
             </div>
          )}

          {activeTab === 'inventory' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-6 lg:gap-8">
               {menuItems.map(item => (
                 <div key={item.id} className="bg-white p-8 lg:p-10 rounded-[35px] lg:rounded-[45px] border border-gray-100 flex flex-col items-center text-center shadow-sm hover:shadow-xl transition-all h-full">
                    <img src={item.image} className="w-16 h-16 rounded-2xl object-cover mb-4 shadow-md" />
                    <h4 className="font-black text-gray-800 text-sm mb-1 truncate w-full px-2">{item.name}</h4>
                    <p className={`text-4xl font-black ${item.stock < 10 ? 'text-red-600' : 'text-gray-950'}`}>{item.stock}</p>
                    <div className="flex gap-2 mt-auto pt-6 w-full">
                       <button onClick={()=>handleUpdateStock(item.id, false)} className="flex-1 bg-gray-50 py-3 rounded-xl hover:bg-red-50 hover:text-red-600 transition-colors font-black text-xs">-</button>
                       <button onClick={()=>handleUpdateStock(item.id, true)} className="flex-1 bg-gray-900 text-white py-3 rounded-xl hover:bg-red-600 transition-colors font-black text-xs">+</button>
                    </div>
                 </div>
               ))}
            </div>
          )}

          {activeTab === 'customers' && (
            <div className="bg-white rounded-[35px] lg:rounded-[50px] border border-gray-100 shadow-sm overflow-hidden animate-slide-up">
              <div className="p-8 lg:p-10 border-b flex justify-between items-center bg-gray-50/30">
                 <h3 className="text-xl lg:text-2xl font-black text-gray-900">Member Registry</h3>
                 <span className="text-[10px] font-black uppercase tracking-widest bg-red-600 text-white px-5 py-2 rounded-full">{customers.length} Nodes</span>
              </div>
              <div className="overflow-x-auto w-full">
                <table className="w-full text-left min-w-[700px]">
                  <thead>
                    <tr className="bg-gray-50/80 border-b border-gray-100">
                       <th className="px-8 lg:px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Identity</th>
                       <th className="px-8 lg:px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Communication</th>
                       <th className="px-8 lg:px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Loyalty Status</th>
                       <th className="px-8 lg:px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50">
                    {customers.map((c, idx) => (
                      <tr key={idx} className="hover:bg-gray-50/50 transition-all">
                        <td className="px-8 lg:px-10 py-6 lg:py-8 font-black text-gray-900">{c.name}</td>
                        <td className="px-8 lg:px-10 py-6 lg:py-8 text-sm text-gray-500 font-bold">{c.email}</td>
                        <td className="px-8 lg:px-10 py-6 lg:py-8">
                           <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest ${
                             c.tier === 'PLATINUM' ? 'bg-indigo-100 text-indigo-700' :
                             c.tier === 'GOLD' ? 'bg-amber-100 text-amber-700' : 'bg-gray-100 text-gray-500'
                           }`}>{c.tier}</span>
                        </td>
                        <td className="px-8 lg:px-10 py-6 lg:py-8">
                           <button onClick={() => showToast(`Audit for ${c.name}`, 'info')} className="text-gray-300 hover:text-red-600 transition-all p-2">
                             <i className="fas fa-ellipsis"></i>
                           </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {activeTab === 'reports' && (
            <div className="space-y-12">
               <div className="bg-gray-950 p-8 lg:p-16 rounded-[40px] lg:rounded-[60px] text-white relative overflow-hidden group">
                  <div className="absolute top-0 right-0 w-96 h-96 bg-red-600/10 rounded-full blur-[100px] -mr-48 -mt-48 group-hover:bg-red-600/20 transition-all"></div>
                  <div className="relative z-10">
                     <div className="flex items-center gap-4 mb-6">
                        <span className="bg-red-600 px-4 py-1 rounded-full text-[8px] font-black uppercase tracking-widest">Confidential</span>
                        <span className="text-[10px] font-black opacity-40 uppercase tracking-widest">Fiscal Cycle Q3</span>
                     </div>
                     <h3 className="text-3xl lg:text-5xl font-black tracking-tighter mb-4">Fiscal Audit Terminal</h3>
                     <p className="text-gray-400 font-bold max-w-lg mb-12 text-sm leading-relaxed">
                        Nodes currently showing average 22% growth. Cross-referencing logistics throughput with behavior patterns.
                     </p>
                     <div className="flex flex-col sm:flex-row gap-4">
                        <button 
                          onClick={() => handleExportData('PDF')}
                          disabled={!!isExporting}
                          className="bg-white text-gray-950 px-10 py-5 rounded-3xl text-[10px] font-black uppercase tracking-widest hover:bg-red-600 hover:text-white transition-all disabled:opacity-50 flex items-center justify-center gap-3 shadow-xl active:scale-95"
                        >
                          {isExporting === 'PDF' ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-file-pdf"></i>}
                          {isExporting === 'PDF' ? 'Processing...' : 'Export PDF Audit'}
                        </button>
                        <button 
                          onClick={() => handleExportData('EXCEL')}
                          disabled={!!isExporting}
                          className="bg-gray-800 border-2 border-white/5 px-10 py-5 rounded-3xl text-[10px] font-black uppercase tracking-widest hover:border-white transition-all flex items-center justify-center gap-3 active:scale-95"
                        >
                          {isExporting === 'EXCEL' ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-file-excel"></i>}
                          {isExporting === 'EXCEL' ? 'Processing...' : 'Excel Ledger'}
                        </button>
                     </div>
                  </div>
               </div>

               <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-12">
                  <div className="bg-white p-8 lg:p-12 rounded-[40px] lg:rounded-[50px] border border-gray-100 shadow-sm">
                     <h4 className="text-xl font-black uppercase tracking-tighter mb-8">Behavior Intel</h4>
                     <div className="h-[300px] w-full">
                        <ResponsiveContainer width="100%" height="100%">
                           <PieChart>
                              <Pie data={CUSTOMER_BEHAVIOR} innerRadius="65%" outerRadius="85%" paddingAngle={10} dataKey="value" stroke="none">
                                 <Cell fill="#dc2626" />
                                 <Cell fill="#111827" />
                                 <Cell fill="#F97316" />
                              </Pie>
                              <Tooltip />
                           </PieChart>
                        </ResponsiveContainer>
                     </div>
                  </div>
                  <div className="bg-white p-8 lg:p-12 rounded-[40px] lg:rounded-[50px] border border-gray-100 shadow-sm">
                     <h4 className="text-xl font-black uppercase tracking-tighter mb-8">Growth Velocity</h4>
                     <div className="h-[300px] w-full">
                        <ResponsiveContainer width="100%" height="100%">
                           <LineChart data={ANALYTICS_DATA}>
                              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 9, fontWeight: 'bold'}} />
                              <YAxis hide />
                              <Tooltip cursor={{ stroke: '#dc2626', strokeWidth: 2 }} />
                              <Line type="stepAfter" dataKey="growth" stroke="#dc2626" strokeWidth={4} dot={{r: 6, fill: '#dc2626', strokeWidth: 4, stroke: '#fff'}} />
                           </LineChart>
                        </ResponsiveContainer>
                     </div>
                  </div>
               </div>
            </div>
          )}
        </main>
      </div>

      <ChatBot />
    </div>
  );
};

const SidebarBtn = ({ active, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-6 px-6 lg:px-8 py-4 lg:py-5 rounded-[22px] transition-all duration-300 border-2 ${
    active ? 'bg-red-600 border-red-600 text-white shadow-lg shadow-red-600/20' : 'bg-transparent border-transparent text-gray-400 hover:bg-red-50 hover:text-red-600'
  }`}>
    <div className="w-8 flex justify-center shrink-0">
      <i className={`fas ${icon} text-base lg:text-xl`}></i>
    </div>
    <span className="font-black text-[10px] uppercase tracking-[3px] whitespace-nowrap">{label}</span>
  </button>
);

const StatCard = ({ title, value, icon, color }: any) => (
  <div className="bg-white p-6 lg:p-10 rounded-[35px] lg:rounded-[45px] border border-gray-100 flex items-center gap-6 lg:gap-8 group hover:shadow-xl transition-all h-full min-w-0">
    <div className={`w-14 lg:w-16 h-14 lg:h-16 bg-gray-50 rounded-[20px] lg:rounded-[25px] flex items-center justify-center text-xl lg:text-2xl ${color} shadow-inner shrink-0 group-hover:scale-105 transition-transform`}><i className={`fas ${icon}`}></i></div>
    <div className="min-w-0 flex-1">
      <p className="text-[9px] lg:text-[10px] font-black text-gray-300 uppercase tracking-widest mb-1 truncate">{title}</p>
      <h4 className="text-2xl lg:text-3xl font-black text-gray-900 tracking-tighter truncate leading-none">{value}</h4>
    </div>
  </div>
);

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { Button } from './Button';
import { ChatBot } from './ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, BarChart, Bar, LineChart, Line
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, growth: 12 },
  { name: 'Sun', sales: 3800, growth: -5 },
  { name: 'Mon', sales: 5200, growth: 22 },
  { name: 'Tue', sales: 4800, growth: 8 },
  { name: 'Wed', sales: 6200, growth: 15 },
  { name: 'Thu', sales: 5800, growth: 10 },
  { name: 'Fri', sales: 8500, growth: 35 },
];

const CATEGORY_DATA = [
  { name: 'Biryani', value: 45, color: '#dc2626' },
  { name: 'Kebab', value: 25, color: '#ea580c' },
  { name: 'Curry', value: 20, color: '#f59e0b' },
  { name: 'Desserts', value: 10, color: '#10b981' },
];

const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  [UserRole.ADMIN]: ['dashboard', 'orders', 'menu', 'inventory', 'customers', 'reports'],
  [UserRole.MANAGER]: ['dashboard', 'orders', 'menu', 'inventory', 'reports'],
  [UserRole.STAFF]: ['orders', 'inventory'],
  [UserRole.CUSTOMER]: []
};

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const allowedTabs = ROLE_PERMISSIONS[userRole] || [];
  const [activeTab, setActiveTab] = useState(allowedTabs[0] || 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(3600);
  const [isExporting, setIsExporting] = useState<'PDF' | 'EXCEL' | null>(null);
  const [adminToast, setAdminToast] = useState<{msg: string, type: 'success' | 'error' | 'warning'} | null>(null);
  const [customers, setCustomers] = useState<any[]>([]);

  const showToast = useCallback((msg: string, type: 'success' | 'error' | 'warning') => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const verifyAccess = useCallback(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (!savedUser) return false;
    try {
      const user = JSON.parse(savedUser) as User;
      if (!user.sessionToken) return false;
      const parts = user.sessionToken.split('.');
      if (parts.length !== 3) return false;

      const payload = JSON.parse(atob(parts[1]));
      if (payload.exp < Date.now()) return false;
      if (payload.role !== userRole) return false;

      setSessionTimeLeft(Math.round((payload.exp - Date.now()) / 1000));
      return true;
    } catch { return false; }
  }, [userRole]);

  useEffect(() => {
    if (verifyAccess()) {
      setIsAuthorized(true);
    } else {
      onLogout();
    }
  }, [verifyAccess, onLogout]);

  useEffect(() => {
    const timer = setInterval(() => {
      if (!verifyAccess()) {
        showToast('Session Expired: Security lock engaged.', 'error');
        setTimeout(onLogout, 2000);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [verifyAccess, onLogout, showToast]);

  useEffect(() => {
    const raw = localStorage.getItem('bfc_customers');
    if (raw) {
      const data = JSON.parse(raw);
      setCustomers(Object.values(data));
    }
  }, []);

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    const today = new Date().toISOString().split('T')[0];
    const todayOrders = orders.filter(o => o.createdAt.startsWith(today));

    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length,
      todayCount: todayOrders.length,
      todayRevenue: todayOrders.reduce((acc, o) => acc + o.total, 0)
    };
  }, [orders, menuItems]);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order #${orderId.slice(-4)} status set to ${newStatus}.`, 'success');
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) {
          showToast(`Action Blocked: Minimum stock reached.`, 'warning');
          return item;
        }
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  const handleExportData = async (type: 'PDF' | 'EXCEL') => {
    if (!navigator.onLine) {
      showToast('Sync Error: Connection required for fiscal data export.', 'error');
      return;
    }
    setIsExporting(type);
    await new Promise(r => setTimeout(r, 2000));
    showToast(`${type} audit generated. Terminal sync successful.`, 'success');
    setIsExporting(null);
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white p-10">
      <div className="relative w-24 h-24 mb-10">
        <div className="absolute inset-0 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center">
           <i className="fas fa-microchip text-red-600 animate-pulse text-2xl"></i>
        </div>
      </div>
      <p className="text-[10px] font-black uppercase tracking-[10px] animate-pulse text-red-500 text-center">Authorization Pending...</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden font-sans relative">
      {adminToast && (
        <div className={`fixed top-8 left-1/2 -translate-x-1/2 z-[3000] px-8 py-5 rounded-3xl shadow-2xl border animate-slide-up flex items-center gap-5 ${
          adminToast.type === 'error' ? 'bg-red-600 border-red-400 text-white' : 
          adminToast.type === 'warning' ? 'bg-amber-500 border-amber-400 text-white' : 'bg-gray-900 border-white/10 text-white'
        }`}>
          <i className={`fas ${adminToast.type === 'success' ? 'fa-circle-check' : adminToast.type === 'error' ? 'fa-circle-xmark' : 'fa-triangle-exclamation'}`}></i>
          <span className="text-[11px] font-black uppercase tracking-widest">{adminToast.msg}</span>
        </div>
      )}

      {isSidebarOpen && (
        <div className="lg:hidden fixed inset-0 bg-black/40 backdrop-blur-sm z-[200]" onClick={() => setSidebarOpen(false)} />
      )}

      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 sm:w-80 bg-white border-r border-gray-100 transition-transform duration-500 ease-in-out transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 lg:p-12 flex items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white shadow-xl rotate-3">
              <i className="fas fa-shield-halved text-xl"></i>
            </div>
            <h1 className="text-xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
          </div>
          <button className="lg:hidden text-gray-300 hover:text-red-600 transition-colors" onClick={() => setSidebarOpen(false)}>
            <i className="fas fa-times text-xl"></i>
          </button>
        </div>

        <nav className="px-6 lg:px-8 space-y-2 max-h-[calc(100vh-250px)] overflow-y-auto scrollbar-hide">
          {allowedTabs.map(tab => (
             <SidebarBtn 
                key={tab} 
                active={activeTab === tab} 
                onClick={() => {setActiveTab(tab); setSidebarOpen(false);}} 
                icon={tab === 'dashboard' ? 'fa-chart-pie' : tab === 'orders' ? 'fa-list-check' : tab === 'menu' ? 'fa-utensils' : tab === 'inventory' ? 'fa-box-open' : tab === 'customers' ? 'fa-users' : 'fa-file-invoice-dollar'} 
                label={tab.toUpperCase()} 
             />
          ))}
        </nav>

        <div className="absolute bottom-0 w-full p-8 border-t bg-white">
          <div className="flex items-center gap-4 mb-6">
            <div className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center font-black">
              {userRole.charAt(0)}
            </div>
            <div className="min-w-0">
              <p className="text-[10px] font-black text-gray-950 uppercase tracking-widest truncate">{userRole}</p>
              <p className={`text-[8px] font-bold ${sessionTimeLeft < 300 ? 'text-red-600 animate-pulse' : 'text-gray-400'}`}>Session: {Math.floor(sessionTimeLeft / 60)}m left</p>
            </div>
          </div>
          <button onClick={onLogout} className="w-full flex items-center justify-center gap-3 py-4 rounded-2xl bg-gray-50 text-gray-400 font-black hover:bg-red-50 hover:text-red-600 transition-all uppercase tracking-[4px] text-[9px]">
            Terminate Node
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden">
        <header className="h-20 lg:h-24 bg-white/80 backdrop-blur-xl border-b flex items-center justify-between px-6 lg:px-12 shrink-0 z-50">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center text-gray-600">
              <i className="fas fa-bars"></i>
            </button>
            <h2 className="text-lg lg:text-2xl font-black text-gray-800 tracking-tight uppercase truncate">
              {activeTab} Interface
            </h2>
          </div>
          <div className="hidden sm:block text-[9px] font-black text-gray-400 uppercase tracking-widest bg-gray-50 px-6 py-2 rounded-full border border-gray-100">
             TERMINAL: BFC-HQ-01
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-6 lg:p-12 space-y-10 lg:space-y-12 animate-slide-up scroll-smooth">
          {activeTab === 'dashboard' && (
            <div className="space-y-10 lg:space-y-12">
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6 lg:gap-8">
                <StatCard title="Total Revenue" value={`৳${stats.revenue.toLocaleString()}`} icon="fa-taka-sign" color="text-red-600" />
                <StatCard title="Orders Flow" value={stats.orderCount} icon="fa-box-archive" color="text-blue-600" />
                <StatCard title="Queue Pending" value={stats.pending} icon="fa-clock" color="text-purple-600" />
                <StatCard title="Stock Risks" value={stats.lowStock} icon="fa-triangle-exclamation" color="text-amber-500" />
              </div>
              <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 lg:gap-12">
                <div className="bg-white p-6 lg:p-10 rounded-[35px] lg:rounded-[50px] border border-gray-100 shadow-sm min-h-[400px]">
                   <h3 className="text-lg lg:text-xl font-black mb-8 lg:mb-10 uppercase tracking-tighter">Growth Metrics</h3>
                   <div className="h-[300px] w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={ANALYTICS_DATA}>
                          <defs>
                            <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                              <stop offset="5%" stopColor="#dc2626" stopOpacity={0.1}/>
                              <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                            </linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                          <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                          <Tooltip />
                          <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={4} fill="url(#colorSales)" />
                        </AreaChart>
                      </ResponsiveContainer>
                   </div>
                </div>
                <div className="bg-white p-6 lg:p-10 rounded-[35px] lg:rounded-[50px] border border-gray-100 shadow-sm min-h-[400px]">
                   <h3 className="text-lg lg:text-xl font-black mb-8 lg:mb-10 uppercase tracking-tighter">Category Mix</h3>
                   <div className="h-[300px] w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={CATEGORY_DATA} innerRadius="60%" outerRadius="80%" paddingAngle={8} dataKey="value">
                            {CATEGORY_DATA.map((entry, idx) => <Cell key={idx} fill={entry.color} />)}
                          </Pie>
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                   </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'orders' && (
             <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
               {orders.map(o => (
                  <div key={o.id} className="bg-white p-8 rounded-[40px] border border-gray-50 flex flex-col gap-6 shadow-sm hover:shadow-xl transition-all">
                    <div className="flex justify-between items-start">
                       <div className="flex items-center gap-4">
                          <div className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center font-black">#{o.id.slice(-4)}</div>
                          <div>
                            <p className="font-black text-gray-800 text-lg leading-none mb-1">{o.customerName}</p>
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{o.paymentMethod}</p>
                          </div>
                       </div>
                       <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-100 text-emerald-700' : 'bg-red-50 text-red-600'}`}>{o.status}</span>
                    </div>
                    <div className="space-y-4">
                       <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Order Summary</p>
                       <ul className="space-y-2">
                          {o.items.map((it, idx) => (
                             <li key={idx} className="flex justify-between text-xs font-bold text-gray-700">
                                <span>{it.quantity}x {it.name}</span>
                                <span>৳{it.price * it.quantity}</span>
                             </li>
                          ))}
                       </ul>
                    </div>
                    <select 
                      className="w-full bg-gray-50 border-2 border-gray-100 rounded-[22px] p-5 text-[10px] font-black uppercase tracking-widest outline-none shadow-sm cursor-pointer hover:border-red-600 transition-all" 
                      value={o.status} 
                      onChange={(e) => handleUpdateStatus(o.id, e.target.value as OrderStatus)}
                    >
                      {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
               ))}
             </div>
          )}

          {activeTab === 'inventory' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-6 lg:gap-8">
               {menuItems.map(item => (
                 <div key={item.id} className="bg-white p-8 lg:p-10 rounded-[35px] lg:rounded-[45px] border border-gray-100 flex flex-col items-center text-center shadow-sm hover:shadow-xl transition-all h-full">
                    <div className="relative mb-6">
                       <img src={item.image} className="w-20 h-20 rounded-3xl object-cover shadow-md" />
                       {item.stock < 10 && <div className="absolute -top-2 -right-2 w-6 h-6 bg-red-600 text-white rounded-full flex items-center justify-center text-[10px]"><i className="fas fa-exclamation"></i></div>}
                    </div>
                    <h4 className="font-black text-gray-800 text-sm mb-1 truncate w-full px-2">{item.name}</h4>
                    <p className={`text-4xl font-black ${item.stock < 10 ? 'text-red-600' : 'text-gray-950'}`}>{item.stock}</p>
                    <div className="flex gap-2 mt-auto pt-6 w-full">
                       <button onClick={()=>handleUpdateStock(item.id, false)} className="flex-1 bg-gray-50 py-3 rounded-xl hover:bg-red-50 hover:text-red-600 transition-colors font-black text-xs">-</button>
                       <button onClick={()=>handleUpdateStock(item.id, true)} className="flex-1 bg-gray-900 text-white py-3 rounded-xl hover:bg-red-600 transition-colors font-black text-xs">+</button>
                    </div>
                 </div>
               ))}
            </div>
          )}

          {activeTab === 'customers' && (
            <div className="bg-white rounded-[35px] lg:rounded-[50px] border border-gray-100 shadow-sm overflow-hidden animate-slide-up">
              <div className="p-8 lg:p-10 border-b flex justify-between items-center bg-gray-50/30">
                 <h3 className="text-xl lg:text-2xl font-black text-gray-900">Member Registry</h3>
                 <span className="text-[10px] font-black uppercase tracking-widest bg-red-600 text-white px-5 py-2 rounded-full">{customers.length} Nodes</span>
              </div>
              <div className="overflow-x-auto w-full">
                <table className="w-full text-left min-w-[700px]">
                  <thead>
                    <tr className="bg-gray-50/80 border-b border-gray-100">
                       <th className="px-8 lg:px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Identity</th>
                       <th className="px-8 lg:px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Communication</th>
                       <th className="px-8 lg:px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Loyalty Status</th>
                       <th className="px-8 lg:px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50">
                    {customers.map((c, idx) => (
                      <tr key={idx} className="hover:bg-gray-50/50 transition-all">
                        <td className="px-8 lg:px-10 py-6 lg:py-8 font-black text-gray-900">{c.name}</td>
