                        </td>
                        <td className="px-8 lg:px-10 py-6 lg:py-8">
                           <button onClick={() => showToast(`Audit for ${c.name}`, 'success')} className="text-gray-300 hover:text-red-600 transition-all p-2">
                             <i className="fas fa-ellipsis"></i>
                           </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {activeTab === 'reports' && (
            <div className="space-y-12">
               <div className="bg-gray-950 p-8 lg:p-16 rounded-[40px] lg:rounded-[60px] text-white relative overflow-hidden group">
