                  </div>
                  <div className="bg-white p-8 lg:p-12 rounded-[40px] lg:rounded-[50px] border border-gray-100 shadow-sm">
                     <h4 className="text-xl font-black uppercase tracking-tighter mb-8">Quarterly Velocity</h4>
                     <div className="h-[300px] w-full">
                        <ResponsiveContainer width="100%" height="100%">
                           <LineChart data={ANALYTICS_DATA}>
                              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
