import React, { useState, useEffect, useCallback, useRef } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
  persistent?: boolean;
}

// Privileged Access Database
const MOCK_AUTH_DB: Record<string, { pass: string, role: UserRole, name: string, phone: string }> = {
  'admin@bfc.com': { pass: 'admin123', role: UserRole.ADMIN, name: 'BFC Root Admin', phone: '01711-000111' },
  'manager@bfc.com': { pass: 'manager456', role: UserRole.MANAGER, name: 'Regional Manager', phone: '01711-000222' },
  'staff@bfc.com': { pass: 'staff789', role: UserRole.STAFF, name: 'Floor Supervisor', phone: '01711-000333' }
};

const MAX_ATTEMPTS = 3;
const LOCKOUT_TIME = 60000;

// Simulate a secure JWT generation
const generateSecureToken = (role: UserRole, email: string) => {
  const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
  const payload = btoa(JSON.stringify({
    role,
    email,
    iat: Date.now(),
    exp: Date.now() + 3600000 // 1 hour expiry
  }));
  // Mock signature
  const signature = btoa(`bfc_master_secret_v3_${email}_${role}`);
  return `${header}.${payload}.${signature}`;
};

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE'>('HOME');
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [language, setLanguage] = useState<'EN' | 'BN'>('BN');
  const [activeCategory, setActiveCategory] = useState('All');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Tracking
  const [selectedOrderToTrack, setSelectedOrderToTrack] = useState<Order | null>(null);

  // Auth Form States
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [formName, setFormName] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [formImage, setFormImage] = useState<string | undefined>(undefined);
  const [formErrors, setFormErrors] = useState<Record<string, string>>({});
  const [showPass, setShowPass] = useState(false);
  const [failedAttempts, setFailedAttempts] = useState(0);
  const [lockoutUntil, setLockoutUntil] = useState<number | null>(null);

  // Profile Edit
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editName, setEditName] = useState('');
  const [editPhone, setEditPhone] = useState('');
  const [editImage, setEditImage] = useState<string | undefined>(undefined);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const regFileInputRef = useRef<HTMLInputElement>(null);

  // Checkout
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [checkoutError, setCheckoutError] = useState<string | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<Order['paymentMethod']>('BKASH');
  const [cardDetails, setCardDetails] = useState({ number: '', expiry: '', cvv: '', name: '' });

  const showToast = useCallback((message: string, type: Toast['type'] = 'info', persistent: boolean = false) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, persistent }]);
    if (!persistent) {
      setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 5000);
    }
  }, []);

  useEffect(() => {
    const handleOnline = () => { 
      setIsOnline(true); 
      showToast('Node Reconnected: Online operations resumed.', 'success'); 
    };
    const handleOffline = () => { 
      setIsOnline(false); 
      showToast('Network Lost: Switched to offline restricted mode.', 'error', true); 
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  useEffect(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (savedUser) {
      try {
        const user = JSON.parse(savedUser) as User;
        if (user.sessionToken) {
          const parts = user.sessionToken.split('.');
          if (parts.length === 3) {
            const payload = JSON.parse(atob(parts[1]));
            if (payload.exp > Date.now()) {
              setCurrentUser(user);
            } else {
              localStorage.removeItem('bfc_user_session');
              showToast("Session credentials expired. Re-authentication required.", "warning");
            }
          }
        }
      } catch (e) {
        localStorage.removeItem('bfc_user_session');
      }
    }
  }, [showToast]);

  const validateAuthForm = () => {
    const errors: Record<string, string> = {};
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phoneRegex = /^01[3-9]\d{8}$/;

    if (!formEmail) {
      errors.email = "Email identity is required.";
    } else if (!emailRegex.test(formEmail)) {
      errors.email = "Invalid format. Check your entry.";
    }

    if (!formPass) {
      errors.password = "Access key is required.";
    }

    if (authMode === 'REGISTER') {
      if (!formName.trim()) errors.name = "Full name required for member registry.";
      if (!formPhone) {
        errors.phone = "Mobile contact required for logistics.";
      } else if (!phoneRegex.test(formPhone)) {
        errors.phone = "Invalid format (e.g. 01712345678).";
      }
    }

    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleAuth = async () => {
    if (!validateAuthForm()) return;

    if (lockoutUntil && Date.now() < lockoutUntil) {
      const remaining = Math.ceil((lockoutUntil - Date.now()) / 1000);
      return showToast(`Terminal Locked: Security cooling down. Try in ${remaining}s.`, 'error');
    }

    setIsAuthenticating(true);
    await new Promise(r => setTimeout(r, 1500));

    const emailKey = formEmail.toLowerCase().trim();
    const privileged = MOCK_AUTH_DB[emailKey];
    const customers = JSON.parse(localStorage.getItem('bfc_customers') || '{}');
    const registeredCustomer = customers[emailKey];

    const match = privileged || registeredCustomer;

    if (match && match.pass === formPass) {
      setFailedAttempts(0);
      const user: User = {
        id: match.id || `BFC-${Math.random().toString(36).slice(7).toUpperCase()}`,
        name: match.name, 
        email: emailKey, 
        phone: match.phone || '01700-000000',
        role: match.role || UserRole.CUSTOMER, 
        loyaltyPoints: match.loyaltyPoints || 0, 
        tier: match.tier || 'SILVER',
        wishlist: [], 
        referralCode: match.referralCode || 'N/A',
        profileImage: match.profileImage,
        sessionToken: generateSecureToken(match.role || UserRole.CUSTOMER, emailKey)
      };

      localStorage.setItem('bfc_user_session', JSON.stringify(user));
      setCurrentUser(user);
      showToast(`Authorization Successful. Welcome, ${user.name}.`, 'success');

      if ([UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF].includes(user.role)) {
        setView('ADMIN');
      } else {
        setView('HOME');
      }
    } else {
      const newAttempts = failedAttempts + 1;
      setFailedAttempts(newAttempts);
      if (newAttempts >= MAX_ATTEMPTS) {
        setLockoutUntil(Date.now() + LOCKOUT_TIME);
        showToast('Maximum entry failures. Security lockout engaged for 60s.', 'error', true);
      } else {
        showToast(`Invalid credentials. Terminal access denied. (${MAX_ATTEMPTS - newAttempts} left)`, 'error');
      }
    }
    setIsAuthenticating(false);
  };

  const handleSaveProfile = () => {
    if (!currentUser) return;
    if (!editName.trim() || !editPhone.trim()) {
      showToast("Identity fields cannot be null.", "warning");
      return;
    }

    const updatedUser: User = {
      ...currentUser,
      name: editName,
      phone: editPhone,
      profileImage: editImage
    };

    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    setCurrentUser(updatedUser);
    setIsEditingProfile(false);
    showToast("Profile registry updated.", "success");
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, isReg: boolean = false) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        showToast("Payload too large. Max 2MB image allowed.", "error");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        if (isReg) setFormImage(reader.result as string);
        else setEditImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleCheckout = async () => {
    if (!isOnline) {
      showToast("Network Error: Payment gateway unreachable offline.", "error");
      return;
    }
    if (cart.length === 0) {
      showToast("Order payload empty. Cart discarded.", "warning");
      return;
    }
    if (!currentUser) {
      showToast("Identity verification required to initiate order.", "warning");
      setView('LOGIN');
      return;
    }

    if (paymentMethod === 'CARD') {
      if (cardDetails.number.length < 16 || !cardDetails.expiry || cardDetails.cvv.length < 3) {
        setCheckoutError("Card credentials incomplete. Authorization failed.");
        showToast("Invalid card metadata.", "warning");
        return;
      }
    }

    setIsCheckingOut(true);
    setCheckoutError(null);
    await new Promise(r => setTimeout(r, 2000));

    // 20% failure simulation
    if (paymentMethod !== 'COD' && Math.random() < 0.2) {
      setCheckoutError(`${paymentMethod} transaction rejected. Insufficient balance or gateway timeout.`);
      showToast("Payment Node Error.", "error");
      setIsCheckingOut(false);
    } else {
      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser.id,
        customerName: currentUser.name,
        customerPhone: currentUser.phone,
        items: cart.map(c => ({
          menuId: c.item.id,
          quantity: c.qty,
          price: c.item.price,
          name: c.item.name
        })),
        total: cart.reduce((a, b) => a + (b.item.price * b.qty), 0),
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: paymentMethod === 'COD' ? 'UNPAID' : 'PAID',
        paymentMethod: paymentMethod,
        address: 'Dhaka Metropolitan Node',
        deliveryZone: 'Central',
        deliverySlot: 'Standard',
        pointsEarned: Math.floor(cart.reduce((a, b) => a + (b.item.price * b.qty), 0) / 10),
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };

      setAllOrders(prev => [newOrder, ...prev]);
      setCart([]);
      showToast(`Order #${newOrder.id.slice(-4)} verified!`, "success");
      setIsCheckingOut(false);
      setSelectedOrderToTrack(newOrder);
      setTimeout(() => setView('TRACKING'), 800);
    }
  };

  const isPrivileged = currentUser && [UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF].includes(currentUser.role);

  if (view === 'ADMIN' && isPrivileged) {
    return (
      <AdminPanel 
        userRole={currentUser.role} 
        onLogout={() => { 
          localStorage.removeItem('bfc_user_session');
          setCurrentUser(null); 
          setView('HOME'); 
          showToast('Privileged session terminated.', 'info');
        }}
        menuItems={menuItems}
        setMenuItems={setMenuItems}
        orders={allOrders}
        setOrders={setAllOrders}
      />
    );
  }

  const currentUserOrders = currentUser ? allOrders.filter(o => o.customerId === currentUser.id) : [];

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans">
      {!isOnline && (
        <div className="bg-red-600 text-white text-[8px] font-black uppercase tracking-[4px] text-center py-1.5 sticky top-0 z-[100] animate-pulse">
           Offline Mode: Sync restricted
        </div>
      )}

      {/* Dynamic Toasts */}
      <div className="fixed top-12 right-6 z-[1000] space-y-3 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto flex items-center gap-4 px-6 py-4 rounded-2xl shadow-2xl border bg-white animate-slide-up border-gray-100 ring-1 ring-black/5">
            <div className={`w-8 h-8 rounded-xl shrink-0 flex items-center justify-center text-xs ${
              t.type === 'error' ? 'bg-red-50 text-red-600' : 
              t.type === 'warning' ? 'bg-amber-50 text-amber-600' : 
              t.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'
            }`}>
              <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark' : t.type === 'warning' ? 'fa-triangle-exclamation' : t.type === 'success' ? 'fa-circle-check' : 'fa-info-circle'}`}></i>
            </div>
            <p className="font-bold text-[10px] text-gray-800 uppercase tracking-tight">{t.message}</p>
          </div>
        ))}
      </div>

      <nav className={`sticky ${!isOnline ? 'top-8' : 'top-0'} z-50 glass-nav border-b border-gray-100 px-6 lg:px-12 py-4 flex justify-between items-center`}>
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-9 h-9 bg-red-600 rounded-xl flex items-center justify-center text-white text-lg font-black shadow-lg">B</div>
          <h1 className="text-xl font-black text-red-600 tracking-tighter">BFC</h1>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center transition-all hover:bg-red-50">
            <i className="fas fa-shopping-basket text-gray-600"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[8px] w-5 h-5 rounded-full flex items-center justify-center ring-2 ring-white font-black">{cart.reduce((a,b)=>a+b.qty,0)}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 rounded-xl bg-gray-950 text-white font-black flex items-center justify-center overflow-hidden border-2 border-white shadow-md">
               {currentUser.profileImage ? <img src={currentUser.profileImage} className="w-full h-full object-cover" /> : currentUser.name.charAt(0)}
            </button>
          ) : (
            <Button size="sm" className="rounded-xl px-5 py-2 text-xs" onClick={() => setView('LOGIN')}>Login</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-12 min-h-[70vh]">
        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto mt-6 lg:mt-12">
            <div className="bg-white p-10 lg:p-14 rounded-[45px] shadow-2xl border border-gray-100 animate-slide-up relative overflow-hidden">
               <div className="flex gap-2 p-1.5 bg-gray-50 rounded-2xl mb-10">
                  <button onClick={()=>{setAuthMode('LOGIN'); setFormErrors({});}} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${authMode === 'LOGIN' ? 'bg-white text-gray-950 shadow-sm' : 'text-gray-400'}`}>Login</button>
                  <button onClick={()=>{setAuthMode('REGISTER'); setFormErrors({});}} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${authMode === 'REGISTER' ? 'bg-white text-gray-950 shadow-sm' : 'text-gray-400'}`}>Register</button>
               </div>

               <div className="text-center mb-8">
                  <h2 className="text-3xl font-black text-gray-950 uppercase tracking-tight">{authMode === 'LOGIN' ? 'Access' : 'Join'} BFC</h2>
                  <p className="text-[8px] font-black text-gray-300 uppercase tracking-[4px] mt-2">Verified Terminal Access</p>
               </div>

               <div className="space-y-5">
                  {authMode === 'REGISTER' && (
                    <div className="flex flex-col items-center mb-6">
                      <div className="w-20 h-20 bg-gray-50 rounded-3xl flex items-center justify-center overflow-hidden border-4 border-white shadow-xl cursor-pointer group" onClick={() => regFileInputRef.current?.click()}>
                        {formImage ? <img src={formImage} className="w-full h-full object-cover" /> : <i className="fas fa-camera text-gray-300 text-xl"></i>}
                        <input type="file" ref={regFileInputRef} onChange={(e) => handleImageUpload(e, true)} className="hidden" accept="image/*" />
                      </div>
                    </div>
                  )}

                  {authMode === 'REGISTER' && (
                    <div className="space-y-1">
                      <label className="text-[8px] font-black uppercase text-gray-400 tracking-[3px] ml-4">Full Name</label>
                      <input 
                        type="text" 
                        value={formName} 
                        onChange={(e)=>{setFormName(e.target.value); setFormErrors(prev => ({...prev, name: ''}));}}
                        placeholder="John Doe"
                        className={`w-full bg-gray-50 border-2 rounded-2xl px-6 py-4 font-bold outline-none transition-all ${formErrors.name ? 'border-red-300' : 'border-transparent focus:border-red-600/10'}`}
                      />
                      {formErrors.name && <p className="text-[8px] text-red-600 font-bold ml-4">{formErrors.name}</p>}
                    </div>
                  )}

                  <div className="space-y-1">
                    <label className="text-[8px] font-black uppercase text-gray-400 tracking-[3px] ml-4">Email Identity</label>
                    <input 
                      type="email" 
                      value={formEmail} 
                      onChange={(e)=>{setFormEmail(e.target.value); setFormErrors(prev => ({...prev, email: ''}));}}
                      placeholder="name@example.com"
                      className={`w-full bg-gray-50 border-2 rounded-2xl px-6 py-4 font-bold outline-none transition-all ${formErrors.email ? 'border-red-300' : 'border-transparent focus:border-red-600/10'}`}
                    />
                    {formErrors.email && <p className="text-[8px] text-red-600 font-bold ml-4">{formErrors.email}</p>}
                  </div>

                  {authMode === 'REGISTER' && (
                    <div className="space-y-1">
                      <label className="text-[8px] font-black uppercase text-gray-400 tracking-[3px] ml-4">Phone Contact</label>
                      <input 
                        type="tel" 
                        value={formPhone} 
                        onChange={(e)=>{setFormPhone(e.target.value); setFormErrors(prev => ({...prev, phone: ''}));}}
                        placeholder="017xxxxxxxx"
                        className={`w-full bg-gray-50 border-2 rounded-2xl px-6 py-4 font-bold outline-none transition-all ${formErrors.phone ? 'border-red-300' : 'border-transparent focus:border-red-600/10'}`}
                      />
                      {formErrors.phone && <p className="text-[8px] text-red-600 font-bold ml-4">{formErrors.phone}</p>}
                    </div>
                  )}

                  <div className="space-y-1">
                    <label className="text-[8px] font-black uppercase text-gray-400 tracking-[3px] ml-4">Access Pass</label>
                    <div className="relative">
                      <input 
                        type={showPass ? 'text' : 'password'} 
                        value={formPass} 
                        onChange={(e)=>{setFormPass(e.target.value); setFormErrors(prev => ({...prev, password: ''}));}}
                        placeholder="••••••••"
                        className={`w-full bg-gray-50 border-2 rounded-2xl px-6 py-4 font-bold outline-none transition-all ${formErrors.password ? 'border-red-300' : 'border-transparent focus:border-red-600/10'}`}
                      />
                      <button onClick={()=>setShowPass(!showPass)} className="absolute right-6 top-1/2 -translate-y-1/2 text-gray-300">
                        <i className={`fas ${showPass ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                      </button>
                    </div>
                    {formErrors.password && <p className="text-[8px] text-red-600 font-bold ml-4">{formErrors.password}</p>}
                  </div>

                  <Button 
                    fullWidth 
                    size="lg" 
                    className="rounded-2xl py-4 shadow-xl mt-4 text-xs font-black uppercase tracking-widest" 
                    onClick={handleAuth}
                    disabled={isAuthenticating}
                  >
                    {isAuthenticating ? 'Processing...' : (authMode === 'LOGIN' ? 'Initiate Link' : 'Register Node')}
                  </Button>
               </div>
            </div>
          </div>
        )}

        {view === 'PROFILE' && currentUser && (
          <div className="max-w-4xl mx-auto animate-slide-up space-y-12">
            <div className="bg-white rounded-[45px] p-10 lg:p-16 shadow-sm border border-gray-100">
               <div className="flex flex-col lg:flex-row items-center gap-10">
                  <div className="relative">
                    <div className="w-32 h-32 bg-gray-900 rounded-[40px] flex items-center justify-center text-white text-4xl font-black shadow-2xl border-4 border-white overflow-hidden">
                       {isEditingProfile ? (editImage ? <img src={editImage} className="w-full h-full object-cover" /> : editName.charAt(0)) : (currentUser.profileImage ? <img src={currentUser.profileImage} className="w-full h-full object-cover" /> : currentUser.name.charAt(0))}
                    </div>
                    {isEditingProfile && (
                      <button onClick={() => fileInputRef.current?.click()} className="absolute -bottom-2 -right-2 w-10 h-10 bg-red-600 text-white rounded-xl flex items-center justify-center shadow-lg"><i className="fas fa-camera text-xs"></i></button>
                    )}
                    <input type="file" ref={fileInputRef} onChange={(e) => handleImageUpload(e, false)} className="hidden" accept="image/*" />
                  </div>
                  <div className="flex-1 text-center lg:text-left">
                     <span className="px-4 py-1.5 bg-red-600 text-white text-[8px] font-black uppercase tracking-[3px] rounded-full inline-block mb-3">{currentUser.tier} NODE</span>
                     {isEditingProfile ? (
                       <div className="space-y-3">
                          <input type="text" value={editName} onChange={(e)=>setEditName(e.target.value)} className="text-3xl font-black text-gray-950 bg-gray-50 px-4 py-2 rounded-xl w-full" />
                          <input type="tel" value={editPhone} onChange={(e)=>setEditPhone(e.target.value)} className="text-sm font-bold text-gray-400 bg-gray-50 px-4 py-2 rounded-xl w-full" />
                       </div>
                     ) : (
                       <>
