                    <h3 className="text-lg font-black text-gray-800 mb-8 uppercase tracking-widest">Payment Terminal</h3>
                    <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-10">
                       <PaymentOption id="BKASH" label="bKash" logo="https://freelogopng.com/images/all_img/1656234744bkash-logo-png.png" active={paymentMethod === 'BKASH'} onClick={() => {setPaymentMethod('BKASH'); setCheckoutError(null);}} />
                       <PaymentOption id="NAGAD" label="Nagad" logo="https://freelogopng.com/images/all_img/1679248787nagad-logo-png.png" active={paymentMethod === 'NAGAD'} onClick={() => {setPaymentMethod('NAGAD'); setCheckoutError(null);}} />
                       <PaymentOption id="CARD" label="Bank Card" active={paymentMethod === 'CARD'} onClick={() => {setPaymentMethod('CARD'); setCheckoutError(null);}} icon="fa-credit-card" color="bg-gray-800" />
                       <PaymentOption id="COD" label="Cash" active={paymentMethod === 'COD'} onClick={() => {setPaymentMethod('COD'); setCheckoutError(null);}} icon="fa-money-bill-wave" color="bg-emerald-600" />
                    </div>

                    {paymentMethod === 'CARD' && (
                      <div className="mb-8 animate-slide-up space-y-4 bg-gray-50 p-6 rounded-3xl border border-gray-100">
                        <input type="text" placeholder="CARD NUMBER" value={cardDetails.number} onChange={(e) => setCardDetails({...cardDetails, number: e.target.value.replace(/\D/g, '').substring(0, 16)})} className="w-full bg-white border-2 border-transparent focus:border-red-600/10 rounded-xl px-5 py-3.5 font-black text-xs outline-none" />
                        <div className="flex gap-4">
                           <input type="text" placeholder="MM/YY" value={cardDetails.expiry} onChange={(e) => setCardDetails({...cardDetails, expiry: e.target.value})} className="flex-1 bg-white border-2 border-transparent focus:border-red-600/10 rounded-xl px-5 py-3.5 font-black text-xs outline-none" />
                           <input type="password" placeholder="CVV" value={cardDetails.cvv} onChange={(e) => setCardDetails({...cardDetails, cvv: e.target.value.replace(/\D/g, '').substring(0, 3)})} className="flex-1 bg-white border-2 border-transparent focus:border-red-600/10 rounded-xl px-5 py-3.5 font-black text-xs outline-none" />
                        </div>
                      </div>
                    )}

                    <div className="flex justify-between items-center text-2xl font-black mb-8 border-t pt-8">
                       <span className="text-[10px] font-black text-gray-300 uppercase tracking-widest">Grand Total</span>
                       <span className="text-red-600">৳{cart.reduce((a,b)=>a+(b.item.price*b.qty), 0)}</span>
                    </div>

                    {checkoutError && (
                      <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-2xl flex gap-3 animate-slide-up">
                        <i className="fas fa-triangle-exclamation text-red-600 mt-1"></i>
                        <p className="text-red-700 font-bold text-[10px]">{checkoutError}</p>
                      </div>
                    )}

                    <Button fullWidth size="lg" className="rounded-2xl py-5 shadow-2xl text-xs font-black uppercase tracking-widest" onClick={handleCheckout} disabled={isCheckingOut}>
                      {isCheckingOut ? 'Processing Payload...' : paymentMethod === 'COD' ? 'Confirm Dispatch' : 'Initiate Payment'}
                    </Button>
                 </div>
              </div>
            )}
          </div>
        )}
      </main>

      <ChatBot />

      {/* Navigation Mobile Terminal */}
      <div className="lg:hidden fixed bottom-0 w-full bg-white/95 backdrop-blur-xl px-8 py-5 flex justify-between items-center z-[200] border-t border-gray-100 shadow-[0_-10px_40px_rgba(0,0,0,0.05)] rounded-t-[35px]">
         <button onClick={()=>setView('HOME')} className={`text-xl ${view === 'HOME' ? 'text-red-600' : 'text-gray-300'}`}><i className="fas fa-house"></i></button>
         <button onClick={()=>setView('MENU')} className={`text-xl ${view === 'MENU' ? 'text-red-600' : 'text-gray-300'}`}><i className="fas fa-utensils"></i></button>
         <button onClick={()=>setView('CART')} className={`text-xl relative ${view === 'CART' ? 'text-red-600' : 'text-gray-300'}`}>
            <i className="fas fa-shopping-bag"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[7px] w-4 h-4 rounded-full flex items-center justify-center font-black">{cart.length}</span>}
         </button>
         <button onClick={()=>currentUser ? setView('PROFILE') : setView('LOGIN')} className={`text-xl ${['PROFILE', 'LOGIN', 'ADMIN'].includes(view) ? 'text-red-600' : 'text-gray-300'}`}><i className="fas fa-circle-user"></i></button>
      </div>
    </div>
  );
};

