import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { Button } from './Button';
import { ChatBot } from './ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, LineChart, Line
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, growth: 12 },
  { name: 'Sun', sales: 3800, growth: -5 },
  { name: 'Mon', sales: 5200, growth: 22 },
  { name: 'Tue', sales: 4800, growth: 8 },
  { name: 'Wed', sales: 6200, growth: 15 },
  { name: 'Thu', sales: 5800, growth: 10 },
  { name: 'Fri', sales: 8500, growth: 35 },
];

const CATEGORY_DATA = [
  { name: 'Biryani', value: 45, color: '#dc2626' },
  { name: 'Kebab', value: 25, color: '#ea580c' },
  { name: 'Curry', value: 20, color: '#f59e0b' },
  { name: 'Desserts', value: 10, color: '#10b981' },
];

const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  [UserRole.ADMIN]: ['dashboard', 'orders', 'menu', 'inventory', 'customers', 'security'],
  [UserRole.MANAGER]: ['dashboard', 'orders', 'inventory', 'customers'],
  [UserRole.STAFF]: ['orders', 'inventory'],
  [UserRole.CUSTOMER]: []
};

// Mock audit logs for security
const MOCK_AUDIT_LOGS = [
  { time: '10:45 AM', event: 'Terminal Access', actor: 'Root Admin', status: 'SUCCESS' },
  { time: '09:30 AM', event: 'Inventory Audit', actor: 'Regional Manager', status: 'SUCCESS' },
  { time: '08:15 AM', event: 'Order Dispatch', actor: 'Staff User', status: 'SUCCESS' },
  { time: '07:50 AM', event: 'Unauthorized Access Blocked', actor: '192.168.1.4', status: 'FAILURE' },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const allowedTabs = ROLE_PERMISSIONS[userRole] || [];
  const [activeTab, setActiveTab] = useState(allowedTabs[0] || 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(3600);
  const [adminToast, setAdminToast] = useState<{msg: string, type: 'success' | 'error' | 'warning'} | null>(null);
  const [customers, setCustomers] = useState<any[]>([]);

  const showToast = useCallback((msg: string, type: 'success' | 'error' | 'warning') => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const verifyAccess = useCallback(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (!savedUser) return false;
    try {
      const user = JSON.parse(savedUser) as User;
      if (!user.sessionToken) return false;
      const parts = user.sessionToken.split('.');
      if (parts.length !== 3) return false;

      const payload = JSON.parse(atob(parts[1]));
      if (payload.exp < Date.now()) return false;
      if (payload.role !== userRole) return false;

      setSessionTimeLeft(Math.round((payload.exp - Date.now()) / 1000));
      return true;
    } catch { return false; }
  }, [userRole]);

  useEffect(() => {
    if (verifyAccess()) {
      setIsAuthorized(true);
    } else {
      onLogout();
    }
  }, [verifyAccess, onLogout]);

  useEffect(() => {
    const timer = setInterval(() => {
      if (!verifyAccess()) {
        showToast('Terminal session expired. Terminating access.', 'error');
        setTimeout(onLogout, 1500);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [verifyAccess, onLogout, showToast]);

  useEffect(() => {
    const raw = localStorage.getItem('bfc_customers');
    if (raw) {
      const data = JSON.parse(raw);
      setCustomers(Object.values(data));
    }
  }, []);

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length,
    };
  }, [orders, menuItems]);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order #${orderId.slice(-4)} updated to ${newStatus}.`, 'success');
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) {
          showToast(`Forbidden: Minimum stock threshold reached.`, 'warning');
          return item;
        }
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white">
      <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin mb-6"></div>
      <p className="text-[10px] font-black uppercase tracking-[8px] animate-pulse">Encrypting Node Access...</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden font-sans">
      {adminToast && (
        <div className={`fixed top-8 left-1/2 -translate-x-1/2 z-[3000] px-6 py-4 rounded-2xl shadow-2xl border animate-slide-up flex items-center gap-4 ${
          adminToast.type === 'error' ? 'bg-red-600 border-red-400 text-white' : 
          adminToast.type === 'warning' ? 'bg-amber-500 border-amber-400 text-white' : 'bg-gray-900 border-white/10 text-white'
        }`}>
          <i className={`fas ${adminToast.type === 'success' ? 'fa-circle-check' : adminToast.type === 'error' ? 'fa-circle-xmark' : 'fa-triangle-exclamation'}`}></i>
          <span className="text-[10px] font-black uppercase tracking-widest">{adminToast.msg}</span>
        </div>
      )}

      {/* Sidebar Terminal */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 bg-white border-r border-gray-100 transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white shadow-lg"><i className="fas fa-terminal"></i></div>
            <h1 className="text-xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
          </div>
          <button className="lg:hidden text-gray-300" onClick={() => setSidebarOpen(false)}><i className="fas fa-times"></i></button>
        </div>

        <nav className="px-6 space-y-1 overflow-y-auto h-[calc(100vh-250px)] scrollbar-hide">
          {allowedTabs.map(tab => (
             <SidebarBtn key={tab} active={activeTab === tab} onClick={() => {setActiveTab(tab); setSidebarOpen(false);}} icon={tab === 'dashboard' ? 'fa-chart-pie' : tab === 'orders' ? 'fa-list-check' : tab === 'menu' ? 'fa-utensils' : tab === 'inventory' ? 'fa-box-open' : tab === 'customers' ? 'fa-users' : 'fa-shield-halved'} label={tab} />
          ))}
        </nav>

        <div className="absolute bottom-0 w-full p-8 border-t bg-white">
          <div className="flex items-center gap-3 mb-6">
            <div className="w-10 h-10 bg-gray-950 text-white rounded-xl flex items-center justify-center font-black">{userRole.charAt(0)}</div>
            <div>
              <p className="text-[9px] font-black text-gray-950 uppercase tracking-widest">{userRole}</p>
              <p className="text-[7px] font-bold text-gray-400">SESSION: {Math.floor(sessionTimeLeft / 60)}m left</p>
            </div>
          </div>
          <button onClick={onLogout} className="w-full py-3 rounded-xl bg-gray-50 text-gray-400 font-black hover:bg-red-50 hover:text-red-600 transition-all uppercase tracking-[4px] text-[8px]">Terminate</button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-20 bg-white/80 backdrop-blur-xl border-b flex items-center justify-between px-8 shrink-0 z-50">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center text-gray-600"><i className="fas fa-bars"></i></button>
            <h2 className="text-lg font-black text-gray-800 tracking-tight uppercase">{activeTab} TERMINAL</h2>
          </div>
          <div className="text-[8px] font-black text-gray-400 uppercase tracking-widest bg-gray-50 px-4 py-2 rounded-full border">NODE: BFC-HQ-01</div>
        </header>

        <main className="flex-1 overflow-y-auto p-8 space-y-10 animate-slide-up scrollbar-hide">
          {activeTab === 'dashboard' && (
            <div className="space-y-10">
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6">
                <StatCard title="Revenue" value={`৳${stats.revenue.toLocaleString()}`} icon="fa-taka-sign" color="text-red-600" />
                <StatCard title="Active Orders" value={stats.orderCount} icon="fa-box" color="text-blue-600" />
                <StatCard title="Queue" value={stats.pending} icon="fa-clock" color="text-purple-600" />
                <StatCard title="Stock Risks" value={stats.lowStock} icon="fa-warning" color="text-amber-500" />
              </div>
              <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
                <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm min-h-[350px]">
                   <h3 className="text-sm font-black mb-8 uppercase tracking-widest">Growth Analytics</h3>
                   <div className="h-[250px] w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={ANALYTICS_DATA}>
                          <defs><linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#dc2626" stopOpacity={0.1}/><stop offset="95%" stopColor="#dc2626" stopOpacity={0}/></linearGradient></defs>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 9}} />
                          <YAxis axisLine={false} tickLine={false} tick={{fontSize: 9}} />
                          <Tooltip />
                          <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={3} fill="url(#colorSales)" />
                        </AreaChart>
                      </ResponsiveContainer>
                   </div>
                </div>
                <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm min-h-[350px]">
                   <h3 className="text-sm font-black mb-8 uppercase tracking-widest">Market Mix</h3>
                   <div className="h-[250px] w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={CATEGORY_DATA} innerRadius="60%" outerRadius="80%" paddingAngle={8} dataKey="value">
                            {CATEGORY_DATA.map((entry, idx) => <Cell key={idx} fill={entry.color} />)}
                          </Pie>
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                   </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'orders' && (
             <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
               {orders.map(o => (
                  <div key={o.id} className="bg-white p-6 rounded-3xl border border-gray-50 flex flex-col gap-5 hover:shadow-xl transition-all group">
                    <div className="flex justify-between items-start">
                       <div className="flex items-center gap-3">
                          <div className="w-10 h-10 bg-gray-950 text-white rounded-xl flex items-center justify-center font-black text-xs">#{o.id.slice(-4)}</div>
                          <div>
                            <p className="font-black text-gray-800 text-sm">{o.customerName}</p>
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest">{o.paymentMethod}</p>
                          </div>
                       </div>
                       <span className={`px-3 py-1.5 rounded-lg text-[8px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-100 text-emerald-700' : 'bg-red-50 text-red-600'}`}>{o.status}</span>
                    </div>
                    <select className="w-full bg-gray-50 border-2 border-transparent rounded-xl p-3 text-[9px] font-black uppercase tracking-widest outline-none focus:border-red-600/10 cursor-pointer" value={o.status} onChange={(e) => handleUpdateStatus(o.id, e.target.value as OrderStatus)}>
                      {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
               ))}
             </div>
          )}

          {activeTab === 'inventory' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-6">
               {menuItems.map(item => (
                 <div key={item.id} className="bg-white p-6 rounded-3xl border border-gray-100 flex flex-col items-center text-center shadow-sm">
                    <img src={item.image} className="w-16 h-16 rounded-xl object-cover mb-4" />
                    <h4 className="font-black text-gray-800 text-xs mb-1 truncate w-full">{item.name}</h4>
                    <p className={`text-3xl font-black ${item.stock < 10 ? 'text-red-600' : 'text-gray-950'}`}>{item.stock}</p>
                    <div className="flex gap-2 mt-4 w-full">
                       <button onClick={()=>handleUpdateStock(item.id, false)} className="flex-1 bg-gray-50 py-2 rounded-lg hover:bg-red-50 hover:text-red-600 transition-colors font-black text-[10px]">-</button>
                       <button onClick={()=>handleUpdateStock(item.id, true)} className="flex-1 bg-gray-900 text-white py-2 rounded-lg hover:bg-red-600 transition-colors font-black text-[10px]">+</button>
                    </div>
                 </div>
               ))}
            </div>
          )}

          {activeTab === 'customers' && (
            <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden">
              <div className="p-6 border-b flex justify-between items-center bg-gray-50/30">
                 <h3 className="font-black text-gray-900 text-sm uppercase">Member Registry</h3>
                 <span className="text-[8px] font-black uppercase tracking-widest bg-red-600 text-white px-3 py-1 rounded-full">{customers.length} Nodes</span>
              </div>
              <div className="overflow-x-auto w-full">
                <table className="w-full text-left min-w-[600px]">
                  <thead>
                    <tr className="bg-gray-50/80 border-b border-gray-100 text-[8px] font-black uppercase tracking-widest text-gray-400">
                       <th className="px-6 py-4">Identity</th>
                       <th className="px-6 py-4">Communication</th>
                       <th className="px-6 py-4">Loyalty Tier</th>
                       <th className="px-6 py-4">Registry Action</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50 text-xs font-bold text-gray-700">
                    {customers.map((c, idx) => (
                      <tr key={idx} className="hover:bg-gray-50/50 transition-all">
                        <td className="px-6 py-5 font-black text-gray-900">{c.name}</td>
                        <td className="px-6 py-5">{c.email}</td>
                        <td className="px-6 py-5"><span className="px-2 py-1 bg-gray-100 rounded text-[7px] font-black uppercase tracking-widest">{c.tier}</span></td>
                        <td className="px-6 py-5"><button onClick={() => showToast(`Auditing node: ${c.name}`, 'info')} className="text-gray-300 hover:text-red-600 transition-all"><i className="fas fa-search"></i></button></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {activeTab === 'security' && userRole === UserRole.ADMIN && (
            <div className="space-y-10">
               <div className="bg-gray-950 p-10 rounded-[40px] text-white relative overflow-hidden group">
                  <div className="absolute top-0 right-0 w-64 h-64 bg-red-600/10 rounded-full blur-[80px] -mr-32 -mt-32"></div>
                  <div className="relative z-10">
                     <h3 className="text-3xl font-black tracking-tighter mb-4">Terminal Audit Log</h3>
                     <p className="text-gray-400 font-bold max-w-lg mb-8 text-xs leading-relaxed">Cryptographic proof of all privileged terminal actions. System integrity is verified in real-time.</p>
                     <div className="space-y-4">
                        {MOCK_AUDIT_LOGS.map((log, idx) => (
                          <div key={idx} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5 hover:border-white/20 transition-all">
                             <div className="flex items-center gap-4">
                                <div className={`w-2 h-2 rounded-full ${log.status === 'SUCCESS' ? 'bg-emerald-500 shadow-[0_0_8px_#10b981]' : 'bg-red-500 shadow-[0_0_8px_#ef4444]'}`}></div>
                                <div>
                                   <p className="text-[10px] font-black uppercase tracking-tight">{log.event}</p>
                                   <p className="text-[8px] opacity-40 uppercase tracking-widest">{log.actor} • {log.time}</p>
                                </div>
                             </div>
                             <span className={`text-[8px] font-black uppercase tracking-widest px-2 py-1 rounded-md ${log.status === 'SUCCESS' ? 'text-emerald-500' : 'text-red-500'}`}>{log.status}</span>
                          </div>
                        ))}
                     </div>
                  </div>
               </div>
            </div>
          )}
        </main>
      </div>

      <ChatBot />
    </div>
  );
};

const SidebarBtn = ({ active, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-5 px-6 py-4 rounded-xl transition-all duration-300 border-2 ${
    active ? 'bg-red-600 border-red-600 text-white shadow-lg shadow-red-600/20' : 'bg-transparent border-transparent text-gray-400 hover:bg-red-50 hover:text-red-600'
  }`}>
    <div className="w-6 flex justify-center shrink-0"><i className={`fas ${icon} text-lg`}></i></div>
    <span className="font-black text-[9px] uppercase tracking-[2px]">{label}</span>
  </button>
);

const StatCard = ({ title, value, icon, color }: any) => (
  <div className="bg-white p-6 rounded-3xl border border-gray-100 flex items-center gap-5 group hover:shadow-lg transition-all">
    <div className={`w-12 h-12 bg-gray-50 rounded-xl flex items-center justify-center text-lg ${color} shadow-inner shrink-0 group-hover:scale-105 transition-transform`}><i className={`fas ${icon}`}></i></div>
    <div className="min-w-0">
      <p className="text-[8px] font-black text-gray-300 uppercase tracking-widest mb-0.5 truncate">{title}</p>
      <h4 className="text-xl font-black text-gray-900 tracking-tight truncate leading-none">{value}</h4>
    </div>
  </div>
);

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { Button } from './Button';
import { ChatBot } from './ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, LineChart, Line
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200, growth: 12 },
  { name: 'Sun', sales: 3800, growth: -5 },
  { name: 'Mon', sales: 5200, growth: 22 },
  { name: 'Tue', sales: 4800, growth: 8 },
  { name: 'Wed', sales: 6200, growth: 15 },
  { name: 'Thu', sales: 5800, growth: 10 },
  { name: 'Fri', sales: 8500, growth: 35 },
];

const CATEGORY_DATA = [
  { name: 'Biryani', value: 45, color: '#dc2626' },
  { name: 'Kebab', value: 25, color: '#ea580c' },
  { name: 'Curry', value: 20, color: '#f59e0b' },
  { name: 'Desserts', value: 10, color: '#10b981' },
];

const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  [UserRole.ADMIN]: ['dashboard', 'orders', 'menu', 'inventory', 'customers', 'security'],
  [UserRole.MANAGER]: ['dashboard', 'orders', 'inventory', 'customers'],
  [UserRole.STAFF]: ['orders', 'inventory'],
  [UserRole.CUSTOMER]: []
};

const MOCK_AUDIT_LOGS = [
  { time: '10:45 AM', event: 'Terminal Access', actor: 'Root Admin', status: 'SUCCESS' },
  { time: '09:30 AM', event: 'Inventory Audit', actor: 'Regional Manager', status: 'SUCCESS' },
  { time: '08:15 AM', event: 'Order Dispatch', actor: 'Staff User', status: 'SUCCESS' },
  { time: '07:50 AM', event: 'Unauthorized Access Blocked', actor: '192.168.1.4', status: 'FAILURE' },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const allowedTabs = ROLE_PERMISSIONS[userRole] || [];
  const [activeTab, setActiveTab] = useState(allowedTabs[0] || 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(3600);
  const [adminToast, setAdminToast] = useState<{msg: string, type: 'success' | 'error' | 'warning'} | null>(null);
  const [customers, setCustomers] = useState<any[]>([]);

  const showToast = useCallback((msg: string, type: 'success' | 'error' | 'warning') => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const verifyAccess = useCallback(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (!savedUser) return false;
    try {
      const user = JSON.parse(savedUser) as User;
      if (!user.sessionToken) return false;
      const parts = user.sessionToken.split('.');
      if (parts.length !== 3) return false;

      const payload = JSON.parse(atob(parts[1]));
      if (payload.exp < Date.now()) return false;
      if (payload.role !== userRole) return false;

      setSessionTimeLeft(Math.round((payload.exp - Date.now()) / 1000));
      return true;
    } catch { return false; }
  }, [userRole]);

  useEffect(() => {
    if (verifyAccess()) {
      setIsAuthorized(true);
    } else {
      onLogout();
    }
  }, [verifyAccess, onLogout]);

  useEffect(() => {
    const timer = setInterval(() => {
      if (!verifyAccess()) {
        showToast('Terminal session expired. Terminating access.', 'error');
        setTimeout(onLogout, 1500);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [verifyAccess, onLogout, showToast]);

  useEffect(() => {
    const raw = localStorage.getItem('bfc_customers');
    if (raw) {
      const data = JSON.parse(raw);
      setCustomers(Object.values(data));
    }
  }, []);

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length,
    };
  }, [orders, menuItems]);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order #${orderId.slice(-4)} updated to ${newStatus}.`, 'success');
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) {
          showToast(`Forbidden: Minimum stock threshold reached.`, 'warning');
          return item;
        }
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white p-6 text-center">
      <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin mb-6"></div>
      <p className="text-[10px] font-black uppercase tracking-[8px] animate-pulse">Encrypting Node Access...</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden font-sans">
      {adminToast && (
        <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-[3000] px-6 py-4 rounded-2xl shadow-2xl border animate-slide-up flex items-center gap-4 w-[90%] sm:w-auto max-w-md ${
          adminToast.type === 'error' ? 'bg-red-600 border-red-400 text-white' : 
          adminToast.type === 'warning' ? 'bg-amber-500 border-amber-400 text-white' : 'bg-gray-900 border-white/10 text-white'
        }`}>
          <i className={`fas ${adminToast.type === 'success' ? 'fa-circle-check' : adminToast.type === 'error' ? 'fa-circle-xmark' : 'fa-triangle-exclamation'}`}></i>
          <span className="text-[10px] font-black uppercase tracking-widest leading-snug">{adminToast.msg}</span>
        </div>
      )}

      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[200] lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar Terminal */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 bg-white border-r border-gray-100 transition-transform duration-300 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 flex items-center justify-between border-b border-gray-50">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white shadow-lg"><i className="fas fa-terminal"></i></div>
            <h1 className="text-xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
          </div>
          <button className="lg:hidden w-10 h-10 flex items-center justify-center text-gray-300 hover:text-red-600 transition-colors" onClick={() => setSidebarOpen(false)}>
            <i className="fas fa-times text-xl"></i>
          </button>
        </div>

        <nav className="p-6 space-y-1 overflow-y-auto h-[calc(100vh-280px)] scrollbar-hide">
          {allowedTabs.map(tab => (
             <SidebarBtn key={tab} active={activeTab === tab} onClick={() => {setActiveTab(tab); setSidebarOpen(false);}} icon={tab === 'dashboard' ? 'fa-chart-pie' : tab === 'orders' ? 'fa-list-check' : tab === 'menu' ? 'fa-utensils' : tab === 'inventory' ? 'fa-box-open' : tab === 'customers' ? 'fa-users' : 'fa-shield-halved'} label={tab} />
          ))}
        </nav>

        <div className="absolute bottom-0 w-full p-8 border-t bg-white">
          <div className="flex items-center gap-3 mb-6 bg-gray-50 p-4 rounded-2xl">
            <div className="w-10 h-10 bg-gray-950 text-white rounded-xl flex items-center justify-center font-black shrink-0">{userRole.charAt(0)}</div>
            <div className="min-w-0">
              <p className="text-[9px] font-black text-gray-950 uppercase tracking-widest truncate">{userRole}</p>
              <p className="text-[7px] font-bold text-gray-400">SESSION: {Math.floor(sessionTimeLeft / 60)}m</p>
            </div>
          </div>
          <button onClick={onLogout} className="w-full py-4 rounded-xl bg-red-50 text-red-600 font-black hover:bg-red-600 hover:text-white transition-all uppercase tracking-[4px] text-[8px] border border-red-100">Terminate</button>
        </div>
      </aside>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-20 bg-white/80 backdrop-blur-xl border-b flex items-center justify-between px-6 lg:px-12 shrink-0 z-50">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden w-10 h-10 bg-gray-100 rounded-xl flex items-center justify-center text-gray-600 hover:bg-gray-200 transition-colors">
              <i className="fas fa-bars"></i>
            </button>
            <h2 className="text-base lg:text-xl font-black text-gray-800 tracking-tight uppercase truncate">
              {activeTab} Interface
            </h2>
          </div>
          <div className="hidden sm:flex items-center gap-3 text-[8px] font-black text-gray-400 uppercase tracking-widest bg-gray-50 px-4 py-2 rounded-full border">
            <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
            Node: BFC-HQ-01
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-6 lg:p-12 space-y-10 animate-slide-up scrollbar-hide scroll-smooth">
          {activeTab === 'dashboard' && (
            <div className="space-y-10">
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6">
                <StatCard title="Revenue" value={`৳${stats.revenue.toLocaleString()}`} icon="fa-taka-sign" color="text-red-600" />
                <StatCard title="Active Orders" value={stats.orderCount} icon="fa-box" color="text-blue-600" />
                <StatCard title="Queue" value={stats.pending} icon="fa-clock" color="text-purple-600" />
                <StatCard title="Stock Risks" value={stats.lowStock} icon="fa-triangle-exclamation" color="text-amber-500" />
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 lg:gap-12">
                <div className="bg-white p-6 lg:p-10 rounded-[40px] border border-gray-100 shadow-sm min-h-[400px]">
                   <h3 className="text-xs font-black mb-8 uppercase tracking-[3px] text-gray-400">Growth Velocity</h3>
                   <div className="h-[300px] w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={ANALYTICS_DATA}>
                          <defs>
                            <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                              <stop offset="5%" stopColor="#dc2626" stopOpacity={0.1}/>
                              <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                            </linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold'}} />
                          <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold'}} />
                          <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 40px rgba(0,0,0,0.1)' }} />
                          <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={4} fill="url(#colorSales)" />
                        </AreaChart>
                      </ResponsiveContainer>
                   </div>
                </div>

                <div className="bg-white p-6 lg:p-10 rounded-[40px] border border-gray-100 shadow-sm min-h-[400px]">
                   <h3 className="text-xs font-black mb-8 uppercase tracking-[3px] text-gray-400">Category Distribution</h3>
                   <div className="h-[300px] w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie 
                            data={CATEGORY_DATA} 
                            innerRadius="65%" 
                            outerRadius="85%" 
                            paddingAngle={8} 
                            dataKey="value"
                            stroke="none"
                          >
                            {CATEGORY_DATA.map((entry, idx) => <Cell key={idx} fill={entry.color} />)}
                          </Pie>
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                   </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'orders' && (
             <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 lg:gap-8">
               {orders.length === 0 ? (
                 <div className="col-span-full py-20 text-center bg-white rounded-[40px] border border-gray-100">
                    <i className="fas fa-inbox text-5xl text-gray-100 mb-6"></i>
                    <p className="font-black text-gray-300 uppercase tracking-widest text-xs">No active orders in queue</p>
                 </div>
               ) : (
                 orders.map(o => (
                  <div key={o.id} className="bg-white p-6 lg:p-8 rounded-[35px] border border-gray-50 flex flex-col gap-6 hover:shadow-2xl transition-all group hover:-translate-y-1">
                    <div className="flex justify-between items-start">
                       <div className="flex items-center gap-4">
                          <div className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center font-black text-xs shadow-xl">#{o.id.slice(-4)}</div>
                          <div className="min-w-0">
                            <p className="font-black text-gray-800 text-sm truncate">{o.customerName}</p>
                            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">{o.paymentMethod}</p>
                          </div>
                       </div>
                       <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-100 text-emerald-700' : 'bg-red-50 text-red-600'}`}>
                         {o.status}
                       </span>
                    </div>

                    <div className="bg-gray-50 rounded-2xl p-4 space-y-2">
                       {o.items.map((it, idx) => (
                         <div key={idx} className="flex justify-between text-[10px] font-bold text-gray-600">
                            <span>{it.quantity}x {it.name}</span>
                            <span>৳{it.price * it.quantity}</span>
                         </div>
                       ))}
                    </div>

                    <select 
                      className="w-full bg-white border-2 border-gray-100 rounded-2xl p-4 text-[10px] font-black uppercase tracking-widest outline-none focus:border-red-600 transition-all cursor-pointer shadow-sm" 
                      value={o.status} 
                      onChange={(e) => handleUpdateStatus(o.id, e.target.value as OrderStatus)}
                    >
                      {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
                 ))
               )}
             </div>
          )}

          {activeTab === 'inventory' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-6 lg:gap-8">
               {menuItems.map(item => (
                 <div key={item.id} className="bg-white p-6 lg:p-8 rounded-[40px] border border-gray-100 flex flex-col items-center text-center shadow-sm hover:shadow-xl transition-all group">
                    <div className="relative mb-6">
                      <img src={item.image} className="w-20 h-20 rounded-3xl object-cover shadow-lg group-hover:scale-110 transition-transform duration-500" alt={item.name} />
                      {item.stock < 10 && <div className="absolute -top-2 -right-2 w-6 h-6 bg-red-600 text-white rounded-full flex items-center justify-center text-[10px] ring-4 ring-white"><i className="fas fa-exclamation"></i></div>}
                    </div>
                    <h4 className="font-black text-gray-800 text-xs mb-2 truncate w-full px-4">{item.name}</h4>
                    <p className={`text-4xl font-black mb-6 ${item.stock < 10 ? 'text-red-600' : 'text-gray-950'}`}>{item.stock}</p>
                    <div className="flex gap-2 w-full">
                       <button onClick={()=>handleUpdateStock(item.id, false)} className="flex-1 bg-gray-50 py-3 rounded-xl hover:bg-red-50 hover:text-red-600 transition-colors font-black text-sm">-</button>
                       <button onClick={()=>handleUpdateStock(item.id, true)} className="flex-1 bg-gray-900 text-white py-3 rounded-xl hover:bg-red-600 transition-colors font-black text-sm">+</button>
                    </div>
                 </div>
               ))}
            </div>
          )}

          {activeTab === 'customers' && (
            <div className="bg-white rounded-[40px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
              <div className="p-8 border-b flex flex-col sm:flex-row justify-between items-center gap-4 bg-gray-50/30">
                 <h3 className="font-black text-gray-900 text-base uppercase tracking-tight">Node Registry</h3>
                 <span className="text-[9px] font-black uppercase tracking-[3px] bg-red-600 text-white px-5 py-2 rounded-full shadow-lg shadow-red-600/20">{customers.length} Nodes Online</span>
              </div>
              <div className="overflow-x-auto w-full scrollbar-hide">
                <table className="w-full text-left min-w-[700px]">
                  <thead>
                    <tr className="bg-gray-50/80 border-b border-gray-100 text-[10px] font-black uppercase tracking-[3px] text-gray-400">
                       <th className="px-8 py-6">Member Identity</th>
                       <th className="px-8 py-6">Communication</th>
                       <th className="px-8 py-6">Loyalty Node</th>
                       <th className="px-8 py-6">Audit</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50 text-xs font-bold text-gray-700">
                    {customers.map((c, idx) => (
                      <tr key={idx} className="hover:bg-gray-50/50 transition-all group">
                        <td className="px-8 py-6 font-black text-gray-900">{c.name}</td>
                        <td className="px-8 py-6 text-gray-500">{c.email}</td>
                        <td className="px-8 py-6">
                          <span className={`px-4 py-2 rounded-xl text-[8px] font-black uppercase tracking-widest ${
                            c.tier === 'PLATINUM' ? 'bg-indigo-50 text-indigo-600 border border-indigo-100' :
                            c.tier === 'GOLD' ? 'bg-amber-50 text-amber-600 border border-amber-100' :
                            'bg-gray-100 text-gray-400'
                          }`}>
                            {c.tier}
                          </span>
                        </td>
                        <td className="px-8 py-6">
                          <button onClick={() => showToast(`Accessing node audit for ${c.name}...`, 'info')} className="w-10 h-10 rounded-xl bg-gray-50 text-gray-300 flex items-center justify-center hover:bg-red-50 hover:text-red-600 transition-all">
                            <i className="fas fa-search-plus"></i>
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <div className="p-4 bg-gray-50/50 text-center lg:hidden">
                 <p className="text-[8px] font-black text-gray-300 uppercase tracking-widest">Swipe left to see all columns</p>
              </div>
            </div>
          )}

          {activeTab === 'security' && userRole === UserRole.ADMIN && (
            <div className="space-y-10">
               <div className="bg-gray-950 p-8 lg:p-16 rounded-[50px] text-white relative overflow-hidden group">
                  <div className="absolute top-0 right-0 w-80 h-80 bg-red-600/10 rounded-full blur-[100px] -mr-40 -mt-40"></div>
                  <div className="relative z-10">
                     <div className="flex items-center gap-4 mb-8">
                        <div className="w-14 h-14 bg-red-600 rounded-2xl flex items-center justify-center shadow-2xl shadow-red-600/40 border border-white/10">
                           <i className="fas fa-shield-virus text-2xl"></i>
                        </div>
                        <div>
                          <h3 className="text-3xl font-black tracking-tighter">Terminal Audit Log</h3>
                          <p className="text-[10px] font-black opacity-40 uppercase tracking-[4px]">Real-time security protocol</p>
                        </div>
                     </div>
                     <p className="text-gray-400 font-bold max-w-lg mb-12 text-sm leading-relaxed">Cryptographic validation active. All privileged node interactions are recorded in the immutable ledger.</p>

                     <div className="space-y-4">
                        {MOCK_AUDIT_LOGS.map((log, idx) => (
                          <div key={idx} className="flex flex-col sm:flex-row sm:items-center justify-between p-6 bg-white/5 rounded-3xl border border-white/5 hover:bg-white/10 transition-all gap-4">
                             <div className="flex items-center gap-6">
                                <div className={`w-3 h-3 rounded-full shrink-0 ${log.status === 'SUCCESS' ? 'bg-emerald-500 shadow-[0_0_15px_#10b981]' : 'bg-red-500 shadow-[0_0_15px_#ef4444]'}`}></div>
                                <div className="min-w-0">
                                   <p className="text-xs font-black uppercase tracking-widest mb-1 truncate">{log.event}</p>
                                   <p className="text-[9px] opacity-40 uppercase tracking-[4px] truncate">{log.actor} • {log.time}</p>
                                </div>
                             </div>
                             <span className={`text-[10px] font-black uppercase tracking-[3px] px-6 py-2 rounded-xl text-center ${log.status === 'SUCCESS' ? 'bg-emerald-500/10 text-emerald-500' : 'bg-red-500/10 text-red-500'}`}>
                               {log.status}
                             </span>
                          </div>
                        ))}
                     </div>
                  </div>
               </div>
            </div>
          )}
        </main>
      </div>

      <ChatBot />
    </div>
  );
};

const SidebarBtn = ({ active, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-5 px-6 py-4 rounded-2xl transition-all duration-300 border-2 active:scale-[0.98] ${
    active ? 'bg-red-600 border-red-600 text-white shadow-xl shadow-red-600/30' : 'bg-transparent border-transparent text-gray-400 hover:bg-red-50 hover:text-red-600'
  }`}>
    <div className="w-8 flex justify-center shrink-0"><i className={`fas ${icon} text-lg lg:text-xl`}></i></div>
    <span className="font-black text-[10px] uppercase tracking-[3px] whitespace-nowrap">{label}</span>
  </button>
);

const StatCard = ({ title, value, icon, color }: any) => (
  <div className="bg-white p-6 lg:p-10 rounded-[40px] border border-gray-100 flex items-center gap-6 group hover:shadow-2xl transition-all h-full relative overflow-hidden">
    <div className="absolute -right-4 -bottom-4 text-gray-50 text-6xl opacity-50 group-hover:scale-110 transition-transform">
      <i className={`fas ${icon}`}></i>
    </div>
    <div className={`w-14 h-14 bg-gray-50 rounded-2xl flex items-center justify-center text-xl ${color} shadow-inner shrink-0 group-hover:scale-110 transition-transform z-10`}><i className={`fas ${icon}`}></i></div>
    <div className="min-w-0 z-10">
      <p className="text-[10px] font-black text-gray-300 uppercase tracking-widest mb-1 truncate">{title}</p>
      <h4 className="text-2xl lg:text-3xl font-black text-gray-900 tracking-tighter truncate leading-none">{value}</h4>
    </div>
  </div>
);

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { Button } from './Button';
import { ChatBot } from './ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 },
  { name: 'Sun', sales: 3800 },
  { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 },
  { name: 'Wed', sales: 6200 },
  { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

const CATEGORY_DATA = [
  { name: 'Biryani', value: 45, color: '#dc2626' },
  { name: 'Kebab', value: 25, color: '#ea580c' },
  { name: 'Curry', value: 20, color: '#f59e0b' },
  { name: 'Desserts', value: 10, color: '#10b981' },
];

const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  [UserRole.ADMIN]: ['dashboard', 'orders', 'menu', 'inventory', 'customers', 'security'],
  [UserRole.MANAGER]: ['dashboard', 'orders', 'inventory', 'customers'],
  [UserRole.STAFF]: ['orders', 'inventory'],
  [UserRole.CUSTOMER]: []
};

const MOCK_AUDIT_LOGS = [
  { time: '10:45 AM', event: 'Terminal Access', actor: 'Root Admin', status: 'SUCCESS' },
  { time: '09:30 AM', event: 'Inventory Audit', actor: 'Regional Manager', status: 'SUCCESS' },
  { time: '08:15 AM', event: 'Order Dispatch', actor: 'Staff User', status: 'SUCCESS' },
  { time: '07:50 AM', event: 'Unauthorized Access Blocked', actor: '192.168.1.4', status: 'FAILURE' },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const allowedTabs = useMemo(() => ROLE_PERMISSIONS[userRole] || [], [userRole]);
  const [activeTab, setActiveTab] = useState(allowedTabs[0] || 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(3600);
  const [adminToast, setAdminToast] = useState<{msg: string, type: 'success' | 'error' | 'warning'} | null>(null);
  const [customers, setCustomers] = useState<any[]>([]);

  const showToast = useCallback((msg: string, type: 'success' | 'error' | 'warning') => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const verifyAccess = useCallback(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (!savedUser) return false;
    try {
      const user = JSON.parse(savedUser) as User;
      if (!user.sessionToken) return false;
      const parts = user.sessionToken.split('.');
      if (parts.length !== 3) return false;

      const payload = JSON.parse(atob(parts[1]));
      if (payload.exp < Date.now()) return false;
      if (payload.role !== userRole) return false;

      setSessionTimeLeft(Math.round((payload.exp - Date.now()) / 1000));
      return true;
    } catch { return false; }
  }, [userRole]);

  useEffect(() => {
    if (verifyAccess()) {
      setIsAuthorized(true);
    } else {
      onLogout();
    }
  }, [verifyAccess, onLogout]);

  useEffect(() => {
    const timer = setInterval(() => {
      if (!verifyAccess()) {
        showToast('Terminal session expired. Terminating access.', 'error');
        setTimeout(onLogout, 1500);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [verifyAccess, onLogout, showToast]);

  useEffect(() => {
    const raw = localStorage.getItem('bfc_customers');
    if (raw) {
      try {
        const data = JSON.parse(raw);
        setCustomers(Object.values(data));
      } catch (e) {
        setCustomers([]);
      }
    }
  }, []);

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length,
    };
  }, [orders, menuItems]);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order #${orderId.slice(-4)} updated to ${newStatus}.`, 'success');
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) {
          showToast(`Forbidden: Minimum stock threshold reached.`, 'warning');
          return item;
        }
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white p-6 text-center">
      <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin mb-6"></div>
      <p className="text-[10px] font-black uppercase tracking-[8px] animate-pulse">Encrypting Node Access...</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden font-sans">
      {adminToast && (
        <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-[3000] px-6 py-4 rounded-2xl shadow-2xl border animate-slide-up flex items-center gap-4 w-[90%] sm:w-auto max-w-md ${
          adminToast.type === 'error' ? 'bg-red-600 border-red-400 text-white' : 
          adminToast.type === 'warning' ? 'bg-amber-500 border-amber-400 text-white' : 'bg-gray-900 border-white/10 text-white'
        }`}>
          <i className={`fas ${adminToast.type === 'success' ? 'fa-circle-check' : adminToast.type === 'error' ? 'fa-circle-xmark' : 'fa-triangle-exclamation'}`}></i>
          <span className="text-[10px] font-black uppercase tracking-widest leading-snug">{adminToast.msg}</span>
        </div>
      )}

      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[200] lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 bg-white border-r border-gray-100 transition-transform duration-300 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 flex items-center justify-between border-b border-gray-50">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white shadow-lg"><i className="fas fa-terminal"></i></div>
            <h1 className="text-xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
          </div>
          <button className="lg:hidden w-10 h-10 flex items-center justify-center text-gray-300 hover:text-red-600 transition-colors" onClick={() => setSidebarOpen(false)}>
            <i className="fas fa-times text-xl"></i>
          </button>
        </div>

        <nav className="p-6 space-y-1 overflow-y-auto h-[calc(100vh-280px)] scrollbar-hide">
          {allowedTabs.map(tab => (
             <SidebarBtn key={tab} active={activeTab === tab} onClick={() => {setActiveTab(tab); setSidebarOpen(false);}} icon={tab === 'dashboard' ? 'fa-chart-pie' : tab === 'orders' ? 'fa-list-check' : tab === 'menu' ? 'fa-utensils' : tab === 'inventory' ? 'fa-box-open' : tab === 'customers' ? 'fa-users' : 'fa-shield-halved'} label={tab} />
          ))}
        </nav>

        <div className="absolute bottom-0 w-full p-8 border-t bg-white">
          <div className="flex items-center gap-3 mb-6 bg-gray-50 p-4 rounded-2xl">
            <div className="w-10 h-10 bg-gray-950 text-white rounded-xl flex items-center justify-center font-black shrink-0">{userRole.charAt(0)}</div>
            <div className="min-w-0">
              <p className="text-[9px] font-black text-gray-950 uppercase tracking-widest truncate">{userRole}</p>
              <p className="text-[7px] font-bold text-gray-400">SESSION: {Math.floor(sessionTimeLeft / 60)}m</p>
            </div>
          </div>
          <button onClick={onLogout} className="w-full py-4 rounded-xl bg-red-50 text-red-600 font-black hover:bg-red-600 hover:text-white transition-all uppercase tracking-[4px] text-[8px] border border-red-100">Terminate</button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-20 bg-white/80 backdrop-blur-xl border-b flex items-center justify-between px-6 lg:px-12 shrink-0 z-50">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden w-10 h-10 bg-gray-100 rounded-xl flex items-center justify-center text-gray-600 hover:bg-gray-200 transition-colors">
              <i className="fas fa-bars"></i>
            </button>
            <h2 className="text-base lg:text-xl font-black text-gray-800 tracking-tight uppercase truncate">
              {activeTab} Interface
            </h2>
          </div>
          <div className="hidden sm:flex items-center gap-3 text-[8px] font-black text-gray-400 uppercase tracking-widest bg-gray-50 px-4 py-2 rounded-full border">
            <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
            Node: BFC-HQ-01
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 lg:p-10 space-y-10 animate-slide-up scrollbar-hide scroll-smooth">
          {activeTab === 'dashboard' && (
            <div className="space-y-10">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 lg:gap-6">
                <StatCard title="Revenue" value={`৳${stats.revenue.toLocaleString()}`} icon="fa-taka-sign" color="text-red-600" />
                <StatCard title="Active Orders" value={stats.orderCount} icon="fa-box" color="text-blue-600" />
                <StatCard title="Queue" value={stats.pending} icon="fa-clock" color="text-purple-600" />
                <StatCard title="Stock Risks" value={stats.lowStock} icon="fa-triangle-exclamation" color="text-amber-500" />
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-2 gap-6 lg:gap-10">
                <div className="bg-white p-6 rounded-[32px] border border-gray-100 shadow-sm min-h-[350px]">
                   <h3 className="text-[10px] font-black mb-6 uppercase tracking-[3px] text-gray-400">Weekly Revenue Flow</h3>
                   <div className="h-[250px] w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={ANALYTICS_DATA}>
                          <defs>
                            <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                              <stop offset="5%" stopColor="#dc2626" stopOpacity={0.1}/>
                              <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                            </linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 9, fontWeight: 'bold'}} />
                          <YAxis axisLine={false} tickLine={false} tick={{fontSize: 9, fontWeight: 'bold'}} />
                          <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 30px rgba(0,0,0,0.05)' }} />
                          <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={3} fill="url(#colorSales)" />
                        </AreaChart>
                      </ResponsiveContainer>
                   </div>
                </div>

                <div className="bg-white p-6 rounded-[32px] border border-gray-100 shadow-sm min-h-[350px]">
                   <h3 className="text-[10px] font-black mb-6 uppercase tracking-[3px] text-gray-400">Inventory Distribution</h3>
                   <div className="h-[250px] w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie 
                            data={CATEGORY_DATA} 
                            innerRadius="60%" 
                            outerRadius="80%" 
                            paddingAngle={5} 
                            dataKey="value"
                            stroke="none"
                          >
                            {CATEGORY_DATA.map((entry, idx) => <Cell key={idx} fill={entry.color} />)}
                          </Pie>
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                   </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'orders' && (
             <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 lg:gap-6">
               {orders.length === 0 ? (
                 <div className="col-span-full py-20 text-center bg-white rounded-[32px] border border-gray-100 shadow-sm">
                    <i className="fas fa-inbox text-5xl text-gray-100 mb-6"></i>
                    <p className="font-black text-gray-300 uppercase tracking-widest text-xs">No active orders found</p>
                 </div>
               ) : (
                 orders.map(o => (
                  <div key={o.id} className="bg-white p-6 rounded-[32px] border border-gray-50 flex flex-col gap-5 hover:shadow-xl transition-all group">
                    <div className="flex justify-between items-start">
                       <div className="flex items-center gap-3">
                          <div className="w-10 h-10 bg-gray-950 text-white rounded-xl flex items-center justify-center font-black text-[10px] shadow-lg">#{o.id.slice(-4)}</div>
                          <div className="min-w-0">
                            <p className="font-black text-gray-800 text-xs truncate">{o.customerName}</p>
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest">{o.paymentMethod}</p>
                          </div>
                       </div>
                       <span className={`px-3 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-100 text-emerald-700' : 'bg-red-50 text-red-600'}`}>
                         {o.status}
                       </span>
                    </div>

                    <div className="bg-gray-50 rounded-2xl p-4 space-y-1">
                       {o.items.map((it, idx) => (
                         <div key={idx} className="flex justify-between text-[10px] font-bold text-gray-600">
                            <span>{it.quantity}x {it.name}</span>
                            <span>৳{it.price * it.quantity}</span>
                         </div>
                       ))}
                    </div>

                    <select 
                      className="w-full bg-white border-2 border-gray-100 rounded-2xl p-3 text-[10px] font-black uppercase tracking-widest outline-none focus:border-red-600 transition-all cursor-pointer" 
                      value={o.status} 
                      onChange={(e) => handleUpdateStatus(o.id, e.target.value as OrderStatus)}
                    >
                      {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
                 ))
               )}
             </div>
          )}

          {activeTab === 'inventory' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 lg:gap-6">
               {menuItems.map(item => (
                 <div key={item.id} className="bg-white p-6 rounded-[32px] border border-gray-100 flex flex-col items-center text-center shadow-sm hover:shadow-lg transition-all group">
                    <div className="relative mb-4">
                      <img src={item.image} className="w-16 h-16 rounded-2xl object-cover shadow-md group-hover:scale-110 transition-transform" alt={item.name} />
                      {item.stock < 10 && <div className="absolute -top-1 -right-1 w-5 h-5 bg-red-600 text-white rounded-full flex items-center justify-center text-[8px] ring-2 ring-white"><i className="fas fa-exclamation"></i></div>}
                    </div>
                    <h4 className="font-black text-gray-800 text-xs mb-1 truncate w-full px-2">{item.name}</h4>
                    <p className={`text-3xl font-black mb-4 ${item.stock < 10 ? 'text-red-600' : 'text-gray-950'}`}>{item.stock}</p>
                    <div className="flex gap-2 w-full">
                       <button onClick={()=>handleUpdateStock(item.id, false)} className="flex-1 bg-gray-50 py-2 rounded-xl hover:bg-red-50 hover:text-red-600 transition-colors font-black text-xs">-</button>
                       <button onClick={()=>handleUpdateStock(item.id, true)} className="flex-1 bg-gray-900 text-white py-2 rounded-xl hover:bg-red-600 transition-colors font-black text-xs">+</button>
                    </div>
                 </div>
               ))}
            </div>
          )}

          {activeTab === 'customers' && (
            <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
              <div className="p-6 border-b flex flex-col sm:flex-row justify-between items-center gap-4 bg-gray-50/20">
                 <h3 className="font-black text-gray-900 text-sm uppercase">Member Node Registry</h3>
                 <span className="text-[8px] font-black uppercase tracking-widest bg-red-600 text-white px-4 py-1.5 rounded-full">{customers.length} Nodes Online</span>
              </div>
              <div className="overflow-x-auto w-full scrollbar-hide">
                <table className="w-full text-left min-w-[600px]">
                  <thead>
                    <tr className="bg-gray-50/50 border-b border-gray-100 text-[9px] font-black uppercase tracking-[2px] text-gray-400">
                       <th className="px-6 py-4">Identity</th>
                       <th className="px-6 py-4">Endpoint</th>
                       <th className="px-6 py-4">Loyalty Rank</th>
                       <th className="px-6 py-4">Action</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50 text-[11px] font-bold text-gray-700">
                    {customers.length === 0 ? (
                      <tr>
                        <td colSpan={4} className="px-6 py-12 text-center text-gray-300">No registered members found in cache.</td>
                      </tr>
                    ) : (
                      customers.map((c, idx) => (
                        <tr key={idx} className="hover:bg-gray-50/50 transition-all">
                          <td className="px-6 py-4 font-black text-gray-900">{c.name}</td>
                          <td className="px-6 py-4 text-gray-400">{c.email}</td>
                          <td className="px-6 py-4">
                            <span className={`px-3 py-1 rounded-lg text-[7px] font-black uppercase tracking-widest ${
                              c.tier === 'PLATINUM' ? 'bg-indigo-50 text-indigo-600' :
                              c.tier === 'GOLD' ? 'bg-amber-50 text-amber-600' :
                              'bg-gray-100 text-gray-400'
                            }`}>
                              {c.tier}
                            </span>
                          </td>
                          <td className="px-6 py-4">
                            <button onClick={() => showToast(`Syncing ${c.name}...`, 'info')} className="w-8 h-8 rounded-lg bg-gray-100 text-gray-300 flex items-center justify-center hover:bg-red-50 hover:text-red-600 transition-all">
                              <i className="fas fa-eye"></i>
                            </button>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {activeTab === 'security' && userRole === UserRole.ADMIN && (
            <div className="space-y-6">
               <div className="bg-gray-950 p-6 lg:p-12 rounded-[40px] text-white relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-64 h-64 bg-red-600/5 rounded-full blur-[80px] -mr-32 -mt-32"></div>
                  <div className="relative z-10">
                     <div className="flex items-center gap-4 mb-6">
                        <div className="w-12 h-12 bg-red-600 rounded-xl flex items-center justify-center shadow-lg border border-white/10">
                           <i className="fas fa-shield-halved text-xl"></i>
                        </div>
                        <h3 className="text-xl font-black tracking-tight">Active Audit Log</h3>
                     </div>
                     <p className="text-gray-400 font-bold max-w-lg mb-8 text-xs leading-relaxed">System-wide event tracking enabled. All privileged terminal requests are hashed and logged for forensic review.</p>

                     <div className="space-y-3">
                        {MOCK_AUDIT_LOGS.map((log, idx) => (
                          <div key={idx} className="flex flex-col sm:flex-row sm:items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5 hover:bg-white/10 transition-all gap-3">
                             <div className="flex items-center gap-4">
                                <div className={`w-2 h-2 rounded-full shrink-0 ${log.status === 'SUCCESS' ? 'bg-emerald-500 shadow-[0_0_10px_#10b981]' : 'bg-red-500 shadow-[0_0_10px_#ef4444]'}`}></div>
                                <div className="min-w-0">
                                   <p className="text-[10px] font-black uppercase tracking-tight truncate">{log.event}</p>
                                   <p className="text-[8px] opacity-30 uppercase tracking-[2px] truncate">{log.actor} • {log.time}</p>
                                </div>
                             </div>
                             <span className={`text-[8px] font-black uppercase tracking-[2px] px-4 py-1.5 rounded-lg text-center ${log.status === 'SUCCESS' ? 'bg-emerald-500/10 text-emerald-500' : 'bg-red-500/10 text-red-500'}`}>
                               {log.status}
                             </span>
                          </div>
                        ))}
                     </div>
                  </div>
               </div>
            </div>
          )}
        </main>
      </div>

      <ChatBot />
    </div>
  );
};

const SidebarBtn = ({ active, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-5 py-3.5 rounded-xl transition-all duration-300 border-2 active:scale-95 ${
    active ? 'bg-red-600 border-red-600 text-white shadow-lg shadow-red-600/20' : 'bg-transparent border-transparent text-gray-400 hover:bg-red-50 hover:text-red-600'
  }`}>
    <div className="w-6 flex justify-center shrink-0"><i className={`fas ${icon} text-lg`}></i></div>
    <span className="font-black text-[9px] uppercase tracking-[2px] whitespace-nowrap">{label}</span>
  </button>
);

const StatCard = ({ title, value, icon, color }: any) => (
  <div className="bg-white p-5 lg:p-7 rounded-[28px] border border-gray-100 flex items-center gap-4 group hover:shadow-lg transition-all h-full relative overflow-hidden text-left">
    <div className={`w-12 h-12 bg-gray-50 rounded-xl flex items-center justify-center text-lg ${color} shadow-inner shrink-0 group-hover:scale-110 transition-transform`}><i className={`fas ${icon}`}></i></div>
    <div className="min-w-0">
      <p className="text-[9px] font-black text-gray-300 uppercase tracking-widest mb-0.5 truncate">{title}</p>
      <h4 className="text-xl lg:text-2xl font-black text-gray-900 tracking-tighter truncate leading-none">{value}</h4>
    </div>
  </div>
);

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { Button } from './Button';
import { ChatBot } from './ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 },
  { name: 'Sun', sales: 3800 },
  { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 },
  { name: 'Wed', sales: 6200 },
  { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

const CATEGORY_DATA = [
  { name: 'Biryani', value: 45, color: '#dc2626' },
  { name: 'Kebab', value: 25, color: '#ea580c' },
  { name: 'Curry', value: 20, color: '#f59e0b' },
  { name: 'Desserts', value: 10, color: '#10b981' },
];

const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  [UserRole.ADMIN]: ['dashboard', 'orders', 'menu', 'inventory', 'customers', 'security'],
  [UserRole.MANAGER]: ['dashboard', 'orders', 'inventory', 'customers'],
  [UserRole.STAFF]: ['orders', 'inventory'],
  [UserRole.CUSTOMER]: []
};

const MOCK_AUDIT_LOGS = [
  { 
    timestamp: '2024-05-20T10:45:12+06:00', 
    event: 'Terminal Access', 
    actor: 'Root Admin', 
    status: 'SUCCESS',
    affectedItem: 'System Kernel #01'
  },
  { 
    timestamp: '2024-05-20T09:30:45+06:00', 
    event: 'Inventory Modification', 
    actor: 'Regional Manager', 
    status: 'SUCCESS',
    affectedItem: 'Item: Kacchi Biryani (+50)'
  },
  { 
    timestamp: '2024-05-20T08:15:22+06:00', 
    event: 'Order Dispatch', 
    actor: 'Floor Staff', 
    status: 'SUCCESS',
    affectedItem: 'Order: ORD-9921B'
  },
  { 
    timestamp: '2024-05-20T07:50:11+06:00', 
    event: 'Unauthorized Link Attempt', 
    actor: '192.168.1.4', 
    status: 'FAILURE',
    affectedItem: 'Admin Gateway Port 8080'
  },
  { 
    timestamp: '2024-05-20T06:22:05+06:00', 
    event: 'Config Sync', 
    actor: 'Cloud Automate', 
    status: 'SUCCESS',
    affectedItem: 'Delivery Zone Latency Params'
  }
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const allowedTabs = useMemo(() => ROLE_PERMISSIONS[userRole] || [], [userRole]);
  const [activeTab, setActiveTab] = useState(allowedTabs[0] || 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(3600);
  const [adminToast, setAdminToast] = useState<{msg: string, type: 'success' | 'error' | 'warning'} | null>(null);
  const [customers, setCustomers] = useState<any[]>([]);

  const showToast = useCallback((msg: string, type: 'success' | 'error' | 'warning') => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const verifyAccess = useCallback(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (!savedUser) return false;
    try {
      const user = JSON.parse(savedUser) as User;
      if (!user.sessionToken) return false;
      const parts = user.sessionToken.split('.');
      if (parts.length !== 3) return false;

      const payload = JSON.parse(atob(parts[1]));
      if (payload.exp < Date.now()) return false;
      if (payload.role !== userRole) return false;

      setSessionTimeLeft(Math.round((payload.exp - Date.now()) / 1000));
      return true;
    } catch { return false; }
  }, [userRole]);

  useEffect(() => {
    if (verifyAccess()) {
      setIsAuthorized(true);
    } else {
      onLogout();
    }
  }, [verifyAccess, onLogout]);

  useEffect(() => {
    const timer = setInterval(() => {
      if (!verifyAccess()) {
        showToast('Terminal session expired. Terminating access.', 'error');
        setTimeout(onLogout, 1500);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [verifyAccess, onLogout, showToast]);

  useEffect(() => {
    const raw = localStorage.getItem('bfc_customers');
    if (raw) {
      try {
        const data = JSON.parse(raw);
        setCustomers(Object.values(data));
      } catch (e) {
        setCustomers([]);
      }
    }
  }, []);

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length,
    };
  }, [orders, menuItems]);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order #${orderId.slice(-4)} updated to ${newStatus}.`, 'success');
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) {
          showToast(`Forbidden: Minimum stock threshold reached.`, 'warning');
          return item;
        }
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white p-6 text-center">
      <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin mb-6"></div>
      <p className="text-[10px] font-black uppercase tracking-[8px] animate-pulse">Encrypting Node Access...</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden font-sans">
      {adminToast && (
        <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-[3000] px-6 py-4 rounded-2xl shadow-2xl border animate-slide-up flex items-center gap-4 w-[90%] sm:w-auto max-w-md ${
          adminToast.type === 'error' ? 'bg-red-600 border-red-400 text-white' : 
          adminToast.type === 'warning' ? 'bg-amber-500 border-amber-400 text-white' : 'bg-gray-900 border-white/10 text-white'
        }`}>
          <i className={`fas ${adminToast.type === 'success' ? 'fa-circle-check' : adminToast.type === 'error' ? 'fa-circle-xmark' : 'fa-triangle-exclamation'}`}></i>
          <span className="text-[10px] font-black uppercase tracking-widest leading-snug">{adminToast.msg}</span>
        </div>
      )}

      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[200] lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 bg-white border-r border-gray-100 transition-transform duration-300 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 flex items-center justify-between border-b border-gray-50">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white shadow-lg"><i className="fas fa-terminal"></i></div>
            <h1 className="text-xl font-black text-gray-800 tracking-tighter">BFC HUB</h1>
          </div>
          <button className="lg:hidden w-10 h-10 flex items-center justify-center text-gray-300 hover:text-red-600 transition-colors" onClick={() => setSidebarOpen(false)}>
            <i className="fas fa-times text-xl"></i>
          </button>
        </div>

        <nav className="p-6 space-y-1 overflow-y-auto h-[calc(100vh-280px)] scrollbar-hide">
          {allowedTabs.map(tab => (
             <SidebarBtn key={tab} active={activeTab === tab} onClick={() => {setActiveTab(tab); setSidebarOpen(false);}} icon={tab === 'dashboard' ? 'fa-chart-pie' : tab === 'orders' ? 'fa-list-check' : tab === 'menu' ? 'fa-utensils' : tab === 'inventory' ? 'fa-box-open' : tab === 'customers' ? 'fa-users' : 'fa-shield-halved'} label={tab} />
          ))}
        </nav>

        <div className="absolute bottom-0 w-full p-8 border-t bg-white">
          <div className="flex items-center gap-3 mb-6 bg-gray-50 p-4 rounded-2xl">
            <div className="w-10 h-10 bg-gray-950 text-white rounded-xl flex items-center justify-center font-black shrink-0">{userRole.charAt(0)}</div>
            <div className="min-w-0">
              <p className="text-[9px] font-black text-gray-950 uppercase tracking-widest truncate">{userRole}</p>
              <p className="text-[7px] font-bold text-gray-400">SESSION: {Math.floor(sessionTimeLeft / 60)}m</p>
            </div>
          </div>
          <button onClick={onLogout} className="w-full py-4 rounded-xl bg-red-50 text-red-600 font-black hover:bg-red-600 hover:text-white transition-all uppercase tracking-[4px] text-[8px] border border-red-100">Terminate</button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-20 bg-white/80 backdrop-blur-xl border-b flex items-center justify-between px-6 lg:px-12 shrink-0 z-50">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden w-10 h-10 bg-gray-100 rounded-xl flex items-center justify-center text-gray-600 hover:bg-gray-200 transition-colors">
              <i className="fas fa-bars"></i>
            </button>
            <h2 className="text-base lg:text-xl font-black text-gray-800 tracking-tight uppercase truncate">
              {activeTab} Interface
            </h2>
          </div>
          <div className="hidden sm:flex items-center gap-3 text-[8px] font-black text-gray-400 uppercase tracking-widest bg-gray-50 px-4 py-2 rounded-full border">
            <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
            Node: BFC-HQ-01
          </div>
        </header>

        <main className="flex-1 overflow-y-auto p-4 lg:p-10 space-y-10 animate-slide-up scrollbar-hide scroll-smooth">
          {activeTab === 'dashboard' && (
            <div className="space-y-10">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 lg:gap-6">
                <StatCard title="Revenue" value={`৳${stats.revenue.toLocaleString()}`} icon="fa-taka-sign" color="text-red-600" />
                <StatCard title="Active Orders" value={stats.orderCount} icon="fa-box" color="text-blue-600" />
                <StatCard title="Queue" value={stats.pending} icon="fa-clock" color="text-purple-600" />
                <StatCard title="Stock Risks" value={stats.lowStock} icon="fa-triangle-exclamation" color="text-amber-500" />
              </div>

              <div className="grid grid-cols-1 xl:grid-cols-2 gap-6 lg:gap-10">
                <div className="bg-white p-6 rounded-[32px] border border-gray-100 shadow-sm min-h-[350px]">
                   <h3 className="text-[10px] font-black mb-6 uppercase tracking-[3px] text-gray-400">Weekly Revenue Flow</h3>
                   <div className="h-[250px] w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={ANALYTICS_DATA}>
                          <defs>
                            <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                              <stop offset="5%" stopColor="#dc2626" stopOpacity={0.1}/>
                              <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                            </linearGradient>
                          </defs>
                          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 9, fontWeight: 'bold'}} />
                          <YAxis axisLine={false} tickLine={false} tick={{fontSize: 9, fontWeight: 'bold'}} />
                          <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 30px rgba(0,0,0,0.05)' }} />
                          <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={3} fill="url(#colorSales)" />
                        </AreaChart>
                      </ResponsiveContainer>
                   </div>
                </div>

                <div className="bg-white p-6 rounded-[32px] border border-gray-100 shadow-sm min-h-[350px]">
                   <h3 className="text-[10px] font-black mb-6 uppercase tracking-[3px] text-gray-400">Inventory Distribution</h3>
                   <div className="h-[250px] w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie 
                            data={CATEGORY_DATA} 
                            innerRadius="60%" 
                            outerRadius="80%" 
                            paddingAngle={5} 
                            dataKey="value"
                            stroke="none"
                          >
                            {CATEGORY_DATA.map((entry, idx) => <Cell key={idx} fill={entry.color} />)}
                          </Pie>
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                   </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'orders' && (
             <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 lg:gap-6">
               {orders.length === 0 ? (
                 <div className="col-span-full py-20 text-center bg-white rounded-[32px] border border-gray-100 shadow-sm">
                    <i className="fas fa-inbox text-5xl text-gray-100 mb-6"></i>
                    <p className="font-black text-gray-300 uppercase tracking-widest text-xs">No active orders found</p>
                 </div>
               ) : (
                 orders.map(o => (
                  <div key={o.id} className="bg-white p-6 rounded-[32px] border border-gray-50 flex flex-col gap-5 hover:shadow-xl transition-all group">
                    <div className="flex justify-between items-start">
                       <div className="flex items-center gap-3">
                          <div className="w-10 h-10 bg-gray-950 text-white rounded-xl flex items-center justify-center font-black text-[10px] shadow-lg">#{o.id.slice(-4)}</div>
                          <div className="min-w-0">
                            <p className="font-black text-gray-800 text-xs truncate">{o.customerName}</p>
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest">{o.paymentMethod}</p>
                          </div>
                       </div>
                       <span className={`px-3 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-100 text-emerald-700' : 'bg-red-50 text-red-600'}`}>
                         {o.status}
                       </span>
                    </div>

                    <div className="bg-gray-50 rounded-2xl p-4 space-y-1">
                       {o.items.map((it, idx) => (
                         <div key={idx} className="flex justify-between text-[10px] font-bold text-gray-600">
                            <span>{it.quantity}x {it.name}</span>
                            <span>৳{it.price * it.quantity}</span>
                         </div>
                       ))}
                    </div>

                    <select 
                      className="w-full bg-white border-2 border-gray-100 rounded-2xl p-3 text-[10px] font-black uppercase tracking-widest outline-none focus:border-red-600 transition-all cursor-pointer" 
                      value={o.status} 
                      onChange={(e) => handleUpdateStatus(o.id, e.target.value as OrderStatus)}
                    >
                      {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
                 ))
               )}
             </div>
          )}

          {activeTab === 'inventory' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 lg:gap-6">
               {menuItems.map(item => (
                 <div key={item.id} className="bg-white p-6 rounded-[32px] border border-gray-100 flex flex-col items-center text-center shadow-sm hover:shadow-lg transition-all group">
                    <div className="relative mb-4">
                      <img src={item.image} className="w-16 h-16 rounded-2xl object-cover shadow-md group-hover:scale-110 transition-transform" alt={item.name} />
