                </div>
                <div>
                  <h3 className="font-black text-2xl tracking-tighter uppercase leading-none italic">BFC Assist</h3>
                  <div className="flex items-center gap-2 mt-2">
                    <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                    <p className="text-[9px] font-black uppercase tracking-[4px] text-emerald-400">Node Online</p>
                  </div>
                </div>
              </div>
              <button 
                onClick={() => setIsOpen(false)} 
                className="w-12 h-12 bg-white/5 hover:bg-white/10 rounded-2xl flex items-center justify-center transition-all border border-white/10 active:scale-90"
              >
                <i className="fas fa-xmark text-lg text-gray-400"></i>
              </button>
            </div>
          </div>

          {/* Chat Engine */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 lg:p-10 space-y-8 scrollbar-hide bg-gradient-to-b from-[#FDFDFD] to-[#F8F9FA] relative">
