              >
                <i className={`fas ${isListening ? 'fa-microphone-lines' : 'fa-microphone'} text-lg`}></i>
              </button>

              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={isListening ? "Listening..." : "Tell BFC Boss..."}
                className="flex-1 bg-transparent border-none py-4 px-3 outline-none text-[15px] font-bold text-gray-900 placeholder:text-gray-400"
              />

              <button 
