  const validateAuthForm = () => {
    const errors: Record<string, string> = {};
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phoneRegex = /^01[3-9]\d{8}$/;

    if (!formEmail) errors.email = "Email is required.";
    else if (!emailRegex.test(formEmail)) errors.email = "Invalid format.";

    if (!formPass) errors.password = "Password required.";

    if (authMode === 'REGISTER') {
      if (!formName.trim()) errors.name = "Full name required.";
      if (!formPhone) errors.phone = "Phone contact required.";
      else if (!phoneRegex.test(formPhone)) errors.phone = "Invalid BD format.";
    }

    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleAuth = async () => {
    if (!validateAuthForm()) return;
    if (lockoutUntil && Date.now() < lockoutUntil) return;

    setIsAuthenticating(true);
    await new Promise(r => setTimeout(r, 1200));

    const emailKey = formEmail.toLowerCase().trim();
    const privileged = MOCK_AUTH_DB[emailKey];
    const match = privileged; 

    if (match && match.pass === formPass) {
      setFailedAttempts(0);
      const user: User = {
        id: `BFC-${Math.random().toString(36).slice(7).toUpperCase()}`,
        name: match.name, 
        email: emailKey, 
        phone: match.phone,
        role: match.role, 
        loyaltyPoints: 0, 
        tier: 'SILVER',
        wishlist: [], 
        referralCode: 'BFC-PRO',
        sessionToken: generateSecureToken(match.role, emailKey)
      };

      localStorage.setItem('bfc_user_session', JSON.stringify(user));
      setCurrentUser(user);
      showToast(`Welcome back, ${user.name}.`, 'success');
      setView(user.role === UserRole.CUSTOMER ? 'HOME' : 'ADMIN');
    } else {
      setFailedAttempts(prev => prev + 1);
      showToast("Access Denied.", "error");
    }
    setIsAuthenticating(false);
  };

  const handleCheckout = async () => {
    if (!isOnline) {
      showToast("Offline: Payment restricted.", "error");
      return;
    }
    if (cart.length === 0) return;
    if (!currentUser) {
      showToast("Please login to proceed.", "warning");
      setView('LOGIN');
      return;
    }

    // Validation for MFS and Card
    if (['BKASH', 'NAGAD', 'ROCKET', 'UPAY'].includes(paymentMethod)) {
      if (mfsDetails.number.length < 11 || mfsDetails.pin.length < 4) {
        setCheckoutError("Wallet credentials incomplete.");
        return;
      }
    } else if (paymentMethod === 'CARD') {
      if (cardDetails.number.length < 16 || cardDetails.cvv.length < 3) {
        setCheckoutError("Card details invalid.");
        return;
      }
    }

    setIsCheckingOut(true);
    setCheckoutError(null);
    await new Promise(r => setTimeout(r, 2500));

    const newOrder: Order = {
      id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
