import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

const QUICK_ACTIONS = [
  "Today's Deals 🔥",
  "Kacchi Review 🍖",
  "Spice Level? 🌶️",
  "Elite Stock 📦"
];

interface ChatBotProps {
  isOnline?: boolean;
}

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { 
      role: 'model', 
      text: "Kire Boss? 🌶️ BFC Assist here. Legendary flavors or elite deals—what's the mission today?", 
      timestamp: new Date() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isTyping]);

  const toggleVoice = () => {
    if (!isOnline) return;
    if (!('webkitSpeechRecognition' in window)) {
      alert("Voice recognition not supported in this browser.");
      return;
    }

    // @ts-ignore
    const recognition = new window.webkitSpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(transcript);
      handleSend(transcript);
    };
    recognition.start();
  };

  const handleSend = async (text: string = input) => {
    if (!isOnline) return;
    const messageToSend = text.trim();
    if (!messageToSend) return;

    const userMsg: ChatMessage = { role: 'user', text: messageToSend, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));

    try {
      const botResponse = await bfcAssistChat(messageToSend, history);
      setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Server glitch. Try again, Boss! 😅", timestamp: new Date() }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[2000] font-sans">
      {isOpen ? (
        <div className="bg-white/95 backdrop-blur-3xl w-[94vw] sm:w-[440px] h-[80vh] sm:h-[720px] rounded-[48px] shadow-[0_40px_120px_-20px_rgba(0,0,0,0.3)] flex flex-col border border-white/60 overflow-hidden animate-slide-up ring-1 ring-black/5">

          {/* Cyber-Dhaka Header */}
          <div className="bg-gray-950 p-8 text-white relative overflow-hidden shrink-0">
            <div className="absolute top-0 right-0 w-64 h-64 bg-red-600/30 rounded-full blur-[80px] -mr-32 -mt-32 animate-pulse"></div>

            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-5">
                <div className="relative group">
                  <div className="w-16 h-16 bg-red-600 rounded-[22px] flex items-center justify-center shadow-[0_0_30px_rgba(220,38,38,0.4)] border border-white/20">
                    <i className="fas fa-bolt-lightning text-2xl"></i>
                  </div>
                  <div className={`absolute -bottom-1 -right-1 w-5 h-5 border-4 border-gray-950 rounded-full shadow-lg ${isOnline ? 'bg-emerald-500' : 'bg-red-500 animate-pulse'}`}></div>
                </div>
                <div>
                  <h3 className="font-black text-2xl tracking-tighter uppercase leading-none italic">BFC Assist</h3>
                  <div className="flex items-center gap-2 mt-2">
                    <span className={`w-2 h-2 rounded-full ${isOnline ? 'bg-emerald-500 animate-pulse' : 'bg-red-500'}`}></span>
                    <p className={`text-[9px] font-black uppercase tracking-[4px] ${isOnline ? 'text-emerald-400' : 'text-red-400'}`}>
                      {isOnline ? 'Node Online' : 'Signal Lost'}
                    </p>
                  </div>
                </div>
              </div>
              <button 
                onClick={() => setIsOpen(false)} 
                className="w-12 h-12 bg-white/5 hover:bg-white/10 rounded-2xl flex items-center justify-center transition-all border border-white/10"
              >
                <i className="fas fa-xmark text-lg text-gray-400"></i>
              </button>
            </div>
          </div>

          {/* Chat Engine */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 lg:p-10 space-y-8 scrollbar-hide bg-gradient-to-b from-[#FDFDFD] to-[#F8F9FA] relative">
            {!isOnline && (
