                 <div className="space-y-4">
                    <i className="fas fa-satellite-dish text-4xl text-red-600 animate-bounce"></i>
                    <p className="font-black text-[11px] uppercase tracking-[4px] text-gray-800">Connection required to link with AI Boss</p>
