            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                <div className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'} max-w-[85%]`}>
                  <div className={`px-6 py-4 rounded-[30px] text-[15px] font-semibold leading-relaxed shadow-sm transition-all ${
                    m.role === 'user' 
                    ? 'bg-red-600 text-white rounded-br-none shadow-[0_15px_35px_-5px_rgba(220,38,38,0.25)]' 
                    : 'bg-white text-gray-800 rounded-tl-none border border-gray-100 shadow-md'
                  }`}>
                    {m.text}
                  </div>
                  <span className="text-[8px] mt-2 font-black tracking-[2px] opacity-30 uppercase px-2 font-mono">
                    {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start animate-slide-up">
                <div className="bg-white px-5 py-3 rounded-[24px] rounded-tl-none shadow-sm border border-gray-100 flex gap-1.5 items-center">
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce"></div>
                </div>
              </div>
            )}
          </div>

          {/* Action Hub */}
          <div className={`p-6 lg:p-10 bg-white border-t border-gray-100 shrink-0 ${!isOnline ? 'opacity-30 pointer-events-none' : ''}`}>
            <div className="flex gap-2.5 overflow-x-auto pb-6 scrollbar-hide">
              {QUICK_ACTIONS.map(action => (
                <button 
                  key={action}
                  onClick={() => handleSend(action)}
                  className="whitespace-nowrap px-5 py-3 bg-gray-50 hover:bg-red-600 hover:text-white rounded-2xl text-[10px] font-black uppercase tracking-widest text-gray-500 border border-transparent transition-all"
                >
                  {action}
                </button>
              ))}
            </div>

            <div className="relative flex items-center bg-gray-100 rounded-[30px] p-2 shadow-inner">
              <button 
                onClick={toggleVoice}
                className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'text-gray-400'}`}
              >
                <i className={`fas ${isListening ? 'fa-microphone-lines' : 'fa-microphone'} text-lg`}></i>
              </button>

              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Tell BFC Boss..."
                className="flex-1 bg-transparent border-none py-4 px-3 outline-none text-[15px] font-bold text-gray-900"
              />

              <button 
                onClick={() => handleSend()}
                disabled={!input.trim() || isTyping}
                className="w-12 h-12 bg-gray-950 text-white rounded-full flex items-center justify-center hover:bg-red-600 transition-all disabled:opacity-20"
              >
                <i className="fas fa-arrow-up text-sm"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="group relative"
        >
          {!isOnline && <div className="absolute -top-1 -left-1 w-6 h-6 bg-red-600 rounded-full z-10 flex items-center justify-center border-2 border-white text-[8px] text-white"><i className="fas fa-exclamation"></i></div>}
          <div className="relative bg-gray-950 text-white w-24 h-24 rounded-[35px] shadow-2xl flex flex-col items-center justify-center hover:scale-105 transition-all duration-500 border-4 border-white overflow-hidden">
             <i className="fas fa-comments text-3xl"></i>
             <span className="text-[9px] font-black uppercase tracking-[3px]">Assist</span>
          </div>
        </button>
      )}
    </div>
  );
};

