            {allowedTabs.map(tab => (
               <SidebarBtn key={tab} active={activeTab === tab} onClick={() => {setActiveTab(tab); setSidebarOpen(false);}} icon={tab === 'dashboard' ? 'fa-chart-pie' : tab === 'orders' ? 'fa-list-check' : tab === 'menu' ? 'fa-utensils' : tab === 'inventory' ? 'fa-box-open' : tab === 'customers' ? 'fa-users' : tab === 'reports' ? 'fa-file-invoice-dollar' : 'fa-shield-halved'} label={tab} theme={theme} />
