import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  if (!navigator.onLine) {
    return "Offline, Boss! Link up with the network to chat. 📶";
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist" – the elite food concierge and system navigator for BFC (Bangla Food Club).

        TONE: 
        - High-energy, practical, and "Dhaka Foodie Boss" persona.
        - Speak like a respected local entrepreneur who knows the best Kacchi spot in town.
        - Respectful but informal (use "Boss").

        CORE RULES:
        1. EXTREME BREVITY: Max 10-12 words per response. Keep it laser-focused.
        2. PRACTICALITY: Provide direct answers. If asked about stock, focus on availability. If asked about orders, focus on status.
        3. NO FLUFF: No "I understand," "Sure," or "As BFC Assist...". Get straight to the point.
        4. BANGLISH VIBE: Blend English with soulful Dhaka street-slang (e.g., "Kire Boss", "Agul 🔥", "Kora logic").

        KNOWLEDGE DOMAIN:
        - BFC Menu: Kacchi, Roast, Rezala, Doi.
        - System Intel: Inventory thresholds, order tracking, and elite customer status.

        Example Input: "How many orders are pending?"
        Example Response: "4 orders in the queue, Boss. Kitchen's heating up! 🔥"`,
        temperature: 0.7,
        topP: 0.9,
      },
    });

    return response.text || "Node glitch. Try again, Boss! 😅";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return "Signal dropped! Refresh the link and try again. 🌯";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

const QUICK_ACTIONS = [
  "Inventory Check 📦",
  "Live Orders 🚚",
  "Top Sellers 🏆",
  "System Status ⚙️"
];

interface ChatBotProps {
  isOnline?: boolean;
}

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { 
      role: 'model', 
      text: "Salaam Boss! 🌶️ Ready to dominate the floor? Let me know what intel you need.", 
      timestamp: new Date() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isTyping]);

  const toggleVoice = () => {
    if (!isOnline) return;
    if (!('webkitSpeechRecognition' in window)) {
      alert("Voice engine not found in this node.");
      return;
    }

    // @ts-ignore
    const recognition = new window.webkitSpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(transcript);
      handleSend(transcript);
    };
    recognition.start();
  };

  const handleSend = async (text: string = input) => {
    if (!isOnline) return;
    const messageToSend = text.trim();
    if (!messageToSend) return;

    const userMsg: ChatMessage = { role: 'user', text: messageToSend, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));

    try {
      const botResponse = await bfcAssistChat(messageToSend, history);
      setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Node failure. Try again, Boss! 😅", timestamp: new Date() }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[3000] font-sans">
      {isOpen ? (
        <div className="bg-white/90 dark:bg-gray-950/90 backdrop-blur-2xl w-[94vw] sm:w-[420px] h-[75vh] sm:h-[680px] rounded-[40px] shadow-[0_40px_100px_-20px_rgba(0,0,0,0.4)] flex flex-col border border-white/40 dark:border-white/5 overflow-hidden animate-slide-up ring-1 ring-black/5">

          {/* Elite Hub Header */}
          <div className="bg-gray-950 p-7 text-white relative overflow-hidden shrink-0 border-b border-white/5">
            <div className="absolute top-0 right-0 w-48 h-48 bg-red-600/20 rounded-full blur-[60px] -mr-24 -mt-24 animate-pulse"></div>

            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-4">
                <div className="relative">
                  <div className="w-14 h-14 bg-red-600 rounded-2xl flex items-center justify-center shadow-2xl border border-white/10 overflow-hidden">
                    <i className="fas fa-ghost text-xl"></i>
                  </div>
                  <div className={`absolute -bottom-1 -right-1 w-4 h-4 border-2 border-gray-950 rounded-full shadow-lg ${isOnline ? 'bg-emerald-500 animate-pulse' : 'bg-red-500'}`}></div>
                </div>
                <div>
                  <h3 className="font-black text-xl tracking-tighter uppercase italic leading-none">BFC Assist</h3>
                  <p className="text-[8px] font-black text-red-500 uppercase tracking-[3px] mt-1.5 opacity-80">Privileged AI Node</p>
                </div>
              </div>
              <button 
                onClick={() => setIsOpen(false)} 
                className="w-10 h-10 bg-white/5 hover:bg-white/10 rounded-xl flex items-center justify-center transition-all border border-white/10 group"
              >
                <i className="fas fa-chevron-down text-xs text-gray-400 group-hover:text-white group-hover:translate-y-0.5 transition-all"></i>
              </button>
            </div>
          </div>

          {/* Chat Feed */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 lg:p-8 space-y-6 scrollbar-hide bg-gradient-to-b from-transparent to-gray-50/50 dark:to-black/20">
            {!isOnline && (
              <div className="absolute inset-0 z-50 flex flex-col items-center justify-center bg-white/40 dark:bg-black/40 backdrop-blur-md p-10 text-center gap-4">
                 <i className="fas fa-tower-broadcast text-3xl text-red-600 animate-pulse"></i>
                 <p className="font-black text-[10px] uppercase tracking-[4px] text-gray-800 dark:text-gray-100">Connection Link Broken, Boss</p>
              </div>
            )}

            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                <div className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'} max-w-[88%]`}>
                  <div className={`px-5 py-3.5 rounded-[24px] text-[14px] font-bold leading-relaxed shadow-sm transition-all border ${
                    m.role === 'user' 
                    ? 'bg-gray-950 text-white rounded-br-none border-gray-800 shadow-xl' 
                    : 'bg-white dark:bg-gray-900 text-gray-800 dark:text-gray-200 rounded-tl-none border-gray-100 dark:border-white/5 shadow-md'
                  }`}>
                    {m.text}
                  </div>
                  <span className="text-[7px] mt-2 font-black tracking-[2px] opacity-20 dark:opacity-40 uppercase px-2 font-mono">
                    {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start animate-slide-up">
                <div className="bg-white dark:bg-gray-900 px-4 py-2.5 rounded-[18px] rounded-tl-none shadow-sm border border-gray-100 dark:border-white/5 flex gap-1.5 items-center">
