        <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
          <header className="h-20 bg-white/80 dark:bg-gray-900/80 backdrop-blur-xl border-b dark:border-gray-800 flex items-center justify-between px-6 lg:px-12 shrink-0 z-50 transition-colors">
            <div className="flex items-center gap-4">
              <button onClick={() => setSidebarOpen(true)} className="lg:hidden w-10 h-10 bg-gray-100 dark:bg-gray-800 rounded-xl flex items-center justify-center text-gray-600 dark:text-gray-400">
                <i className="fas fa-bars"></i>
              </button>
              <h2 className="text-base lg:text-xl font-black text-gray-800 dark:text-gray-100 tracking-tight uppercase truncate">
                {activeTab === 'dashboard' ? `${userRole} Portal` : `${activeTab} Interface`}
              </h2>
            </div>
            <div className="flex items-center gap-4">
              <button onClick={toggleTheme} className="w-10 h-10 flex items-center justify-center rounded-xl bg-gray-50 dark:bg-gray-800 text-gray-600 dark:text-amber-400 border border-gray-100 dark:border-gray-700 transition-all shadow-sm">
                <i className={`fas ${theme === 'light' ? 'fa-moon' : 'fa-sun'}`}></i>
              </button>
            </div>
