          <span className="text-[9px] font-black uppercase tracking-[3px]">System Offline • Restricted Mode Active</span>
        </div>
      )}

      <div className="fixed top-12 right-6 z-[1000] space-y-3 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} onClick={() => removeToast(t.id)} className="pointer-events-auto flex items-center gap-4 px-6 py-4 rounded-2xl shadow-2xl border bg-white animate-slide-up border-gray-100 ring-1 ring-black/5 cursor-pointer hover:scale-105 transition-transform">
            <div className={`w-8 h-8 rounded-xl shrink-0 flex items-center justify-center text-xs ${
              t.type === 'error' ? 'bg-red-50 text-red-600' : 
              t.type === 'warning' ? 'bg-amber-50 text-amber-600' :
              t.type === 'info' ? 'bg-blue-50 text-blue-600' : 'bg-emerald-50 text-emerald-600'
