import React, { useState, useEffect, useCallback } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
  persistent?: boolean;
}

const MOCK_AUTH_DB: Record<string, { pass: string, role: UserRole, name: string, phone: string }> = {
  'admin@bfc.com': { pass: 'admin123', role: UserRole.ADMIN, name: 'BFC Root Admin', phone: '01711-000111' },
  'manager@bfc.com': { pass: 'manager456', role: UserRole.MANAGER, name: 'Regional Manager', phone: '01711-000222' },
  'staff@bfc.com': { pass: 'staff789', role: UserRole.STAFF, name: 'Floor Supervisor', phone: '01711-000333' }
};

// Advanced Mock JWT Generator
const generateSecureToken = (role: UserRole, email: string) => {
  const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
  const payload = btoa(JSON.stringify({
    role,
    email,
    iat: Date.now(),
    exp: Date.now() + 3600000 // 1 Hour Expiry
  }));
  // Mock HMAC-SHA256 signature
  const signature = btoa(`bfc_master_secret_v4_${email}_${role}_${Date.now()}`);
  return `${header}.${payload}.${signature}`;
};

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE'>('HOME');
  const [activeCategory, setActiveCategory] = useState('All');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [loginAttempts, setLoginAttempts] = useState(0);
  const [isLockedOut, setIsLockedOut] = useState(false);

  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<Order['paymentMethod']>('BKASH');
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [mfsNumber, setMfsNumber] = useState('');
  const [deliveryInstructions, setDeliveryInstructions] = useState('');

  const showToast = useCallback((message: string, type: Toast['type'] = 'info', persistent: boolean = false) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, persistent }]);
    if (!persistent) {
      setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
    }
  }, []);

  // Session Recovery & Token Validation
  useEffect(() => {
    const savedSession = localStorage.getItem('bfc_user_session');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession) as User;
        if (user.sessionToken) {
          const payload = JSON.parse(atob(user.sessionToken.split('.')[1]));
          if (payload.exp > Date.now()) {
            setCurrentUser(user);
            if (user.role !== UserRole.CUSTOMER) setView('ADMIN');
          } else {
            localStorage.removeItem('bfc_user_session');
            showToast("Session expired. Please re-authenticate.", "warning");
          }
        }
      } catch (e) {
        localStorage.removeItem('bfc_user_session');
      }
    }
  }, [showToast]);

  useEffect(() => {
    const handleOnline = () => { 
      setIsOnline(true); 
      showToast('Network Restored! Systems are back online.', 'success'); 
    };
    const handleOffline = () => { 
      setIsOnline(false); 
      showToast('Connection Lost. Browsing in restricted mode.', 'error', true); 
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [showToast]);

  const handleAuth = async () => {
    if (isLockedOut) {
      showToast("Access blocked due to multiple failed attempts. Wait 60s.", "error");
      return;
    }

    if (!formEmail.trim() || !formPass.trim()) {
      showToast("Identity verification requires both credentials.", "warning");
      return;
    }

    setIsAuthenticating(true);
    try {
      // Cryptographic simulation delay
      await new Promise(r => setTimeout(r, 1500));
      const emailKey = formEmail.toLowerCase().trim();
      const privileged = MOCK_AUTH_DB[emailKey];

      if (privileged && privileged.pass === formPass) {
        const user: User = {
          id: `BFC-${Math.random().toString(36).slice(7).toUpperCase()}`,
          name: privileged.name, 
          email: emailKey, 
          phone: privileged.phone,
          role: privileged.role, 
          loyaltyPoints: 0, 
          tier: 'SILVER',
          wishlist: [], 
          referralCode: 'BFC-PRO',
          sessionToken: generateSecureToken(privileged.role, emailKey)
        };

        localStorage.setItem('bfc_user_session', JSON.stringify(user));
        setCurrentUser(user);
        setLoginAttempts(0);
        showToast(`Authentication Successful. Establish Node Link...`, 'success');
        setView(user.role === UserRole.CUSTOMER ? 'HOME' : 'ADMIN');
      } else {
        const newAttempts = loginAttempts + 1;
        setLoginAttempts(newAttempts);
        if (newAttempts >= 5) {
          setIsLockedOut(true);
          setTimeout(() => { setIsLockedOut(false); setLoginAttempts(0); }, 60000);
          showToast("CRITICAL: Maximum login attempts exceeded. Terminal locked.", "error");
        } else {
          showToast(`Invalid credentials. ${5 - newAttempts} attempts remaining before lockout.`, "error");
        }
      }
    } catch (err) {
      showToast("Handshake failed. Cryptographic error in auth layer.", "error");
    } finally {
      setIsAuthenticating(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('bfc_user_session');
    setCurrentUser(null);
    setView('HOME');
    showToast("Session Terminated. Secure Logout complete.", "info");
  };

  const handleCheckout = async () => {
    if (!isOnline) {
      showToast("Dispatch failed: Network required for secure payment.", "error");
      return;
    }

    if (cart.length === 0) {
      showToast("Your cart is empty. Add some delicacies first!", "warning");
      return;
    }

    if (paymentMethod !== 'COD') {
      const phoneRegex = /^01[3-9]\d{8}$/;
      if (!phoneRegex.test(mfsNumber)) {
        showToast(`Invalid ${paymentMethod} number. Use format: 017XXXXXXXX`, "error");
        return;
      }
    }

    setIsCheckingOut(true);
    try {
      await new Promise((resolve, reject) => {
        setTimeout(() => {
          Math.random() > 0.98 ? reject() : resolve(true);
        }, 2500);
      });

      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser?.id || 'GUEST',
        customerName: currentUser?.name || 'Guest User',
        customerPhone: mfsNumber || currentUser?.phone || '01XXXXXXXXX',
        items: cart.map(c => ({
          menuId: c.item.id,
          quantity: c.qty,
          price: c.item.price,
          name: c.item.name
        })),
        total: cart.reduce((a, b) => a + (b.item.price * b.qty), 0),
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: paymentMethod === 'COD' ? 'UNPAID' : 'PAID',
        paymentMethod,
        address: 'Dhaka',
        deliveryZone: 'Dhaka',
        deliverySlot: 'ASAP',
        deliveryInstructions: deliveryInstructions.trim() || undefined,
        pointsEarned: 0,
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };

      setAllOrders(prev => [newOrder, ...prev]);
      setCart([]);
      setMfsNumber('');
      setDeliveryInstructions('');
      showToast(`Order Placed! Courier will be assigned soon.`, "success");
      setView('TRACKING');
    } catch (err) {
      showToast("Payment Gateway Timeout. Please try again or choose COD.", "error");
    } finally {
      setIsCheckingOut(false);
    }
  };

  const removeToast = (id: number) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  if (view === 'ADMIN' && currentUser && currentUser.role !== UserRole.CUSTOMER) {
    return (
      <AdminPanel 
        userRole={currentUser.role} 
        onLogout={handleLogout}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans">
      {!isOnline && (
        <div className="fixed top-0 left-0 w-full z-[3000] bg-red-600 text-white py-1.5 px-6 flex items-center justify-center gap-3 animate-pulse">
          <i className="fas fa-wifi-slash text-[10px]"></i>
          <span className="text-[9px] font-black uppercase tracking-[3px]">System Offline • Restricted Mode Active</span>
        </div>
      )}

      {/* Global Toast Notification System */}
      <div className="fixed top-12 right-6 z-[4000] space-y-3 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} onClick={() => removeToast(t.id)} className="pointer-events-auto flex items-center gap-4 px-6 py-4 rounded-2xl shadow-2xl border bg-white animate-slide-up border-gray-100 ring-1 ring-black/5 cursor-pointer hover:scale-105 transition-transform">
            <div className={`w-8 h-8 rounded-xl shrink-0 flex items-center justify-center text-xs ${
              t.type === 'error' ? 'bg-red-50 text-red-600' : 
              t.type === 'warning' ? 'bg-amber-50 text-amber-600' :
              t.type === 'info' ? 'bg-blue-50 text-blue-600' : 'bg-emerald-50 text-emerald-600'
            }`}>
              <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark' : t.type === 'warning' ? 'fa-triangle-exclamation' : t.type === 'info' ? 'fa-info-circle' : 'fa-circle-check'}`}></i>
            </div>
            <p className="font-bold text-[10px] text-gray-800 uppercase tracking-tight leading-tight">{t.message}</p>
          </div>
        ))}
      </div>

      <nav className={`sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-12 py-4 flex justify-between items-center transition-transform ${!isOnline ? 'translate-y-[28px]' : ''}`}>
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setView('HOME')}>
          <div className="w-9 h-9 bg-red-600 rounded-xl flex items-center justify-center text-white text-lg font-black shadow-lg">B</div>
          <h1 className="text-xl font-black text-red-600 tracking-tighter">BFC</h1>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center">
            <i className="fas fa-shopping-basket text-gray-600"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[8px] w-5 h-5 rounded-full flex items-center justify-center ring-2 ring-white font-black">{cart.length}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 rounded-xl bg-gray-950 text-white font-black flex items-center justify-center overflow-hidden border-2 border-white shadow-md">
               {currentUser.profileImage ? <img src={currentUser.profileImage} className="w-full h-full object-cover" /> : currentUser.name.charAt(0)}
            </button>
          ) : (
            <Button size="sm" className="rounded-xl px-5 py-2 text-xs" onClick={() => setView('LOGIN')}>Login</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-12">
        {view === 'HOME' && (
