import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { Button } from './Button';
import { ChatBot } from './ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, BarChart, Bar
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 },
  { name: 'Sun', sales: 3800 },
  { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 },
  { name: 'Wed', sales: 6200 },
  { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

const CATEGORY_DATA = [
  { name: 'Biryani', value: 45, color: '#dc2626' },
  { name: 'Kebab', value: 25, color: '#ea580c' },
  { name: 'Curry', value: 20, color: '#f59e0b' },
  { name: 'Desserts', value: 10, color: '#10b981' },
];

const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  [UserRole.ADMIN]: ['dashboard', 'orders', 'menu', 'inventory', 'customers', 'reports', 'security'],
  [UserRole.MANAGER]: ['dashboard', 'orders', 'inventory', 'customers', 'reports'],
  [UserRole.STAFF]: ['dashboard', 'orders', 'inventory'],
  [UserRole.CUSTOMER]: []
};

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const allowedTabs = useMemo(() => ROLE_PERMISSIONS[userRole] || [], [userRole]);
  const [activeTab, setActiveTab] = useState(allowedTabs[0] || 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(3600);
  const [adminToast, setAdminToast] = useState<{msg: string, type: 'success' | 'error' | 'warning' | 'info'} | null>(null);
  const [customers, setCustomers] = useState<any[]>([]);
  const [orderFilter, setOrderFilter] = useState('');
  const [inventorySearch, setInventorySearch] = useState('');

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('bfc_admin_theme') as 'light' | 'dark') || 'light';
  });

  const showToast = useCallback((msg: string, type: 'success' | 'error' | 'warning' | 'info') => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const verifyAccess = useCallback(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (!savedUser) return false;
    try {
      const user = JSON.parse(savedUser) as User;
      if (!user.sessionToken) return false;
      const parts = user.sessionToken.split('.');
      if (parts.length !== 3) return false;

      const payload = JSON.parse(atob(parts[1]));
      // Strictly verify time and role alignment
      if (payload.exp < Date.now()) return false;
      if (payload.role !== userRole) return false;

      setSessionTimeLeft(Math.max(0, Math.round((payload.exp - Date.now()) / 1000)));
      return true;
    } catch { return false; }
  }, [userRole]);

  // Security Heartbeat - Runs every 2 seconds to ensure session integrity
  useEffect(() => {
    const heartbeat = setInterval(() => {
      if (!verifyAccess()) {
        showToast("CRITICAL: Session compromised or expired. Evacuating node...", "error");
        clearInterval(heartbeat);
        setTimeout(onLogout, 1500);
      }
    }, 2000);

    if (verifyAccess()) {
      setIsAuthorized(true);
    } else {
      onLogout();
    }

    return () => clearInterval(heartbeat);
  }, [verifyAccess, onLogout, showToast]);

  useEffect(() => {
    localStorage.setItem('bfc_admin_theme', theme);
  }, [theme]);

  const toggleTheme = () => setTheme(prev => prev === 'light' ? 'dark' : 'light');

  useEffect(() => {
    const raw = localStorage.getItem('bfc_customers');
    if (raw) {
      try {
        const data = JSON.parse(raw);
        setCustomers(Object.values(data));
      } catch (e) { setCustomers([]); }
    } else {
      setCustomers([
        { name: 'Arif Khan', email: 'arif@demo.com', tier: 'PLATINUM' },
        { name: 'Sumon Ahmed', email: 'sumon@demo.com', tier: 'GOLD' },
        { name: 'Fahim Islam', email: 'fahim@demo.com', tier: 'SILVER' },
      ]);
    }
  }, []);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order #${orderId.slice(-4)} updated to ${newStatus}.`, 'success');
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) return item;
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length,
    };
  }, [orders, menuItems]);

  const todaysOrders = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return orders.filter(o => o.createdAt.startsWith(today));
  }, [orders]);

  const renderDashboardContent = () => {
    if (userRole === UserRole.STAFF) {
      return (
        <div className="space-y-8">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div>
              <h3 className="text-3xl font-black text-gray-900 dark:text-gray-100 tracking-tighter italic">LIVE QUEUE</h3>
              <p className="text-[9px] font-black text-red-600 uppercase tracking-[4px]">Floor Surveillance Terminal</p>
            </div>
            <div className="bg-white dark:bg-gray-900 px-6 py-3 rounded-2xl border dark:border-gray-800 shadow-sm flex items-center gap-4">
               <div className="text-right">
                  <p className="text-[7px] font-black text-gray-400 uppercase tracking-widest">Active Orders</p>
                  <p className="text-xl font-black dark:text-white">{todaysOrders.length}</p>
               </div>
               <div className="w-10 h-10 bg-emerald-500 rounded-xl flex items-center justify-center text-white shadow-lg animate-pulse">
                  <i className="fas fa-bolt"></i>
               </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {todaysOrders.length === 0 ? (
              <div className="col-span-full py-20 text-center bg-white dark:bg-gray-900 rounded-[45px] border-2 border-dashed border-gray-100 dark:border-gray-800">
                <i className="fas fa-mug-hot text-4xl text-gray-200 mb-4"></i>
                <p className="font-black text-gray-300 uppercase tracking-[5px]">All Clear, Boss!</p>
              </div>
            ) : (
              todaysOrders.map(o => (
                <div key={o.id} className="bg-white dark:bg-gray-900 p-6 rounded-[35px] border border-gray-50 dark:border-gray-800 shadow-sm hover:shadow-xl transition-all">
                  <div className="flex justify-between mb-4">
                    <div>
                       <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest">ID: #{o.id.slice(-4)}</p>
                       <h4 className="font-black text-gray-900 dark:text-gray-100">{o.customerName}</h4>
                    </div>
                    <span className={`h-fit px-3 py-1 rounded-lg text-[7px] font-black uppercase tracking-widest ${o.status === OrderStatus.READY ? 'bg-emerald-100 text-emerald-700' : 'bg-red-50 text-red-600'}`}>
                      {o.status}
                    </span>
                  </div>
                  <div className="bg-gray-50 dark:bg-gray-800/50 p-4 rounded-2xl mb-4 text-[10px] font-bold text-gray-600 dark:text-gray-400">
                    {o.items.map((it, idx) => (
                      <div key={idx} className="flex justify-between">
                        <span>{it.quantity}x {it.name}</span>
                        <span>৳{it.price * it.quantity}</span>
                      </div>
                    ))}
                  </div>
                  <div className="flex gap-2">
                     <button onClick={() => handleUpdateStatus(o.id, OrderStatus.PREPARING)} className="flex-1 py-3 bg-gray-100 dark:bg-gray-800 text-gray-950 dark:text-white rounded-xl text-[8px] font-black uppercase tracking-widest border border-gray-200 dark:border-gray-700">Prepare</button>
                     <button onClick={() => handleUpdateStatus(o.id, OrderStatus.READY)} className="flex-1 py-3 bg-red-600 text-white rounded-xl text-[8px] font-black uppercase tracking-widest shadow-lg shadow-red-600/20">Ready</button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      );
    }

    if (userRole === UserRole.MANAGER) {
      return (
        <div className="space-y-10">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <StatCard title="Today's Revenue" value={`৳${stats.revenue.toLocaleString()}`} icon="fa-taka-sign" color="text-red-600" />
            <StatCard title="Active Pool" value={stats.orderCount} icon="fa-list-check" color="text-blue-600" />
            <StatCard title="Inventory Alerts" value={stats.lowStock} icon="fa-box-open" color="text-amber-500" />
            <StatCard title="Staff Active" value="12" icon="fa-id-card-clip" color="text-purple-600" />
          </div>

          <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
            <div className="xl:col-span-2 bg-white dark:bg-gray-900 p-8 rounded-[45px] border border-gray-100 dark:border-gray-800 shadow-sm">
               <div className="flex justify-between items-center mb-8">
                  <h4 className="text-xs font-black uppercase tracking-widest text-gray-400">Recent Movements</h4>
                  <button onClick={() => setActiveTab('orders')} className="text-[8px] font-black text-red-600 uppercase tracking-widest">Full List</button>
               </div>
               <div className="space-y-4">
                  {orders.slice(0, 4).map(o => (
                    <div key={o.id} className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-800/50 rounded-2xl border dark:border-gray-700">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-white dark:bg-gray-900 rounded-xl flex items-center justify-center text-xs shadow-sm border dark:border-gray-700">#{o.id.slice(-4)}</div>
                        <div>
                          <p className="font-black text-[12px] dark:text-white">{o.customerName}</p>
                          <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest">৳{o.total} • {o.paymentMethod}</p>
                        </div>
                      </div>
                      <span className="px-3 py-1 bg-white dark:bg-gray-900 rounded-lg text-[7px] font-black uppercase tracking-widest border dark:border-gray-700 dark:text-white">{o.status}</span>
                    </div>
                  ))}
               </div>
            </div>

            <div className="bg-gray-950 p-8 rounded-[45px] text-white flex flex-col justify-between overflow-hidden relative shadow-2xl">
               <div className="absolute top-0 right-0 w-40 h-40 bg-red-600/20 rounded-full blur-[80px] -mr-20 -mt-20"></div>
               <div className="relative z-10">
                  <h4 className="text-[10px] font-black uppercase tracking-[3px] text-gray-500 mb-8 italic">Inventory Pulse</h4>
                  <div className="space-y-6">
                    {menuItems.slice(0, 3).map(item => (
                      <div key={item.id} className="flex items-center justify-between">
                         <div className="flex items-center gap-3">
                            <div className="w-2 h-2 rounded-full bg-red-600"></div>
                            <span className="text-[11px] font-black uppercase tracking-tighter truncate w-24">{item.name}</span>
                         </div>
                         <span className={`text-xl font-black ${item.stock < 10 ? 'text-red-500' : 'text-white'}`}>{item.stock}</span>
                      </div>
                    ))}
                  </div>
               </div>
               <button onClick={() => setActiveTab('inventory')} className="mt-10 w-full py-4 bg-white/5 hover:bg-white/10 rounded-2xl border border-white/5 text-[8px] font-black uppercase tracking-[4px] transition-all">Manage Stock</button>
            </div>
          </div>
        </div>
      );
    }

    // Default Admin Dashboard
    return (
      <div className="space-y-10">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 lg:gap-6">
          <StatCard title="Revenue" value={`৳${stats.revenue.toLocaleString()}`} icon="fa-taka-sign" color="text-red-600" />
          <StatCard title="Total Orders" value={stats.orderCount} icon="fa-box" color="text-blue-600" />
          <StatCard title="Pending" value={stats.pending} icon="fa-clock" color="text-purple-600" />
          <StatCard title="Low Stock" value={stats.lowStock} icon="fa-triangle-exclamation" color="text-amber-500" />
        </div>

        <div className="grid grid-cols-1 xl:grid-cols-2 gap-6 lg:gap-10">
          <div className="bg-white dark:bg-gray-900 p-6 rounded-[32px] border border-gray-100 dark:border-gray-800 shadow-sm min-h-[350px]">
             <h3 className="text-[10px] font-black mb-6 uppercase tracking-[3px] text-gray-400 dark:text-gray-500">Sales Analytics</h3>
             <div className="h-[250px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={ANALYTICS_DATA}>
                    <defs>
                      <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#dc2626" stopOpacity={0.1}/>
                        <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#1f2937' : '#F1F5F9'} />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 9, fontWeight: 'bold', fill: theme === 'dark' ? '#9ca3af' : '#4b5563'}} />
                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 9, fontWeight: 'bold', fill: theme === 'dark' ? '#9ca3af' : '#4b5563'}} />
                    <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', backgroundColor: theme === 'dark' ? '#111827' : '#ffffff', color: theme === 'dark' ? '#f3f4f6' : '#111827' }} />
                    <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={3} fill="url(#colorSales)" />
                  </AreaChart>
                </ResponsiveContainer>
             </div>
          </div>

          <div className="bg-white dark:bg-gray-900 p-6 rounded-[32px] border border-gray-100 dark:border-gray-800 shadow-sm min-h-[350px]">
             <h3 className="text-[10px] font-black mb-6 uppercase tracking-[3px] text-gray-400 dark:text-gray-500">Category Mix</h3>
             <div className="h-[250px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={CATEGORY_DATA} innerRadius="60%" outerRadius="80%" paddingAngle={5} dataKey="value" stroke="none">
                      {CATEGORY_DATA.map((entry, idx) => <Cell key={idx} fill={entry.color} />)}
                    </Pie>
                    <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', backgroundColor: theme === 'dark' ? '#111827' : '#ffffff', color: theme === 'dark' ? '#f3f4f6' : '#111827' }} />
                  </PieChart>
                </ResponsiveContainer>
             </div>
          </div>
        </div>
      </div>
    );
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white p-6 text-center">
      <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin mb-6"></div>
      <p className="text-[10px] font-black uppercase tracking-[8px] animate-pulse">Establishing Secure Node Link...</p>
    </div>
  );

  return (
    <div className={theme === 'dark' ? 'dark' : ''}>
      <div className="flex h-screen bg-[#F8FAFC] dark:bg-gray-950 overflow-hidden font-sans transition-colors duration-300">
        {adminToast && (
          <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[5000] px-6 py-4 rounded-2xl shadow-2xl border animate-slide-up flex items-center gap-4 w-[90%] sm:w-auto max-w-md ${
            adminToast.type === 'error' ? 'bg-red-600 border-red-400 text-white' : 
            adminToast.type === 'warning' ? 'bg-amber-500 border-amber-400 text-white' : 
            adminToast.type === 'info' ? 'bg-blue-600 border-blue-400 text-white' : 'bg-gray-900 border-white/10 text-white'
          }`}>
            <i className={`fas ${adminToast.type === 'success' ? 'fa-circle-check' : adminToast.type === 'error' ? 'fa-circle-xmark' : adminToast.type === 'info' ? 'fa-info-circle' : 'fa-triangle-exclamation'}`}></i>
            <span className="text-[10px] font-black uppercase tracking-widest leading-snug">{adminToast.msg}</span>
          </div>
        )}

        {isSidebarOpen && (
          <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[200] lg:hidden" onClick={() => setSidebarOpen(false)} />
        )}

        <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 bg-white dark:bg-gray-900 border-r border-gray-100 dark:border-gray-800 transition-transform duration-300 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
          <div className="p-8 flex items-center justify-between border-b border-gray-50 dark:border-gray-800">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white shadow-lg"><i className="fas fa-terminal"></i></div>
              <h1 className="text-xl font-black text-gray-800 dark:text-gray-100 tracking-tighter">BFC HUB</h1>
            </div>
            <button className="lg:hidden w-10 h-10 flex items-center justify-center text-gray-300" onClick={() => setSidebarOpen(false)}><i className="fas fa-times"></i></button>
          </div>

          <nav className="p-6 space-y-1 overflow-y-auto h-[calc(100vh-280px)] scrollbar-hide">
            {allowedTabs.map(tab => (
