              <button onClick={() => setSidebarOpen(true)} className="lg:hidden w-10 h-10 bg-gray-100 dark:bg-gray-800 rounded-xl flex items-center justify-center text-gray-600 dark:text-gray-400">
                <i className="fas fa-bars"></i>
              </button>
              <h2 className="text-base lg:text-xl font-black text-gray-800 dark:text-gray-100 tracking-tight uppercase truncate">
                {activeTab === 'dashboard' ? `${userRole} Portal` : `${activeTab} Interface`}
