            </div>
            <div className="flex items-center gap-4">
              <button onClick={toggleTheme} className="w-10 h-10 flex items-center justify-center rounded-xl bg-gray-50 dark:bg-gray-800 text-gray-600 dark:text-amber-400 border border-gray-100 dark:border-gray-700 transition-all shadow-sm">
                <i className={`fas ${theme === 'light' ? 'fa-moon' : 'fa-sun'}`}></i>
              </button>
            </div>
          </header>

          <main className="flex-1 overflow-y-auto p-4 lg:p-10 space-y-10 animate-slide-up scrollbar-hide scroll-smooth">
            {activeTab === 'dashboard' && renderDashboardContent()}

            {activeTab === 'orders' && (
               <div className="space-y-6">
                 <div className="flex flex-col sm:flex-row gap-4 mb-6">
                    <div className="relative flex-1">
                       <i className="fas fa-search absolute left-4 top-1/2 -translate-y-1/2 text-gray-400"></i>
                       <input 
                        type="text" 
                        placeholder="Search Orders..." 
                        value={orderFilter}
                        onChange={(e) => setOrderFilter(e.target.value)}
                        className="w-full bg-white dark:bg-gray-900 border-2 border-gray-100 dark:border-gray-800 rounded-2xl py-4 pl-12 pr-6 text-sm font-bold outline-none focus:border-red-600 transition-all dark:text-white"
                       />
                    </div>
                 </div>
                 <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                   {orders.filter(o => o.customerName.toLowerCase().includes(orderFilter.toLowerCase())).map(o => (
                    <div key={o.id} className="bg-white dark:bg-gray-900 p-6 rounded-[32px] border border-gray-50 dark:border-gray-800 flex flex-col gap-5 hover:shadow-xl transition-all">
                      <div className="flex justify-between items-start">
                         <div className="flex items-center gap-3">
                            <div className="w-10 h-10 bg-gray-950 dark:bg-gray-800 text-white rounded-xl flex items-center justify-center font-black text-[10px] shadow-lg">#{o.id.slice(-4)}</div>
                            <div className="min-w-0">
                              <p className="font-black text-gray-800 dark:text-gray-100 text-xs truncate">{o.customerName}</p>
                              {o.customerPhone && <p className="text-[10px] font-black text-red-600/70 tracking-tighter"><i className="fas fa-phone-alt scale-75"></i> {o.customerPhone}</p>}
                            </div>
                         </div>
                         <span className={`px-3 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest ${o.status === OrderStatus.DELIVERED ? 'bg-emerald-100 text-emerald-700' : 'bg-red-50 text-red-600'}`}>
                           {o.status}
                         </span>
                      </div>
                      <select className="w-full bg-white dark:bg-gray-800 border-2 border-gray-100 dark:border-gray-700 dark:text-white rounded-2xl p-3 text-[10px] font-black uppercase tracking-widest outline-none focus:border-red-600 transition-all cursor-pointer" value={o.status} onChange={(e) => handleUpdateStatus(o.id, e.target.value as OrderStatus)}>
                        {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                    </div>
                   ))}
                 </div>
               </div>
            )}

            {activeTab === 'inventory' && (
              <div className="space-y-8">
                 <div className="flex flex-col sm:flex-row gap-4">
                    <div className="relative flex-1">
