                       <input 
                        type="text" 
                        placeholder="Search Inventory..." 
                        value={inventorySearch}
                        onChange={(e) => setInventorySearch(e.target.value)}
                        className="w-full bg-white dark:bg-gray-900 border-2 border-gray-100 dark:border-gray-800 rounded-2xl py-4 pl-12 pr-6 text-sm font-bold outline-none focus:border-red-600 transition-all dark:text-white"
                       />
                    </div>
                 </div>
                 <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                   {menuItems.filter(i => i.name.toLowerCase().includes(inventorySearch.toLowerCase())).map(item => (
                     <div key={item.id} className="bg-white dark:bg-gray-900 p-6 rounded-[32px] border border-gray-100 dark:border-gray-800 flex flex-col items-center text-center shadow-sm hover:shadow-lg transition-all">
                        <div className="relative mb-4">
                          <img src={item.image} className="w-16 h-16 rounded-2xl object-cover shadow-md" alt={item.name} />
                          {item.stock < 10 && <div className="absolute -top-1 -right-1 w-5 h-5 bg-red-600 text-white rounded-full flex items-center justify-center text-[8px] ring-2 ring-white dark:ring-gray-900"><i className="fas fa-exclamation"></i></div>}
                        </div>
                        <h4 className="font-black text-gray-800 dark:text-gray-100 text-xs mb-1 truncate w-full px-2">{item.name}</h4>
                        <p className={`text-3xl font-black mb-4 ${item.stock < 10 ? 'text-red-600' : 'text-gray-950 dark:text-white'}`}>{item.stock}</p>
                        <div className="flex gap-2 w-full">
                           <button onClick={()=>handleUpdateStock(item.id, false)} className="flex-1 bg-gray-50 dark:bg-gray-800 dark:text-gray-300 py-2 rounded-xl font-black text-xs">-</button>
                           <button onClick={()=>handleUpdateStock(item.id, true)} className="flex-1 bg-gray-900 dark:bg-gray-700 text-white py-2 rounded-xl font-black text-xs">+</button>
                        </div>
                     </div>
                   ))}
                 </div>
              </div>
            )}

            {activeTab === 'customers' && (
              <div className="bg-white dark:bg-gray-900 rounded-[45px] border border-gray-100 dark:border-gray-800 shadow-sm overflow-hidden flex flex-col">
                <div className="p-8 border-b dark:border-gray-800 flex justify-between items-center gap-4 bg-gray-50/20 dark:bg-gray-800/10">
                   <h3 className="font-black text-gray-900 dark:text-gray-100 text-sm uppercase italic">Member Registry</h3>
                </div>
                <div className="overflow-x-auto w-full scrollbar-hide">
                  <table className="w-full text-left min-w-[700px]">
                    <thead>
                      <tr className="bg-gray-50/50 dark:bg-gray-800/30 border-b border-gray-100 dark:border-gray-800 text-[9px] font-black uppercase tracking-[3px] text-gray-400 dark:text-gray-500">
                         <th className="px-8 py-5">Name</th>
                         <th className="px-8 py-5">Tier</th>
                         <th className="px-8 py-5">Action</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50 dark:divide-gray-800 text-[11px] font-bold text-gray-700 dark:text-gray-300">
                      {customers.map((c, idx) => (
                        <tr key={idx} className="hover:bg-red-50/30 dark:hover:bg-red-900/10 transition-all cursor-default group">
                          <td className="px-8 py-5 font-black text-gray-900 dark:text-gray-100 group-hover:text-red-600">{c.name}</td>
                          <td className="px-8 py-5">
                            <span className={`px-4 py-1.5 rounded-xl text-[7px] font-black uppercase tracking-widest border ${
                              c.tier === 'PLATINUM' ? 'bg-indigo-50 dark:bg-indigo-900/10 text-indigo-600 dark:text-indigo-400 border-indigo-100 dark:border-indigo-900/20' :
                              c.tier === 'GOLD' ? 'bg-amber-50 dark:bg-amber-900/10 text-amber-600 dark:text-amber-400 border-amber-100 dark:border-amber-900/20' :
                              'bg-gray-100 dark:bg-gray-800 text-gray-400 dark:text-gray-500 border-gray-200 dark:border-gray-700'
                            }`}>
                              {c.tier}
                            </span>
                          </td>
                          <td className="px-8 py-5">
                            <button className="w-10 h-10 rounded-xl bg-gray-100 dark:bg-gray-800 text-gray-300 flex items-center justify-center hover:bg-gray-900 dark:hover:bg-white hover:text-white dark:hover:text-gray-950 transition-all">
                              <i className="fas fa-ellipsis-v"></i>
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </main>
        </div>
      </div>
      <ChatBot isOnline={true} />
    </div>
  );
};

const SidebarBtn = ({ active, onClick, icon, label, theme }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl transition-all border-2 group ${
    active 
    ? 'bg-red-600 border-red-600 text-white shadow-lg' 
    : 'bg-transparent border-transparent text-gray-400 dark:text-gray-500 hover:bg-red-50 dark:hover:bg-red-900/10 hover:text-red-600'
  }`}>
    <div className="w-6 flex justify-center shrink-0"><i className={`fas ${icon} text-lg transition-transform group-hover:rotate-12`}></i></div>
    <span className="font-black text-[10px] uppercase tracking-[3px] whitespace-nowrap">{label} Node</span>
  </button>
);

const StatCard = ({ title, value, icon, color }: any) => (
  <div className="bg-white dark:bg-gray-900 p-6 rounded-[32px] border border-gray-100 dark:border-gray-800 flex items-center gap-4 hover:shadow-xl transition-all h-full">
    <div className={`w-12 h-12 bg-gray-50 dark:bg-gray-800 rounded-2xl flex items-center justify-center text-lg ${color} shrink-0`}><i className={`fas ${icon}`}></i></div>
    <div className="min-w-0">
      <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest mb-1 truncate">{title}</p>
      <h4 className="text-xl font-black text-gray-900 dark:text-gray-100 tracking-tighter truncate leading-none">{value}</h4>
    </div>
  </div>
);

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { Button } from './Button';
import { ChatBot } from './ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 },
  { name: 'Sun', sales: 3800 },
  { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 },
  { name: 'Wed', sales: 6200 },
  { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

const CATEGORY_DATA = [
  { name: 'Biryani', value: 45, color: '#dc2626' },
  { name: 'Kebab', value: 25, color: '#ea580c' },
  { name: 'Curry', value: 20, color: '#f59e0b' },
  { name: 'Desserts', value: 10, color: '#10b981' },
];

const BEHAVIOR_DATA = [
  { segment: 'Loyalists', users: 120, revenue: 45000 },
  { segment: 'Newcomers', users: 340, revenue: 22000 },
  { segment: 'At Risk', users: 45, revenue: 8000 },
  { segment: 'Inactive', users: 80, revenue: 1200 },
];

const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  [UserRole.ADMIN]: ['dashboard', 'orders', 'menu', 'inventory', 'customers', 'reports', 'security'],
  [UserRole.MANAGER]: ['dashboard', 'orders', 'inventory', 'customers', 'reports'],
  [UserRole.STAFF]: ['dashboard', 'orders', 'inventory'],
  [UserRole.CUSTOMER]: []
};

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, 
  onLogout, 
  menuItems, 
  setMenuItems, 
  orders, 
  setOrders 
}) => {
  const allowedTabs = useMemo(() => ROLE_PERMISSIONS[userRole] || [], [userRole]);
  const [activeTab, setActiveTab] = useState(allowedTabs[0] || 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(3600);
  const [adminToast, setAdminToast] = useState<{msg: string, type: 'success' | 'error' | 'warning' | 'info'} | null>(null);
  const [customers, setCustomers] = useState<any[]>([]);
  const [orderFilter, setOrderFilter] = useState('');
  const [inventorySearch, setInventorySearch] = useState('');
  const [reportType, setReportType] = useState<'sales' | 'inventory' | 'behavior'>('sales');

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('bfc_admin_theme') as 'light' | 'dark') || 'light';
  });

  const showToast = useCallback((msg: string, type: 'success' | 'error' | 'warning' | 'info') => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const verifyAccess = useCallback(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (!savedUser) return false;
    try {
      const user = JSON.parse(savedUser) as User;
      if (!user.sessionToken) return false;
      const parts = user.sessionToken.split('.');
      if (parts.length !== 3) return false;

      const payload = JSON.parse(atob(parts[1]));
      if (payload.exp < Date.now()) return false;
      if (payload.role !== userRole) return false;

      setSessionTimeLeft(Math.max(0, Math.round((payload.exp - Date.now()) / 1000)));
      return true;
    } catch { return false; }
  }, [userRole]);

  useEffect(() => {
    const heartbeat = setInterval(() => {
      if (!verifyAccess()) {
        showToast("CRITICAL: Session compromised or expired. Evacuating node...", "error");
        clearInterval(heartbeat);
        setTimeout(onLogout, 1500);
      }
    }, 2000);

    if (verifyAccess()) {
      setIsAuthorized(true);
    } else {
      onLogout();
    }

    return () => clearInterval(heartbeat);
  }, [verifyAccess, onLogout, showToast]);

  useEffect(() => {
    localStorage.setItem('bfc_admin_theme', theme);
  }, [theme]);

  const toggleTheme = () => setTheme(prev => prev === 'light' ? 'dark' : 'light');

  useEffect(() => {
    const raw = localStorage.getItem('bfc_customers');
    if (raw) {
      try {
        const data = JSON.parse(raw);
        setCustomers(Object.values(data));
      } catch (e) { setCustomers([]); }
    } else {
      setCustomers([
        { name: 'Arif Khan', email: 'arif@demo.com', tier: 'PLATINUM' },
        { name: 'Sumon Ahmed', email: 'sumon@demo.com', tier: 'GOLD' },
        { name: 'Fahim Islam', email: 'fahim@demo.com', tier: 'SILVER' },
      ]);
    }
  }, []);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order #${orderId.slice(-4)} updated to ${newStatus}.`, 'success');
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) return item;
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  const stats = useMemo(() => {
    const revenue = orders.reduce((acc, o) => acc + o.total, 0);
    return {
      revenue,
      orderCount: orders.length,
      pending: orders.filter(o => o.status === OrderStatus.PENDING).length,
      lowStock: menuItems.filter(i => i.stock < 10).length,
    };
  }, [orders, menuItems]);

  const todaysOrders = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return orders.filter(o => o.createdAt.startsWith(today));
  }, [orders]);

  // --- Export Functionality ---
  const handleExportCSV = () => {
    let csvContent = "data:text/csv;charset=utf-8,";
    let filename = `BFC_Report_${reportType}_${new Date().toISOString().split('T')[0]}.csv`;

    if (reportType === 'sales') {
      csvContent += "Order ID,Customer,Total,Status,Payment,Date\n";
      orders.forEach(o => {
        csvContent += `${o.id},"${o.customerName}",${o.total},${o.status},${o.paymentMethod},${o.createdAt}\n`;
      });
    } else if (reportType === 'inventory') {
      csvContent += "Item ID,Name,Category,Stock,Price\n";
      menuItems.forEach(i => {
        csvContent += `${i.id},"${i.name}",${i.category},${i.stock},${i.price}\n`;
      });
    } else if (reportType === 'behavior') {
      csvContent += "Segment,User Count,Total Revenue\n";
      BEHAVIOR_DATA.forEach(d => {
        csvContent += `"${d.segment}",${d.users},${d.revenue}\n`;
      });
    }

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast("Report generated as CSV (Excel compatible).", "success");
  };

  const handleExportPDF = () => {
    showToast("Preparing printable layout for PDF conversion...", "info");
    setTimeout(() => {
      window.print();
    }, 500);
  };

  const renderDashboardContent = () => {
