import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 }, { name: 'Sun', sales: 3800 }, { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 }, { name: 'Wed', sales: 6200 }, { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

const BFC_JWT_SECRET = "bfc_secure_node_alpha_v5_2024";

const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  [UserRole.ADMIN]: ['dashboard', 'orders', 'inventory', 'customers', 'reports', 'audit'],
  [UserRole.MANAGER]: ['dashboard', 'orders', 'inventory', 'reports'],
  [UserRole.STAFF]: ['dashboard', 'orders', 'inventory'],
  [UserRole.CUSTOMER]: []
};

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, onLogout, menuItems, setMenuItems, orders, setOrders 
}) => {
  const allowedTabs = useMemo(() => ROLE_PERMISSIONS[userRole] || [], [userRole]);
  const [activeTab, setActiveTab] = useState(allowedTabs[0] || 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(3600);
  const [adminToast, setAdminToast] = useState<{msg: string, type: string} | null>(null);
  const [reportType, setReportType] = useState<'sales' | 'inventory'>('sales');
  const [auditLogs] = useState([
    { event: 'LOGIN_SUCCESS', user: 'admin@bfc.com', time: '10:00:05 AM', status: 'OK' },
    { event: 'STOCK_UPDATE', user: 'staff@bfc.com', time: '10:15:20 AM', status: 'OK' },
    { event: 'ORDER_PREPARED', user: 'staff@bfc.com', time: '10:45:00 AM', status: 'OK' },
  ]);

  const showToast = useCallback((msg: string, type: string) => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const verifyAccess = useCallback(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (!savedUser) return false;
    try {
      const user = JSON.parse(savedUser) as User;
      if (!user.sessionToken) return false;
      const parts = user.sessionToken.split('.');
      if (parts.length !== 3) return false;

      const payload = JSON.parse(atob(parts[1]));
      const sig = parts[2];

      // Strict signature and role verification
      if (sig !== btoa(`${BFC_JWT_SECRET}.${parts[1]}.${user.role}`)) return false;
      if (payload.exp < Date.now()) return false;
      if (payload.role !== userRole) return false;

      setSessionTimeLeft(Math.max(0, Math.round((payload.exp - Date.now()) / 1000)));
      return true;
    } catch { return false; }
  }, [userRole]);

  useEffect(() => {
    const heartbeat = setInterval(() => {
      if (!verifyAccess()) {
        showToast("Session compromise detected. Disconnecting.", "error");
        setTimeout(onLogout, 1000);
      }
    }, 2000);
    if (verifyAccess()) setIsAuthorized(true); else onLogout();
    return () => clearInterval(heartbeat);
  }, [verifyAccess, onLogout, showToast]);

  const handleExportCSV = () => {
    const data = reportType === 'sales' ? orders : menuItems;
    const csvRows = [["ID", "Name", "Meta", "Value"]];
    data.forEach((o: any) => csvRows.push([o.id, o.customerName || o.name, o.status || o.category, o.total || o.stock]));

    const blob = new Blob([csvRows.map(r => r.join(",")).join("\n")], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `BFC_Report_${Date.now()}.csv`;
    link.click();
    showToast("Report Exported.", "success");
  };

  if (!isAuthorized) return <div className="h-screen bg-gray-950 flex items-center justify-center text-white">Authenticating...</div>;

  return (
    <div className="flex h-screen bg-[#F8FAFC] dark:bg-gray-950 overflow-hidden font-sans">
      {adminToast && (
        <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[5000] px-6 py-4 rounded-2xl shadow-2xl bg-gray-950 text-white flex items-center gap-4 animate-slide-up">
           <span className="text-[10px] font-black uppercase tracking-widest">{adminToast.msg}</span>
        </div>
      )}

      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 bg-white dark:bg-gray-900 border-r dark:border-gray-800 transition-transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 border-b dark:border-gray-800 flex items-center justify-between">
          <h1 className="text-xl font-black text-red-600">BFC HUB</h1>
          <button className="lg:hidden" onClick={() => setSidebarOpen(false)}><i className="fas fa-times"></i></button>
        </div>
        <nav className="p-6 space-y-1">
          {allowedTabs.map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl uppercase text-[9px] font-black tracking-widest ${activeTab === tab ? 'bg-red-600 text-white shadow-lg' : 'text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800'}`}>
              <i className="fas fa-cube"></i> {tab} Node
            </button>
          ))}
          <div className="pt-10">
            <button onClick={onLogout} className="w-full py-4 text-red-600 font-black uppercase tracking-[4px] text-[8px] border border-red-100 rounded-2xl hover:bg-red-600 hover:text-white transition-all">Sign Out</button>
          </div>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto p-4 lg:p-10">
        <header className="flex justify-between items-center mb-10">
           <h2 className="text-3xl font-black uppercase italic tracking-tighter">{activeTab} Interface</h2>
           <div className="text-right">
              <p className="text-[8px] font-black text-gray-400 uppercase">Session TTL</p>
              <p className="text-xs font-black dark:text-white">{Math.floor(sessionTimeLeft / 60)}m left</p>
           </div>
        </header>

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="bg-white dark:bg-gray-900 p-6 rounded-[32px] border dark:border-gray-800">
               <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Revenue</p>
               <h4 className="text-3xl font-black text-red-600">৳{orders.reduce((a,b)=>a+b.total, 0)}</h4>
            </div>
          </div>
        )}

        {activeTab === 'reports' && (
          <div className="space-y-8">
            <div className="flex gap-4">
               <button onClick={handleExportCSV} className="px-8 py-4 bg-gray-950 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest">Export Excel (Large Dataset Ready)</button>
               <button onClick={() => window.print()} className="px-8 py-4 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest">Print PDF</button>
            </div>
            <div className="bg-white dark:bg-gray-900 p-8 rounded-[40px] border dark:border-gray-800">
               <h3 className="text-xl font-black mb-6 uppercase italic">Sales Analytics</h3>
