                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={ANALYTICS_DATA}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} />
                      <YAxis axisLine={false} tickLine={false} />
                      <Tooltip />
                      <Area type="monotone" dataKey="sales" stroke="#dc2626" fill="#dc2626" fillOpacity={0.1} />
                    </AreaChart>
                  </ResponsiveContainer>
               </div>
            </div>
          </div>
        )}

        {activeTab === 'audit' && (
          <div className="bg-white dark:bg-gray-900 rounded-[40px] border dark:border-gray-800 overflow-hidden">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50 dark:bg-gray-800 text-[9px] font-black uppercase tracking-widest text-gray-400 border-b dark:border-gray-700">
                  <th className="p-6">Event</th>
                  <th className="p-6">Identity</th>
                  <th className="p-6">Timestamp</th>
                  <th className="p-6">Status</th>
                </tr>
              </thead>
              <tbody className="text-xs font-bold text-gray-700 dark:text-gray-300">
                {auditLogs.map((log, i) => (
