import React, { useState, useEffect, useCallback } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './components/AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
  persistent?: boolean;
}

const MOCK_AUTH_DB: Record<string, { pass: string, role: UserRole, name: string, phone: string }> = {
  'admin@bfc.com': { pass: 'admin123', role: UserRole.ADMIN, name: 'BFC Root Admin', phone: '01711-000111' },
  'manager@bfc.com': { pass: 'manager456', role: UserRole.MANAGER, name: 'Regional Manager', phone: '01711-000222' },
  'staff@bfc.com': { pass: 'staff789', role: UserRole.STAFF, name: 'Floor Supervisor', phone: '01711-000333' }
};

const BFC_JWT_SECRET = "bfc_secure_node_alpha_v5_2024";

const generateSecureToken = (role: UserRole, email: string) => {
  const header = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
  const payload = btoa(JSON.stringify({
    role,
    email,
    iat: Date.now(),
    exp: Date.now() + 3600000 
  }));
  const signature = btoa(`${BFC_JWT_SECRET}.${payload}.${role}`);
  return `${header}.${payload}.${signature}`;
};

const App: React.FC = () => {
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE'>('HOME');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [loginAttempts, setLoginAttempts] = useState(0);
  const [isLockedOut, setIsLockedOut] = useState(false);

  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [mfaCode, setMfaCode] = useState('');
  const [showMfa, setShowMfa] = useState(false);
  const [pendingUser, setPendingUser] = useState<User | null>(null);

  const [paymentMethod, setPaymentMethod] = useState<Order['paymentMethod']>('BKASH');
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [mfsNumber, setMfsNumber] = useState('');

  const showToast = useCallback((message: string, type: Toast['type'] = 'info', persistent: boolean = false) => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id, persistent }]);
    if (!persistent) {
      setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
    }
  }, []);

  useEffect(() => {
    const savedSession = localStorage.getItem('bfc_user_session');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession) as User;
        if (user.sessionToken) {
          const parts = user.sessionToken.split('.');
          const payload = JSON.parse(atob(parts[1]));
          const sig = parts[2];

          if (sig === btoa(`${BFC_JWT_SECRET}.${parts[1]}.${user.role}`) && payload.exp > Date.now()) {
            setCurrentUser(user);
            if (user.role !== UserRole.CUSTOMER) setView('ADMIN');
          } else {
            localStorage.removeItem('bfc_user_session');
            showToast("Your session has expired for security. Please log in again to continue.", "warning");
          }
        }
      } catch (e) {
        localStorage.removeItem('bfc_user_session');
      }
    }
  }, [showToast]);

  useEffect(() => {
    const handleOnline = () => { 
      setIsOnline(true); 
      showToast('You are back online! Full features restored.', 'success'); 
    };
    const handleOffline = () => { 
      setIsOnline(false); 
      showToast('You are currently offline. Payments and AI chat are disabled until you reconnect.', 'error', true); 
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => { 
      window.removeEventListener('online', handleOnline); 
      window.removeEventListener('offline', handleOffline); 
    };
  }, [showToast]);

  const handleAuth = async () => {
    if (isLockedOut) {
      showToast("Security Lockout: Too many failed attempts. Please wait 60 seconds before trying again.", "error");
      return;
    }

    if (!formEmail.trim() || !formEmail.includes('@')) {
      showToast("The email address you entered is invalid. Please use a proper email format (e.g., name@bfc.com).", "warning");
      return;
    }

    if (formPass.length < 6) {
      showToast("Your password is too short. It must be at least 6 characters long for security.", "warning");
      return;
    }

    setIsAuthenticating(true);
    try {
      if (!navigator.onLine) throw new Error("NETWORK_FAILURE");

      await new Promise(r => setTimeout(r, 1200));
      const emailKey = formEmail.toLowerCase().trim();
      const privileged = MOCK_AUTH_DB[emailKey];

      if (privileged && privileged.pass === formPass) {
        const user: User = {
          id: `BFC-${Math.random().toString(36).slice(7).toUpperCase()}`,
          name: privileged.name, 
          email: emailKey, 
          phone: privileged.phone,
          role: privileged.role, 
          loyaltyPoints: 0, 
          tier: 'SILVER',
          wishlist: [], 
          referralCode: 'BFC-PRO',
          sessionToken: generateSecureToken(privileged.role, emailKey)
        };

        if (user.role === UserRole.ADMIN || user.role === UserRole.MANAGER) {
          setPendingUser(user);
          setShowMfa(true);
          showToast("Admin node detected. Please enter the 6-digit MFA code sent to your authorized device.", "info");
        } else {
          completeAuth(user);
        }
      } else {
        const newAttempts = loginAttempts + 1;
        setLoginAttempts(newAttempts);
        if (newAttempts >= 5) {
          setIsLockedOut(true);
          setTimeout(() => { setIsLockedOut(false); setLoginAttempts(0); }, 60000);
          showToast("Multiple failed attempts detected. Access to this node is temporarily restricted for 1 minute.", "error");
        } else {
          showToast(`The credentials entered do not match our records. You have ${5 - newAttempts} attempts left.`, "error");
        }
      }
    } catch (err: any) {
      if (err.message === "NETWORK_FAILURE") {
        showToast("We couldn't reach our login servers. Please check your internet connection and try again.", "error");
      } else {
        showToast("An unexpected error occurred during authentication. Please try refreshing the page.", "error");
      }
    } finally {
      setIsAuthenticating(false);
    }
  };

  const handleMfa = () => {
    if (mfaCode.length !== 6) {
      showToast("Please enter the full 6-digit security code provided.", "warning");
      return;
    }
    if (mfaCode === '123456' && pendingUser) {
      completeAuth(pendingUser);
    } else {
      showToast("The MFA code you entered is incorrect. Please double-check the code and try again.", "error");
      setLoginAttempts(p => p + 1);
    }
  };

  const completeAuth = (user: User) => {
    localStorage.setItem('bfc_user_session', JSON.stringify(user));
    setCurrentUser(user);
    setLoginAttempts(0);
    setShowMfa(false);
    setPendingUser(null);
    showToast(`Welcome back, Boss ${user.name.split(' ')[0]}! Secure link established.`, 'success');
    setView(user.role === UserRole.CUSTOMER ? 'HOME' : 'ADMIN');
  };

  const handleLogout = () => {
    localStorage.removeItem('bfc_user_session');
    setCurrentUser(null);
    setView('HOME');
    showToast("You have been successfully logged out. Stay safe!", "info");
  };

  const handleCheckout = async () => {
    if (!isOnline) { 
      showToast("Unable to process payment while offline. Please reconnect to finalize your order.", "error"); 
      return; 
    }
    if (cart.length === 0) { 
      showToast("Your selection is empty. Add some delicious food to your cart before checking out!", "warning"); 
      return; 
    }
    if (paymentMethod !== 'COD' && (!mfsNumber || mfsNumber.length < 11)) {
      showToast("Please enter a valid 11-digit mobile number for your " + paymentMethod + " payment.", "warning");
      return;
    }

    setIsCheckingOut(true);
    try {
      if (Math.random() < 0.05) throw new Error("GATEWAY_ERROR");

      await new Promise(r => setTimeout(r, 2000));
      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser?.id || 'GUEST',
        customerName: currentUser?.name || 'Guest User',
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total: cart.reduce((a, b) => a + (b.item.price * b.qty), 0),
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: paymentMethod === 'COD' ? 'UNPAID' : 'PAID',
        paymentMethod,
        address: 'Dhaka Terminal 1',
        deliveryZone: 'Dhaka',
        deliverySlot: 'ASAP',
        pointsEarned: 0,
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };
      setAllOrders(prev => [newOrder, ...prev]);
      setCart([]);
      setMfsNumber('');
      showToast(`Great! Your order #${newOrder.id} has been placed and is being processed.`, "success");
      setView('TRACKING');
    } catch (err: any) {
      if (err.message === "GATEWAY_ERROR") {
        showToast("The payment gateway is currently under high load. Please try submitting again in a few moments.", "error");
      } else {
        showToast("Something went wrong during checkout. Please check your network and try again.", "error");
      }
    } finally {
      setIsCheckingOut(false);
    }
  };

  if (view === 'ADMIN' && currentUser && currentUser.role !== UserRole.CUSTOMER) {
    return (
      <AdminPanel 
        userRole={currentUser.role} 
        onLogout={handleLogout}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans">
      {!isOnline && (
        <div className="fixed top-0 left-0 w-full z-[3000] bg-red-600 text-white py-1 px-6 flex items-center justify-center gap-3 shadow-lg">
          <i className="fas fa-wifi-slash text-xs"></i>
          <span className="text-[9px] font-black uppercase tracking-[3px]">Restricted Offline Access Active — Reconnect for full features</span>
        </div>
      )}

      <div className="fixed top-12 right-6 z-[4000] space-y-3 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} onClick={() => setToasts(p => p.filter(x => x.id !== t.id))} className={`pointer-events-auto flex items-center gap-4 px-6 py-4 rounded-2xl shadow-2xl border bg-white animate-slide-up cursor-pointer group hover:scale-105 transition-transform ${
            t.type === 'error' ? 'border-red-100' : t.type === 'success' ? 'border-emerald-100' : 'border-blue-100'
          }`}>
            <div className={`w-8 h-8 rounded-xl shrink-0 flex items-center justify-center text-xs ${
              t.type === 'error' ? 'bg-red-50 text-red-600' : 
              t.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 
              t.type === 'warning' ? 'bg-amber-50 text-amber-600' : 
              'bg-blue-50 text-blue-600'
            }`}>
              <i className={`fas ${
                t.type === 'error' ? 'fa-circle-xmark' : 
                t.type === 'success' ? 'fa-circle-check' : 
                t.type === 'warning' ? 'fa-triangle-exclamation' : 
                'fa-info-circle'
              }`}></i>
            </div>
            <p className="font-bold text-[10px] text-gray-800 uppercase tracking-tight leading-tight">{t.message}</p>
          </div>
        ))}
      </div>

      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-12 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-9 h-9 bg-red-600 rounded-xl flex items-center justify-center text-white text-lg font-black">B</div>
          <h1 className="text-xl font-black text-red-600 tracking-tighter">BFC</h1>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center hover:bg-red-50 transition-colors">
            <i className="fas fa-shopping-basket text-gray-700"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[8px] w-5 h-5 rounded-full flex items-center justify-center font-black animate-bounce">{cart.length}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 rounded-xl bg-gray-950 text-white font-black flex items-center justify-center hover:bg-gray-800 transition-colors">
               {currentUser.name.charAt(0)}
            </button>
          ) : (
            <Button size="sm" className="rounded-xl px-5" onClick={() => setView('LOGIN')}>Login</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-12">
        {view === 'HOME' && (
          <div className="animate-slide-up space-y-12">
            <header className="relative h-[400px] lg:h-[550px] rounded-[45px] overflow-hidden shadow-2xl group">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="BFC Hero" />
               <div className="absolute inset-0 bg-gradient-to-r from-black/80 to-transparent flex flex-col justify-center px-10">
                  <h2 className="text-4xl lg:text-7xl font-black text-white leading-[0.95] mb-8 tracking-tighter italic">LEGENDARY<br/><span className="text-red-600">FLAVORS</span></h2>
                  <Button size="lg" className="rounded-2xl w-fit" onClick={() => setView('MENU')}>Order Delicious Kacchi</Button>
               </div>
            </header>
            <section className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {menuItems.slice(0, 3).map(item => (
                <div key={item.id} className="bg-white rounded-[35px] overflow-hidden shadow-sm border p-6 hover:shadow-xl transition-all">
                   <img src={item.image} className="h-48 w-full object-cover rounded-[28px] mb-6" alt={item.name} />
                   <h4 className="text-xl font-black text-gray-900">{item.name}</h4>
                   <p className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-4">৳{item.price}</p>
                   <Button fullWidth variant="outline" className="rounded-xl" onClick={() => { setCart(p => [...p, {item, qty:1}]); showToast(`Added ${item.name} to your cart.`, 'success'); }}>Add to Selection</Button>
                </div>
              ))}
            </section>
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto py-10">
             <div className="bg-white p-12 rounded-[50px] shadow-2xl border relative overflow-hidden">
                {isLockedOut && (
                  <div className="absolute inset-0 z-50 bg-black/90 flex flex-col items-center justify-center p-8 text-center text-white backdrop-blur-sm">
                     <i className="fas fa-lock text-4xl text-red-600 mb-6 animate-pulse"></i>
                     <h4 className="text-xl font-black uppercase tracking-tight">Security Lockout</h4>
                     <p className="text-[10px] text-gray-400 mt-2">Too many incorrect attempts. For your safety, access is paused for 60 seconds.</p>
                  </div>
                )}

                <h3 className="text-3xl font-black text-center mb-10 uppercase italic">
                   <i className="fas fa-shield-halved text-red-600 mr-3"></i>
                   {showMfa ? 'Verify Identity' : 'Secure Login'}
                </h3>

                {showMfa ? (
                  <div className="space-y-6">
                    <div>
                      <label className="text-[9px] font-black uppercase tracking-[3px] text-gray-400 ml-2 block mb-1">MFA PASS-KEY (123456)</label>
                      <input type="text" maxLength={6} value={mfaCode} onChange={e => setMfaCode(e.target.value)} className="w-full bg-gray-50 p-5 rounded-2xl font-black text-center tracking-[10px] text-2xl outline-none border-2 border-transparent focus:border-red-600 transition-colors" placeholder="000000" />
                    </div>
                    <Button fullWidth size="lg" className="rounded-2xl shadow-lg shadow-red-600/20" onClick={handleMfa}>Verify Code</Button>
                    <button onClick={() => { setShowMfa(false); setMfaCode(''); }} className="w-full text-[9px] font-black uppercase tracking-widest text-gray-400 hover:text-red-600 transition-colors">Wrong email? Change login</button>
                  </div>
                ) : (
                  <div className="space-y-4">
                    <div>
                      <label className="text-[9px] font-black uppercase tracking-widest text-gray-400 ml-2 block mb-1">Registered Email</label>
                      <input type="email" value={formEmail} onChange={e => setFormEmail(e.target.value)} placeholder="e.g. boss@bfc.com" className="w-full bg-gray-50 p-5 rounded-2xl font-black text-xs outline-none border-2 border-transparent focus:border-red-600 transition-colors" />
                    </div>
                    <div>
                      <label className="text-[9px] font-black uppercase tracking-widest text-gray-400 ml-2 block mb-1">Access Password</label>
                      <input type="password" value={formPass} onChange={e => setFormPass(e.target.value)} placeholder="••••••••" className="w-full bg-gray-50 p-5 rounded-2xl font-black text-xs outline-none border-2 border-transparent focus:border-red-600 transition-colors" />
                    </div>
                    <Button fullWidth size="lg" className="rounded-2xl mt-10 shadow-lg shadow-red-600/20" onClick={handleAuth} disabled={isAuthenticating}>
                      {isAuthenticating ? (
                        <span className="flex items-center gap-2">
                          <i className="fas fa-circle-notch animate-spin"></i> Establishing Link...
                        </span>
                      ) : 'Secure Sign In'}
                    </Button>
                    <p className="text-[8px] text-center text-gray-400 mt-4 font-bold uppercase tracking-widest leading-relaxed">Authorized access only. All sessions are monitored for security.</p>
                  </div>
                )}
             </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-4xl mx-auto space-y-10 animate-slide-up">
            <h3 className="text-3xl font-black uppercase italic tracking-tighter">Current Selection</h3>
            {cart.length === 0 ? (
              <div className="bg-white p-20 rounded-[50px] text-center border-2 border-dashed border-gray-100">
                <i className="fas fa-shopping-basket text-5xl text-gray-100 mb-6"></i>
                <p className="font-black text-gray-400 uppercase tracking-[5px]">Your cart is hungry!</p>
                <p className="text-xs text-gray-400 mt-2 mb-8">Add some legendary flavors to get started.</p>
                <Button variant="outline" className="rounded-xl" onClick={() => setView('MENU')}>View Menu</Button>
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
                <div className="lg:col-span-2 space-y-4">
                  {cart.map((c, i) => (
                    <div key={i} className="bg-white p-6 rounded-3xl border flex items-center gap-6">
                      <img src={c.item.image} className="w-20 h-20 rounded-2xl object-cover" alt={c.item.name} />
                      <div className="flex-1">
                        <h4 className="font-black text-gray-900">{c.item.name}</h4>
                        <p className="text-[10px] font-black text-red-600">৳{c.item.price}</p>
                      </div>
                      <div className="flex items-center gap-4">
                        <button onClick={() => setCart(prev => prev.map((it, idx) => idx === i ? {...it, qty: Math.max(1, it.qty-1)} : it))} className="w-8 h-8 rounded-lg bg-gray-50 flex items-center justify-center font-black hover:bg-gray-100 transition-colors">-</button>
                        <span className="font-black w-6 text-center">{c.qty}</span>
                        <button onClick={() => setCart(prev => prev.map((it, idx) => idx === i ? {...it, qty: it.qty+1} : it))} className="w-8 h-8 rounded-lg bg-gray-900 text-white flex items-center justify-center font-black hover:scale-105 transition-transform">+</button>
                        <button onClick={() => { setCart(prev => prev.filter((_, idx) => idx !== i)); showToast(`Removed ${c.item.name} from cart.`, 'info'); }} className="text-gray-300 hover:text-red-600 transition-colors ml-2"><i className="fas fa-trash-alt"></i></button>
                      </div>
                    </div>
                  ))}
                </div>
                <div className="bg-white p-8 rounded-[40px] border h-fit space-y-8 sticky top-32 shadow-sm">
                  <h4 className="font-black text-[10px] uppercase tracking-[3px] text-gray-400">Order Intelligence</h4>
                  <div className="space-y-3">
                     <div className="flex justify-between text-xs font-bold text-gray-600">
                        <span>Items Subtotal</span>
                        <span>৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0)}</span>
                     </div>
                     <div className="flex justify-between text-xs font-bold text-gray-600">
                        <span>Delivery Logistics</span>
                        <span>৳50</span>
                     </div>
                     <div className="h-px bg-gray-50 my-4"></div>
                     <div className="flex justify-between text-xl font-black text-gray-950">
                        <span>Total Payable</span>
                        <span>৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50}</span>
                     </div>
                  </div>

                  <div className="space-y-4">
                    <p className="text-[9px] font-black uppercase tracking-widest text-gray-400 mb-2">Payment Gateway</p>
                    <div className="grid grid-cols-2 gap-2">
                       <button onClick={() => setPaymentMethod('BKASH')} className={`p-4 rounded-2xl border-2 transition-all font-black text-[10px] ${paymentMethod === 'BKASH' ? 'border-red-600 bg-red-50 text-red-600' : 'border-gray-50 bg-gray-50'}`}>bKash</button>
                       <button onClick={() => setPaymentMethod('COD')} className={`p-4 rounded-2xl border-2 transition-all font-black text-[10px] ${paymentMethod === 'COD' ? 'border-red-600 bg-red-50 text-red-600' : 'border-gray-50 bg-gray-50'}`}>Cash on Delivery</button>
                    </div>

                    {paymentMethod !== 'COD' && (
                      <div className="animate-slide-up">
                        <label className="text-[9px] font-black uppercase tracking-widest text-gray-400 block mb-1 ml-2">MFS Account Number</label>
                        <input 
                          type="tel" 
                          value={mfsNumber} 
                          onChange={e => setMfsNumber(e.target.value.replace(/\D/g, '').slice(0, 11))} 
                          placeholder="017XXXXXXXX" 
                          className="w-full bg-gray-50 p-4 rounded-2xl font-black text-xs outline-none border-2 border-transparent focus:border-red-600 transition-colors" 
                        />
                        <p className="text-[7px] text-gray-400 mt-2 ml-2 font-bold uppercase">Enter exactly 11 digits</p>
                      </div>
                    )}
                  </div>

                  <Button fullWidth size="lg" className="rounded-2xl" onClick={handleCheckout} disabled={isCheckingOut}>
                    {isCheckingOut ? (
                      <span className="flex items-center gap-2">
                        <i className="fas fa-circle-notch animate-spin"></i> Processing Order...
                      </span>
                    ) : 'Confirm and Pay'}
                  </Button>
                </div>
              </div>
            )}
          </div>
        )}
      </main>
      <ChatBot isOnline={isOnline} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from './types';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 }, { name: 'Sun', sales: 3800 }, { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 }, { name: 'Wed', sales: 6200 }, { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

const BFC_JWT_SECRET = "bfc_secure_node_alpha_v5_2024";

const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  [UserRole.ADMIN]: ['dashboard', 'orders', 'inventory', 'customers', 'reports', 'audit'],
  [UserRole.MANAGER]: ['dashboard', 'orders', 'inventory', 'reports'],
  [UserRole.STAFF]: ['dashboard', 'orders', 'inventory'],
  [UserRole.CUSTOMER]: []
};

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, onLogout, menuItems, setMenuItems, orders, setOrders 
}) => {
  const allowedTabs = useMemo(() => ROLE_PERMISSIONS[userRole] || [], [userRole]);
  const [activeTab, setActiveTab] = useState(allowedTabs[0] || 'dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [sessionTimeLeft, setSessionTimeLeft] = useState<number>(3600);
  const [adminToast, setAdminToast] = useState<{msg: string, type: string} | null>(null);
  const [reportType, setReportType] = useState<'sales' | 'inventory'>('sales');
  const [auditLogs] = useState([
    { event: 'LOGIN_SUCCESS', user: 'admin@bfc.com', time: '10:00:05 AM', status: 'OK' },
    { event: 'STOCK_UPDATE', user: 'staff@bfc.com', time: '10:15:20 AM', status: 'OK' },
    { event: 'ORDER_PREPARED', user: 'staff@bfc.com', time: '10:45:00 AM', status: 'OK' },
  ]);

  const showToast = useCallback((msg: string, type: string) => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const verifyAccess = useCallback(() => {
    const savedUser = localStorage.getItem('bfc_user_session');
    if (!savedUser) return false;
    try {
      const user = JSON.parse(savedUser) as User;
      if (!user.sessionToken) return false;
      const parts = user.sessionToken.split('.');
      if (parts.length !== 3) return false;

      const payload = JSON.parse(atob(parts[1]));
      const sig = parts[2];

      if (sig !== btoa(`${BFC_JWT_SECRET}.${parts[1]}.${user.role}`)) return false;
      if (payload.exp < Date.now()) return false;
      if (payload.role !== userRole) return false;

      setSessionTimeLeft(Math.max(0, Math.round((payload.exp - Date.now()) / 1000)));
      return true;
    } catch { return false; }
  }, [userRole]);

  useEffect(() => {
    const heartbeat = setInterval(() => {
      if (!verifyAccess()) {
        showToast("Your administrative session has expired for security. Redirecting...", "error");
        setTimeout(onLogout, 1500);
      }
    }, 2000);
    if (verifyAccess()) setIsAuthorized(true); else onLogout();
    return () => clearInterval(heartbeat);
  }, [verifyAccess, onLogout, showToast]);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    try {
      setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
      showToast(`Order #${orderId.slice(-4)} updated to ${newStatus}. Status synched.`, "success");
    } catch (e) {
      showToast("Could not update order status. Please try again.", "error");
    }
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) {
          showToast(`Invalid Stock Adjustment: Inventory for ${item.name} cannot be less than zero.`, "warning");
          return item;
        }
        showToast(`Stock for ${item.name} updated to ${newStock}.`, "success");
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  const handleExportCSV = () => {
    try {
      const data = reportType === 'sales' ? orders : menuItems;
      if (data.length === 0) {
        showToast(`Export Failed: No ${reportType} data was found for the current period.`, "warning");
        return;
      }
      const csvRows = [["ID", "Name", "Metric", "Value"]];
      data.forEach((o: any) => csvRows.push([o.id, o.customerName || o.name, o.status || o.category, o.total || o.stock]));

      const blob = new Blob([csvRows.map(r => r.join(",")).join("\n")], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `BFC_${reportType.toUpperCase()}_Log_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
      showToast("Data intelligence exported successfully. File: BFC_Log.csv", "success");
    } catch (e) {
      showToast("System Error: Failed to generate export file. Check storage permissions.", "error");
    }
  };

  if (!isAuthorized) return (
    <div className="h-screen bg-gray-950 flex flex-col items-center justify-center text-white gap-4">
      <i className="fas fa-circle-notch animate-spin text-2xl text-red-600"></i>
      <p className="text-[10px] font-black uppercase tracking-[5px]">Establishing Encrypted Node Link...</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F8FAFC] dark:bg-gray-950 overflow-hidden font-sans">
      {/* Toast Notification Container */}
      {adminToast && (
        <div className={`fixed top-4 left-4 right-4 sm:left-auto sm:right-6 sm:top-6 sm:w-auto z-[6000] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-slide-up border ${
          adminToast.type === 'error' ? 'bg-red-600 text-white border-red-400' : 
          adminToast.type === 'warning' ? 'bg-amber-500 text-white border-amber-400' :
          'bg-gray-950 text-white border-white/10'
        }`}>
           <i className={`fas ${adminToast.type === 'success' ? 'fa-check-circle' : 'fa-info-circle'}`}></i>
           <span className="text-[10px] font-black uppercase tracking-widest">{adminToast.msg}</span>
        </div>
      )}

      {/* Sidebar Overlay for Mobile */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[240] lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar Navigation */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 bg-white dark:bg-gray-900 border-r dark:border-gray-800 transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 border-b dark:border-gray-800 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-red-600 rounded-lg flex items-center justify-center text-white font-black">B</div>
            <h1 className="text-xl font-black text-red-600 tracking-tight">BFC HUB</h1>
          </div>
          <button className="lg:hidden w-8 h-8 flex items-center justify-center text-gray-400" onClick={() => setSidebarOpen(false)}>
            <i className="fas fa-times"></i>
          </button>
        </div>
