        <div className="flex items-center gap-3">
          <button onClick={() => setView('CART')} className="relative w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center">
            <i className="fas fa-shopping-basket text-gray-700"></i>
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[8px] w-5 h-5 rounded-full flex items-center justify-center font-black">{cart.length}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-10 h-10 rounded-xl bg-gray-950 text-white font-black flex items-center justify-center uppercase">{currentUser.name.charAt(0)}</button>
