                  <div key={item.id} className="bg-white rounded-[35px] overflow-hidden shadow-sm border p-6 hover:shadow-xl transition-all">
                     <img src={item.image} className="h-48 w-full object-cover rounded-[28px] mb-6" alt={item.name} />
                     <div className="flex justify-between items-start mb-2">
                        <h4 className="text-xl font-black text-gray-900">{item.name}</h4>
                        <span className="bg-red-50 text-red-600 text-[8px] font-black px-2 py-1 rounded-full uppercase">৳{item.price}</span>
                     </div>
                     <p className="text-xs text-gray-400 mb-6 line-clamp-2">{item.description}</p>
                     <Button fullWidth variant="outline" className="rounded-xl" onClick={() => { setCart(p => [...p, {item, qty:1}]); showToast('Added to Cart', 'success'); }}>Add to Selection</Button>
