                />
              </div>
            </div>

            <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
              {categories.map(cat => (
                <button 
                  key={cat} 
                  onClick={() => setActiveCategory(cat)}
                  className={`px-6 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${
                    activeCategory === cat ? 'bg-red-600 text-white shadow-lg shadow-red-600/20' : 'bg-white text-gray-400 border border-gray-100 hover:border-red-200'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {filteredMenu.map(item => (
                <div key={item.id} className="bg-white rounded-[40px] border border-gray-50 p-4 hover:shadow-2xl transition-all group">
                   <div className="relative overflow-hidden rounded-[30px] mb-4 h-56">
                      <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" alt={item.name} />
                      <div className="absolute top-4 right-4 bg-white/90 backdrop-blur-md px-3 py-1.5 rounded-xl">
                        <p className="text-[10px] font-black text-gray-900">৳{item.price}</p>
                      </div>
                   </div>
                   <div className="px-2">
                      <div className="flex justify-between items-center mb-1">
                        <h4 className="font-black text-gray-900 text-sm truncate">{item.name}</h4>
                        <div className="flex items-center gap-1">
                          <i className="fas fa-star text-amber-400 text-[10px]"></i>
                          <span className="text-[10px] font-black">{item.rating}</span>
                        </div>
                      </div>
                      <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-4">{item.nameBn}</p>
                      <Button fullWidth size="sm" className="rounded-xl shadow-lg shadow-red-600/5" onClick={() => { setCart(p => [...p, {item, qty:1}]); showToast('Added to Cart', 'success'); }}>
                        <i className="fas fa-plus mr-2 text-[8px]"></i> Add to Cart
                      </Button>
                   </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'TRACKING' && (
          <div className="animate-slide-up max-w-4xl mx-auto space-y-8">
            <h3 className="text-3xl font-black uppercase italic tracking-tighter">Active Missions</h3>
            {allOrders.length === 0 ? (
              <div className="bg-white p-20 rounded-[50px] text-center border-2 border-dashed border-gray-100">
                <i className="fas fa-clock text-4xl text-gray-200 mb-4"></i>
                <p className="font-black text-gray-400 uppercase tracking-widest">No active orders found</p>
              </div>
            ) : (
              <div className="space-y-6">
                {allOrders.map(order => (
                  <div key={order.id} className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm">
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
                      <div>
                        <p className="text-[10px] font-black text-red-600 uppercase tracking-[3px] mb-1">Order Identifier</p>
                        <h4 className="text-xl font-black">#{order.id}</h4>
                      </div>
                      <div className="bg-emerald-50 text-emerald-600 px-6 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest">
                        {order.status}
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-10">
                      {[OrderStatus.PENDING, OrderStatus.PREPARING, OrderStatus.READY, OrderStatus.DELIVERED].map((s, idx) => {
                        const isCompleted = order.trackingUpdates.some(u => u.status === s);
                        const isCurrent = order.status === s;
                        return (
                          <div key={s} className="relative flex flex-col items-center">
                            <div className={`w-10 h-10 rounded-full flex items-center justify-center z-10 ${
                              isCompleted || isCurrent ? 'bg-red-600 text-white shadow-lg' : 'bg-gray-100 text-gray-300'
                            }`}>
                              <i className={`fas ${s === OrderStatus.PENDING ? 'fa-check' : s === OrderStatus.PREPARING ? 'fa-fire' : s === OrderStatus.READY ? 'fa-box' : 'fa-house'} text-xs`}></i>
                            </div>
                            <p className={`mt-3 text-[8px] font-black uppercase tracking-widest ${isCompleted || isCurrent ? 'text-gray-900' : 'text-gray-300'}`}>{s}</p>
                            {idx < 3 && <div className={`hidden md:block absolute top-5 left-[60%] w-[80%] h-0.5 ${isCompleted ? 'bg-red-600' : 'bg-gray-100'}`}></div>}
                          </div>
                        );
                      })}
                    </div>

                    <div className="bg-gray-50 rounded-3xl p-6">
                      <h5 className="text-[9px] font-black uppercase tracking-widest text-gray-400 mb-4">Item Intelligence</h5>
                      <div className="space-y-3">
                        {order.items.map((item, i) => (
                          <div key={i} className="flex justify-between items-center text-xs font-bold">
                            <span className="text-gray-600">{item.quantity}x {item.name}</span>
                            <span className="text-gray-900">৳{item.price * item.quantity}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto py-10 animate-slide-up">
             <div className="bg-white p-12 rounded-[50px] shadow-2xl border">
                <h3 className="text-3xl font-black text-center mb-10 uppercase italic">Access Terminal</h3>
                <div className="space-y-4">
                  <div>
                    <label className="text-[9px] font-black uppercase tracking-widest text-gray-400 ml-2 block mb-1">Email Node</label>
                    <input type="email" value={formEmail} onChange={e => setFormEmail(e.target.value)} placeholder="e.g. boss@bfc.com" className="w-full bg-gray-50 p-5 rounded-2xl font-black text-xs outline-none border-2 border-transparent focus:border-red-600 transition-colors" />
                  </div>
                  <div>
                    <label className="text-[9px] font-black uppercase tracking-widest text-gray-400 ml-2 block mb-1">Security Key</label>
                    <input type="password" value={formPass} onChange={e => setFormPass(e.target.value)} placeholder="••••••••" className="w-full bg-gray-50 p-5 rounded-2xl font-black text-xs outline-none border-2 border-transparent focus:border-red-600 transition-colors" />
                  </div>
                  <Button fullWidth size="lg" className="rounded-2xl mt-10" onClick={handleAuth} disabled={isAuthenticating}>Establish Link</Button>
                </div>
             </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-4xl mx-auto space-y-10 animate-slide-up">
            <h3 className="text-3xl font-black uppercase italic tracking-tighter">Deployment Payload</h3>
            {cart.length === 0 ? (
              <div className="bg-white p-20 rounded-[50px] text-center border-2 border-dashed border-gray-100">
                <i className="fas fa-shopping-basket text-5xl text-gray-100 mb-6"></i>
                <p className="font-black text-gray-400 uppercase tracking-[5px]">Empty Payload</p>
                <Button variant="outline" className="mt-8 rounded-xl" onClick={() => setView('MENU')}>Back to Menu</Button>
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
                <div className="lg:col-span-2 space-y-4">
                  {cart.map((c, i) => (
                    <div key={i} className="bg-white p-6 rounded-3xl border flex items-center gap-6">
                      <img src={c.item.image} className="w-20 h-20 rounded-2xl object-cover" alt={c.item.name} />
                      <div className="flex-1">
                        <h4 className="font-black text-gray-900">{c.item.name}</h4>
                        <p className="text-[10px] font-black text-red-600">৳{c.item.price}</p>
                      </div>
                      <div className="flex items-center gap-4">
                        <button onClick={() => setCart(prev => prev.map((it, idx) => idx === i ? {...it, qty: Math.max(1, it.qty-1)} : it))} className="w-8 h-8 rounded-lg bg-gray-50 flex items-center justify-center font-black">-</button>
                        <span className="font-black w-6 text-center">{c.qty}</span>
                        <button onClick={() => setCart(prev => prev.map((it, idx) => idx === i ? {...it, qty: it.qty+1} : it))} className="w-8 h-8 rounded-lg bg-gray-900 text-white flex items-center justify-center font-black">+</button>
                      </div>
                    </div>
                  ))}
                </div>
                <div className="bg-white p-8 rounded-[40px] border h-fit space-y-8 sticky top-32 shadow-sm">
                  <h4 className="font-black text-[10px] uppercase tracking-[3px] text-gray-400">Order Intelligence</h4>
                  <div className="space-y-3">
                     <div className="flex justify-between text-xs font-bold text-gray-600">
                        <span>Subtotal</span>
                        <span>৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0)}</span>
                     </div>
                     <div className="flex justify-between text-xs font-bold text-gray-600">
                        <span>Logistics</span>
                        <span>৳50</span>
                     </div>
                     <div className="h-px bg-gray-50 my-4"></div>
                     <div className="flex justify-between text-xl font-black text-gray-950">
                        <span>Total Payable</span>
                        <span>৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50}</span>
                     </div>
                  </div>

                  <div className="space-y-4">
                    <p className="text-[9px] font-black uppercase tracking-widest text-gray-400 mb-2">Gate</p>
                    <div className="grid grid-cols-2 gap-2">
                       <button onClick={() => setPaymentMethod('BKASH')} className={`p-4 rounded-2xl border-2 transition-all font-black text-[10px] ${paymentMethod === 'BKASH' ? 'border-red-600 bg-red-50 text-red-600' : 'border-gray-50 bg-gray-50'}`}>bKash</button>
                       <button onClick={() => setPaymentMethod('COD')} className={`p-4 rounded-2xl border-2 transition-all font-black text-[10px] ${paymentMethod === 'COD' ? 'border-red-600 bg-red-50 text-red-600' : 'border-gray-50 bg-gray-50'}`}>Cash</button>
                    </div>
                  </div>

                  <Button fullWidth size="lg" className="rounded-2xl" onClick={handleCheckout} disabled={isCheckingOut}>
                    {isCheckingOut ? <i className="fas fa-circle-notch animate-spin"></i> : 'Execute Order'}
                  </Button>
                </div>
              </div>
            )}
          </div>
        )}
      </main>

      {/* Navigation Footer for Mobile */}
      <nav className="lg:hidden fixed bottom-0 left-0 w-full bg-white border-t border-gray-100 flex justify-around p-4 z-[4500]">
        <button onClick={() => setView('HOME')} className={`flex flex-col items-center gap-1 ${view === 'HOME' ? 'text-red-600' : 'text-gray-400'}`}>
          <i className="fas fa-home text-lg"></i>
          <span className="text-[7px] font-black uppercase">Home</span>
        </button>
        <button onClick={() => setView('MENU')} className={`flex flex-col items-center gap-1 ${view === 'MENU' ? 'text-red-600' : 'text-gray-400'}`}>
          <i className="fas fa-utensils text-lg"></i>
          <span className="text-[7px] font-black uppercase">Menu</span>
        </button>
        <button onClick={() => setView('TRACKING')} className={`flex flex-col items-center gap-1 ${view === 'TRACKING' ? 'text-red-600' : 'text-gray-400'}`}>
          <i className="fas fa-map-marker-alt text-lg"></i>
          <span className="text-[7px] font-black uppercase">Track</span>
        </button>
        <button onClick={() => setView('PROFILE')} className={`flex flex-col items-center gap-1 ${view === 'PROFILE' ? 'text-red-600' : 'text-gray-400'}`}>
          <i className="fas fa-user text-lg"></i>
          <span className="text-[7px] font-black uppercase">Profile</span>
        </button>
      </nav>

      <ChatBot isOnline={isOnline} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from '../types';
import { Button } from './Button';
import { ChatBot } from './ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer
} from 'recharts';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 }, { name: 'Sun', sales: 3800 }, { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 }, { name: 'Wed', sales: 6200 }, { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, onLogout, menuItems, setMenuItems, orders, setOrders 
}) => {
  const allowedTabs = useMemo(() => {
    if (userRole === UserRole.ADMIN) return ['dashboard', 'orders', 'inventory', 'reports', 'audit'];
    if (userRole === UserRole.MANAGER) return ['dashboard', 'orders', 'inventory'];
    return ['orders'];
  }, [userRole]);

  const [activeTab, setActiveTab] = useState(allowedTabs[0]);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [adminToast, setAdminToast] = useState<{msg: string, type: string} | null>(null);

  const showToast = useCallback((msg: string, type: string) => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 3000);
  }, []);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order updated to ${newStatus}`, "success");
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) {
          showToast(`Stock cannot be less than zero`, "warning");
          return item;
        }
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] dark:bg-gray-950 overflow-hidden font-sans">
      {adminToast && (
        <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[6000] px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-4 animate-slide-up border ${
          adminToast.type === 'error' ? 'bg-red-600 text-white' : 'bg-gray-950 text-white'
        }`}>
           <span className="text-[10px] font-black uppercase tracking-widest">{adminToast.msg}</span>
        </div>
      )}

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 bg-white dark:bg-gray-900 border-r dark:border-gray-800 transition-transform duration-300 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 border-b dark:border-gray-800 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-red-600 rounded-lg flex items-center justify-center text-white font-black">B</div>
            <h1 className="text-xl font-black text-red-600 tracking-tight">BFC HUB</h1>
          </div>
          <button className="lg:hidden text-gray-400" onClick={() => setSidebarOpen(false)}><i className="fas fa-times"></i></button>
        </div>
        <nav className="p-6 space-y-1">
          {allowedTabs.map(tab => (
            <button key={tab} onClick={() => { setActiveTab(tab); setSidebarOpen(false); }} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl transition-all ${activeTab === tab ? 'bg-red-600 text-white shadow-lg' : 'text-gray-400 hover:bg-gray-50'}`}>
              <i className={`fas ${tab === 'dashboard' ? 'fa-chart-pie' : tab === 'orders' ? 'fa-list-check' : 'fa-box-open'} text-xs`}></i> 
              <span className="uppercase text-[9px] font-black tracking-widest">{tab}</span>
            </button>
          ))}
          <div className="pt-10">
            <button onClick={onLogout} className="w-full py-4 text-red-600 font-black uppercase tracking-[4px] text-[8px] border border-red-100 rounded-2xl hover:bg-red-600 hover:text-white transition-all">Emergency Exit</button>
          </div>
        </nav>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto bg-[#F8FAFC] dark:bg-gray-950 flex flex-col">
        <header className="sticky top-0 z-40 bg-white/80 dark:bg-gray-900/80 backdrop-blur-md border-b dark:border-gray-800 px-8 py-4 flex items-center justify-between">
           <div className="flex items-center gap-4">
             <button className="lg:hidden w-10 h-10 bg-gray-100 dark:bg-gray-800 rounded-xl" onClick={() => setSidebarOpen(true)}><i className="fas fa-bars"></i></button>
             <h2 className="text-xl font-black uppercase italic tracking-tighter">{activeTab} Interface</h2>
           </div>
           <div className="w-10 h-10 bg-gray-900 text-white rounded-xl flex items-center justify-center font-black text-xs uppercase">{userRole.charAt(0)}</div>
        </header>

        <div className="p-8 space-y-8">
          {activeTab === 'dashboard' && (
            <div className="animate-slide-up space-y-8">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard title="Revenue" value={`৳${orders.reduce((a,b)=>a+b.total, 0).toLocaleString()}`} icon="fa-taka-sign" color="text-red-600" />
                <StatCard title="Total Orders" value={orders.length} icon="fa-receipt" color="text-blue-600" />
                <StatCard title="Stock Status" value={menuItems.length} icon="fa-box" color="text-amber-500" />
                <StatCard title="Active Hubs" value="03" icon="fa-house" color="text-purple-600" />
              </div>

              <div className="bg-white dark:bg-gray-900 p-8 rounded-[40px] border dark:border-gray-800 shadow-sm">
                <h3 className="text-[10px] font-black uppercase tracking-[4px] text-gray-400 italic mb-8">Growth Metrics</h3>
                <div className="h-[300px] w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={ANALYTICS_DATA}>
                      <defs>
                        <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="5%" stopColor="#dc2626" stopOpacity={0.2}/>
                          <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                        </linearGradient>
                      </defs>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 9, fontWeight: 'bold'}} />
                      <YAxis axisLine={false} tickLine={false} tick={{fontSize: 9, fontWeight: 'bold'}} />
                      <Tooltip contentStyle={{borderRadius: '20px', border: 'none'}} />
                      <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={4} fill="url(#colorSales)" />
                    </AreaChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'orders' && (
            <div className="animate-slide-up space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 2xl:grid-cols-3 gap-6">
                {orders.map(o => (
                  <div key={o.id} className="bg-white dark:bg-gray-900 p-8 rounded-[40px] border dark:border-gray-800 shadow-sm flex flex-col justify-between group">
                    <div>
                      <div className="flex justify-between items-start mb-4">
                        <p className="text-[9px] font-black text-red-600 tracking-widest">#{o.id}</p>
                        <span className="text-[8px] font-black text-gray-400 uppercase">{new Date(o.createdAt).toLocaleTimeString()}</span>
                      </div>
                      <h4 className="font-black text-gray-950 dark:text-white uppercase italic text-lg">{o.customerName}</h4>
                      <p className="text-[10px] font-bold text-gray-400 mt-1 uppercase tracking-wider">৳{o.total} • {o.items.length} Units</p>
                    </div>
                    <div className="mt-8 flex gap-2">
                       <select 
                        className="flex-1 bg-gray-50 dark:bg-gray-800 border-none rounded-xl p-3 text-[9px] font-black uppercase tracking-widest outline-none cursor-pointer"
                        value={o.status}
                        onChange={(e) => handleUpdateStatus(o.id, e.target.value as OrderStatus)}
                       >
                         {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                       </select>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'inventory' && (
            <div className="animate-slide-up space-y-6">
              <h3 className="text-xl font-black uppercase italic tracking-tighter">Stock Intelligence</h3>
              <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 2xl:grid-cols-6 gap-6">
                {menuItems.map(item => (
                  <div key={item.id} className="bg-white dark:bg-gray-900 p-6 rounded-[35px] border dark:border-gray-800 shadow-sm flex flex-col items-center text-center">
                     <div className="relative mb-4">
                        <img src={item.image} className="w-20 h-20 rounded-2xl object-cover shadow-lg" alt={item.name} />
                        {item.stock < 10 && (
                          <div className="absolute -top-1 -right-1 w-5 h-5 bg-red-600 text-white rounded-full flex items-center justify-center text-[8px] animate-bounce shadow-lg ring-2 ring-white">
                            <i className="fas fa-exclamation"></i>
                          </div>
                        )}
                     </div>
                     <h4 className="font-black text-[10px] text-gray-950 dark:text-white mb-4 uppercase tracking-tighter truncate w-full px-2">{item.name}</h4>
                     <p className={`text-4xl font-black mb-6 ${item.stock < 10 ? 'text-red-600' : 'dark:text-white'}`}>{item.stock}</p>
                     <div className="flex gap-2 w-full mt-auto">
                        <button onClick={() => handleUpdateStock(item.id, false)} className="flex-1 bg-gray-50 dark:bg-gray-800 py-3 rounded-xl font-black text-lg hover:bg-red-50 transition-colors">-</button>
                        <button onClick={() => handleUpdateStock(item.id, true)} className="flex-1 bg-gray-950 dark:bg-white dark:text-gray-950 text-white py-3 rounded-xl font-black text-lg hover:scale-105 transition-transform">+</button>
                     </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </main>
      <ChatBot isOnline={true} />
    </div>
  );
};

const StatCard = ({ title, value, icon, color }: any) => (
  <div className="bg-white dark:bg-gray-900 p-6 rounded-[35px] border dark:border-gray-800 flex items-center gap-4 hover:shadow-lg transition-all group overflow-hidden">
    <div className={`w-14 h-14 bg-gray-50 dark:bg-gray-800 rounded-2xl flex items-center justify-center text-xl ${color} shrink-0 group-hover:scale-110 transition-transform`}>
      <i className={`fas ${icon}`}></i>
    </div>
    <div className="min-w-0">
      <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest mb-1 truncate">{title}</p>
      <h4 className="text-2xl font-black text-gray-950 dark:text-white tracking-tighter truncate italic">{value}</h4>
    </div>
  </div>
);

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
}

const App: React.FC = () => {
  // Core State
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE'>('HOME');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Menu Filter States
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  // Login States
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  // Checkout States
  const [isCheckingOut, setIsCheckingOut] = useState(false);

  // Computed Values
  const categories = useMemo(() => ['All', ...new Set(menuItems.map(item => item.category))], [menuItems]);

  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [menuItems, searchQuery, activeCategory]);

  const showToast = useCallback((message: string, type: Toast['type'] = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  }, []);

  // Sync Persistence
  useEffect(() => {
    const savedSession = localStorage.getItem('bfc_user_session');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        if (user.role !== UserRole.CUSTOMER) setView('ADMIN');
      } catch (e) { localStorage.removeItem('bfc_user_session'); }
    }
  }, []);

  useEffect(() => {
    const handleOnline = () => { setIsOnline(true); showToast('Signal Established! System Online.', 'success'); };
    const handleOffline = () => { setIsOnline(false); showToast('Link Severed. Operating in Offline Mode.', 'error'); };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => { window.removeEventListener('online', handleOnline); window.removeEventListener('offline', handleOffline); };
  }, [showToast]);

  const handleAuth = async () => {
    if (!formEmail.includes('@')) {
      showToast('Enter a valid Email Node, Boss!', 'warning');
      return;
    }
    setIsAuthenticating(true);
    // Simulation
    setTimeout(() => {
      const role = formEmail.startsWith('admin') ? UserRole.ADMIN : UserRole.CUSTOMER;
      const user: User = {
        id: 'U1', name: role === UserRole.ADMIN ? 'BFC Admin' : 'Valued Customer', 
        email: formEmail, role, phone: '017', loyaltyPoints: 100, tier: 'GOLD', wishlist: [], referralCode: 'BFC1'
      };
      setCurrentUser(user);
      localStorage.setItem('bfc_user_session', JSON.stringify(user));
      setView(role === UserRole.ADMIN ? 'ADMIN' : 'HOME');
      setIsAuthenticating(false);
      showToast('Login Successful!', 'success');
    }, 1000);
  };

  const handleCheckout = () => {
    if (cart.length === 0) return;
    setIsCheckingOut(true);
    setTimeout(() => {
      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser?.id || 'GUEST',
        customerName: currentUser?.name || 'Guest User',
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total: cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: 'PAID',
        paymentMethod: 'BKASH',
        address: 'Dhaka Terminal',
        deliveryZone: 'Dhaka',
        deliverySlot: 'ASAP',
        pointsEarned: 10,
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };
      setAllOrders(prev => [newOrder, ...prev]);
      setCart([]);
      setIsCheckingOut(false);
      setView('TRACKING');
      showToast('Order Placed Successfully!', 'success');
    }, 1500);
  };

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(c => c.item.id === item.id);
      if (existing) return prev.map(c => c.item.id === item.id ? { ...c, qty: c.qty + 1 } : c);
      return [...prev, { item, qty: 1 }];
    });
    showToast(`${item.name} added to payload.`, 'success');
  };

  if (view === 'ADMIN' && currentUser?.role !== UserRole.CUSTOMER) {
    return (
      <AdminPanel 
        userRole={currentUser!.role} 
        onLogout={() => { setCurrentUser(null); setView('HOME'); localStorage.removeItem('bfc_user_session'); }}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans">
      {/* Network Status Bar */}
      {!isOnline && (
        <div className="fixed top-0 left-0 w-full z-[6000] bg-red-600 text-white py-1 px-4 text-center">
          <p className="text-[9px] font-black uppercase tracking-widest">Running on Cache Memory - Reconnect for live updates</p>
        </div>
      )}

      {/* Toast Overlay */}
      <div className="fixed top-12 right-6 z-[5500] space-y-3 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className={`pointer-events-auto px-6 py-4 rounded-2xl shadow-2xl border bg-white animate-slide-up flex items-center gap-3 ${
            t.type === 'error' ? 'border-red-100 text-red-600' : 'border-emerald-100 text-emerald-600'
          }`}>
            <i className={`fas ${t.type === 'error' ? 'fa-bolt' : 'fa-circle-check'} text-xs`}></i>
            <p className="font-black text-[10px] uppercase tracking-tight">{t.message}</p>
          </div>
        ))}
      </div>

      {/* Desktop Navigation */}
      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-12 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white text-xl font-black shadow-lg shadow-red-600/20">B</div>
          <h1 className="text-2xl font-black text-red-600 tracking-tighter italic">BFC</h1>
        </div>

        <div className="hidden md:flex gap-10">
          {['HOME', 'MENU', 'TRACKING'].map(v => (
            <button 
              key={v} 
              onClick={() => setView(v as any)}
              className={`text-[10px] font-black uppercase tracking-[3px] transition-all hover:text-red-600 ${view === v ? 'text-red-600' : 'text-gray-400'}`}
            >
              {v}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-4">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 bg-white rounded-2xl border flex items-center justify-center shadow-sm hover:border-red-600 transition-colors group">
            <i className="fas fa-shopping-basket text-gray-700 group-hover:text-red-600"></i>
            {cart.length > 0 && (
              <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[9px] w-6 h-6 rounded-full flex items-center justify-center font-black animate-bounce shadow-lg">
                {cart.length}
              </span>
            )}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-12 h-12 rounded-2xl bg-gray-950 text-white font-black flex items-center justify-center uppercase shadow-xl hover:scale-105 transition-transform">
              {currentUser.name.charAt(0)}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl px-6" onClick={() => setView('LOGIN')}>Login</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-10">
        {view === 'HOME' && (
          <div className="animate-slide-up space-y-16">
            <header className="relative h-[450px] lg:h-[600px] rounded-[50px] overflow-hidden shadow-2xl group border-8 border-white">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" alt="BFC Hero" />
               <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent flex flex-col justify-end p-12 lg:p-20">
                  <h2 className="text-5xl lg:text-8xl font-black text-white leading-[0.85] mb-8 tracking-tighter italic">LEGENDARY<br/><span className="text-red-600">DHAKA TASTE</span></h2>
                  <div className="flex gap-4">
                    <Button size="lg" className="rounded-2xl" onClick={() => setView('MENU')}>View Vault Menu</Button>
                    <button onClick={() => setView('TRACKING')} className="px-8 py-4 bg-white/10 backdrop-blur-md text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-white/20 transition-all border border-white/20">Track Mission</button>
                  </div>
               </div>
            </header>

            <section>
              <div className="flex justify-between items-end mb-10">
                <div>
                  <h3 className="text-3xl font-black uppercase italic tracking-tighter">Current Hotlist</h3>
                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mt-1">Trending flavors across Dhaka nodes</p>
                </div>
                <button onClick={() => setView('MENU')} className="text-[10px] font-black text-red-600 uppercase tracking-widest border-b-2 border-red-600 pb-1">See All</button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                {menuItems.filter(i => i.isPopular).map(item => (
                  <div key={item.id} className="bg-white rounded-[45px] overflow-hidden shadow-sm border border-gray-50 p-6 hover:shadow-2xl transition-all group">
                     <div className="relative h-64 rounded-[35px] overflow-hidden mb-6">
                       <img src={item.image} className="h-full w-full object-cover group-hover:scale-110 transition-transform" alt={item.name} />
                       <div className="absolute top-5 right-5 bg-white/90 backdrop-blur-md px-4 py-2 rounded-2xl font-black text-xs">৳{item.price}</div>
                     </div>
                     <h4 className="text-2xl font-black text-gray-900 leading-tight mb-2">{item.name}</h4>
                     <p className="text-xs text-gray-400 mb-8 line-clamp-2 leading-relaxed">{item.description}</p>
                     <Button fullWidth variant="outline" className="rounded-2xl py-4" onClick={() => addToCart(item)}>Add to Payload</Button>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {view === 'MENU' && (
          <div className="animate-slide-up space-y-10">
            <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-8">
              <div>
                <h3 className="text-4xl font-black uppercase italic tracking-tighter leading-none">The Vault Menu</h3>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[4px] mt-2 italic">Secured local recipes and global fusion</p>
              </div>
              <div className="relative w-full lg:w-1/3">
                <i className="fas fa-search absolute left-5 top-1/2 -translate-y-1/2 text-gray-400 text-sm"></i>
                <input 
                  type="text" 
                  placeholder="Kacchi, Roast, Rezala..." 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full bg-white border border-gray-100 p-5 pl-14 rounded-3xl outline-none focus:border-red-600 transition-colors font-bold text-xs shadow-sm"
                />
              </div>
            </div>

            <div className="flex gap-3 overflow-x-auto pb-4 scrollbar-hide">
              {categories.map(cat => (
                <button 
                  key={cat} 
                  onClick={() => setActiveCategory(cat)}
                  className={`px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap shadow-sm ${
                    activeCategory === cat ? 'bg-red-600 text-white shadow-red-600/30' : 'bg-white text-gray-400 border border-gray-50 hover:border-red-100'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
              {filteredMenu.map(item => (
                <div key={item.id} className="bg-white rounded-[50px] border border-gray-100 p-5 hover:shadow-2xl transition-all group flex flex-col h-full">
                   <div className="relative overflow-hidden rounded-[40px] mb-6 h-60 shrink-0">
                      <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={item.name} />
                      <div className="absolute top-5 right-5 bg-red-600 text-white px-4 py-2 rounded-2xl shadow-lg font-black text-[11px]">৳{item.price}</div>
                   </div>
                   <div className="px-3 flex-1 flex flex-col">
                      <div className="flex justify-between items-start mb-2">
                        <h4 className="font-black text-gray-950 text-xl leading-tight truncate pr-2">{item.name}</h4>
                        <div className="flex items-center gap-1.5 bg-amber-50 px-2 py-1 rounded-lg">
                          <i className="fas fa-star text-amber-500 text-[10px]"></i>
                          <span className="text-[10px] font-black text-amber-700">{item.rating}</span>
                        </div>
                      </div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-6 italic">{item.nameBn}</p>
                      <div className="mt-auto">
                        <Button fullWidth size="md" className="rounded-2xl shadow-lg shadow-red-600/10 py-4" onClick={() => addToCart(item)}>
                          <i className="fas fa-plus mr-3 text-[10px]"></i> Buy Now
                        </Button>
                      </div>
                   </div>
                </div>
              ))}
              {filteredMenu.length === 0 && (
                <div className="col-span-full py-20 text-center opacity-30 italic font-black uppercase tracking-widest">No Node Found with this Identifier</div>
              )}
            </div>
          </div>
        )}

        {view === 'TRACKING' && (
          <div className="animate-slide-up max-w-4xl mx-auto space-y-12">
            <h3 className="text-4xl font-black uppercase italic tracking-tighter">Mission Control</h3>
            {allOrders.length === 0 ? (
              <div className="bg-white p-24 rounded-[60px] text-center border-2 border-dashed border-gray-100 flex flex-col items-center">
                <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center text-gray-200 text-3xl mb-8">
                  <i className="fas fa-satellite-dish"></i>
                </div>
                <p className="font-black text-gray-400 uppercase tracking-[6px]">No Active Signals</p>
                <Button variant="outline" className="mt-8 rounded-2xl px-10" onClick={() => setView('MENU')}>Launch Order</Button>
              </div>
            ) : (
              <div className="space-y-8">
                {allOrders.map(order => (
                  <div key={order.id} className="bg-white p-10 rounded-[50px] border border-gray-100 shadow-sm relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-red-600/5 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10 relative z-10">
