                        return (
                          <div key={s} className="flex flex-col items-center">
                            <div className={`w-14 h-14 rounded-3xl flex items-center justify-center shadow-lg transition-all ${
                              isCompleted || isCurrent ? 'bg-red-600 text-white' : 'bg-gray-100 text-gray-300'
                            }`}>
                              <i className={`fas ${s === OrderStatus.PENDING ? 'fa-bolt' : s === OrderStatus.PREPARING ? 'fa-fire' : s === OrderStatus.READY ? 'fa-motorcycle' : 'fa-house-flag'} text-xl`}></i>
                            </div>
                            <p className={`mt-4 text-[9px] font-black uppercase tracking-widest ${isCompleted || isCurrent ? 'text-gray-900' : 'text-gray-300'}`}>{s}</p>
                          </div>
                        );
                      })}
                    </div>

                    <div className="bg-gray-50/50 backdrop-blur-sm rounded-[35px] p-8 border border-gray-100">
                      <h5 className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-6">Manifest Content</h5>
                      <div className="space-y-4">
                        {order.items.map((item, i) => (
                          <div key={i} className="flex justify-between items-center text-[13px] font-bold">
                            <span className="text-gray-700">{item.quantity}x {item.name}</span>
                            <span className="text-gray-950">৳{item.price * item.quantity}</span>
                          </div>
                        ))}
                        <div className="h-px bg-gray-200 my-4"></div>
                        <div className="flex justify-between items-center text-lg font-black italic">
