];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, onLogout, menuItems, setMenuItems, orders, setOrders 
}) => {
  const allowedTabs = useMemo(() => {
    if (userRole === UserRole.ADMIN) return ['dashboard', 'orders', 'menu-stock', 'reports', 'audit'];
    if (userRole === UserRole.MANAGER) return ['dashboard', 'orders', 'menu-stock'];
    return ['orders'];
  }, [userRole]);

  const [activeTab, setActiveTab] = useState(allowedTabs[0]);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [adminToast, setAdminToast] = useState<{msg: string, type: string} | null>(null);

  // Reports sub-tab state
  const [reportType, setReportType] = useState<'sales' | 'inventory' | 'customers'>('sales');

  const showToast = useCallback((msg: string, type: string) => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 3000);
  }, []);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
    showToast(`Order updated to ${newStatus}`, "success");
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) {
          showToast(`Invalid Operation: Stock < 0`, "error");
          return item;
        }
        return { ...item, stock: newStock };
      }
      return item;
    }));
    showToast('Stock Integrity Synced.', 'success');
  };

  // Customer Behavior Data Aggregation
  const customerBehaviorData = useMemo(() => {
    const customerMap: Record<string, { name: string, totalOrders: number, totalSpend: number, lastOrder: string }> = {};
    orders.forEach(o => {
      if (!customerMap[o.customerId]) {
        customerMap[o.customerId] = { name: o.customerName, totalOrders: 0, totalSpend: 0, lastOrder: o.createdAt };
      }
      customerMap[o.customerId].totalOrders += 1;
      customerMap[o.customerId].totalSpend += o.total;
      if (new Date(o.createdAt) > new Date(customerMap[o.customerId].lastOrder)) {
        customerMap[o.customerId].lastOrder = o.createdAt;
      }
    });
    return Object.values(customerMap).sort((a, b) => b.totalSpend - a.totalSpend);
  }, [orders]);

  // Export Logic
  const handleExportExcel = () => {
    let data: any[] = [];
    let filename = `BFC_Report_${reportType}_${new Date().toISOString().split('T')[0]}.xlsx`;

    if (reportType === 'sales') {
      data = orders.map(o => ({ 
        'Order ID': o.id, 
        'Customer': o.customerName, 
        'Total (৳)': o.total, 
        'Status': o.status, 
        'Payment': o.paymentMethod, 
        'Date': new Date(o.createdAt).toLocaleDateString() 
      }));
    } else if (reportType === 'inventory') {
      data = menuItems.map(m => ({ 
        'Item ID': m.id, 
        'Name': m.name, 
        'Category': m.category, 
        'Price (৳)': m.price, 
        'Stock': m.stock, 
        'Status': m.stock < 10 ? 'LOW' : 'STABLE' 
      }));
    } else if (reportType === 'customers') {
      data = customerBehaviorData.map(c => ({ 
        'Customer Name': c.name, 
        'Total Orders': c.totalOrders, 
        'Total Spend (৳)': c.totalSpend, 
        'Avg Order Value (৳)': (c.totalSpend / c.totalOrders).toFixed(2),
        'Last Active': new Date(c.lastOrder).toLocaleDateString()
      }));
    }

    const worksheet = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Report");
    XLSX.writeFile(workbook, filename);
    showToast(`Excel Export Generated.`, 'success');
  };

  const handleExportPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text(`BFC Hub: ${reportType.toUpperCase()} Report`, 14, 20);
    doc.setFontSize(10);
    doc.text(`Generated on: ${new Date().toLocaleString()}`, 14, 28);

    let head: any[][] = [];
    let body: any[][] = [];

    if (reportType === 'sales') {
      head = [['Order ID', 'Customer', 'Total', 'Status', 'Date']];
      body = orders.map(o => [o.id, o.customerName, `BTD ${o.total}`, o.status, new Date(o.createdAt).toLocaleDateString()]);
    } else if (reportType === 'inventory') {
      head = [['ID', 'Name', 'Category', 'Price', 'Stock']];
      body = menuItems.map(m => [m.id, m.name, m.category, `BTD ${m.price}`, m.stock]);
    } else if (reportType === 'customers') {
      head = [['Customer', 'Orders', 'Total Spend', 'Avg Order', 'Last Active']];
      body = customerBehaviorData.map(c => [
        c.name, 
        c.totalOrders, 
        `BTD ${c.totalSpend}`, 
        `BTD ${(c.totalSpend/c.totalOrders).toFixed(0)}`, 
        new Date(c.lastOrder).toLocaleDateString()
      ]);
    }

    autoTable(doc, {
      head,
      body,
      startY: 35,
      theme: 'striped',
      headStyles: { fillStyle: 'F0F0F0', textColor: [220, 38, 38], fontStyle: 'bold' }
    });

    doc.save(`BFC_Report_${reportType}.pdf`);
    showToast(`PDF Document Exported.`, 'success');
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] dark:bg-gray-950 overflow-hidden font-sans">
      {/* Admin Notifications */}
      {adminToast && (
        <div className={`fixed top-8 left-1/2 -translate-x-1/2 z-[7000] px-8 py-4 rounded-3xl shadow-2xl flex items-center gap-4 animate-slide-up border ${
          adminToast.type === 'error' ? 'bg-red-600 text-white border-red-400' : 'bg-gray-950 text-white border-white/10'
        }`}>
           <i className="fas fa-terminal text-xs"></i>
           <span className="text-[10px] font-black uppercase tracking-[3px]">{adminToast.msg}</span>
        </div>
      )}

      {/* Sidebar Navigation */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 bg-white dark:bg-gray-900 border-r dark:border-gray-800 transition-transform duration-500 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0 shadow-2xl lg:shadow-none'}`}>
        <div className="p-10 border-b dark:border-gray-800 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-red-600 rounded-2xl flex items-center justify-center text-white font-black shadow-xl shadow-red-600/20">B</div>
            <h1 className="text-2xl font-black text-red-600 tracking-tighter italic">BFC HUB</h1>
          </div>
          <button className="lg:hidden w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center text-gray-400" onClick={() => setSidebarOpen(false)}>
            <i className="fas fa-times"></i>
          </button>
        </div>
        <nav className="p-8 space-y-2 overflow-y-auto max-h-[calc(100vh-140px)] scrollbar-hide">
          {allowedTabs.map(tab => (
            <button key={tab} onClick={() => { setActiveTab(tab); setSidebarOpen(false); }} className={`w-full flex items-center gap-5 px-6 py-5 rounded-[24px] transition-all group ${activeTab === tab ? 'bg-red-600 text-white shadow-2xl shadow-red-600/30' : 'text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800'}`}>
              <i className={`fas ${
                tab === 'dashboard' ? 'fa-chart-line' : 
                tab === 'orders' ? 'fa-list-check' : 
                tab === 'menu-stock' ? 'fa-bowl-food' : 
                tab === 'reports' ? 'fa-file-invoice' : 
                'fa-shield-halved'
              } text-sm group-hover:scale-110 transition-transform`}></i> 
              <span className="uppercase text-[10px] font-black tracking-[4px]">{tab.replace('-', ' ')}</span>
            </button>
          ))}
          <div className="pt-12">
            <button onClick={onLogout} className="w-full py-5 text-red-600 font-black uppercase tracking-[5px] text-[9px] border-2 border-red-50 dark:border-red-900/10 rounded-[28px] hover:bg-red-600 hover:text-white transition-all shadow-sm">Terminate Session</button>
          </div>
        </nav>
