                                <td className="p-10 font-black">৳{m.price}</td>
                                <td className="p-10 text-right">
                                   <span className={`font-black text-lg ${m.stock < 10 ? 'text-red-600' : 'text-emerald-500'}`}>{m.stock}</span>
                                   <p className="text-[8px] font-black uppercase tracking-widest text-gray-400">Units</p>
                                </td>
                             </tr>
                          ))}
                          {reportType === 'customers' && customerBehaviorData.map((c, i) => (
                             <tr key={i} className="hover:bg-gray-50/50 dark:hover:bg-gray-800/50 transition-colors">
                                <td className="p-10 flex items-center gap-4">
                                   <div className="w-10 h-10 bg-gray-100 dark:bg-gray-800 rounded-xl flex items-center justify-center font-black text-xs uppercase">{c.name.charAt(0)}</div>
                                   <span className="font-black text-gray-950 dark:text-white italic truncate max-w-[150px]">{c.name}</span>
                                </td>
                                <td className="p-10 font-black">{c.totalOrders}</td>
                                <td className="p-10 font-black text-gray-950 dark:text-white">৳{c.totalSpend.toLocaleString()}</td>
                                <td className="p-10 italic text-gray-400">৳{(c.totalSpend/c.totalOrders).toFixed(0)} / order</td>
                                <td className="p-10 text-right text-gray-400 font-mono text-[10px]">{new Date(c.lastOrder).toLocaleDateString()}</td>
                             </tr>
                          ))}
                       </tbody>
                    </table>
                 </div>
              </div>
            </div>
          )}
        </div>

        <div className="h-24 lg:hidden shrink-0" />
      </main>

      <ChatBot isOnline={true} />
    </div>
  );
};

const StatCard = ({ title, value, icon, color }: any) => (
  <div className="bg-white dark:bg-gray-900 p-10 rounded-[45px] border dark:border-gray-800 flex items-center gap-8 hover:shadow-2xl transition-all group overflow-hidden h-full">
    <div className={`w-16 h-16 bg-gray-50 dark:bg-gray-800 rounded-[28px] flex items-center justify-center text-2xl ${color} shrink-0 group-hover:scale-110 transition-transform shadow-sm`}>
      <i className={`fas ${icon}`}></i>
    </div>
    <div className="min-w-0">
      <p className="text-[10px] font-black text-gray-400 uppercase tracking-[4px] mb-2 truncate leading-none">{title}</p>
      <h4 className="text-3xl font-black text-gray-950 dark:text-white tracking-tighter truncate leading-tight italic">{value}</h4>
    </div>
  </div>
);

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
}

const App: React.FC = () => {
  // Core State
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE'>('HOME');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Menu Filter States
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  // Login States
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  // Checkout States
  const [isCheckingOut, setIsCheckingOut] = useState(false);

  // Computed Values
  const categories = useMemo(() => ['All', ...new Set(menuItems.map(item => item.category))], [menuItems]);

  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [menuItems, searchQuery, activeCategory]);

  const showToast = useCallback((message: string, type: Toast['type'] = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  // Sync Persistence
  useEffect(() => {
    const savedSession = localStorage.getItem('bfc_user_session');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        if (user.role !== UserRole.CUSTOMER) setView('ADMIN');
      } catch (e) { localStorage.removeItem('bfc_user_session'); }
    }
  }, []);

  useEffect(() => {
    const handleOnline = () => { 
      setIsOnline(true); 
      showToast('You are back online! Full access to live menus and orders restored.', 'success'); 
    };
    const handleOffline = () => { 
      setIsOnline(false); 
      showToast('Connection lost. You can still browse the menu, but live updates and orders are paused.', 'error'); 
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => { 
      window.removeEventListener('online', handleOnline); 
      window.removeEventListener('offline', handleOffline); 
    };
  }, [showToast]);

  const handleAuth = async () => {
    if (!formEmail.trim()) {
      showToast('Please enter your email address to continue.', 'warning');
      return;
    }
    if (!formEmail.includes('@')) {
      showToast('The email format looks incorrect. Please check for a proper address (e.g., name@email.com).', 'warning');
      return;
    }
    if (!formPass.trim()) {
      showToast('Security key required. Please enter your password.', 'warning');
      return;
    }
    if (formPass.length < 4) {
      showToast('Password is too short. It must be at least 4 characters long.', 'warning');
      return;
    }

    setIsAuthenticating(true);
    try {
      if (!isOnline) throw new Error('OFFLINE');

      // Simulation delay
      await new Promise(resolve => setTimeout(resolve, 1200));

      const role = formEmail.startsWith('admin') ? UserRole.ADMIN : UserRole.CUSTOMER;
      const user: User = {
        id: 'U1', name: role === UserRole.ADMIN ? 'BFC Admin' : 'Valued Customer', 
        email: formEmail, role, phone: '017', loyaltyPoints: 100, tier: 'GOLD', wishlist: [], referralCode: 'BFC1'
      };

      setCurrentUser(user);
      localStorage.setItem('bfc_user_session', JSON.stringify(user));
      setView(role === UserRole.ADMIN ? 'ADMIN' : 'HOME');
      showToast('Welcome back! You have successfully logged in.', 'success');
    } catch (error: any) {
      if (error.message === 'OFFLINE') {
        showToast('Login failed. Please check your internet connection and try again.', 'error');
      } else {
        showToast('We encountered an error during login. Please double-check your credentials.', 'error');
      }
    } finally {
      setIsAuthenticating(false);
    }
  };

  const handleCheckout = async () => {
    if (!isOnline) {
      showToast('Unable to place order while offline. Please reconnect to the network.', 'error');
      return;
    }
    if (cart.length === 0) {
      showToast('Your cart is empty! Add some delicious food before checking out.', 'warning');
      return;
    }

    setIsCheckingOut(true);
    try {
      // Simulate network request
      await new Promise((resolve, reject) => {
        setTimeout(() => {
          if (Math.random() < 0.1) reject(new Error('GATEWAY_ERROR'));
          else resolve(true);
        }, 2000);
      });

      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser?.id || 'GUEST',
        customerName: currentUser?.name || 'Guest User',
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total: cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: 'PAID',
        paymentMethod: 'BKASH',
        address: 'Dhaka Terminal',
        deliveryZone: 'Dhaka',
        deliverySlot: 'ASAP',
        pointsEarned: 10,
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };

      setAllOrders(prev => [newOrder, ...prev]);
      setCart([]);
      setView('TRACKING');
      showToast('Order confirmed! We are starting the preparation right away.', 'success');
    } catch (error: any) {
      if (error.message === 'GATEWAY_ERROR') {
        showToast('The payment gateway is temporarily busy. Please try processing your order again.', 'error');
      } else {
        showToast('Something went wrong with the order. Please try again or contact support.', 'error');
      }
    } finally {
      setIsCheckingOut(false);
    }
  };

  const addToCart = (item: MenuItem) => {
    if (item.stock <= 0) {
      showToast(`Sorry, ${item.name} is currently out of stock.`, 'warning');
      return;
    }
    setCart(prev => {
      const existing = prev.find(c => c.item.id === item.id);
      if (existing) return prev.map(c => c.item.id === item.id ? { ...c, qty: c.qty + 1 } : c);
      return [...prev, { item, qty: 1 }];
    });
    showToast(`${item.name} added to your selection.`, 'success');
  };

  if (view === 'ADMIN' && currentUser?.role !== UserRole.CUSTOMER) {
    return (
      <AdminPanel 
        userRole={currentUser!.role} 
        onLogout={() => { setCurrentUser(null); setView('HOME'); localStorage.removeItem('bfc_user_session'); }}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans">
      {/* Network Status Bar */}
      {!isOnline && (
        <div className="fixed top-0 left-0 w-full z-[6000] bg-red-600 text-white py-1 px-4 text-center">
          <p className="text-[9px] font-black uppercase tracking-widest">You are currently offline. Browse freely, but orders require a connection.</p>
        </div>
      )}

      {/* Toast Overlay */}
      <div className="fixed top-12 right-6 z-[5500] space-y-3 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} className={`pointer-events-auto px-6 py-4 rounded-2xl shadow-2xl border bg-white animate-slide-up flex items-start gap-4 ${
            t.type === 'error' ? 'border-red-100' : 
            t.type === 'warning' ? 'border-amber-100' : 
            'border-emerald-100'
          }`}>
            <div className={`mt-0.5 w-6 h-6 rounded-lg flex items-center justify-center shrink-0 ${
              t.type === 'error' ? 'bg-red-50 text-red-600' : 
              t.type === 'warning' ? 'bg-amber-50 text-amber-600' : 
              'bg-emerald-50 text-emerald-600'
            }`}>
              <i className={`fas ${
                t.type === 'error' ? 'fa-circle-xmark' : 
                t.type === 'warning' ? 'fa-triangle-exclamation' : 
                'fa-circle-check'
              } text-[10px]`}></i>
            </div>
            <div className="flex-1">
              <p className="font-bold text-[10px] text-gray-800 uppercase tracking-tight leading-tight">
                {t.message}
              </p>
            </div>
          </div>
        ))}
      </div>

      {/* Desktop Navigation */}
      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-12 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white text-xl font-black shadow-lg shadow-red-600/20">B</div>
          <h1 className="text-2xl font-black text-red-600 tracking-tighter italic">BFC</h1>
        </div>

        <div className="hidden md:flex gap-10">
          {['HOME', 'MENU', 'TRACKING'].map(v => (
            <button 
              key={v} 
              onClick={() => setView(v as any)}
              className={`text-[10px] font-black uppercase tracking-[3px] transition-all hover:text-red-600 ${view === v ? 'text-red-600' : 'text-gray-400'}`}
            >
              {v}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-4">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 bg-white rounded-2xl border flex items-center justify-center shadow-sm hover:border-red-600 transition-colors group">
            <i className="fas fa-shopping-basket text-gray-700 group-hover:text-red-600"></i>
            {cart.length > 0 && (
              <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[9px] w-6 h-6 rounded-full flex items-center justify-center font-black animate-bounce shadow-lg">
                {cart.length}
              </span>
            )}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-12 h-12 rounded-2xl bg-gray-950 text-white font-black flex items-center justify-center uppercase shadow-xl hover:scale-105 transition-transform">
              {currentUser.name.charAt(0)}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl px-6" onClick={() => setView('LOGIN')}>Login</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-10">
        {view === 'HOME' && (
          <div className="animate-slide-up space-y-16">
            <header className="relative h-[450px] lg:h-[600px] rounded-[50px] overflow-hidden shadow-2xl group border-8 border-white">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" alt="BFC Hero" />
               <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent flex flex-col justify-end p-12 lg:p-20">
                  <h2 className="text-5xl lg:text-8xl font-black text-white leading-[0.85] mb-8 tracking-tighter italic">LEGENDARY<br/><span className="text-red-600">DHAKA TASTE</span></h2>
                  <div className="flex gap-4">
                    <Button size="lg" className="rounded-2xl" onClick={() => setView('MENU')}>View Vault Menu</Button>
                    <button onClick={() => setView('TRACKING')} className="px-8 py-4 bg-white/10 backdrop-blur-md text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-white/20 transition-all border border-white/20">Track Mission</button>
                  </div>
               </div>
            </header>

            <section>
              <div className="flex justify-between items-end mb-10">
                <div>
                  <h3 className="text-3xl font-black uppercase italic tracking-tighter">Current Hotlist</h3>
                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mt-1">Trending flavors across Dhaka nodes</p>
                </div>
                <button onClick={() => setView('MENU')} className="text-[10px] font-black text-red-600 uppercase tracking-widest border-b-2 border-red-600 pb-1">See All</button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                {menuItems.filter(i => i.isPopular).map(item => (
                  <div key={item.id} className="bg-white rounded-[45px] overflow-hidden shadow-sm border border-gray-50 p-6 hover:shadow-2xl transition-all group">
                     <div className="relative h-64 rounded-[35px] overflow-hidden mb-6">
                       <img src={item.image} className="h-full w-full object-cover group-hover:scale-110 transition-transform" alt={item.name} />
                       <div className="absolute top-5 right-5 bg-white/90 backdrop-blur-md px-4 py-2 rounded-2xl font-black text-xs">৳{item.price}</div>
                     </div>
                     <h4 className="text-2xl font-black text-gray-900 leading-tight mb-2">{item.name}</h4>
                     <p className="text-xs text-gray-400 mb-8 line-clamp-2 leading-relaxed">{item.description}</p>
                     <Button fullWidth variant="outline" className="rounded-2xl py-4" onClick={() => addToCart(item)}>Add to Payload</Button>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {view === 'MENU' && (
          <div className="animate-slide-up space-y-10">
            <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-8">
              <div>
                <h3 className="text-4xl font-black uppercase italic tracking-tighter leading-none">The Vault Menu</h3>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[4px] mt-2 italic">Secured local recipes and global fusion</p>
              </div>
              <div className="relative w-full lg:w-1/3">
                <i className="fas fa-search absolute left-5 top-1/2 -translate-y-1/2 text-gray-400 text-sm"></i>
                <input 
                  type="text" 
                  placeholder="Kacchi, Roast, Rezala..." 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full bg-white border border-gray-100 p-5 pl-14 rounded-3xl outline-none focus:border-red-600 transition-colors font-bold text-xs shadow-sm"
                />
              </div>
            </div>

            <div className="flex gap-3 overflow-x-auto pb-4 scrollbar-hide">
              {categories.map(cat => (
                <button 
                  key={cat} 
                  onClick={() => setActiveCategory(cat)}
                  className={`px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap shadow-sm ${
                    activeCategory === cat ? 'bg-red-600 text-white shadow-red-600/30' : 'bg-white text-gray-400 border border-gray-50 hover:border-red-100'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
              {filteredMenu.map(item => (
                <div key={item.id} className="bg-white rounded-[50px] border border-gray-100 p-5 hover:shadow-2xl transition-all group flex flex-col h-full">
                   <div className="relative overflow-hidden rounded-[40px] mb-6 h-60 shrink-0">
                      <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={item.name} />
                      <div className="absolute top-5 right-5 bg-red-600 text-white px-4 py-2 rounded-2xl shadow-lg font-black text-[11px]">৳{item.price}</div>
                   </div>
                   <div className="px-3 flex-1 flex flex-col">
                      <div className="flex justify-between items-start mb-2">
                        <h4 className="font-black text-gray-950 text-xl leading-tight truncate pr-2">{item.name}</h4>
                        <div className="flex items-center gap-1.5 bg-amber-50 px-2 py-1 rounded-lg">
                          <i className="fas fa-star text-amber-500 text-[10px]"></i>
                          <span className="text-[10px] font-black text-amber-700">{item.rating}</span>
                        </div>
                      </div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-6 italic">{item.nameBn}</p>
                      <div className="mt-auto">
                        <Button fullWidth size="md" className="rounded-2xl shadow-lg shadow-red-600/10 py-4" onClick={() => addToCart(item)}>
                          <i className="fas fa-plus mr-3 text-[10px]"></i> Buy Now
                        </Button>
                      </div>
                   </div>
                </div>
              ))}
              {filteredMenu.length === 0 && (
                <div className="col-span-full py-20 text-center opacity-30 italic font-black uppercase tracking-widest">No results matched your search. Try different terms.</div>
              )}
            </div>
          </div>
        )}

        {view === 'TRACKING' && (
          <div className="animate-slide-up max-w-4xl mx-auto space-y-12">
            <h3 className="text-4xl font-black uppercase italic tracking-tighter">Mission Control</h3>
            {allOrders.length === 0 ? (
              <div className="bg-white p-24 rounded-[60px] text-center border-2 border-dashed border-gray-100 flex flex-col items-center">
                <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center text-gray-200 text-3xl mb-8">
                  <i className="fas fa-satellite-dish"></i>
                </div>
                <p className="font-black text-gray-400 uppercase tracking-[6px]">No Active Orders</p>
                <p className="text-xs text-gray-400 mt-2">Place your first order to see real-time updates here.</p>
                <Button variant="outline" className="mt-8 rounded-2xl px-10" onClick={() => setView('MENU')}>View Menu</Button>
              </div>
            ) : (
              <div className="space-y-8">
                {allOrders.map(order => (
                  <div key={order.id} className="bg-white p-10 rounded-[50px] border border-gray-100 shadow-sm relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-red-600/5 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10 relative z-10">
                      <div>
                        <p className="text-[10px] font-black text-red-600 uppercase tracking-[4px] mb-2">Order Identification</p>
                        <h4 className="text-2xl font-black italic tracking-tight">#{order.id}</h4>
                      </div>
                      <div className="bg-emerald-600 text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-emerald-600/20">
                        {order.status}
                      </div>
                    </div>

                    <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mb-12">
                      {[OrderStatus.PENDING, OrderStatus.PREPARING, OrderStatus.READY, OrderStatus.DELIVERED].map((s, idx) => {
                        const isCompleted = order.trackingUpdates.some(u => u.status === s);
                        const isCurrent = order.status === s;
                        return (
                          <div key={s} className="flex flex-col items-center">
                            <div className={`w-14 h-14 rounded-3xl flex items-center justify-center shadow-lg transition-all ${
                              isCompleted || isCurrent ? 'bg-red-600 text-white' : 'bg-gray-100 text-gray-300'
                            }`}>
                              <i className={`fas ${s === OrderStatus.PENDING ? 'fa-bolt' : s === OrderStatus.PREPARING ? 'fa-fire' : s === OrderStatus.READY ? 'fa-motorcycle' : 'fa-house-flag'} text-xl`}></i>
                            </div>
                            <p className={`mt-4 text-[9px] font-black uppercase tracking-widest ${isCompleted || isCurrent ? 'text-gray-900' : 'text-gray-300'}`}>{s}</p>
                          </div>
                        );
                      })}
                    </div>

                    <div className="bg-gray-50/50 backdrop-blur-sm rounded-[35px] p-8 border border-gray-100">
                      <h5 className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-6">Manifest Content</h5>
                      <div className="space-y-4">
                        {order.items.map((item, i) => (
                          <div key={i} className="flex justify-between items-center text-[13px] font-bold">
                            <span className="text-gray-700">{item.quantity}x {item.name}</span>
                            <span className="text-gray-950">৳{item.price * item.quantity}</span>
                          </div>
                        ))}
                        <div className="h-px bg-gray-200 my-4"></div>
                        <div className="flex justify-between items-center text-lg font-black italic">
                          <span>Final Payload Value</span>
                          <span className="text-red-600">৳{order.total}</span>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-5xl mx-auto space-y-12 animate-slide-up">
            <h3 className="text-4xl font-black uppercase italic tracking-tighter">Current Selection</h3>
            {cart.length === 0 ? (
              <div className="bg-white p-24 rounded-[60px] text-center border-2 border-dashed border-gray-100">
                <i className="fas fa-cart-arrow-down text-5xl text-gray-100 mb-8"></i>
                <p className="font-black text-gray-400 uppercase tracking-[6px]">Your payload is empty</p>
                <p className="text-xs text-gray-400 mt-2">Browse the menu to add legendary flavors to your cart.</p>
                <Button variant="outline" className="mt-10 rounded-2xl px-12" onClick={() => setView('MENU')}>View Menu</Button>
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
                <div className="lg:col-span-2 space-y-6">
                  {cart.map((c, i) => (
                    <div key={i} className="bg-white p-8 rounded-[40px] border border-gray-50 flex flex-col sm:flex-row items-center gap-8 shadow-sm hover:shadow-xl transition-all">
                      <img src={c.item.image} className="w-32 h-32 rounded-[30px] object-cover shadow-lg shrink-0" alt={c.item.name} />
                      <div className="flex-1 text-center sm:text-left">
                        <h4 className="font-black text-gray-900 text-2xl leading-tight mb-2">{c.item.name}</h4>
                        <p className="text-[11px] font-black text-red-600 uppercase tracking-widest mb-4">৳{c.item.price} per Unit</p>
                        <div className="flex items-center justify-center sm:justify-start gap-6">
                          <div className="flex items-center gap-4 bg-gray-50 p-2 rounded-2xl border">
                            <button onClick={() => setCart(prev => prev.map((it, idx) => idx === i ? {...it, qty: Math.max(1, it.qty-1)} : it))} className="w-10 h-10 rounded-xl bg-white flex items-center justify-center font-black hover:bg-red-50 transition-colors shadow-sm">-</button>
                            <span className="font-black w-8 text-center text-lg">{c.qty}</span>
                            <button onClick={() => setCart(prev => prev.map((it, idx) => idx === i ? {...it, qty: it.qty+1} : it))} className="w-10 h-10 rounded-xl bg-gray-950 text-white flex items-center justify-center font-black hover:scale-105 transition-transform shadow-lg">+</button>
                          </div>
                          <button onClick={() => { setCart(prev => prev.filter((_, idx) => idx !== i)); showToast(`Removed ${c.item.name} from selection.`, 'warning'); }} className="text-gray-300 hover:text-red-600 transition-colors">
                            <i className="fas fa-trash-alt text-lg"></i>
                          </button>
                        </div>
                      </div>
                      <div className="text-right shrink-0">
                         <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Item Total</p>
                         <p className="text-2xl font-black italic text-gray-950">৳{c.item.price * c.qty}</p>
                      </div>
                    </div>
                  ))}
                </div>

                <div className="bg-white p-10 rounded-[55px] border border-gray-100 h-fit space-y-10 sticky top-32 shadow-2xl">
                  <h4 className="font-black text-[11px] uppercase tracking-[4px] text-gray-400 italic">Bill Summary</h4>
                  <div className="space-y-4">
                     <div className="flex justify-between text-sm font-bold text-gray-600 uppercase tracking-tight">
                        <span>Subtotal</span>
                        <span>৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0)}</span>
                     </div>
                     <div className="flex justify-between text-sm font-bold text-gray-600 uppercase tracking-tight">
                        <span>Delivery</span>
                        <span>৳50</span>
                     </div>
                     <div className="h-px bg-gray-100 my-6"></div>
                     <div className="flex justify-between text-3xl font-black text-gray-950 italic tracking-tighter">
                        <span>Total Due</span>
                        <span className="text-red-600">৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50}</span>
                     </div>
                  </div>

                  <div className="space-y-4">
                    <p className="text-[10px] font-black uppercase tracking-[4px] text-gray-400 mb-4 italic">Select Payment</p>
                    <div className="grid grid-cols-1 gap-3">
                       <button className="flex items-center justify-between p-5 rounded-3xl border-2 border-red-600 bg-red-50 text-red-600 font-black text-[11px] uppercase tracking-widest transition-all">
                         <span>bKash (Verified)</span>
                         <i className="fas fa-check-circle"></i>
                       </button>
                       <button className="flex items-center justify-between p-5 rounded-3xl border-2 border-gray-50 bg-gray-50 text-gray-400 font-black text-[11px] uppercase tracking-widest opacity-50 cursor-not-allowed">
                         <span>Nagad / Rocket</span>
                         <i className="fas fa-lock text-[8px]"></i>
                       </button>
                    </div>
                  </div>

                  <Button fullWidth size="lg" className="rounded-3xl shadow-2xl shadow-red-600/30 py-5" onClick={handleCheckout} disabled={isCheckingOut}>
                    {isCheckingOut ? (
                      <span className="flex items-center gap-3">
                        <i className="fas fa-circle-notch animate-spin text-[10px]"></i> Processing...
                      </span>
                    ) : (
                      <span className="flex items-center gap-3">
                        <i className="fas fa-bolt text-[10px]"></i> Secure Checkout
                      </span>
                    )}
                  </Button>
                </div>
              </div>
            )}
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto py-16 animate-slide-up">
             <div className="bg-white p-14 rounded-[60px] shadow-3xl border border-gray-50 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-red-600 to-orange-500"></div>
                <div className="flex justify-center mb-10">
                   <div className="w-20 h-20 bg-gray-950 rounded-3xl flex items-center justify-center text-white text-3xl shadow-2xl">
                      <i className="fas fa-key"></i>
                   </div>
                </div>
                <h3 className="text-4xl font-black text-center mb-12 uppercase italic tracking-tighter">Login Access</h3>
                <div className="space-y-6">
                  <div>
                    <label className="text-[10px] font-black uppercase tracking-[3px] text-gray-400 ml-4 block mb-2">Registered Email</label>
                    <input 
                      type="email" 
                      value={formEmail} 
                      onChange={e => setFormEmail(e.target.value)} 
                      placeholder="boss@bfc.com" 
                      className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none border-2 border-transparent focus:border-red-600 transition-colors shadow-inner" 
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase tracking-[3px] text-gray-400 ml-4 block mb-2">Secret Password</label>
                    <input 
                      type="password" 
                      value={formPass} 
                      onChange={e => setFormPass(e.target.value)} 
                      placeholder="••••••••" 
                      className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none border-2 border-transparent focus:border-red-600 transition-colors shadow-inner" 
                    />
                  </div>
                  <Button fullWidth size="lg" className="rounded-3xl mt-12 py-5 shadow-2xl shadow-red-600/20" onClick={handleAuth} disabled={isAuthenticating}>
                    {isAuthenticating ? 'Authenticating...' : 'Sign In Now'}
                  </Button>
                  <p className="text-center text-[8px] font-black text-gray-400 uppercase tracking-widest mt-6 px-4">
                    By signing in, you agree to our terms. Use 'admin@bfc.com' to test admin features.
                  </p>
                </div>
             </div>
          </div>
        )}
      </main>

      {/* Mobile Sticky Footer */}
      <nav className="lg:hidden fixed bottom-0 left-0 w-full bg-white/90 backdrop-blur-xl border-t border-gray-100 flex justify-around p-5 z-[5000] shadow-[0_-20px_40px_-20px_rgba(0,0,0,0.1)]">
        {[
          { icon: 'fa-home', label: 'Home', view: 'HOME' },
          { icon: 'fa-utensils', label: 'Menu', view: 'MENU' },
          { icon: 'fa-rocket', label: 'Track', view: 'TRACKING' },
          { icon: 'fa-user', label: 'Profile', view: 'PROFILE' }
        ].map(nav => (
          <button 
            key={nav.view}
            onClick={() => setView(nav.view as any)} 
            className={`flex flex-col items-center gap-1.5 transition-all ${view === nav.view ? 'text-red-600' : 'text-gray-400'}`}
          >
            <i className={`fas ${nav.icon} text-xl`}></i>
            <span className="text-[8px] font-black uppercase tracking-widest">{nav.label}</span>
          </button>
        ))}
      </nav>

      <ChatBot isOnline={isOnline} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User } from './types';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 }, { name: 'Sun', sales: 3800 }, { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 }, { name: 'Wed', sales: 6200 }, { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, onLogout, menuItems, setMenuItems, orders, setOrders 
}) => {
  const allowedTabs = useMemo(() => {
    if (userRole === UserRole.ADMIN) return ['dashboard', 'orders', 'menu-stock', 'reports', 'audit'];
    if (userRole === UserRole.MANAGER) return ['dashboard', 'orders', 'menu-stock'];
    return ['orders'];
  }, [userRole]);

  const [activeTab, setActiveTab] = useState(allowedTabs[0]);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [adminToast, setAdminToast] = useState<{msg: string, type: string} | null>(null);

  // Reports sub-tab state
  const [reportType, setReportType] = useState<'sales' | 'inventory' | 'customers'>('sales');

  const showToast = useCallback((msg: string, type: string) => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    try {
      setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
      showToast(`Order #${orderId.slice(-4)} status successfully updated to ${newStatus}.`, "success");
    } catch (e) {
      showToast("Could not update order status. Please refresh and try again.", "error");
    }
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) {
          showToast(`Invalid action: Stock for ${item.name} cannot be less than zero.`, "error");
          return item;
        }
        showToast(`Stock for ${item.name} updated to ${newStock}.`, "success");
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  // Customer Behavior Data Aggregation
  const customerBehaviorData = useMemo(() => {
    const customerMap: Record<string, { name: string, totalOrders: number, totalSpend: number, lastOrder: string }> = {};
    orders.forEach(o => {
      if (!customerMap[o.customerId]) {
        customerMap[o.customerId] = { name: o.customerName, totalOrders: 0, totalSpend: 0, lastOrder: o.createdAt };
      }
      customerMap[o.customerId].totalOrders += 1;
      customerMap[o.customerId].totalSpend += o.total;
      if (new Date(o.createdAt) > new Date(customerMap[o.customerId].lastOrder)) {
        customerMap[o.customerId].lastOrder = o.createdAt;
      }
    });
    return Object.values(customerMap).sort((a, b) => b.totalSpend - a.totalSpend);
  }, [orders]);

  // Export Logic
  const handleExportExcel = () => {
    try {
      let data: any[] = [];
      let filename = `BFC_Report_${reportType}_${new Date().toISOString().split('T')[0]}.xlsx`;

      if (reportType === 'sales') {
        data = orders.map(o => ({ 
          'Order ID': o.id, 
          'Customer': o.customerName, 
          'Total (৳)': o.total, 
          'Status': o.status, 
          'Payment': o.paymentMethod, 
          'Date': new Date(o.createdAt).toLocaleDateString() 
        }));
      } else if (reportType === 'inventory') {
        data = menuItems.map(m => ({ 
          'Item ID': m.id, 
          'Name': m.name, 
          'Category': m.category, 
          'Price (৳)': m.price, 
          'Stock': m.stock, 
          'Status': m.stock < 10 ? 'LOW' : 'STABLE' 
        }));
      } else if (reportType === 'customers') {
        data = customerBehaviorData.map(c => ({ 
          'Customer Name': c.name, 
          'Total Orders': c.totalOrders, 
          'Total Spend (৳)': c.totalSpend, 
          'Avg Order Value (৳)': (c.totalSpend / c.totalOrders).toFixed(2),
          'Last Active': new Date(c.lastOrder).toLocaleDateString()
        }));
      }

      if (data.length === 0) {
        showToast(`Export failed: No data available for the selected ${reportType} report.`, "warning");
        return;
      }

      const worksheet = XLSX.utils.json_to_sheet(data);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Report");
      XLSX.writeFile(workbook, filename);
      showToast(`Excel spreadsheet for ${reportType} generated and downloaded.`, 'success');
    } catch (err) {
      showToast("Unable to generate Excel file. Please ensure you are not using an old browser.", "error");
    }
  };

  const handleExportPDF = () => {
    try {
      const doc = new jsPDF();
      doc.setFontSize(18);
      doc.text(`BFC Hub: ${reportType.toUpperCase()} Report`, 14, 20);
      doc.setFontSize(10);
      doc.text(`Generated on: ${new Date().toLocaleString()}`, 14, 28);

      let head: any[][] = [];
      let body: any[][] = [];

      if (reportType === 'sales') {
        head = [['Order ID', 'Customer', 'Total', 'Status', 'Date']];
        body = orders.map(o => [o.id, o.customerName, `৳${o.total}`, o.status, new Date(o.createdAt).toLocaleDateString()]);
      } else if (reportType === 'inventory') {
        head = [['ID', 'Name', 'Category', 'Price', 'Stock']];
        body = menuItems.map(m => [m.id, m.name, m.category, `৳${m.price}`, m.stock]);
      } else if (reportType === 'customers') {
        head = [['Customer', 'Orders', 'Total Spend', 'Avg Order', 'Last Active']];
        body = customerBehaviorData.map(c => [
          c.name, 
          c.totalOrders, 
          `৳${c.totalSpend}`, 
          `৳${(c.totalSpend/c.totalOrders).toFixed(0)}`, 
          new Date(c.lastOrder).toLocaleDateString()
        ]);
      }

      if (body.length === 0) {
        showToast(`Nothing to export: The ${reportType} dataset is currently empty.`, "warning");
        return;
      }

      autoTable(doc, {
        head,
        body,
        startY: 35,
        theme: 'striped',
        headStyles: { fillColor: [220, 38, 38], textColor: [255, 255, 255], fontStyle: 'bold' }
      });

      doc.save(`BFC_Report_${reportType}.pdf`);
      showToast(`PDF document for ${reportType} successfully exported.`, 'success');
    } catch (err) {
      showToast("PDF generation encountered an error. Please try refreshing the node.", "error");
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] dark:bg-gray-950 overflow-hidden font-sans">
      {/* Admin Notifications */}
      {adminToast && (
        <div className={`fixed top-8 left-1/2 -translate-x-1/2 z-[7000] px-8 py-4 rounded-3xl shadow-2xl flex items-center gap-4 animate-slide-up border ${
          adminToast.type === 'error' ? 'bg-red-600 text-white border-red-400' : 
          adminToast.type === 'warning' ? 'bg-amber-500 text-white border-amber-400' :
          'bg-gray-950 text-white border-white/10'
        }`}>
           <i className={`fas ${adminToast.type === 'error' ? 'fa-circle-xmark' : adminToast.type === 'warning' ? 'fa-triangle-exclamation' : 'fa-terminal'} text-xs`}></i>
           <span className="text-[10px] font-black uppercase tracking-[3px]">{adminToast.msg}</span>
        </div>
      )}

      {/* Sidebar Navigation */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-72 bg-white dark:bg-gray-900 border-r dark:border-gray-800 transition-transform duration-500 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0 shadow-2xl lg:shadow-none'}`}>
        <div className="p-10 border-b dark:border-gray-800 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-red-600 rounded-2xl flex items-center justify-center text-white font-black shadow-xl shadow-red-600/20">B</div>
            <h1 className="text-2xl font-black text-red-600 tracking-tighter italic">BFC HUB</h1>
          </div>
          <button className="lg:hidden w-10 h-10 bg-gray-50 rounded-xl flex items-center justify-center text-gray-400" onClick={() => setSidebarOpen(false)}>
            <i className="fas fa-times"></i>
          </button>
        </div>
        <nav className="p-8 space-y-2 overflow-y-auto max-h-[calc(100vh-140px)] scrollbar-hide">
          {allowedTabs.map(tab => (
            <button key={tab} onClick={() => { setActiveTab(tab); setSidebarOpen(false); }} className={`w-full flex items-center gap-5 px-6 py-5 rounded-[24px] transition-all group ${activeTab === tab ? 'bg-red-600 text-white shadow-2xl shadow-red-600/30' : 'text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800'}`}>
              <i className={`fas ${
                tab === 'dashboard' ? 'fa-chart-line' : 
                tab === 'orders' ? 'fa-list-check' : 
                tab === 'menu-stock' ? 'fa-bowl-food' : 
                tab === 'reports' ? 'fa-file-invoice' : 
                'fa-shield-halved'
              } text-sm group-hover:scale-110 transition-transform`}></i> 
              <span className="uppercase text-[10px] font-black tracking-[4px]">{tab.replace('-', ' ')}</span>
            </button>
          ))}
          <div className="pt-12">
            <button onClick={onLogout} className="w-full py-5 text-red-600 font-black uppercase tracking-[5px] text-[9px] border-2 border-red-50 dark:border-red-900/10 rounded-[28px] hover:bg-red-600 hover:text-white transition-all shadow-sm">Logout Terminal</button>
          </div>
        </nav>
      </aside>

      {/* Admin Content Area */}
      <main className="flex-1 overflow-y-auto bg-[#F8FAFC] dark:bg-gray-950 flex flex-col scrollbar-hide">
        <header className="sticky top-0 z-40 bg-white/90 dark:bg-gray-900/90 backdrop-blur-xl border-b dark:border-gray-800 px-10 py-6 flex items-center justify-between">
           <div className="flex items-center gap-6">
             <button className="lg:hidden w-12 h-12 bg-gray-50 dark:bg-gray-800 rounded-2xl flex items-center justify-center text-gray-600 dark:text-gray-400" onClick={() => setSidebarOpen(true)}>
               <i className="fas fa-bars"></i>
             </button>
             <div>
               <h2 className="text-3xl font-black uppercase italic tracking-tighter leading-none">{activeTab.replace('-', ' ')} Interface</h2>
               <p className="text-[9px] font-black text-gray-400 uppercase tracking-[4px] mt-2">Authority Level: {userRole}</p>
             </div>
           </div>

           <div className="flex items-center gap-5">
             <div className="hidden md:flex flex-col items-end px-6 py-2 rounded-2xl border border-gray-100 dark:border-gray-800 bg-white/50 dark:bg-gray-900/50">
                <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest">Mainframe Status</p>
                <p className="text-[11px] font-black dark:text-white uppercase">Operational 🟢</p>
             </div>
             <div className="w-12 h-12 bg-gray-950 text-white rounded-2xl flex items-center justify-center font-black text-sm shadow-2xl border-2 border-white/5 uppercase">
               {userRole.charAt(0)}
             </div>
           </div>
        </header>

        <div className="p-10 space-y-12 max-w-[1600px] mx-auto w-full">
          {activeTab === 'dashboard' && (
            <div className="animate-slide-up space-y-12">
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-8">
                <StatCard title="Revenue Stream" value={`৳${orders.reduce((a,b)=>a+b.total, 0).toLocaleString()}`} icon="fa-taka-sign" color="text-red-600" />
                <StatCard title="Successful Missions" value={orders.length} icon="fa-rocket" color="text-blue-600" />
                <StatCard title="Inventory Nodes" value={menuItems.length} icon="fa-bowl-rice" color="text-amber-500" />
                <StatCard title="Fleet Strength" value="12 Units" icon="fa-truck-fast" color="text-purple-600" />
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
                <div className="lg:col-span-2 bg-white dark:bg-gray-900 p-10 rounded-[55px] border dark:border-gray-800 shadow-sm">
                  <div className="flex items-center justify-between mb-10">
                    <h3 className="text-[11px] font-black uppercase tracking-[5px] text-gray-400 italic">Financial Velocity</h3>
                    <div className="flex items-center gap-3">
                       <span className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse shadow-lg shadow-emerald-500/40"></span>
                       <span className="text-[9px] font-black text-gray-400 uppercase tracking-[2px]">Real-time Feed</span>
                    </div>
                  </div>
                  <div className="h-[350px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={ANALYTICS_DATA}>
                        <defs>
                          <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor="#dc2626" stopOpacity={0.2}/>
                            <stop offset="95%" stopColor="#dc2626" stopOpacity={0}/>
                          </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'black', textTransform: 'uppercase'}} />
                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'black'}} />
                        <Tooltip contentStyle={{borderRadius: '25px', border: 'none', boxShadow: '0 20px 50px -10px rgba(0,0,0,0.1)'}} />
                        <Area type="monotone" dataKey="sales" stroke="#dc2626" strokeWidth={5} fill="url(#colorSales)" />
                      </AreaChart>
                    </ResponsiveContainer>
                  </div>
                </div>

                <div className="bg-white dark:bg-gray-900 p-10 rounded-[55px] border dark:border-gray-800 shadow-sm flex flex-col">
                  <h3 className="text-[11px] font-black uppercase tracking-[5px] text-gray-400 italic mb-10">Security Intel</h3>
                  <div className="space-y-8 flex-1">
                     <p className="text-[13px] font-black text-gray-500 leading-relaxed uppercase tracking-widest italic">All systems green. Mainframe sync at 100%. Check Inventory tab for low-stock alerts in Sector B.</p>
                     <div className="p-6 bg-red-50 dark:bg-red-950/20 rounded-3xl border border-red-100 dark:border-red-900/30">
                        <p className="text-[9px] font-black text-red-600 uppercase mb-2">Priority Notice</p>
                        <p className="text-[11px] font-bold dark:text-gray-300">"Kacchi Biryani" stock is nearing critical levels. Replenish immediately.</p>
                     </div>
                  </div>
                  <button className="w-full py-5 bg-gray-950 dark:bg-white dark:text-gray-950 text-white rounded-[28px] text-[10px] font-black uppercase tracking-widest hover:scale-105 transition-all shadow-xl">Detailed Insights</button>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'orders' && (
            <div className="animate-slide-up space-y-8">
              <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                <h3 className="text-3xl font-black uppercase italic tracking-tighter leading-none">Mission Control stream</h3>
                <div className="relative w-full md:w-80">
                  <i className="fas fa-search absolute left-5 top-1/2 -translate-y-1/2 text-gray-400 text-sm"></i>
                  <input type="text" placeholder="Search orders..." className="w-full bg-white dark:bg-gray-900 py-4 pl-14 pr-6 rounded-2xl text-[11px] font-black outline-none border border-gray-100 dark:border-gray-800 focus:border-red-600 transition-colors shadow-sm uppercase tracking-widest" />
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 2xl:grid-cols-3 gap-8">
                {orders.map(o => (
                  <div key={o.id} className="bg-white dark:bg-gray-900 p-8 rounded-[45px] border dark:border-gray-800 flex flex-col justify-between group hover:shadow-2xl transition-all border-l-8 border-l-red-600">
                    <div className="flex justify-between items-start mb-6">
                       <div>
                        <p className="text-[10px] font-black text-red-600 mb-2 tracking-[3px]">SIGNATURE: #{o.id.slice(-5)}</p>
                        <h4 className="font-black text-gray-950 dark:text-white uppercase italic text-2xl truncate pr-4">{o.customerName}</h4>
                       </div>
                       <div className="bg-gray-50 dark:bg-gray-800 p-3 rounded-2xl text-[10px] font-black text-gray-400">
                         {new Date(o.createdAt).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}
                       </div>
                    </div>
                    <div className="space-y-3 mb-8">
                       <p className="text-[11px] font-bold text-gray-400 uppercase tracking-widest">৳{o.total} • {o.items.length} Units • {o.paymentMethod}</p>
                       <p className="text-[11px] font-bold text-gray-900 dark:text-gray-100 truncate"><i className="fas fa-map-marker-alt mr-2 text-red-600"></i>{o.address}</p>
                    </div>
                    <div className="flex gap-3">
                       <select 
                        className="flex-1 bg-gray-50 dark:bg-gray-800 border-none rounded-2xl p-4 text-[10px] font-black uppercase tracking-widest outline-none cursor-pointer dark:text-white focus:ring-4 ring-red-600/10"
                        value={o.status}
                        onChange={(e) => handleUpdateStatus(o.id, e.target.value as OrderStatus)}
                       >
                         {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                       </select>
                       <button className="w-14 h-14 bg-gray-950 text-white rounded-2xl flex items-center justify-center hover:bg-red-600 transition-colors shadow-lg">
                          <i className="fas fa-print text-xs"></i>
                       </button>
                    </div>
                  </div>
                ))}
                {orders.length === 0 && (
                  <div className="col-span-full py-20 text-center text-gray-400 font-black uppercase tracking-widest italic opacity-40">No active missions detected.</div>
                )}
              </div>
            </div>
          )}

          {activeTab === 'menu-stock' && (
            <div className="animate-slide-up space-y-10">
              <div className="flex justify-between items-end">
                <div>
                  <h3 className="text-4xl font-black uppercase italic tracking-tighter leading-none">Node Inventory</h3>
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-[4px] mt-2 italic">Maintain menu node integrity and availability</p>
                </div>
                <button className="px-8 py-4 bg-gray-950 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:scale-105 transition-all shadow-xl">Sync Nodes</button>
              </div>
              <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 2xl:grid-cols-6 gap-8">
                {menuItems.map(item => (
                  <div key={item.id} className="bg-white dark:bg-gray-900 p-8 rounded-[45px] border dark:border-gray-800 shadow-sm flex flex-col items-center text-center hover:shadow-2xl transition-all group">
                     <div className="relative mb-6">
                        <img src={item.image} className="w-24 h-24 sm:w-28 sm:h-28 rounded-[35px] object-cover shadow-2xl group-hover:rotate-6 transition-transform" alt={item.name} />
                        {item.stock < 10 && (
                          <div className="absolute -top-2 -right-2 w-7 h-7 bg-red-600 text-white rounded-full flex items-center justify-center text-[10px] animate-bounce shadow-xl ring-4 ring-white dark:ring-gray-900">
                            <i className="fas fa-triangle-exclamation"></i>
                          </div>
                        )}
                     </div>
                     <h4 className="font-black text-[11px] text-gray-950 dark:text-white mb-6 uppercase tracking-tighter truncate w-full px-2 leading-tight">{item.name}</h4>
                     <div className="flex flex-col mb-8">
                        <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Stock Level</p>
                        <p className={`text-5xl font-black italic ${item.stock < 10 ? 'text-red-600' : 'dark:text-white'}`}>{item.stock}</p>
                     </div>
                     <div className="flex gap-2 w-full mt-auto">
                        <button onClick={() => handleUpdateStock(item.id, false)} className="flex-1 bg-gray-50 dark:bg-gray-800 py-4 rounded-2xl font-black text-xl hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors shadow-sm">-</button>
                        <button onClick={() => handleUpdateStock(item.id, true)} className="flex-1 bg-gray-950 dark:bg-white dark:text-gray-950 text-white py-4 rounded-2xl font-black text-xl hover:scale-110 active:scale-90 transition-transform shadow-xl">+</button>
                     </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'reports' && (
            <div className="animate-slide-up space-y-10">
              <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-8">
                <div>
                  <h3 className="text-4xl font-black uppercase italic tracking-tighter leading-none">Data Analytics Hub</h3>
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-[4px] mt-2 italic">Export performance and behavior telemetry</p>
                </div>

                <div className="flex flex-wrap gap-4 w-full xl:w-auto">
                   <div className="flex bg-white dark:bg-gray-900 p-2 rounded-2xl border dark:border-gray-800 shadow-sm w-full sm:w-auto">
                      {(['sales', 'inventory', 'customers'] as const).map(type => (
                        <button 
                          key={type}
                          onClick={() => setReportType(type)}
                          className={`flex-1 sm:flex-none px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${
                            reportType === type ? 'bg-red-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-900 dark:hover:text-white'
                          }`}
                        >
                          {type}
                        </button>
                      ))}
                   </div>

                   <div className="flex gap-3 w-full sm:w-auto">
                      <button 
                        onClick={handleExportExcel}
                        className="flex-1 sm:flex-none px-8 py-4 bg-emerald-600 text-white rounded-2xl text-[9px] font-black uppercase tracking-widest hover:scale-105 transition-all flex items-center justify-center gap-3 shadow-xl shadow-emerald-600/20"
                      >
                        <i className="fas fa-file-excel"></i> Excel
                      </button>
                      <button 
                        onClick={handleExportPDF}
                        className="flex-1 sm:flex-none px-8 py-4 bg-gray-950 text-white rounded-2xl text-[9px] font-black uppercase tracking-widest hover:scale-105 transition-all flex items-center justify-center gap-3 shadow-xl"
                      >
                        <i className="fas fa-file-pdf text-red-500"></i> PDF
                      </button>
                   </div>
                </div>
              </div>

              <div className="bg-white dark:bg-gray-900 rounded-[55px] border dark:border-gray-800 overflow-hidden shadow-sm">
                 <div className="overflow-x-auto w-full scrollbar-hide">
                    { (reportType === 'sales' && orders.length === 0) || (reportType === 'inventory' && menuItems.length === 0) ? (
                      <div className="p-20 text-center font-black uppercase text-gray-400 tracking-[5px] italic opacity-50">
                        No report data available for the current selection.
                      </div>
                    ) : (
                      <table className="w-full text-left min-w-[1000px]">
                        <thead>
                            <tr className="bg-gray-50/50 dark:bg-gray-800/30 text-[10px] font-black uppercase tracking-widest text-gray-400 border-b dark:border-gray-800">
                              {reportType === 'sales' && (
                                <>
                                  <th className="p-10">Order Reference</th>
                                  <th className="p-10">Subject Node</th>
                                  <th className="p-10">Metric Value</th>
                                  <th className="p-10">Status Label</th>
                                  <th className="p-10 text-right">Time Signature</th>
                                </>
                              )}
                              {reportType === 'inventory' && (
                                <>
                                  <th className="p-10">Item ID</th>
                                  <th className="p-10">Product Name</th>
                                  <th className="p-10">Node Category</th>
                                  <th className="p-10">Unit Price</th>
                                  <th className="p-10 text-right">Stock Level</th>
                                </>
                              )}
                              {reportType === 'customers' && (
                                <>
                                  <th className="p-10">Customer Profile</th>
                                  <th className="p-10">Total Missions</th>
                                  <th className="p-10">Lifetime Value</th>
                                  <th className="p-10">Avg Engagement</th>
                                  <th className="p-10 text-right">Last Sync</th>
                                </>
                              )}
                            </tr>
                        </thead>
                        <tbody className="text-[12px] font-bold text-gray-700 dark:text-gray-300 divide-y divide-gray-50 dark:divide-gray-800">
                            {reportType === 'sales' && orders.map((o) => (
                              <tr key={o.id} className="hover:bg-gray-50/50 dark:hover:bg-gray-800/50 transition-colors">
                                  <td className="p-10 font-black uppercase tracking-tighter">#{o.id}</td>
                                  <td className="p-10 truncate max-w-[200px] italic">{o.customerName}</td>
                                  <td className="p-10 font-black text-gray-950 dark:text-white">৳{o.total.toLocaleString()}</td>
                                  <td className="p-10">
                                    <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                                      o.status === OrderStatus.DELIVERED ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-red-50 text-red-600 border-red-100'
                                    }`}>{o.status}</span>
                                  </td>
                                  <td className="p-10 text-right font-mono text-gray-400">{new Date(o.createdAt).toLocaleDateString()}</td>
                              </tr>
                            ))}
                            {reportType === 'inventory' && menuItems.map((m) => (
                              <tr key={m.id} className="hover:bg-gray-50/50 dark:hover:bg-gray-800/50 transition-colors">
                                  <td className="p-10 font-black uppercase tracking-tighter">NODE-{m.id}</td>
                                  <td className="p-10 font-black text-gray-950 dark:text-white truncate max-w-[200px]">{m.name}</td>
                                  <td className="p-10 italic uppercase tracking-widest text-[10px] text-gray-400">{m.category}</td>
                                  <td className="p-10 font-black">৳{m.price}</td>
                                  <td className="p-10 text-right">
                                    <span className={`font-black text-lg ${m.stock < 10 ? 'text-red-600' : 'text-emerald-500'}`}>{m.stock}</span>
                                    <p className="text-[8px] font-black uppercase tracking-widest text-gray-400">Units</p>
                                  </td>
                              </tr>
                            ))}
                            {reportType === 'customers' && customerBehaviorData.map((c, i) => (
                              <tr key={i} className="hover:bg-gray-50/50 dark:hover:bg-gray-800/50 transition-colors">
                                  <td className="p-10 flex items-center gap-4">
                                    <div className="w-10 h-10 bg-gray-100 dark:bg-gray-800 rounded-xl flex items-center justify-center font-black text-xs uppercase">{c.name.charAt(0)}</div>
                                    <span className="font-black text-gray-950 dark:text-white italic truncate max-w-[150px]">{c.name}</span>
                                  </td>
                                  <td className="p-10 font-black">{c.totalOrders}</td>
                                  <td className="p-10 font-black text-gray-950 dark:text-white">৳{c.totalSpend.toLocaleString()}</td>
                                  <td className="p-10 italic text-gray-400">৳{(c.totalSpend/c.totalOrders).toFixed(0)} / order</td>
                                  <td className="p-10 text-right text-gray-400 font-mono text-[10px]">{new Date(c.lastOrder).toLocaleDateString()}</td>
                              </tr>
                            ))}
                        </tbody>
                      </table>
                    )}
                 </div>
              </div>
            </div>
          )}
        </div>

        <div className="h-24 lg:hidden shrink-0" />
      </main>

      <ChatBot isOnline={true} />
    </div>
  );
};

