  <div className="bg-white dark:bg-gray-900 p-10 rounded-[45px] border dark:border-gray-800 flex items-center gap-8 hover:shadow-2xl transition-all group overflow-hidden h-full">
    <div className={`w-16 h-16 bg-gray-50 dark:bg-gray-800 rounded-[28px] flex items-center justify-center text-2xl ${color} shrink-0 group-hover:scale-110 transition-transform shadow-sm`}>
      <i className={`fas ${icon}`}></i>
