      <p className="text-[10px] font-black text-gray-400 uppercase tracking-[4px] mb-2 truncate leading-none">{title}</p>
      <h4 className="text-3xl font-black text-gray-950 dark:text-white tracking-tighter truncate leading-tight italic">{value}</h4>
