  qty: number;
  isSubscription?: boolean;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone?: string;
  items: Array<{
    menuId: string;
    quantity: number;
    price: number;
    name: string;
  }>;
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentStatus: 'PAID' | 'UNPAID';
  paymentMethod: 'BKASH' | 'NAGAD' | 'ROCKET' | 'UPAY' | 'CARD' | 'COD';
  address: string;
  deliveryZone: string;
  deliverySlot: string;
  deliveryInstructions?: string;
  pointsEarned: number;
  trackingUpdates: Array<{ status: OrderStatus; time: string }>;
