                                   <span className={`px-4 py-1.5 rounded-xl text-[8px] font-black uppercase tracking-widest border ${
                                     log.level === 'CRITICAL' ? 'bg-red-600 text-white border-red-700 shadow-lg shadow-red-600/20' :
                                     log.level === 'WARNING' ? 'bg-amber-100 text-amber-700 border-amber-200' :
                                     'bg-gray-100 text-gray-500 border-gray-200'
                                   }`}>
                                     {log.level}
                                   </span>
                                </td>
                                <td className="p-10 text-right font-mono text-[9px] text-gray-400">
                                  {new Date(log.timestamp).toLocaleString([], { hour:'2-digit', minute:'2-digit', second:'2-digit' })}
