      <i className={`fas ${icon}`}></i>
    </div>
    <div className="min-w-0">
      <p className="text-[10px] font-black text-gray-400 uppercase tracking-[4px] mb-2 truncate leading-none">{title}</p>
      <h4 className="text-3xl font-black text-gray-950 dark:text-white tracking-tighter truncate leading-tight italic">{value}</h4>
    </div>
  </div>
);

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User, AuditLog } from './types';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 }, { name: 'Sun', sales: 3800 }, { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 }, { name: 'Wed', sales: 6200 }, { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, onLogout, menuItems, setMenuItems, orders, setOrders 
}) => {
  const allowedTabs = useMemo(() => {
    if (userRole === UserRole.ADMIN) return ['dashboard', 'orders', 'menu-stock', 'reports', 'audit'];
    if (userRole === UserRole.MANAGER) return ['dashboard', 'orders', 'menu-stock'];
    return ['orders'];
  }, [userRole]);

  const [activeTab, setActiveTab] = useState(allowedTabs[0]);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [adminToast, setAdminToast] = useState<{msg: string, type: string} | null>(null);

  // Reports sub-tab state
  const [reportType, setReportType] = useState<'sales' | 'inventory' | 'customers'>('sales');

  // Audit Log state
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([
    { id: 'LOG-001', userId: 'A-001', userName: 'Super Admin', action: 'SYSTEM_START', details: 'BFC Mainframe initialized in Gulshan Sector.', timestamp: new Date(Date.now() - 86400000).toISOString(), level: 'INFO' },
    { id: 'LOG-002', userId: 'A-001', userName: 'Super Admin', action: 'SECURITY_PATCH', details: 'Firewall protocols updated to v5.2.', timestamp: new Date(Date.now() - 43200000).toISOString(), level: 'WARNING' },
  ]);
  const [auditSearch, setAuditSearch] = useState('');
  const [auditLevelFilter, setAuditLevelFilter] = useState<'ALL' | 'INFO' | 'WARNING' | 'CRITICAL'>('ALL');

  const showToast = useCallback((msg: string, type: string) => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const addAuditLog = useCallback((action: string, details: string, level: AuditLog['level'] = 'INFO') => {
    const newLog: AuditLog = {
      id: `LOG-${Math.random().toString(36).slice(2, 7).toUpperCase()}`,
      userId: 'ADMIN-01',
      userName: userRole === UserRole.ADMIN ? 'Head Admin' : 'Node Manager',
      action,
      details,
      timestamp: new Date().toISOString(),
      level
    };
    setAuditLogs(prev => [newLog, ...prev]);
  }, [userRole]);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    try {
      const oldStatus = orders.find(o => o.id === orderId)?.status;
      setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
      showToast(`Order #${orderId.slice(-4)} updated to ${newStatus}.`, "success");
      addAuditLog('ORDER_STATUS_UPDATE', `Order #${orderId} changed from ${oldStatus} to ${newStatus}.`, 'INFO');
    } catch (e) {
      showToast("Could not update order status.", "error");
    }
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) {
          showToast(`Invalid action: Stock for ${item.name} cannot be less than zero.`, "error");
          addAuditLog('INVALID_STOCK_ADJUSTMENT', `Attempted to set stock for ${item.name} below zero.`, 'WARNING');
          return item;
        }
        showToast(`Stock for ${item.name} updated to ${newStock}.`, "success");
        addAuditLog('STOCK_UPDATE', `Stock for ${item.name} adjusted to ${newStock}.`, newStock < 5 ? 'WARNING' : 'INFO');
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  const customerBehaviorData = useMemo(() => {
    const customerMap: Record<string, { name: string, totalOrders: number, totalSpend: number, lastOrder: string }> = {};
    orders.forEach(o => {
      if (!customerMap[o.customerId]) {
        customerMap[o.customerId] = { name: o.customerName, totalOrders: 0, totalSpend: 0, lastOrder: o.createdAt };
      }
      customerMap[o.customerId].totalOrders += 1;
      customerMap[o.customerId].totalSpend += o.total;
      if (new Date(o.createdAt) > new Date(customerMap[o.customerId].lastOrder)) {
        customerMap[o.customerId].lastOrder = o.createdAt;
      }
    });
    return Object.values(customerMap).sort((a, b) => b.totalSpend - a.totalSpend);
  }, [orders]);

  const filteredAuditLogs = useMemo(() => {
    return auditLogs.filter(log => {
      const matchesSearch = log.action.toLowerCase().includes(auditSearch.toLowerCase()) || 
                            log.userName.toLowerCase().includes(auditSearch.toLowerCase()) ||
                            log.details.toLowerCase().includes(auditSearch.toLowerCase());
      const matchesLevel = auditLevelFilter === 'ALL' || log.level === auditLevelFilter;
      return matchesSearch && matchesLevel;
    });
  }, [auditLogs, auditSearch, auditLevelFilter]);

  // Metric Computations for Reports
  const reportMetrics = useMemo(() => {
    if (reportType === 'sales') {
      const totalRevenue = orders.reduce((a, b) => a + b.total, 0);
      const avgOrder = orders.length ? (totalRevenue / orders.length).toFixed(0) : 0;
      return [
        { label: 'Total Node Revenue', value: `৳${totalRevenue.toLocaleString()}`, icon: 'fa-vault' },
        { label: 'Avg Mission Value', value: `৳${avgOrder}`, icon: 'fa-scale-balanced' },
        { label: 'Conversion Rate', value: '12.4%', icon: 'fa-arrow-trend-up' }
      ];
    } else if (reportType === 'inventory') {
      const totalValuation = menuItems.reduce((a, b) => a + (b.price * b.stock), 0);
      const lowStockCount = menuItems.filter(m => m.stock < 10).length;
      return [
        { label: 'Stock Valuation', value: `৳${totalValuation.toLocaleString()}`, icon: 'fa-sack-dollar' },
        { label: 'Critical Nodes', value: lowStockCount, icon: 'fa-triangle-exclamation' },
        { label: 'Storage Capacity', value: '85%', icon: 'fa-warehouse' }
      ];
    } else { // customers
      const totalSpenders = customerBehaviorData.length;
      const avgLTV = totalSpenders ? (orders.reduce((a, b) => a + b.total, 0) / totalSpenders).toFixed(0) : 0;
      return [
        { label: 'Registered Spenders', value: totalSpenders, icon: 'fa-users-gear' },
        { label: 'Lifetime Value (Avg)', value: `৳${avgLTV}`, icon: 'fa-gem' },
        { label: 'Retention Logic', value: 'High', icon: 'fa-link' }
      ];
    }
  }, [reportType, orders, menuItems, customerBehaviorData]);

  const handleExportExcel = () => {
    try {
      let data: any[] = [];
      let filename = `BFC_Report_${reportType}_${new Date().toISOString().split('T')[0]}.xlsx`;

      if (reportType === 'sales') {
        data = orders.map(o => ({ 
          'Order ID': o.id, 'Customer': o.customerName, 'Total (৳)': o.total, 'Status': o.status, 'Payment': o.paymentMethod, 'Date': new Date(o.createdAt).toLocaleDateString() 
        }));
      } else if (reportType === 'inventory') {
        data = menuItems.map(m => ({ 
          'Item ID': m.id, 'Name': m.name, 'Category': m.category, 'Price (৳)': m.price, 'Stock': m.stock, 'Status': m.stock < 10 ? 'LOW' : 'STABLE' 
        }));
      } else if (reportType === 'customers') {
        data = customerBehaviorData.map(c => ({ 
          'Customer Name': c.name, 'Total Orders': c.totalOrders, 'Total Spend (৳)': c.totalSpend, 'Avg Order Value (৳)': (c.totalSpend / c.totalOrders).toFixed(2), 'Last Active': new Date(c.lastOrder).toLocaleDateString()
        }));
      }

      if (data.length === 0) {
        showToast(`Export failed: No data available.`, "warning");
        return;
      }

      const worksheet = XLSX.utils.json_to_sheet(data);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Report");
      XLSX.writeFile(workbook, filename);
      showToast(`Excel generated.`, 'success');
      addAuditLog('REPORT_EXPORT_EXCEL', `Generated Excel report for ${reportType}.`, 'INFO');
    } catch (err) {
      showToast("Unable to generate Excel file.", "error");
    }
  };

  const handleExportPDF = () => {
    try {
      const doc = new jsPDF();
      doc.setFontSize(18);
      doc.text(`BFC Hub: ${reportType.toUpperCase()} Report`, 14, 20);
      doc.setFontSize(10);
      doc.text(`Generated on: ${new Date().toLocaleString()}`, 14, 28);

      let head: any[][] = [];
      let body: any[][] = [];

      if (reportType === 'sales') {
        head = [['Order ID', 'Customer', 'Total', 'Status', 'Date']];
        body = orders.map(o => [o.id, o.customerName, `৳${o.total}`, o.status, new Date(o.createdAt).toLocaleDateString()]);
      } else if (reportType === 'inventory') {
        head = [['ID', 'Name', 'Category', 'Price', 'Stock']];
        body = menuItems.map(m => [m.id, m.name, m.category, `৳${m.price}`, m.stock]);
      } else if (reportType === 'customers') {
        head = [['Customer', 'Orders', 'Total Spend', 'Avg Order', 'Last Active']];
        body = customerBehaviorData.map(c => [
          c.name, c.totalOrders, `৳${c.totalSpend}`, `৳${(c.totalSpend/c.totalOrders).toFixed(0)}`, new Date(c.lastOrder).toLocaleDateString()
        ]);
      }

      if (body.length === 0) {
        showToast(`Nothing to export.`, "warning");
        return;
      }

      autoTable(doc, {
        head,
        body,
        startY: 35,
        theme: 'striped',
        headStyles: { fillColor: [220, 38, 38], textColor: [255, 255, 255], fontStyle: 'bold' }
      });

      doc.save(`BFC_Report_${reportType}.pdf`);
      showToast(`PDF successfully exported.`, 'success');
