                    <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mb-12">
                      {[OrderStatus.PENDING, OrderStatus.PREPARING, OrderStatus.READY, OrderStatus.DELIVERED].map((s, idx) => {
                        const isCompleted = order.trackingUpdates.some(u => u.status === s);
                        const isCurrent = order.status === s;
                        return (
                          <div key={s} className="flex flex-col items-center">
                            <div className={`w-14 h-14 rounded-3xl flex items-center justify-center shadow-lg transition-all ${
