                        ))}
                        <div className="h-px bg-gray-200 my-4"></div>
                        <div className="flex justify-between items-center text-lg font-black italic">
                          <span>Final Payload Value</span>
                          <span className="text-red-600">৳{order.total}</span>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {view === 'PROFILE' && currentUser && (
          <div className="max-w-4xl mx-auto py-10 animate-slide-up space-y-12">
             <div className="flex flex-col md:flex-row items-center gap-12 bg-white p-12 rounded-[60px] border border-gray-100 shadow-sm">
                <div className="relative group">
                  <div className="w-48 h-48 rounded-[50px] bg-gray-100 border-4 border-white shadow-2xl overflow-hidden flex items-center justify-center text-5xl font-black text-gray-300 uppercase">
                    {editImage ? (
                      <img src={editImage} className="w-full h-full object-cover" alt="Profile" />
                    ) : (
                      currentUser.name.charAt(0)
                    )}
                  </div>
                  <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="absolute -bottom-4 -right-4 w-14 h-14 bg-red-600 text-white rounded-2xl flex items-center justify-center shadow-2xl hover:scale-110 transition-transform border-4 border-white"
                  >
                    <i className="fas fa-camera"></i>
                  </button>
                  <input type="file" ref={fileInputRef} onChange={handleImageUpload} accept="image/*" className="hidden" />
                </div>

                <div className="flex-1 text-center md:text-left space-y-4">
                   <div className="flex flex-wrap items-center justify-center md:justify-start gap-4">
                      <h3 className="text-4xl font-black tracking-tighter italic uppercase">{currentUser.name}</h3>
                      <span className="px-6 py-2 bg-amber-50 text-amber-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-amber-100 shadow-sm shadow-amber-500/10">
                        {currentUser.tier} MEMBER
                      </span>
                   </div>
                   <p className="text-gray-400 font-bold uppercase text-[10px] tracking-widest">LOYALTY CREDIT: <span className="text-red-600">{currentUser.loyaltyPoints} POINTS</span></p>
                   <p className="text-gray-400 font-bold uppercase text-[10px] tracking-widest">REFERRAL: <span className="text-gray-950">{currentUser.referralCode}</span></p>
                   <div className="pt-4 flex justify-center md:justify-start">
                     <button onClick={() => { localStorage.removeItem('bfc_user_session'); setCurrentUser(null); setView('HOME'); }} className="text-[10px] font-black uppercase tracking-widest text-red-600 border-b-2 border-red-600 pb-1">Terminate Session</button>
                   </div>
                </div>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="bg-white p-12 rounded-[60px] border border-gray-100 shadow-sm space-y-8">
                   <h4 className="text-xl font-black uppercase italic tracking-tighter">Secure Parameters</h4>
                   <div className="space-y-6">
                      <div>
                        <label className="text-[10px] font-black uppercase tracking-widest text-gray-400 ml-4 block mb-2">Display Identity</label>
                        <input type="text" value={editName} onChange={e => setEditName(e.target.value)} className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none border-2 border-transparent focus:border-red-600 transition-colors shadow-inner" />
