                <div className="bg-gray-950 p-12 rounded-[60px] text-white space-y-8 relative overflow-hidden">
                   <div className="absolute top-0 right-0 w-32 h-32 bg-red-600/20 rounded-full blur-3xl"></div>
                   <h4 className="text-xl font-black uppercase italic tracking-tighter">Elite Privileges</h4>
                   <div className="space-y-6">
                      <div className="flex items-center gap-6 p-6 bg-white/5 rounded-[30px] border border-white/10">
