                            <p className="font-black text-[10px] uppercase tracking-widest">Free Deployment</p>
                            <p className="text-[10px] text-gray-400 font-bold mt-1">Active for next 3 missions.</p>
                         </div>
                      </div>
                      <div className="flex items-center gap-6 p-6 bg-white/5 rounded-[30px] border border-white/10">
                         <div className="w-12 h-12 bg-amber-500 rounded-2xl flex items-center justify-center text-xl shadow-xl">
                            <i className="fas fa-percent"></i>
                         </div>
                         <div>
                            <p className="font-black text-[10px] uppercase tracking-widest">10% Node Discount</p>
                            <p className="text-[10px] text-gray-400 font-bold mt-1">Permanent Gold Tier Perk.</p>
                         </div>
                      </div>
                      <div className="flex items-center gap-6 p-6 bg-white/5 rounded-[30px] border border-white/10 opacity-40">
                         <div className="w-12 h-12 bg-purple-600 rounded-2xl flex items-center justify-center text-xl">
                            <i className="fas fa-crown"></i>
                         </div>
                         <div>
                            <p className="font-black text-[10px] uppercase tracking-widest text-gray-300">Platinum Vault</p>
                            <p className="text-[10px] text-gray-500 font-bold mt-1">Unlock at 500 points.</p>
                         </div>
                      </div>
                   </div>
                </div>
             </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-5xl mx-auto space-y-12 animate-slide-up">
            <h3 className="text-4xl font-black uppercase italic tracking-tighter">Current Selection</h3>
            {cart.length === 0 ? (
              <div className="bg-white p-24 rounded-[60px] text-center border-2 border-dashed border-gray-100">
                <i className="fas fa-cart-arrow-down text-5xl text-gray-100 mb-8"></i>
                <p className="font-black text-gray-400 uppercase tracking-[6px]">Your payload is empty</p>
                <p className="text-xs text-gray-400 mt-2">Browse the menu to add legendary flavors to your cart.</p>
                <Button variant="outline" className="mt-10 rounded-2xl px-12" onClick={() => setView('MENU')}>View Menu</Button>
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
                <div className="lg:col-span-2 space-y-6">
                  {cart.map((c, i) => (
                    <div key={i} className="bg-white p-8 rounded-[40px] border border-gray-50 flex flex-col sm:flex-row items-center gap-8 shadow-sm hover:shadow-xl transition-all">
                      <img src={c.item.image} className="w-32 h-32 rounded-[30px] object-cover shadow-lg shrink-0" alt={c.item.name} />
                      <div className="flex-1 text-center sm:text-left">
                        <h4 className="font-black text-gray-900 text-2xl leading-tight mb-2">{c.item.name}</h4>
                        <p className="text-[11px] font-black text-red-600 uppercase tracking-widest mb-4">৳{c.item.price} per Unit</p>
                        <div className="flex items-center justify-center sm:justify-start gap-6">
                          <div className="flex items-center gap-4 bg-gray-50 p-2 rounded-2xl border">
                            <button onClick={() => setCart(prev => prev.map((it, idx) => idx === i ? {...it, qty: Math.max(1, it.qty-1)} : it))} className="w-10 h-10 rounded-xl bg-white flex items-center justify-center font-black hover:bg-red-50 transition-colors shadow-sm">-</button>
                            <span className="font-black w-8 text-center text-lg">{c.qty}</span>
                            <button onClick={() => setCart(prev => prev.map((it, idx) => idx === i ? {...it, qty: it.qty+1} : it))} className="w-10 h-10 rounded-xl bg-gray-950 text-white flex items-center justify-center font-black hover:scale-105 transition-transform shadow-lg">+</button>
                          </div>
                          <button onClick={() => { setCart(prev => prev.filter((_, idx) => idx !== i)); showToast(`Removed ${c.item.name} from selection.`, 'warning'); }} className="text-gray-300 hover:text-red-600 transition-colors">
                            <i className="fas fa-trash-alt text-lg"></i>
                          </button>
                        </div>
                      </div>
                      <div className="text-right shrink-0">
                         <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Item Total</p>
                         <p className="text-2xl font-black italic text-gray-950">৳{c.item.price * c.qty}</p>
                      </div>
                    </div>
                  ))}
                </div>

                <div className="bg-white p-10 rounded-[55px] border border-gray-100 h-fit space-y-10 sticky top-32 shadow-2xl">
                  <h4 className="font-black text-[11px] uppercase tracking-[4px] text-gray-400 italic">Bill Summary</h4>
                  <div className="space-y-4">
                     <div className="flex justify-between text-sm font-bold text-gray-600 uppercase tracking-tight">
                        <span>Subtotal</span>
                        <span>৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0)}</span>
                     </div>
                     <div className="flex justify-between text-sm font-bold text-gray-600 uppercase tracking-tight">
                        <span>Delivery</span>
                        <span>৳50</span>
                     </div>
                     <div className="h-px bg-gray-100 my-6"></div>
                     <div className="flex justify-between text-3xl font-black text-gray-950 italic tracking-tighter">
                        <span>Total Due</span>
                        <span className="text-red-600">৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50}</span>
                     </div>
                  </div>

                  <div className="space-y-4">
                    <p className="text-[10px] font-black uppercase tracking-[4px] text-gray-400 mb-4 italic">Select Payment</p>
                    <div className="grid grid-cols-1 gap-3">
                       <button className="flex items-center justify-between p-5 rounded-3xl border-2 border-red-600 bg-red-50 text-red-600 font-black text-[11px] uppercase tracking-widest transition-all">
                         <span>bKash (Verified)</span>
                         <i className="fas fa-check-circle"></i>
                       </button>
                       <button className="flex items-center justify-between p-5 rounded-3xl border-2 border-gray-50 bg-gray-50 text-gray-400 font-black text-[11px] uppercase tracking-widest opacity-50 cursor-not-allowed">
                         <span>Nagad / Rocket</span>
                         <i className="fas fa-lock text-[8px]"></i>
                       </button>
                    </div>
                  </div>

                  <Button fullWidth size="lg" className="rounded-3xl shadow-2xl shadow-red-600/30 py-5" onClick={handleCheckout} disabled={isCheckingOut}>
                    {isCheckingOut ? (
                      <span className="flex items-center gap-3">
                        <i className="fas fa-circle-notch animate-spin text-[10px]"></i> Processing...
                      </span>
                    ) : (
                      <span className="flex items-center gap-3">
                        <i className="fas fa-bolt text-[10px]"></i> Secure Checkout
                      </span>
                    )}
                  </Button>
                </div>
              </div>
            )}
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto py-16 animate-slide-up">
             <div className="bg-white p-14 rounded-[60px] shadow-3xl border border-gray-100 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-red-600 to-orange-500"></div>
                <div className="flex justify-center mb-10">
                   <div className="w-20 h-20 bg-gray-950 rounded-3xl flex items-center justify-center text-white text-3xl shadow-2xl">
                      <i className="fas fa-key"></i>
                   </div>
                </div>
                <h3 className="text-4xl font-black text-center mb-12 uppercase italic tracking-tighter">Login Access</h3>
                <div className="space-y-6">
                  <div>
                    <label className="text-[10px] font-black uppercase tracking-[3px] text-gray-400 ml-4 block mb-2">Registered Email</label>
                    <input 
                      type="email" 
                      value={formEmail} 
                      onChange={e => setFormEmail(e.target.value)} 
                      placeholder="boss@bfc.com" 
                      className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none border-2 border-transparent focus:border-red-600 transition-colors shadow-inner" 
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase tracking-[3px] text-gray-400 ml-4 block mb-2">Secret Password</label>
                    <input 
                      type="password" 
                      value={formPass} 
                      onChange={e => setFormPass(e.target.value)} 
                      placeholder="••••••••" 
                      className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none border-2 border-transparent focus:border-red-600 transition-colors shadow-inner" 
                    />
                  </div>
                  <Button fullWidth size="lg" className="rounded-3xl mt-12 py-5 shadow-2xl shadow-red-600/20" onClick={handleAuth} disabled={isAuthenticating}>
                    {isAuthenticating ? 'Authenticating...' : 'Sign In Now'}
                  </Button>
                  <p className="text-center text-[8px] font-black text-gray-400 uppercase tracking-widest mt-6 px-4">
                    By signing in, you agree to our terms. Use 'admin@bfc.com' to test admin features.
                  </p>
                </div>
             </div>
          </div>
        )}
      </main>

      {/* Mobile Sticky Footer */}
      <nav className="lg:hidden fixed bottom-0 left-0 w-full bg-white/90 backdrop-blur-xl border-t border-gray-100 flex justify-around p-5 z-[5000] shadow-[0_-20px_40px_-20px_rgba(0,0,0,0.1)]">
        {[
          { icon: 'fa-home', label: 'Home', view: 'HOME' },
          { icon: 'fa-utensils', label: 'Menu', view: 'MENU' },
          { icon: 'fa-rocket', label: 'Track', view: 'TRACKING' },
          { icon: 'fa-user', label: 'Profile', view: 'PROFILE' }
        ].map(nav => (
          <button 
            key={nav.view}
            onClick={() => setView(nav.view as any)} 
            className={`flex flex-col items-center gap-1.5 transition-all ${view === nav.view ? 'text-red-600' : 'text-gray-400'}`}
          >
            {nav.view === 'PROFILE' && currentUser?.profileImage ? (
              <div className="w-6 h-6 rounded-full overflow-hidden border border-gray-200">
                <img src={currentUser.profileImage} className="w-full h-full object-cover" alt="Me" />
              </div>
            ) : (
              <i className={`fas ${nav.icon} text-xl`}></i>
            )}
            <span className="text-[8px] font-black uppercase tracking-widest">{nav.label}</span>
          </button>
        ))}
      </nav>

      <ChatBot isOnline={isOnline} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
}

const App: React.FC = () => {
  // Core State
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE'>('HOME');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Auth States
  const [isSignup, setIsSignup] = useState(false);
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [formName, setFormName] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  // Profile Edit States
  const [editName, setEditName] = useState('');
  const [editPhone, setEditPhone] = useState('');
  const [editImage, setEditImage] = useState<string | undefined>(undefined);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Menu Filter States
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  // Checkout States
  const [isCheckingOut, setIsCheckingOut] = useState(false);

  // Computed Values
  const categories = useMemo(() => ['All', ...new Set(menuItems.map(item => item.category))], [menuItems]);

  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [menuItems, searchQuery, activeCategory]);

  const showToast = useCallback((message: string, type: Toast['type'] = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  // Sync Persistence
  useEffect(() => {
    const savedSession = localStorage.getItem('bfc_user_session');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setEditName(user.name);
        setEditPhone(user.phone);
        setEditImage(user.profileImage);
        if (user.role !== UserRole.CUSTOMER) setView('ADMIN');
      } catch (e) { localStorage.removeItem('bfc_user_session'); }
    }
  }, []);

  useEffect(() => {
    const handleOnline = () => { 
      setIsOnline(true); 
      showToast('Node Link Established. Systems Online.', 'success'); 
    };
    const handleOffline = () => { 
      setIsOnline(false); 
      showToast('Node Link Severed. Offline Mode Active.', 'error'); 
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => { 
      window.removeEventListener('online', handleOnline); 
      window.removeEventListener('offline', handleOffline); 
    };
  }, [showToast]);

  const handleAuth = async () => {
    if (!formEmail.trim() || !formPass.trim()) {
      showToast('Credentials required for mainframe access.', 'warning');
      return;
    }

    if (isSignup && (!formName.trim() || !formPhone.trim())) {
      showToast('Full profile parameters required for registration.', 'warning');
      return;
    }

    setIsAuthenticating(true);
    try {
      if (!isOnline) throw new Error('OFFLINE');
      await new Promise(resolve => setTimeout(resolve, 1500));

      let user: User;

      if (isSignup) {
        // Handle Signup
        user = {
          id: 'U-' + Math.random().toString(36).slice(2, 7),
          name: formName,
          email: formEmail,
          phone: formPhone,
          role: UserRole.CUSTOMER,
          loyaltyPoints: 0,
          tier: 'SILVER',
          wishlist: [],
          referralCode: 'BFC-' + Math.random().toString(36).slice(2, 6).toUpperCase()
        };
        showToast('Account Initialized. Welcome to BFC!', 'success');
      } else {
        // Handle Login (Simulation)
        const role = formEmail.includes('admin') ? UserRole.ADMIN : UserRole.CUSTOMER;
        user = {
          id: 'U-EXISTING',
          name: role === UserRole.ADMIN ? 'Head Admin' : 'Valued Client',
          email: formEmail,
          phone: '01700000000',
          role,
          loyaltyPoints: 150,
          tier: 'GOLD',
          wishlist: [],
          referralCode: 'BFC-BOSS'
        };
        showToast('Mainframe Link Established. Welcome back.', 'success');
      }

      setCurrentUser(user);
      setEditName(user.name);
      setEditPhone(user.phone);
      setEditImage(user.profileImage);
      localStorage.setItem('bfc_user_session', JSON.stringify(user));
      setView(user.role === UserRole.ADMIN ? 'ADMIN' : 'HOME');
    } catch (error: any) {
      showToast('Authentication Interrupted. Check link status.', 'error');
    } finally {
      setIsAuthenticating(false);
    }
  };

  const handleUpdateProfile = () => {
    if (!currentUser) return;
    const updatedUser: User = {
      ...currentUser,
      name: editName,
      phone: editPhone,
      profileImage: editImage
    };
    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    showToast('Profile Parameters Synced.', 'success');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setEditImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleCheckout = async () => {
    if (!currentUser) {
      setView('LOGIN');
      showToast('Authentication required for mission deployment.', 'warning');
      return;
    }
    setIsCheckingOut(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 2000));
      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser.id,
        customerName: currentUser.name,
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total: cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: 'PAID',
        paymentMethod: 'BKASH',
        address: 'Dhaka Sector Node',
        deliveryZone: 'Dhaka',
        deliverySlot: 'Express',
        pointsEarned: 25,
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };
      setAllOrders(prev => [newOrder, ...prev]);
      setCart([]);
      setView('TRACKING');
      showToast('Mission Launched. Kitchen Engaged.', 'success');
    } finally {
      setIsCheckingOut(false);
    }
  };

  const addToCart = (item: MenuItem) => {
    if (item.stock <= 0) {
      showToast(`${item.name} is depleted in local nodes.`, 'warning');
      return;
    }
    setCart(prev => {
      const existing = prev.find(c => c.item.id === item.id);
      if (existing) return prev.map(c => c.item.id === item.id ? { ...c, qty: c.qty + 1 } : c);
      return [...prev, { item, qty: 1 }];
    });
    showToast(`${item.name} added to payload.`, 'success');
  };

  if (view === 'ADMIN' && currentUser?.role !== UserRole.CUSTOMER) {
    return (
      <AdminPanel 
        userRole={currentUser!.role} 
        onLogout={() => { setCurrentUser(null); setView('HOME'); localStorage.removeItem('bfc_user_session'); }}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans">
      {/* Toast Overlay */}
      <div className="fixed top-12 right-6 z-[5500] space-y-3 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto px-6 py-4 rounded-2xl shadow-2xl border bg-white animate-slide-up flex items-start gap-4 border-gray-100">
             <div className={`mt-0.5 w-6 h-6 rounded-lg flex items-center justify-center shrink-0 ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>
                <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark' : 'fa-check-circle'} text-[10px]`}></i>
             </div>
             <p className="font-bold text-[10px] text-gray-800 uppercase tracking-tight leading-tight">{t.message}</p>
          </div>
        ))}
      </div>

      {/* Navigation */}
      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-12 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white text-xl font-black shadow-lg">B</div>
          <h1 className="text-2xl font-black text-red-600 tracking-tighter italic">BFC</h1>
        </div>
        <div className="hidden md:flex gap-10">
          {['HOME', 'MENU', 'TRACKING'].map(v => (
            <button key={v} onClick={() => setView(v as any)} className={`text-[10px] font-black uppercase tracking-[3px] transition-all hover:text-red-600 ${view === v ? 'text-red-600' : 'text-gray-400'}`}>{v}</button>
          ))}
        </div>
        <div className="flex items-center gap-4">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 bg-white rounded-2xl border flex items-center justify-center shadow-sm">
            <i className="fas fa-shopping-basket text-gray-700"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[9px] w-6 h-6 rounded-full flex items-center justify-center font-black animate-bounce">{cart.length}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-12 h-12 rounded-2xl bg-gray-950 text-white font-black flex items-center justify-center overflow-hidden border-2 border-white shadow-xl">
              {currentUser.profileImage ? <img src={currentUser.profileImage} className="w-full h-full object-cover" alt="Me" /> : currentUser.name.charAt(0)}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl px-6" onClick={() => setView('LOGIN')}>Initialize</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-10">
        {view === 'HOME' && (
          <div className="animate-slide-up space-y-16">
            <header className="relative h-[450px] lg:h-[600px] rounded-[50px] overflow-hidden shadow-2xl border-8 border-white group">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-1000" alt="BFC Hero" />
               <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent flex flex-col justify-end p-12 lg:p-20">
                  <h2 className="text-5xl lg:text-8xl font-black text-white leading-[0.85] mb-8 tracking-tighter italic uppercase">DHAKA’S<br/><span className="text-red-600">ELITE FLAVORS</span></h2>
                  <div className="flex gap-4">
                    <Button size="lg" className="rounded-2xl shadow-2xl" onClick={() => setView('MENU')}>Open Vault</Button>
                    <button onClick={() => setView('TRACKING')} className="px-8 py-4 bg-white/10 backdrop-blur-md text-white rounded-2xl font-black text-[10px] uppercase tracking-widest border border-white/20">Track Link</button>
                  </div>
               </div>
            </header>
            <section>
              <h3 className="text-3xl font-black uppercase italic tracking-tighter mb-10">Hot-Link Menu</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                {menuItems.slice(0, 3).map(item => (
                  <div key={item.id} className="bg-white rounded-[45px] p-6 shadow-sm border border-gray-50 hover:shadow-2xl transition-all">
                     <img src={item.image} className="h-64 w-full rounded-[35px] object-cover mb-6" alt={item.name} />
                     <h4 className="text-2xl font-black mb-2">{item.name}</h4>
                     <p className="text-xs text-gray-400 mb-8 line-clamp-2">{item.description}</p>
                     <Button fullWidth variant="outline" className="rounded-2xl" onClick={() => addToCart(item)}>Lock in ৳{item.price}</Button>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto py-16 animate-slide-up">
             <div className="bg-white p-14 rounded-[60px] shadow-3xl border border-gray-50 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-2 bg-red-600"></div>
                <div className="flex flex-col items-center mb-12">
                   <div className="w-20 h-20 bg-gray-950 rounded-3xl flex items-center justify-center text-white text-3xl shadow-2xl mb-6">
                      <i className={`fas ${isSignup ? 'fa-user-plus' : 'fa-shield-halved'}`}></i>
                   </div>
                   <h3 className="text-3xl font-black uppercase italic tracking-tighter">{isSignup ? 'New Node' : 'Mainframe Access'}</h3>
                </div>
                <div className="space-y-5">
                  {isSignup && (
                    <>
                      <input type="text" value={formName} onChange={e => setFormName(e.target.value)} placeholder="Node Name (Name)" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none focus:ring-2 ring-red-600/10" />
                      <input type="tel" value={formPhone} onChange={e => setFormPhone(e.target.value)} placeholder="Comms Link (Phone)" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none focus:ring-2 ring-red-600/10" />
                    </>
                  )}
                  <input type="email" value={formEmail} onChange={e => setFormEmail(e.target.value)} placeholder="Auth ID (Email)" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none focus:ring-2 ring-red-600/10" />
                  <input type="password" value={formPass} onChange={e => setFormPass(e.target.value)} placeholder="Encryption (Password)" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none focus:ring-2 ring-red-600/10" />

                  <Button fullWidth size="lg" className="rounded-3xl mt-6 py-5" onClick={handleAuth} disabled={isAuthenticating}>
                    {isAuthenticating ? 'Authenticating...' : (isSignup ? 'Initialize Account' : 'Connect Node')}
                  </Button>

                  <div className="text-center pt-8">
                    <button onClick={() => setIsSignup(!isSignup)} className="text-[10px] font-black uppercase tracking-widest text-red-600 hover:scale-105 transition-transform">
                      {isSignup ? 'Already a member? Sign in Boss' : 'No account? Create Node Link'}
                    </button>
                  </div>
                </div>
             </div>
          </div>
        )}

        {view === 'PROFILE' && currentUser && (
          <div className="max-w-4xl mx-auto space-y-12 animate-slide-up">
             <div className="bg-white p-12 rounded-[60px] border border-gray-100 flex flex-col md:flex-row items-center gap-10">
                <div className="relative">
                   <div className="w-44 h-44 rounded-[50px] bg-gray-100 border-4 border-white shadow-2xl overflow-hidden flex items-center justify-center text-5xl font-black text-gray-300">
                      {editImage ? <img src={editImage} className="w-full h-full object-cover" alt="Me" /> : currentUser.name.charAt(0)}
                   </div>
                   <button onClick={() => fileInputRef.current?.click()} className="absolute -bottom-4 -right-4 w-12 h-12 bg-red-600 text-white rounded-2xl shadow-xl flex items-center justify-center border-4 border-white hover:scale-110 transition-transform">
                      <i className="fas fa-camera"></i>
                   </button>
                   <input type="file" ref={fileInputRef} onChange={handleImageUpload} accept="image/*" className="hidden" />
                </div>
                <div className="flex-1 text-center md:text-left">
                   <div className="flex items-center justify-center md:justify-start gap-4 mb-2">
                      <h3 className="text-4xl font-black tracking-tighter italic uppercase">{currentUser.name}</h3>
                      <span className="px-5 py-2 bg-red-600 text-white rounded-full text-[9px] font-black tracking-widest">{currentUser.tier} NODE</span>
                   </div>
                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6">Loyalty Credits: <span className="text-red-600">{currentUser.loyaltyPoints} PKT</span></p>
                   <div className="flex flex-wrap justify-center md:justify-start gap-4">
                      <div className="bg-gray-50 px-6 py-4 rounded-3xl border border-gray-100">
                         <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest">Referral Link</p>
                         <p className="text-xs font-black uppercase text-gray-950">{currentUser.referralCode}</p>
                      </div>
                      <button onClick={() => { localStorage.removeItem('bfc_user_session'); setCurrentUser(null); setView('HOME'); }} className="px-6 py-4 bg-red-50 text-red-600 rounded-3xl font-black text-[10px] uppercase tracking-widest border border-red-100">Terminate Session</button>
                   </div>
                </div>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="bg-white p-12 rounded-[60px] border border-gray-100 shadow-sm space-y-8">
                   <h4 className="text-xl font-black uppercase italic tracking-tighter">Node Parameters</h4>
                   <div className="space-y-5">
                      <input type="text" value={editName} onChange={e => setEditName(e.target.value)} placeholder="Node Name" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none border-2 border-transparent focus:border-red-600 transition-colors shadow-inner" />
                      <input type="tel" value={editPhone} onChange={e => setEditPhone(e.target.value)} placeholder="Comms Link" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none border-2 border-transparent focus:border-red-600 transition-colors shadow-inner" />
                      <Button fullWidth onClick={handleUpdateProfile} className="rounded-3xl py-5 mt-6 shadow-xl shadow-red-600/10">Sync Profile</Button>
                   </div>
                </div>
                <div className="bg-gray-950 p-12 rounded-[60px] text-white space-y-8">
                   <h4 className="text-xl font-black uppercase italic tracking-tighter">Mission Log</h4>
                   <div className="space-y-4">
                      {allOrders.filter(o => o.customerId === currentUser.id).length === 0 ? (
                        <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest italic py-10">No missions logged in this node.</p>
                      ) : (
                        allOrders.filter(o => o.customerId === currentUser.id).map(o => (
                          <div key={o.id} className="flex justify-between items-center p-5 bg-white/5 rounded-3xl border border-white/10">
                             <div>
                                <p className="text-[10px] font-black text-red-600">#{o.id.slice(-5)}</p>
                                <p className="text-[9px] font-bold text-gray-400">{new Date(o.createdAt).toLocaleDateString()}</p>
                             </div>
                             <p className="font-black text-sm italic">৳{o.total}</p>
                          </div>
                        ))
                      )}
                      <Button fullWidth variant="outline" className="rounded-3xl border-white/20 text-white hover:bg-white/10" onClick={() => setView('MENU')}>Initiate New Mission</Button>
                   </div>
                </div>
             </div>
          </div>
        )}

        {/* Existing Menu/Cart/Tracking views would continue here... */}
        {view === 'MENU' && <div className="text-center py-20 opacity-40 uppercase font-black italic tracking-[10px]">Vault Modules Loading...</div>}
        {view === 'CART' && (
          <div className="max-w-4xl mx-auto animate-slide-up space-y-12">
            <h3 className="text-4xl font-black uppercase italic tracking-tighter">Payload Summary</h3>
            {cart.length === 0 ? (
              <div className="bg-white p-24 rounded-[60px] text-center border-2 border-dashed border-gray-100">
                <p className="font-black text-gray-400 uppercase tracking-[6px] mb-8">Payload Empty</p>
                <Button variant="outline" className="px-12 rounded-2xl" onClick={() => setView('MENU')}>View Menu</Button>
              </div>
            ) : (
              <div className="bg-white p-12 rounded-[60px] shadow-sm space-y-8">
                {cart.map((c, i) => (
                  <div key={i} className="flex justify-between items-center">
                    <div className="flex gap-6 items-center">
                      <img src={c.item.image} className="w-16 h-16 rounded-2xl object-cover" alt={c.item.name} />
                      <div>
                        <h4 className="font-black text-lg">{c.item.name}</h4>
                        <p className="text-[10px] font-black text-red-600">৳{c.item.price} x {c.qty}</p>
                      </div>
                    </div>
                    <p className="font-black text-xl italic">৳{c.item.price * c.qty}</p>
                  </div>
                ))}
                <div className="h-px bg-gray-100 my-8"></div>
                <div className="flex justify-between text-3xl font-black italic">
                   <span>Final Value</span>
                   <span className="text-red-600">৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50}</span>
                </div>
                <Button fullWidth size="lg" className="rounded-3xl py-6 mt-10" onClick={handleCheckout} disabled={isCheckingOut}>
                  {isCheckingOut ? 'Processing Payload...' : 'Initiate Secure Checkout'}
                </Button>
              </div>
            )}
          </div>
        )}
      </main>

      {/* Mobile Footer */}
      <nav className="lg:hidden fixed bottom-0 left-0 w-full bg-white/95 backdrop-blur-xl border-t border-gray-100 flex justify-around p-6 z-[5000]">
        {[
          { icon: 'fa-home', label: 'Home', view: 'HOME' },
          { icon: 'fa-utensils', label: 'Vault', view: 'MENU' },
          { icon: 'fa-rocket', label: 'Link', view: 'TRACKING' },
          { icon: 'fa-user-astronaut', label: 'Me', view: 'PROFILE' }
        ].map(nav => (
          <button key={nav.view} onClick={() => setView(nav.view as any)} className={`flex flex-col items-center gap-1.5 transition-all ${view === nav.view ? 'text-red-600 scale-110' : 'text-gray-400'}`}>
            <i className={`fas ${nav.icon} text-xl`}></i>
            <span className="text-[8px] font-black uppercase tracking-widest">{nav.label}</span>
          </button>
        ))}
      </nav>

      <ChatBot isOnline={isOnline} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
}

const App: React.FC = () => {
  // Core State
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'TRACKING' | 'PROFILE'>('HOME');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Auth States
  const [isSignup, setIsSignup] = useState(false);
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [formName, setFormName] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  // Profile Edit States
  const [editName, setEditName] = useState('');
  const [editPhone, setEditPhone] = useState('');
  const [editImage, setEditImage] = useState<string | undefined>(undefined);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Menu Filter States
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  // Checkout States
  const [isCheckingOut, setIsCheckingOut] = useState(false);

  // Tracking Simulation
  const [mapMarkerPos, setMapMarkerPos] = useState({ x: 20, y: 80 });

  // Computed Values
  const categories = useMemo(() => ['All', ...new Set(menuItems.map(item => item.category))], [menuItems]);

  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [menuItems, searchQuery, activeCategory]);

  const showToast = useCallback((message: string, type: Toast['type'] = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  // Map Animation Effect for Tracking
  useEffect(() => {
    if (view === 'TRACKING' && allOrders.length > 0) {
      const interval = setInterval(() => {
        setMapMarkerPos(prev => {
          const newX = prev.x + (Math.random() * 2 - 0.5);
          const newY = prev.y - (Math.random() * 2 - 0.5);
          return { 
            x: Math.min(Math.max(newX, 10), 90), 
            y: Math.min(Math.max(newY, 10), 90) 
          };
        });
      }, 3000);
      return () => clearInterval(interval);
    }
  }, [view, allOrders]);

  // Sync Persistence
  useEffect(() => {
    const savedSession = localStorage.getItem('bfc_user_session');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setEditName(user.name);
        setEditPhone(user.phone);
        setEditImage(user.profileImage);
        if (user.role !== UserRole.CUSTOMER) setView('ADMIN');
      } catch (e) { localStorage.removeItem('bfc_user_session'); }
    }
  }, []);

  useEffect(() => {
    const handleOnline = () => { 
      setIsOnline(true); 
      showToast('Node Link Established. Systems Online.', 'success'); 
    };
    const handleOffline = () => { 
      setIsOnline(false); 
      showToast('Node Link Severed. Offline Mode Active.', 'error'); 
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => { 
      window.removeEventListener('online', handleOnline); 
      window.removeEventListener('offline', handleOffline); 
    };
  }, [showToast]);

  const handleAuth = async () => {
    if (!formEmail.trim() || !formPass.trim()) {
      showToast('Credentials required for mainframe access.', 'warning');
      return;
    }

    if (isSignup && (!formName.trim() || !formPhone.trim())) {
      showToast('Full profile parameters required for registration.', 'warning');
      return;
    }

    setIsAuthenticating(true);
    try {
      if (!isOnline) throw new Error('OFFLINE');
      await new Promise(resolve => setTimeout(resolve, 1500));

      let user: User;

      if (isSignup) {
        user = {
          id: 'U-' + Math.random().toString(36).slice(2, 7),
          name: formName,
          email: formEmail,
          phone: formPhone,
          role: UserRole.CUSTOMER,
          loyaltyPoints: 0,
          tier: 'SILVER',
          wishlist: [],
          referralCode: 'BFC-' + Math.random().toString(36).slice(2, 6).toUpperCase()
        };
        showToast('Account Initialized. Welcome to BFC!', 'success');
      } else {
        const role = formEmail.includes('admin') ? UserRole.ADMIN : UserRole.CUSTOMER;
        user = {
          id: 'U-EXISTING',
          name: role === UserRole.ADMIN ? 'Head Admin' : 'Valued Client',
          email: formEmail,
          phone: '01700000000',
          role,
          loyaltyPoints: 150,
          tier: 'GOLD',
          wishlist: [],
          referralCode: 'BFC-BOSS'
        };
        showToast('Mainframe Link Established. Welcome back.', 'success');
      }

      setCurrentUser(user);
      setEditName(user.name);
      setEditPhone(user.phone);
      setEditImage(user.profileImage);
      localStorage.setItem('bfc_user_session', JSON.stringify(user));
      setView(user.role === UserRole.ADMIN ? 'ADMIN' : 'HOME');
    } catch (error: any) {
      showToast('Authentication Interrupted. Check link status.', 'error');
    } finally {
      setIsAuthenticating(false);
    }
  };

  const handleUpdateProfile = () => {
    if (!currentUser) return;
    const updatedUser: User = {
      ...currentUser,
      name: editName,
      phone: editPhone,
      profileImage: editImage
    };
    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    showToast('Profile Parameters Synced.', 'success');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setEditImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleCheckout = async () => {
    if (!currentUser) {
      setView('LOGIN');
      showToast('Authentication required for mission deployment.', 'warning');
      return;
    }
    setIsCheckingOut(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 2000));
      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser.id,
        customerName: currentUser.name,
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total: cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50,
        status: OrderStatus.PREPARING,
        createdAt: new Date().toISOString(),
        paymentStatus: 'PAID',
        paymentMethod: 'BKASH',
        address: 'Dhaka Sector Node',
        deliveryZone: 'Dhaka',
        deliverySlot: 'Express',
