                         <p className="text-xs font-black uppercase text-gray-950">{currentUser.referralCode}</p>
                      </div>
                      <button onClick={() => { localStorage.removeItem('bfc_user_session'); setCurrentUser(null); setView('HOME'); }} className="px-6 py-4 bg-red-50 text-red-600 rounded-3xl font-black text-[10px] uppercase tracking-widest border border-red-100 hover:bg-red-600 hover:text-white transition-all">Terminate Session</button>
                   </div>
                </div>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="bg-white p-12 rounded-[60px] border border-gray-100 shadow-sm space-y-8">
                   <h4 className="text-xl font-black uppercase italic tracking-tighter">Node Parameters</h4>
                   <div className="space-y-5">
                      <input type="text" value={editName} onChange={e => setEditName(e.target.value)} placeholder="Node Name" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none border-2 border-transparent focus:border-red-600 transition-colors shadow-inner" />
                      <input type="tel" value={editPhone} onChange={e => setEditPhone(e.target.value)} placeholder="Comms Link" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none border-2 border-transparent focus:border-red-600 transition-colors shadow-inner" />
                      <Button fullWidth onClick={handleUpdateProfile} className="rounded-3xl py-5 mt-6 shadow-xl shadow-red-600/10">Sync Profile</Button>
                   </div>
                </div>
                <div className="bg-gray-950 p-12 rounded-[60px] text-white space-y-8 relative overflow-hidden">
                   <div className="absolute top-0 right-0 w-40 h-40 bg-red-600/10 rounded-full blur-3xl"></div>
                   <h4 className="text-xl font-black uppercase italic tracking-tighter relative z-10">Mission Log</h4>
                   <div className="space-y-4 relative z-10">
                      {allOrders.filter(o => o.customerId === currentUser.id).length === 0 ? (
                        <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest italic py-10">No missions logged in this node.</p>
                      ) : (
                        allOrders.filter(o => o.customerId === currentUser.id).map(o => (
                          <div key={o.id} className="flex justify-between items-center p-5 bg-white/5 rounded-3xl border border-white/10 hover:bg-white/10 transition-colors group cursor-pointer" onClick={() => setView('TRACKING')}>
                             <div>
                                <p className="text-[10px] font-black text-red-600 group-hover:scale-110 transition-transform origin-left">#{o.id.slice(-5)}</p>
                                <p className="text-[9px] font-bold text-gray-400">{new Date(o.createdAt).toLocaleDateString()}</p>
                             </div>
                             <p className="font-black text-sm italic">৳{o.total}</p>
                          </div>
                        ))
                      )}
                      <Button fullWidth variant="outline" className="rounded-3xl border-white/20 text-white hover:bg-white/10" onClick={() => setView('MENU')}>Initiate New Mission</Button>
                   </div>
                </div>
             </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-4xl mx-auto animate-slide-up space-y-12">
            <h3 className="text-4xl font-black uppercase italic tracking-tighter">Payload Summary</h3>
            {cart.length === 0 ? (
              <div className="bg-white p-24 rounded-[60px] text-center border-2 border-dashed border-gray-100">
                <p className="font-black text-gray-400 uppercase tracking-[6px] mb-8">Payload Empty</p>
                <Button variant="outline" className="px-12 rounded-2xl" onClick={() => setView('MENU')}>View Menu</Button>
              </div>
            ) : (
              <div className="bg-white p-12 rounded-[60px] shadow-sm space-y-8">
                {cart.map((c, i) => (
                  <div key={i} className="flex justify-between items-center hover:bg-gray-50 p-4 rounded-3xl transition-colors">
                    <div className="flex gap-6 items-center">
                      <img src={c.item.image} className="w-16 h-16 rounded-2xl object-cover shadow-md" alt={c.item.name} />
                      <div>
                        <h4 className="font-black text-lg">{c.item.name}</h4>
                        <p className="text-[10px] font-black text-red-600">৳{c.item.price} x {c.qty}</p>
                      </div>
                    </div>
                    <p className="font-black text-xl italic">৳{c.item.price * c.qty}</p>
                  </div>
                ))}
                <div className="h-px bg-gray-100 my-8"></div>
                <div className="flex justify-between text-3xl font-black italic">
                   <span>Final Value</span>
                   <span className="text-red-600">৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50}</span>
                </div>
                <Button fullWidth size="lg" className="rounded-3xl py-6 mt-10 shadow-2xl shadow-red-600/20" onClick={handleCheckout} disabled={isCheckingOut}>
                  {isCheckingOut ? <><i className="fas fa-circle-notch animate-spin mr-3"></i> Syncing Node...</> : 'Initiate Secure Checkout'}
                </Button>
              </div>
            )}
          </div>
        )}
      </main>

      {/* Mobile Footer */}
      <nav className="lg:hidden fixed bottom-0 left-0 w-full bg-white/95 backdrop-blur-xl border-t border-gray-100 flex justify-around p-6 z-[5000] shadow-[0_-10px_30px_-15px_rgba(0,0,0,0.1)]">
        {[
          { icon: 'fa-home', label: 'Home', view: 'HOME' },
          { icon: 'fa-utensils', label: 'Vault', view: 'MENU' },
          { icon: 'fa-rocket', label: 'Pulse', view: 'TRACKING' },
          { icon: 'fa-user-astronaut', label: 'Me', view: 'PROFILE' }
        ].map(nav => (
          <button key={nav.view} onClick={() => setView(nav.view as any)} className={`flex flex-col items-center gap-1.5 transition-all ${view === nav.view ? 'text-red-600 scale-110' : 'text-gray-400'}`}>
            <i className={`fas ${nav.icon} text-xl`}></i>
            <span className="text-[8px] font-black uppercase tracking-widest">{nav.label}</span>
          </button>
        ))}
      </nav>

      <ChatBot isOnline={isOnline} />
    </div>
  );
};

export default App;

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  STAFF = 'STAFF',
  CUSTOMER = 'CUSTOMER'
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export interface Review {
  id: string;
  userName: string;
  rating: number;
  comment: string;
  date: string;
}

export interface MenuItem {
  id: string;
  name: string;
  nameBn: string;
  description: string;
  price: number;
  category: string;
  image: string;
  rating: number;
  reviews?: Review[];
  ingredients: string[];
  dietary: string[];
  stock: number;
  prepTime: string;
  isPopular?: boolean;
}

export interface CartItem {
  item: MenuItem;
  qty: number;
  isSubscription?: boolean;
}

export interface RewardVoucher {
  id: string;
  title: string;
  description: string;
  pointsCost: number;
  code: string;
  icon: string;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone?: string;
  items: Array<{
    menuId: string;
    quantity: number;
    price: number;
    name: string;
  }>;
  total: number;
  status: OrderStatus;
  createdAt: string;
  paymentStatus: 'PAID' | 'UNPAID';
  paymentMethod: 'BKASH' | 'NAGAD' | 'ROCKET' | 'UPAY' | 'CARD' | 'COD';
  address: string;
  deliveryZone: string;
  deliverySlot: string;
  deliveryInstructions?: string;
  pointsEarned: number;
  trackingUpdates: Array<{ status: OrderStatus; time: string }>;
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  phone: string;
  password?: string;
  loyaltyPoints: number;
  tier: 'SILVER' | 'GOLD' | 'PLATINUM';
  wishlist: string[];
  referralCode: string;
  profileImage?: string;
  sessionToken?: string;
  unlockedVouchers?: string[];
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

export interface AuditLog {
  id: string;
  userId: string;
  userName: string;
  action: string;
  details: string;
  timestamp: string;
  level: 'INFO' | 'WARNING' | 'CRITICAL';
}

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem, RewardVoucher } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
}

const AVAILABLE_REWARDS: RewardVoucher[] = [
  { id: 'RV-01', title: 'Free Borhani', description: 'Redeem points for a 500ml chilled Borhani.', pointsCost: 150, code: 'FREEBOR', icon: 'fa-glass-water' },
  { id: 'RV-02', title: '20% Off Mission', description: 'Get 20% flat discount on your next order.', pointsCost: 300, code: 'OFF20ELITE', icon: 'fa-tags' },
  { id: 'RV-03', title: 'Priority Delivery', description: 'Skip the queue for the next 3 missions.', pointsCost: 100, code: 'FASTFLY', icon: 'fa-bolt' },
  { id: 'RV-04', title: 'Dessert Protocol', description: 'One free Mishti Doi with any kacchi.', pointsCost: 80, code: 'SWEETBFC', icon: 'fa-cookie-bite' },
];

const App: React.FC = () => {
  // Core State
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'PROFILE'>('HOME');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Auth States
  const [isSignup, setIsSignup] = useState(false);
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [formName, setFormName] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  // Profile Edit States
  const [editName, setEditName] = useState('');
  const [editPhone, setEditPhone] = useState('');
  const [editImage, setEditImage] = useState<string | undefined>(undefined);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Menu Filter States
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  // Checkout States
  const [isCheckingOut, setIsCheckingOut] = useState(false);

  // Computed Values
  const categories = useMemo(() => ['All', ...new Set(menuItems.map(item => item.category))], [menuItems]);

  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [menuItems, searchQuery, activeCategory]);

  const showToast = useCallback((message: string, type: Toast['type'] = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  // Sync Persistence
  useEffect(() => {
    const savedSession = localStorage.getItem('bfc_user_session');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setEditName(user.name);
        setEditPhone(user.phone);
        setEditImage(user.profileImage);
        if (user.role !== UserRole.CUSTOMER) setView('ADMIN');
      } catch (e) { localStorage.removeItem('bfc_user_session'); }
    }
  }, []);

  useEffect(() => {
    const handleOnline = () => { 
      setIsOnline(true); 
      showToast('Node Link Established.', 'success'); 
    };
    const handleOffline = () => { 
      setIsOnline(false); 
      showToast('Link Severed. Offline Mode.', 'error'); 
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => { 
      window.removeEventListener('online', handleOnline); 
      window.removeEventListener('offline', handleOffline); 
    };
  }, [showToast]);

  const handleAuth = async () => {
    if (!formEmail.trim() || !formPass.trim()) {
      showToast('Credentials required.', 'warning');
      return;
    }

    setIsAuthenticating(true);
    try {
      if (!isOnline) throw new Error('OFFLINE');
      await new Promise(resolve => setTimeout(resolve, 1500));

      let user: User;

      if (isSignup) {
        user = {
          id: 'U-' + Math.random().toString(36).slice(2, 7),
          name: formName,
          email: formEmail,
          phone: formPhone,
          role: UserRole.CUSTOMER,
          loyaltyPoints: 50, // Welcome points
          tier: 'SILVER',
          wishlist: [],
          referralCode: 'BFC-' + Math.random().toString(36).slice(2, 6).toUpperCase(),
          unlockedVouchers: []
        };
        showToast('Account Created! +50 Points awarded.', 'success');
      } else {
        const role = formEmail.includes('admin') ? UserRole.ADMIN : UserRole.CUSTOMER;
        user = {
          id: 'U-EXISTING',
          name: role === UserRole.ADMIN ? 'Head Admin' : 'Valued Client',
          email: formEmail,
          phone: '01700000000',
          role,
          loyaltyPoints: 240,
          tier: 'GOLD',
          wishlist: [],
          referralCode: 'BFC-BOSS',
          unlockedVouchers: []
        };
        showToast('Login Successful.', 'success');
      }

      setCurrentUser(user);
      setEditName(user.name);
      setEditPhone(user.phone);
      setEditImage(user.profileImage);
      localStorage.setItem('bfc_user_session', JSON.stringify(user));
      setView(user.role === UserRole.ADMIN ? 'ADMIN' : 'HOME');
    } catch (error: any) {
      showToast('Authentication Interrupted.', 'error');
    } finally {
      setIsAuthenticating(false);
    }
  };

  const handleRedeem = (reward: RewardVoucher) => {
    if (!currentUser) return;
    if (currentUser.loyaltyPoints < reward.pointsCost) {
      showToast('Insufficient points for this reward.', 'warning');
      return;
    }

    const updatedUser: User = {
      ...currentUser,
      loyaltyPoints: currentUser.loyaltyPoints - reward.pointsCost,
      unlockedVouchers: [...(currentUser.unlockedVouchers || []), reward.id]
    };

    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    showToast(`${reward.title} unlocked! Code: ${reward.code}`, 'success');
  };

  const handleClaimDaily = () => {
    if (!currentUser) return;
    const lastClaim = localStorage.getItem('bfc_last_claim');
    const today = new Date().toDateString();

    if (lastClaim === today) {
      showToast('Daily bonus already claimed for today.', 'info');
      return;
    }

    const bonus = 10;
    const updatedUser: User = { ...currentUser, loyaltyPoints: currentUser.loyaltyPoints + bonus };
    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    localStorage.setItem('bfc_last_claim', today);
    showToast(`Claimed +${bonus} points!`, 'success');
  };

  const handleUpdateProfile = () => {
    if (!currentUser) return;
    const updatedUser: User = {
      ...currentUser,
      name: editName,
      phone: editPhone,
      profileImage: editImage
    };
    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    showToast('Profile Updated.', 'success');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setEditImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleCheckout = async () => {
    if (!currentUser) { setView('LOGIN'); return; }
    setIsCheckingOut(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 2000));
      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser.id,
        customerName: currentUser.name,
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total: cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: 'PAID',
        paymentMethod: 'BKASH',
        address: 'Dhaka Sector Node',
        deliveryZone: 'Dhaka',
        deliverySlot: 'Express',
        pointsEarned: 25,
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };
      setAllOrders(prev => [newOrder, ...prev]);

      // Award points
      const updatedUser: User = { ...currentUser, loyaltyPoints: currentUser.loyaltyPoints + 25 };
      setCurrentUser(updatedUser);
      localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));

      setCart([]);
      setView('HOME');
      showToast('Order Successful! Points Added.', 'success');
    } finally {
      setIsCheckingOut(false);
    }
  };

  const addToCart = (item: MenuItem) => {
    if (item.stock <= 0) { showToast('Item Out of Stock.', 'warning'); return; }
    setCart(prev => {
      const existing = prev.find(c => c.item.id === item.id);
      if (existing) return prev.map(c => c.item.id === item.id ? { ...c, qty: c.qty + 1 } : c);
      return [...prev, { item, qty: 1 }];
    });
    showToast(`${item.name} added.`, 'success');
  };

  if (view === 'ADMIN' && currentUser?.role !== UserRole.CUSTOMER) {
    return (
      <AdminPanel 
        userRole={currentUser!.role} 
        onLogout={() => { setCurrentUser(null); setView('HOME'); localStorage.removeItem('bfc_user_session'); }}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans">
      <div className="fixed top-12 right-6 z-[5500] space-y-3 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto px-6 py-4 rounded-2xl shadow-2xl border bg-white animate-slide-up flex items-start gap-4 border-gray-100">
             <div className={`mt-0.5 w-6 h-6 rounded-lg flex items-center justify-center shrink-0 ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>
                <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark' : 'fa-check-circle'} text-[10px]`}></i>
             </div>
             <p className="font-black text-[10px] text-gray-800 uppercase tracking-tight leading-tight">{t.message}</p>
          </div>
        ))}
      </div>

      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-12 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white text-xl font-black shadow-lg">B</div>
          <h1 className="text-2xl font-black text-red-600 tracking-tighter italic">BFC</h1>
        </div>
        <div className="hidden md:flex gap-10">
          {['HOME', 'MENU', 'VAULT'].map(v => (
            <button key={v} onClick={() => setView(v as any)} className={`text-[10px] font-black uppercase tracking-[3px] transition-all hover:text-red-600 ${view === v ? 'text-red-600' : 'text-gray-400'}`}>{v}</button>
          ))}
        </div>
        <div className="flex items-center gap-4">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 bg-white rounded-2xl border flex items-center justify-center shadow-sm">
            <i className="fas fa-shopping-basket text-gray-700"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[9px] w-6 h-6 rounded-full flex items-center justify-center font-black">{cart.length}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-12 h-12 rounded-2xl bg-gray-950 text-white font-black flex items-center justify-center overflow-hidden border-2 border-white shadow-xl">
              {currentUser.profileImage ? <img src={currentUser.profileImage} className="w-full h-full object-cover" alt="Me" /> : currentUser.name.charAt(0)}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl px-6" onClick={() => setView('LOGIN')}>Initialize</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-10">
        {view === 'HOME' && (
          <div className="animate-slide-up space-y-16">
            <header className="relative h-[450px] lg:h-[600px] rounded-[50px] overflow-hidden shadow-2xl border-8 border-white group">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover" alt="BFC Hero" />
               <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent flex flex-col justify-end p-12 lg:p-20">
                  <h2 className="text-5xl lg:text-8xl font-black text-white leading-[0.85] mb-8 tracking-tighter italic uppercase">DHAKA’S<br/><span className="text-red-600">ELITE FLAVORS</span></h2>
                  <div className="flex gap-4">
                    <Button size="lg" className="rounded-2xl shadow-2xl" onClick={() => setView('MENU')}>Open Vault</Button>
                    <button onClick={() => setView('VAULT')} className="px-8 py-4 bg-white/10 backdrop-blur-md text-white rounded-2xl font-black text-[10px] uppercase tracking-widest border border-white/20">Loyalty Rewards</button>
                  </div>
               </div>
            </header>
            <section>
              <h3 className="text-3xl font-black uppercase italic tracking-tighter mb-10">Daily Specials</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                {menuItems.slice(0, 3).map(item => (
                  <div key={item.id} className="bg-white rounded-[45px] p-6 shadow-sm border border-gray-50">
                     <img src={item.image} className="h-64 w-full rounded-[35px] object-cover mb-6" alt={item.name} />
                     <h4 className="text-2xl font-black mb-2">{item.name}</h4>
                     <p className="text-xs text-gray-400 mb-8">{item.description}</p>
                     <Button fullWidth variant="outline" className="rounded-2xl" onClick={() => addToCart(item)}>Buy ৳{item.price}</Button>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {view === 'VAULT' && (
          <div className="max-w-6xl mx-auto space-y-12 animate-slide-up">
             <div className="bg-gray-950 p-12 rounded-[60px] text-white relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-red-600/20 rounded-full blur-[100px] -mr-32 -mt-32"></div>
                <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-10">
                   <div className="text-center md:text-left">
                      <p className="text-[10px] font-black uppercase tracking-[5px] text-red-500 mb-2">BFC ELITE STATUS</p>
                      <h3 className="text-5xl font-black italic tracking-tighter leading-none mb-4">THE REWARDS VAULT</h3>
                      <p className="text-gray-400 text-sm font-bold">Earn points on every mission. Unlock legendary perks.</p>
                   </div>
                   <div className="bg-white/5 backdrop-blur-xl p-10 rounded-[45px] border border-white/10 text-center min-w-[250px]">
                      <p className="text-[9px] font-black uppercase tracking-widest text-gray-500 mb-2">Current Balance</p>
                      <h4 className="text-6xl font-black text-red-600 italic leading-none">{currentUser?.loyaltyPoints || 0}</h4>
                      <p className="text-[9px] font-black uppercase tracking-widest text-gray-500 mt-2">Elite Points</p>
                      {currentUser && (
                        <button onClick={handleClaimDaily} className="mt-8 px-8 py-3 bg-red-600 text-white rounded-2xl text-[8px] font-black uppercase tracking-[2px] shadow-xl hover:scale-105 transition-all">Claim Daily Bonus</button>
                      )}
                   </div>
                </div>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                {AVAILABLE_REWARDS.map(reward => {
                  const isUnlocked = currentUser?.unlockedVouchers?.includes(reward.id);
                  return (
                    <div key={reward.id} className={`bg-white p-8 rounded-[45px] border border-gray-100 shadow-sm flex flex-col justify-between transition-all ${isUnlocked ? 'border-emerald-500 bg-emerald-50/10' : ''}`}>
                       <div>
                          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-xl mb-6 shadow-xl ${isUnlocked ? 'bg-emerald-500 text-white' : 'bg-gray-950 text-white'}`}>
                             <i className={`fas ${reward.icon}`}></i>
                          </div>
                          <h5 className="text-xl font-black italic mb-2">{reward.title}</h5>
                          <p className="text-[10px] font-bold text-gray-400 leading-relaxed mb-6">{reward.description}</p>
                       </div>
                       <div>
                          <div className="h-px bg-gray-100 mb-6"></div>
                          {isUnlocked ? (
                            <div className="bg-emerald-100 text-emerald-700 p-4 rounded-2xl text-center">
                               <p className="text-[8px] font-black uppercase mb-1">UNLOCKED CODE</p>
                               <p className="text-sm font-black tracking-widest">{reward.code}</p>
                            </div>
                          ) : (
                            <button 
                              onClick={() => handleRedeem(reward)}
                              className="w-full py-4 bg-gray-50 text-gray-950 rounded-2xl text-[9px] font-black uppercase tracking-widest border border-gray-100 hover:bg-red-600 hover:text-white transition-all"
                            >
                              Redeem {reward.pointsCost} Pkts
                            </button>
                          )}
                       </div>
                    </div>
                  );
                })}
             </div>
          </div>
        )}

        {view === 'MENU' && (
          <div className="animate-slide-up space-y-10">
            <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-8">
              <div>
                <h3 className="text-4xl font-black uppercase italic tracking-tighter leading-none">The Vault Menu</h3>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[4px] mt-2 italic">Secured local recipes</p>
              </div>
              <div className="relative w-full lg:w-1/3">
                <i className="fas fa-search absolute left-5 top-1/2 -translate-y-1/2 text-gray-400 text-sm"></i>
                <input 
                  type="text" 
                  placeholder="Kacchi, Roast..." 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full bg-white border border-gray-100 p-5 pl-14 rounded-3xl outline-none focus:border-red-600 transition-colors font-bold text-xs"
                />
              </div>
            </div>

            <div className="flex gap-3 overflow-x-auto pb-4 scrollbar-hide">
              {categories.map(cat => (
                <button key={cat} onClick={() => setActiveCategory(cat)} className={`px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeCategory === cat ? 'bg-red-600 text-white shadow-lg' : 'bg-white text-gray-400 border border-gray-50'}`}>{cat}</button>
              ))}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
              {filteredMenu.map(item => (
                <div key={item.id} className="bg-white rounded-[50px] border border-gray-100 p-5 hover:shadow-2xl transition-all group flex flex-col h-full">
                   <img src={item.image} className="w-full h-60 object-cover rounded-[40px] mb-6" alt={item.name} />
                   <div className="px-3 flex-1 flex flex-col">
                      <h4 className="font-black text-xl mb-1">{item.name}</h4>
                      <p className="text-[10px] font-black text-red-600 uppercase mb-6 italic">{item.nameBn}</p>
                      <Button fullWidth size="md" className="rounded-2xl mt-auto py-4" onClick={() => addToCart(item)}>Buy ৳{item.price}</Button>
                   </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'LOGIN' && (
          <div className="max-w-md mx-auto py-16 animate-slide-up">
             <div className="bg-white p-14 rounded-[60px] shadow-3xl border border-gray-50 relative overflow-hidden text-center">
                <div className="w-20 h-20 bg-gray-950 rounded-3xl flex items-center justify-center text-white text-3xl shadow-2xl mx-auto mb-10">
                   <i className={`fas ${isSignup ? 'fa-user-plus' : 'fa-shield-halved'}`}></i>
                </div>
                <h3 className="text-3xl font-black uppercase italic tracking-tighter mb-10">{isSignup ? 'New Account' : 'Mainframe Access'}</h3>
                <div className="space-y-5">
                  {isSignup && (
                    <>
                      <input type="text" value={formName} onChange={e => setFormName(e.target.value)} placeholder="Full Name" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none" />
                      <input type="tel" value={formPhone} onChange={e => setFormPhone(e.target.value)} placeholder="Phone Link" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none" />
                    </>
                  )}
                  <input type="email" value={formEmail} onChange={e => setFormEmail(e.target.value)} placeholder="Email ID" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none" />
                  <input type="password" value={formPass} onChange={e => setFormPass(e.target.value)} placeholder="Password" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none" />
                  <Button fullWidth size="lg" className="rounded-3xl mt-6 py-5" onClick={handleAuth} disabled={isAuthenticating}>{isAuthenticating ? 'Working...' : (isSignup ? 'Create Account' : 'Connect Node')}</Button>
                  <button onClick={() => setIsSignup(!isSignup)} className="text-[10px] font-black uppercase text-red-600 mt-8">{isSignup ? 'Have account? Sign in' : 'No account? Join Club'}</button>
                </div>
             </div>
          </div>
        )}

        {view === 'PROFILE' && currentUser && (
          <div className="max-w-4xl mx-auto space-y-12 animate-slide-up">
             <div className="bg-white p-12 rounded-[60px] border border-gray-100 flex flex-col md:flex-row items-center gap-10">
                <div className="relative">
                   <div className="w-44 h-44 rounded-[50px] bg-gray-100 border-4 border-white shadow-2xl overflow-hidden flex items-center justify-center text-5xl font-black text-gray-300">
                      {editImage ? <img src={editImage} className="w-full h-full object-cover" alt="Me" /> : currentUser.name.charAt(0)}
                   </div>
                   <button onClick={() => fileInputRef.current?.click()} className="absolute -bottom-4 -right-4 w-12 h-12 bg-red-600 text-white rounded-2xl shadow-xl flex items-center justify-center border-4 border-white">
                      <i className="fas fa-camera"></i>
                   </button>
                   <input type="file" ref={fileInputRef} onChange={handleImageUpload} accept="image/*" className="hidden" />
                </div>
                <div className="flex-1 text-center md:text-left">
                   <h3 className="text-4xl font-black tracking-tighter italic uppercase mb-2">{currentUser.name}</h3>
                   <span className="px-5 py-2 bg-red-600 text-white rounded-full text-[9px] font-black tracking-widest">{currentUser.tier} NODE</span>
                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-6">Loyalty Status: <span className="text-red-600">{currentUser.loyaltyPoints} Pkts</span></p>
                   <div className="mt-8 flex flex-wrap justify-center md:justify-start gap-4">
                      <button onClick={() => { localStorage.removeItem('bfc_user_session'); setCurrentUser(null); setView('HOME'); }} className="px-8 py-4 bg-red-50 text-red-600 rounded-3xl font-black text-[10px] uppercase">Terminate Session</button>
                   </div>
                </div>
             </div>
             <div className="bg-white p-12 rounded-[60px] border border-gray-100 shadow-sm space-y-8">
                <h4 className="text-xl font-black uppercase italic tracking-tighter">Update Parameters</h4>
                <div className="space-y-5">
                   <input type="text" value={editName} onChange={e => setEditName(e.target.value)} placeholder="Node Name" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none" />
                   <input type="tel" value={editPhone} onChange={e => setEditPhone(e.target.value)} placeholder="Phone Link" className="w-full bg-gray-50 p-6 rounded-[28px] font-black text-sm outline-none" />
                   <Button fullWidth onClick={handleUpdateProfile} className="rounded-3xl py-5 mt-6">Sync Profile</Button>
                </div>
             </div>
          </div>
        )}

        {view === 'CART' && (
          <div className="max-w-4xl mx-auto animate-slide-up space-y-12">
            <h3 className="text-4xl font-black uppercase italic tracking-tighter">Mission Payload</h3>
            {cart.length === 0 ? (
              <div className="bg-white p-24 rounded-[60px] text-center border-2 border-dashed border-gray-100">
                <p className="font-black text-gray-400 uppercase tracking-[6px] mb-8">Payload Empty</p>
                <Button variant="outline" className="px-12 rounded-2xl" onClick={() => setView('MENU')}>View Menu</Button>
              </div>
            ) : (
              <div className="bg-white p-12 rounded-[60px] shadow-sm space-y-8">
                {cart.map((c, i) => (
                  <div key={i} className="flex justify-between items-center p-4 border-b border-gray-50">
                    <div className="flex gap-6 items-center">
                      <img src={c.item.image} className="w-16 h-16 rounded-2xl object-cover" alt={c.item.name} />
                      <div>
                        <h4 className="font-black text-lg">{c.item.name}</h4>
                        <p className="text-[10px] font-black text-red-600">৳{c.item.price} x {c.qty}</p>
                      </div>
                    </div>
                    <p className="font-black text-xl italic">৳{c.item.price * c.qty}</p>
                  </div>
                ))}
                <div className="flex justify-between text-3xl font-black italic pt-10">
                   <span>Final Value</span>
                   <span className="text-red-600">৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50}</span>
                </div>
                <Button fullWidth size="lg" className="rounded-3xl py-6 mt-10 shadow-2xl" onClick={handleCheckout} disabled={isCheckingOut}>
                  {isCheckingOut ? 'Initiating Mission...' : 'Confirm Checkout'}
                </Button>
              </div>
            )}
          </div>
        )}
      </main>

      <nav className="lg:hidden fixed bottom-0 left-0 w-full bg-white/95 backdrop-blur-xl border-t border-gray-100 flex justify-around p-6 z-[5000]">
        {[
          { icon: 'fa-home', label: 'Home', view: 'HOME' },
          { icon: 'fa-utensils', label: 'Menu', view: 'MENU' },
          { icon: 'fa-gem', label: 'Vault', view: 'VAULT' },
          { icon: 'fa-user-astronaut', label: 'Me', view: 'PROFILE' }
        ].map(nav => (
          <button key={nav.view} onClick={() => setView(nav.view as any)} className={`flex flex-col items-center gap-1.5 transition-all ${view === nav.view ? 'text-red-600 scale-110' : 'text-gray-400'}`}>
            <i className={`fas ${nav.icon} text-xl`}></i>
            <span className="text-[8px] font-black uppercase tracking-widest">{nav.label}</span>
          </button>
        ))}
      </nav>

      <ChatBot isOnline={isOnline} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem, RewardVoucher } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
}

const AVAILABLE_REWARDS: RewardVoucher[] = [
  { id: 'RV-01', title: 'Free Borhani', description: 'Redeem points for a 500ml chilled Borhani.', pointsCost: 150, code: 'FREEBOR', icon: 'fa-glass-water' },
  { id: 'RV-02', title: '20% Off Mission', description: 'Get 20% flat discount on your next order.', pointsCost: 300, code: 'OFF20ELITE', icon: 'fa-tags' },
  { id: 'RV-03', title: 'Priority Delivery', description: 'Skip the queue for the next 3 missions.', pointsCost: 100, code: 'FASTFLY', icon: 'fa-bolt' },
  { id: 'RV-04', title: 'Dessert Protocol', description: 'One free Mishti Doi with any kacchi.', pointsCost: 80, code: 'SWEETBFC', icon: 'fa-cookie-bite' },
];

const PAYMENT_METHODS = [
  { id: 'BKASH', label: 'bKash', icon: 'fa-mobile-screen', color: 'bg-pink-600' },
  { id: 'ROCKET', label: 'Rocket', icon: 'fa-building-columns', color: 'bg-purple-700' },
  { id: 'UPAY', label: 'Upay', icon: 'fa-wallet', color: 'bg-amber-500' },
  { id: 'NAGAD', label: 'Nagad', icon: 'fa-money-bill-transfer', color: 'bg-orange-600' },
  { id: 'CARD', label: 'Card', icon: 'fa-credit-card', color: 'bg-blue-600' },
];

const App: React.FC = () => {
  // Core State
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'PROFILE'>('HOME');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Auth States
  const [isSignup, setIsSignup] = useState(false);
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [formName, setFormName] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  // Profile Edit States
  const [editName, setEditName] = useState('');
  const [editPhone, setEditPhone] = useState('');
  const [editImage, setEditImage] = useState<string | undefined>(undefined);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Menu Filter States
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  // Checkout States
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [selectedPayment, setSelectedPayment] = useState<string>('BKASH');

  // Computed Values
  const categories = useMemo(() => ['All', ...new Set(menuItems.map(item => item.category))], [menuItems]);

  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [menuItems, searchQuery, activeCategory]);

  const showToast = useCallback((message: string, type: Toast['type'] = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  // Sync Persistence
  useEffect(() => {
    const savedSession = localStorage.getItem('bfc_user_session');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setEditName(user.name);
        setEditPhone(user.phone);
        setEditImage(user.profileImage);
        if (user.role !== UserRole.CUSTOMER) setView('ADMIN');
      } catch (e) { localStorage.removeItem('bfc_user_session'); }
    }
  }, []);

  useEffect(() => {
    const handleOnline = () => { 
      setIsOnline(true); 
      showToast('Node Link Established.', 'success'); 
    };
    const handleOffline = () => { 
      setIsOnline(false); 
      showToast('Link Severed. Offline Mode.', 'error'); 
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => { 
      window.removeEventListener('online', handleOnline); 
      window.removeEventListener('offline', handleOffline); 
    };
  }, [showToast]);

  const handleAuth = async () => {
    if (!formEmail.trim() || !formPass.trim()) {
      showToast('Credentials required.', 'warning');
      return;
    }

    setIsAuthenticating(true);
    try {
      if (!isOnline) throw new Error('OFFLINE');
      await new Promise(resolve => setTimeout(resolve, 1500));

      let user: User;

      if (isSignup) {
        user = {
          id: 'U-' + Math.random().toString(36).slice(2, 7),
          name: formName,
          email: formEmail,
          phone: formPhone,
          role: UserRole.CUSTOMER,
          loyaltyPoints: 50, // Welcome points
          tier: 'SILVER',
          wishlist: [],
          referralCode: 'BFC-' + Math.random().toString(36).slice(2, 6).toUpperCase(),
          unlockedVouchers: []
        };
        showToast('Account Created! +50 Points awarded.', 'success');
      } else {
        const role = formEmail.includes('admin') ? UserRole.ADMIN : UserRole.CUSTOMER;
        user = {
          id: 'U-EXISTING',
          name: role === UserRole.ADMIN ? 'Head Admin' : 'Valued Client',
          email: formEmail,
          phone: '01700000000',
          role,
          loyaltyPoints: 240,
          tier: 'GOLD',
          wishlist: [],
          referralCode: 'BFC-BOSS',
          unlockedVouchers: []
        };
        showToast('Login Successful.', 'success');
      }

      setCurrentUser(user);
      setEditName(user.name);
      setEditPhone(user.phone);
      setEditImage(user.profileImage);
      localStorage.setItem('bfc_user_session', JSON.stringify(user));
      setView(user.role === UserRole.ADMIN ? 'ADMIN' : 'HOME');
    } catch (error: any) {
      showToast('Authentication Interrupted.', 'error');
    } finally {
      setIsAuthenticating(false);
    }
  };

  const handleRedeem = (reward: RewardVoucher) => {
    if (!currentUser) return;
    if (currentUser.loyaltyPoints < reward.pointsCost) {
      showToast('Insufficient points for this reward.', 'warning');
      return;
    }

    const updatedUser: User = {
      ...currentUser,
      loyaltyPoints: currentUser.loyaltyPoints - reward.pointsCost,
      unlockedVouchers: [...(currentUser.unlockedVouchers || []), reward.id]
    };

    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    showToast(`${reward.title} unlocked! Code: ${reward.code}`, 'success');
  };

  const handleClaimDaily = () => {
    if (!currentUser) return;
    const lastClaim = localStorage.getItem('bfc_last_claim');
    const today = new Date().toDateString();

    if (lastClaim === today) {
      showToast('Daily bonus already claimed for today.', 'info');
      return;
    }

    const bonus = 10;
    const updatedUser: User = { ...currentUser, loyaltyPoints: currentUser.loyaltyPoints + bonus };
    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    localStorage.setItem('bfc_last_claim', today);
    showToast(`Claimed +${bonus} points!`, 'success');
  };

  const handleUpdateProfile = () => {
    if (!currentUser) return;
    const updatedUser: User = {
      ...currentUser,
      name: editName,
      phone: editPhone,
      profileImage: editImage
    };
    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    showToast('Profile Updated.', 'success');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setEditImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleCheckout = async () => {
    if (!currentUser) { setView('LOGIN'); return; }
    setIsCheckingOut(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 2000));
      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser.id,
        customerName: currentUser.name,
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total: cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: 'PAID',
        paymentMethod: selectedPayment as any,
        address: 'Dhaka Sector Node',
        deliveryZone: 'Dhaka',
        deliverySlot: 'Express',
        pointsEarned: 25,
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };
      setAllOrders(prev => [newOrder, ...prev]);

      // Award points
      const updatedUser: User = { ...currentUser, loyaltyPoints: currentUser.loyaltyPoints + 25 };
      setCurrentUser(updatedUser);
      localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));

      setCart([]);
      setView('HOME');
      showToast(`Order Confirmed via ${selectedPayment}! Points Added.`, 'success');
    } finally {
      setIsCheckingOut(false);
    }
  };

  const addToCart = (item: MenuItem) => {
    if (item.stock <= 0) { showToast('Item Out of Stock.', 'warning'); return; }
    setCart(prev => {
      const existing = prev.find(c => c.item.id === item.id);
      if (existing) return prev.map(c => c.item.id === item.id ? { ...c, qty: c.qty + 1 } : c);
      return [...prev, { item, qty: 1 }];
    });
    showToast(`${item.name} added.`, 'success');
  };

  if (view === 'ADMIN' && currentUser?.role !== UserRole.CUSTOMER) {
    return (
      <AdminPanel 
        userRole={currentUser!.role} 
        onLogout={() => { setCurrentUser(null); setView('HOME'); localStorage.removeItem('bfc_user_session'); }}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans">
      <div className="fixed top-12 right-6 z-[5500] space-y-3 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto px-6 py-4 rounded-2xl shadow-2xl border bg-white animate-slide-up flex items-start gap-4 border-gray-100">
             <div className={`mt-0.5 w-6 h-6 rounded-lg flex items-center justify-center shrink-0 ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>
                <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark' : 'fa-check-circle'} text-[10px]`}></i>
             </div>
             <p className="font-black text-[10px] text-gray-800 uppercase tracking-tight leading-tight">{t.message}</p>
          </div>
        ))}
