          'Customer Name': c.name, 'Total Orders': c.totalOrders, 'Total Spend (৳)': c.totalSpend, 'Avg Order Value (৳)': (c.totalSpend / c.totalOrders).toFixed(2), 'Last Active': new Date(c.lastOrder).toLocaleDateString()
