    if (!currentUser) return;
    if (currentUser.loyaltyPoints < reward.pointsCost) {
      showToast('Insufficient points for this reward.', 'warning');
      return;
    }

    const updatedUser: User = {
      ...currentUser,
      loyaltyPoints: currentUser.loyaltyPoints - reward.pointsCost,
      unlockedVouchers: [...(currentUser.unlockedVouchers || []), reward.id]
