    const today = new Date().toDateString();

    if (lastClaim === today) {
      showToast('Daily bonus already claimed for today.', 'info');
      return;
    }

    const bonus = 10;
    const updatedUser: User = { ...currentUser, loyaltyPoints: currentUser.loyaltyPoints + bonus };
    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    localStorage.setItem('bfc_last_claim', today);
    showToast(`Claimed +${bonus} points!`, 'success');
  };

  const handleCheckout = async () => {
    if (!currentUser) { setView('LOGIN'); return; }

    // Validation for CARD
    if (selectedPayment === 'CARD') {
      if (!cardDetails.number || !cardDetails.expiry || !cardDetails.cvv) {
        showToast('Please provide card parameters.', 'warning');
        return;
      }
    }

    setIsCheckingOut(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 2000));
