        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser.id,
        customerName: currentUser.name,
        customerPhone: currentUser.phone,
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total: cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: selectedPayment === 'COD' ? 'UNPAID' : 'PAID',
        paymentMethod: selectedPayment as any,
        address: 'Dhaka Sector Node',
        deliveryZone: 'Dhaka',
        deliverySlot: 'Express',
        pointsEarned: 25,
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };
      setAllOrders(prev => [newOrder, ...prev]);

      const updatedUser: User = { ...currentUser, loyaltyPoints: currentUser.loyaltyPoints + 25 };
      setCurrentUser(updatedUser);
      localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));

      setCart([]);
      setView('HOME');
      showToast(`Order Confirmed via ${selectedPayment}! Points Added.`, 'success');
    } finally {
      setIsCheckingOut(false);
    }
  };

  const addToCart = (item: MenuItem) => {
