                  </div>

                  <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3 sm:gap-4">
                    {PAYMENT_METHODS.map((method) => (
                      <button
                        key={method.id}
                        onClick={() => setSelectedPayment(method.id)}
                        className={`relative flex flex-col items-center gap-2.5 p-4 rounded-[30px] border-2 transition-all duration-300 group ${
                          selectedPayment === method.id 
                          ? 'border-red-600 bg-red-50/20 shadow-2xl shadow-red-600/10 scale-[1.05]' 
                          : 'border-gray-50 bg-white hover:border-gray-200 hover:scale-[1.02]'
                        }`}
                      >
                        <div className={`w-10 h-10 sm:w-12 sm:h-12 rounded-2xl flex items-center justify-center text-white text-lg shadow-lg ${method.color} transition-transform group-active:scale-90`}>
                           <i className={`fas ${method.icon}`}></i>
                        </div>
                        <span className={`text-[8px] sm:text-[9px] font-black uppercase tracking-widest text-center leading-tight ${selectedPayment === method.id ? 'text-gray-900' : 'text-gray-400'}`}>{method.label}</span>
                        {selectedPayment === method.id && (
                          <div className="absolute -top-1.5 -right-1.5 bg-red-600 text-white w-5 h-5 rounded-full flex items-center justify-center border-2 border-white text-[7px] animate-slide-up shadow-lg">
                            <i className="fas fa-check"></i>
                          </div>
                        )}
                      </button>
                    ))}
                  </div>

                  {/* Dynamic Input Form for Card */}
                  {selectedPayment === 'CARD' && (
                    <div className="animate-slide-up bg-gray-50 p-8 rounded-[40px] border border-gray-100 space-y-6">
                       <p className="text-[10px] font-black uppercase tracking-[3px] text-gray-500 mb-4 flex items-center gap-2">
                         <i className="fas fa-lock text-emerald-500"></i> Encrypted Terminal Input
                       </p>
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div className="space-y-2">
                             <label className="text-[9px] font-black uppercase tracking-widest ml-4 text-gray-400">Global Node Number</label>
                             <div className="relative">
                               <input 
                                 type="text" 
                                 placeholder="xxxx xxxx xxxx xxxx" 
                                 value={cardDetails.number}
                                 onChange={(e) => setCardDetails(prev => ({...prev, number: e.target.value}))}
                                 className="w-full bg-white p-5 rounded-2xl font-black text-sm outline-none border-2 border-transparent focus:border-red-600 transition-all shadow-sm"
                               />
                               <i className="fas fa-credit-card absolute right-5 top-1/2 -translate-y-1/2 text-gray-300"></i>
                             </div>
                          </div>
                          <div className="grid grid-cols-2 gap-4">
                             <div className="space-y-2">
                                <label className="text-[9px] font-black uppercase tracking-widest ml-4 text-gray-400">Expiry Sync</label>
                                <input 
                                  type="text" 
                                  placeholder="MM/YY" 
                                  value={cardDetails.expiry}
                                  onChange={(e) => setCardDetails(prev => ({...prev, expiry: e.target.value}))}
                                  className="w-full bg-white p-5 rounded-2xl font-black text-sm outline-none border-2 border-transparent focus:border-red-600 transition-all shadow-sm"
                                />
                             </div>
                             <div className="space-y-2">
                                <label className="text-[9px] font-black uppercase tracking-widest ml-4 text-gray-400">Security Key</label>
                                <input 
                                  type="password" 
                                  placeholder="***" 
                                  maxLength={3}
                                  value={cardDetails.cvv}
                                  onChange={(e) => setCardDetails(prev => ({...prev, cvv: e.target.value}))}
                                  className="w-full bg-white p-5 rounded-2xl font-black text-sm outline-none border-2 border-transparent focus:border-red-600 transition-all shadow-sm"
                                />
                             </div>
                          </div>
                       </div>
                    </div>
                  )}

                  {selectedPayment === 'COD' && (
                    <div className="animate-slide-up bg-emerald-50/50 p-8 rounded-[40px] border border-emerald-100 flex items-center gap-6">
                       <div className="w-14 h-14 bg-emerald-500 text-white rounded-2xl flex items-center justify-center text-xl shadow-xl shadow-emerald-500/20">
                          <i className="fas fa-truck-fast"></i>
                       </div>
                       <div>
                          <p className="text-[10px] font-black uppercase tracking-[2px] text-emerald-700">Physical Node Handover</p>
                          <p className="text-[12px] font-bold text-emerald-900 leading-tight mt-1">Pay the mission operator in person upon payload arrival.</p>
                       </div>
                    </div>
                  )}
                </div>

                <div className="flex justify-between items-end pt-10 border-t border-gray-100">
                   <div>
                      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Total Mission Value</p>
                      <h5 className="text-4xl sm:text-5xl font-black italic text-gray-950 leading-none">৳{cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50}</h5>
                   </div>
                   <Button size="lg" className="rounded-3xl py-5 px-10 shadow-2xl shadow-red-600/20" onClick={handleCheckout} disabled={isCheckingOut}>
                     {isCheckingOut ? 'Authorizing Node...' : 'Initialize Mission'}
                   </Button>
                </div>
              </div>
            )}
          </div>
        )}
      </main>

      <nav className="lg:hidden fixed bottom-0 left-0 w-full bg-white/95 backdrop-blur-xl border-t border-gray-100 flex justify-around p-6 z-[5000]">
        {[
          { icon: 'fa-home', label: 'Home', view: 'HOME' },
          { icon: 'fa-utensils', label: 'Menu', view: 'MENU' },
          { icon: 'fa-gem', label: 'Vault', view: 'VAULT' },
          { icon: 'fa-user-astronaut', label: 'Me', view: 'PROFILE' }
        ].map(nav => (
          <button key={nav.view} onClick={() => setView(nav.view as any)} className={`flex flex-col items-center gap-1.5 transition-all ${view === nav.view ? 'text-red-600 scale-110' : 'text-gray-400'}`}>
            <i className={`fas ${nav.icon} text-xl`}></i>
            <span className="text-[8px] font-black uppercase tracking-widest">{nav.label}</span>
          </button>
        ))}
      </nav>

      <ChatBot isOnline={isOnline} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MenuItem, UserRole, User, Order, OrderStatus, CartItem, RewardVoucher } from './types';
import { MOCK_MENU, MOCK_ORDERS } from './constants';
import { AdminPanel } from './AdminPanel';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';

interface Toast {
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  id: number;
}

const AVAILABLE_REWARDS: RewardVoucher[] = [
  { id: 'RV-01', title: 'Free Borhani', description: 'Redeem points for a 500ml chilled Borhani.', pointsCost: 150, code: 'FREEBOR', icon: 'fa-glass-water' },
  { id: 'RV-02', title: '20% Off Mission', description: 'Get 20% flat discount on your next order.', pointsCost: 300, code: 'OFF20ELITE', icon: 'fa-tags' },
  { id: 'RV-03', title: 'Priority Delivery', description: 'Skip the queue for the next 3 missions.', pointsCost: 100, code: 'FASTFLY', icon: 'fa-bolt' },
  { id: 'RV-04', title: 'Dessert Protocol', description: 'One free Mishti Doi with any kacchi.', pointsCost: 80, code: 'SWEETBFC', icon: 'fa-cookie-bite' },
];

const PAYMENT_METHODS = [
  { id: 'BKASH', label: 'bKash', icon: 'fa-mobile-screen', color: 'bg-[#d12053]', brandColor: '#d12053' },
  { id: 'NAGAD', label: 'Nagad', icon: 'fa-money-bill-transfer', color: 'bg-[#f7941d]', brandColor: '#f7941d' },
  { id: 'ROCKET', label: 'Rocket', icon: 'fa-building-columns', color: 'bg-[#8c3494]', brandColor: '#8c3494' },
  { id: 'UPAY', label: 'Upay', icon: 'fa-wallet', color: 'bg-[#ffc20e]', brandColor: '#ffc20e' },
  { id: 'CARD', label: 'Credit Card', icon: 'fa-credit-card', color: 'bg-[#1a1a1a]', brandColor: '#1a1a1a' },
  { id: 'COD', label: 'Cash on Delivery', icon: 'fa-hand-holding-dollar', color: 'bg-[#059669]', brandColor: '#059669' },
];

const App: React.FC = () => {
  // Core State
  const [menuItems, setMenuItems] = useState<MenuItem[]>(MOCK_MENU);
  const [allOrders, setAllOrders] = useState<Order[]>(MOCK_ORDERS as any);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [view, setView] = useState<'HOME' | 'MENU' | 'CART' | 'ADMIN' | 'LOGIN' | 'VAULT' | 'PROFILE'>('HOME');
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Auth States
  const [isSignup, setIsSignup] = useState(false);
  const [formEmail, setFormEmail] = useState('');
  const [formPass, setFormPass] = useState('');
  const [formName, setFormName] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  // Profile Edit States
  const [editName, setEditName] = useState('');
  const [editPhone, setEditPhone] = useState('');
  const [editImage, setEditImage] = useState<string | undefined>(undefined);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Menu Filter States
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');

  // Checkout & Gateway States
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [selectedPayment, setSelectedPayment] = useState<string>('BKASH');
  const [gatewayStep, setGatewayStep] = useState<1 | 2 | 3>(1); // 1: Select/Input, 2: OTP, 3: PIN (for MFS)
  const [mfsNumber, setMfsNumber] = useState('');
  const [cardDetails, setCardDetails] = useState({ number: '', expiry: '', cvv: '', name: '' });

  // Computed Values
  const categories = useMemo(() => ['All', ...new Set(menuItems.map(item => item.category))], [menuItems]);

  const filteredMenu = useMemo(() => {
    return menuItems.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            item.nameBn.includes(searchQuery);
      const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [menuItems, searchQuery, activeCategory]);

  const showToast = useCallback((message: string, type: Toast['type'] = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { message, type, id }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 6000);
  }, []);

  // Sync Persistence
  useEffect(() => {
    const savedSession = localStorage.getItem('bfc_user_session');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setEditName(user.name);
        setEditPhone(user.phone);
        setEditImage(user.profileImage);
        if (user.role !== UserRole.CUSTOMER) setView('ADMIN');
      } catch (e) { localStorage.removeItem('bfc_user_session'); }
    }
  }, []);

  useEffect(() => {
    const handleOnline = () => { 
      setIsOnline(true); 
      showToast('Node Link Established.', 'success'); 
    };
    const handleOffline = () => { 
      setIsOnline(false); 
      showToast('Link Severed. Offline Mode.', 'error'); 
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => { 
      window.removeEventListener('online', handleOnline); 
      window.removeEventListener('offline', handleOffline); 
    };
  }, [showToast]);

  const handleAuth = async () => {
    if (!formEmail.trim() || !formPass.trim()) {
      showToast('Credentials required.', 'warning');
      return;
    }

    setIsAuthenticating(true);
    try {
      if (!isOnline) throw new Error('OFFLINE');
      await new Promise(resolve => setTimeout(resolve, 1500));

      let user: User;

      if (isSignup) {
        user = {
          id: 'U-' + Math.random().toString(36).slice(2, 7),
          name: formName || 'New Boss',
          email: formEmail,
          phone: formPhone || 'Not Set',
          role: UserRole.CUSTOMER,
          loyaltyPoints: 50,
          tier: 'SILVER',
          wishlist: [],
          referralCode: 'BFC-' + Math.random().toString(36).slice(2, 6).toUpperCase(),
          unlockedVouchers: []
        };
        showToast('Account Created! +50 Points awarded.', 'success');
      } else {
        const role = formEmail.includes('admin') ? UserRole.ADMIN : UserRole.CUSTOMER;
        user = {
          id: 'U-' + (Math.random() * 1000).toFixed(0),
          name: role === UserRole.ADMIN ? 'Head Admin' : 'Valued Client',
          email: formEmail,
          phone: formPhone || '01700000000',
          role,
          loyaltyPoints: 240,
          tier: 'GOLD',
          wishlist: [],
          referralCode: 'BFC-BOSS',
          unlockedVouchers: []
        };
        showToast('Login Successful.', 'success');
      }

      setCurrentUser(user);
      setEditName(user.name);
      setEditPhone(user.phone);
      setEditImage(user.profileImage);
      localStorage.setItem('bfc_user_session', JSON.stringify(user));
      setView(user.role === UserRole.ADMIN ? 'ADMIN' : 'HOME');
    } catch (error: any) {
      showToast('Authentication Interrupted.', 'error');
    } finally {
      setIsAuthenticating(false);
    }
  };

  const handleUpdateProfile = () => {
    if (!currentUser) return;
    if (!editName.trim()) { showToast('Name required.', 'warning'); return; }

    const updatedUser: User = { ...currentUser, name: editName, phone: editPhone, profileImage: editImage };
    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    showToast('Profile parameters synced.', 'success');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) { showToast('Max 2MB.', 'warning'); return; }
      const reader = new FileReader();
      reader.onloadend = () => setEditImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleRedeem = (reward: RewardVoucher) => {
    if (!currentUser) { setView('LOGIN'); return; }
    if (currentUser.loyaltyPoints < reward.pointsCost) { showToast('Insufficient points.', 'warning'); return; }

    const updatedUser: User = {
      ...currentUser,
      loyaltyPoints: currentUser.loyaltyPoints - reward.pointsCost,
      unlockedVouchers: [...(currentUser.unlockedVouchers || []), reward.id]
    };
    setCurrentUser(updatedUser);
    localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));
    showToast(`${reward.title} unlocked!`, 'success');
  };

  const handleCheckoutInitiate = () => {
    if (!currentUser) { 
      showToast('Authorization required for mission payload.', 'warning');
      setView('LOGIN'); 
      return; 
    }

    // Logic for Card validation before final confirm
    if (selectedPayment === 'CARD') {
       if (!cardDetails.number || !cardDetails.expiry || !cardDetails.cvv) {
         showToast('Card parameters missing.', 'error');
         return;
       }
    }

    // Logic for MFS validation
    if (['BKASH', 'NAGAD', 'ROCKET', 'UPAY'].includes(selectedPayment)) {
      if (gatewayStep < 3) {
        if (gatewayStep === 1 && !mfsNumber) { showToast('Valid number required.', 'warning'); return; }
        setGatewayStep((prev) => (prev + 1) as any);
        return;
      }
    }

    handleFinalOrder();
  };

  const handleFinalOrder = async () => {
    setIsCheckingOut(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 2500));
      const total = cart.reduce((a, b) => a + (b.item.price * b.qty), 0) + 50;
      const newOrder: Order = {
        id: 'ORD-' + Math.random().toString(36).slice(2, 7).toUpperCase(),
        customerId: currentUser!.id,
        customerName: currentUser!.name,
        customerPhone: currentUser!.phone,
        items: cart.map(c => ({ menuId: c.item.id, quantity: c.qty, price: c.item.price, name: c.item.name })),
        total,
        status: OrderStatus.PENDING,
        createdAt: new Date().toISOString(),
        paymentStatus: selectedPayment === 'COD' ? 'UNPAID' : 'PAID',
        paymentMethod: selectedPayment as any,
        address: 'User-specified Node Location',
        deliveryZone: 'Dhaka Central',
        deliverySlot: 'Standard',
        pointsEarned: Math.floor(total / 20),
        trackingUpdates: [{ status: OrderStatus.PENDING, time: new Date().toLocaleTimeString() }]
      };
      setAllOrders(prev => [newOrder, ...prev]);

      const updatedUser: User = { ...currentUser!, loyaltyPoints: currentUser!.loyaltyPoints + Math.floor(total / 20) };
      setCurrentUser(updatedUser);
      localStorage.setItem('bfc_user_session', JSON.stringify(updatedUser));

      setCart([]);
      setGatewayStep(1);
      setView('HOME');
      showToast(`Mission Authenticated! Payload via ${selectedPayment}.`, 'success');
    } finally {
      setIsCheckingOut(false);
    }
  };

  const addToCart = (item: MenuItem) => {
    if (item.stock <= 0) { showToast('Item Depleted.', 'warning'); return; }
    setCart(prev => {
      const existing = prev.find(c => c.item.id === item.id);
      if (existing) return prev.map(c => c.item.id === item.id ? { ...c, qty: c.qty + 1 } : c);
      return [...prev, { item, qty: 1 }];
    });
    showToast(`${item.name} assigned to payload.`, 'success');
  };

  if (view === 'ADMIN' && currentUser?.role !== UserRole.CUSTOMER) {
    return (
      <AdminPanel 
        userRole={currentUser!.role} 
        onLogout={() => { setCurrentUser(null); setView('HOME'); localStorage.removeItem('bfc_user_session'); }}
        menuItems={menuItems} setMenuItems={setMenuItems}
        orders={allOrders} setOrders={setAllOrders}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-24 lg:pb-0 font-sans">
      <div className="fixed top-12 right-6 z-[6000] space-y-3 pointer-events-none max-w-sm">
        {toasts.map(t => (
          <div key={t.id} className="pointer-events-auto px-6 py-4 rounded-2xl shadow-2xl border bg-white animate-slide-up flex items-start gap-4 border-gray-100">
             <div className={`mt-0.5 w-6 h-6 rounded-lg flex items-center justify-center shrink-0 ${t.type === 'error' ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>
                <i className={`fas ${t.type === 'error' ? 'fa-circle-xmark' : 'fa-check-circle'} text-[10px]`}></i>
             </div>
             <p className="font-black text-[10px] text-gray-800 uppercase tracking-tight leading-tight">{t.message}</p>
          </div>
        ))}
      </div>

      <nav className="sticky top-0 z-50 glass-nav border-b border-gray-100 px-6 lg:px-12 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('HOME')}>
          <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white text-xl font-black shadow-lg">B</div>
          <h1 className="text-2xl font-black text-red-600 tracking-tighter italic">BFC</h1>
        </div>
        <div className="hidden md:flex gap-10">
          {['HOME', 'MENU', 'VAULT'].map(v => (
            <button key={v} onClick={() => setView(v as any)} className={`text-[10px] font-black uppercase tracking-[3px] transition-all hover:text-red-600 ${view === v ? 'text-red-600' : 'text-gray-400'}`}>{v}</button>
          ))}
        </div>
        <div className="flex items-center gap-4">
          <button onClick={() => setView('CART')} className="relative w-12 h-12 bg-white rounded-2xl border flex items-center justify-center shadow-sm">
            <i className="fas fa-shopping-basket text-gray-700"></i>
            {cart.length > 0 && <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[9px] w-6 h-6 rounded-full flex items-center justify-center font-black">{cart.length}</span>}
          </button>
          {currentUser ? (
            <button onClick={() => setView('PROFILE')} className="w-12 h-12 rounded-2xl bg-gray-950 text-white font-black flex items-center justify-center overflow-hidden border-2 border-white shadow-xl transition-transform active:scale-90">
              {currentUser.profileImage ? <img src={currentUser.profileImage} className="w-full h-full object-cover" alt="Me" /> : currentUser.name.charAt(0)}
            </button>
          ) : (
            <Button size="sm" className="rounded-2xl px-6" onClick={() => setView('LOGIN')}>Initialize</Button>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 py-10 pb-20">
        {view === 'HOME' && (
          <div className="animate-slide-up space-y-16">
            <header className="relative h-[450px] lg:h-[600px] rounded-[50px] overflow-hidden shadow-2xl border-8 border-white group">
               <img src="https://images.unsplash.com/photo-1541140134513-85a161dc4a00?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover" alt="BFC Hero" />
               <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent flex flex-col justify-end p-12 lg:p-20">
                  <h2 className="text-5xl lg:text-8xl font-black text-white leading-[0.85] mb-8 tracking-tighter italic uppercase">DHAKA’S<br/><span className="text-red-600">ELITE FLAVORS</span></h2>
                  <div className="flex gap-4">
                    <Button size="lg" className="rounded-2xl shadow-2xl" onClick={() => setView('MENU')}>Open Vault</Button>
                    <button onClick={() => setView('VAULT')} className="px-8 py-4 bg-white/10 backdrop-blur-md text-white rounded-2xl font-black text-[10px] uppercase tracking-widest border border-white/20">Loyalty Rewards</button>
                  </div>
               </div>
            </header>
            <section>
              <h3 className="text-3xl font-black uppercase italic tracking-tighter mb-10">Daily Specials</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                {menuItems.slice(0, 3).map(item => (
                  <div key={item.id} className="bg-white rounded-[45px] p-6 shadow-sm border border-gray-50">
                     <img src={item.image} className="h-64 w-full rounded-[35px] object-cover mb-6" alt={item.name} />
                     <h4 className="text-2xl font-black mb-2">{item.name}</h4>
                     <p className="text-xs text-gray-400 mb-8">{item.description}</p>
                     <Button fullWidth variant="outline" className="rounded-2xl" onClick={() => addToCart(item)}>Buy ৳{item.price}</Button>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {view === 'VAULT' && (
          <div className="max-w-6xl mx-auto space-y-12 animate-slide-up">
             <div className="bg-gray-950 p-12 rounded-[60px] text-white relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-red-600/20 rounded-full blur-[100px] -mr-32 -mt-32"></div>
                <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-10">
                   <div className="text-center md:text-left">
                      <p className="text-[10px] font-black uppercase tracking-[5px] text-red-500 mb-2">BFC ELITE STATUS</p>
                      <h3 className="text-5xl font-black italic tracking-tighter leading-none mb-4">THE REWARDS VAULT</h3>
                      <p className="text-gray-400 text-sm font-bold">Earn points on every mission. Unlock legendary perks.</p>
                   </div>
                   <div className="bg-white/5 backdrop-blur-xl p-10 rounded-[45px] border border-white/10 text-center min-w-[250px]">
                      <p className="text-[9px] font-black uppercase tracking-widest text-gray-500 mb-2">Current Balance</p>
