                              <th className="p-6 sm:p-10">Severity</th>
                              <th className="p-6 sm:p-10 text-right">Time Sync</th>
                           </tr>
                        </thead>
                        <tbody className="text-[9px] sm:text-[11px] font-bold text-gray-700 dark:text-gray-300 divide-y divide-gray-50 dark:divide-gray-800">
                           {filteredAuditLogs.map((log) => (
                             <tr key={log.id} className="hover:bg-gray-50/50 dark:hover:bg-gray-800/50 transition-colors">
                                <td className="p-6 sm:p-10 font-black uppercase tracking-tighter text-red-600">#{log.id.slice(-5)}</td>
                                <td className="p-6 sm:p-10 flex items-center gap-3 truncate">
                                   <div className="w-6 h-6 sm:w-8 sm:h-8 bg-gray-950 text-white rounded-lg flex items-center justify-center font-black text-[7px] sm:text-[8px] uppercase shrink-0">{log.userName.charAt(0)}</div>
                                   <span className="font-black truncate max-w-[100px]">{log.userName}</span>
                                </td>
                                <td className="p-6 sm:p-10 font-black italic truncate">{log.action}</td>
                                <td className="p-6 sm:p-10 truncate max-w-[200px] text-gray-500 dark:text-gray-400">{log.details}</td>
                                <td className="p-6 sm:p-10">
                                   <span className={`px-2 sm:px-4 py-1 rounded-lg sm:rounded-xl text-[7px] sm:text-[8px] font-black uppercase tracking-widest border ${
                                     log.level === 'CRITICAL' ? 'bg-red-600 text-white border-red-700' :
                                     log.level === 'WARNING' ? 'bg-amber-100 text-amber-700 border-amber-200' :
                                     'bg-gray-100 text-gray-500 border-gray-200'
                                   }`}>
                                     {log.level}
                                   </span>
                                </td>
                                <td className="p-6 sm:p-10 text-right font-mono text-[8px] sm:text-[9px] text-gray-400 whitespace-nowrap">
                                  {new Date(log.timestamp).toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' })}
                                </td>
                             </tr>
                           ))}
                        </tbody>
                      </table>
                    )}
                 </div>
              </div>
            </div>
          )}
        </div>
      </main>
      <ChatBot isOnline={true} />
    </div>
  );
};

const StatCard = ({ title, value, icon, color }: any) => (
  <div className="bg-white dark:bg-gray-900 p-6 sm:p-10 rounded-[30px] sm:rounded-[45px] border dark:border-gray-800 flex items-center gap-4 sm:gap-8 hover:shadow-2xl transition-all group overflow-hidden h-full">
    <div className={`w-12 h-12 sm:w-16 sm:h-16 bg-gray-50 dark:bg-gray-800 rounded-2xl sm:rounded-[28px] flex items-center justify-center text-lg sm:text-2xl ${color} shrink-0 group-hover:scale-110 transition-transform shadow-sm`}>
      <i className={`fas ${icon}`}></i>
    </div>
    <div className="min-w-0">
      <p className="text-[7px] sm:text-[10px] font-black text-gray-400 uppercase tracking-[2px] sm:tracking-[4px] mb-1 sm:mb-2 truncate leading-none">{title}</p>
      <h4 className="text-xl sm:text-3xl font-black text-gray-950 dark:text-white tracking-tighter truncate leading-tight italic">{value}</h4>
    </div>
  </div>
);

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User, AuditLog } from './types';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 }, { name: 'Sun', sales: 3800 }, { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 }, { name: 'Wed', sales: 6200 }, { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

const MOCK_ADMIN_USERS: User[] = [
  { id: 'U-001', name: 'Rahim Ahmed', email: 'rahim@node.com', role: UserRole.CUSTOMER, phone: '01711111111', loyaltyPoints: 450, tier: 'GOLD', wishlist: [], referralCode: 'BFC-RAHIM' },
  { id: 'U-002', name: 'Karim Ullah', email: 'karim@hub.com', role: UserRole.MANAGER, phone: '01822222222', loyaltyPoints: 1200, tier: 'PLATINUM', wishlist: [], referralCode: 'BFC-KARIM' },
  { id: 'U-003', name: 'Sadia Islam', email: 'sadia@sector.com', role: UserRole.CUSTOMER, phone: '01933333333', loyaltyPoints: 85, tier: 'SILVER', wishlist: [], referralCode: 'BFC-SADIA' },
  { id: 'U-004', name: 'Tanvir Hossain', email: 'tanvir@admin.com', role: UserRole.ADMIN, phone: '01644444444', loyaltyPoints: 5000, tier: 'PLATINUM', wishlist: [], referralCode: 'BFC-BOSS' },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, onLogout, menuItems, setMenuItems, orders, setOrders 
}) => {
  const allowedTabs = useMemo(() => {
    if (userRole === UserRole.ADMIN) return ['dashboard', 'orders', 'menu-stock', 'users', 'reports', 'audit'];
    if (userRole === UserRole.MANAGER) return ['dashboard', 'orders', 'menu-stock'];
    return ['orders'];
  }, [userRole]);

  const [activeTab, setActiveTab] = useState(allowedTabs[0]);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [adminToast, setAdminToast] = useState<{msg: string, type: string} | null>(null);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);

  // Tab-specific search states
  const [userSearch, setUserSearch] = useState('');
  const [userRoleFilter, setUserRoleFilter] = useState<'ALL' | UserRole>('ALL');
  const [menuStockSearch, setMenuStockSearch] = useState('');

  // Reports sub-tab state
  const [reportType, setReportType] = useState<'sales' | 'inventory' | 'customers'>('sales');

  // Audit Log state
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([
    { id: 'LOG-001', userId: 'A-001', userName: 'Super Admin', action: 'SYSTEM_START', details: 'BFC Mainframe initialized in Gulshan Sector.', timestamp: new Date(Date.now() - 86400000).toISOString(), level: 'INFO' },
    { id: 'LOG-002', userId: 'A-001', userName: 'Super Admin', action: 'SECURITY_PATCH', details: 'Firewall protocols updated to v5.2.', timestamp: new Date(Date.now() - 43200000).toISOString(), level: 'WARNING' },
  ]);
  const [auditSearch, setAuditSearch] = useState('');
  const [auditLevelFilter, setAuditLevelFilter] = useState<'ALL' | 'INFO' | 'WARNING' | 'CRITICAL'>('ALL');

  const showToast = useCallback((msg: string, type: string) => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const addAuditLog = useCallback((action: string, details: string, level: AuditLog['level'] = 'INFO') => {
    const newLog: AuditLog = {
      id: `LOG-${Math.random().toString(36).slice(2, 7).toUpperCase()}`,
      userId: 'ADMIN-01',
      userName: userRole === UserRole.ADMIN ? 'Head Admin' : 'Node Manager',
      action,
      details,
      timestamp: new Date().toISOString(),
      level
    };
    setAuditLogs(prev => [newLog, ...prev]);
  }, [userRole]);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    try {
      const oldStatus = orders.find(o => o.id === orderId)?.status;
      setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
      showToast(`Order #${orderId.slice(-4)} updated to ${newStatus}.`, "success");
      addAuditLog('ORDER_STATUS_UPDATE', `Order #${orderId} changed from ${oldStatus} to ${newStatus}.`, 'INFO');
    } catch (e) {
      showToast("Could not update order status.", "error");
    }
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) {
          showToast(`Invalid action: Stock for ${item.name} cannot be less than zero.`, "error");
          addAuditLog('INVALID_STOCK_ADJUSTMENT', `Attempted to set stock for ${item.name} below zero.`, 'WARNING');
          return item;
        }
        showToast(`Stock for ${item.name} updated to ${newStock}.`, "success");
        addAuditLog('STOCK_UPDATE', `Stock for ${item.name} adjusted to ${newStock}.`, newStock < 5 ? 'WARNING' : 'INFO');
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  // Robust filtering with null-checks
  const filteredMenuItems = useMemo(() => {
    if (!menuItems) return [];
    const query = menuStockSearch.toLowerCase().trim();
    if (!query) return menuItems;

    return menuItems.filter(item => {
      const nameMatch = item.name?.toLowerCase().includes(query);
      const bnMatch = item.nameBn?.includes(query);
      const catMatch = item.category?.toLowerCase().includes(query);
      return nameMatch || bnMatch || catMatch;
    });
  }, [menuItems, menuStockSearch]);

  const customerBehaviorData = useMemo(() => {
    const customerMap: Record<string, { name: string, totalOrders: number, totalSpend: number, lastOrder: string }> = {};
    orders.forEach(o => {
      if (!customerMap[o.customerId]) {
        customerMap[o.customerId] = { name: o.customerName, totalOrders: 0, totalSpend: 0, lastOrder: o.createdAt };
      }
      customerMap[o.customerId].totalOrders += 1;
      customerMap[o.customerId].totalSpend += o.total;
      if (new Date(o.createdAt) > new Date(customerMap[o.customerId].lastOrder)) {
        customerMap[o.customerId].lastOrder = o.createdAt;
      }
    });
    return Object.values(customerMap).sort((a, b) => b.totalSpend - a.totalSpend);
  }, [orders]);

  const filteredUsers = useMemo(() => {
    return MOCK_ADMIN_USERS.filter(user => {
      const matchesSearch = user.name.toLowerCase().includes(userSearch.toLowerCase()) || 
                            user.email.toLowerCase().includes(userSearch.toLowerCase()) ||
                            user.phone.includes(userSearch);
      const matchesRole = userRoleFilter === 'ALL' || user.role === userRoleFilter;
      return matchesSearch && matchesRole;
    });
  }, [userSearch, userRoleFilter]);

  const filteredAuditLogs = useMemo(() => {
    return auditLogs.filter(log => {
      const matchesSearch = log.action.toLowerCase().includes(auditSearch.toLowerCase()) || 
                            log.userName.toLowerCase().includes(auditSearch.toLowerCase()) ||
                            log.details.toLowerCase().includes(auditSearch.toLowerCase());
      const matchesLevel = auditLevelFilter === 'ALL' || log.level === auditLevelFilter;
      return matchesSearch && matchesLevel;
    });
  }, [auditLogs, auditSearch, auditLevelFilter]);

  const reportMetrics = useMemo(() => {
    if (reportType === 'sales') {
      const totalRevenue = orders.reduce((a, b) => a + b.total, 0);
      const avgOrder = orders.length ? (totalRevenue / orders.length).toFixed(0) : 0;
      return [
        { label: 'Total Node Revenue', value: `৳${totalRevenue.toLocaleString()}`, icon: 'fa-vault' },
        { label: 'Avg Mission Value', value: `৳${avgOrder}`, icon: 'fa-scale-balanced' },
        { label: 'Conversion Rate', value: '12.4%', icon: 'fa-arrow-trend-up' }
      ];
    } else if (reportType === 'inventory') {
      const totalValuation = menuItems.reduce((a, b) => a + (b.price * b.stock), 0);
      const lowStockCount = menuItems.filter(m => m.stock < 10).length;
      return [
        { label: 'Stock Valuation', value: `৳${totalValuation.toLocaleString()}`, icon: 'fa-sack-dollar' },
        { label: 'Critical Nodes', value: lowStockCount, icon: 'fa-triangle-exclamation' },
        { label: 'Storage Capacity', value: '85%', icon: 'fa-warehouse' }
      ];
    } else { // customers
      const totalSpenders = customerBehaviorData.length;
      const avgLTV = totalSpenders ? (orders.reduce((a, b) => a + b.total, 0) / totalSpenders).toFixed(0) : 0;
      return [
        { label: 'Registered Spenders', value: totalSpenders, icon: 'fa-users-gear' },
        { label: 'Lifetime Value (Avg)', value: `৳${avgLTV}`, icon: 'fa-gem' },
        { label: 'Retention Logic', value: 'High', icon: 'fa-link' }
      ];
    }
  }, [reportType, orders, menuItems, customerBehaviorData]);

  const handleExportExcel = () => {
    try {
      let data: any[] = [];
      let filename = `BFC_Report_${reportType}_${new Date().toISOString().split('T')[0]}.xlsx`;
      if (reportType === 'sales') {
        data = orders.map(o => ({ 
          'Order ID': o.id, 'Customer': o.customerName, 'Total (৳)': o.total, 'Status': o.status, 'Payment': o.paymentMethod, 'Date': new Date(o.createdAt).toLocaleDateString() 
        }));
      } else if (reportType === 'inventory') {
        data = menuItems.map(m => ({ 
          'Item ID': m.id, 'Name': m.name, 'Category': m.category, 'Price (৳)': m.price, 'Stock': m.stock, 'Status': m.stock < 10 ? 'LOW' : 'STABLE' 
        }));
      } else if (reportType === 'customers') {
        data = customerBehaviorData.map(c => ({ 
          'Customer Name': c.name, 'Total Orders': c.totalOrders, 'Total Spend (৳)': c.totalSpend, 'Avg Order Value (৳)': (c.totalSpend / c.totalOrders).toFixed(2), 'Last Active': new Date(c.lastOrder).toLocaleDateString()
        }));
      }
      if (data.length === 0) {
        showToast(`Export failed: No data available.`, "warning");
        return;
      }
      const worksheet = XLSX.utils.json_to_sheet(data);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Report");
      XLSX.writeFile(workbook, filename);
      showToast(`Excel generated.`, 'success');
      addAuditLog('REPORT_EXPORT_EXCEL', `Generated Excel report for ${reportType}.`, 'INFO');
    } catch (err) {
      showToast("Unable to generate Excel file.", "error");
    }
  };

  const handleExportPDF = () => {
    try {
      const doc = new jsPDF();
      doc.setFontSize(18);
      doc.text(`BFC Hub: ${reportType.toUpperCase()} Report`, 14, 20);
      doc.setFontSize(10);
      doc.text(`Generated on: ${new Date().toLocaleString()}`, 14, 28);
      let head: any[][] = [];
      let body: any[][] = [];
      if (reportType === 'sales') {
        head = [['Order ID', 'Customer', 'Total', 'Status', 'Date']];
        body = orders.map(o => [o.id, o.customerName, `৳${o.total}`, o.status, new Date(o.createdAt).toLocaleDateString()]);
      } else if (reportType === 'inventory') {
        head = [['ID', 'Name', 'Category', 'Price', 'Stock']];
        body = menuItems.map(m => [m.id, m.name, m.category, `৳${m.price}`, m.stock]);
      } else if (reportType === 'customers') {
        head = [['Customer', 'Orders', 'Total Spend', 'Avg Order', 'Last Active']];
        body = customerBehaviorData.map(c => [
          c.name, c.totalOrders, `৳${c.totalSpend}`, `৳${(c.totalSpend/c.totalOrders).toFixed(0)}`, new Date(c.lastOrder).toLocaleDateString()
        ]);
      }
      if (body.length === 0) {
        showToast(`Nothing to export.`, "warning");
        return;
      }
      autoTable(doc, {
        head,
        body,
        startY: 35,
        theme: 'striped',
        headStyles: { fillColor: [220, 38, 38], textColor: [255, 255, 255], fontStyle: 'bold' }
      });
      doc.save(`BFC_Report_${reportType}.pdf`);
      showToast(`PDF successfully exported.`, 'success');
      addAuditLog('REPORT_EXPORT_PDF', `Generated PDF report for ${reportType}.`, 'INFO');
    } catch (err) {
      showToast("PDF generation encountered an error.", "error");
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] dark:bg-gray-950 overflow-hidden font-sans">
      {/* Admin Notifications */}
      {adminToast && (
        <div className={`fixed top-4 sm:top-8 left-1/2 -translate-x-1/2 z-[7000] px-4 sm:px-8 py-3 sm:py-4 rounded-2xl sm:rounded-3xl shadow-2xl flex items-center gap-3 sm:gap-4 animate-slide-up border w-[90%] sm:w-auto ${
          adminToast.type === 'error' ? 'bg-red-600 text-white border-red-400' : 
          adminToast.type === 'warning' ? 'bg-amber-500 text-white border-amber-400' :
          'bg-gray-950 text-white border-white/10'
        }`}>
           <i className={`fas ${adminToast.type === 'error' ? 'fa-circle-xmark' : adminToast.type === 'warning' ? 'fa-triangle-exclamation' : 'fa-terminal'} text-[10px]`}></i>
           <span className="text-[9px] sm:text-[10px] font-black uppercase tracking-[2px] sm:tracking-[3px] truncate">{adminToast.msg}</span>
        </div>
      )}

      {/* Logout Confirmation Modal */}
      {showLogoutConfirm && (
        <div className="fixed inset-0 z-[8000] flex items-center justify-center p-6 bg-gray-900/60 backdrop-blur-md animate-fade-in">
          <div className="bg-white dark:bg-gray-900 w-full max-w-sm rounded-[40px] p-10 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.5)] border dark:border-gray-800 animate-slide-up text-center">
             <div className="w-20 h-20 bg-red-50 dark:bg-red-950/20 rounded-3xl flex items-center justify-center text-red-600 text-2xl mx-auto mb-8 shadow-xl">
                <i className="fas fa-right-from-bracket"></i>
             </div>
             <h3 className="text-2xl font-black uppercase italic tracking-tighter mb-4">Terminate Session?</h3>
             <p className="text-[11px] font-bold text-gray-500 uppercase tracking-widest leading-relaxed mb-10">Confirm you want to exit the BFC HUB terminal. All active background tasks will continue.</p>
             <div className="flex flex-col gap-3">
                <button 
                  onClick={onLogout}
                  className="w-full py-5 bg-red-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-[4px] shadow-2xl shadow-red-600/20 active:scale-95 transition-all"
                >
                  Terminate Session
                </button>
                <button 
                  onClick={() => setShowLogoutConfirm(false)}
                  className="w-full py-5 bg-gray-50 dark:bg-gray-800 text-gray-500 dark:text-gray-400 rounded-2xl font-black text-[10px] uppercase tracking-[4px] hover:text-gray-900 dark:hover:text-white transition-all"
                >
                  Return to Dashboard
                </button>
             </div>
          </div>
        </div>
      )}

      {/* Sidebar Backdrop Mobile */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-gray-900/60 backdrop-blur-sm z-[240] lg:hidden transition-opacity duration-300"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar Navigation */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[250] w-64 sm:w-72 bg-white dark:bg-gray-900 border-r dark:border-gray-800 transition-transform duration-500 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0 shadow-2xl lg:shadow-none'}`}>
        <div className="p-6 sm:p-10 border-b dark:border-gray-800 flex items-center justify-between">
          <div className="flex items-center gap-3 sm:gap-4">
            <div className="w-8 h-8 sm:w-10 sm:h-10 bg-red-600 rounded-xl sm:rounded-2xl flex items-center justify-center text-white font-black shadow-xl shadow-red-600/20">B</div>
            <h1 className="text-xl sm:text-2xl font-black text-red-600 tracking-tighter italic">BFC HUB</h1>
          </div>
          <button className="lg:hidden w-8 h-8 sm:w-10 sm:h-10 bg-gray-50 dark:bg-gray-800 rounded-xl flex items-center justify-center text-gray-400" onClick={() => setSidebarOpen(false)}>
            <i className="fas fa-times text-xs"></i>
          </button>
        </div>
        <nav className="p-4 sm:p-8 space-y-2 overflow-y-auto max-h-[calc(100vh-140px)] scrollbar-hide">
          {allowedTabs.map(tab => (
            <button key={tab} onClick={() => { setActiveTab(tab); setSidebarOpen(false); }} className={`w-full flex items-center gap-3 sm:gap-5 px-4 sm:px-6 py-4 sm:py-5 rounded-[20px] sm:rounded-[24px] transition-all group ${activeTab === tab ? 'bg-red-600 text-white shadow-xl sm:shadow-2xl shadow-red-600/30' : 'text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800'}`}>
              <i className={`fas ${
                tab === 'dashboard' ? 'fa-chart-line' : 
                tab === 'orders' ? 'fa-list-check' : 
                tab === 'menu-stock' ? 'fa-bowl-food' : 
                tab === 'users' ? 'fa-users' :
                tab === 'reports' ? 'fa-file-invoice' : 
                'fa-shield-halved'
              } text-[10px] sm:text-sm group-hover:scale-110 transition-transform`}></i> 
              <span className="uppercase text-[8px] sm:text-[10px] font-black tracking-[2px] sm:tracking-[4px]">{tab.replace('-', ' ')}</span>
            </button>
          ))}
          <div className="pt-8 sm:pt-12">
            <button 
              onClick={() => setShowLogoutConfirm(true)}
              className="w-full py-4 sm:py-5 text-red-600 font-black uppercase tracking-[3px] sm:tracking-[5px] text-[8px] sm:text-[9px] border-2 border-red-50 dark:border-red-900/10 rounded-[20px] sm:rounded-[28px] hover:bg-red-600 hover:text-white transition-all shadow-sm"
            >
              Logout Terminal
            </button>
          </div>
        </nav>
      </aside>

      {/* Admin Content Area */}
      <main className="flex-1 overflow-y-auto bg-[#F8FAFC] dark:bg-gray-950 flex flex-col scrollbar-hide">
        <header className="sticky top-0 z-40 bg-white/90 dark:bg-gray-900/90 backdrop-blur-xl border-b dark:border-gray-800 px-4 sm:px-10 py-4 sm:py-6 flex items-center justify-between">
           <div className="flex items-center gap-4 sm:gap-6 overflow-hidden">
             <button className="lg:hidden w-10 h-10 sm:w-12 sm:h-12 bg-gray-50 dark:bg-gray-800 rounded-xl sm:rounded-2xl flex items-center justify-center text-gray-600 dark:text-gray-400 shrink-0" onClick={() => setSidebarOpen(true)}>
               <i className="fas fa-bars text-xs sm:text-base"></i>
             </button>
             <div className="truncate">
               <h2 className="text-xl sm:text-3xl font-black uppercase italic tracking-tighter leading-none truncate">{activeTab.replace('-', ' ')} Interface</h2>
               <p className="text-[7px] sm:text-[9px] font-black text-gray-400 uppercase tracking-[2px] sm:tracking-[4px] mt-1 sm:mt-2 truncate">Authority: {userRole}</p>
             </div>
           </div>
           <div className="w-10 h-10 sm:w-12 sm:h-12 bg-gray-950 text-white rounded-xl sm:rounded-2xl flex items-center justify-center font-black text-[10px] sm:text-sm shadow-2xl border-2 border-white/5 uppercase shrink-0 ml-2">
             {userRole.charAt(0)}
           </div>
        </header>

        <div className="p-4 sm:p-10 space-y-8 sm:space-y-12 max-w-[1600px] mx-auto w-full">
          {activeTab === 'dashboard' && (
            <div className="animate-slide-up space-y-8 sm:space-y-12">
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 sm:gap-8">
                <StatCard title="Revenue Stream" value={`৳${orders.reduce((a,b)=>a+b.total, 0).toLocaleString()}`} icon="fa-taka-sign" color="text-red-600" />
                <StatCard title="Missions" value={orders.length} icon="fa-rocket" color="text-blue-600" />
                <StatCard title="Nodes" value={menuItems.length} icon="fa-bowl-rice" color="text-amber-500" />
