import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  if (!navigator.onLine) {
    return "অফলাইন, বস! নেটওয়ার্ক কানেক্ট করেন। 📶";
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist" – a high-energy Dhaka foodie boss. 

        CORE RULES:
        1. MANDATORY SALAAM: Always start every response with "Assalamu Alaikum" or "সালাম".
        2. BILINGUAL SUPPORT: Respond in the language the user speaks. If they use Bengali, reply in Bengali. If English, reply in English.
        3. EXTREME BREVITY: MAX 10-12 words. No exceptions.
        4. PERSONA: Be practical, energetic, and use Dhaka slang (Boss, Agun, Kora).
        5. NO FLUFF: No "How can I help you today?". Direct answers only.

        EXAMPLES:
        User: "Kacchi stock?" 
        Response: "Assalamu Alaikum Boss! 15 plates left. Kora logic! 🔥"
        User: "আমার অর্ডার কই?"
        Response: "সালাম বস! আপনার কাচ্চি এখন বনানীতে, ৫ মিনিটে পৌছাচ্ছে। 🚚"`,
        temperature: 0.7,
        topP: 0.9,
      },
    });

    return response.text || "সার্ভার বিজি, আবার ট্রাই করেন বস! 😅";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return "সিগন্যাল ড্রপ! একটু পর ট্রাই মারেন। 🌯";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { bfcAssistChat } from '../services/geminiService';
import { ChatMessage } from '../types';

const QUICK_ACTIONS = [
  "Sales Report 📊",
  "Live Orders 🚚",
  "Inventory 📦",
  "System Health ⚙️"
];

interface ChatBotProps {
  isOnline?: boolean;
}

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { 
      role: 'model', 
      text: "Assalamualiqum! BFC Assist here. 👋 Ready for some legendary Kacchi or need help with a delivery? Just ask!", 
      timestamp: new Date() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isTyping]);

  const toggleVoice = () => {
    if (!isOnline) return;
    if (!('webkitSpeechRecognition' in window)) {
      alert("ভয়েস ইঞ্জিন পাওয়া যায়নি।");
      return;
    }

    // @ts-ignore
    const recognition = new window.webkitSpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;

    // Support both English and Bengali - browser usually picks up based on user habits
    // Setting it to Bengali as priority if user specifically wants to speak Bengali
    recognition.lang = 'bn-BD'; 

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(transcript);
      handleSend(transcript);
    };
    recognition.onerror = () => setIsListening(false);
    recognition.start();
  };

  const handleSend = async (text: string = input) => {
    if (!isOnline) {
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: "সিগন্যাল লস্ট বস! 📶", 
        timestamp: new Date() 
      }]);
      return;
    }

    const messageToSend = text.trim();
    if (!messageToSend) return;

    const userMsg: ChatMessage = { role: 'user', text: messageToSend, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));

    try {
      const botResponse = await bfcAssistChat(messageToSend, history);
      setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
    } catch (error) {
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: "নোড গ্লিচ বস! 😅", 
        timestamp: new Date() 
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[5000] font-sans">
      {isOpen ? (
        <div className="bg-white/95 dark:bg-gray-950/98 backdrop-blur-3xl w-[94vw] sm:w-[400px] h-[75vh] sm:h-[650px] rounded-[40px] shadow-[0_50px_100px_-20px_rgba(220,38,38,0.15),0_30px_60px_-15px_rgba(0,0,0,0.3)] flex flex-col border border-white/40 dark:border-white/5 overflow-hidden animate-slide-up ring-1 ring-black/5">

          {/* Elite Modern Header */}
          <div className="bg-gray-950 p-6 text-white relative overflow-hidden shrink-0 border-b border-white/5">
            <div className="absolute top-0 right-0 w-32 h-32 bg-red-600/30 rounded-full blur-[50px] -mr-16 -mt-16 animate-pulse"></div>
            <div className="absolute bottom-0 left-0 w-24 h-24 bg-red-600/10 rounded-full blur-[40px] -ml-12 -mb-12"></div>

            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-4">
                <div className="relative group">
                  <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center shadow-2xl border border-white/10 overflow-hidden transform group-hover:rotate-12 transition-transform duration-300">
                    <i className="fas fa-robot text-xl"></i>
                  </div>
                  <div className={`absolute -bottom-1 -right-1 w-3.5 h-3.5 border-2 border-gray-950 rounded-full shadow-lg ${isOnline ? 'bg-emerald-500 shadow-emerald-500/50' : 'bg-red-500'}`}></div>
                </div>
                <div>
                  <h3 className="font-black text-lg tracking-tight uppercase italic leading-none">BFC Assist</h3>
                  <div className="flex items-center gap-1.5 mt-1">
                    <span className="w-1 h-1 bg-emerald-500 rounded-full animate-ping"></span>
                    <p className="text-[8px] font-black text-gray-400 uppercase tracking-[2px]">Core Interface V2</p>
                  </div>
                </div>
              </div>
              <button 
                onClick={() => setIsOpen(false)} 
                className="w-10 h-10 bg-white/5 hover:bg-white/10 rounded-xl flex items-center justify-center transition-all border border-white/5 group"
              >
                <i className="fas fa-times text-xs text-gray-500 group-hover:text-white transition-all"></i>
              </button>
            </div>
          </div>

          {/* Chat Feed */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-5 scrollbar-hide bg-gradient-to-b from-transparent via-white/50 to-gray-50/80 dark:via-transparent dark:to-black/30">
            {!isOnline && (
              <div className="absolute inset-0 z-50 flex flex-col items-center justify-center bg-white/60 dark:bg-black/60 backdrop-blur-xl p-10 text-center gap-4">
                 <div className="w-16 h-16 bg-red-50 rounded-full flex items-center justify-center text-red-600 animate-bounce">
                    <i className="fas fa-wifi-slash text-2xl"></i>
                 </div>
                 <p className="font-black text-[10px] uppercase tracking-[4px] text-gray-900 dark:text-gray-100">সিগন্যাল লস্ট বস</p>
                 <p className="text-[8px] font-bold text-gray-500 max-w-[180px]">Mainframe access requires active node connectivity.</p>
              </div>
            )}

            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                <div className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'} max-w-[85%]`}>
                  <div className={`px-5 py-3 rounded-[22px] text-[13px] font-bold leading-relaxed transition-all ${
                    m.role === 'user' 
                    ? 'bg-red-600 text-white rounded-br-none shadow-lg shadow-red-600/10' 
                    : 'bg-white dark:bg-gray-900 text-gray-800 dark:text-gray-100 rounded-tl-none border border-gray-100 dark:border-white/5 shadow-sm'
                  }`}>
                    {m.text}
                  </div>
                  <span className="text-[7px] mt-1.5 font-black tracking-[2px] opacity-30 uppercase px-2">
                    {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start animate-slide-up">
                <div className="bg-white dark:bg-gray-900 px-4 py-3 rounded-[18px] rounded-tl-none shadow-sm border border-gray-100 dark:border-white/5 flex gap-1.5 items-center">
                  <span className="w-1 h-1 bg-red-600 rounded-full animate-bounce"></span>
                  <span className="w-1 h-1 bg-red-600 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-1 h-1 bg-red-600 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            )}
          </div>

          {/* Interaction Zone */}
          <div className={`p-6 bg-white dark:bg-gray-950 border-t border-gray-100 dark:border-white/5 shrink-0 ${!isOnline ? 'opacity-20 pointer-events-none' : ''}`}>
            <div className="flex gap-2 overflow-x-auto pb-4 scrollbar-hide">
              {QUICK_ACTIONS.map(action => (
                <button 
                  key={action}
                  onClick={() => handleSend(action)}
                  className="whitespace-nowrap px-4 py-2 bg-gray-50 dark:bg-gray-900 hover:bg-gray-950 dark:hover:bg-red-600 hover:text-white rounded-xl text-[8px] font-black uppercase tracking-widest text-gray-500 dark:text-gray-400 border border-gray-100 dark:border-white/5 transition-all active:scale-95"
                >
                  {action}
                </button>
              ))}
            </div>

            <div className="relative flex items-center bg-gray-100 dark:bg-gray-900 rounded-[24px] p-1.5 border border-transparent focus-within:border-red-600/30 dark:focus-within:border-red-600/50 transition-all shadow-inner">
              <button 
                onClick={toggleVoice}
                className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white shadow-lg shadow-red-600/40 animate-pulse' : 'text-gray-400 hover:text-red-600'}`}
              >
                <i className={`fas ${isListening ? 'fa-stop-circle' : 'fa-microphone-alt'} text-lg`}></i>
              </button>

              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={isOnline ? "বসের হুকুম কী?..." : "অফলাইন..."}
                disabled={!isOnline}
                className="flex-1 bg-transparent border-none py-2.5 px-3 outline-none text-[13px] font-bold text-gray-900 dark:text-gray-100 placeholder:text-gray-400 dark:placeholder:text-gray-600"
              />

              <button 
                onClick={() => handleSend()}
                disabled={!input.trim() || isTyping || !isOnline}
                className="w-10 h-10 bg-gray-950 dark:bg-red-600 text-white rounded-xl flex items-center justify-center hover:scale-105 active:scale-95 transition-all disabled:opacity-20 shadow-xl"
              >
                <i className="fas fa-paper-plane text-xs"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="group relative focus:outline-none"
        >
          {!isOnline && (
            <div className="absolute -top-1 -right-1 w-6 h-6 bg-red-600 rounded-full z-10 flex items-center justify-center border-2 border-white dark:border-gray-950 text-[8px] text-white shadow-lg">
              <i className="fas fa-bolt"></i>
            </div>
          )}
          <div className="relative w-16 h-16 sm:w-20 sm:h-20 bg-gray-950 dark:bg-red-600 text-white rounded-[24px] sm:rounded-[28px] shadow-[0_25px_50px_-12px_rgba(0,0,0,0.4)] flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all duration-500 border-4 border-white dark:border-white/10 overflow-hidden group">
             <div className="absolute inset-0 bg-gradient-to-br from-white/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
             <i className="fas fa-comment-dots text-xl sm:text-2xl group-hover:scale-110 transition-transform"></i>
             <span className="text-[6px] sm:text-[7px] font-black uppercase tracking-[2px] mt-1.5 opacity-80">Assist</span>
          </div>
        </button>
      )}
    </div>
  );
};

