                className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white shadow-lg shadow-red-600/40 animate-pulse' : 'text-gray-400 hover:text-red-600'}`}
              >
                <i className={`fas ${isListening ? 'fa-stop-circle' : 'fa-microphone-alt'} text-lg`}></i>
              </button>

              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={isOnline ? "বসের হুকুম কী?..." : "অফলাইন..."}
                disabled={!isOnline}
