              />

              <button 
                onClick={() => handleSend()}
                disabled={!input.trim() || isTyping || !isOnline}
                className="w-10 h-10 bg-gray-950 dark:bg-red-600 text-white rounded-xl flex items-center justify-center hover:scale-105 active:scale-95 transition-all disabled:opacity-20 shadow-xl"
              >
                <i className="fas fa-paper-plane text-xs"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="group relative focus:outline-none"
        >
          <div className="relative w-16 h-16 sm:w-20 sm:h-20 bg-gray-950 dark:bg-red-600 text-white rounded-[24px] sm:rounded-[28px] shadow-[0_25px_50px_-12px_rgba(0,0,0,0.4)] flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all duration-500 border-4 border-white dark:border-white/10 overflow-hidden group">
             {isSpeaking && <div className="absolute inset-0 bg-red-500/20 animate-pulse"></div>}
             <i className={`fas ${isSpeaking ? 'fa-volume-up animate-bounce' : 'fa-comment-dots'} text-xl sm:text-2xl group-hover:scale-110 transition-transform`}></i>
             <span className="text-[6px] sm:text-[7px] font-black uppercase tracking-[2px] mt-1.5 opacity-80">{isSpeaking ? 'Speaking' : 'Assist'}</span>
          </div>
        </button>
      )}
    </div>
  );
};

