interface ChatBotProps {
  isOnline?: boolean;
}

export const ChatBot: React.FC<ChatBotProps> = ({ isOnline = true }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { 
      role: 'model', 
      text: "Assalamualiqum! BFC Assist here. 👋 Ready for some legendary Kacchi or need help with a delivery? Just ask!", 
      timestamp: new Date() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isHandsFree, setIsHandsFree] = useState(false); // Gemini Live Mode

  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);

  // Initialize AudioContext on first interaction
  const initAudio = async () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (audioContextRef.current.state === 'suspended') {
      await audioContextRef.current.resume();
    }
  };

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isTyping]);

  // The Loop: Auto-listen after speaking finishes
  const speakText = async (text: string) => {
    if (!text) return;

    await initAudio();
    setIsSpeaking(true);

    try {
      const base64Audio = await generateSpeech(text);
      if (base64Audio && audioContextRef.current) {
        const ctx = audioContextRef.current;
        const audioData = decodeBase64(base64Audio);
        const audioBuffer = await decodeAudioData(audioData, ctx, 24000, 1);

        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);

        source.onended = () => {
          setIsSpeaking(false);
          // If in hands-free mode, start listening again automatically after a small delay
          if (isHandsFree) {
            setTimeout(() => startListening(), 500);
          }
        };

        source.start();
      } else {
        setIsSpeaking(false);
        if (isHandsFree) startListening();
      }
    } catch (err) {
      console.error("Speech Error:", err);
      setIsSpeaking(false);
      if (isHandsFree) startListening();
    }
  };

  const startListening = () => {
    if (!isOnline || isSpeaking) return;

    if (!('webkitSpeechRecognition' in window)) {
      alert("ভয়েস ইঞ্জিন পাওয়া যায়নি।");
      return;
    }

    if (!recognitionRef.current) {
      // @ts-ignore
      const recognition = new window.webkitSpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.lang = 'bn-BD'; // Support Bengali as priority

      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInput(transcript);
        handleSend(transcript);
      };
      recognition.onerror = () => setIsListening(false);
      recognitionRef.current = recognition;
    }

    try {
      recognitionRef.current.start();
    } catch (e) {
      console.log("Recognition already started");
    }
  };

  const toggleHandsFree = () => {
    initAudio();
    const newMode = !isHandsFree;
    setIsHandsFree(newMode);
    if (newMode && !isListening && !isSpeaking) {
      startListening();
    }
  };

  const handleSend = async (text: string = input) => {
    if (!isOnline) return;

    const messageToSend = text.trim();
    if (!messageToSend) return;

    const userMsg: ChatMessage = { role: 'user', text: messageToSend, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const history = messages.map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));

    try {
      const botResponse = await bfcAssistChat(messageToSend, history);
      setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
      speakText(botResponse);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "নোড গ্লিচ বস! 😅", timestamp: new Date() }]);
      if (isHandsFree) startListening();
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[5000] font-sans">
      {isOpen ? (
        <div className="bg-white/95 dark:bg-gray-950/98 backdrop-blur-3xl w-[94vw] sm:w-[400px] h-[75vh] sm:h-[650px] rounded-[40px] shadow-[0_50px_100px_-20px_rgba(220,38,38,0.15),0_30px_60px_-15px_rgba(0,0,0,0.3)] flex flex-col border border-white/40 dark:border-white/5 overflow-hidden animate-slide-up ring-1 ring-black/5">

          {/* Header with Live Status & Soundwave */}
          <div className="bg-gray-950 p-6 text-white relative overflow-hidden shrink-0 border-b border-white/5">
            <div className={`absolute top-0 right-0 w-32 h-32 rounded-full blur-[50px] -mr-16 -mt-16 transition-all duration-1000 ${isSpeaking || isListening ? 'bg-red-600/40 animate-pulse' : 'bg-red-600/20'}`}></div>

            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-4">
                <div className="relative">
                  <div className={`w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center shadow-2xl border border-white/10 transition-all duration-500 ${isSpeaking ? 'scale-110 rotate-12 shadow-red-600/50' : ''}`}>
                    <i className={`fas ${isSpeaking ? 'fa-waveform-lines animate-pulse' : isListening ? 'fa-microphone-lines animate-pulse' : 'fa-robot'} text-xl`}></i>
                  </div>
                  <div className={`absolute -bottom-1 -right-1 w-3.5 h-3.5 border-2 border-gray-950 rounded-full ${isOnline ? 'bg-emerald-500' : 'bg-red-500'}`}></div>
                </div>
                <div>
                  <h3 className="font-black text-lg tracking-tight uppercase italic leading-none">BFC Assist</h3>
