import { GoogleGenAI, Modality } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  if (!navigator.onLine) {
    return "অফলাইন, বস! নেটওয়ার্ক কানেক্ট করেন। 📶";
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist" – a high-energy Dhaka foodie boss. 

        CORE RULES:
        1. MANDATORY SALAAM: Always start every response with "Assalamu Alaikum" or "সালাম".
        2. BILINGUAL SUPPORT: Respond in the language the user speaks. If they use Bengali, reply in Bengali. If English, reply in English.
        3. EXTREME BREVITY: MAX 8-10 words. Extremely short and punchy.
        4. PERSONA: Be practical, high-energy, and use Dhaka slang (Boss, Agun, Kora, Mama).
        5. NO FLUFF: Direct answers only. NO "How can I help?".

        EXAMPLES:
        User: "Kacchi stock?" 
        Response: "সালাম বস! ১৫ প্লেট আছে। আগুন কাচ্চি! 🔥"
        User: "Where is my order?"
        Response: "Assalamu Alaikum Boss! Rider at Banani. 2 minutes only. 🚚"`,
        temperature: 0.8,
        topP: 0.95,
      },
    });

    return response.text || "সার্ভার বিজি, আবার ট্রাই করেন বস! 😅";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return "সিগন্যাল ড্রপ! একটু পর ট্রাই মারেন। 🌯";
  }
};

export const generateSpeech = async (text: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, // Kore is energetic
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    return base64Audio;
  } catch (error) {
    console.error("Speech Gen Error:", error);
    return null;
  }
};

