    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[5000] font-sans">
      {isOpen ? (
        <div className="bg-white/95 dark:bg-gray-950/98 backdrop-blur-3xl w-[94vw] sm:w-[420px] h-[80vh] sm:h-[680px] rounded-[48px] shadow-[0_50px_100px_-20px_rgba(220,38,38,0.25)] flex flex-col border border-white/40 dark:border-white/5 overflow-hidden animate-slide-up ring-1 ring-black/5">

          {/* Live Interface Header */}
          <div className="bg-gray-950 p-7 text-white relative overflow-hidden shrink-0">
            <div className={`absolute inset-0 bg-gradient-to-br from-red-600/20 to-transparent transition-opacity duration-1000 ${isSpeaking || isListening ? 'opacity-100' : 'opacity-30'}`}></div>
            <div className={`absolute top-0 right-0 w-40 h-40 bg-red-600/30 rounded-full blur-[60px] -mr-20 -mt-20 transition-all duration-700 ${isSpeaking ? 'scale-150 opacity-60' : 'scale-100 opacity-20'}`}></div>

            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-4">
                <div className="relative">
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center border border-white/10 transition-all duration-500 shadow-2xl ${isSpeaking ? 'bg-red-600 scale-110 rotate-6' : isListening ? 'bg-emerald-600 scale-105' : 'bg-gray-800'}`}>
                    <i className={`fas ${isSpeaking ? 'fa-waveform-lines animate-pulse' : isListening ? 'fa-microphone-lines animate-bounce' : 'fa-robot'} text-2xl`}></i>
                  </div>
                  <div className={`absolute -bottom-1 -right-1 w-4 h-4 border-2 border-gray-950 rounded-full ${isOnline ? 'bg-emerald-500 shadow-emerald-500/50' : 'bg-red-500'}`}></div>
                </div>
                <div>
                  <h3 className="font-black text-xl tracking-tighter uppercase italic leading-none">BFC BOSS LIVE</h3>
                  <p className="text-[9px] font-black text-gray-500 uppercase tracking-[3px] mt-1.5 flex items-center gap-2">
                    {isSpeaking ? <span className="text-red-500 animate-pulse">● Speaking</span> : isListening ? <span className="text-emerald-500 animate-pulse">● Listening</span> : <span className="opacity-50 italic">Ready for hookum</span>}
                  </p>
                </div>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={toggleLiveMode}
                  className={`w-11 h-11 rounded-2xl flex items-center justify-center transition-all border ${isLiveMode ? 'bg-red-600 border-red-500 shadow-lg shadow-red-600/30 text-white' : 'bg-white/5 border-white/10 text-gray-500 hover:text-white'}`}
                  title="Toggle Live Hands-free Mode"
                >
                  <i className={`fas ${isLiveMode ? 'fa-headset' : 'fa-microphone-slash'} text-sm`}></i>
                </button>
                <button onClick={() => setIsOpen(false)} className="w-11 h-11 bg-white/5 hover:bg-white/10 rounded-2xl flex items-center justify-center border border-white/10 group">
