                      animationDelay: `${i * 0.04}s`
                    }}
                  ></div>
                ))}
              </div>
            )}
          </div>

          {/* Chat Interface */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-7 space-y-6 scrollbar-hide bg-gray-50/30 dark:bg-transparent">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                <div className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'} max-w-[85%]`}>
