                    m.role === 'user' 
                    ? 'bg-red-600 text-white rounded-br-none border-red-500 shadow-red-600/10' 
                    : 'bg-white dark:bg-gray-900 text-gray-800 dark:text-gray-100 rounded-tl-none border-gray-100 dark:border-white/5'
