import React, { useState, useRef, useEffect, useCallback } from 'react';
import { bfcAssistChat, generateSpeech } from '../services/geminiService';
import { ChatMessage } from '../types';

const QUICK_ACTIONS = [
  "Sales Report 📊",
  "Live Orders 🚚",
  "Inventory 📦"
];

// Audio utilities for high-performance Raw PCM decoding
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const buffer = ctx.createBuffer(1, dataInt16.length, sampleRate);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) {
    channelData[i] = dataInt16[i] / 32768.0;
  }
  return buffer;
}

export const ChatBot: React.FC<{ isOnline?: boolean }> = ({ isOnline = true }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: "সালাম বস! বিএফসি অ্যাসিস্ট রেডি। কী হুকুম?", timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLiveMode, setIsLiveMode] = useState(false); // Hands-free toggle

  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);
  const currentSpeechSource = useRef<AudioBufferSourceNode | null>(null);

  // Initialize Audio Engine
  const initAudio = useCallback(async () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (audioContextRef.current.state === 'suspended') {
      await audioContextRef.current.resume();
    }
    return audioContextRef.current;
  }, []);

  // Automatic Speech Execution
  const speakText = async (text: string) => {
    if (!text) return;

    const ctx = await initAudio();
    setIsSpeaking(true);

    // Stop any currently playing audio before starting new one
    if (currentSpeechSource.current) {
      try { currentSpeechSource.current.stop(); } catch(e) {}
    }

    try {
      const base64Audio = await generateSpeech(text);
      if (base64Audio) {
        const audioData = decodeBase64(base64Audio);
        const audioBuffer = await decodeAudioData(audioData, ctx, 24000);

        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        currentSpeechSource.current = source;

        source.onended = () => {
          setIsSpeaking(false);
          currentSpeechSource.current = null;
          // IMPORTANT: If in Live Mode, start listening again automatically after speaking
          if (isLiveMode && isOpen) {
            setTimeout(() => startListening(), 400);
          }
        };

        source.start(0);
      } else {
        setIsSpeaking(false);
        if (isLiveMode && isOpen) startListening();
      }
    } catch (err) {
      console.error("Speech Error:", err);
      setIsSpeaking(false);
      if (isLiveMode && isOpen) startListening();
    }
  };

  const startListening = () => {
    if (!isOnline || isSpeaking) return;

    if (!('webkitSpeechRecognition' in window)) {
      alert("ভয়েস ইঞ্জিন পাওয়া যায়নি বস!");
      return;
    }

    if (!recognitionRef.current) {
      // @ts-ignore
      const recognition = new window.webkitSpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.lang = 'bn-BD';

      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        handleSend(transcript);
      };
      recognition.onerror = (event: any) => {
        setIsListening(false);
        if (isLiveMode && event.error !== 'no-speech' && isOpen) {
          setTimeout(() => startListening(), 1000);
        }
      };
      recognitionRef.current = recognition;
    }

    try {
      recognitionRef.current.start();
    } catch (e) {
      // Catch already started errors
    }
  };

  const stopListening = () => {
    if (recognitionRef.current) recognitionRef.current.stop();
    setIsListening(false);
  };

  const toggleLiveMode = async () => {
    await initAudio();
    const nextMode = !isLiveMode;
    setIsLiveMode(nextMode);

    if (nextMode) {
      startListening();
    } else {
      stopListening();
    }
  };

  const handleSend = async (text: string = input) => {
    const messageToSend = text.trim();
    if (!messageToSend || !isOnline) return;

    setMessages(prev => [...prev, { role: 'user', text: messageToSend, timestamp: new Date() }]);
    setInput('');
    setIsTyping(true);

    const history = messages.slice(-6).map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));

    try {
      const botResponse = await bfcAssistChat(messageToSend, history);
      setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
      // Direct voice output right after getting the response
      speakText(botResponse);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "সার্ভারে জ্যাম বস! 😅", timestamp: new Date() }]);
      if (isLiveMode) startListening();
    } finally {
      setIsTyping(false);
    }
  };

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, isTyping]);

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[5000] font-sans">
      {isOpen ? (
        <div className="bg-white/95 dark:bg-gray-950/98 backdrop-blur-3xl w-[94vw] sm:w-[420px] h-[80vh] sm:h-[680px] rounded-[48px] shadow-[0_50px_100px_-20px_rgba(220,38,38,0.25)] flex flex-col border border-white/40 dark:border-white/5 overflow-hidden animate-slide-up ring-1 ring-black/5">

          {/* Header with Visualizer */}
          <div className="bg-gray-950 p-7 text-white relative overflow-hidden shrink-0">
            <div className={`absolute inset-0 bg-gradient-to-br from-red-600/20 to-transparent transition-opacity duration-1000 ${isSpeaking || isListening ? 'opacity-100' : 'opacity-30'}`}></div>

            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-4">
                <div className="relative">
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center border border-white/10 transition-all duration-500 shadow-2xl ${isSpeaking ? 'bg-red-600 scale-110 shadow-red-600/50' : isListening ? 'bg-emerald-600 scale-105 shadow-emerald-600/50' : 'bg-gray-800'}`}>
                    <i className={`fas ${isSpeaking ? 'fa-waveform-lines animate-pulse' : isListening ? 'fa-microphone-lines animate-bounce' : 'fa-robot'} text-2xl`}></i>
                  </div>
                  <div className={`absolute -bottom-1 -right-1 w-4 h-4 border-2 border-gray-950 rounded-full ${isOnline ? 'bg-emerald-500 shadow-emerald-500/50' : 'bg-red-500'}`}></div>
                </div>
                <div>
                  <h3 className="font-black text-xl tracking-tighter uppercase italic leading-none">BFC BOSS LIVE</h3>
                  <p className="text-[9px] font-black text-gray-500 uppercase tracking-[3px] mt-1.5 flex items-center gap-2">
                    {isSpeaking ? <span className="text-red-500 animate-pulse">● Speaking</span> : isListening ? <span className="text-emerald-500 animate-pulse">● Listening</span> : <span className="opacity-50 italic">Waiting for command</span>}
                  </p>
                </div>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={toggleLiveMode}
                  className={`w-11 h-11 rounded-2xl flex items-center justify-center transition-all border ${isLiveMode ? 'bg-red-600 border-red-500 shadow-lg shadow-red-600/30 text-white' : 'bg-white/5 border-white/10 text-gray-500 hover:text-white'}`}
                  title="Toggle Live Hands-free Mode"
                >
                  <i className={`fas ${isLiveMode ? 'fa-headset' : 'fa-microphone-slash'} text-sm`}></i>
                </button>
                <button onClick={() => setIsOpen(false)} className="w-11 h-11 bg-white/5 hover:bg-white/10 rounded-2xl flex items-center justify-center border border-white/10 group">
                  <i className="fas fa-times text-sm text-gray-500 group-hover:text-white"></i>
                </button>
              </div>
            </div>

            {/* Soundwave Animation */}
            {(isSpeaking || isListening) && (
              <div className="mt-6 flex items-end justify-center gap-1.5 h-8">
                {[...Array(15)].map((_, i) => (
                  <div 
                    key={i} 
                    className={`w-1 bg-red-500/80 rounded-full animate-bounce`} 
                    style={{ 
                      height: `${30 + Math.random() * 70}%`, 
                      animationDuration: `${0.2 + Math.random() * 0.4}s`,
                      animationDelay: `${i * 0.04}s`
                    }}
                  ></div>
                ))}
              </div>
            )}
          </div>

          {/* Chat Feed */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-7 space-y-6 scrollbar-hide bg-gray-50/30 dark:bg-transparent">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                <div className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'} max-w-[85%]`}>
                  <div className={`px-5 py-4 rounded-[28px] text-[13px] font-bold leading-relaxed shadow-sm border transition-all ${
                    m.role === 'user' 
                    ? 'bg-red-600 text-white rounded-br-none border-red-500 shadow-red-600/10' 
                    : 'bg-white dark:bg-gray-900 text-gray-800 dark:text-gray-100 rounded-tl-none border-gray-100 dark:border-white/5'
                  }`}>
                    {m.text}
                  </div>
                  <span className="text-[7px] mt-2 font-black tracking-[2px] opacity-20 uppercase px-2">{m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start animate-slide-up">
                <div className="bg-white dark:bg-gray-900 px-5 py-3 rounded-[20px] rounded-tl-none border border-gray-100 dark:border-white/5 flex gap-1.5">
                  <span className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce"></span>
                  <span className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:0.1s]"></span>
                  <span className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                </div>
              </div>
            )}
          </div>

          {/* Controls */}
          <div className={`p-7 bg-white dark:bg-gray-950 border-t border-gray-100 dark:border-white/5 ${!isOnline ? 'opacity-30 pointer-events-none' : ''}`}>
            <div className="relative flex items-center bg-gray-100 dark:bg-gray-900 rounded-[32px] p-2 border border-transparent focus-within:border-red-600/20 transition-all shadow-inner">
              <button 
                onClick={() => isListening ? stopListening() : startListening()}
                className={`w-12 h-12 rounded-[20px] flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white shadow-lg shadow-red-600/30' : 'text-gray-400 hover:text-red-600 bg-transparent'}`}
              >
                <i className={`fas ${isListening ? 'fa-stop' : 'fa-microphone-alt'} text-xl`}></i>
              </button>

              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={isLiveMode ? "LIVE MODE ACTIVE..." : "বসের হুকুম কী?..."}
                disabled={isLiveMode}
                className="flex-1 bg-transparent border-none py-3 px-4 outline-none text-[13px] font-bold text-gray-900 dark:text-gray-100 placeholder:text-gray-400"
              />

              <button 
                onClick={() => handleSend()}
                disabled={!input.trim() || isTyping || isLiveMode}
                className="w-12 h-12 bg-gray-950 dark:bg-red-600 text-white rounded-[20px] flex items-center justify-center hover:scale-105 active:scale-95 transition-all disabled:opacity-10 shadow-xl"
              >
                <i className="fas fa-paper-plane text-sm"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={async () => { setIsOpen(true); await initAudio(); }}
          className="group relative focus:outline-none"
        >
          {isLiveMode && <div className="absolute -top-1 -right-1 w-6 h-6 bg-red-600 rounded-full z-10 border-2 border-white flex items-center justify-center animate-pulse"><i className="fas fa-headset text-[8px] text-white"></i></div>}
          <div className={`relative w-18 h-18 sm:w-20 sm:h-20 bg-gray-950 dark:bg-red-600 text-white rounded-[32px] shadow-[0_30px_60px_-15px_rgba(220,38,38,0.4)] flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all duration-500 border-4 border-white dark:border-white/10 group`}>
             {isSpeaking && <div className="absolute inset-0 bg-white/10 animate-ping rounded-full"></div>}
             <i className={`fas ${isSpeaking ? 'fa-volume-high animate-bounce' : isLiveMode ? 'fa-headset' : 'fa-comment-dots'} text-2xl group-hover:rotate-12 transition-transform`}></i>
             <span className="text-[7px] font-black uppercase tracking-[2.5px] mt-2 opacity-80 leading-none">{isSpeaking ? 'Boss Talks' : isLiveMode ? 'Live' : 'Assist'}</span>
          </div>
        </button>
      )}
    </div>
  );
};

