import { GoogleGenAI, Modality } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  if (!navigator.onLine) {
    return "দুঃখিত, আমি অফলাইন। ইন্টারনেট সংযোগ চেক করুন।";
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history.slice(-3), // Keep context short for faster processing
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are "BFC Assist" – a respectful, polite, and kind customer support agent.

        CORE RULES:
        1. FORMAL ADDRESS: Use "Apni" and "Sir/Madam". NEVER use "Boss", "Mama", or slang.
        2. TONE: Be extremely kind, sincere, and welcoming.
        3. MANDATORY SALAAM: Always start with "Assalamu Alaikum" or "সালাম".
        4. ULTRA BREVITY: MAX 6-8 words per response. Very short for instant voice output.
        5. VOICE OPTIMIZED: No markdown, no symbols, just clean text for speech.
        6. LANGUAGE: Match the user's language (Bengali/English).

        EXAMPLES:
        User: "Kacchi update?"
        Response: "সালাম স্যার। আপনার কাচ্চি এখন প্রস্তুত করা হচ্ছে।"
        User: "Where is my food?"
        Response: "সালাম। আপনার খাবারটি রাইডার নিয়ে আপনার ঠিকানায় আসছেন।"`,
        temperature: 0.5, // Lower temperature for more predictable/fast responses
        topP: 0.8,
      },
    });

    return response.text || "আমি আন্তরিকভাবে দুঃখিত, আবার চেষ্টা করুন।";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return "নেটওয়ার্ক ত্রুটি, দয়া করে আবার বলুন।";
  }
};

export const generateSpeech = async (text: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            // Using 'Kore' which is clear and can sound professional when the text is formal
            prebuiltVoiceConfig: { voiceName: 'Kore' }, 
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    return base64Audio;
  } catch (error) {
    console.error("Speech Gen Error:", error);
    return null;
  }
};

