// Fast Base64 to Bytes decoding
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Ultra-low latency raw PCM decoding
async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const buffer = ctx.createBuffer(1, dataInt16.length, sampleRate);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) {
    channelData[i] = dataInt16[i] / 32768.0;
  }
  return buffer;
}

export const ChatBot: React.FC<{ isOnline?: boolean }> = ({ isOnline = true }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: "সালাম। বিএফসি অ্যাসিস্ট্যান্ট হিসেবে আমি আপনার সেবায় নিয়োজিত। কেমন আছেন আপনি? কী লাগবে আপনার?", timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLiveMode, setIsLiveMode] = useState(false); 

  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);
  const currentSpeechSource = useRef<AudioBufferSourceNode | null>(null);

  const initAudio = useCallback(async () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (audioContextRef.current.state === 'suspended') {
      await audioContextRef.current.resume();
    }
    return audioContextRef.current;
  }, []);

  const startListening = useCallback(() => {
    if (!isOnline || isSpeaking) return;

    if (!('webkitSpeechRecognition' in window)) return;

    if (!recognitionRef.current) {
      // @ts-ignore
      const recognition = new window.webkitSpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.lang = 'bn-BD';

      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        handleSend(transcript);
      };
      recognition.onerror = (event: any) => {
        setIsListening(false);
        if (isLiveMode && isOpen && (event.error === 'no-speech' || event.error === 'network')) {
          setTimeout(() => startListening(), 500);
        }
      };
      recognitionRef.current = recognition;
    }

    try {
      recognitionRef.current.start();
    } catch (e) {}
  }, [isOnline, isSpeaking, isLiveMode, isOpen]);

  const speakText = async (text: string) => {
    if (!text) return;

    const ctx = await initAudio();
    setIsSpeaking(true);

    if (currentSpeechSource.current) {
      try { currentSpeechSource.current.stop(); } catch(e) {}
    }

    try {
      const base64Audio = await generateSpeech(text);
      if (base64Audio) {
        const audioData = decodeBase64(base64Audio);
        const audioBuffer = await decodeAudioData(audioData, ctx, 24000);

        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        currentSpeechSource.current = source;

        source.onended = () => {
          setIsSpeaking(false);
          currentSpeechSource.current = null;
          if (isLiveMode && isOpen) {
            // Fast loop back to listening state
            setTimeout(() => startListening(), 150);
          }
        };

        source.start(0);
      } else {
        setIsSpeaking(false);
        if (isLiveMode && isOpen) startListening();
      }
    } catch (err) {
      setIsSpeaking(false);
      if (isLiveMode && isOpen) startListening();
    }
  };

  const handleSend = async (text: string = input) => {
    const messageToSend = text.trim();
    if (!messageToSend || !isOnline) return;

    setMessages(prev => [...prev, { role: 'user', text: messageToSend, timestamp: new Date() }]);
    setInput('');
    setIsTyping(true);

    const history = messages.slice(-2).map(m => ({ 
      role: m.role, 
      parts: [{ text: m.text }] 
    }));

    try {
      // Rapid processing with Gemini 3 Flash
      const botResponse = await bfcAssistChat(messageToSend, history);
      setMessages(prev => [...prev, { role: 'model', text: botResponse, timestamp: new Date() }]);
      speakText(botResponse);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "দুঃখিত, আমি এই মুহূর্তে উত্তর দিতে পারছি না।", timestamp: new Date() }]);
      if (isLiveMode) startListening();
    } finally {
      setIsTyping(false);
    }
  };

  const toggleLiveMode = async () => {
    await initAudio();
    const nextMode = !isLiveMode;
    setIsLiveMode(nextMode);
    if (nextMode) startListening();
  };

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, isTyping]);

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[5000] font-sans">
      {isOpen ? (
        <div className="bg-white/95 dark:bg-gray-950/98 backdrop-blur-3xl w-[92vw] sm:w-[420px] h-[75vh] sm:h-[650px] rounded-[48px] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.2)] flex flex-col border border-white/40 dark:border-white/5 overflow-hidden animate-slide-up ring-1 ring-black/5">

          {/* Professional Sincere Header */}
          <div className="bg-gray-950 p-8 text-white relative overflow-hidden shrink-0">
            <div className={`absolute inset-0 bg-red-600/5 transition-opacity duration-1000 ${isSpeaking || isListening ? 'opacity-100' : 'opacity-20'}`}></div>

            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-4">
                <div className="relative">
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center border border-white/10 transition-all duration-300 shadow-2xl ${isSpeaking ? 'bg-red-600' : isListening ? 'bg-emerald-600' : 'bg-gray-800'}`}>
                    <i className={`fas ${isSpeaking ? 'fa-waveform-lines animate-pulse' : isListening ? 'fa-microphone-lines' : 'fa-headset'} text-2xl`}></i>
                  </div>
                  <div className={`absolute -bottom-1 -right-1 w-4 h-4 border-2 border-gray-950 rounded-full ${isOnline ? 'bg-emerald-500 shadow-emerald-500/50' : 'bg-red-500'}`}></div>
                </div>
                <div>
                  <h3 className="font-black text-xl tracking-tighter uppercase italic leading-none">BFC ASSIST</h3>
                  <p className="text-[9px] font-bold text-gray-500 uppercase tracking-[2px] mt-1.5 flex items-center gap-2">
                    {isSpeaking ? <span className="text-red-500 animate-pulse">● Speaking Sincerely</span> : isListening ? <span className="text-emerald-500">● Listening sincerely...</span> : <span className="opacity-50 italic">At your service</span>}
                  </p>
                </div>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={toggleLiveMode}
                  className={`w-11 h-11 rounded-2xl flex items-center justify-center transition-all border ${isLiveMode ? 'bg-red-600 border-red-500 shadow-lg text-white' : 'bg-white/5 border-white/10 text-gray-500 hover:text-white'}`}
                  title="Hands-free Sincere Mode"
                >
                  <i className={`fas ${isLiveMode ? 'fa-ear-listen' : 'fa-microphone-slash'} text-sm`}></i>
                </button>
                <button onClick={() => setIsOpen(false)} className="w-11 h-11 bg-white/5 hover:bg-white/10 rounded-2xl flex items-center justify-center border border-white/10 group">
                  <i className="fas fa-times text-sm text-gray-500 group-hover:text-white"></i>
