                  <p className="text-[8px] font-bold text-gray-500 uppercase tracking-[2px] mt-1">
                    {isSpeaking ? 'Speaking Sincerely' : isListening ? 'Listening...' : 'At your service'}
                  </p>
                </div>
              </div>
              <div className="flex gap-2">
                <button onClick={toggleLiveMode} className={`w-10 h-10 rounded-xl flex items-center justify-center border ${isLiveMode ? 'bg-red-600 border-red-500' : 'bg-white/5 border-white/10 text-gray-500'}`}>
                  <i className={`fas ${isLiveMode ? 'fa-ear-listen' : 'fa-microphone-slash'} text-xs`}></i>
                </button>
                <button onClick={() => setIsOpen(false)} className="w-10 h-10 bg-white/5 rounded-xl flex items-center justify-center border border-white/10">
                  <i className="fas fa-times text-xs text-gray-500"></i>
                </button>
              </div>
            </div>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-4 scrollbar-hide">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`px-5 py-3 rounded-[24px] text-[13px] font-bold shadow-sm border ${m.role === 'user' ? 'bg-red-600 text-white border-red-500' : 'bg-white dark:bg-gray-900 text-gray-800 dark:text-gray-100 border-gray-100 dark:border-white/5'}`}>
