      // Immediate voice call - parallel to UI update
      speakText(res);
    } catch (e) {
      if (isLiveMode) startListening();
    } finally {
      setIsTyping(false);
    }
  };

  const toggleLiveMode = async () => {
    await initAudio();
    const next = !isLiveMode;
    setIsLiveMode(next);
    if (next) startListening();
  };

