    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[5000]">
      {isOpen ? (
        <div className="bg-white/98 dark:bg-gray-950/98 backdrop-blur-3xl w-[92vw] sm:w-[420px] h-[75vh] sm:h-[650px] rounded-[48px] shadow-2xl flex flex-col border border-white/40 dark:border-white/5 overflow-hidden ring-1 ring-black/5 animate-slide-up">
          <div className="bg-gray-950 p-6 text-white relative overflow-hidden shrink-0">
            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isSpeaking ? 'bg-red-600' : isListening ? 'bg-emerald-600' : 'bg-gray-800'}`}>
                  <i className={`fas ${isSpeaking ? 'fa-waveform-lines animate-pulse' : isListening ? 'fa-microphone' : 'fa-headset'} text-xl`}></i>
                </div>
                <div>
                  <h3 className="font-black text-lg tracking-tighter uppercase italic leading-none">BFC ASSIST</h3>
                  <p className="text-[8px] font-bold text-gray-500 uppercase tracking-[2px] mt-1">
                    {isSpeaking ? 'Sincere Speaking' : isListening ? 'Listening...' : 'Ultra-Fast Support'}
                  </p>
                </div>
              </div>
              <div className="flex gap-2">
                <button onClick={toggleLiveMode} className={`w-10 h-10 rounded-xl flex items-center justify-center border transition-all ${isLiveMode ? 'bg-red-600 border-red-500 text-white shadow-lg' : 'bg-white/5 border-white/10 text-gray-500'}`}>
                  <i className={`fas ${isLiveMode ? 'fa-ear-listen' : 'fa-microphone-slash'} text-xs`}></i>
                </button>
                <button onClick={() => setIsOpen(false)} className="w-10 h-10 bg-white/5 rounded-xl flex items-center justify-center border border-white/10 text-gray-500 hover:text-white transition-colors">
                  <i className="fas fa-times text-xs"></i>
                </button>
              </div>
