                <div className={`px-5 py-3 rounded-[24px] text-[13px] font-bold shadow-sm border ${m.role === 'user' ? 'bg-red-600 text-white border-red-500' : 'bg-white dark:bg-gray-900 text-gray-800 dark:text-gray-100 border-gray-100 dark:border-white/5'}`}>
                  {m.text}
