              </div>
            ))}
            {isTyping && <div className="text-[9px] font-black text-red-600 animate-pulse uppercase tracking-[3px]">Mission logic...</div>}
          </div>

          <div className="p-6 bg-white dark:bg-gray-950 border-t dark:border-white/5">
            <div className="flex items-center bg-gray-100 dark:bg-gray-900 rounded-[24px] p-2 border border-transparent focus-within:border-red-600/20 transition-all">
              <button onClick={() => isListening ? recognitionRef.current?.stop() : startListening()} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white shadow-lg' : 'text-gray-400'}`}>
