              </button>
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder={isLiveMode ? "Listening sincerely..." : "কীভাবে সাহায্য করতে পারি?..."}
                disabled={isLiveMode}
                className="flex-1 bg-transparent border-none px-4 outline-none text-[13px] font-bold dark:text-white placeholder:text-gray-400"
              />
              <button onClick={() => handleSend()} disabled={!input.trim() || isTyping || isLiveMode} className="w-10 h-10 bg-gray-950 dark:bg-red-600 text-white rounded-xl flex items-center justify-center shadow-lg active:scale-90 transition-transform disabled:opacity-30">
                <i className="fas fa-paper-plane text-xs"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button onClick={async () => { setIsOpen(true); await initAudio(); }} className="w-16 h-16 bg-gray-950 dark:bg-red-600 text-white rounded-[24px] shadow-2xl flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all group overflow-hidden border-4 border-white dark:border-white/10">
           {(isSpeaking || isListening) && <div className="absolute inset-0 bg-white/10 animate-pulse"></div>}
           <i className={`fas ${isSpeaking ? 'fa-waveform-lines' : isLiveMode ? 'fa-ear-listen' : 'fa-headset'} text-xl transition-transform`}></i>
           <span className="text-[6px] font-black uppercase mt-1 tracking-widest leading-none">{isLiveMode ? 'LIVE' : 'ASSIST'}</span>
        </button>
