// PCM Utilities for Gemini Live
export function encodeAudio(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { bfcAssistChat, generateSpeech, decodeAudio, decodeAudioData, encodeAudio } from '../services/geminiService';
import { ChatMessage } from '../types';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';
import { MOCK_MENU } from '../constants';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const menuData = MOCK_MENU.map(i => `${i.nameBn}:৳${i.price}`).join(",");

export const ChatBot: React.FC<{ isOnline?: boolean }> = ({ isOnline = true }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: "সালাম। কেমন আছেন আপনি? আমি বিএফসি অ্যাসিস্ট্যান্ট, আপনার কী লাগবে?", timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLiveMode, setIsLiveMode] = useState(false); 

  const scrollRef = useRef<HTMLDivElement>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const liveSessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const recognitionRef = useRef<any>(null);
  const currentSpeechSource = useRef<AudioBufferSourceNode | null>(null);

  const stopAllAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    if (currentSpeechSource.current) {
      try { currentSpeechSource.current.stop(); } catch(e) {}
      currentSpeechSource.current = null;
    }
    nextStartTimeRef.current = 0;
  };

  const initLiveSession = async () => {
    if (!isOnline) return;

    // Low latency settings
    inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
    outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const session = await ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const processor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            processor.onaudioprocess = (e) => {
              if (!isLiveMode) return;
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              session.sendRealtimeInput({
                media: { data: encodeAudio(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' }
              });
            };
            source.connect(processor);
            processor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData && outputAudioContextRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };
            }
            if (msg.serverContent?.interrupted) stopAllAudio();
            if (msg.serverContent?.turnComplete) setIsTyping(false);
          },
          onerror: () => setIsLiveMode(false),
          onclose: () => setIsLiveMode(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
          systemInstruction: `ROLE: BFC Assist (Live).
          EXTREME SPEED: Start speaking immediately.
          PERSONA: Ultra-Polite, Formal, Kind. Use "Apni/Sir/Madam". 
          SCOPE: BFC food only. If off-topic, say: "সালাম। আমি শুধু খাবার নিয়ে কথা বলি।"
          MENU: ${menuData}. 
          LENGTH: 3-5 words max per response.`
        }
      });
      liveSessionRef.current = session;
    } catch (err) {
      setIsLiveMode(false);
    }
  };

  const speakText = async (text: string) => {
    if (!text) return;
    const ctx = outputAudioContextRef.current || new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    setIsSpeaking(true);
    stopAllAudio();
    try {
      const base64Audio = await generateSpeech(text);
      if (base64Audio) {
        const audioBuffer = await decodeAudioData(decodeAudio(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        currentSpeechSource.current = source;
        source.onended = () => { setIsSpeaking(false); currentSpeechSource.current = null; };
        source.start(0);
      } else { setIsSpeaking(false); }
    } catch (err) { setIsSpeaking(false); }
  };

  const handleSend = async (text: string = input) => {
    const msg = text.trim();
    if (!msg || !isOnline) return;
    setMessages(p => [...p, { role: 'user', text: msg, timestamp: new Date() }]);
    setInput('');
    setIsTyping(true);
    try {
      const res = await bfcAssistChat(msg, messages.slice(-1).map(m => ({ role: m.role, parts: [{ text: m.text }] })));
      setMessages(p => [...p, { role: 'model', text: res, timestamp: new Date() }]);
      speakText(res);
    } catch (e) { } finally { setIsTyping(false); }
  };

  const toggleLiveMode = async () => {
    const next = !isLiveMode;
    setIsLiveMode(next);
    stopAllAudio();
    if (next) {
      await initLiveSession();
    } else {
      if (liveSessionRef.current) liveSessionRef.current.close();
      if (inputAudioContextRef.current) inputAudioContextRef.current.close();
    }
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'auto' });
  }, [messages, isTyping]);

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[5000]">
      {isOpen ? (
        <div className="bg-white/98 dark:bg-gray-950/98 backdrop-blur-3xl w-[92vw] sm:w-[420px] h-[75vh] sm:h-[650px] rounded-[48px] shadow-2xl flex flex-col border border-white/40 dark:border-white/5 overflow-hidden ring-1 ring-black/5 animate-slide-up">
          <div className="bg-gray-950 p-6 text-white relative overflow-hidden shrink-0">
            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all duration-300 ${isLiveMode ? 'bg-red-600 scale-110 shadow-lg shadow-red-600/50' : isSpeaking ? 'bg-amber-500 shadow-lg shadow-amber-500/50' : 'bg-gray-800'}`}>
                   <i className={`fas ${isLiveMode ? 'fa-bolt animate-pulse' : isSpeaking ? 'fa-waveform-lines' : 'fa-headset'} text-xl`}></i>
                </div>
                <div>
                  <h3 className="font-black text-lg tracking-tighter uppercase italic leading-none">BFC ASSIST</h3>
                  <p className="text-[8px] font-bold text-gray-500 uppercase tracking-[2px] mt-1">
                    {isLiveMode ? 'Real-time Live Sync' : isSpeaking ? 'Speaking Sincerely' : 'Ultra-Fast Interface'}
                  </p>
                </div>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={toggleLiveMode} 
                  className={`w-10 h-10 rounded-xl flex items-center justify-center border transition-all ${isLiveMode ? 'bg-red-600 border-red-500 text-white shadow-lg' : 'bg-white/5 border-white/10 text-gray-500 hover:text-white'}`}
                  title={isLiveMode ? "Stop Live Sync" : "Start Live Sync"}
                >
                  <i className={`fas ${isLiveMode ? 'fa-stop' : 'fa-microphone'} text-xs`}></i>
                </button>
                <button onClick={() => { setIsOpen(false); if(isLiveMode) toggleLiveMode(); }} className="w-10 h-10 bg-white/5 rounded-xl flex items-center justify-center border border-white/10 text-gray-500 hover:text-white transition-colors">
                  <i className="fas fa-times text-xs"></i>
                </button>
              </div>
            </div>
            {isLiveMode && (
              <div className="absolute bottom-0 left-0 h-1 bg-red-600 w-full overflow-hidden">
                <div className="h-full bg-white/50 w-1/3 animate-[slide_2s_linear_infinite]"></div>
              </div>
            )}
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-4 scrollbar-hide">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`px-5 py-3 rounded-[24px] text-[13px] font-bold shadow-sm border animate-slide-up ${m.role === 'user' ? 'bg-red-600 text-white border-red-500' : 'bg-white dark:bg-gray-900 text-gray-800 dark:text-gray-100 border-gray-100 dark:border-white/5'}`}>
                  {m.text}
                </div>
              </div>
            ))}
            {(isTyping || isLiveMode) && (
              <div className="flex items-center gap-2 text-[9px] font-black text-red-600 animate-pulse uppercase tracking-[3px]">
                <span className="w-1.5 h-1.5 bg-red-600 rounded-full"></span>
                {isLiveMode ? 'Live Comms Active...' : 'Processing Sincerely...'}
              </div>
            )}
          </div>

          <div className="p-6 bg-white dark:bg-gray-950 border-t dark:border-white/5">
            <div className={`flex items-center bg-gray-100 dark:bg-gray-900 rounded-[24px] p-2 border transition-all duration-500 ${isLiveMode ? 'border-red-600/50 bg-red-50/10' : 'border-transparent focus-within:border-red-600/20'}`}>
              <button disabled={isLiveMode} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isLiveMode ? 'opacity-10' : 'text-gray-400'}`}>
                <i className="fas fa-keyboard text-lg"></i>
              </button>
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder={isLiveMode ? "Listening in real-time..." : "কী অর্ডার করবেন?..."}
                disabled={isLiveMode}
                className="flex-1 bg-transparent border-none px-4 outline-none text-[13px] font-bold dark:text-white placeholder:text-gray-400 disabled:opacity-50"
              />
              <button 
                onClick={() => handleSend()} 
                disabled={!input.trim() || isTyping || isLiveMode} 
                className="w-10 h-10 bg-gray-950 dark:bg-red-600 text-white rounded-xl flex items-center justify-center shadow-lg active:scale-90 transition-transform disabled:opacity-30"
              >
                <i className="fas fa-paper-plane text-xs"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)} 
          className="w-16 h-16 bg-gray-950 dark:bg-red-600 text-white rounded-[24px] shadow-2xl flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all group overflow-hidden border-4 border-white dark:border-white/10 relative"
        >
           {(isSpeaking || isLiveMode) && <div className="absolute inset-0 bg-white/20 animate-pulse"></div>}
           <i className={`fas ${isLiveMode ? 'fa-bolt' : isSpeaking ? 'fa-waveform-lines' : 'fa-headset'} text-xl transition-transform`}></i>
           <span className="text-[6px] font-black uppercase mt-1 tracking-widest leading-none">{isLiveMode ? 'LIVE' : 'ASSIST'}</span>
        </button>
      )}
      <style>{`
        @keyframes slide {
          from { transform: translateX(-100%); }
          to { transform: translateX(300%); }
        }
      `}</style>
    </div>
  );
};

