            {isLiveMode && liveTranscription && (
              <div className="flex justify-start">
                <div className="px-5 py-3 rounded-[24px] text-[12px] font-black bg-gray-50 dark:bg-gray-800 text-red-600 border border-red-100 dark:border-red-900/30 italic animate-pulse">
                  "{liveTranscription}"
                </div>
              </div>
            )}
            {(isTyping || (isLiveMode && !liveTranscription)) && (
              <div className="flex items-center gap-2 text-[9px] font-black text-red-600 animate-pulse uppercase tracking-[3px]">
                <span className="w-1.5 h-1.5 bg-red-600 rounded-full"></span>
                {isLiveMode ? 'Assistant is listening...' : 'Sincere Thinking...'}
              </div>
            )}
          </div>

          <div className="p-6 bg-white dark:bg-gray-950 border-t dark:border-white/5">
            <div className={`flex items-center bg-gray-100 dark:bg-gray-900 rounded-[24px] p-2 border transition-all duration-500 ${isLiveMode ? 'border-red-600/50 bg-red-50/10 shadow-inner' : 'border-transparent focus-within:border-red-600/20'}`}>
              <button disabled={isLiveMode} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isLiveMode ? 'opacity-10' : 'text-gray-400'}`}>
                <i className="fas fa-keyboard text-lg"></i>
              </button>
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder={isLiveMode ? "Hearing your request..." : "কী অর্ডার করবেন?..."}
                disabled={isLiveMode}
                className="flex-1 bg-transparent border-none px-4 outline-none text-[13px] font-bold dark:text-white placeholder:text-gray-400 disabled:opacity-50"
              />
              <button 
                onClick={() => handleSend()} 
                disabled={!input.trim() || isTyping || isLiveMode} 
                className="w-10 h-10 bg-gray-900 dark:bg-red-600 text-white rounded-xl flex items-center justify-center shadow-lg active:scale-90 transition-transform disabled:opacity-30"
              >
                <i className="fas fa-paper-plane text-xs"></i>
              </button>
            </div>
          </div>
        </div>
      ) : (
        <button 
          onClick={async () => {
            setIsOpen(true);
            await initAudioContexts();
          }} 
          className="w-16 h-16 bg-gray-900 dark:bg-red-600 text-white rounded-[24px] shadow-2xl flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all group overflow-hidden border-4 border-white dark:border-white/10 relative"
          aria-label="Open BFC Assist"
        >
           {(isSpeaking || isLiveMode) && <div className="absolute inset-0 bg-white/20 animate-pulse"></div>}
           <i className={`fas ${isLiveMode ? 'fa-bolt' : isSpeaking ? 'fa-waveform-lines' : 'fa-headset'} text-xl transition-transform`}></i>
           <span className="text-[6px] font-black uppercase mt-1 tracking-widest leading-none">{isLiveMode ? 'LIVE' : 'ASSIST'}</span>
        </button>
      )}
      <style>{`
        @keyframes slide {
          from { transform: translateX(-100%); }
          to { transform: translateX(300%); }
        }
      `}</style>
    </div>
  );
};

const CACHE_NAME = 'bfc-v4-ultra';
const STATIC_ASSETS = [
  '/',
  '/index.html',
  '/manifest.json',
  'https://cdn.tailwindcss.com',
  'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css',
  'https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&family=Hind+Siliguri:wght@400;700&display=swap'
];

const IMAGE_CACHE = 'bfc-images-v1';

// Install: Cache essential shell
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      console.log('[BFC SW] Initializing Offline Core');
      return cache.addAll(STATIC_ASSETS);
    })
  );
  self.skipWaiting();
});

// Activate: Purge old versions
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cache) => {
          if (cache !== CACHE_NAME && cache !== IMAGE_CACHE) {
            console.log('[BFC SW] Clearing Stale Node:', cache);
            return caches.delete(cache);
          }
        })
      );
    })
  );
  return self.clients.claim();
});

// Fetch: Hybrid Strategy
self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Bypass Gemini API - must be online
  if (url.hostname.includes('generativelanguage.googleapis.com')) {
    return;
  }

  // Strategy: Cache-First for Images (Heavy Assets)
  if (request.destination === 'image') {
    event.respondWith(
      caches.open(IMAGE_CACHE).then((cache) => {
        return cache.match(request).then((cached) => {
          return cached || fetch(request).then((network) => {
            cache.put(request, network.clone());
            return network;
          });
        });
      })
    );
    return;
  }

  // Strategy: Stale-While-Revalidate for App Shell
  event.respondWith(
    caches.match(request).then((cachedResponse) => {
      const fetchPromise = fetch(request).then((networkResponse) => {
        if (networkResponse && networkResponse.status === 200) {
          const responseToCache = networkResponse.clone();
          caches.open(CACHE_NAME).then((cache) => {
            cache.put(request, responseToCache);
          });
        }
        return networkResponse;
      }).catch(() => {
        if (request.mode === 'navigate') {
          return caches.match('/index.html');
        }
      });

      return cachedResponse || fetchPromise;
    })
  );
});

