import { GoogleGenAI, Modality } from "@google/genai";
import { MOCK_MENU } from "../constants";

// Function to get a fresh instance to ensure we use the latest injected API key
export const getAiInstance = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const menuData = MOCK_MENU.map(i => `${i.nameBn}:৳${i.price}`).join(",");

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  if (!navigator.onLine) return "নেটওয়ার্ক নেই। অনুগ্রহ করে কানেকশন চেক করুন।";
  const ai = getAiInstance();

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history.slice(-1), 
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `ROLE: BFC Assist. 
        KNOWLEDGE: BFC Menu: ${menuData}.
        TONE: Friendly, energetic, and extremely efficient. 
        RULES:
        1. Natural Bangla: Use engaging, helpful language (e.g., "অবশ্যই!", "নিশ্চয়ই সাহায্য করছি").
        2. Greeting: Start with a warm "সালাম" or "হ্যালো".
        3. Scope: ONLY BFC food. 
        4. Brevity: Keep responses under 10 words. Focus on being practical.`,
        temperature: 0.7,
      },
    });

    return response.text || "আমি বিএফসি অ্যাসিস্ট্যান্ট। কীভাবে সাহায্য করতে পারি?";
  } catch (error: any) {
    return "দুঃখিত, কানেকশনে কিছুটা সমস্যা হচ্ছে।";
  }
};

export const generateSpeech = async (text: string) => {
  const ai = getAiInstance();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, 
          },
        },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (error) {
    return null;
  }
};

export function encodeAudio(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { bfcAssistChat, generateSpeech, decodeAudio, decodeAudioData, encodeAudio, getAiInstance } from '../services/geminiService';
import { ChatMessage } from '../types';
import { Modality, LiveServerMessage } from '@google/genai';
import { MOCK_MENU } from '../constants';

const menuData = MOCK_MENU.map(i => `${i.nameBn}:৳${i.price}`).join(",");

export const ChatBot: React.FC<{ isOnline?: boolean }> = ({ isOnline = true }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: "হ্যালো! বিএফসি হাবে আপনাকে স্বাগতম। আজ আপনার জন্য কী অর্ডার করতে পারি?", timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLiveMode, setIsLiveMode] = useState(false); 
  const [micError, setMicError] = useState<string | null>(null);
  const [liveTranscription, setLiveTranscription] = useState<string>('');

  const scrollRef = useRef<HTMLDivElement>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const liveSessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const currentSpeechSource = useRef<AudioBufferSourceNode | null>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);

  const stopAllAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    if (currentSpeechSource.current) {
      try { currentSpeechSource.current.stop(); } catch(e) {}
      currentSpeechSource.current = null;
    }
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
  };

  const cleanupLiveResources = () => {
    if (liveSessionRef.current) {
      try { liveSessionRef.current.close(); } catch(e) {}
      liveSessionRef.current = null;
    }
    if (processorRef.current) {
      processorRef.current.disconnect();
      processorRef.current = null;
    }
    if (micStreamRef.current) {
      micStreamRef.current.getTracks().forEach(track => track.stop());
      micStreamRef.current = null;
    }
    setIsLiveMode(false);
    setLiveTranscription('');
  };

  const initAudioContexts = async () => {
    try {
      if (!inputAudioContextRef.current) {
        inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      }
      if (!outputAudioContextRef.current) {
        outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      if (inputAudioContextRef.current.state === 'suspended') await inputAudioContextRef.current.resume();
      if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();
    } catch (e) {
      console.error("AudioContext initialization failed", e);
    }
  };

  const startLiveSession = async () => {
    if (!isOnline) return;
    setMicError(null);
    stopAllAudio();
    await initAudioContexts();

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;

      const ai = getAiInstance();
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const processor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            processorRef.current = processor;

            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) {
                int16[i] = inputData[i] * 32768;
              }
              const pcmBlob = {
                data: encodeAudio(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(processor);
            processor.connect(inputAudioContextRef.current!.destination);
            setIsLiveMode(true);
            setMessages(p => [...p, { role: 'model', text: "আমি শুনছি, বলুন কী লাগবে?", timestamp: new Date() }]);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData && outputAudioContextRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

              const audioBuffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);

              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };

              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.inputTranscription) {
              setLiveTranscription(message.serverContent.inputTranscription.text);
            }
            if (message.serverContent?.outputTranscription) {
              setLiveTranscription(prev => prev + " " + message.serverContent!.outputTranscription!.text);
            }

            if (message.serverContent?.interrupted) {
              stopAllAudio();
            }
          },
          onerror: (e) => {
            setMicError("দুঃখিত, কানেকশনে ত্রুটি হয়েছে।");
            cleanupLiveResources();
          },
          onclose: () => {
            cleanupLiveResources();
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: `ROLE: BFC Assist. Friendly, fast, and helpful. Use engaging Bangla. Start with a warm greeting. KNOWLEDGE: ${menuData}. Keep responses under 8 words.`
        }
      });

      liveSessionRef.current = await sessionPromise;

    } catch (err) {
      setMicError("মাইক্রোফোন পারমিশন প্রয়োজন।");
      cleanupLiveResources();
    }
  };

  const toggleLiveMode = async () => {
    if (isLiveMode) {
      cleanupLiveResources();
      stopAllAudio();
    } else {
      await startLiveSession();
    }
  };

  const handleSend = async (text: string = input) => {
    const msg = text.trim();
    if (!msg || !isOnline) return;
    setMessages(p => [...p, { role: 'user', text: msg, timestamp: new Date() }]);
    setInput('');
    setIsTyping(true);

    try {
      const res = await bfcAssistChat(msg, messages.slice(-1).map(m => ({ role: m.role, parts: [{ text: m.text }] })));
      setMessages(p => [...p, { role: 'model', text: res, timestamp: new Date() }]);

      const base64Audio = await generateSpeech(res);
      if (base64Audio) {
        stopAllAudio();
        await initAudioContexts();
        const ctx = outputAudioContextRef.current!;
        const buffer = await decodeAudioData(decodeAudio(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        setIsSpeaking(true);
        source.onended = () => setIsSpeaking(false);
        source.start(0);
        currentSpeechSource.current = source;
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsTyping(false);
    }
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, isTyping, liveTranscription]);

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[5000]">
      {isOpen ? (
        <div className="bg-white/95 dark:bg-gray-900/95 backdrop-blur-2xl w-[95vw] sm:w-[400px] h-[70vh] sm:h-[600px] rounded-[40px] shadow-[0_25px_60px_-15px_rgba(220,38,38,0.15)] flex flex-col border border-white/20 dark:border-white/5 overflow-hidden animate-slide-up ring-1 ring-black/5">
          {/* Header */}
          <div className="bg-gradient-to-r from-red-600 to-red-700 p-6 sm:p-8 text-white relative overflow-hidden shrink-0">
            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-4">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-500 ${isLiveMode ? 'bg-white text-red-600 scale-110 shadow-lg' : 'bg-white/20 text-white'}`}>
                   <i className={`fas ${isLiveMode ? 'fa-microphone-lines animate-pulse' : isSpeaking ? 'fa-volume-high animate-bounce' : 'fa-bolt-lightning'} text-xl`}></i>
                </div>
                <div>
                  <h3 className="font-black text-xl tracking-tight leading-none uppercase italic">BFC Assist</h3>
                  <div className="flex items-center gap-2 mt-1.5">
                    <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span>
                    <p className="text-[10px] font-black uppercase tracking-widest text-red-100/80">Online Hub</p>
                  </div>
                </div>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={toggleLiveMode} 
                  className={`w-11 h-11 rounded-xl flex items-center justify-center transition-all ${isLiveMode ? 'bg-white text-red-600 shadow-xl scale-110' : 'bg-white/10 hover:bg-white/20'}`}
                  aria-label="Voice Assist"
                >
                  <i className="fas fa-microphone text-sm"></i>
                </button>
                <button 
                  onClick={() => { setIsOpen(false); if(isLiveMode) cleanupLiveResources(); }} 
                  className="w-11 h-11 bg-white/10 hover:bg-white/20 rounded-xl flex items-center justify-center transition-all"
                >
                  <i className="fas fa-times text-sm"></i>
                </button>
              </div>
            </div>
            {/* Visual Waveform placeholder */}
            {isSpeaking && (
              <div className="absolute bottom-0 left-0 w-full h-1 flex gap-0.5 px-1 items-end">
                {[...Array(20)].map((_, i) => (
                  <div key={i} className="flex-1 bg-white/40 rounded-t-full animate-waveform" style={{ animationDelay: `${i * 0.1}s`, height: `${Math.random() * 100}%` }}></div>
                ))}
              </div>
            )}
          </div>

          {/* Messages Area */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 sm:p-8 space-y-6 scrollbar-hide bg-gray-50/50 dark:bg-gray-950/20">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-6 py-4 rounded-[28px] text-[13px] font-bold shadow-sm animate-slide-up border ${
                  m.role === 'user' 
                  ? 'bg-red-600 text-white border-red-500 rounded-br-none' 
                  : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-100 border-gray-100 dark:border-white/5 rounded-bl-none'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isLiveMode && liveTranscription && (
              <div className="flex justify-start">
                <div className="px-6 py-4 rounded-[28px] rounded-bl-none text-[12px] font-black bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 border border-emerald-100 dark:border-emerald-900/30 italic animate-pulse">
                  "{liveTranscription}"
                </div>
              </div>
            )}
            {isTyping && (
              <div className="flex items-center gap-3 ml-2">
                <div className="flex gap-1.5">
                  <span className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce"></span>
                  <span className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-1.5 h-1.5 bg-red-600 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
                <span className="text-[9px] font-black text-red-600/50 uppercase tracking-widest italic">Hub processing...</span>
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-6 sm:p-8 bg-white dark:bg-gray-900 border-t dark:border-white/5">
            <div className={`flex items-center bg-gray-100 dark:bg-gray-800 rounded-[30px] p-2 pr-2 border transition-all duration-500 focus-within:shadow-lg focus-within:border-red-600/30 ${isLiveMode ? 'opacity-50 grayscale' : ''}`}>
              <div className="w-10 h-10 flex items-center justify-center text-gray-400 shrink-0">
                <i className="fas fa-keyboard-text text-sm"></i>
              </div>
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder={isLiveMode ? "Listening mode active..." : "আপনার প্রশ্ন লিখুন..."}
                disabled={isLiveMode}
                className="flex-1 bg-transparent border-none px-3 outline-none text-[13px] font-black dark:text-white placeholder:text-gray-400"
              />
              <button 
                onClick={() => handleSend()} 
                disabled={!input.trim() || isTyping || isLiveMode} 
                className="w-11 h-11 bg-red-600 text-white rounded-[22px] flex items-center justify-center shadow-lg active:scale-90 transition-all disabled:opacity-0 disabled:scale-75"
              >
                <i className="fas fa-paper-plane-top text-xs"></i>
              </button>
            </div>
            {micError && <p className="mt-3 text-[10px] font-black text-red-600 text-center uppercase tracking-widest">{micError}</p>}
          </div>
        </div>
      ) : (
        <button 
          onClick={async () => {
            setIsOpen(true);
            await initAudioContexts();
          }} 
          className="w-18 h-18 sm:w-20 sm:h-20 bg-gray-950 dark:bg-red-600 text-white rounded-[32px] shadow-[0_20px_50px_rgba(220,38,38,0.3)] flex flex-col items-center justify-center hover:scale-110 active:scale-95 transition-all group border-4 border-white dark:border-white/10 relative overflow-hidden"
          aria-label="BFC Assist Hub"
        >
           <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/5 to-white/10 group-hover:rotate-12 transition-transform"></div>
           <i className="fas fa-bolt-lightning text-xl sm:text-2xl mb-1 transition-transform group-hover:scale-125"></i>
           <span className="text-[8px] font-black uppercase tracking-[3px] leading-none opacity-80">Assist</span>
           {isSpeaking && (
             <span className="absolute -top-1 -right-1 flex h-4 w-4">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-4 w-4 bg-red-500"></span>
             </span>
           )}
        </button>
      )}
      <style>{`
        @keyframes waveform {
          0%, 100% { height: 10%; }
