              />
              <button 
                onClick={() => handleSend()} 
                disabled={!input.trim() || isTyping || isLiveMode} 
                className="w-12 h-12 bg-red-600 text-white rounded-[24px] flex items-center justify-center shadow-lg active:scale-90 hover:scale-105 transition-all disabled:opacity-0 disabled:scale-75"
              >
