          aria-label="Activate BFC Assist"
        >
           <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/5 to-white/20 group-hover:animate-pulse"></div>
           <i className="fas fa-bolt-lightning text-2xl sm:text-3xl mb-1.5 transition-transform group-hover:scale-125 drop-shadow-md"></i>
           <span className="text-[9px] font-black uppercase tracking-[4px] leading-none opacity-90 drop-shadow-sm">ASSIST</span>
           {(isSpeaking || isLiveMode) && (
             <span className="absolute top-4 right-4 flex h-3.5 w-3.5">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-3.5 w-3.5 bg-white"></span>
             </span>
           )}
        </button>
      )}
      <style>{`
        @keyframes waveform {
          0%, 100% { height: 15%; }
          50% { height: 95%; }
        }
        .animate-waveform {
          animation: waveform 0.5s ease-in-out infinite;
        }
        .py-4\.5 { padding-top: 1.125rem; padding-bottom: 1.125rem; }
      `}</style>
    </div>
  );
};

import { GoogleGenAI, Modality } from "@google/genai";
import { MOCK_MENU } from "../constants";

// Function to get a fresh instance to ensure we use the latest injected API key
export const getAiInstance = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const menuData = MOCK_MENU.map(i => `${i.nameBn}:৳${i.price}`).join(",");

export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  if (!navigator.onLine) return "নেটওয়ার্ক নেই। কানেকশন চেক করুন!";
  const ai = getAiInstance();

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history.slice(-1), 
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `ROLE: BFC Assist Hub. 
        KNOWLEDGE: BFC Menu: ${menuData}.
        TONE: Energetic, friendly, and efficient. 
        RULES:
        1. Use natural Bangla (e.g., "অবশ্যই", "হ্যালো", "দারুণ হবে").
        2. Keep answers strictly under 8 words.
        3. Only focus on BFC food items.
        4. Be direct and helpful.`,
        temperature: 0.8,
      },
    });

    return response.text || "সালাম! কী খেতে ইচ্ছে করছে আজ?";
  } catch (error: any) {
    return "দুঃখিত, কানেকশনে কিছুটা সমস্যা হচ্ছে।";
  }
};

export const generateSpeech = async (text: string) => {
  const ai = getAiInstance();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, 
          },
        },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (error) {
    return null;
  }
};

export function encodeAudio(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { bfcAssistChat, generateSpeech, decodeAudio, decodeAudioData, encodeAudio, getAiInstance } from '../services/geminiService';
import { ChatMessage } from '../types';
import { Modality, LiveServerMessage } from '@google/genai';
import { MOCK_MENU } from '../constants';

const menuData = MOCK_MENU.map(i => `${i.nameBn}:৳${i.price}`).join(",");

export const ChatBot: React.FC<{ isOnline?: boolean }> = ({ isOnline = true }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: "সালাম! বিএফসি হাবে আপনাকে স্বাগতম। আজ আপনার জন্য সেরা কী খাবারটি অর্ডার করব?", timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLiveMode, setIsLiveMode] = useState(false); 
  const [micError, setMicError] = useState<string | null>(null);
  const [liveTranscription, setLiveTranscription] = useState<string>('');

  const scrollRef = useRef<HTMLDivElement>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const liveSessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const currentSpeechSource = useRef<AudioBufferSourceNode | null>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);

  const stopAllAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    if (currentSpeechSource.current) {
      try { currentSpeechSource.current.stop(); } catch(e) {}
      currentSpeechSource.current = null;
    }
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
  };

  const cleanupLiveResources = () => {
    if (liveSessionRef.current) {
      try { liveSessionRef.current.close(); } catch(e) {}
      liveSessionRef.current = null;
    }
    if (processorRef.current) {
      processorRef.current.disconnect();
      processorRef.current = null;
    }
    if (micStreamRef.current) {
      micStreamRef.current.getTracks().forEach(track => track.stop());
      micStreamRef.current = null;
    }
    setIsLiveMode(false);
    setLiveTranscription('');
  };

  const initAudioContexts = async () => {
    try {
      if (!inputAudioContextRef.current) {
        inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      }
      if (!outputAudioContextRef.current) {
        outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      if (inputAudioContextRef.current.state === 'suspended') await inputAudioContextRef.current.resume();
      if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();
    } catch (e) {
      console.error("AudioContext error:", e);
    }
  };

  const startLiveSession = async () => {
    if (!isOnline) return;
    setMicError(null);
    stopAllAudio();
    await initAudioContexts();

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;

      const ai = getAiInstance();
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const processor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            processorRef.current = processor;

            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) {
                int16[i] = inputData[i] * 32768;
              }
              const pcmBlob = {
                data: encodeAudio(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(processor);
            processor.connect(inputAudioContextRef.current!.destination);
            setIsLiveMode(true);
            setMessages(p => [...p, { role: 'model', text: "বলুন, আমি শুনছি!", timestamp: new Date() }]);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData && outputAudioContextRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

              const audioBuffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);

              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };

              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.inputTranscription) {
              setLiveTranscription(message.serverContent.inputTranscription.text);
            }

            if (message.serverContent?.interrupted) {
              stopAllAudio();
            }
          },
          onerror: (e) => {
            setMicError("কানেকশনে সমস্যা হচ্ছে।");
            cleanupLiveResources();
          },
          onclose: () => {
            cleanupLiveResources();
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
          inputAudioTranscription: {},
          systemInstruction: `ROLE: BFC Assist. Friendly, fast, helpful. KNOWLEDGE: ${menuData}. Max 8 words.`
        }
      });

      liveSessionRef.current = await sessionPromise;

    } catch (err) {
      setMicError("মাইক্রোফোন চালু করুন।");
      cleanupLiveResources();
    }
  };

  const handleSend = async (text: string = input) => {
    const msg = text.trim();
    if (!msg || !isOnline) return;
    setMessages(p => [...p, { role: 'user', text: msg, timestamp: new Date() }]);
    setInput('');
    setIsTyping(true);

    try {
      const res = await bfcAssistChat(msg, messages.slice(-1).map(m => ({ role: m.role, parts: [{ text: m.text }] })));
      setMessages(p => [...p, { role: 'model', text: res, timestamp: new Date() }]);

      const base64Audio = await generateSpeech(res);
      if (base64Audio) {
        stopAllAudio();
        await initAudioContexts();
        const ctx = outputAudioContextRef.current!;
        const buffer = await decodeAudioData(decodeAudio(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        setIsSpeaking(true);
        source.onended = () => setIsSpeaking(false);
        source.start(0);
        currentSpeechSource.current = source;
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsTyping(false);
    }
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, isTyping, liveTranscription]);

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[5000]">
      {isOpen ? (
        <div className="bg-white/98 dark:bg-gray-900/98 backdrop-blur-3xl w-[92vw] sm:w-[420px] h-[75vh] sm:h-[650px] rounded-[52px] shadow-[0_40px_100px_-20px_rgba(0,0,0,0.25)] flex flex-col border border-white/40 dark:border-white/5 overflow-hidden animate-slide-up ring-1 ring-black/5">
          {/* Header */}
          <div className="bg-gradient-to-br from-red-600 to-red-800 p-8 sm:p-10 text-white relative overflow-hidden shrink-0">
            <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16 blur-3xl"></div>
            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-5">
                <div className={`w-16 h-16 rounded-[24px] flex items-center justify-center transition-all duration-700 ${isLiveMode ? 'bg-white text-red-600 scale-110 shadow-2xl' : 'bg-white/20 text-white shadow-inner'}`}>
                   <i className={`fas ${isLiveMode ? 'fa-microphone-lines animate-pulse' : isSpeaking ? 'fa-waveform-lines animate-bounce' : 'fa-bolt-lightning'} text-2xl`}></i>
                </div>
                <div>
                  <h3 className="font-black text-2xl tracking-tighter leading-none uppercase italic">BFC Assist</h3>
