                placeholder={isLiveMode ? "Hearing you..." : "কী খেতে চান?..."}
                disabled={isLiveMode}
                className="flex-1 bg-transparent border-none px-3 outline-none text-[14px] font-black dark:text-white"
              />
              <button onClick={() => handleSend()} disabled={!input.trim() || isTyping || isLiveMode} className="w-12 h-12 bg-red-600 text-white rounded-[24px] flex items-center justify-center shadow-lg active:scale-90 transition-all disabled:opacity-0">
                <i className="fas fa-paper-plane-top text-sm"></i>
