  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: "হ্যালো! আজ কী অর্ডার করবেন?", timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLiveMode, setIsLiveMode] = useState(false); 
  const [micError, setMicError] = useState<string | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const liveSessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const currentSpeechSource = useRef<AudioBufferSourceNode | null>(null);
  const micStreamRef = useRef<MediaStream | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);

  const stopAllAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    if (currentSpeechSource.current) {
      try { currentSpeechSource.current.stop(); } catch(e) {}
      currentSpeechSource.current = null;
    }
    nextStartTimeRef.current = 0;
    setIsSpeaking(false);
  };

  const cleanupLiveResources = () => {
    if (liveSessionRef.current) {
      try { liveSessionRef.current.close(); } catch(e) {}
      liveSessionRef.current = null;
    }
    if (processorRef.current) {
      processorRef.current.disconnect();
      processorRef.current = null;
    }
    if (micStreamRef.current) {
      micStreamRef.current.getTracks().forEach(track => track.stop());
      micStreamRef.current = null;
    }
    setIsLiveMode(false);
  };

  const initAudioContexts = async () => {
    try {
      if (!inputAudioContextRef.current) {
        inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      }
      if (!outputAudioContextRef.current) {
        outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      if (inputAudioContextRef.current.state === 'suspended') await inputAudioContextRef.current.resume();
      if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();
    } catch (e) {
      console.error("AudioContext error:", e);
    }
  };

  const startLiveSession = async () => {
    if (!isOnline) {
        setMicError("অফলাইনে ভয়েস মোড সম্ভব নয়।");
        return;
    }
    setMicError(null);
    stopAllAudio();
    await initAudioContexts();

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;

      const ai = getAiInstance();
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const processor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            processorRef.current = processor;

            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) {
                int16[i] = inputData[i] * 32768;
              }
              const pcmBlob = {
                data: encodeAudio(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(processor);
            processor.connect(inputAudioContextRef.current!.destination);
            setIsLiveMode(true);
            setMessages(p => [...p, { role: 'model', text: "আমি শুনছি, বলুন!", timestamp: new Date() }]);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData && outputAudioContextRef.current) {
              setIsSpeaking(true);
              const ctx = outputAudioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

              const audioBuffer = await decodeAudioData(decodeAudio(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);

              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              };

              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }
            if (message.serverContent?.interrupted) {
              stopAllAudio();
            }
          },
          onerror: (e) => {
            setMicError("কানেকশনে সমস্যা হচ্ছে।");
            cleanupLiveResources();
          },
          onclose: () => {
            cleanupLiveResources();
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
          systemInstruction: `ROLE: BFC Assist. Fast. Knowledge: ${menuData}. Max 5 words.`
        }
      });
      liveSessionRef.current = await sessionPromise;
    } catch (err) {
      setMicError("মাইক্রোফোন চালু করুন।");
      cleanupLiveResources();
    }
  };

  const handleSend = async (text: string = input) => {
    const msg = text.trim();
    if (!msg) return;
    setMessages(p => [...p, { role: 'user', text: msg, timestamp: new Date() }]);
    setInput('');
    setIsTyping(true);

    if (!isOnline) {
        setTimeout(() => {
            setMessages(p => [...p, { role: 'model', text: "দুঃখিত, অফলাইন।", timestamp: new Date() }]);
            setIsTyping(false);
        }, 300);
        return;
    }

    try {
      // Parallelize AI response and UI feedback
      const res = await bfcAssistChat(msg, messages.slice(-1).map(m => ({ role: m.role, parts: [{ text: m.text }] })));
      setMessages(p => [...p, { role: 'model', text: res, timestamp: new Date() }]);

      const base64Audio = await generateSpeech(res);
      if (base64Audio) {
        stopAllAudio();
        await initAudioContexts();
        const ctx = outputAudioContextRef.current!;
        const buffer = await decodeAudioData(decodeAudio(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        setIsSpeaking(true);
        source.onended = () => setIsSpeaking(false);
        source.start(0);
        currentSpeechSource.current = source;
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsTyping(false);
    }
  };

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, isTyping]);

  return (
    <div className="fixed bottom-6 right-6 lg:bottom-12 lg:right-12 z-[5000]">
      {isOpen ? (
        <div className="bg-white/98 dark:bg-gray-900/98 backdrop-blur-3xl w-[90vw] sm:w-[400px] h-[75vh] sm:h-[650px] rounded-[48px] shadow-[0_40px_100px_-20px_rgba(0,0,0,0.3)] flex flex-col border border-white/40 dark:border-white/5 overflow-hidden animate-slide-up ring-1 ring-black/5">
          {/* Header */}
          <div className="bg-gradient-to-br from-red-600 to-red-800 p-8 text-white relative overflow-hidden shrink-0">
            <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16 blur-3xl"></div>
            <div className="flex justify-between items-center relative z-10">
              <div className="flex items-center gap-4">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-700 ${isLiveMode ? 'bg-white text-red-600 scale-110 shadow-xl' : 'bg-white/20 text-white'}`}>
                   <i className={`fas ${isLiveMode ? 'fa-microphone-lines animate-pulse' : isSpeaking ? 'fa-waveform-lines animate-bounce' : 'fa-bolt-lightning'} text-xl`}></i>
                </div>
                <div>
                  <h3 className="font-black text-xl tracking-tight uppercase italic leading-none">BFC Assist</h3>
                  <p className="text-[9px] font-black uppercase tracking-[2px] opacity-70 mt-2">Lightning Fast AI</p>
                </div>
              </div>
              <div className="flex gap-2">
                <button onClick={async () => { if(isLiveMode) cleanupLiveResources(); else await startLiveSession(); }} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isLiveMode ? 'bg-white text-red-600' : 'bg-white/10 hover:bg-white/20'}`}>
                  <i className="fas fa-microphone text-xs"></i>
                </button>
                <button onClick={() => { setIsOpen(false); cleanupLiveResources(); }} className="w-10 h-10 bg-white/10 hover:bg-white/20 rounded-xl flex items-center justify-center transition-all">
                  <i className="fas fa-times text-xs"></i>
                </button>
              </div>
            </div>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 scrollbar-hide bg-[#fcfcfc]/50 dark:bg-gray-950/20">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-5 py-3.5 rounded-[28px] text-[13px] font-bold shadow-sm border animate-slide-up ${
                  m.role === 'user' 
                  ? 'bg-red-600 text-white border-red-500 rounded-br-none' 
                  : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-100 border-gray-100 dark:border-white/5 rounded-bl-none'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex items-center gap-2 ml-1">
                <div className="flex gap-1 p-2 px-3 bg-white dark:bg-gray-800 rounded-full border dark:border-white/5 shadow-sm">
                  <span className="w-1 h-1 bg-red-600 rounded-full animate-bounce"></span>
                  <span className="w-1 h-1 bg-red-600 rounded-full animate-bounce [animation-delay:0.2s]"></span>
                  <span className="w-1 h-1 bg-red-600 rounded-full animate-bounce [animation-delay:0.4s]"></span>
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="p-6 bg-white dark:bg-gray-900 border-t dark:border-white/5">
            <div className={`flex items-center bg-gray-50 dark:bg-gray-800/80 rounded-[30px] p-1.5 transition-all duration-300 ${isLiveMode ? 'opacity-30' : 'focus-within:bg-white focus-within:ring-2 focus-within:ring-red-600/10'}`}>
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder={isLiveMode ? " hearing you..." : " কী খেতে চান?..."}
                disabled={isLiveMode}
                className="flex-1 bg-transparent border-none px-4 outline-none text-[13px] font-bold dark:text-white"
              />
              <button onClick={() => handleSend()} disabled={!input.trim() || isTyping || isLiveMode} className="w-10 h-10 bg-red-600 text-white rounded-[20px] flex items-center justify-center shadow-lg active:scale-90 transition-all disabled:opacity-0">
                <i className="fas fa-paper-plane text-xs"></i>
              </button>
            </div>
            {micError && <p className="mt-3 text-[9px] font-black text-red-600 text-center uppercase tracking-widest">{micError}</p>}
          </div>
        </div>
      ) : (
        <button onClick={async () => { setIsOpen(true); await initAudioContexts(); }} className="w-20 h-20 bg-gray-950 dark:bg-red-600 text-white rounded-[35px] shadow-[0_30px_60px_rgba(220,38,38,0.3)] flex flex-col items-center justify-center hover:scale-105 active:scale-95 transition-all group border-4 border-white dark:border-white/10 relative overflow-hidden">
           <i className="fas fa-bolt-lightning text-2xl mb-1 group-hover:animate-pulse"></i>
           <span className="text-[8px] font-black uppercase tracking-[3px]">Assist</span>
           {isSpeaking && <span className="absolute top-3 right-3 flex h-2.5 w-2.5"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span><span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-white"></span></span>}
        </button>
      )}
      <style>{`
        @keyframes slideUp { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-slide-up { animation: slideUp 0.3s ease-out forwards; }
      `}</style>
    </div>
  );
};

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { UserRole, OrderStatus, Order, MenuItem, User, AuditLog } from './types';
import { Button } from './components/Button';
import { ChatBot } from './components/ChatBot';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer
} from 'recharts';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';

interface AdminPanelProps {
  userRole: UserRole;
  onLogout: () => void;
  menuItems: MenuItem[];
  setMenuItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
}

const ANALYTICS_DATA = [
  { name: 'Sat', sales: 4200 }, { name: 'Sun', sales: 3800 }, { name: 'Mon', sales: 5200 },
  { name: 'Tue', sales: 4800 }, { name: 'Wed', sales: 6200 }, { name: 'Thu', sales: 5800 },
  { name: 'Fri', sales: 8500 },
];

const MOCK_ADMIN_USERS: User[] = [
  { id: 'U-001', name: 'Rahim Ahmed', email: 'rahim@node.com', role: UserRole.CUSTOMER, phone: '01711111111', loyaltyPoints: 450, tier: 'GOLD', wishlist: [], referralCode: 'BFC-RAHIM' },
  { id: 'U-002', name: 'Karim Ullah', email: 'karim@hub.com', role: UserRole.MANAGER, phone: '01822222222', loyaltyPoints: 1200, tier: 'PLATINUM', wishlist: [], referralCode: 'BFC-KARIM' },
  { id: 'U-003', name: 'Sadia Islam', email: 'sadia@sector.com', role: UserRole.CUSTOMER, phone: '01933333333', loyaltyPoints: 85, tier: 'SILVER', wishlist: [], referralCode: 'BFC-SADIA' },
  { id: 'U-004', name: 'Tanvir Hossain', email: 'tanvir@admin.com', role: UserRole.ADMIN, phone: '01644444444', loyaltyPoints: 5000, tier: 'PLATINUM', wishlist: [], referralCode: 'BFC-BOSS' },
];

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  userRole, onLogout, menuItems, setMenuItems, orders, setOrders 
}) => {
  const allowedTabs = useMemo(() => {
    if (userRole === UserRole.ADMIN) return ['dashboard', 'orders', 'menu-stock', 'users', 'reports', 'audit'];
    if (userRole === UserRole.MANAGER) return ['dashboard', 'orders', 'menu-stock', 'users', 'reports'];
    if (userRole === UserRole.STAFF) return ['orders']; // Staff only sees active orders
    return ['orders'];
  }, [userRole]);

  const [activeTab, setActiveTab] = useState(allowedTabs[0]);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [adminToast, setAdminToast] = useState<{msg: string, type: string} | null>(null);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);

  const [userSearch, setUserSearch] = useState('');
  const [userRoleFilter, setUserRoleFilter] = useState<'ALL' | UserRole>('ALL');
  const [menuStockSearch, setMenuStockSearch] = useState('');
  const [reportType, setReportType] = useState<'sales' | 'inventory' | 'customers'>('sales');

  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([
    { id: 'LOG-001', userId: 'A-001', userName: 'Super Admin', action: 'SYSTEM_START', details: 'BFC Mainframe initialized in Gulshan Sector.', timestamp: new Date(Date.now() - 86400000).toISOString(), level: 'INFO' },
    { id: 'LOG-002', userId: 'A-001', userName: 'Super Admin', action: 'SECURITY_PATCH', details: 'Firewall protocols updated to v5.2.', timestamp: new Date(Date.now() - 43200000).toISOString(), level: 'WARNING' },
  ]);
  const [auditSearch, setAuditSearch] = useState('');
  const [auditLevelFilter, setAuditLevelFilter] = useState<'ALL' | 'INFO' | 'WARNING' | 'CRITICAL'>('ALL');

  const showToast = useCallback((msg: string, type: string) => {
    setAdminToast({ msg, type });
    setTimeout(() => setAdminToast(null), 4000);
  }, []);

  const addAuditLog = useCallback((action: string, details: string, level: AuditLog['level'] = 'INFO') => {
    const newLog: AuditLog = {
      id: `LOG-${Math.random().toString(36).slice(2, 7).toUpperCase()}`,
      userId: 'ADMIN-01',
      userName: userRole === UserRole.ADMIN ? 'Head Admin' : userRole === UserRole.MANAGER ? 'Node Manager' : 'Staff Member',
      action,
      details,
      timestamp: new Date().toISOString(),
      level
    };
    setAuditLogs(prev => [newLog, ...prev]);
  }, [userRole]);

  const handleUpdateStatus = (orderId: string, newStatus: OrderStatus) => {
    try {
      const oldStatus = orders.find(o => o.id === orderId)?.status;
      setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
      showToast(`Order #${orderId.slice(-4)} updated to ${newStatus}.`, "success");
      addAuditLog('ORDER_STATUS_UPDATE', `Order #${orderId} changed from ${oldStatus} to ${newStatus}.`, 'INFO');
    } catch (e) {
      showToast("Could not update order status.", "error");
    }
  };

  const handleUpdateStock = (itemId: string, increment: boolean) => {
    setMenuItems(prev => prev.map(item => {
      if (item.id === itemId) {
        const newStock = increment ? item.stock + 1 : item.stock - 1;
        if (newStock < 0) {
          showToast(`Invalid action: Stock for ${item.name} cannot be less than zero.`, "error");
          return item;
        }
        showToast(`Stock for ${item.name} updated to ${newStock}.`, "success");
        return { ...item, stock: newStock };
      }
      return item;
    }));
  };

  const filteredMenuItems = useMemo(() => {
    if (!menuItems) return [];
    const query = menuStockSearch.toLowerCase().trim();
    if (!query) return menuItems;
    return menuItems.filter(item => item.name?.toLowerCase().includes(query) || item.nameBn?.includes(query) || item.category?.toLowerCase().includes(query));
  }, [menuItems, menuStockSearch]);

  const customerBehaviorData = useMemo(() => {
    const customerMap: Record<string, { name: string, totalOrders: number, totalSpend: number, lastOrder: string }> = {};
    orders.forEach(o => {
      if (!customerMap[o.customerId]) {
        customerMap[o.customerId] = { name: o.customerName, totalOrders: 0, totalSpend: 0, lastOrder: o.createdAt };
      }
      customerMap[o.customerId].totalOrders += 1;
      customerMap[o.customerId].totalSpend += o.total;
      if (new Date(o.createdAt) > new Date(customerMap[o.customerId].lastOrder)) {
        customerMap[o.customerId].lastOrder = o.createdAt;
      }
    });
    return Object.values(customerMap).sort((a, b) => b.totalSpend - a.totalSpend);
  }, [orders]);

  const filteredUsers = useMemo(() => {
    return MOCK_ADMIN_USERS.filter(user => {
      const matchesSearch = user.name.toLowerCase().includes(userSearch.toLowerCase()) || 
                            user.email.toLowerCase().includes(userSearch.toLowerCase());
      const matchesRole = userRoleFilter === 'ALL' || user.role === userRoleFilter;
      return matchesSearch && matchesRole;
    });
  }, [userSearch, userRoleFilter]);

  const filteredAuditLogs = useMemo(() => {
    return auditLogs.filter(log => {
      const matchesSearch = log.action.toLowerCase().includes(auditSearch.toLowerCase()) || log.userName.toLowerCase().includes(auditSearch.toLowerCase());
      const matchesLevel = auditLevelFilter === 'ALL' || log.level === auditLevelFilter;
      return matchesSearch && matchesLevel;
    });
  }, [auditLogs, auditSearch, auditLevelFilter]);

  const reportMetrics = useMemo(() => {
    if (reportType === 'sales') {
      const totalRevenue = orders.reduce((a, b) => a + b.total, 0);
      return [
        { label: 'Total Node Revenue', value: `৳${totalRevenue.toLocaleString()}`, icon: 'fa-vault' },
        { label: 'Avg Mission Value', value: `৳${orders.length ? (totalRevenue / orders.length).toFixed(0) : 0}`, icon: 'fa-scale-balanced' },
        { label: 'Conversion Rate', value: '12.4%', icon: 'fa-arrow-trend-up' }
      ];
    } else if (reportType === 'inventory') {
      const totalValuation = menuItems.reduce((a, b) => a + (b.price * b.stock), 0);
      return [
        { label: 'Stock Valuation', value: `৳${totalValuation.toLocaleString()}`, icon: 'fa-sack-dollar' },
        { label: 'Critical Nodes', value: menuItems.filter(m => m.stock < 10).length, icon: 'fa-triangle-exclamation' },
        { label: 'Storage Capacity', value: '85%', icon: 'fa-warehouse' }
      ];
    } else {
      return [
        { label: 'Registered Spenders', value: customerBehaviorData.length, icon: 'fa-users-gear' },
        { label: 'Lifetime Value (Avg)', value: `৳${customerBehaviorData.length ? (orders.reduce((a, b) => a + b.total, 0) / customerBehaviorData.length).toFixed(0) : 0}`, icon: 'fa-gem' },
        { label: 'Retention Logic', value: 'High', icon: 'fa-link' }
      ];
    }
  }, [reportType, orders, menuItems, customerBehaviorData]);

  const handleExportExcel = () => {
    let data: any[] = [];
    if (reportType === 'sales') data = orders.map(o => ({ 'Order ID': o.id, 'Customer': o.customerName, 'Total': o.total }));
    else if (reportType === 'inventory') data = menuItems.map(m => ({ 'Name': m.name, 'Stock': m.stock }));
    else data = customerBehaviorData.map(c => ({ 'Name': c.name, 'Spend': c.totalSpend }));

    const worksheet = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Report");
    XLSX.writeFile(workbook, `BFC_${reportType}.xlsx`);
    showToast("Excel exported.", "success");
  };

  const handleExportPDF = () => {
    const doc = new jsPDF();
    doc.text(`BFC Report: ${reportType.toUpperCase()}`, 14, 20);
    doc.save(`BFC_${reportType}.pdf`);
    showToast("PDF exported.", "success");
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] dark:bg-gray-950 overflow-hidden font-sans">
      {adminToast && (
        <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-[7000] px-8 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-slide-up border ${
          adminToast.type === 'error' ? 'bg-red-600 text-white border-red-400' : 'bg-gray-950 text-white border-white/10'
        }`}>
           <span className="text-[10px] font-black uppercase tracking-[3px]">{adminToast.msg}</span>
        </div>
      )}

      {showLogoutConfirm && (
        <div className="fixed inset-0 z-[8000] flex items-center justify-center p-6 bg-gray-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-gray-900 w-full max-w-sm rounded-[40px] p-10 shadow-2xl text-center">
             <h3 className="text-2xl font-black uppercase italic tracking-tighter mb-4">Exit Terminal?</h3>
             <div className="flex flex-col gap-3">
                <button onClick={onLogout} className="w-full py-5 bg-red-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-[4px]">Terminate Session</button>
                <button onClick={() => setShowLogoutConfirm(false)} className="w-full py-5 bg-gray-100 dark:bg-gray-800 text-gray-500 rounded-2xl font-black text-[10px] uppercase tracking-[4px]">Stay</button>
             </div>
          </div>
