export const bfcAssistChat = async (message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) => {
  if (!navigator.onLine) return "অফলাইন। চেক করুন!";
  const ai = getAiInstance();

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history.slice(-1), 
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `ROLE: BFC Specialized Concierge.
        KNOWLEDGE: ${menuData}. 
        STRICT RULES:
        1. ONLY discuss BFC food, menu, ordering process, or payment issues.
        2. If a question is NOT about BFC, say: "দুঃখিত, আমি শুধু বিএফসি সম্পর্কিত তথ্য দিতে পারি।"
        3. Provide food suggestions based on ingredients.
        4. Help with payment methods (bKash, Nagad, Card) or order errors.
        5. Language: Natural Bangla. 
        6. Max 8 words per response for speed.
        7. Tone: Helpful and hospitable.`,
        temperature: 0.5,
        thinkingConfig: { thinkingBudget: 0 }
      },
    });

    return response.text || "কীভাবে সাহায্য করতে পারি?";
  } catch (error: any) {
    return "দুঃখিত, বিএফসি হাবে সমস্যা হচ্ছে।";
  }
};

export const generateSpeech = async (text: string) => {
  if (!navigator.onLine) return null;
  const ai = getAiInstance();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, 
          },
        },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (error) {
    return null;
  }
};

export function encodeAudio(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decodeAudio(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

