                <button onClick={async () => { if(isLiveMode) cleanupLiveResources(); else await startLiveSession(); }} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isLiveMode ? 'bg-white text-red-600' : 'bg-white/10 hover:bg-white/20'}`}>
