        <div className="bg-white/95 dark:bg-gray-950/95 backdrop-blur-2xl w-[90vw] sm:w-[320px] h-[50vh] sm:h-[450px] rounded-[35px] shadow-[0_40px_100px_-20px_rgba(0,0,0,0.5)] flex flex-col border border-white/20 dark:border-white/10 overflow-hidden animate-slide-up">
          <div className="bg-red-600 p-4 text-white flex justify-between items-center">
            <div className="flex items-center gap-2">
