            <button onClick={() => setIsOpen(false)} className="w-8 h-8 bg-white/10 rounded-lg flex items-center justify-center hover:bg-white/20 transition-all"><i className="fas fa-times text-[10px]"></i></button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-3 scrollbar-hide bg-gray-50/20">
            {messages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-3 py-1.5 rounded-[18px] text-[10px] font-black ${m.role === 'user' ? 'bg-red-600 text-white' : 'bg-white dark:bg-gray-900 text-gray-800 dark:text-gray-100 border border-gray-100 dark:border-white/5 shadow-sm'}`}>
                  {m.text}
                </div>
