          <div className="p-3 bg-white dark:bg-gray-950 border-t dark:border-white/5 flex gap-2">
            <button onClick={toggleMic} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${micStreamRef.current ? 'bg-red-600 text-white animate-pulse' : 'bg-gray-100 dark:bg-gray-900 text-gray-400'}`}>
              <i className="fas fa-microphone text-xs"></i>
            </button>
            <div className="flex-1 flex items-center bg-gray-100 dark:bg-gray-900 rounded-xl p-0.5">
              <input 
                type="text" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()}
                placeholder="কী চাই?..."
                className="flex-1 bg-transparent border-none px-3 outline-none text-[10px] font-black dark:text-white"
              />
              <button onClick={handleSend} className="w-8 h-8 bg-red-600 text-white rounded-lg flex items-center justify-center shadow-lg active:scale-90 transition-all">
                <i className="fas fa-paper-plane text-[8px]"></i>
              </button>
            </div>
